contracts/people/people.rules.json.text:
{
  "schema": "suborned.people.rules/1",
  "author": "Motive (brief 010 A, 2026-10-15)",
  "gdd": "the-suborned-agent-gdd-v0.21.0-2026-10-15.md",
  "rule": "The rules a generated person must obey. Anything not in this file is rejected (GDD §01 house rules: unknown = reject). Every entry cites its GDD § in `src`; an entry the GDD does not state is marked `proposed: true` with a `reason`, for Sky to accept or strike. Tags in src: [B] built, [S] starting value to tune by playtest.",
  "person": {
    "is": ["routine", "need", "temperament", "memory", "secret"],
    "needsPerPerson": 1,
    "memoryAtStart": "empty",
    "src": "§04 person = routine + need + temperament + memory; §09 people checked for one clear need; §09 history, not backstory",
    "reason": "memory starts empty: a person's history is what the systems record from the first run on (§09), never written backstory. Ties are the only relationships a person starts with.",
    "readBy": {
      "fields": {
        "name": "§08 debrief reports each contact with cause; §13 T7 names ≥ 2 contacts a day later; names.pinned casts Inez and Vale",
        "temperament": "§04 which approach a person responds to, refuses or reports; Hero/Menace changes the price",
        "need": "§04 Help and Pressure require the need known (Listen); needs.list.metBy",
        "ties": "§04 introductions (ties.kinds.introduces); §08 keeper tips needs (knowledge.needsKnown); needs kin and protection require a tie",
        "scales": "§04 Talker test and lie rule; §04 Accomplice hides ops and drives, Fighter joins armed (§06)",
        "memory": "§04 Ask leaves a remembered refusal (+$10,000, +1 T); Talker gives only facts in memory; §08 debrief",
        "routine": "§04 Pay requires routine known (Watch); §05 who stands within 13 m of an act to witness it",
