        "reason": "a simulated person who neither lives nor works in the district (shopper, reveller) still needs a role the checker knows."
      },
      "docker": {
        "employer": "hiring-hall", "allow": ["idealist", "mercenary", "fearful", "loyal"],
        "src": "life.json routines.docker; §08 Act II takes a workplace e.g. docks",
        "proposed": true,
        "reason": "port workers hired by shift at the hiring hall are not its staff, so they need their own role."
      },
      "clerk": {
        "employer": "records-office", "allow": ["idealist", "mercenary", "fearful", "loyal"],
        "src": "§08 economy: clerk skims cash; life.json civicEmployers records-office",
        "proposed": true,
        "reason": "the Records Office's staff. All four: §08's skimming clerk is a Mercenary, and the Office must hold some who can be helped."
      },
      "guard": {
        "employer": "records-office", "allow": ["loyal", "mercenary"],
        "src": "§05 security: guard on door routine (café stop pre-shift); §07 cast; brief 010 A (Sky): Loyal to the Office or Mercenary, never Idealist",
        "proposed": true,
        "reason": "Sky's question in the brief, answered yes. Not Fearful either: a guard who folds to a threat would make §07 route A's Help-and-call the costly way round."
      },
      "official-driver": {
        "employer": "records-office", "allow": ["idealist", "mercenary", "fearful", "loyal"],
        "src": "§07 official driver (needs cash), turned before 5:40",
        "proposed": true,
        "reason": "all four: the Handover picks a driver it can turn (brief 010 D), the city does not shape its drivers for one mission."
      },
      "councillor": {
        "employer": "records-office", "allow": ["loyal", "mercenary", "fearful"],
        "src": "§07 Councillor Vale signed the clearance order",
        "proposed": true,
        "reason": "the one who signs clearance orders. Never Idealist, for the same reason creditors are not: the order is the harm."
      },
      "watcher": {
        "employer": "civic", "allow": ["loyal", "mercenary", "fearful"],
        "src": "§01 world: cameras are closed-circuit, watched by people; §05 watchers",
        "proposed": true,
        "reason": "the people behind the cameras. Never Idealist: a watcher's log is the city's record against the cell (§05)."
      },
      "patrol-officer": {
        "employer": "civic", "allow": ["loyal", "mercenary"],
        "src": "§05 security: patrol sweep, response unit; §06 health guard/officer 3",
        "proposed": true,
        "reason": "as guard: Loyal or Mercenary."
      },
      "investigator": {
        "employer": "civic", "allow": ["loyal", "mercenary"],
        "src": "§05 investigators",
        "proposed": true,
        "reason": "as guard: Loyal or Mercenary. An investigator who could be helped across would undo §05's pressure."
      }
    },
    "mix": {
      "rule": "the culture baseline is the cast row: an area × occupation's temperament weights. No temperament may hold more than rowMaxShare of a row's weight, and a unit with whenStaffAtLeast staff or more carries at least unitMinDistinct temperaments.",
      "rowMaxShare": 0.6,
      "unitMinDistinct": 2,
      "whenStaffAtLeast": 3,
      "src": "§09 risk: sameness (Watch Dogs: Legion); §04 Hero and Menace turn different halves of the city",
      "proposed": true,
      "reason": "DF draws each person from a culture baseline, then lets them deviate. Our baseline is the cast row, and this cap keeps every person from being the baseline. At any workplace of three or more there are two kinds of person, so there are two ways in at two prices, which serves the pillar orchestrate the city. 0.6 and 3 are [S]."
    },
    "employers": {
      "records-office": { "plot": "records-office", "block": "civic-office", "kind": "civic", "src": "life.json generator.civicEmployers; civic-block.json civic-office" },
      "cafe": {
        "block": "cafe", "kind": "trade", "trade": "diner",
        "src": "civic-block.json cafe (Corner café); plan standards.frontage.placement.corner: corners on two streets take an anchor trade (w ≥ 18), else a diner; the records mix lists diner",
        "proposed": true,
        "reason": "the café is none of the 39 trades by name. A 22 m corner unit takes a diner (the plan's corner rule; diner is an anchor in the records mix and opens 6–24, covering the 17:00 Handover). Datum or Vantage may name it otherwise."
      },
      "civic": {
        "kind": "civic", "src": "§05 security, watchers, investigators",
        "proposed": true,
        "reason": "the city's own security, which the plan does not site. Its people are loyal to the civic order (institution kind civic)."
      }
    }
  },
  "names": {
    "scope": "district",
    "pool": "one pool per district, carried by the cast tables (brief 010 B); every simulated person's given and family name come from it",
    "form": { "parts": ["given", "family"], "pattern": "^\\p{Lu}[\\p{L}'-]{1,15}$" },
    "noEraDate": "no digits, years, dates, generational suffixes (Jr, Sr, II, III) or titles in a name; the pattern forbids them",
    "avoid": ["Betty", "Peggy", "Dottie", "Dolores", "Mabel", "Gertrude", "Hank", "Buddy", "Butch", "Biff", "Skip", "Sonny", "Junior", "Chester", "Elmer"],
    "minGiven": 60,
    "minFamily": 80,
    "origins": ["anglo", "celtic", "french", "iberian", "italian", "germanic", "nordic", "slavic", "greek", "levantine", "arabic", "persian", "turkish", "west-african", "east-african", "south-asian", "east-asian", "southeast-asian", "polynesian", "caribbean", "latin-american"],
    "minOrigins": 6,
    "maxOriginShare": 0.25,
    "uniqueFullName": true,
    "background": "unnamed",
    "pinned": [
      { "part": "given", "name": "Inez", "position": "server", "employer": "cafe", "src": "§07 cast: Inez (café waitress, in debt)" },
      { "part": "family", "name": "Vale", "role": "councillor", "employer": "records-office", "src": "§07 cast: Councillor Vale" }
    ],
    "src": "§15 people: people prompts carry no era date; mixed cast (ages, builds, ethnicities); brief 010 A: a pool per district, no era date, a mixed cast",
    "proposed": true,
    "reason": "the GDD gives the principle, not the numbers. Each pool entry is tagged with one origin from the closed list; ≥ 6 origins and no origin over a quarter of a pool make a mixed cast checkable. 60 × 80 = 4,800 full names keeps every simulated person in a district unique. The avoid list holds names that date a person to 1950s Americana (the §15 failure in names). Pinned: the GDD names Inez and Vale, so the person the Handover pins by role takes that name part; no other name is ever authored."
  }
}

