// Redline's engine review (briefs/011/review/redline-engine.html), each finding as a test that would have caught it.
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;
using Suborned.Sim;
using Xunit;

public class RedlineTests
{
    static readonly Engine.Inputs I = Repo.Inputs;
    static void Rejects(string rulebook, string people, string site, string what)
    {
        var e = Record.Exception(() => Engine.FromTexts(rulebook, people, site, I.People));
        Assert.True(e is FormatException, $"{what}: loaded, should be rejected at load ({e?.GetType().Name})");
    }
    static string Sub(string text, string from, string to) { Assert.Contains(from, text); return text.Replace(from, to); }

    [Fact]
    public void E1_unknown_is_rejected_at_load_everywhere_the_engine_reads()
    {
        string rb = I.Rulebook, pr = I.PeopleRules, st = I.Site;
        Rejects(Sub(rb, "\"schema\": \"suborned.rulebook/1\",", "\"schema\": \"suborned.rulebook/1\", \"stray\": 1,"), pr, st, "an unknown top-level key");
        Rejects(Sub(rb, "\"watch-s\": { \"v\": 20,", "\"watch-s\": { \"vv\": 1, \"v\": 52,"), pr, st, "an unknown key in a value");
        Rejects(Sub(rb, "\"speed\": \"v:op-speed-cm-s\"", "\"sped\": \"v:op-speed-cm-s\", \"speed\": \"v:op-speed-cm-s\""), pr, st, "an unknown key in the cell section");
        Rejects(Sub(rb, "\"ask\": { \"fit\": \"refused\"", "\"ask\": { \"fit\": \"refusedd\""), pr, st, "a fit typo");
        Rejects(Sub(rb, "\"when\": [{ \"k\": \"reports-approach\" }", "\"when\": [{ \"k\": \"mood\" }"), pr, st, "an unknown condition kind in the reports");
        Rejects(Sub(rb, "\"add\": [{ \"scale\": \"bravery\", \"by\": \"v:bravery-per-job\" }]", "\"add\": [{ \"scale\": \"bravry\", \"by\": \"v:bravery-per-job\" }]"), pr, st, "a ladder on an unknown scale");
        Rejects(Sub(rb, "{ \"k\": \"temperament\", \"in\": [\"mercenary\"] }], \"usd\": \"v:mercenary-hero-usd\"", "{ \"k\": \"temperament\", \"in\": [\"mercenaryy\"] }], \"usd\": \"v:mercenary-hero-usd\""), pr, st, "a temperament typo in a condition");
        Rejects(Sub(rb, "\"debt-cleared\": { \"standing\": \"hero\"", "\"debt-cleared\": { \"standing\": \"heroo\""), pr, st, "a traceable standing typo");
        Rejects(Sub(rb, "\"knownBy\": [\"scout.listen\"]", "\"knownBy\": [\"scout.lisen\"]"), pr, st, "knownBy naming no event");
        Rejects(rb, Sub(pr, "\"schema\": \"suborned.people.rules/1\",", "\"schema\": \"suborned.people.rules/1\", \"stray\": 1,"), st, "an unknown key at the people rules' root");
        Rejects(rb, Sub(pr, "\"respondsTo\": [\"help\"], \"refuses\": [\"pay\"]", "\"respondsToo\": [], \"respondsTo\": [\"help\"], \"refuses\": [\"pay\"]"), st, "an unknown key in a temperament");
        Rejects(rb, pr, Sub(st, "\"schema\": \"suborned.sim.site/1\",", "\"schema\": \"suborned.sim.site/1\",\n \"stray\": 1,"), "an unknown key at the site's root");
        Rejects(rb, pr, Regex.Replace(st, "\"purse\": 100000,", "\"purse\": 100000.5,"), "a float purse");
        Rejects(Sub(rb, "\"watch-s\": { \"v\": 20,", "\"watch-s\": { \"v\": 0,"), pr, st, "a 0 s action (E3)");
        Rejects(Sub(rb, "\"pointBlank\": \"v:point-blank-m\",", "\"pointBlank\": \"v:point-blank-m\", \"spread\": \"v:point-blank-m\","), pr, st, "an unknown key in the weapons section (Sky 2026-10-15 fights)");
        Rejects(Sub(rb, "\"pistol-eff-m\": { \"v\": 15,", "\"pistol-eff-m\": { \"v\": 26,"), pr, st, "a pistol's effective band beyond its max");
        Rejects(Sub(rb, "\"health-guard\": { \"v\": 3,", "\"health-guard\": { \"v\": 0,"), pr, st, "a health of 0");
        Rejects(Sub(rb, "\"draw-ticks\": { \"v\": 10,", "\"draw-ticks\": { \"v\": 0,"), pr, st, "a 0-tick draw (unit ticks ≥ 1)");
        Rejects(rb, pr, Sub(st, "\"arms\": 3,", "\"arms\": -1,"), "negative Arms");
        Rejects(Sub(rb, "\"turn\": \"aborted\",", "\"turn\": \"forgotten\","), pr, st, "a cancel line the engine doesn't do (Sky 2026-10-15 playtest)");
        Rejects(Sub(rb, "\"watch\": \"lost\",", "\"watch\": \"kept\","), pr, st, "a fixed cancel line changed");
        Rejects(Sub(rb, "{ \"id\": \"not-yet\", \"when\": [],", "{ \"id\": \"not-yet\", \"when\": [{ \"k\": \"cash-covers\" }],"), pr, st, "cash-covers in an outcome (it recursed until the stack overflowed)");
    }

    [Fact]
    public void E1_step_never_throws()
    {
        var g = Engine.New(I);
        for (int i = 0; i < 5000 && !g.Over; i++) g.Step();
        Assert.True(g.FailCode != "engine-error", g.FailText);
    }

    [Fact]
    public void E2_a_refusal_gives_back_exactly_what_was_taken()
    {
        var s = new Start(); s.Known["guard"] = new List<string> { "routine" };
        s.Temperament["guard"] = "loyal"; // the premise: Menace refuses a Loyal person's Pay, whoever the cast's guard is (r016's is a Mercenary)
        var g = Engine.New(I, s);
        var run = new Run(g);
        run.To(run.Send("fixer", "d:Office approach"));
        var q = g.Preview("pay", "guard");
        long before = g.Cash;
        Assert.True(run.Do("fixer", "turn", "guard", "pay"));
        long taken = before - g.Cash;
        Assert.Equal(q.Usd, taken);
        g.Standing = I.Rules.MenaceAt; // standing moves while the order runs: Menace refuses a Loyal's Pay
        run.Done("fixer");
        Assert.Contains(g.Log, l => l.Code == "turn.pay.refused");
        Assert.Equal(before, g.Cash);
    }

    [Fact]
    public void E5_cones_hold_at_district_scale()
    {
        Assert.False(G.InCone(new Pt(0, 0), new Pt(65536, 0), 3000, 1500, 300, new Pt(65536, 0)));
        Assert.False(G.InCone(new Pt(0, 0), new Pt(46341, 0), 3000, 1500, 300, new Pt(92682, 0)));
        Assert.True(G.InCone(new Pt(0, 0), new Pt(65536, 0), 3000, 1500, 300, new Pt(2900, 100)));
    }

    [Fact]
    public void E4_crlf_and_bom_replay_to_the_same_hashes()
    {
        string Win(string s) => "\uFEFF" + s.Replace("\n", "\r\n");
        var w = Engine.FromTexts(Win(I.Rulebook), Win(I.PeopleRules), Win(I.Site), Win(I.People), I.Provisional.Length > 0 ? Win(I.Provisional) : null, I.Takedown.Length > 0 ? Win(I.Takedown) : null, I.Rounds.Length > 0 ? Win(I.Rounds) : null);
        Assert.Equal(I.Hash, w.Hash);
        var a = Scenarios.Run(I, Scenarios.Find("S10")!).G; var b = Scenarios.Run(w, Scenarios.Find("S10")!).G;
        Assert.Equal(a.Checkpoints, b.Checkpoints);
    }

    [Fact]
    public void E4_the_checkpoint_hash_covers_what_the_debrief_reads()
    {
        var a = Engine.New(I); var b = Engine.New(I);
        b.GuardReachedCafe = true;
        Assert.NotEqual(Hash.State(a), Hash.State(b));
    }

    [Fact]
    public void E11_json_edges()
    {
        Assert.Equal(1, JNode.Parse("\uFEFF{\"a\": 1}")["a"].Int());
        Assert.Throws<FormatException>(() => JNode.Parse("{\"a\": 01}"));
        Assert.Throws<FormatException>(() => JNode.Parse("{\"a\": \"x\ty\"}"));
        Assert.Throws<FormatException>(() => JNode.Parse("{\"a\": \"\\u12\"}"));
        Assert.Throws<FormatException>(() => JNode.Parse("{\"a\": -}"));
    }

    [Theory]
    [InlineData("sv-SE")] [InlineData("ar-SA")] [InlineData("fa-IR")] [InlineData("tr-TR")]
    public void E7_every_report_is_the_same_in_every_culture(string culture)
    {
        string All()
        {
            var parts = new List<string>();
            foreach (var s in Scenarios.All) { var r = Scenarios.Run(I, s); parts.Add(Report.Json(s.Id, r.G, r.Checks, true)); }
            return string.Join("\n", parts);
        }
        var keep = Thread.CurrentThread.CurrentCulture;
        try
        {
            Thread.CurrentThread.CurrentCulture = CultureInfo.InvariantCulture; var inv = All();
            Thread.CurrentThread.CurrentCulture = new CultureInfo(culture); var other = All();
            if (inv != other)
            {
                var a = inv.Split('\n'); var b = other.Split('\n'); int i = 0; while (i < a.Length && i < b.Length && a[i] == b[i]) i++;
                int j = 0; while (j < a[i].Length && j < b[i].Length && a[i][j] == b[i][j]) j++;
                Assert.Fail($"{culture} differs: …{a[i].Substring(Math.Max(0, j - 60), Math.Min(120, a[i].Length - Math.Max(0, j - 60)))}");
            }
        }
        finally { Thread.CurrentThread.CurrentCulture = keep; }
    }
}

sim/Suborned.Sim.Tests/Rounds.cs.text:
// Brief 022 (Pulse; Sky 2026-10-18): the living café. The engine's round is tools/routines/rounds.ts poseAt: it reproduces Pulse's reference
// vectors (sim/data/handover.rounds.json `vectors`) to 30 cm and by phase; and with the round switched off (Start.Rounds false, the migration
// gate) every scenario and recorded route plays exactly as it does with no rounds file at all.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Suborned.Sim;
using Xunit;

public class RoundsTests
{
    static readonly Engine.Inputs I = Repo.Inputs;
    static readonly Engine.Inputs NoRounds = Engine.FromTexts(I.Rulebook, I.PeopleRules, I.Site, I.People, I.Provisional.Length > 0 ? I.Provisional : null, I.Takedown.Length > 0 ? I.Takedown : null);

    public static IEnumerable<object[]> Kinds => new[] { "free", "held", "called", "ended" }.Select(k => new object[] { k });

    [Fact]
    public void TheMissionDataTurnsTheRoundOn()
    {
        Assert.NotNull(I.SiteData.Rounds);
        var g = Engine.New(I); Assert.True(g.RoundsOn);
        Assert.True(I.SiteData.Rounds!.Servers.ContainsKey(g.Inez.Id));
        Assert.False(new Game(I.Rules, I.SiteData, new Start { Rounds = false }, "", I.Crowd).RoundsOn);
        Assert.False(Engine.New(NoRounds).RoundsOn);
    }

    [Theory, MemberData(nameof(Kinds))]
    public void TheEngineMatchesPulsesReferencePoses(string kind)
    {
        var R = I.SiteData.Rounds!; var g = Engine.New(I);
        foreach (var (id, sv) in R.Servers)
        {
            var rows = R.Vectors[id][kind]; Assert.NotEmpty(rows);
            int o0 = sv.Origin * Game.Hz; var e0 = sv.Exc[0]; int at0 = o0 + e0.Start * Game.Hz;
            var holds = Array.Empty<(int, int, Pt)>(); (int, int, int, Pt)? call = null; int end = -1;
            if (kind == "held") holds = new[] { (at0 + 50, at0 + 50 + 420, new Pt(100, 0)) };
            if (kind == "called")
            {
                int gw = (int)Math.Round(R.GuardStopWalkCm / (double)R.PaceCmPerS * Game.Hz, MidpointRounding.AwayFromZero), c0 = at0 + (int)Math.Floor(e0.Out * Game.Hz * 0.5);
                call = (c0, c0 + gw, c0 + gw + R.StayS * Game.Hz, R.GuardStopAt);
            }
            if (kind == "ended") { var mid = sv.Exc[Math.Min(1, sv.Exc.Count - 1)]; end = o0 + mid.Start * Game.Hz + mid.Out * Game.Hz + 20; }
            foreach (var (tick, pos, _, phase) in rows)
            {
                var q = g.RoundReference(id, tick, holds, call, end);
                Assert.True(q.Phase == phase, $"{kind} @{tick}: phase {q.Phase}, want {phase}");
                Assert.True(G.Within(q.Pos, pos, 30), $"{kind} @{tick}: at {q.Pos}, want {pos} (30 cm)");
            }
        }
    }

    [Fact]
    public void WithTheRoundOffEveryScenarioPlaysAsWithNoRoundsFile()
    {
        foreach (var sc in Scenarios.All)
        {
            if (Scenarios.PlaysTheRound.Contains(sc.Id)) continue; // the round's own cases (N130 to N133) read it
            var off = Start.Parse(JNode.Parse(sc.Start.Canonical())); off.Rounds = false;
            var a = new Run(new Game(NoRounds.Rules, NoRounds.SiteData, Start.Parse(JNode.Parse(sc.Start.Canonical())), "gate", NoRounds.Crowd)); sc.Body(a); a.G.Finish();
            var b = new Run(new Game(I.Rules, I.SiteData, off, "gate", I.Crowd)); sc.Body(b); b.G.Finish();
            Assert.True(Same(a.G, b.G), $"{sc.Id}: rounds off differs from no rounds file");
        }
    }

    [Fact]
    public void WithTheRoundOffEveryRecordedRoutePlaysAsWithNoRoundsFile()
    {
        var root = Engine.FindRoot(AppContext.BaseDirectory); int n = 0;
        foreach (var f in Directory.GetFiles(System.IO.Path.Combine(root, "contracts/missions/handover/routes"), "*.json").OrderBy(x => x, StringComparer.Ordinal))
        {
            var txt = File.ReadAllText(f); if (!txt.Contains("suborned.sim.script/1")) continue;
            var sc = Script.Parse(txt); n++;
            var off = Start.Parse(JNode.Parse(sc.Start.Canonical())); off.Rounds = false;
            var a = Engine.Play(NoRounds, sc.Start, sc.Orders, sc.Until); var b = Engine.Play(I, off, sc.Orders, sc.Until);
            Assert.True(Same(a, b), $"{System.IO.Path.GetFileName(f)}: rounds off differs from no rounds file");
        }
        Assert.True(n > 10);
    }

    /// <summary>The same behaviour: every log line's tick and code, every order's answer, the outcome and the numbers.</summary>
    static bool Same(Game a, Game b) =>
        a.Log.Count == b.Log.Count && a.Log.Zip(b.Log).All(x => x.First.Tick == x.Second.Tick && x.First.Code == x.Second.Code)
        && a.Orders.Count == b.Orders.Count && a.Orders.Zip(b.Orders).All(x => x.First.ok == x.Second.ok && x.First.code == x.Second.code)
        && (a.Result, a.FailCode, a.Tick, a.Trail, a.Alert, a.Cash, a.Standing) == (b.Result, b.FailCode, b.Tick, b.Trail, b.Alert, b.Cash, b.Standing);

    [Fact]
    public void HeadingSkipsZeroLengthSegments()
    {
        var p = new Suborned.Sim.Path(new[] { new Pt(0, 0), new Pt(0, 0), new Pt(100, 0), new Pt(100, 0) });
        Assert.Equal(new Pt(100, 0), p.Heading(0));
        Assert.Equal(new Pt(100, 0), p.Heading(p.Length));
        Assert.Equal(new Pt(0, 0), new Suborned.Sim.Path(new[] { new Pt(5, 5), new Pt(5, 5) }).Heading(0));
    }
}

sim/Suborned.Sim.Tests/Sight.cs.text:
// The cell's knowledge of watchers (Sky 2026-10-16: view cones are the Scout's skill; rulebook sight). The fan is the engine's own
// sight test drawn as a polygon: every sampled point the engine sees is inside it and every point it doesn't is outside, but for a band
// of a few centimetres along the fan's edge (the rays' spacing and integer rounding). The reads change nothing, and knowledge never
// changes an outcome, only what the cards show.
using System;
using System.Collections.Generic;
using System.Linq;
using Suborned.Sim;
using Xunit;

public class SightTests
{
    const int Tol = 8; // cm: the band along the fan's edge where a sample may fall either way (the hair-wide rays either side of a corner: 1/512 rad, 6 cm at 30 m)

    static double SegDist(Pt p, Pt a, Pt b)
    {
        double dx = b.X - a.X, dy = b.Y - a.Y, l2 = dx * dx + dy * dy;
        double t = l2 == 0 ? 0 : Math.Clamp(((p.X - a.X) * dx + (p.Y - a.Y) * dy) / l2, 0, 1);
        double x = a.X + t * dx - p.X, y = a.Y + t * dy - p.Y; return Math.Sqrt(x * x + y * y);
    }
    static double EdgeDist(Pt p, Pt[] poly)
    {
        double d = double.MaxValue;
        for (int i = 0, j = poly.Length - 1; i < poly.Length; j = i++) d = Math.Min(d, SegDist(p, poly[j], poly[i]));
        return d;
    }

    /// <summary>Samples every `step` cm around the watcher; returns the samples where the fan and the engine disagree beyond Tol.</summary>
    static List<string> Disagreements(Game g, string w, bool crowd, int step = 23)
    {
        var f = g.ConeFan(w, crowd); Assert.NotNull(f);
        var bad = new List<string>(); int r = f!.Reach + 200, inside = 0;
        for (int x = -r; x <= r; x += step)
            for (int y = -r; y <= r; y += step)
            {
                var p = new Pt(f.At.X + x, f.At.Y + y);
                var polys = new List<Pt[]> { f.Points }; polys.AddRange(f.More); polys.RemoveAll(q => q.Length < 3); // a mast: a polygon a head
                bool truth = g.InSight(w, p, crowd), drawn = polys.Exists(q => G.InPoly(p, q));
                if (truth) inside++;
                if (truth != drawn && (polys.Count == 0 || polys.Min(q => EdgeDist(p, q)) > Tol)) bad.Add($"{w} at tick {g.Tick}: {p} engine {(truth ? "sees" : "doesn't")}, fan {(drawn ? "in" : "out")}");
            }
        Assert.True(inside > 0, $"{w}: the engine sees nothing around it");
        return bad;
    }

    static void AllAgree(Game g, bool crowd = false)
    {
        var bad = new List<string>(); int n = 0;
        foreach (var w in g.WatcherIds()) { if (g.ConeFan(w, crowd) == null) continue; n++; bad.AddRange(Disagreements(g, w, crowd)); }
        Assert.True(n > 0);
        Assert.True(bad.Count == 0, $"{bad.Count} samples disagree: " + string.Join("; ", bad.Take(8)));
    }

    [Fact]
    public void TheFanIsTheEnginesSightAtTheStart()
    {
        var g = Engine.New(Repo.Inputs); AllAgree(g);
        Assert.Equal(new[] { "camera:entrance", "camera:pickup", "camera:mast-314", "guard", "patrol" }, g.WatcherIds().Where(w => g.ConeFan(w) != null)); // brief 013: the world's Records Square mast
    }

    [Theory]
    [InlineData(150)] [InlineData(330)] [InlineData(500)] [InlineData(740)] [InlineData(910)]
    public void TheSweepingPatrolsFanFollowsItAlongItsSweep(int tick)
    {
        var g = Engine.New(Repo.Inputs); g.RunTo(tick);
        Assert.True(Disagreements(g, "patrol", false).Count == 0, string.Join("; ", Disagreements(g, "patrol", false).Take(5)));
    }

    [Fact]
    public void TheFanWithPeopleOnTheStreetIsCutByThem()
    {
        var g = Engine.New(Repo.Inputs); g.RunTo(300);
        AllAgree(g, crowd: true);
        // somewhere a person stands in a watcher's sight, and the crowd fan is not the walls' fan
        Assert.Contains(g.WatcherIds(), w => g.ConeFan(w, true) is Fan f && f.Stop.Contains("crowd"));
    }

    [Fact]
    public void AWalkingGuardsFanHasItsNearCircleAndALoopedCameraIsNotLive()
    {
        var s = new Start(); s.Turned.Add("waitress");
        var g = Engine.New(Repo.Inputs, s); var r = new Run(g);
        r.Wait(Game.T(5));
        Assert.True(g.Issue(new Order { Tick = g.Tick, Op = "fixer", Do = "move", To = "d:Courtyard" }).ok);
        r.Until(() => g.CanCall("waitress"), Game.T(120));
        Assert.True(g.Issue(new Order { Tick = g.Tick, Op = "fixer", Do = "call", Target = "waitress" }).ok);
        g.Advance(Game.T(10));
        Assert.Equal("walking to café", g.GuardPose()!.Value.phase);
        var f = g.ConeFan("guard")!;
        Assert.Contains("near", f.Stop);
        Assert.Empty(Disagreements(g, "guard", false));
        // the Tech loops the entrance camera: its fan stays, not live, and it notices nobody
        Assert.True(g.Issue(new Order { Tick = g.Tick, Op = "tech", Do = "move", To = "cabinet" }).ok);
        r.Until(() => r.Op("tech").Walk == null, Game.T(120));
        Assert.True(g.Issue(new Order { Tick = g.Tick, Op = "tech", Do = "loop", Target = "entrance" }).ok);
        r.Done("tech");
        Assert.True(g.LoopOn);
        var cam = g.ConeFan("camera:entrance")!;
        Assert.False(cam.Live); Assert.True(cam.Points.Length >= 3);
        Assert.DoesNotContain(g.Detection(), n => n.Watcher == "camera:entrance");
    }

    [Fact]
    public void TheReadsChangeNothing()
    {
        // play S10 (route A) from its orders twice: once bare, once calling every read every tick; the checkpoints are the same
        var played = Scenarios.Run(Repo.Inputs, Scenarios.Find("N11")!).G;
        var orders = played.Orders.Select(o => o.order).ToList();
        var bare = Engine.Play(Repo.Inputs, played.Start, orders, played.Tick);
        var g = Engine.New(Repo.Inputs, played.Start);
        var list = orders.Select((o, i) => (o, i)).OrderBy(x => x.o.Tick).ThenBy(x => x.i).ToList();
        int k = 0;
        while (g.Tick < played.Tick && !g.Over)
        {
            while (k < list.Count && list[k].o.Tick == g.Tick) { g.Issue(list[k].o); k++; }
            var before = Hash.State(g);
            foreach (var w in g.WatcherIds()) { g.ConeFan(w); g.ConeFan(w, true); g.Known(w); g.Routine(w, 600); }
            g.KnownFans(); g.Detection(); g.SeenAt(g.OpOf(OpId.Enforcer).Pos);
            if (g.Tick % 10 == 0) { g.QuoteMove("scout", g.S.Stand("d:Office approach")); g.Preview("help", "waitress"); g.ActivityOf(OpId.Scout); }
            Assert.Equal(before, Hash.State(g));
            if (g.Over) break;
            g.Step();
        }
        while (k < list.Count && list[k].o.Tick == g.Tick) { g.Issue(list[k].o); k++; }
        g.RunTo(played.Tick); g.Finish();
        Assert.Equal(bare.Checkpoints, g.Checkpoints);
        Assert.Equal(played.Result, g.Result);
    }

    [Fact]
    public void KnowledgeNeverChangesAnOutcomeOnlyTheCard()
    {
        // route A's orders, played with no watcher known and with every watcher's sight told: the same run, but for the knowledge itself
        var played = Scenarios.Run(Repo.Inputs, Scenarios.Find("N11")!).G;
        var orders = played.Orders.Select(o => o.order).ToList();
        var told = new Start();
        foreach (var kv in played.Start.Known) told.Known[kv.Key] = new List<string>(kv.Value);
        foreach (var kv in played.Start.Temperament) told.Temperament[kv.Key] = kv.Value;
        told.Turned.AddRange(played.Start.Turned); told.Cash = played.Start.Cash; told.Arms = played.Start.Arms; told.FinalFight = played.Start.FinalFight; told.Crowd = played.Start.Crowd;
        told.Known["camera:entrance"] = new List<string> { "sight" }; told.Known["camera:pickup"] = new List<string> { "sight" }; told.Known["patrol"] = new List<string> { "sight", "routine" };
        var a = Engine.Play(Repo.Inputs, played.Start, orders, played.Tick);
        var b = Engine.Play(Repo.Inputs, told, orders, played.Tick);
        Assert.Equal((a.Result, a.FailCode, a.Trail, a.Alert, a.Cash, a.Standing), (b.Result, b.FailCode, b.Trail, b.Alert, b.Cash, b.Standing));
        Assert.Equal(a.Log.Select(l => (l.Tick, l.Code)), b.Log.Select(l => (l.Tick, l.Code)));
        Assert.Equal(a.Orders.Select(o => (o.ok, o.code)), b.Orders.Select(o => (o.ok, o.code)));
        Assert.Equal(a.Ops.Select(o => o.Pos), b.Ops.Select(o => o.Pos));
        Assert.True(b.Known("camera:entrance")!.Sight && b.Known("camera:entrance")!.How == "told" && !a.Known("camera:entrance")!.Sight);
        Assert.NotEqual(a.Checkpoints.Last().hash, b.Checkpoints.Last().hash); // the knowledge is state: the hash walks it
    }

    [Fact]
    public void TheStartStateRejectsAnUnknownWatcherOrFact()
    {
        var s = new Start(); s.Known["camera:roof"] = new List<string> { "sight" };
        Assert.Throws<FormatException>(() => Engine.New(Repo.Inputs, s));
        var t = new Start(); t.Known["security-1"] = new List<string> { "sight" };
        Assert.Throws<FormatException>(() => Engine.New(Repo.Inputs, t)); // known on arrival, never told
        var u = new Start(); u.Known["camera:entrance"] = new List<string> { "routine" };
        Assert.Throws<FormatException>(() => Engine.New(Repo.Inputs, u)); // a camera's routine comes with its sight
    }

    [Fact]
    public void TheRulebookSightSectionIsReadStrictly()
    {
        var r = Repo.Inputs.Rules;
        Assert.Equal((20, 1800, 40), (r.SightWatchS, r.SightReachCm, r.SightRoutineS));
        Assert.Equal(("watch", "watched"), r.SightKinds["patrol"]);
        Assert.Equal(("arrival", "none"), r.SightKinds["security"]);
        var bad = Repo.Inputs.Rulebook.Replace("\"routine\": \"watched\"", "\"routine\": \"guessed\"");
        Assert.Throws<FormatException>(() => Engine.FromTexts(bad, Repo.Inputs.PeopleRules, Repo.Inputs.Site));
    }
}

sim/Suborned.Sim.Tests/Tests.cs.text:
// dotnet test sim/Suborned.Sim.Tests — the done-check of brief 011 A: the 28 scenarios pass headless; the same orders give
// byte-identical checksums twice; a replay from the order log matches; the rules agree with contracts/rules/rulebook.test.ts.
using System;
using System.Collections.Generic;
using System.Linq;
using Suborned.Sim;
using Xunit;

public static class Repo
{
    public static readonly Engine.Inputs Inputs = Engine.Load(Engine.FindRoot(AppContext.BaseDirectory));
}

public class ScenarioTests
{
    public static IEnumerable<object[]> Ids => Scenarios.All.Select(s => new object[] { s.Id });

    [Theory, MemberData(nameof(Ids))]
    public void Passes(string id)
    {
        var run = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!);
        var failed = run.Checks.Where(c => !c.ok).Select(c => c.what).ToList();
        Assert.True(failed.Count == 0, $"{id}: " + string.Join("; ", failed));
        Assert.NotEmpty(run.Checks);
    }

    [Theory, MemberData(nameof(Ids))]
    public void SameOrdersSameChecksumsTwice(string id)
    {
        var a = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!).G;
        var b = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!).G;
        Assert.Equal(a.Checkpoints, b.Checkpoints);
        Assert.Equal(a.StartHash, b.StartHash);
    }

    [Theory, MemberData(nameof(Ids))]
    public void ReplaysFromStartStateAndOrders(string id)
    {
        var played = Scenarios.Run(Repo.Inputs, Scenarios.Find(id)!).G;
        var replay = Engine.Replay(Repo.Inputs, played);
        Assert.Equal(played.Checkpoints, replay.Checkpoints);
        Assert.Equal(played.Result, replay.Result);
    }

    [Fact]
    public void TwentyEightPortedPlusTheEnginesNCases()
    {
        Assert.Equal(28, Scenarios.All.Count(s => s.Id.StartsWith("S")));
        Assert.Equal(Enumerable.Range(1, 28).Select(i => $"S{i:00}"), Scenarios.All.Where(s => s.Id.StartsWith("S")).Select(s => s.Id));
    }

    [Fact]
    public void OrdersAfterAnOrderEndsTheMissionReplayToo()
    {
        // Keel 2026-10-16 (found while re-casting r016): an order that ends the mission (withdraw, an entry seen) leaves the tick where it
        // is, so anything given after it at that tick is refused (mission-over) and is still the player's, in the record. The replay plays it.
        var g = Engine.New(Repo.Inputs); var r = new Run(g);
        r.Wait(Game.T(30));
        Assert.True(g.Issue(new Order { Tick = g.Tick, Do = "withdraw" }).ok);
        Assert.True(g.Over);
        Assert.Equal("mission-over", g.Issue(new Order { Tick = g.Tick, Op = "scout", Do = "move", To = "d:Courtyard" }).code);
        g.Finish();
        var replay = Engine.Replay(Repo.Inputs, g);
        Assert.Equal(g.Orders.Count, replay.Orders.Count);
        Assert.Equal(g.Checkpoints, replay.Checkpoints);
        Assert.Equal(g.Result, replay.Result);
    }

    [Fact]
    public void AScriptRoundTripsThroughTheOrderFormat()
    {
        var played = Scenarios.Run(Repo.Inputs, Scenarios.Find("S10")!).G;
        var script = Script.Parse(Script.Write(played, Repo.Inputs.Hash));
        var replay = Engine.Play(Repo.Inputs, script.Start, script.Orders, script.Until);
        Assert.Equal(Outcome.Success, replay.Result);
        Assert.Equal(played.Checkpoints, replay.Checkpoints);
        Assert.Equal("", script.Verify(replay, Repo.Inputs.Hash));
        Assert.NotEqual("", script.Verify(replay, Repo.Inputs.Hash ^ 1)); // other inputs: the record says so
    }
}

public class RulesTests
{
    static Game New(Start? s = null) => Engine.New(Repo.Inputs, s);
    static Start Knowing(string temperament)
    {
        var s = new Start(); s.Temperament["waitress"] = temperament; s.Known["waitress"] = new List<string> { "routine", "need", "temperament" }; return s;
    }

    [Fact]
    public void InezReferencePricesFromTheRulebook()
    {
        var g = New(Knowing("idealist"));
        var help = g.Preview("help", "waitress");
        Assert.Equal((40000L, 50L, 1L, 1L, "turned"), (help.Usd, help.S, help.Trail, help.Orders, help.Outcome));
        Assert.Equal("refused", g.Preview("pay", "waitress").Outcome); // Sky 2026-10-15: Inez is an Idealist, Pay is the lesson
        Assert.Equal(4L, g.Preview("pressure", "waitress").Trail);    // one step worse
        Assert.Equal("refused", g.Preview("ask", "waitress").Outcome);
    }

    [Theory]
    [InlineData("mercenary", "pay", 70000, 1, "turned")]
    [InlineData("mercenary", "help", 40000, 2, "not-yet")]
    [InlineData("fearful", "pay", 90000, 1, "turned")]
    [InlineData("loyal", "help", 40000, 2, "not-yet")]
    [InlineData("loyal", "pay", 90000, 1, "turned")]
    public void Q4GridMatchesTheTypeScriptEvaluator(string t, string approach, long usd, long orders, string outcome)
    {
        var q = New(Knowing(t)).Preview(approach, "waitress");
        Assert.Equal((usd, orders, outcome), (q.Usd, q.Orders, q.Outcome));
    }

    [Fact]
    public void ThePreviewShowsQuestionMarksOnlyWhereTemperamentsDiffer()
    {
        var s = new Start(); s.Known["waitress"] = new List<string> { "routine" };
        var g = New(s);
        var pay = g.Preview("pay", "waitress");
        Assert.Equal(("?", 70000L, 90000L), (pay.Outcome, pay.Lines[0].Usd, pay.WorstUsd));
        Assert.Equal("refused", g.Preview("ask", "waitress").Outcome);
        Assert.Equal("?", pay.Reports);
    }

    [Fact]
    public void TalkerTestReadsPeopleRules()
    {
        var r = Repo.Inputs.Rules;
        Assert.False(r.IsTalker(new[] { 1, 0, 0, 1 })); // helped Inez
        Assert.True(r.IsTalker(new[] { 1, 1, 1, 0 }));  // pressured Inez
        Assert.True(r.IsTalker(new[] { 0, 0, 1, 0 }));  // a Fearful start
        Assert.False(r.IsTalker(new[] { 2, 1, 1, 0 })); // equal is not a Talker
    }

    [Fact]
    public void UnknownIsRejected()
    {
        var i = Repo.Inputs;
        var bad = i.Rulebook.Replace("{ \"k\": \"tier\", \"is\": \"simulated\" }", "{ \"k\": \"mood\", \"is\": \"simulated\" }");
        Assert.NotEqual(i.Rulebook, bad);
        Assert.Throws<FormatException>(() => new Rules(bad, i.PeopleRules));
        var g = New();
        Assert.False(g.Issue(new Order { Tick = 0, Op = "scout", Do = "dance" }).ok);
        Assert.Throws<FormatException>(() => Order.Parse(JNode.Parse("{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"speed\":9}")));
        Assert.Throws<FormatException>(() => JNode.Parse("{\"v\": 1.5}")["v"].Long()); // integer state only
    }

    [Fact]
    public void TheFightOrdersKeepTheOrderFormat()
    {
        // new keys are written only when set: an older order reads and writes as before
        var walk = Order.Parse(JNode.Parse("{\"tick\":3,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Courtyard\"}"));
        Assert.Equal("{\"tick\":3,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Courtyard\"}", walk.ToString().Replace(" ", ""));
        var forced = Order.Parse(JNode.Parse("{\"tick\":3,\"op\":\"enforcer\",\"do\":\"fire\",\"target\":\"waitress\",\"force\":true}"));
        Assert.True(forced.Force); Assert.Contains("\"force\"", forced.ToString());
        Assert.Equal("free", Order.Parse(JNode.Parse("{\"tick\":3,\"op\":\"scout\",\"do\":\"stance\",\"stance\":\"free\"}")).Stance);
        Assert.Throws<FormatException>(() => Order.Parse(JNode.Parse("{\"tick\":3,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Courtyard\",\"force\":true}")));
        Assert.Throws<FormatException>(() => Order.Parse(JNode.Parse("{\"tick\":3,\"op\":\"scout\",\"do\":\"fire\",\"target\":\"guard\",\"stance\":\"free\"}")));
        var g = New();
        Assert.False(g.Issue(new Order { Tick = 0, Op = "scout", Do = "stance", Stance = "wild" }).ok); // unknown = reject
        Assert.False(g.Issue(new Order { Tick = 0, Op = "cell", Do = "panic" }).ok);                     // no fight on
        Assert.False(g.Issue(new Order { Tick = 0, Op = "enforcer", Do = "fire", Target = "plaza" }).ok);
    }

    [Fact]
    public void EveryRefusalHasAStableCodeAndTheHashReadsTheCodeNotTheWords()
    {
        var bad = new List<string>(); int refused = 0;
        foreach (var sc in Scenarios.All)
        {
            var g = Scenarios.Run(Repo.Inputs, sc).G;
            foreach (var (o, ok, code, why) in g.Orders)
            {
                if (ok) continue; refused++;
                if (!Answer.Codes.Contains(code) || code == "engine-error") bad.Add($"{sc.Id}: {o} → {code} ({why})");
            }
        }
        Assert.True(refused > 10, $"the scenarios refuse orders ({refused})");
        Assert.Empty(bad);
        var a = New(); var b = New();
        var x = a.Issue(new Order { Tick = 0, Op = "scout", Do = "watch", Target = "waitress" });
        Assert.Equal(("too-far", false), (x.code, x.ok)); Assert.True(x.m > 0); // the number the line needs, as a field
        var (ok2, code2, why2) = b.Issue(new Order { Tick = 0, Op = "scout", Do = "watch", Target = "waitress" });
        Assert.Equal(x.code, code2);
        Assert.Equal(Hash.State(a), Hash.State(b));
        Assert.Equal(Answer.Codes.Length, Answer.Codes.Distinct().Count());
    }

    [Fact]
    public void TheSummonsIsRefusedForEachReasonAtNoCost()
    {
        Start Inez() { var s = new Start(); s.Turned.Add("waitress"); return s; }
        (bool ok, string code, int trail) Call(Game g) { var a = g.Issue(new Order { Tick = g.Tick, Op = "fixer", Do = "call", Target = "waitress" }); return (a.ok, a.code, g.Trail); }
        var alert = New(Inez()); alert.Alert = 2;                                     // a search: he won't leave (summon.alertMax 1)
        Assert.Equal((false, "summon-alert", 0), Call(alert));
        var saw = New(Inez()); saw.GuardP.Memory.Add(new Mem { Act = "saw-gunfire", By = "enforcer", Place = "d:Office entrance" });
        Assert.Equal((false, "summon-saw-violence", 0), Call(saw));                 // he saw what you did
        var down = New(Inez()); down.GuardDown = true;
        Assert.Equal((false, "summon-busy", 0), Call(down));
        var i = Repo.Inputs; // a city where he lives too far: summon.walkMax 30 s against his 46 s walk
        var far = Engine.FromTexts(i.Rulebook.Replace("\"summon-walk-max-s\": { \"v\": 90,", "\"summon-walk-max-s\": { \"v\": 30,"), i.PeopleRules, i.Site, i.People);
        var g = Engine.New(far, Inez()); var a = g.Issue(new Order { Tick = 0, Op = "fixer", Do = "call", Target = "waitress" });
        Assert.Equal("summon-too-far", a.code); Assert.True(a.tick > 300, $"the walk rides as a field ({a.tick} ticks)");
        var ok = New(Inez()); Assert.Equal((true, "", 1), Call(ok));                  // the call: +1 T (cell.call.trail)
    }

    [Fact]
    public void TheCallQueryAndIssueAgree()
    {
        // every scenario's call orders, and a call on every role at every 10 s of a few runs: the query before the click is Issue's answer
        int checkedCalls = 0;
        foreach (var id in new[] { "S10", "N39", "N39c", "N39d", "S21", "N39b", "S07" })
        {
            var sc = Scenarios.Find(id)!;
            var played = Scenarios.Run(Repo.Inputs, sc).G;
            var g = Engine.New(Repo.Inputs, sc.Start); int k = 0;
            while (g.Tick <= played.Tick && !g.Over)
            {
                if (g.Tick % 600 == 0)
                    foreach (var role in new[] { "waitress", "driver", "guard", "councillor" })
                    {
                        var copy = g.Tick == 0 ? Engine.New(Repo.Inputs, sc.Start) : Engine.Play(Repo.Inputs, sc.Start, played.Orders.Take(k).Select(x => x.order).ToList(), g.Tick);
                        var q = copy.CallQuery(role); ulong before = Hash.State(copy);
                        Assert.Equal(before, Hash.State(copy)); // read-only
                        var a = copy.Issue(new Order { Tick = copy.Tick, Op = "fixer", Do = "call", Target = role });
                        Assert.True(q.ok == a.ok && q.code == a.code && q.tick == a.tick, $"{id} {Report.Clock(g.Tick)} call {role}: query {q.code} vs issue {a.code}");
                        checkedCalls++;
                    }
                while (k < played.Orders.Count && played.Orders[k].order.Tick == g.Tick) { var o = played.Orders[k++].order; if (o.Do == "call") { var q = g.CallQuery(o.Target); var a = g.Issue(o); Assert.Equal((q.ok, q.code), (a.ok, a.code)); checkedCalls++; } else g.Issue(o); }
                g.Step();
            }
        }
        Assert.True(checkedCalls > 40, $"calls checked ({checkedCalls})");
    }

    [Fact]
    public void ArmsDecideWhoCarriesASidearm()
    {
        var none = new Start { Arms = 0 };
        var g = New(none);
        Assert.Equal("carbine", g.Enforcer.Gun.W!.Id);                        // the cell's, uses no Arms
        Assert.Null(g.OpOf(OpId.Fixer).Gun.W);
        Assert.False(g.Issue(new Order { Tick = 0, Op = "fixer", Do = "draw" }).ok);
        var all = New();                                                        // the Handover issues three (site arms)
        Assert.All(all.Ops, o => Assert.NotNull(o.Gun.W));
        Assert.Equal(new[] { 4, 4, 4, 6 }, all.Ops.Select(o => o.Gun.Health).ToArray());
    }

    [Fact]
    public void CoverMatchesPulsesVectors()
    {
        // briefs/011/pulse-fight-ai.md §8.1: a point at (0, 0) facing (0, 1000), arc 50° (cos 642)
        var c = new CoverPoint { Id = "cv-001", At = new Pt(0, 0), Faces = new Pt(0, 1000), Cos = 642, Q = 700 };
        Assert.True(CoverRules.Protects(c, new Pt(0, 1500), 0, 500));
        Assert.True(CoverRules.Protects(c, new Pt(1000, 1500), 0, 500));
        Assert.False(CoverRules.Protects(c, new Pt(1800, 1500), 0, 500));
        Assert.False(CoverRules.Protects(c, new Pt(0, -1500), 0, 500));
        Assert.False(CoverRules.Protects(c, new Pt(0, 499), 0, 500));
        Assert.True(CoverRules.Protects(c, new Pt(0, 500), 0, 500));
        var car = new CoverPoint { Id = "cv-002", At = new Pt(0, 0), Faces = new Pt(0, 1000), Cos = 642, Q = 700, From = 100, To = 200 };
        Assert.Equal(new[] { false, true, true, false }, new[] { 99, 100, 199, 200 }.Select(t => CoverRules.Protects(car, new Pt(0, 1500), t, 500)).ToArray());
        // §8.2: the modifier
        int M(CoverPoint p, Pt body, Pt shooter) => CoverRules.Modifier(new[] { p }, body, shooter, 0, 70, 500, 600, 350, 500, 750);
        var low = new CoverPoint { Id = "cv-003", At = new Pt(0, 0), Faces = new Pt(0, 1000), Cos = 642, Q = 400 };
        Assert.Equal(500, M(c, new Pt(0, 0), new Pt(0, 2000)));
        Assert.Equal(750, M(low, new Pt(0, 0), new Pt(0, 2000)));
        Assert.Equal(1000, M(c, new Pt(0, 0), new Pt(0, -2000)));
        Assert.Equal(1000, M(c, new Pt(120, 0), new Pt(0, 2000)));
        Assert.Equal(1000, M(c, new Pt(0, 0), new Pt(0, 300)));
    }

    [Fact]
    public void AccuracyMatchesTheTypeScriptReference()
    {
        var r = New().R;
        // contracts/rules/rulebook.test.ts "bands and modifiers"
        Assert.Equal(750, r.Accuracy(r.Pistol, 1200, false, false, false, false));
        Assert.Equal(750, r.Accuracy(r.Pistol, 400, false, false, false, true));
        Assert.Equal(375, r.Accuracy(r.Pistol, 1200, true, false, false, false));
        Assert.Equal(187, r.Accuracy(r.Pistol, 1200, true, true, false, false));
        Assert.Equal(400, r.Accuracy(r.Pistol, 2000, false, false, false, false));
        Assert.Equal(0, r.Accuracy(r.Pistol, 2600, false, false, false, false));
        Assert.Equal(750, r.Accuracy(r.Carbine, 1800, false, false, false, false));
    }
}

public class GeometryTests
{
    [Fact]
    public void IntegerSquareRootIsExact()
    {
        foreach (long n in new long[] { 0, 1, 2, 3, 4, 15, 16, 17, 99, 100, 101, 1L << 40, (1L << 40) - 1, 4_000_000_000_000_000L })
        {
            long r = G.Isqrt(n);
            Assert.True(r * r <= n && (r + 1) * (r + 1) > n, $"isqrt({n}) = {r}");
        }
    }

    [Fact]
    public void A_slab_above_eye_height_does_not_block_and_a_wall_does()
    {
        // N13 (§05 levels): sightlines run in 3D. A deck slab from 9.43 m does not block an eye-level line; a wall does.
        var square = new[] { new Pt(-100, -100), new Pt(100, -100), new Pt(100, 100), new Pt(-100, 100) };
        var slab = new Occluder("deck", 943, 40, square);
        var wall = new Occluder("wall", 0, 300, square);
        var a = new Pt(-500, 0); var b = new Pt(500, 0);
        Assert.False(slab.Blocks(a, b, 160));
        Assert.True(wall.Blocks(a, b, 160));
        Assert.True(slab.Blocks(a, b, 950)); // seen from the deck, the slab blocks the line along it
    }

    [Fact]
    public void ConesAreDirectional()
    {
        var o = new Pt(0, 0); var f = new Pt(100, 0);
        Assert.True(G.InCone(o, f, 1800, 900, 300, new Pt(1000, 200)));
        Assert.False(G.InCone(o, f, 1800, 900, 300, new Pt(-1000, 0)));
        Assert.True(G.InCone(o, f, 1800, 900, 300, new Pt(-200, 0)));  // within `near`
        Assert.False(G.InCone(o, f, 1800, 900, 300, new Pt(1900, 0))); // beyond reach
    }
}

public class StreamTests
{
    [Fact]
    public void TheNeedStreamIsTheTypeScriptOne()
    {
        // contracts/rules/rulebook.test.ts golden values: stream('p-cafe-11/need/1')() and replaceNeed for missions 1–3
        Assert.Equal(1572639180u, new Streams.Mulberry("p-cafe-11/need/1").Next());
        var items = new List<(string, int)> { ("cash", 2000), ("housing", 1000), ("papers", 1000), ("care", 500), ("advancement", 1000), ("secret", 500) };
        Assert.Equal(new[] { "housing", "care", "housing" }, new[] { 1, 2, 3 }.Select(m => Streams.Draw($"p-cafe-11/need/{m}", items)).ToArray());
    }
}

