// Cover as data (brief 011 fight AI, Pulse: briefs/011/pulse-fight-ai.md §5; contracts/world/civic-block.cover.json, copied into the site
// by tools/sim/site.ts with its sha256). The three functions are tools/cover/select.ts in integers, and give its conformance vectors.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed class CoverPoint
    {
        public string Id = ""; public Pt At, Faces; public int Cos, Q, H; public string Kind = "", Of = ""; public int From = 0, To = int.MaxValue; // present [From, To) mission seconds
        public bool Present(int missionS) => missionS >= From && missionS < To;
    }

    public static class CoverRules
    {
        /// <summary>The point shields a body standing at it from a shooter at s: at least minRange away (point blank is never turned), inside the
        /// cone about `faces` (dot(s − at, faces) ≥ cos × |s − at|, cm·per mille), and present at the mission second.</summary>
        public static bool Protects(CoverPoint c, Pt s, int missionS, int minRangeCm)
        {
            if (!c.Present(missionS)) return false;
            long vx = s.X - c.At.X, vy = s.Y - c.At.Y, d = G.Isqrt(vx * vx + vy * vy);
            if (d < minRangeCm) return false;
            return vx * c.Faces.X + vy * c.Faces.Y >= c.Cos * d;
        }

        /// <summary>The best hit modifier (per mille) a body at p, standing still, gets against a shooter: full, partial, or 1000 (none).</summary>
        public static int Modifier(IReadOnlyList<CoverPoint> points, Pt p, Pt shooter, int missionS, int snapCm, int minRangeCm, int qFull, int qPartial, int modFull, int modPartial)
        {
            int best = 1000; long snap2 = (long)snapCm * snapCm;
            foreach (var c in points)
            {
                if (G.D2(p, c.At) > snap2 || !Protects(c, shooter, missionS, minRangeCm)) continue;
                int m = c.Q >= qFull ? modFull : c.Q >= qPartial ? modPartial : 1000;
                if (m < best) best = m;
            }
            return best;
        }

        /// <summary>The cover point a body runs to, or null. Candidates: not taken, present, at least partial, within seek. With a foe: it shields
        /// against the foe and brings the body no more than stepCloser nearer the foe; without one: no more than retreat farther from the objective.
        /// Minimises distance − quality, then the lower id.</summary>
        public static CoverPoint? Select(IReadOnlyList<CoverPoint> points, Pt me, Pt objective, Pt? foe, ICollection<string> taken, int seekCm, int missionS,
            int minRangeCm, int qPartial, int retreatCm, int stepCloserCm)
        {
            long here = Dist(me, objective);
            CoverPoint? best = null; long bestKey = long.MaxValue;
            foreach (var c in points)
            {
                if (taken.Contains(c.Id) || c.Q < qPartial || !c.Present(missionS)) continue;
                long d = Dist(me, c.At);
                if (d > seekCm) continue;
                if (!foe.HasValue && Dist(c.At, objective) > here + retreatCm) continue;
                if (foe.HasValue && (!Protects(c, foe.Value, missionS, minRangeCm) || Dist(c.At, foe.Value) < Dist(me, foe.Value) - stepCloserCm)) continue;
                long key = d - c.Q;
                if (key < bestKey || (key == bestKey && best != null && string.CompareOrdinal(c.Id, best.Id) < 0)) { best = c; bestKey = key; }
            }
            return best;
        }
        static long Dist(Pt a, Pt b) => G.Isqrt(G.D2(a, b));
    }
}

sim/Suborned.Sim/Debrief.cs.text:
// The debrief (§08 [B]) as data: the top-down test's nextCity, with ids instead of sentences (Fable writes the words, Glyph lays
// them out). Public security from the final Alert and any shot; the investigation from the Trail and named causes; contacts and
// assets; the route summary; the interventions beyond the route.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed class Debrief
    {
        public string PublicSecurity = "", InvestigationState = "", InvestigationCause = "";
        public int Contacts; public bool Loud;
        public string FightBranch = ""; public int FightHostiles, FightDownedByEnforcer, FightDownedByGuard, FightDownedByCell, FightHits, FightShots;
        public readonly List<string> Captured = new List<string>(); public readonly List<(string op, int health, int max)> Cell = new List<(string, int, int)>();
        public Investigation Inv = new Investigation(); public Between Next = new Between(); public int Sightings; public readonly List<string> FightWhy = new List<string>();
        public readonly List<string> Assets = new List<string>(), Route = new List<string>(), Extra = new List<string>(), Chain = new List<string>();
        /// <summary>brief 018 §3: everyone not in the car when it left, with fate and why.</summary>
        public readonly List<(string op, string fate, string why)> LeftBehind = new List<(string, string, string)>();
        /// <summary>What ended a failed (or withdrawn) run, for the fail camera (FailCause.cs); null on success, and then not written.</summary>
        public FailCause? Cause;

        public static Debrief Of(Game g)
        {
            var d = new Debrief { Loud = g.Gunfire > 0, Cause = g.Cause };
            d.PublicSecurity = g.Alert >= 3 ? "high" : d.Loud ? "raised" : "calm";
            bool inezExposed = g.GuardReachedCafe;
            d.Inv = g.Investigate(); d.Next = g.BetweenMissions(d.Inv); d.Sightings = g.Sightings.Count;
            // §08: little → early → active by Trail (0 / 1–2 / 3+); a named cause takes precedence: a civilian shot, a witness of violence, the
            // Fixer's face given up to the investigators (rulebook investigation), the staged distraction; then the count
            (d.InvestigationState, d.InvestigationCause) =
                g.GunOf("waitress")!.Down ? ("active", "waitress-shot") :
                g.GunOf("driver")!.Down ? ("active", "driver-shot") :
                g.InezWitnessedShooting ? ("active", "waitress-witnessed-shooting") :
                g.InezMethod == "pressure" ? ("active", "waitress-can-identify-fixer") :
                d.Inv.NamedCause.Length > 0 ? ("active", d.Inv.NamedCause) :
                inezExposed ? ("active", "staged-distraction") :
                g.Trail >= 3 ? ("active", "several-interventions") :
                g.Trail > 0 ? ("early", "few-leads") : ("little", "");
            if (g.Inez.Turned && !g.Inez.Down) d.Contacts++;
            if (g.Driver.Turned && !g.Driver.Down) d.Contacts++;
            if (g.Inez.Turned && !g.Inez.Down)
                d.Assets.Add(g.InezWitnessedShooting ? "waitress-witnessed-shooting" : g.InezMethod == "pressure" ? "waitress-may-identify-fixer" : inezExposed ? "waitress-may-be-questioned" : "waitress-introduces-cafe");
            if (g.Driver.Turned && !g.Driver.Down) d.Assets.Add("driver-alters-pickups");
            d.Chain.AddRange(g.Chain);
            d.FightBranch = g.FightBranch; d.FightHostiles = g.Hostiles.Count; d.FightDownedByEnforcer = g.DownedByEnforcer; d.FightDownedByGuard = g.DownedByGuard; d.FightDownedByCell = g.DownedByCell; d.FightHits = g.FightHits; d.FightShots = g.FightShots; d.FightWhy.AddRange(g.FightWhy);
            d.Captured.AddRange(g.Captured); d.LeftBehind.AddRange(g.LeftBehindAtGo); foreach (var op in g.Ops) d.Cell.Add((Sim.Op.Name(op.Id), op.Gun.Health, op.Gun.Max)); // wounds carry over (§08)

            var relevant = new HashSet<string>(StringComparer.Ordinal);
            if (g.RouteKind == "front")
            {
                relevant.Add("loop");
                if (g.RouteGuard == "shot") relevant.Add("fire:guard");
                else if (g.RouteGuard == "waitress") { relevant.Add("turn." + (g.InezMethod.Length > 0 ? g.InezMethod : "help") + ":waitress"); relevant.Add("call:waitress"); }
                if (g.RouteBot == "rerouted") relevant.Add("reroute");
                d.Route.Add(g.RouteGuard == "shot" ? (g.InezWitnessedShooting ? "guard-shot-beside-waitress" : "guard-shot-away-from-waitress")
                    : g.RouteGuard == "knocked-out" ? "guard-knocked-out" : g.RouteGuard == "killed" ? "guard-killed" // a takedown (brief 013 E4), not a shooting
                    : "waitress-pulls-guard-away");
                d.Route.Add("entrance-camera-looped");
                d.Route.Add(g.RouteBot == "rerouted" ? "patrol-diverted" : "entry-timed-between-sweeps");
                d.Route.Add("vale-taken-through-office"); d.Route.Add("vale-reaches-getaway-car");
            }
            else if (g.RouteKind == "service" || g.RouteKind == "pickup")
            {
                if (g.RouteKind == "service") relevant.Add("turn.help:driver"); else relevant.Add("call:driver");
                if (g.RouteRival == "mislead") relevant.Add("mislead"); else if (g.RouteRival == "fire") relevant.Add("fire:rivals");
                d.Route.Add(g.RouteKind == "service" ? "driver-moves-vale-to-service-lane" : "pickup-camera-blocked");
                if (g.RouteRival.Length > 0) d.Route.Add(g.RouteRival == "fire" ? "rivals-driven-back" : "rivals-follow-false-tip");
                d.Route.Add("vale-intercepted-outside"); d.Route.Add("vale-reaches-getaway-car");
            }
            // interventions that left a trace beyond the route (the top-down test's traceLabels), counted in the order first taken
            var traced = new[] { "turn.ask:waitress", "turn.pay:waitress", "turn.help:waitress", "turn.pressure:waitress", "call:waitress", "turn.help:driver", "turn.pay:driver",
                "call:driver", "loop", "reroute", "mislead", "fire:guard", "fire:waitress", "fire:driver", "fire:rivals" };
            var order = new List<string>(); var count = new Dictionary<string, int>(StringComparer.Ordinal);
            foreach (var a in g.Actions)
            {
                if (Array.IndexOf(traced, a) < 0 || relevant.Contains(a)) continue;
                if (!count.ContainsKey(a)) { count[a] = 0; order.Add(a); }
                count[a]++;
            }
            foreach (var a in order) d.Extra.Add($"{count[a]} {a}");
            return d;
        }

        public void Write(JWriter w)
        {
            w.Obj().Prop("publicSecurity", PublicSecurity).Open("investigation").Prop("state", InvestigationState).Prop("cause", InvestigationCause).EndObj()
                .Prop("contacts", Contacts).Prop("loud", Loud);
            w.OpenArr("assets"); foreach (var a in Assets) w.Str(a); w.EndArr();
            w.OpenArr("route"); foreach (var a in Route) w.Str(a); w.EndArr();
            w.OpenArr("extraInterventions"); foreach (var a in Extra) w.Str(a); w.EndArr();
            w.OpenArr("chain"); foreach (var a in Chain) w.Str(a); w.EndArr();
            w.Open("investigators").Prop("count", Inv.Investigators).Prop("hops", Inv.Hops).Prop("sightings", Sightings).OpenArr("findings");
            foreach (var x in Inv.Findings)
            {
                w.Obj().Prop("hop", x.Hop).Prop("who", x.Who).Prop("outcome", x.Outcome).Prop("lead", x.Lead);
                w.OpenArr("gives"); foreach (var f in x.Facts) w.Str(f); w.EndArr();
                if (x.Cause.Length > 0) w.Prop("because", x.Cause);
                w.EndObj();
            }
            w.EndArr();
            if (Inv.Hunted.Count > 0) { w.OpenArr("hunted"); foreach (var x in Inv.Hunted) w.Str(x); w.EndArr(); } // brief 018: written only when set
            w.EndObj();
            w.Open("nextMission").Prop("ambush", Next.Ambush);
            if (Next.Cases.Count > 0 || Next.CampaignTrail != 0) // brief 013: written only when a takedown left something, so older debriefs read as before
                w.Prop("campaignTrail", Next.CampaignTrail).Prop("campaignStanding", Next.CampaignStanding).Prop("openCases", Next.OpenCases).Prop("nextLevel", Next.NextLevel); w.OpenArr("ambushBy"); foreach (var a in Next.AmbushBy) w.Str(a); w.EndArr();
            w.OpenArr("standing"); // brief 014: one line per district (rulebook debrief.lines.standing) and the Standing the next mission starts at
            foreach (var l in Next.Standing)
            {
                w.Obj().Prop("district", l.District).Prop("from", l.From).Prop("to", l.To).Prop("band", l.Band).Prop("cause", l.Cause).Prop("who", l.Who)
                 .Prop("mission", l.End - l.From).Prop("found", l.Found).Prop("word", l.Word).Prop("wordUncapped", l.WordUncapped).Prop("drift", l.Drift).OpenArr("moves");
                foreach (var (d, c, who) in l.Moves) w.Obj().Prop("delta", d).Prop("cause", c).Prop("who", who).EndObj();
                w.EndArr().EndObj();
            }
            w.EndArr();
            if (Next.Captives.Count > 0 || Next.CarSeenBy.Length > 0) // brief 018 §3: written only when the car left someone or was seen
            {
                if (Next.CarSeenBy.Length > 0) w.Prop("carSeenBy", Next.CarSeenBy);
                w.OpenArr("captives");
                foreach (var c in Next.Captives)
                {
                    w.Obj().Prop("who", c.Op).Prop("why", c.Why).Prop("heldAt", c.HeldAt).Prop("holds", c.Holds).Prop("talksAt", c.TalksAt).Prop("rescueUntil", c.RescueUntil)
                     .Prop("bravery", c.Sc[0]).Prop("resentment", c.Sc[1]).Prop("fear", c.Sc[2]).Prop("loyalty", c.Sc[3]).Prop("left", c.Left).Prop("right", c.Right).OpenArr("gives");
                    foreach (var f in c.Facts) w.Str(f);
                    w.EndArr().EndObj();
                }
                w.EndArr();
            }
            w.OpenArr("lines"); foreach (var l in Next.Lines) w.Obj().Prop("line", l.Line).Prop("who", l.Who).Prop("detail", l.Detail).EndObj(); w.EndArr();
            w.OpenArr("contacts");
            foreach (var c in Next.Contacts)
                w.Obj().Prop("who", c.Role.Length > 0 ? c.Role : c.Id).Prop("name", c.Name).Prop("need", c.Need).Prop("needKnown", c.KNeed)
                 .Prop("bravery", c.Sc[0]).Prop("resentment", c.Sc[1]).Prop("fear", c.Sc[2]).Prop("loyalty", c.Sc[3]).EndObj();
            w.EndArr().EndObj();
            if (FightBranch.Length > 0)
            {
                w.Open("finalFight").Prop("branch", FightBranch).Prop("hostiles", FightHostiles).Prop("downedByEnforcer", FightDownedByEnforcer).Prop("downedByGuard", FightDownedByGuard).Prop("downedByCell", FightDownedByCell).Prop("hitsTaken", FightHits).Prop("shots", FightShots);
                w.OpenArr("why"); foreach (var a in FightWhy) w.Str(a); w.EndArr(); w.EndObj();
            }
            w.OpenArr("cell"); foreach (var (op, hp, max) in Cell) w.Obj().Prop("op", op).Prop("health", hp).Prop("max", max).EndObj(); w.EndArr();
            w.OpenArr("captured"); foreach (var c in Captured) w.Str(c); w.EndArr();
            if (LeftBehind.Count > 0) { w.OpenArr("leftBehind"); foreach (var (op, fate, why) in LeftBehind) w.Obj().Prop("who", op).Prop("fate", fate).Prop("why", why).EndObj(); w.EndArr(); } // brief 018
            if (Cause != null) { w.Key("cause"); Cause.Write(w); } // the fail camera's culprit: only a failed or withdrawn run has one
            w.EndObj();
        }
    }

    /// <summary>Loading and playing: the engine's inputs from the repo, a script played to its end, a replay from its orders.</summary>
    public static class Engine
    {
        public const string RulebookFile = "contracts/rules/rulebook.json", PeopleRulesFile = "contracts/people/people.rules.json", SiteFile = "sim/data/handover.site.json", PeopleFile = "sim/data/handover.people.json",
            ProvisionalFile = "sim/data/handover.provisional.json", // brief 013: the security level until the plan and mission carry it
            TakedownFile = "sim/data/handover.takedown.json",       // brief 013: stashes, report points, docks and posts (Splice, tools/sim/takedown.ts)
            RoundsFile = "sim/data/handover.rounds.json";           // brief 022: the server's baked round (Pulse, tools/routines/rounds.ts)

        public sealed class Inputs
        {
            public string Rulebook = "", PeopleRules = "", Site = "", People = "", Provisional = "", Takedown = "", Rounds = ""; public Rules Rules = null!; public Site SiteData = null!; public Crowd? Crowd;
            /// <summary>The inputs' hash over their canonical text (no BOM, LF line ends: Redline E4), so a Windows checkout replays a Mac record.</summary>
            public ulong Hash { get { unchecked { var h = Sim.Hash.Of(Rulebook) ^ (Sim.Hash.Of(PeopleRules) * 3) ^ (Sim.Hash.Of(Site) * 7) ^ (Sim.Hash.Of(People) * 11); if (Provisional.Length > 0) h ^= Sim.Hash.Of(Provisional) * 13; if (Takedown.Length > 0) h ^= Sim.Hash.Of(Takedown) * 17; if (Rounds.Length > 0) h ^= Sim.Hash.Of(Rounds) * 19; return h; } } } // a host without brief 013's files hashes as before, and its record says so
        }
        static Inputs? cache; static string? cacheRoot;
        public static Inputs Load(string root)
        {
            if (cache != null && cacheRoot == root) return cache;
            string rd(string f) => System.IO.File.ReadAllText(System.IO.Path.Combine(root, f));
            string? opt(string f) => System.IO.File.Exists(System.IO.Path.Combine(root, f)) ? rd(f) : null;
            var i = FromTexts(rd(RulebookFile), rd(PeopleRulesFile), rd(SiteFile), rd(PeopleFile), opt(ProvisionalFile), opt(TakedownFile), opt(RoundsFile));
            cache = i; cacheRoot = root; return i;
        }
        /// <summary>The same inputs from their texts, for a host that reads files its own way (Unity: TextAssets or StreamingAssets).</summary>
        /// <summary>The engine's version for run records: bump it when a change moves any replay. The assembly's MVID is recorded beside it.</summary>
        public const string Version = "suborned.sim/0.9.0"; // 0.9.0: the driven agent, EXPERIMENTAL (brief 025 playground, Sky 2026-10-19; rulebook cell.drive): a host moves one operative freely and hands the engine a drive sample a tick (an order: to, run, face; release), checked against the pace budget (cell.speed or runSpeed, burst, slack), the walk grid one axis at a time (it slides along walls, never crosses one) and a gap to people; the agent is then where it stands for every rule; a run is one span from Shift down to Shift up (runAlert once a span); pushing a busy agent cancels its act at the cancel cost (onBusy), release stands it (onRelease); a playground start may set pace, onBusy, onRelease, gap (Start.drive); Start.holds (test only) places a held scene at a door (N85); the official car faces along its bay at block-spot (site car.blockFacing, read by CarHeading only); the rulebook and the site move every inputs hash. 0.8.2: a person walks a routine leg 0..12 % faster than its timing, by a hash of their id, and waits at its end (rulebook crowd.pace, brief 023, Pulse: people who leave a stop on the same tick no longer walk as one block); every moving car keeps to the site's drive grid (rulebook car.drive, brief 023: carriageways, bays and drives, never a pavement): the turned driver reaches the service bay (mission point service-bay, parked facing car.serviceFacing) by the road and the drive, and the block move stops at block-spot's nearest drivable cell; a car drives each drive-grid cell at its surface's pace (rulebook car.pace, Motive 2026-10-19: road 5 m/s, drive or bay 2 m/s; the site marks cells r and y): the turned driver is in the service bay about 13 s after driverLast and waits there for Vale (the block move keeps blockMoveS); a car keeps off the kerb (Grid.CarRoute: a carriageway's lane, the middle of a drive or bay; the site's drive.lane); fire orders on final-fight hostiles end when the final fight is over and new ones are refused fight-over (rulebook fight.over, Motive 2026-10-19); the rulebook and the site move every inputs hash. 0.8.1: the summoned partner stands at her side (brief 022 §7.1, Pulse): his stop is the first of the baked rounds guard.stops with nobody within rounds.clear (partners-clear-cm) at the call, else the farthest from anyone; the rulebook and the rounds file move every inputs hash. 0.8.0: the living café (brief 022, Sky 2026-10-18): a server works her round from the baked sim/data/handover.rounds.json (held while spoken to, called home by the summons, ended by Alert 2, a shot, a body found or the final fight); the summoned lover stops rounds.close short of her post, facing her; Path.Heading skips zero-length segments (moves no run); the rounds file moves every inputs hash. 0.7.0: the getaway (brief 018, Sky 2026-10-18): the hold is 8 m or the exit lane (site getaway.exit) with one blocker per fight, Board and Go replace Extract, left behind at Go (captured or walks out), seen leaving (+1 T, the car hunted), the custody projection; the rulebook, the people rules and the site move every inputs hash. 0.6.3: open needs phase 1 (brief 017): the people file is suborned.sim.people/2, every person carries a need record (kind, label, size, holder), read strictly and never acted on; behaviour unchanged, only the inputs hash moves. 0.6.2: a public fight moves Standing once, by whom the cell fought (fight.public, Sky 2026-10-16; retires 0.6.1's gunfire.heard). 0.6.1: a public gunfight costs Standing (gunfire.heard, Sky 2026-10-16). 0.6.0: brief 014 (private turning; Standing starts at +2, the word and the drift between missions). 0.5.0: brief 013 (takedowns, bodies, reports, the response dial, check-in marks)
        public static string Mvid => typeof(Engine).Assembly.ManifestModule.ModuleVersionId.ToString("D");

        public static Inputs FromTexts(string rulebook, string peopleRules, string site, string? people = null, string? provisional = null, string? takedown = null, string? rounds = null)
        {
            rounds = rounds == null ? null : JNode.Canon(rounds);
            rulebook = JNode.Canon(rulebook); peopleRules = JNode.Canon(peopleRules); site = JNode.Canon(site); people = people == null ? null : JNode.Canon(people);
            provisional = provisional == null ? null : JNode.Canon(provisional); takedown = takedown == null ? null : JNode.Canon(takedown);
            var i = new Inputs { Rulebook = rulebook, PeopleRules = peopleRules, Site = site, People = people ?? "", Provisional = provisional ?? "", Takedown = takedown ?? "", Rounds = rounds ?? "" };
            i.Rules = new Rules(rulebook, peopleRules); i.SiteData = new Site(site);
            if (provisional != null) i.SiteData.AddProvisional(provisional);
            if (takedown != null) i.SiteData.AddTakedownWorld(takedown);
            if (rounds != null) i.SiteData.Rounds = RoundsData.Parse(rounds, i.Rules, i.SiteData); // brief 022: the mission's data turns the round on
            if (people != null)
            {
                var cast = new List<string>(); foreach (var c in i.SiteData.Cast) cast.Add(c.Id);
                i.Crowd = new Crowd(people, i.Rules, cast);
                i.Crowd.Warm(i.SiteData); // every routine leg's walk, once, at load: no tick pays for it
            }
            return i;
        }
        /// <summary>The repository root: the nearest directory above `from` holding contracts/rules/rulebook.json.</summary>
        public static string FindRoot(string from)
        {
            var d = new System.IO.DirectoryInfo(from);
            while (d != null) { if (System.IO.File.Exists(System.IO.Path.Combine(d.FullName, RulebookFile))) return d.FullName; d = d.Parent; }
            throw new System.IO.FileNotFoundException($"no {RulebookFile} above {from}");
        }

        public static Game New(Inputs i, Start? start = null) => new Game(i.Rules, i.SiteData, start, i.Hash.ToString(System.Globalization.CultureInfo.InvariantCulture), i.Crowd);

        /// <summary>Play a start state and its orders (sorted by tick, stable) to `until` or the outcome.</summary>
        public static Game Play(Inputs i, Start start, IReadOnlyList<Order> orders, int until)
        {
            var g = New(i, start);
            if (until <= 0) until = Game.T(i.SiteData.Over); // a script without `until` plays to the close mission.json gives
            var list = new List<(int idx, Order o)>(); for (int k = 0; k < orders.Count; k++) list.Add((k, orders[k]));
            list.Sort((a, b) => a.o.Tick != b.o.Tick ? a.o.Tick.CompareTo(b.o.Tick) : a.idx.CompareTo(b.idx));
            foreach (var (_, o) in list)
            {
                if (o.Tick > until) break; // orders past `until` are not played (Redline I2)
                g.RunTo(o.Tick);
                if (g.Over && g.Tick != o.Tick) break; // the mission ended before this order's tick: nothing later was given
                if (g.Tick == o.Tick) g.Issue(o);      // at the tick it ended, the played run took (and refused) it: so does the replay
            }
            g.RunTo(until); g.Finish();
            return g;
        }
        /// <summary>Replay a finished game from its own start state and order log.</summary>
        public static Game Replay(Inputs i, Game played)
        {
            var orders = new List<Order>(); foreach (var (o, _, _, _) in played.Orders) orders.Add(o);
            return Play(i, played.Start, orders, played.Tick);
        }
    }
}

sim/Suborned.Sim/FailCause.cs.text:
// What failed the run, as data for the fail camera (Sky 2026-10-18: "if you fail mission, the camera should pan around the item / person
// that failed you so you know what it was for next time"). Read-only: built at the tick the run ends from state the engine already holds,
// never hashed, never read by a rule, so every replay and checkpoint is the one it was. One cause per ending (a failure, or a withdrawal).
//  · culprits: what decided it, the first is the one to orbit: a camera, the guard, the patrol, an officer or robot, the rivals, a person,
//    Vale, the car, or an operative (who fired, who killed). Where it stood and faced at the deciding tick, in the block frame (cm).
//  · ops: the cell's operatives involved (who was seen, who was downed, who fired).
//  · single: one culprit decided it. When false (the seal clock, an engine error, a withdrawal) `origin` names what started it, if
//    anything did: the report that raised the response, its reporter where they stood when it landed, and the operatives it names.
// Ids use the engine's own grammar so a host can ask the engine about them again: "camera:<id>" (Game.ConeFan, Known), "guard", "patrol",
// "security-<n>", "robot-<n>", "police-<n>", "rivals", "rival-<n>", "officer-<n>", a person's role (cast) or id (crowd), an operative
// ("enforcer"), "car" (the official car), "getaway-car", "desk" (the check-in desk: a missed mark), "heard" (shots heard, nobody saw).
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>One thing the fail camera can look at: what it is, what it did, where it stood and faced at the tick it is read.</summary>
    public sealed class Blamed
    {
        public string Id = "";    // the engine's id (see the file header)
        public string Kind = "";  // camera, guard, patrol, officer, robot, rival, person, vale, op, car, desk, heard
        public string Role = "";  // saw, shot, reached, killed, left, reported, victim
        public bool Placed;       // false: off the street (inside, gone), no position to orbit
        public Pt At;             // cm, block frame; level 0 (every Handover watcher and body stands on the street)
        public bool Faces;        // a facing is known (cameras, the guard, the patrol, officers, robots, the rivals, a shooter, a walking operative)
        public Pt Facing;         // a direction (any length)

        public void Write(JWriter w)
        {
            w.Obj().Prop("id", Id).Prop("kind", Kind).Prop("role", Role);
            if (Placed) w.Prop("x", At.X).Prop("y", At.Y).Prop("level", 0);
            if (Placed && Faces) w.Prop("fx", Facing.X).Prop("fy", Facing.Y);
            w.EndObj();
        }
        public override string ToString() => $"{Kind}:{Id}/{Role}" + (Placed ? "@" + At : "") + (Faces ? ">" + Facing : "");
    }

    /// <summary>What started a chain that has no single culprit: the report that raised the response (or made the final fight loud).</summary>
    public sealed class CauseOrigin
    {
        public int Tick;                 // when the report landed (or the shot was fired)
        public string Report = "";       // what was reported: gunfire:<target>, drawn-seen, attack, post-empty, report:<kind>:<victim>, ...
        public string Because = "";      // what the seal clock began from: response (a report called the response), confirmed (a unit confirmed a reported act), loud-fight
        public Blamed? Reporter;         // who reported it, where they stood when it landed (a camera, the guard, a witness, the desk, "heard")
        public Blamed? Confirmer;        // because "confirmed": the unit or watcher that confirmed it, where it stood then
        public bool ScenePlaced; public Pt Scene; // where it happened
        public readonly List<string> Ops = new List<string>();

        public void Write(JWriter w)
        {
            w.Obj().Prop("tick", Tick).Prop("clock", Sim.Report.Clock(Tick)).Prop("report", Report).Prop("because", Because);
            if (Reporter != null) { w.Key("reporter"); Reporter.Write(w); }
            if (Confirmer != null) { w.Key("confirmer"); Confirmer.Write(w); }
            if (ScenePlaced) w.Open("scene").Prop("x", Scene.X).Prop("y", Scene.Y).Prop("level", 0).EndObj();
            w.OpenArr("ops"); foreach (var o in Ops) w.Str(o); w.EndArr();
            w.EndObj();
        }
    }

    /// <summary>The cause of an ending: the fail code (or "withdraw"), the deciding tick, why, the culprits, the operatives, the origin.</summary>
    public sealed class FailCause
    {
        public string Fail = "";         // Game.FailCode, or "withdraw" for a withdrawal
        public string Why = "";          // stable machine reason: seen, beat-to-pickup, reached-car, downed-enforcer, reached-at-close, too-late, shot, killed, sealed, error, withdrew, car-left-without-vale
        public int Tick;                 // the deciding moment (the run ends at it)
        public bool Single;              // one culprit decided it; false: see Origin
        public readonly List<Blamed> Culprits = new List<Blamed>();
        public readonly List<string> Ops = new List<string>();
        public CauseOrigin? Origin;
        /// <summary>The seal only: a later report that moved the seal clock earlier (the one whose time ran out), when it is not the origin.</summary>
        public CauseOrigin? LastMove;

        public void Write(JWriter w)
        {
            w.Obj().Prop("fail", Fail).Prop("why", Why).Prop("tick", Tick).Prop("clock", Sim.Report.Clock(Tick)).Prop("single", Single);
            w.OpenArr("culprits"); foreach (var c in Culprits) c.Write(w); w.EndArr();
            w.OpenArr("ops"); foreach (var o in Ops) w.Str(o); w.EndArr();
            if (Origin != null) { w.Key("origin"); Origin.Write(w); }
            if (LastMove != null) { w.Key("lastMove"); LastMove.Write(w); }
            w.EndObj();
        }
        public string Json() { var w = new JWriter(); Write(w); return w.ToString(); }
    }

    public sealed partial class Game
    {
        /// <summary>Why the run ended (a failure or a withdrawal): set once, at the tick it ends; null while it runs and on success. Output only.</summary>
        public FailCause? Cause;

        // what the seal clock (and a loud final fight) began from: kept as they happen, read only when the run fails. Never hashed.
        CauseOrigin? sealOrigin, sealLast, alertTwoOrigin, gunfireOrigin, pendingSealOrigin, shotNow;
        readonly Dictionary<int, CauseOrigin> actOrigin = new Dictionary<int, CauseOrigin>();
        string landingBy = ""; Pt landingAt; // the report landing now (LandAct), for an Alert it raises

        /// <summary>The cause of the failure now; a builder that throws leaves a cause with why "unresolved" (it can never change the run).</summary>
        FailCause MakeCause(string code, Func<FailCause>? build)
        {
            FailCause c;
            try { c = build?.Invoke() ?? new FailCause { Why = "unresolved" }; }
            catch (Exception e) when (!(e is OutOfMemoryException)) { c = new FailCause { Why = "unresolved" }; }
            c.Fail = code; c.Tick = Tick;
            return c;
        }

        static FailCause Because(string why, bool single, params Blamed?[] culprits)
        {
            var c = new FailCause { Why = why, Single = single };
            foreach (var b in culprits) if (b != null) c.Culprits.Add(b);
            return c;
        }
        static FailCause With(FailCause c, params string[] ops) { foreach (var o in ops) if (o.Length > 0 && !c.Ops.Contains(o)) c.Ops.Add(o); return c; }

        /// <summary>Where a thing stands and faces now, by the engine's id. look: the point it acted on (a mast's head that faces it; a shooter
        /// or an operative standing still faces it). fallback: where it is when the engine keeps no position (the desk's post, a phone).</summary>
        public Blamed Locate(string id, string role, Pt? look = null, Pt? fallback = null)
        {
            var b = new Blamed { Id = id, Role = role };
            void at(Pt? p) { if (p.HasValue) { b.Placed = true; b.At = p.Value; } else if (fallback.HasValue) { b.Placed = true; b.At = fallback.Value; } }
            void face(Pt? f) { if (f.HasValue && (f.Value.X != 0 || f.Value.Y != 0)) { b.Faces = true; b.Facing = f.Value; } }
            void toward() { if (b.Placed && look.HasValue) face(look.Value - b.At); }
            if (id.StartsWith("camera:", StringComparison.Ordinal))
            {
                b.Kind = "camera"; var cid = id.Substring(7);
                foreach (var c in S.Cameras)
                    if (c.Id == cid)
                    {
                        at(c.At); var f = c.Facing;
                        if (look.HasValue) foreach (var h in c.Facings) if (G.InCone(c.At, h, c.Reach, c.Half, 0, look.Value)) { f = h; break; } // the head that saw it
                        face(f);
                    }
                return b;
            }
            if (IsOpId(id)) { b.Kind = "op"; var op = OpOf(Sim.Op.Parse(id)); at(op.Pos); if (op.Walk != null) face(op.Walk.Heading(op.WalkMm)); else toward(); return b; }
            switch (id)
            {
                case "desk": b.Kind = "desk"; at(null); return b;
                case "heard": b.Kind = "heard"; at(null); return b;
                case "car": b.Kind = "car"; at(CarPos()); return b;
                case "getaway-car": b.Kind = "car"; at(S.At(S.GetawayCar)); return b;
                case "guard":
                    {
                        b.Kind = "guard"; var gp = GuardPose();
                        if (gp.HasValue) { at(gp.Value.pos); face(gp.Value.facing); }
                        else { at(BodyOf(GuardP) is Body gb ? BodyPos(gb) : (Pt?)null); }
                        return b;
                    }
                case "patrol": { b.Kind = "patrol"; var pp = PatrolPose(); if (pp.HasValue) { at(pp.Value.pos); face(pp.Value.facing); } else at(null); return b; }
                case "rivals": { b.Kind = "rival"; var rp = RivalsPose(); if (rp.HasValue) { at(rp.Value.pos); face(rp.Value.facing); } else at(null); return b; }
            }
            int k = SecIndex(id);
            if (k >= 0) { b.Kind = "officer"; var sp = SecOfficerPose(k); if (sp.HasValue) { at(sp.Value.pos); face(sp.Value.facing); } else at(null); return b; }
            foreach (var u in Units)
                if (u.Id == id && !u.Legacy && !u.Patrol)
                {
                    b.Kind = u.Robot ? "robot" : "officer"; var up = UnitPose(u);
                    if (up.HasValue) { at(up.Value.pos); face(up.Value.facing); } else at(null);
                    return b;
                }
            if (HostileOf(id) is Hostile ho)
            {
                b.Kind = IsRival(id) ? "rival" : "officer"; at(ho.Pos(Tick));
                var tp = ho.Gun.Target.Length > 0 ? PosOf(ho.Gun.Target) : null;
                if (tp.HasValue) face(tp.Value - b.At);
                else if (ho.Run != null && ho.Moving(Tick)) face(ho.Run.Heading((long)Math.Max(0, Tick - ho.RunStart) * ho.Speed));
                else toward();
                return b;
            }
            if (PersonById(id) is Person p)
            {
                b.Kind = p == ValeP ? "vale" : "person";
                Pt? pos = p == ValeP ? ValePos() : PosOfPerson(p);
                if (!pos.HasValue && BodyOf(p) is Body pb) pos = BodyPos(pb);
                at(pos); toward();
                return b;
            }
            b.Kind = "unknown"; at(null);
            return b;
        }
        /// <summary>A shooter at the moment of its shot: where it fired from, facing its target.</summary>
        Blamed Shooter(string by, Pt from, Pt at, string role = "shot")
        {
            var b = Locate(by, role); b.Placed = true; b.At = from;
            if (at != from) { b.Faces = true; b.Facing = at - from; }
            return b;
        }
        /// <summary>The id if it is an operative's, else "".</summary>
        static string OpIn(string id) => IsOpId(id) ? id : "";

        /// <summary>An origin now: what was reported, by whom (where they stand now, or `fallback`), where, and the operatives it names.</summary>
        CauseOrigin OriginNow(string report, string because, string reporter, Pt? scene, Pt? fallback, Pt? look, params string[] ops)
        {
            var o = new CauseOrigin { Tick = Tick, Report = report, Because = because, Reporter = reporter.Length > 0 ? Locate(reporter, "reported", look ?? scene, fallback) : null };
            if (scene.HasValue) { o.ScenePlaced = true; o.Scene = scene.Value; }
            foreach (var x in ops) if (x.Length > 0 && !o.Ops.Contains(x)) o.Ops.Add(x);
            return o;
        }
        static CauseOrigin Recast(CauseOrigin o, string because)
        {
            var n = new CauseOrigin { Tick = o.Tick, Report = o.Report, Because = because, Reporter = o.Reporter, Confirmer = o.Confirmer, ScenePlaced = o.ScenePlaced, Scene = o.Scene };
            n.Ops.AddRange(o.Ops); return n;
        }

        /// <summary>A reported act confirmed at Alert 2 or more: its first landed report, and who confirmed it now.</summary>
        CauseOrigin Confirmed(TdAct a, string by)
        {
            var o = actOrigin.TryGetValue(a.Id, out var first) ? Recast(first, "confirmed") : OriginNow($"report:{a.How}:{a.Victim}", "confirmed", "", a.Scene, null, null, "enforcer");
            o.Confirmer = Locate(by == "security" ? "security-1" : by, "confirmed", a.Scene);
            return o;
        }

        /// <summary>The seal clock moved: the first report that set it is the origin (what started the chain); a later one that moved it is
        /// the last move (whose time ran out). Read when the district seals.</summary>
        void SealOrigin(int before, Func<CauseOrigin?> origin)
        {
            if (Lockdown == before) return;
            try
            {
                var o = origin(); if (o == null) return;
                if (before >= INF || sealOrigin == null) { sealOrigin = o; sealLast = null; } else sealLast = o;
            }
            catch (Exception e) when (!(e is OutOfMemoryException)) { }
        }
        FailCause Sealed()
        {
            var c = Because("sealed", false); c.Origin = sealOrigin; c.LastMove = sealLast;
            if (sealOrigin != null) With(c, sealOrigin.Ops.ToArray());
            if (sealLast != null) With(c, sealLast.Ops.ToArray());
            return c;
        }

        /// <summary>Alert reached 2 (search): who raised it, read from the ledger's cause and the report landing now. For a loud final fight.</summary>
        void AlertTwo(string cause)
        {
            try
            {
                var parts = cause.Split(':'); string first = parts[0], last = parts[parts.Length - 1], who = "", op = "";
                switch (first)
                {
                    case "report": if (parts.Length >= 3 && landingBy.Length > 0) { alertTwoOrigin = OriginNow(cause, "alert", landingBy, landingAt, landingAt, null, "enforcer"); return; } who = last; break; // a landed act's reporter; else the person who reported the approach
                    case "drawn-seen": case "runner-seen": op = last; who = parts.Length > 2 ? string.Join(":", parts, 1, parts.Length - 2) : ""; if (who == "people") who = "heard"; break;
                    case "violence-seen": who = last; break;
                    case "takedown-fails": who = last; op = "enforcer"; break;
                    case "gunfire": if (shotNow != null) { alertTwoOrigin = Recast(shotNow, "alert"); return; } who = last; break; // the cell's shot (CellGunfire), or a city gunman's (Resolve: gunfire:<shooter>)
                    case "sighting": who = last; break;
                    case "confirmed": who = landingBy; break;
                }
                if (who == "security") who = "security-1";
                alertTwoOrigin = OriginNow(cause, "alert", who, null, null, null, op);
            }
            catch (Exception e) when (!(e is OutOfMemoryException)) { alertTwoOrigin = new CauseOrigin { Tick = Tick, Report = cause, Because = "alert" }; }
        }

        /// <summary>Brief 018's rival at the car: every rival within cell.atReach of it (nearest first, ties on id), then Vale in the car.</summary>
        FailCause RivalsAtCar()
        {
            var car = S.At(S.GetawayCar); var near = new List<(long d, string id)>();
            foreach (var h in Hostiles) if (IsRival(h.Id) && h.Present && Up(h) && G.Within(h.Pos(Tick), car, R.AtReachCm)) near.Add((G.D2(h.Pos(Tick), car), h.Id));
            near.Sort((x, y) => x.d != y.d ? x.d.CompareTo(y.d) : string.CompareOrdinal(x.id, y.id));
            var c = Because("reached-car", true);
            foreach (var (_, id) in near) c.Culprits.Add(Locate(id, "reached", car));
            c.Culprits.Add(Locate("councillor", "victim", null, car));
            return c;
        }
        /// <summary>A shot that ended the run (the shot being resolved): the shooter where it fired from, facing its target, then the target.</summary>
        FailCause ShotDown(string why, string target)
        {
            var c = Because(why, true);
            if (resolving != null) { c.Culprits.Add(Shooter(resolving.By, resolving.From, resolving.At)); With(c, OpIn(resolving.By)); }
            if (target.Length > 0) c.Culprits.Add(Locate(target, "victim", null, resolving?.At));
            With(c, OpIn(target));
            return c;
        }

        /// <summary>The cause of a withdrawal: the cell pulled out, or the car left without Vale.</summary>
        void Withdrew(bool carLeft)
        {
            Cause = MakeCause("withdraw", () => carLeft
                ? Because("car-left-without-vale", false, Locate("getaway-car", "left"))
                : Because("withdrew", false));
        }
    }
}

sim/Suborned.Sim/Game.cs.text:
// The Handover, stepped at 10 Hz on integer state (GDD §11). The top-down test's causal model
// (~/Projects/the-suborned/testbed/reference/suborned-world-sim.cjs) moved onto the real civic block (sim/data/handover.site.json)
// and onto the rules as data (contracts/rules/rulebook.json, contracts/people/people.rules.json). Every number comes from the
// rulebook, the people rules or the site; this file holds behaviour only. Orders are the only input after the start state, so a
// run replays exactly from its start state and its orders, and its checkpoint hashes say so.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public enum Outcome { None, Success, Failure, Withdrawn }
    public enum ValeAt { Office, Leaving, Pickup, Taking, WithEnforcer, Car, Dead }

    /// <summary>The start state's choices beyond the site: what a scenario fixes before tick 0 (hashed into the start state).</summary>
    public sealed class Start
    {
        public int? RivalsAtS;                                            // §07 3:10 unless a scenario moves it
        public readonly List<string> Turned = new List<string>();         // roles turned before the mission (a scenario fixture)
        public readonly Dictionary<string, List<string>> Known = new Dictionary<string, List<string>>(StringComparer.Ordinal);
        public readonly Dictionary<string, string> Temperament = new Dictionary<string, string>(StringComparer.Ordinal);
        public long? Cash;
        public bool FinalFight = true;  // §07: the final fight is always fought; the top-down test's 28 had none
        public bool Crowd = true;       // §05 witnesses among the city's people; Suture's T4 arm switches it off
