        void ValeTimeline()
        {
            // the car waits for its driver: shot (security pulls Vale away, as before), or taken down and the city knows it, Vale stays in;
            // a driver taken down quietly isn't known, so Vale comes out to an empty car (brief 013, Sky answer 6)
            bool driverKnownDown = civGuns["driver"].Down || (Driver.Down && BodyOf(Driver) is Body db && Acts[db.Act].Landed);
            if (Tick == T(valeExitsS) && Vale == ValeAt.Office && !EntryInProgress && !driverKnownDown)
            {
                Vale = ValeAt.Leaving; PickupService = Driver.Turned && carToService != null; // the service lane only if the car went there (a downed driver drove nowhere)
                var to = PickupService ? S.Stand(S.ValeService) : S.Stand(S.ValeCar);
                valePath = new Path(S.Grid.Route(S.Stand(S.ValeExit), to) ?? new[] { S.Stand(S.ValeExit), to });
                Note("vale.exits", PickupService ? "Vale comes out and walks round to the service lane, where his car is pulling in." : "Vale steps out of the official entrance and walks to his car.");
            }
            if (Tick == T(valeAtCarS) && Vale == ValeAt.Leaving)
            {
                Vale = ValeAt.Pickup;
                Note("vale.at-car", PickupService ? "Vale reaches the car in the service lane." : "Vale reaches the official car under the pickup camera.");
            }
        }

        void Tether()
        {
            var tech = OpOf(OpId.Tech);
            if (LoopOn && (tech.Down || !G.Within(tech.Pos, S.At("cabinet"), R.TetherCm)))
            {
                LoopOn = false; Note("loop.ends", tech.Down ? "The Tech is down. The camera feed returns." : "The Tech leaves the cabinet. The camera feed returns.");
            }
        }

        void PatrolChase()
        {
            if (!PatrolChasing || PatrolDown || PatrolAwayUntil > Tick || Tick % Hz != 0) return;
            if (PatrolGun.Target.Length > 0 && !patrolReturning) return; // engaging: it stops (Pulse §3.6)
            var target = patrolReturning ? SweepPos(Tick) : patrolOrigin; // to the shot's origin; resuming, back to its sweep
            if (patrolReturning && G.Within(chasePos, target, 100)) { PatrolChasing = false; patrolReturning = false; PatrolGun.NoFoeSince = -1; Note("patrol.sweep", "The patrol is back on its sweep."); return; }
            var t = S.Grid.NearestFree(target); var from = S.Grid.NearestFree(chasePos);
            if (!t.HasValue || !from.HasValue) return;
            var route = S.Grid.Route(from.Value, t.Value); if (route == null) return;
            chasePos = new Path(route).At(chaseSpeed * Hz); // a second's chase, as the top-down test moved it
        }

        // ---------------------------------------------------------------- where things are

        public (Pt pos, Pt facing, string phase)? GuardPose()
        {
            if (GuardDown) return null;
            if (GuardHeld) return (heldPos, heldFacing, heldPhase);
            var post = S.Stand(S.GuardPost);
            if (LureTick < 0 || Tick >= GuardAwayUntil) return (post, S.GuardFacing, "door");
            if (guardRunning) { long rm = (long)(Tick - LureTick) * secSpeed; return (guardRun.At(rm), guardRun.Heading(rm), "returning to door"); }
            int age = Tick - LureTick;
            if (age < walkT) { long mm = guardOut.Length * age / walkT; return (guardOut.At(mm), guardOut.Heading(mm), "walking to café"); }
            if (age < walkT + stayT) return (guardOut.End, cafeFace, "at café"); // brief 022: facing her when she has a round
            long back = guardBack.Length * (age - walkT - stayT) / walkT;
            return (guardBack.At(back), guardBack.Heading(back), "returning to door");
        }
        public bool GuardAtDoor => !GuardDown && !GuardHeld && (LureTick < 0 || Tick >= GuardAwayUntil);

        Pt ParkedCar(int t)
        {
            var pickup = blockPath.Points[0];
            if (t < BlockMove) return pickup;
            if (t < BlockedFrom) return blockPath.At(blockPath.Length * (t - BlockMove) / blockMoveT);
            if (t < BlockedUntil) return blockPath.End;
            if (t < BlockedUntil + blockMoveT) return blockPath.At(blockPath.Length - blockPath.Length * (t - BlockedUntil) / blockMoveT);
            return pickup;
        }
        public Pt CarPos()
        {
            if (carStoppedAt.HasValue) return carStoppedAt.Value;
            if (!Driver.Turned || Tick < T(driverLastS) || carToService == null) return ParkedCar(Tick);
            return carToService.At(CarDriveMm(Tick));
        }
        /// <summary>car.pace (Motive 2026-10-19, brief 023): the drive to the service bay, tick by tick from driverLast: each tick the car moves
        /// its cell's pace (car.pace.road on a carriageway, car.pace.yard on a drive or in a bay; cm/s = mm a tick), read where it stands, to the
        /// route's end, where it waits parked for Vale. Integer, computed once when the drive starts.</summary>
        long[] CarProfile(Path p)
        {
            var mm = new List<long> { 0 };
            long at = 0;
            while (at < p.Length)
            {
                int pace = S.Drive.SurfaceAt(p.At(at)) == 'r' ? R.CarRoadSpeed : R.CarYardSpeed;
                at = Math.Min(p.Length, at + Math.Max(1, pace)); mm.Add(at);
            }
            return mm.ToArray();
        }
        long CarDriveMm(int tick) { var d = carDrive!; int k = tick - T(driverLastS); return k <= 0 ? 0 : k >= d.Length ? d[d.Length - 1] : d[k]; }
        /// <summary>The tick the turned driver's car is parked in the service bay (car.pace), or -1 before it drives.</summary>
        public int CarInBayTick => carDrive == null ? -1 : T(driverLastS) + carDrive.Length - 1;
        /// <summary>Which way the official car points, for the host (read-only, never hashed; brief 023): along its drive while it moves, and
        /// the site's car.serviceFacing once parked in the service bay, car.blockFacing parked at block-spot; null where the host keeps its own rule
        /// (at the pickup, on the block move).</summary>
        public Pt? CarHeading()
        {
            if (carStoppedAt.HasValue) return null;
            if (!Driver.Turned || Tick < T(driverLastS) || carToService == null) return Tick >= BlockedFrom && Tick < BlockedUntil ? S.CarBlockFacing : (Pt?)null; // parked at block-spot: along the bay's kerb (Aster 2026-10-19)
            if (Tick >= CarInBayTick) return S.CarServiceFacing; // parked in the bay (car.pace): it waits there for Vale
            return carToService.Heading(CarDriveMm(Tick));
        }
        public Pt? DriverPos()
        {
            if (Driver.Down) return null;
            var car = CarPos();
            return car == blockPath.Points[0] ? S.Stand(S.CarDriver) : car;
        }
        public Pt? ValePos()
        {
            switch (Vale)
            {
                case ValeAt.Leaving: { int span = T(valeAtCarS) - T(valeExitsS); return valePath!.At(valePath.Length * Math.Min(span, Tick - T(valeExitsS)) / span); }
                case ValeAt.Pickup: case ValeAt.Taking: return PickupService ? S.Stand(S.ValeService) : CarPos();
                case ValeAt.WithEnforcer: return Enforcer.Inside ? (Pt?)null : Enforcer.Pos + new Pt(100, 0);
                default: return null;
            }
        }
        public Pt? PersonPos(Person p)
        {
            if (p.Down) return null;
            if (ServerOf(p) is RoundsData.Server sv) return RoundPoseAt(sv, EvRead(sv), Tick).Pos; // brief 022: a server's round
            if (p == Inez) return S.Stand(Inez.Place);
            if (p == Driver) return DriverPos();
            if (p == GuardP) return GuardPose()?.pos;
            return ValePos();
        }

        public (Pt pos, Pt facing)? PatrolPose()
        {
            if (PatrolDown) return (patrolDownAt, new Pt(0, 0));
            if (PatrolUnit() is Unit pu && UnitPose(pu) is var up && up.HasValue) return up.Value; // brief 013: answering an alarm
            if (PatrolAwayUntil > Tick) return (S.Stand(S.PatrolReroute), S.PatrolRerouteFacing);
            if (PatrolChasing) return (chasePos, Enforcer.Pos - chasePos);
            return (SweepPos(Tick), S.PatrolFacing);
        }
        Pt SweepPos(int t)
        {
            int period = T(R.PatrolPeriodS), half = period / 2, ph = t % period;
            return G.Lerp(S.Stand(S.PatrolA), S.Stand(S.PatrolB), ph <= half ? ph : period - ph, half);
        }

        public bool RivalsPresent => RivalsArrived && RivalsDelayedUntil <= Tick && !rivalsAbsorbed;
        public (Pt pos, Pt facing)? RivalsPose()
        {
            if (!RivalsPresent) return null;
            if (!RivalsDrawn)
            {
                bool atService = Tick >= T(valeAtCarS) && PickupService;
                return (S.Stand(atService ? S.ValeService : S.RivalsPark), new Pt(0, 100));
            }
            bool restarting = RivalsDelayedUntil > RivalsDrawnTick;
            var path = restarting ? (rivalsRestartPath ??= new Path(S.Grid.Route(S.Stand(S.RivalsEntry), S.Stand(S.RivalsFront))!)) : rivalsPath!;
            int start = restarting ? RivalsDelayedUntil : RivalsDrawnTick;
            long mm = (long)Math.Max(0, Tick - start) * rivSpeed;
            return mm >= path.Length ? (path.End, Back(path)) : (path.At(mm), path.Heading(mm));
        }

        /// <summary>The response unit: its lead officer still up, and where the unit faces (its officers walk in file, `SecFileMm` apart).</summary>
        public (Pt pos, Pt facing)? SecurityPose()
        {
            if (SecurityDown || Tick < SecurityArrives) return null;
            for (int k = 0; k < SecGuns.Length; k++) if (!SecGuns[k].Down) return SecOfficerPose(k);
            return null;
        }
        const long SecFileMm = 1500; // the officers' spacing in file: placement only (no rule reads it), until Pulse's hostile spec places them
        public (Pt pos, Pt facing)? SecOfficerPose(int k)
        {
            if (Tick < SecurityArrives || SecGuns[k].Down) return null;
            if (secJoined[k]) { var h = HostileOf(SecGuns[k].Id)!; var p = h.Pos(Tick); return (p, Car - p == new Pt(0, 0) ? new Pt(100, 0) : Car - p); } // joined the loud fight: faces the car
            long mm = (long)(Tick - SecurityArrives) * secSpeed - k * SecFileMm, end = Math.Max(0, securityPath.Length - k * SecFileMm);
            if (mm < 0) mm = 0;
            if (mm >= end) return (securityPath.At(end), Back(securityPath));
            return (securityPath.At(mm), securityPath.Heading(mm));
        }

        /// <summary>At the end of its run a unit holds facing back the way it came, as the top-down test's rivals and response unit did.</summary>
        static Pt Back(Path p) { var h = p.Heading(p.Length); return new Pt(-h.X, -h.Y); }

        // ---------------------------------------------------------------- who sees what (rulebook perception)

        bool Sees(Pt from, Pt to) => S.Sight(from, to, eye);
        public bool CameraWatching(string id, Pt p, bool crowd = true)
        {
            if (id == LoopCam && LoopOn) return false;
            if (id == "pickup" && !PickupCameraLive()) return false;
            foreach (var c in S.Cameras) if (c.Id == id) return InHeads(c, p) && Sees(c.At, p) && !(crowd && CrowdBlocks(c.At, p));
            throw new FormatException($"site has no camera '{id}'");
        }
        /// <summary>In any head's cone of the camera (a mast carries several).</summary>
        static bool InHeads(Camera c, Pt p) { foreach (var f in c.Facings) if (G.InCone(c.At, f, c.Reach, c.Half, 0, p)) return true; return false; }
        public bool PickupCameraLive() => (Driver.Turned && Tick >= T(driverLastS) && carToService != null) || Tick < BlockedFrom || Tick >= BlockedUntil; // after 5:40 the turned driver's car is gone from in front of it (if he drove it)
        /// <summary>The guard's cone; crowd: people on the street block it (Pulse §4: watchers), false for his own aim (§1.6).</summary>
        public bool GuardWatching(Pt p, bool crowd = true)
        {
            var g = GuardPose(); if (!g.HasValue) return false;
            var (pos, f, phase) = g.Value;
            if (phase == "door") return G.InCone(pos, f, R.DoorReachCm, R.DoorHalfCm, 0, p) && Sees(pos, p) && !(crowd && CrowdBlocks(pos, p));
            return G.InCone(pos, f, R.FacingReachCm, R.FacingHalfCm, near, p) && Sees(pos, p) && !(crowd && CrowdBlocks(pos, p));
        }
        public bool PatrolWatching(Pt p, bool crowd = true)
        {
            if (PatrolDown || PatrolAwayUntil > Tick) return false;
            if (PatrolUnit() is Unit pu) return UnitSees(pu, p, crowd); // brief 013: on an alarm it looks where it walks and holds
            var (pos, f) = PatrolPose()!.Value;
            if (PatrolChasing) return G.InCone(pos, f, R.FacingReachCm, R.FacingHalfCm, near, p) && Sees(pos, p) && !(crowd && CrowdBlocks(pos, p));
            return InSweepCone(pos, f, p) && Sees(pos, p) && !(crowd && CrowdBlocks(pos, p));
        }
        bool InSweepCone(Pt pos, Pt f, Pt p)
        {
            long ff = (long)f.X * f.X + (long)f.Y * f.Y, fl = G.Isqrt(ff); if (fl == 0) return false;
            long rx = p.X - pos.X, ry = p.Y - pos.Y;
            long depth = (rx * f.X + ry * f.Y) / fl, side = Math.Abs(rx * f.Y - ry * f.X) / fl;
            if (depth < 0 || depth > R.PatrolDepthCm) return false;
            return side <= R.PatrolHalfBase + depth * R.PatrolHalfPerMille / 1000;
        }
        /// <summary>The top-down test's botSeesEntranceOnPatrol: would the sweep, not rerouted, see the public door now?</summary>
        public bool SweepSeesEntrance(int t)
        {
            var pos = SweepPos(t); var door = S.At(S.GuardPost);
            return InSweepCone(pos, S.PatrolFacing, door) && Sees(pos, door);
        }
        public bool SecurityWatching(Pt p)
        {
            for (int k = 0; k < SecGuns.Length; k++) if (SecOfficerWatching(k, p)) return true;
            return false;
        }
        bool SecOfficerWatching(int k, Pt p, bool crowd = true)
        {
            var s = SecOfficerPose(k); if (!s.HasValue) return false;
            return G.InCone(s.Value.pos, s.Value.facing, R.SecReachCm, R.SecHalfCm, near, p) && Sees(s.Value.pos, p) && !(crowd && CrowdBlocks(s.Value.pos, p));
        }
        public bool RivalsWatching(Pt p)
        {
            if (!RivalsDrawn) return false;
            var r = RivalsPose(); if (!r.HasValue) return false;
            return G.InCone(r.Value.pos, r.Value.facing, R.RivReachCm, R.RivHalfCm, near, p) && Sees(r.Value.pos, p);
        }

        // ---------------------------------------------------------------- security, rivals, patrol answering gunfire

        /// <summary>A report of gunfire (or a downed guard's missed mark) calls the response unit: it arrives by the reporter's delay
        /// (level 1's arrivals, shifted by the level's dispatch), the district seals the level's seal after it arrives, and the level's
        /// robots, reinforcements and cordon follow (brief 013, the dial). landing: the report lands now (the dispatch alone).</summary>
        void CallSecurity(int delayS, string text, Pt? scene = null, bool landing = false, Func<CauseOrigin?>? origin = null)
        {
            int arrival = landing ? Tick + T(DialNow.DispatchS) : GunfireArrival(delayS);
            if (arrival >= SecurityArrives) return;
            bool first = SecurityArrives == INF;
            int lockBefore = Lockdown;
            SecurityArrives = arrival; Lockdown = arrival + T(SealS);
            if (origin != null) SealOrigin(lockBefore, origin); // what the seal clock began from (FailCause.cs, output only)
            Note("security.called", $"{text} Security is coming from the north street.");
            if (first) GunfireAlarm(arrival, scene ?? S.Stand(S.SecTo));
        }
        void DrawRivals()
        {
            if (RivalsDrawn) return;
            var start = RivalsArrived && RivalsPose() is var rp && rp.HasValue ? rp.Value.pos : S.Stand(S.RivalsEntry);
            RivalsDrawn = true;
            if (!RivalsArrived) RivalAt = Math.Min(RivalAt, Tick + T(R.RivalsDrawnS));
            RivalsDrawnTick = RivalsArrived ? Tick : RivalAt;
            rivalsPath = new Path(S.Grid.Route(S.Grid.NearestFree(start) ?? start, S.Stand(S.RivalsFront)) ?? new[] { start, S.Stand(S.RivalsFront) });
            Note("rivals.drawn", "The rivals hear gunfire and head for the Office.");
        }
        void WakePatrol(Pt at, OpId who)
        {
            if (PatrolDown || PatrolAwayUntil > Tick || PatrolChasing) return;
            var pos = PatrolPose()!.Value.pos;
            if (!G.Within(pos, at, R.PatrolBreakCm)) return;
            chasePos = pos; PatrolChasing = true; chaseOp = who; patrolOrigin = at; patrolReturning = false; PatrolGun.NoFoeSince = -1;
            Note("patrol.breaks", "The patrol breaks its route and turns toward the gunfire.");
        }

        /// <summary>A civilian who sees violence (§05: 3 at once; rulebook witness.sees, traceable violence): one incident, once.</summary>
        void ViolenceSeen(string incident, Person witness, string by)
        {
            RaiseAlert(R.ViolenceSeen, $"violence-seen:{incident}:{(witness.Role.Length > 0 ? witness.Role : witness.Id)}");
            Remember(witness, "saw-violence", by, true);
            if (witness.Turned) LadderMove(witness, "saw-violence");
            if (!incidents.Add("seen:" + incident)) return;
            AddTrail(R.WitnessTrail, $"witnessed:{incident}");
            // Standing: a civilian shot at is violence (seen-violence); anyone else shot at (the guard, the rivals, officers) is the fight's
            // to judge, once, when it ends (fight.public, Sky 2026-10-16): the incident's gunfire is traceable gunfire, Standing none
            if (CivilianOf(incident) != null) MoveStanding(-R.StandingStep, $"violence-seen:{incident}", "seen-violence", incident);
        }

        /// <summary>Every change to Trail, Alert and standing with its cause, in order: the answer to "why is the investigation active?" (§13 T3).</summary>
        public readonly List<(int tick, string what, int delta, int now, string cause)> Ledger = new List<(int, string, int, int, string)>();
        void AddTrail(int n, string cause) { if (n == 0) return; Trail += n; Ledger.Add((Tick, "trail", n, Trail, cause)); }
        void RaiseAlert(int to, string cause) { if (to <= Alert) return; int d = to - Alert; bool two = Alert < 2 && to >= 2; Alert = to; Ledger.Add((Tick, "alert", d, Alert, cause)); if (two) AlertTwo(cause); if (Alert >= 2) RoundsEnd("alert-2"); }
        /// <summary>Move the district's Standing: `cause` for the ledger, `why` a rulebook standing.causes id and `who` the person it names, for the
        /// debrief's Standing line (brief 014). StandingMoves is output only, never hashed: Standing itself is.</summary>
        void MoveStanding(int d, string cause, string why, string who)
        {
            if (d == 0) return;
            if (!R.StandingCauses.Contains(why)) throw new InvalidOperationException($"standing cause '{why}' is not in the rulebook (unknown = reject)");
            Standing += d; Ledger.Add((Tick, "standing", d, Standing, cause)); StandingMoves.Add((Tick, d, why, who));
        }
        /// <summary>Every move of Standing in the mission, in order, with its rulebook cause and the person it names (brief 014).</summary>
        public readonly List<(int tick, int delta, string cause, string who)> StandingMoves = new List<(int, int, string, string)>();

        public void Finish()
        {
            // a fight still open when the run ends ends with it (fight.public): its move replaces a checkpoint already taken at this tick
            if (EndOpenFight() | fightClosedLate) { fightClosedLate = false; if (Checkpoints.Count > 0 && Checkpoints[Checkpoints.Count - 1].tick == Tick) Checkpoints.RemoveAt(Checkpoints.Count - 1); }
            if (Checkpoints.Count == 0 || Checkpoints[Checkpoints.Count - 1].tick != Tick) Checkpoints.Add((Tick, Hash.State(this)));
        }
    }
}

sim/Suborned.Sim/GameAi.cs.text:
// The fight AI (Pulse, briefs/011/pulse-fight-ai.md; rulebook `ai`): one machine for every hostile body. routine → alerted → advance →
// engage ↔ hold, break → gone (rivals), down. Targets by class (whoever fired at it, whoever holds Vale, the nearest with a weapon drawn,
// the nearest), kept until a better class appears; cover from the site's cover points (Cover.cs); police hold their stand; the response
// unit joins the loud fight; the guard as an ally runs to his post and shoots the rival nearest the Enforcer. Integers only, ties on id.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed partial class Game
    {
        readonly Dictionary<string, string> coverTaken = new Dictionary<string, string>(StringComparer.Ordinal); // cover point → body
        readonly bool[] secJoined = new bool[8];
        readonly Dictionary<string, int> standOverflow = new Dictionary<string, int>(StringComparer.Ordinal);
        Pt patrolOrigin; bool patrolReturning;

        /// <summary>The AI's own state for the checkpoint hash: cover taken, the response unit joined, the patrol's origin and return.</summary>
        internal void HashAi(Func<long, Hash.H> i)
        {
            var keys = new List<string>(coverTaken.Keys); keys.Sort(StringComparer.Ordinal);
            foreach (var k in keys) { foreach (var c in k) i(c); foreach (var c in coverTaken[k]) i(c); i(-1); }
            for (int k = 0; k < SecGuns.Length; k++) i(secJoined[k] ? 1 : 0);
            i(patrolOrigin.X); i(patrolOrigin.Y); i(patrolReturning ? 1 : 0);
            var so = new List<string>(standOverflow.Keys); so.Sort(StringComparer.Ordinal);
            foreach (var k in so) { foreach (var c in k) i(c); i(standOverflow[k]); }
        }

        static bool IsRival(string id) => id.StartsWith("rival-", StringComparison.Ordinal);
        bool IsHolder(Hostile h) => !IsRival(h.Id) || h.Blocker; // police and the response unit hold their stand (Pulse §3.2); a blocker its lane point (brief 018 §1)
        Pt Car => S.At(S.GetawayCar);

        // ---------------------------------------------------------------- moving a body

        void MoveTo(Hostile h, Pt to)
        {
            var from = h.Pos(Tick);
            var a = S.Grid.NearestFree(from) ?? from; var b = S.Grid.NearestFree(to) ?? to;
            var route = S.Grid.Route(a, b);
            if (route == null || route.Length < 2) { h.At = from; h.Run = null; return; }
            h.Run = new Path(route); h.RunStart = Tick; h.At = h.Run.End;
            if (h.Run.Length == 0) { h.Run = null; }
        }
        void Stop(Hostile h) { h.At = h.Pos(Tick); h.Run = null; }

        void TakeCover(Gun g, CoverPoint c) { ReleaseCover(g); coverTaken[c.Id] = g.Id; g.Cover = c.Id; g.UnprotSince = -1; Note("ai.cover", $"{g.Id} takes cover at {c.Id} ({c.Kind} {c.Of}, q {c.Q})."); }
        void ReleaseCover(Gun g) { if (g.Cover.Length > 0 && coverTaken.TryGetValue(g.Cover, out var who) && who == g.Id) coverTaken.Remove(g.Cover); g.Cover = ""; }
        CoverPoint? CoverById(string id) { foreach (var c in S.Cover) if (c.Id == id) return c; return null; }
        HashSet<string> Taken() => new HashSet<string>(coverTaken.Keys, StringComparer.Ordinal);
        bool Protected(Pt pos, Pt shooter) => S.Cover.Count > 0 && CoverRules.Modifier(S.Cover, pos, shooter, Tick / Hz, R.CoverSnapCm, R.PointBlankCm, R.CoverQFull, R.CoverQPartial, R.ModCover, R.ModCoverPartial) < 1000;
        CoverPoint? SelectCover(Pt me, Pt objective, Pt? foe, int seekCm) =>
            S.Cover.Count == 0 ? null : CoverRules.Select(S.Cover, me, objective, foe, Taken(), seekCm, Tick / Hz, R.PointBlankCm, R.CoverQPartial, R.CoverRetreatCm, R.CoverStepCloserCm);

        /// <summary>Where an advancer without cover halts: the first point of its route within ai.stopReach of its weapon's effective reach of
        /// the target (Pulse §2.1), or where it stands if it is already that close.</summary>
        Pt StopPoint(Pt from, Pt target, int effCm)
        {
            long stop = (long)effCm * R.StopReachPerMille / 1000;
            if (G.D2(from, target) <= stop * stop) return from;
            var a = S.Grid.NearestFree(from) ?? from; var b = S.Grid.NearestFree(target) ?? target;
            var route = S.Grid.Route(a, b); if (route == null) return from;
            var p = new Path(route);
            for (long mm = 0; mm <= p.Length; mm += 500) { var q = p.At(mm); if (G.D2(q, target) <= stop * stop) return q; } // every 50 cm (Path is in mm)
            return p.End;
        }

        // ---------------------------------------------------------------- foes and targets

        /// <summary>The foes a body may shoot: in its weapon's effective reach, on a clear line its `sees` allows. Before the final fight only an
        /// operative with a weapon out, who has fired, or who holds Vale; in it every operative (Pulse §2.1) and, for the rivals, the guard ally.</summary>
        List<(string id, Pt at)> FoesInReach(string id, Gun g, Pt pos, Func<Pt, bool> sees, bool anyOp)
        {
            var l = new List<(string, Pt)>(); long eff = (long)g.W!.EffCm * g.W.EffCm;
            foreach (var op in Ops)
            {
                if (op.Down || op.Inside) continue;
                bool foe = anyOp || op.Gun.Drawn || op.Gun.Fired || (op.Id == OpId.Enforcer && Vale == ValeAt.WithEnforcer) || markedFoes.Contains(Sim.Op.Name(op.Id)); // brief 013: security saw them do violence
                if (!foe || G.D2(pos, op.Pos) > eff || !sees(op.Pos)) continue;
                l.Add((Sim.Op.Name(op.Id), op.Pos));
            }
            if (anyOp && IsRival(id) && GuardAlly && !GuardDown) { var ga = PosOf("guard"); if (ga.HasValue && G.D2(pos, ga.Value) <= eff && sees(ga.Value)) l.Add(("guard", ga.Value)); }
            return l;
        }

        /// <summary>Pulse §2.2: class 1 the foe that fired at this body within weapons.lineLapse, 2 the operative holding Vale, 3 the nearest with
        /// a weapon drawn, 4 the nearest; ties on distance, then id. The body keeps its target until it is down or out of the list, unless a
        /// foe of a better class appears.</summary>
        string ChooseTarget(string id, Gun g, Pt pos, List<(string id, Pt at)> foes, bool ally = false)
        {
            if (foes.Count == 0) return "";
            int Class(string f, Pt at)
            {
                if (g.ShotBy == f && g.ShotByTick >= 0 && Tick - g.ShotByTick <= T(R.LineLapseS)) return 1;
                if (ally) return 3;
                if (f == "enforcer" && Vale == ValeAt.WithEnforcer) return 2;
                var fg = GunOf(f); return fg != null && fg.Drawn ? 3 : 4;
            }
            string best = ""; int bc = 9; long bd = long.MaxValue;
            Pt? enf = ally && !Enforcer.Inside ? Enforcer.Pos : (Pt?)null;
            foreach (var (f, at) in foes)
            {
                int c = Class(f, at);
                if (ally && c == 3 && enf.HasValue) c = 2; // the guard ally's class 2: the rival nearest the Enforcer (distance below is to him)
                long d = ally && c == 2 ? G.D2(enf!.Value, at) : G.D2(pos, at);
                if (c < bc || (c == bc && (d < bd || (d == bd && string.CompareOrdinal(f, best) < 0)))) { best = f; bc = c; bd = d; }
            }
            foreach (var (f, at) in foes)
                if (f == g.Target)
                {
                    int cur = Class(f, at); if (ally && cur == 3 && enf.HasValue) cur = 2;
                    if (bc >= cur) { g.Class = cur; return f; } // committed: only a better class replaces it
                }
            g.Class = bc; return best;
        }

        /// <summary>Aim with a warm reacquire (Pulse §2.1 hold): a target lost and found again within ai.reacquire is shot at once.</summary>
        void AimAt(Gun g, string t, bool react)
        {
            if (g.Target == t) return;
            if (t == g.LostTarget && g.LostTick >= 0 && Tick - g.LostTick <= T(R.ReacquireS)) { g.Target = t; g.NextShot = Math.Max(g.NextShot, Tick); return; }
            Aim(g, t, react);
        }
        void LoseTarget(Gun g) { if (g.Target.Length > 0) { g.LostTarget = g.Target; g.LostTick = Tick; } g.Target = ""; }

        // ---------------------------------------------------------------- the bodies

        void CityBody(string id)
        {
            var h = HostileOf(id);
            if (h != null) { FightBody(h); return; }
            int k = SecIndex(id);
            if (k >= 0) { if (!SecGuns[k].Down) PreFight(id, SecGuns[k], SecOfficerPose(k)?.pos, p => SecOfficerWatching(k, p, false)); return; } // its own aim ignores people (Pulse §1.6)
            switch (id)
            {
                case "guard":
                    if (!GuardEngaged || GuardDown) return;
                    PreFight("guard", GuardGun, PosOf("guard"), p => GuardWatching(p, false));
                    if (GuardGun.NoFoeSince >= 0 && Tick - GuardGun.NoFoeSince >= T(R.GuardReturnS)) { GuardEngaged = false; GuardGun.NoFoeSince = -1; Note("guard.stands-down", "No foe in reach: the guard stands down."); }
                    return;
                case "patrol":
                    if (!PatrolChasing || PatrolDown || PatrolAwayUntil > Tick) return;
                    PreFight("patrol", PatrolGun, PosOf("patrol"), p => PatrolWatching(p, false));
                    if (!patrolReturning && PatrolGun.NoFoeSince >= 0 && Tick - PatrolGun.NoFoeSince >= T(R.PatrolResumeS)) { patrolReturning = true; Note("patrol.resumes", "No foe in reach: the patrol goes back to its sweep."); }
                    return;
                case "rivals":
                    if (RivalsDrawn && RivalsPresent) PreFight("rivals", RivalsGun, PosOf("rivals"), RivalsWatching);
                    return;
            }
        }

        /// <summary>A body before the final fight (the guard engaging, the patrol, the response unit en route, the rival crew drawn by gunfire):
        /// it shoots a foe in its weapon's effective reach that it sees, by class; a first sight costs react (Pulse §3.3, §3.5, §3.6).</summary>
        void PreFight(string id, Gun g, Pt? posN, Func<Pt, bool> sees)
        {
            if (g.Down || g.W == null || !posN.HasValue) { LoseTarget(g); return; }
            var pos = posN.Value;
            var foes = FoesInReach(id, g, pos, sees, false);
            string t = ChooseTarget(id, g, pos, foes);
            if (t.Length == 0) { LoseTarget(g); if (g.NoFoeSince < 0) g.NoFoeSince = Tick; return; }
            g.NoFoeSince = -1;
            AimAt(g, t, true);
            if (Tick >= g.NextShot) { var at = PosOf(t)!.Value; Shoot(id, g, pos, t, at, Dist(pos, at), Moving(id), false); }
        }

        /// <summary>A final-fight body (rivals, officers, the response unit once joined): one transition a tick, then its action.</summary>
        void FightBody(Hostile h)
        {
            var g = h.Gun;
            if (g.Down) { ReleaseCover(g); return; }
            if (!h.Present || g.St == "gone") return;
            var pos = h.Pos(Tick); var w = g.W!;
            Func<Pt, bool> sees = p => Sees(pos, p);
            var foes = g.St == "break" ? new List<(string, Pt)>() : FoesInReach(h.Id, g, pos, sees, true);
            bool moving = h.Moving(Tick);
            switch (g.St) // one transition a tick (Pulse §1.4)
            {
                case "alerted":
                    if (Tick >= g.Until)
                    {
                        if (foes.Count > 0) { g.St = "engage"; var t0 = ChooseTarget(h.Id, g, pos, foes); g.Target = t0; g.Acc = R.AccStart; g.NextShot = Math.Max(g.NextShot, Tick); } // the wait was the aim
                        else { g.St = "advance"; Advance(h); }
                    }
                    break;
                case "advance":
                    if (foes.Count > 0) { if (!h.Blocker) Stop(h); g.St = "engage"; moving = h.Moving(Tick); } // a blocker keeps walking to the road (brief 018 §1)
                    else if (!moving) g.St = "hold";
                    break;
                case "engage":
                    if (foes.Count == 0)
                    {
                        if (g.NoFoeSince < 0) g.NoFoeSince = Tick;
                        else if (Tick - g.NoFoeSince >= T(R.EngageLapseS))
                        {
                            g.NoFoeSince = -1; LoseTarget(g);
                            if (IsHolder(h) && pos == h.Home) g.St = "hold"; else { g.St = "advance"; Advance(h); }
                        }
                    }
                    else g.NoFoeSince = -1;
                    break;
                case "hold":
                    if (foes.Count > 0) g.St = "engage";
                    else if (IsHolder(h) && pos != h.Home && !moving) { g.St = "advance"; Advance(h); }
                    break;
                case "break":
                    if (G.Within(pos, S.Stand(S.RivalsPark), R.RivalGoneCm) || !moving) { g.St = "gone"; h.Present = false; Note("ai.gone", $"{h.Id} is gone."); }
                    return;
            }
            if (g.St != "engage" || foes.Count == 0) { if (g.St != "engage") LoseTarget(g); return; }
            if (moving) return; // stepping to cover: fires nothing (run or shoot)
            string t = ChooseTarget(h.Id, g, pos, foes);
            var at = PosOf(t)!.Value;
            // cover (Pulse §2.3): leave a point unprotected for cover.leave; a rival steps to a point that shields it, once each cover.stepGap
            bool prot = Protected(pos, at);
            if (g.Cover.Length > 0)
            {
                var c = CoverById(g.Cover);
                if (c == null || !c.Present(Tick / Hz)) ReleaseCover(g);
                else if (prot) g.UnprotSince = -1;
                else if (g.UnprotSince < 0) g.UnprotSince = Tick;
                else if (Tick - g.UnprotSince >= T(R.CoverLeaveS)) ReleaseCover(g);
            }
            if (!prot && IsRival(h.Id) && !h.Blocker && Tick - g.StepAt >= T(R.CoverStepGapS))
            {
                var c = SelectCover(pos, Car, at, R.SeekRivalCm);
                if (c != null) { g.StepAt = Tick; TakeCover(g, c); MoveTo(h, c.At); if (h.Moving(Tick)) return; }
            }
            AimAt(g, t, false);
            if (Tick >= g.NextShot) Shoot(h.Id, g, pos, t, at, Dist(pos, at), false, false);
        }

        /// <summary>Where an advancer goes (Pulse §3): police and the response unit to their stand; a rival to the cover the data give with the
        /// Enforcer (or the car) as its foe, within ai.seek.rival, else to its stop point short of the car.</summary>
        void Advance(Hostile h)
        {
            var g = h.Gun; var pos = h.Pos(Tick);
            if (IsHolder(h)) { MoveTo(h, h.Home); return; }
            Pt foe = !Enforcer.Inside && !Enforcer.Down ? Enforcer.Pos : Car;
            var c = SelectCover(pos, Car, foe, R.SeekRivalCm);
            if (c != null) { TakeCover(g, c); MoveTo(h, c.At); return; }
            MoveTo(h, StopPoint(pos, Car, g.W!.EffCm));
        }

        /// <summary>The guard as the cell's ally (Pulse §3.4): he runs to his post (or the cover the data give within ai.seek.ally of it) and
        /// shoots, by his own classes: a rival that fired at him, the rival nearest the Enforcer, the nearest.</summary>
        void AllyBody()
        {
            var g = GuardGun; if (GuardDown) return;
            var pos = PosOf("guard"); if (!pos.HasValue) return;
            if (GuardAllyMoving) return; // running in: fires nothing
            var foes = new List<(string, Pt)>(); long eff = (long)g.W!.EffCm * g.W.EffCm;
            foreach (var h in Hostiles)
            {
                if (!IsRival(h.Id) || !h.Present || h.Down || h.Gun.St == "break" || h.Gun.St == "gone") continue;
                var at = h.Pos(Tick); if (G.D2(pos.Value, at) <= eff && Sees(pos.Value, at)) foes.Add((h.Id, at));
            }
            string t = ChooseTarget("guard", g, pos.Value, foes, ally: true);
            if (t.Length == 0) { LoseTarget(g); return; }
            AimAt(g, t, false);
            var tp = PosOf(t)!.Value;
            if (Tick >= g.NextShot) Shoot("guard", g, pos.Value, t, tp, Dist(pos.Value, tp), false, false);
        }

        /// <summary>The guard ally's post: the cover the data give within ai.seek.ally of guard-ally, else the post itself.</summary>
        Pt AllyStop()
        {
            var post = S.Stand(S.FightGuard);
            var c = SelectCover(post, Car, null, R.SeekAllyCm);
            if (c == null) return post;
            TakeCover(GuardGun, c); return c.At;
        }

        /// <summary>Rivals break (Pulse §3.1): the tick a rival goes down, if more than half the crew is down, every rival still up runs for its car.</summary>
        void RivalDown()
        {
            int n = 0, down = 0;
            foreach (var h in Hostiles) if (IsRival(h.Id)) { n++; if (h.Down) down++; }
            if (down * 2 <= n) return;
            bool any = false;
            foreach (var h in Hostiles)
            {
                if (!IsRival(h.Id) || h.Down || h.Gun.St == "break" || h.Gun.St == "gone") continue;
                if (!h.Present) { h.Gun.St = "gone"; continue; } // still lying in wait: it never comes
                ReleaseCover(h.Gun); LoseTarget(h.Gun); h.Gun.St = "break"; h.Speed = rivSpeed; MoveTo(h, S.Stand(S.RivalsPark)); any = true;
            }
            if (any) { FightWhy.Add("rivals-break"); Note("ai.break", "More than half the crew is down: the rivals break for their car."); }
        }

        /// <summary>The response unit joins a loud final fight (Pulse §3.3): at the fight's start, or its arrival if later, each officer still
        /// up runs (no alert delay) to the nearest police stand; a stand taken sends it to the nearest free cover within ai.seek.police of the
        /// stand, else to a slot ai.overflow beside it, across the line to the car, alternating sides.</summary>
        void JoinResponse()
        {
            if (FightBranch != "loud" || Tick < SecurityArrives) return;
            for (int k = 0; k < SecGuns.Length; k++)
            {
                if (secJoined[k] || SecGuns[k].Down) continue;
                var pose = SecOfficerPose(k); if (!pose.HasValue) continue;
                var from = pose.Value.pos;
                string stand = ""; long bd = long.MaxValue;
                foreach (var st in S.FightPolice) { long d = G.D2(from, S.Stand(st)); if (d < bd || (d == bd && string.CompareOrdinal(st, stand) < 0)) { bd = d; stand = st; } }
                var sp = S.Stand(stand);
                bool taken = false;
                foreach (var o in Hostiles) if (!o.Down && o.Home == sp) taken = true;
                standOverflow.TryGetValue(stand, out int overflow);
                Pt home = sp; string cov = "";
                if (taken)
                {
                    CoverPoint? best = null; long cd = long.MaxValue;
                    foreach (var c in S.Cover)
                    {
                        if (coverTaken.ContainsKey(c.Id) || c.Q < R.CoverQPartial || !c.Present(Tick / Hz)) continue;
                        long d = G.D2(sp, c.At); if (d > (long)R.SeekPoliceCm * R.SeekPoliceCm) continue;
                        if (d < cd || (d == cd && best != null && string.CompareOrdinal(c.Id, best.Id) < 0)) { cd = d; best = c; }
                    }
                    if (best != null) { home = best.At; cov = best.Id; }
                    else
                    {
                        long vx = Car.X - sp.X, vy = Car.Y - sp.Y, len = Math.Max(1, G.Isqrt(vx * vx + vy * vy)); int side = overflow % 2 == 0 ? 1 : -1; int step = 1 + overflow / 2;
                        var slot = new Pt(sp.X + (int)(-vy * R.OverflowCm * step * side / len), sp.Y + (int)(vx * R.OverflowCm * step * side / len));
                        home = S.Grid.NearestFree(slot) ?? sp; standOverflow[stand] = overflow + 1;
                    }
                }
                var gun = SecGuns[k]; gun.Engaged = true; gun.St = "advance"; LoseTarget(gun);
                var h = new Hostile { Id = gun.Id, At = from, Speed = secSpeed, Present = true, Gun = gun, Home = home };
                Hostiles.Add(h); secJoined[k] = true;
                if (cov.Length > 0) TakeCover(gun, CoverById(cov)!);
                MoveTo(h, home);
                Note("ai.join", $"{gun.Id} of the response unit joins the fight at {(taken ? (cov.Length > 0 ? cov : "a slot beside " + stand) : stand)}.");
            }
        }
    }
}

sim/Suborned.Sim/GameCancel.cs.text:
// What an operative is doing, and stopping it (Sky 2026-10-15 playtest: "there's nothing showing me what the cell player is doing when
// they're busy, nor is there a way to cancel their action"). Activity(op) is the HUD's read, every tick, and changes nothing. The cancel
// order stops the activity it shows; what that costs or keeps is the rulebook's `cancel` section.
using System;

namespace Suborned.Sim
{
    /// <summary>One operative's current activity, as the HUD shows it.</summary>
    public sealed class Activity
    {
        public string Op = "";
        public string Verb = "";        // move, watch, listen, turn, loop, reroute, mislead, enter, take, carry, fire, draw, holster; "" idle
        public string Target = "";      // the role, place, camera or operative the verb is on ("" if none)
        public string Phase = "idle";   // idle, walking, running, acting, holding, firing, drawing, down
        public int Progress;            // per mille, 0..1000 (integer state: 1000 = done); 0 for an open-ended activity (holding, firing)
        public int TicksLeft;           // ticks until it lands or arrives; for firing, until the next shot; -1 if open-ended
        public string OnDone = "";      // what happens when it lands (an outcome id or a short line), "?" when the card shows "?"
        public string Queued = "";      // the engine keeps no queue: always "" (a queue in the host is the host's to cancel)
        public bool CanCancel;          // whether a cancel order is taken now
        public string CancelCost = "";  // the rulebook cancel line that applies (stop, lost, aborted, ends, staff-report, …) or why not
        public string CancelText = "";  // that consequence in words
    }

    public sealed partial class Game
    {
        /// <summary>Every operative's activity now (scout, fixer, tech, enforcer).</summary>
        public Activity[] Activities() { var a = new Activity[4]; for (int i = 0; i < 4; i++) a[i] = ActivityOf((OpId)i); return a; }

        /// <summary>One operative's activity now: an act in progress first, then a walk or run, then firing, then a draw, then a loop held,
        /// then a downed operative carried; else idle. The cancel order stops exactly this one. Pure: changes nothing.</summary>
        public Activity ActivityOf(OpId id)
        {
            var op = OpOf(id); var g = op.Gun;
            var a = new Activity { Op = Sim.Op.Name(id) };
            if (op.Down) { a.Phase = "down"; a.CancelCost = "down"; a.CancelText = "a downed operative takes no orders"; return a; }
            if (op.Busy != null)
            {
                var o = op.Busy; a.Verb = o.Do; a.Target = o.Target; a.Phase = "acting";
                int span = Math.Max(1, op.BusyEnd - op.BusyStart);
                a.TicksLeft = Math.Max(0, op.BusyEnd - Tick); a.Progress = (int)Math.Min(1000L, (long)(Tick - op.BusyStart) * 1000 / span);
                a.OnDone = OnDone(op, o);
                a.CanCancel = true; (a.CancelCost, a.CancelText) = CancelLine(op, o.Do);
                if (o.Do == "enter" && o.How == "out") { a.CanCancel = false; a.CancelCost = "nothing"; a.CancelText = "both doors are held: he waits inside until one is free"; } // a cancelled Enter, waiting
                return a;
            }
            if (op.InCar) // brief 018: boarded; a move steps out (an order, not a cancel)
            {
                a.Verb = "board"; a.Target = "car"; a.Phase = "holding"; a.TicksLeft = -1; a.OnDone = "leaves with the car on Go";
                a.CanCancel = false; a.CancelCost = "nothing"; a.CancelText = "in the car: a move steps out";
                return a;
            }
            if (op.Walk != null)
            {
                a.Verb = "move"; a.Phase = op.Running ? "running" : "walking"; a.Target = $"{op.Walk.End.X},{op.Walk.End.Y}";
                int speed = op.WalkSpeed > 0 ? op.WalkSpeed : opSpeed; long left = op.Walk.Length - op.WalkMm;
                a.TicksLeft = (int)((left + speed - 1) / speed); a.Progress = op.Walk.Length == 0 ? 1000 : (int)(op.WalkMm * 1000 / op.Walk.Length);
                a.OnDone = "arrives";
                a.CanCancel = true; a.CancelCost = "stop"; a.CancelText = "stops where they stand";
                if (g.Order.Length > 0) a.OnDone = $"arrives (firing on {g.Order} as they walk)";
                return a;
            }
            if (g.Order.Length > 0)
            {
                a.Verb = "fire"; a.Target = g.Order; a.Phase = "firing"; a.Progress = 0;
                a.TicksLeft = Math.Max(0, Math.Max(g.NextShot, g.DrawReady) - Tick); a.OnDone = $"{g.Order} down";
                a.CanCancel = true; a.CancelCost = "cease"; a.CancelText = "ceases fire, the weapon stays drawn";
                return a;
            }
            if (g.Drawn && g.HolsterAt < 0 && Tick < g.DrawReady)
            {
                a.Verb = "draw"; a.Phase = "drawing"; a.TicksLeft = g.DrawReady - Tick;
                a.Progress = (int)Math.Min(1000L, (long)(Tick - g.DrawTick) * 1000 / Math.Max(1, g.DrawReady - g.DrawTick)); a.OnDone = "weapon drawn";
                a.CanCancel = true; a.CancelCost = "holster"; a.CancelText = "the weapon goes back (a draw already seen stays seen)";
                return a;
            }
            if (g.HolsterAt >= 0) { a.Verb = "holster"; a.Phase = "acting"; a.TicksLeft = Math.Max(0, g.HolsterAt - Tick); a.OnDone = "weapon away"; a.CancelCost = "none"; a.CancelText = "holstering finishes in a moment"; return a; }
            if (id == OpId.Tech && LoopOn)
            {
                a.Verb = "loop"; a.Target = LoopCam; a.Phase = "holding"; a.TicksLeft = -1; a.OnDone = "holds while the Tech stays at the cabinet";
                a.CanCancel = true; a.CancelCost = "ends"; a.CancelText = "the loop ends and the camera comes back";
                return a;
            }
            if (op.CarryBody.Length > 0) // brief 013: a body carried
            {
                a.Verb = "carry"; a.Target = op.CarryBody; a.Phase = "holding"; a.TicksLeft = -1; a.OnDone = "a stash hides it; open ground does not";
                a.CanCancel = true; a.CancelCost = "put-down"; a.CancelText = "the body is laid down here";
                return a;
            }
            if (op.Carrying.HasValue)
            {
                a.Verb = "carry"; a.Target = Sim.Op.Name(op.Carrying.Value); a.Phase = "holding"; a.TicksLeft = -1; a.OnDone = "brought to the car, they escape";
                a.CanCancel = true; a.CancelCost = "put-down"; a.CancelText = $"the {a.Target} is laid down here";
                return a;
            }
            if (op.Driven) // brief 025 (EXPERIMENTAL): the host moves it; a release ends that, not a cancel
            {
                a.Verb = "drive"; a.Phase = op.Running ? "running" : "driven"; a.TicksLeft = -1; a.OnDone = "the player moves them";
                a.CanCancel = false; a.CancelCost = "nothing"; a.CancelText = "under the player's control: release to stop driving";
                return a;
            }
            if (id == OpId.Enforcer && Vale == ValeAt.WithEnforcer)
            {
                a.Verb = "take"; a.Target = "councillor"; a.Phase = "holding"; a.TicksLeft = -1; a.OnDone = "Vale boards the getaway car with him; the win is the car leaving with Vale (Go)";
                a.CanCancel = false; a.CancelCost = "keeps-vale"; a.CancelText = "putting Vale down is no cancel";
                return a;
            }
            a.CancelCost = "nothing"; a.CancelText = "nothing to cancel";
            return a;
        }

        string OnDone(Op op, Order o)
        {
            switch (o.Do)
            {
                case "watch":
                    {
                        if (o.Target == "guard") return "learns the routine and his sight";
                        if (IsPersonRoleName(o.Target)) return "learns the routine";
                        if (IsContainer(o.Target)) return "learns when the round empties it";
                        var k = Known(o.Target);
                        bool routine = k != null && !k.Routine && k.RoutineNeedsS > 0 && k.WatchedS + R.SightWatchS >= k.RoutineNeedsS;
                        return routine ? "learns the sight and the routine" : "learns the sight";
                    }
                case "listen": return "learns the need and temperament";
                case "turn": return op.BusyQuote?.Outcome ?? "?";
                case "loop": return o.Target == "entrance" ? "the entrance camera loops" : $"the {o.Target} camera loops";
                case "reroute": return "the patrol leaves its sweep";
                case "mislead": return "the rivals follow a false tip";
                case "enter": return o.How == "out" ? "out by a door no unit holds, without Vale" : "out at the service lane with Vale";
                case "take": return "Vale is with the Enforcer";
                case "carry": return IsOpId(o.Target) ? $"lifts the {o.Target}" : $"lifts {o.Target}";
                case "takedown": return o.How == "kill" ? "dead" : "out";
                case "drop": return "laid down";
                case "stash": return "hidden";
                case "restrain": return "tied";
                case "board": return op.Carrying.HasValue ? $"in the car with the {Sim.Op.Name(op.Carrying.Value)}" : op.Id == OpId.Enforcer && Vale == ValeAt.WithEnforcer ? "in the car with Vale" : "in the car";
                case "move": return "steps out of the car"; // only a boarded operative's move is an action
                default: return "";
            }
        }

        (string cost, string text) CancelLine(Op op, string verb)
        {
            switch (verb)
            {
                case "watch": case "listen": return ("lost", "the time is spent; nothing is learned");
                case "turn": return R.CancelTurn == "aborted" ? ("aborted", $"the money held comes back; the {op.Busy!.Target} remembers an aborted approach and the Fixer's face") : ("lost", "the money held comes back; nothing is remembered");
                case "loop": case "reroute": case "mislead": case "carry": case "drop": case "stash": case "restrain": return ("lost", "the time is spent; nothing lands");
                case "takedown": return ("released", "the victim is let go: he saw it, and reports it as a woken victim would");
                case "enter": return R.CancelEnter == "staff-report" ? ("staff-report", $"back out {CancelledEnterOut()} without Vale; the staff report the intruder (a reported incident)") : ("quiet", $"back out {CancelledEnterOut()} without Vale");
                case "take": return R.CancelTake == "vale-reports" ? ("vale-reports", "Vale is let go at his car and reports the attempt (a reported incident)") : ("quiet", "Vale is let go at his car");
                default: return ("lost", "nothing lands");
            }
        }

        /// <summary>The cancel order (rulebook cancel): stops the activity ActivityOf shows, at the cost its line names.</summary>
        string Cancel(Op op)
        {
            var a = ActivityOf(op.Id); string name = Sim.Op.Name(op.Id);
            if (!a.CanCancel) return No(a.CancelCost == "down" ? "agent-down" : a.CancelCost == "keeps-vale" ? "keeps-vale" : a.CancelCost == "none" ? "holstering" : "nothing-to-cancel", a.CancelText);
            switch (a.Phase)
            {
                case "acting":
                    {
                        var o = op.Busy!; long paid = op.BusyPaid; RoundHoldCut(op);
                        op.Busy = null; op.BusyQuote = null; op.BusyPaid = 0; op.BusyEnd = Tick;
                        switch (o.Do)
                        {
                            case "turn":
                                Cash += paid; // held at the order, paid only in the outcome's charge (Redline E2): it comes back
                                if (R.CancelTurn == "aborted") Remember(PersonByRole(o.Target), "aborted", "fixer", false);
                                break;
                            case "enter":
                                EntryInProgress = false;
                                ExitWithoutVale(op, true);
                                if (R.CancelEnter == "staff-report") ReportBy("office-staff", S.Stand(S.GuardPost));
                                break;
                            case "takedown": // brief 013 (rulebook cancel.takedown released): let go, he saw the Enforcer and reports it
                                if (BodyById(o.Target) is Body tb && tb.Seizing) { var ta = ActOf(tb); ta.Aware = true; tb.Seizing = false; Remember(tb.P, "attacked-aware", "enforcer", false); Wake(tb, false); }
                                break;
                            case "take":
                                Vale = ValeAt.Pickup;
                                if (R.CancelTake == "vale-reports")
                                {
                                    // a Take already seen is an incident: Vale's own report is one more report of it (one incident counts once
                                    // toward Alert, brief 013 D), a victim's report as a woken victim's; unseen, it is the reported incident it was
                                    var ta = Acts.Find(x => x.Take);
                                    if (ta != null) LandAct(ta, "woken", "councillor", ValeP, ValePos() ?? op.Pos, SevOf("woken"), "");
                                    else ReportBy("councillor", ValePos() ?? op.Pos);
                                    Remember(ValeP, "aborted", "enforcer", false); // a lead for the investigators (Motive addendum Q4)
                                }
                                break;
                        }
                        Note("cancel." + o.Do, $"{name} stops: {o.Do}{(o.Target.Length > 0 ? " " + o.Target : "")} ({a.CancelCost}: {a.CancelText}).");
                        return "";
                    }
                case "walking": case "running":
                    op.Walk = null; op.WalkMm = 0; op.Running = false;
                    Note("cancel.move", $"{name} stops where they stand.");
                    return "";
                case "firing":
                    op.Gun.Order = ""; op.Gun.Force = false; op.Gun.Target = ""; op.Gun.LostAt = -1;
                    Note("cancel.fire", $"{name} ceases fire.");
                    return "";
                case "drawing":
                    op.Gun.Drawn = false; op.Gun.Target = "";
                    Note("cancel.draw", $"{name} puts the weapon back.");
                    return "";
                case "holding":
                    if (a.Verb == "loop") { LoopOn = false; Note("loop.ends", "The Tech lets the loop go. The camera feed returns."); return ""; }
                    if (a.Verb == "carry" && op.CarryBody.Length > 0) { PutDown(op, "cancel"); return ""; }
                    if (a.Verb == "carry") { var c = OpOf(op.Carrying!.Value); c.CarriedBy = null; op.Carrying = null; Note("cancel.carry", $"{name} lays the {Sim.Op.Name(c.Id)} down."); return ""; }
                    break;
            }
            return No("nothing-to-cancel", "nothing to cancel");
        }

        /// <summary>A cancelled Enter comes out without Vale (rev 4 R4.1, rulebook response: no exit through a held door; Aster 2026-10-16,
        /// brief 013 E3): by the public door unless a unit holds it, else by the service door; both held, he waits inside (an Enter that
        /// cannot be cancelled) and comes out the tick one is free. Re-tried each tick from Land.</summary>
        internal void ExitWithoutVale(Op op, bool first)
        {
            bool frontHeld = DoorHeld(EnterDoor), serviceHeld = DoorHeld(ExitDoor);
            if (frontHeld && serviceHeld)
            {
                op.Inside = true; op.Busy = new Order { Tick = Tick, Op = Sim.Op.Name(op.Id), Do = "enter", How = "out" }; op.BusyEnd = Tick + 1;
                if (first) { op.BusyStart = Tick; Note("cancel.enter-waits", "Both doors are held: the Enforcer waits inside, without Vale."); }
                return;
            }
            op.Inside = false; op.Pos = frontHeld ? S.Stand(S.ValeService) : S.Stand(S.GuardPost);
            if (frontHeld || !first) Note("cancel.enter-out", frontHeld ? "The public door is held: the Enforcer comes out at the service lane without Vale." : "A door is free: the Enforcer comes out at the public door without Vale.");
        }
        /// <summary>Where a cancelled Enter would come out now, in the engine's words (the cancel line).</summary>
        string CancelledEnterOut() => !DoorHeld(EnterDoor) ? "at the public door" : !DoorHeld(ExitDoor) ? "at the service lane (the public door is held)" : "when a door is free (both are held: he waits inside)";

        /// <summary>A reported incident by someone who is not a contact (rulebook alert.byIncident): the Office staff, or Vale.</summary>
        void ReportBy(string who, Pt at)
        {
            Reported++;
            var list = R.AlertByIncident;
            RaiseAlert(list[Math.Min(Reported, list.Length) - 1], "report:" + who);
            AddIncident("report", "report:" + who, at);
            Note("report", $"The {who.Replace('-', ' ')} report{(who == "councillor" ? "s" : "")} the attempt. Alert {Alert}.");
        }
    }
}

sim/Suborned.Sim/GameCombat.cs.text:
// Real-time shoot-outs and running (Sky 2026-10-15: approved Motive's briefs/011/motive-fights.md, all five answers as recommended).
// Every number is the rulebook's `weapons` section (and cell.runSpeed, cell.runAlert, cell.carry, alert.gunfire). The rules here:
//  · A shot's accuracy is its band's (point blank, effective, long) times the modifiers that apply (Rules.Accuracy). Hits are counted,
//    not rolled: each shooter keeps an integer accumulator on its target, starting at acc.start; each shot adds the accuracy, and at
//    1000 or more the shot hits and 1000 comes off. At 750 that is exactly three hits in four. No seed, no dice: same orders, same hits.
//  · The cost moves from the shot to the victim: +hit Trail per person hit (once), +down more when they go down; any gunfire raises
//    Alert to at least alert.gunfire; the final fight stays untraced (fight.traced). A drawn weapon seen by security raises Alert to
//    costs.drawSeenSecurity and that watcher engages; seen by people it is one witnessed incident.
//  · Running is noticed where an act would be: people remember where and when (and the face), security counts a found fault once a run.
//    Running is free once a fight is on, or the run is loud.
// Hostile behaviour beyond "shoot what you see, by priority" (advance to cover, rivals break, police hold) is Pulse's spec: not here yet.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>The going-loud card (motive-fights.md §2.6): what an order would set off, read before it is given. The engine never pauses.</summary>
    public sealed class LoudCard
    {
        public bool Loud;                 // the order would make the run loud (Alert ≥ 2 or a shot) when it isn't yet
        public string Why = "";           // draw-seen, fire, panic; or why not: already-loud, fight-on, unseen-draw, no-change
        public string Refused = "";       // the order would be refused, and why (the card shows nothing to commit)
        public int AlertTo;               // Alert after the order: 2, or 3 with civilians watching violence
        public int Civilians;             // civilians who would see it now
        public string ReportedBy = "";    // witness, seen, unseen, civilian, rivals-unseen, none
        public int PoliceInS = -1;        // the response unit's delay from now, -1 if none is called
        public int SecurityArrives = -1, Seal = -1; // ticks: the response unit on the street, the district sealed
        public int RivalsInS = -1;        // the rivals drawn by gunfire: seconds until they come (0: already here or coming)
        public bool PatrolBreaks;         // the patrol is within patrol.breakTo and breaks its route
        public string FightAfter = "";    // the final fight's branch after this order ("loud"), "" if the fight is not to come
        public int Officers, ResponseOfficers; // the loud fight's officers from the north street, and the response unit's
        public bool GuardAllyLost, WarningLost; // the safe fight's ally and Inez's warning, lost
        public int TrailPerHit, TrailPerDown, HoldTicks; // the price per person, and the card's commit hold
        public int TrailPerShooting;      // +T once per shooting, hit or miss (Motive addendum Q1)
        public bool DownedCaptured;       // the loss line: anyone downed is captured unless carried (Motive addendum Q3)
    }

    /// <summary>The price chip for a move (motive-fights.md §1.2): walk time, run time, who would see the run now, and whether it can run.</summary>
    public sealed class MoveQuote
    {
        public int WalkS, RunS; public string RunRefused = "";
        public readonly List<string> RunSeenBy = new List<string>(); // watchers whose cone the route crosses now
        public int RunPeople;             // people within witness range of the route now ("~": people move)
        public int AlertIfRun;            // Alert after the run if security sees it
        public bool RunFree;              // a fight is on or the run is loud: nobody counts a runner
        /// <summary>What the chip shows for "seen by" along the route now (rulebook sight.unknown; Sky 2026-10-16): known watchers' true
        /// answer, "?" for an unknown watcher that could see it. RunSeenBy above is the engine's truth for every watcher: the HUD shows Seen.</summary>
        public SeenQuote Seen = new SeenQuote();
    }

    public sealed partial class Game
    {
        public Gun GuardGun = null!, PatrolGun = null!, RivalsGun = null!;
        public Gun[] SecGuns = Array.Empty<Gun>();
        readonly Dictionary<string, Gun> civGuns = new Dictionary<string, Gun>(StringComparer.Ordinal);
        public readonly List<string> Captured = new List<string>();
        readonly HashSet<string> drawSeen = new HashSet<string>(StringComparer.Ordinal);
        readonly HashSet<string> violenceBy = new HashSet<string>(StringComparer.Ordinal);
        readonly Dictionary<string, Incident> fireIncident = new Dictionary<string, Incident>(StringComparer.Ordinal);
        public bool CellFiredOn; // someone has fired on the cell this mission: a fight is on
        Incident? lastDrawIncident;

        Gun NewGun(string id, Weapon? w, bool trained, int health) => new Gun(id) { W = w, Trained = trained, Health = health, Max = health };

        static bool IsOpId(string id) => id == "scout" || id == "fixer" || id == "tech" || id == "enforcer";
        /// <summary>The simulated person a target id names, if they are a civilian (people.rules: not the city's security), cast or crowd, by
        /// role or id; null for an operative, the guard, the patrol, the rivals, an officer or a robot. One rule for every person (brief 013,
        /// Sky 2026-10-16: no named target list): a civilian is shot at only when forced (the Ctrl case).</summary>
        Person? CivilianOf(string id) => IsOpId(id) ? null : PersonById(id) is Person p && p.Civilian ? p : null;
        bool IsCivilian(string id) => CivilianOf(id) != null;
        bool IsFightHostile(string id) { foreach (var h in Hostiles) if (h.Id == id) return true; return false; }
        Hostile? HostileOf(string id) { foreach (var h in Hostiles) if (h.Id == id) return h; return null; }
        int SecIndex(string id) { for (int k = 0; k < SecGuns.Length; k++) if (SecGuns[k].Id == id) return k; return -1; }
        /// <summary>A person, not the patrol unit: violence on them seen by a civilian is §05's "violence seen by a civilian".</summary>
        bool IsPersonTarget(string id) => id != "patrol" && !IsOpId(id);

        /// <summary>A fight is on (motive-fights.md §2.4 panic, §1.1 running free): someone has fired on the cell, or the final fight is on.</summary>
        public bool FightOn => CellFiredOn || FightSprung != INF || FightBranch == "loud";
        bool RunFree(Op op) => FightOn || Alert >= 2 || Gunfire > 0 || UnderFire(op);
        bool UnderFire(Op op)
        {
            string id = Sim.Op.Name(op.Id);
            if (GuardGun.Target == id || PatrolGun.Target == id || RivalsGun.Target == id) return true;
            foreach (var g in SecGuns) if (g.Target == id) return true;
            foreach (var h in Hostiles) if (h.Gun.Target == id) return true;
            return false;
        }

        public Gun? GunOf(string id)
        {
            if (IsOpId(id)) return OpOf(Sim.Op.Parse(id)).Gun;
            switch (id) { case "guard": return GuardGun; case "patrol": return PatrolGun; case "rivals": return RivalsGun; }
            if (civGuns.TryGetValue(id, out var c)) return c;
            int k = SecIndex(id); if (k >= 0) return SecGuns[k];
            if (UnitOf(id) is Unit u) return u.Gun;
            var h = HostileOf(id); if (h != null) return h.Gun;
            if (CivilianOf(id) is Person p && WalkerOf(p) != null) { var g = NewGun(p.Id, null, false, R.HealthCivilian); civGuns[p.Id] = g; extraCivGuns.Add(p.Id); return g; } // a person of the crowd, the first time a shot names them
            return null;
        }

        /// <summary>Where a shooter or target stands now, or null when it is not out on the street to be shot at.</summary>
        public Pt? PosOf(string id)
        {
            if (IsOpId(id)) { var op = OpOf(Sim.Op.Parse(id)); return op.Inside ? (Pt?)null : op.Pos; }
            switch (id)
            {
                case "guard": return GuardDown ? null : GuardPose()?.pos;
                case "patrol": return PatrolDown ? null : PatrolPose()?.pos;
                case "rivals": return RivalsPresent ? RivalsPose()?.pos : null;
                case "waitress": case "driver": case "councillor": return PersonPos(PersonByRole(id));
            }
            int k = SecIndex(id); if (k >= 0) return SecOfficerPose(k)?.pos;
            if (UnitOf(id) is Unit u) return UnitPose(u)?.pos;
            var h = HostileOf(id); if (h != null) return h.Present && !h.Down ? h.Pos(Tick) : (Pt?)null;
            return CivilianOf(id) is Person p ? PosOfPerson(p) : null;
        }

        bool Moving(string id)
        {
            if (IsOpId(id)) { var mo = OpOf(Sim.Op.Parse(id)); return mo.Walk != null || mo.DriveMoved; } // brief 025: a driven agent that moved this tick moves
            switch (id)
            {
                case "guard": { if (GuardAlly) return GuardAllyMoving; var g = GuardPose(); return g.HasValue && (g.Value.phase == "walking to café" || g.Value.phase == "returning to door"); }
                case "patrol": return !PatrolDown && PatrolAwayUntil <= Tick; // sweeping or chasing, it is never still
                case "rivals":
                    {
                        if (!RivalsDrawn || !RivalsPresent) return false;
                        var a = RivalsPose(); if (!a.HasValue) return false;
                        var path = RivalsDelayedUntil > RivalsDrawnTick ? rivalsRestartPath : rivalsPath;
                        return path != null && a.Value.pos != path.End;
                    }
            }
            int k = SecIndex(id);
            if (k >= 0) { long mm = (long)(Tick - SecurityArrives) * secSpeed - k * SecFileMm; return mm < Math.Max(0, securityPath.Length - k * SecFileMm); }
            if (UnitOf(id) is Unit u) return u.St == "walk" || u.St == "back";
            return HostileOf(id)?.Moving(Tick) ?? false;
        }

        /// <summary>The cover modifier on a shot at `t` standing at `at` from a shooter at `from` (Pulse §2.3, rulebook ai.cover): standing
        /// still beside a cover point that shields it, past point blank: weapons.mod.cover for full cover, ai.cover.modPartial for partial.</summary>
        int CoverMod(string t, Pt at, Pt from)
        {
            if (IsOpId(t) && OpOf(Sim.Op.Parse(t)).InCar) return R.ModCover; // brief 018 §2: in the car, a target still beside cover
            if (S.Cover.Count == 0 || Moving(t)) return 1000;
            return CoverRules.Modifier(S.Cover, at, from, Tick / Hz, R.CoverSnapCm, R.PointBlankCm, R.CoverQFull, R.CoverQPartial, R.ModCover, R.ModCoverPartial);
        }

        static long Dist(Pt a, Pt b) => G.Isqrt(G.D2(a, b));
        /// <summary>Brief 018 (Sky 2026-10-18): the Enforcer walking Vale can't run or fire; once Vale is in the car he is any operative again.</summary>
        bool CarriesVale(Op op) => op.Id == OpId.Enforcer && (Vale == ValeAt.WithEnforcer || Vale == ValeAt.Taking);
        bool Ready(Gun g) => g.Drawn && g.HolsterAt < 0 && Tick >= g.DrawReady;

        // ---------------------------------------------------------------- the tick

        /// <summary>One tick of fighting (Pulse §1): the cell, then the guard as an ally, then security (by id: the response unit, the
        /// officers, an engaging guard, the patrol), then the rivals (by id). Every body decides from the start-of-tick state; the shots are
        /// applied together at the end (accumulators at the decision, then damage, then down).</summary>
        void Combat()
        {
            pending.Clear();
            foreach (var op in Ops) { var g = op.Gun; if (g.HolsterAt >= 0 && Tick >= g.HolsterAt) { g.Drawn = false; g.HolsterAt = -1; } }
            foreach (var op in Ops) CellShooter(op);
            if (GuardAlly && FightSprung != INF) AllyBody();
            var security = new List<string>();
            for (int k = 0; k < SecGuns.Length; k++) if (!IsFightHostile(SecGuns[k].Id)) security.Add(SecGuns[k].Id);
            foreach (var h in Hostiles) if (!h.Id.StartsWith("rival-", StringComparison.Ordinal)) security.Add(h.Id);
            if (!GuardAlly) security.Add("guard");
            security.Add("patrol");
            security.Sort(StringComparer.Ordinal);
            foreach (var id in security) CityBody(id);
            UnitsCombat(); // brief 013: the response's robots and police
            var rivals = new List<string> { "rivals" };
            foreach (var h in Hostiles) if (h.Id.StartsWith("rival-", StringComparison.Ordinal)) rivals.Add(h.Id);
            rivals.Sort(StringComparer.Ordinal);
            foreach (var id in rivals) CityBody(id);
            PatrolTracking = PatrolGun.Target.Length > 0 && !IsFightHostile("patrol");
            SecurityTracking = false; for (int k = 0; k < SecGuns.Length; k++) SecurityTracking |= SecGuns[k].Target.Length > 0;
            RivalsTracking = RivalsGun.Target.Length > 0;
            Resolve();
        }

        /// <summary>An operative shoots: its standing fire order, else what its stance allows. Not while running, carrying, inside or doing
        /// an action; a walking operative fires at the moving rate (motive-fights.md §1.1, §2.4).</summary>
        void CellShooter(Op op)
        {
            var g = op.Gun; string name = Sim.Op.Name(op.Id);
            if (g.Down || g.W == null || op.Inside || op.InCar || !g.Drawn) return; // in the car: no fire (brief 018 §2)
            if (g.Order.Length > 0)
            {
                var tg = GunOf(g.Order);
                if (tg == null || tg.Down || !PosOf(g.Order).HasValue)
                {
                    Note("fire.done", $"{name}: {g.Order} is {(tg != null && tg.Down ? "down" : "gone")}. The fire order ends.");
                    g.Order = ""; g.Force = false; g.Target = ""; g.LostAt = -1;
                }
                else if (FightOverTick != INF && IsFightHostile(g.Order)) // rulebook fight.over (Motive, brief 023): the final fight is over, the broken crew is no target
                {
                    Note("fire.done", $"{name}: the fight is over. The fire order on {g.Order} ends.");
                    g.Order = ""; g.Force = false; g.Target = ""; g.LostAt = -1;
                }
            }
            if (op.Busy != null || op.Running || op.Carrying.HasValue || op.CarryBody.Length > 0 || CarriesVale(op) || !Ready(g)) return; // brief 018: walking Vale, the Enforcer doesn't fire
            string t = g.Order.Length > 0 ? g.Order : StanceTarget(op);
            if (t.Length == 0) { g.Target = ""; return; }
            var at = PosOf(t)!.Value; long d = Dist(op.Pos, at);
            if (d > g.W.MaxCm || !Sees(op.Pos, at))
            {
                if (t == g.Order)
                {
                    if (g.LostAt < 0) g.LostAt = Tick;
                    else if (Tick - g.LostAt >= T(R.LineLapseS)) { Note("fire.lapses", $"{name} loses the line on {t}. The fire order lapses."); g.Order = ""; g.Force = false; g.Target = ""; g.LostAt = -1; }
                }
                return;
            }
            g.LostAt = -1;
            Aim(g, t, false);
            if (Tick >= g.NextShot) Shoot(name, g, op.Pos, t, at, d, op.Walk != null || op.DriveMoved, op.Id == OpId.Enforcer && Vale == ValeAt.WithEnforcer);
        }

        /// <summary>Who an operative's stance fires at (motive-fights.md §2.4): hold, nobody; return, whoever fired on it; free, the nearest
        /// combatant. A combatant is a final-fight hostile, or a guard, patrol, officer or rival crew that has fired or aims at the cell;
        /// never a civilian, a contact or Vale, so a stance can never start a loud run by itself.</summary>
        string StanceTarget(Op op)
        {
            var g = op.Gun;
            if (g.Stance == "hold") return "";
            if (g.Stance == "return") return g.ShotBy.Length > 0 && Combatant(g.ShotBy) && InLine(op.Pos, g.ShotBy, g.W!.MaxCm) ? g.ShotBy : "";
            string best = ""; long bd = long.MaxValue;
            foreach (var id in CombatantIds())
            {
                if (!Combatant(id)) continue;
                var at = PosOf(id); if (!at.HasValue) continue;
                long d = G.D2(op.Pos, at.Value);
                if (d < bd && d <= (long)g.W!.MaxCm * g.W.MaxCm && Sees(op.Pos, at.Value)) { bd = d; best = id; }
            }
            return best;
        }
        bool InLine(Pt from, string id, int maxCm) { var at = PosOf(id); return at.HasValue && G.Within(from, at.Value, maxCm) && Sees(from, at.Value); }
        IEnumerable<string> CombatantIds()
        {
            yield return "guard"; yield return "patrol";
            foreach (var g in SecGuns) yield return g.Id;
            yield return "rivals";
            foreach (var h in Hostiles) yield return h.Id;
            foreach (var u in Units) if (!u.Legacy && !u.Patrol) yield return u.Id;
        }
        bool Combatant(string id)
        {
            var g = GunOf(id); if (g == null || g.Down || !PosOf(id).HasValue) return false;
            if (IsFightHostile(id)) { var h = HostileOf(id)!; return h.Present && h.Gun.St != "break" && h.Gun.St != "gone"; }
            if (id == "guard" && GuardAlly) return false;
            if (IsOpId(id) || IsCivilian(id)) return false;
            return IsOpId(g.Target) || g.Fired;
        }

        /// <summary>Take a target: a new one resets the accumulator to acc.start and waits aimNew, or react on a hostile's first sight.</summary>
        void Aim(Gun g, string t, bool react)
        {
            if (g.Target == t) return;
            g.Target = t; g.Acc = R.AccStart;
            g.NextShot = Math.Max(g.NextShot, Tick + (react && !g.Engaged ? T(R.ReactS) : R.AimNewTicks));
        }

        // ---------------------------------------------------------------- a shot

        sealed class PendingShot { public string By = "", T = ""; public Gun G = null!; public Pt At, From; public long D; public int Acc; public bool Hit; }
        readonly List<PendingShot> pending = new List<PendingShot>();

        /// <summary>A body fires: the accumulator moves now (it is the shooter's), the shot lands with the others at the end of the tick.</summary>
        void Shoot(string by, Gun g, Pt from, string t, Pt at, long d, bool moving, bool vale)
        {
            int acc = R.Accuracy(g.W!, d, moving, CoverMod(t, at, from), vale, !g.Trained);
            g.Acc += acc; bool hit = g.Acc >= 1000; if (hit) g.Acc -= 1000;
            g.NextShot = Tick + g.W!.Every; g.Fired = g.Engaged = true;
            pending.Add(new PendingShot { By = by, T = t, G = g, At = at, From = from, D = d, Acc = acc, Hit = hit });
        }

        PendingShot? resolving; // the shot being resolved: what a fail it causes names (FailCause.cs; output only)
        void Resolve()
        {
            foreach (var s in pending)
            {
                if (Over) return;
                resolving = s;
                var tg = GunOf(s.T)!;
                tg.ShotBy = s.By; tg.ShotByTick = Tick;
                shotsThisTick.Add(s.From); LastShotTick = Tick; lastShooter = s.From; // the crowd hears it (Pulse §4)
                RoundsEnd("gunfire"); // brief 022: any shot ends the round
                FightShot(s.By, s.T, s.From); // the public hears it: one fight, judged when it ends (fight.public)
                if (IsOpId(s.T)) CellFiredOn = true;
                Note(s.Hit ? "shot.hit" : "shot.miss", $"{s.By} fires on {s.T} at {s.D / 100} m ({s.Acc} ‰): {(s.Hit ? "hit" : "miss")}.");
                bool cell = IsOpId(s.By), untraced = cell && IsFightHostile(s.T) && !R.FightTraced;
                if (cell) CellGunfire(OpOf(Sim.Op.Parse(s.By)), s.T, s.At, untraced);
                else if (!IsFightHostile(s.By) && !(s.By == "guard" && GuardAlly)) RaiseAlert(R.GunfireAlert, "gunfire:" + s.By); // any gunfire (§05)
                if (Over) return;
                if (s.Hit && !tg.Down) Damage(s.T, tg, s.G.W!.Damage, s.By, cell, untraced);
            }
            resolving = null;
            pending.Clear();
        }

        /// <summary>What the cell's shot sets off. Untraced in the final fight (fight.traced off, Sky 2026-10-15): the shots are counted apart
        /// and only wake the patrol. Otherwise: a shot fired, Alert to alert.gunfire, one incident per target with everyone who saw it,
        /// violence seen by civilians, the rivals drawn, the patrol woken, and the response unit called by whoever reports it.</summary>
        void CellGunfire(Op op, string t, Pt at, bool untraced)
        {
            string name = Sim.Op.Name(op.Id);
            if (untraced) { FightShots++; WakePatrol(op.Pos, op.Id); return; }
            Gunfire++;
            var shot = new CauseOrigin { Tick = Tick, Report = "gunfire:" + t, Because = "gunfire", Reporter = Shooter(name, op.Pos, at), ScenePlaced = true, Scene = IsPersonTarget(t) ? at : op.Pos }; shot.Ops.Add(name); // output only (FailCause.cs)
            if (gunfireOrigin == null) gunfireOrigin = shot;
            shotNow = shot; RaiseAlert(R.GunfireAlert, "gunfire:" + t); shotNow = null;
            Person? victim = CivilianOf(t) ?? (t == "guard" ? GuardP : null);
            // one incident per target (rulebook alert: every shot of one fight with one target is one incident); later shots add new witnesses
            if (!fireIncident.TryGetValue(t, out var inc))
            {
                incidents.Add("fire:" + t);
                AddTrail(R.GunfireTrail, "gunfire:" + t); // a shooting is a case: once, at its first shot, hit or miss (Motive addendum Q1)
                inc = AddIncident(IsCivilian(t) ? "violence" : "gunfire", (IsCivilian(t) ? "violence:" : "gunfire:") + t, IsPersonTarget(t) ? at : op.Pos);
                fireIncident[t] = inc;
            }
            var seen = WitnessesWithPos(op.Pos, victim);
            if (IsPersonTarget(t)) foreach (var w in WitnessesWithPos(at, victim)) if (!seen.Exists(x => x.p == w.p)) seen.Add(w);
            foreach (var (p, wp) in seen)
            {
                if (inc.Witnesses.Exists(x => x.p == p)) continue;
                inc.Witnesses.Add((p, wp)); Remember(p, "saw-gunfire", name, true); // Pulse §4: a witness of a shot, before any startle
            }
            int civSees = 0; string firstCiv = "";
            if (IsPersonTarget(t))
                foreach (var c in WitnessesOf(at, victim))
                {
                    if (!c.Civilian) continue;
                    civSees++; if (firstCiv.Length == 0) firstCiv = Who(c);
                    if (!violenceBy.Add(t + "/" + c.Id)) continue;
                    ViolenceSeen(t, c, name);
                    if (c == Inez && !InezWitnessedShooting) { InezWitnessedShooting = true; Note("witness.waitress", $"Inez sees the {t} shot at near her café. She is now a witness."); }
                    else if (c != Inez) Note("witness.crowd", $"{c.Name} sees the {t} shot at.");
                }
            if (CivilianOf(t) is Person shotAt) CivilianShotAt(shotAt, op);
            DrawRivals(); WakePatrol(op.Pos, op.Id);
            var (delay, text, who) = Reporter(t, op.Pos, civSees > 0);
            if (delay >= 0)
            {
                var scene = IsPersonTarget(t) ? at : op.Pos; var by = who == "witness" ? (firstCiv.Length > 0 ? firstCiv : "heard") : who;
                CallSecurity(delay, text, scene, origin: () => OriginNow("gunfire:" + t, "response", by, scene, by == "heard" ? op.Pos : (Pt?)null, op.Pos, name));
            }
        }

        /// <summary>Who reports the cell's gunfire, and so how soon the response unit comes (rulebook security.response).</summary>
        // who: the reporter's id for the fail cause (FailCause.cs; "witness": the first civilian who saw it, "heard": nobody saw it)
        (int delay, string text, string who) Reporter(string t, Pt shooter, bool civSees)
        {
            if (IsCivilian(t)) return (R.RespCivilianS, t == "waitress" ? "Inez is shot at the café. Witnesses call security." : t == "driver" ? "The official driver is shot at. Security rushes to the pickup." : t == "councillor" ? "Shots at the councillor are reported." : "A shooting in the street is reported.", "witness");
            if (t == "patrol") return (R.RespSeenS, "Gunfire at the patrol is reported.", "patrol");
            if (t == "rivals") return CameraWatching("pickup", shooter) ? (R.RespSeenS, "The firefight with the rivals is reported.", "camera:pickup") : (R.RespRivalsUnseenS, "The firefight with the rivals is reported.", "heard");
            if (SecIndex(t) >= 0 || IsFightHostile(t) || UnitOf(t) != null) return (-1, "", "");
            if (civSees) return (R.RespWitnessS, InezWitnessedShooting ? "Inez reports the shooting." : "A witness reports the shooting.", "witness");
            bool guard = t == "guard" ? GuardWatching(shooter) : false;
            if (guard) return (R.RespSeenS, "The guard calls in the shooting.", "guard");
            if (PatrolWatching(shooter)) return (R.RespSeenS, "The patrol reports gunfire.", "patrol");
            if (CameraWatching("entrance", shooter)) return (R.RespSeenS, "The entrance camera reports gunfire.", "camera:entrance");
            foreach (var c in S.Cameras) if (c.World && CameraWatching(c.Id, shooter)) return (R.RespSeenS, "A street camera reports gunfire.", "camera:" + c.Id);
            return (R.RespUnseenS, "Shots are heard in the district.", "heard");
        }

        /// <summary>A civilian or a contact shot at (§05: violence → Alert 3 at once; rulebook traceable violence): the guard, away from his
        /// door, stops to search for the shooter.</summary>
        void CivilianShotAt(Person p, Op op)
        {
            string who = Who(p);
            RaiseAlert(R.ViolenceSeen, $"violence-seen:{who}");
            if (incidents.Add("seen:" + who)) { AddTrail(R.WitnessTrail, $"witnessed:violence:{who}"); MoveStanding(-R.StandingStep, $"violence-seen:{who}", "seen-violence", who); }
            var g = GuardPose();
            if (g.HasValue && g.Value.phase != "door" && !GuardHeld)
            {
                GuardHeld = true; heldPos = g.Value.pos; heldFacing = g.Value.facing; heldPhase = "searching for the shooter"; GuardAwayUntil = INF;
                if (GuardWatching(op.Pos)) GuardEngaged = true;
            }
        }

        // ---------------------------------------------------------------- a hit

        void Damage(string t, Gun tg, int dmg, string by, bool cell, bool untraced)
        {
            tg.Health = Math.Max(0, tg.Health - dmg);
            bool traced = cell && !untraced;
            if (traced && !tg.Hit) AddTrail(R.HitTrail, "hit:" + t);
            tg.Hit = true;
            bool down = tg.Health == 0;
            if (down && t != "rivals") { tg.Down = true; if (traced) AddTrail(R.DownTrail, "down:" + t); }
            if (IsOpId(t)) { OpHit(OpOf(Sim.Op.Parse(t)), down, by); return; }
            switch (t)
            {
                case "guard": GuardHit(down, by); return;
                case "patrol":
                    if (down) { patrolDownAt = PatrolPose()!.Value.pos; PatrolDown = true; PatrolChasing = false; Chain.Add("patrol-down"); Note("patrol.down", "The patrol goes down. Its distress signal is already out."); }
                    else Note("patrol.hit", $"The patrol is hit. {tg.Health} left.");
                    return;
                case "rivals":
                    if (down)
                    {
                        tg.Health = tg.Max; RivalsDelayedUntil = Tick + T(R.RivalsRetreatS); RivalsDelayMethod = "fire"; // running away isn't a drop (no Trail)
                        CrewBroken(); // fight.public: the crew broke in this fight
                        Chain.Add("rivals-driven-back"); Note("rivals.retreat", "The rivals retreat for now.");
                    }
                    else Note("rivals.hit", "The rival crew takes a hit.");
                    return;
                case "waitress": case "driver": case "councillor": CivilianHit(PersonByRole(t), down); return;
            }
            if (UnitOf(t) is Unit hu) { Note(down ? "response.down" : "response.hit", down ? $"{t} is down." : $"{t} is hit."); if (down) hu.St = "gone"; return; }
            if (CivilianOf(t) is Person cp) { CivilianHit(cp, down); return; }
            int k = SecIndex(t);
            if (k >= 0)
            {
                bool all = true; foreach (var s in SecGuns) if (!s.Down) all = false;
                if (all && !SecurityDown) { SecurityDown = true; Chain.Add("response-unit-down"); Note("security.down", "The response unit is down. The wider cordon is still closing."); }
                else Note(down ? "security.officer-down" : "security.hit", down ? $"{t} is down." : $"{t} is hit.");
                return;
            }
            var h = HostileOf(t);
            if (h != null)
            {
                string who = by == "enforcer" ? "The Enforcer" : by == "guard" ? "The guard" : "The " + by;
                if (down)
                {
                    if (by == "enforcer") DownedByEnforcer++; else if (by == "guard") DownedByGuard++; else DownedByCell++;
                    Note("fight.down", $"{who} drops {t}."); ReleaseCover(tg); Stop(h);
                    if (IsRival(t)) RivalDown();
                }
                else Note("fight.hit", $"{who} hits {t}.");
            }
        }

        void OpHit(Op op, bool down, string by)
        {
            string name = Sim.Op.Name(op.Id);
            if (FightBranch.Length > 0) FightHits++;
            Note(name + ".hit." + (IsFightHostile(by) ? "fight" : by), $"{by} hits the {name}. {op.Gun.Health} health left.");
            if (!down) return;
            if (op.Id == OpId.Enforcer && Vale != ValeAt.Car) // brief 018 §2: once Vale is in the car, the Enforcer is any operative
            {
                if (FightBranch == "safe" && Vale == ValeAt.WithEnforcer) Fail("rivals-reach-vale", "The Enforcer is down and the rival crew takes Vale off him.", () => ShotDown("downed-enforcer", "enforcer")); // the rivals' goal (Motive addendum Q7)
                else Fail("enforcer-down", "The Enforcer is down.", () => ShotDown("shot", "enforcer"));
                return;
            }
            if (op.Busy != null) { Cash += op.BusyPaid; op.Busy = null; op.BusyQuote = null; op.BusyPaid = 0; RoundHoldCut(op); } // an action cut short: the price comes back, as a refusal's does
            op.Walk = null; op.WalkMm = 0; op.Running = false; op.Gun.Order = ""; op.Gun.Target = "";
            if (op.Carrying.HasValue) { OpOf(op.Carrying.Value).CarriedBy = null; op.Carrying = null; }
            if (op.CarryBody.Length > 0) PutDown(op, name + " down");
            Note(name + ".down", op.InCar ? $"The {name} is down in the car." : $"The {name} is down. Carry them into the car, or they are captured.");
        }

        void GuardHit(bool down, string by)
        {
            if (down)
            {
                GuardDown = true; GuardP.Down = true; GuardEngaged = false; // his next check-in mark misses (brief 013: response.checkIn)
                bool rivals = IsFightHostile(by); // downed by the rivals in the safe fight: the post is still empty, but no act of the cell (Motive addendum Q6)
                Chain.Add(rivals ? "guard-down-by-rivals" : "guard-shot"); Note("guard.down", rivals ? "The rivals drop the guard. His missed check-in will still be noticed." : "The guard falls. His missed check-in will draw more attention.");
                return;
            }
            var pose = GuardPose()!.Value;
            if (pose.phase != "door" && !GuardHeld) { GuardHeld = true; heldPos = pose.pos; heldFacing = pose.facing; heldPhase = "wounded"; GuardAwayUntil = INF; }
            bool seen = IsOpId(by) && GuardWatching(OpOf(Sim.Op.Parse(by)).Pos);
            if (seen && !GuardAlly) GuardEngaged = true;
            Note("guard.hit", seen ? "The guard is hit but fires back." : "The guard is hit. He cannot see the shooter yet.");
        }

        void CivilianHit(Person p, bool down)
        {
            if (!down) { Note("civilian.hit", $"{p.Name} ({p.Role}) is hit."); return; }
            if (p == ValeP)
            {
                Vale = ValeAt.Dead; ValeP.Down = true;
                Fail("vale-dead", "Vale is dead. The live capture objective has failed.", () => ShotDown("shot", "councillor"));
                return;
            }
            if (p == Driver) carStoppedAt = CarPos();
            p.Down = true; p.Turned = false;
            if (WalkerOf(p) is Walker cw) { cw.St = ""; cw.Run = null; cw.Pace = 0; }
            Chain.Add(Who(p) + "-shot");
            Note("civilian.down", $"{p.Name} ({Who(p)}) is down.");
            if (p == Driver && Vale != ValeAt.Office) Fail("driver-shot", "The driver is shot during handover. Security pulls Vale away.", () => ShotDown("shot", "driver"));
        }

        // ---------------------------------------------------------------- what the city sees

        /// <summary>A drawn weapon is an act (motive-fights.md §2.3). Seen by security (the guard, the patrol, a live camera, the response unit):
        /// Alert to weapons.costs.drawSeenSecurity, the watcher engages and calls it in. Seen by people (civilians within witness range):
        /// one witnessed incident, Alert at least drawSeenPeople, and they remember the face. Once per draw each; not in the final fight.</summary>
        void DrawnSeen()
        {
            if (FightBranch.Length > 0) return; // the final fight is untraced (fight.traced)
            foreach (var op in Ops)
            {
                var g = op.Gun; if (!g.Drawn || g.Down || op.Inside) continue;
                string name = Sim.Op.Name(op.Id);
                foreach (var w in new List<string>(SecurityWatchers))
                    if (!drawSeen.Contains($"{w}/{name}/{g.DrawTick}") && WatcherSees(w, op.Pos)) { drawSeen.Add($"{w}/{name}/{g.DrawTick}"); SecuritySawDraw(w, op); if (Over) return; }
                string pk = $"people/{name}/{g.DrawTick}";
                if (drawSeen.Contains(pk)) continue;
                var ws = WitnessesWithPos(op.Pos, null).FindAll(x => x.p.Civilian);
                if (ws.Count == 0) continue;
                drawSeen.Add(pk);
                // drawings at one place and time are one incident (Motive addendum Q1): within weapons.costs.drawWindow and witness range of the last
                var same = lastDrawIncident != null && Tick - lastDrawIncident.Tick < T(R.DrawWindowS) && G.Within(lastDrawIncident.At, op.Pos, witnessRange);
                if (same) { foreach (var w in ws) if (!lastDrawIncident!.Witnesses.Exists(x => x.p == w.p)) lastDrawIncident.Witnesses.Add(w); }
                else
                {
                    lastDrawIncident = AddIncident("weapon-drawn", "weapon-drawn:" + name, op.Pos, ws);
                    AddTrail(R.WitnessTrail, $"witnessed:weapon-drawn:{name}"); MoveStanding(R.Traceable["weapon-drawn"] * R.StandingStep, "witnessed:weapon-drawn", "seen-weapon-drawn", "");
                }
                RaiseAlert(R.DrawSeenPeople, $"drawn-seen:people:{name}");
                foreach (var (p, _) in ws) Remember(p, "saw-weapon-drawn", name, true);
                Note("witness.weapon-drawn", $"{ws.Count} see the {name}'s weapon drawn.");
            }
        }
        static readonly string[] SecurityWatchersFixed = { "guard", "patrol", "camera:entrance", "camera:pickup", "security" };
        /// <summary>The city's eyes that call in what they see: the fixed five, then the response's robots and police (brief 013) by id.</summary>
        IEnumerable<string> SecurityWatchers { get { foreach (var w in SecurityWatchersFixed) yield return w; foreach (var c in S.Cameras) if (c.World) yield return "camera:" + c.Id; foreach (var u in Units) if (!u.Legacy && !u.Patrol && u.OnStreet(Tick) && !u.Gun.Down) yield return u.Id; } }
        bool WatcherSees(string w, Pt p) => w switch
        {
            "guard" => !GuardAlly && GuardWatching(p),
            "patrol" => PatrolWatching(p),
            "camera:entrance" => CameraWatching("entrance", p),
            "camera:pickup" => CameraWatching("pickup", p),
            "security" => SecurityWatching(p),
            _ => UnitOf(w) is Unit u ? UnitSees(u, p) : w.StartsWith("camera:", StringComparison.Ordinal) && CameraWatching(w.Substring(7), p),
        };
        string? SecurityWatcherOf(Pt p) { foreach (var w in SecurityWatchers) if (WatcherSees(w, p)) return w; return null; }

        void SecuritySawDraw(string w, Op op)
        {
            string name = Sim.Op.Name(op.Id);
            RaiseAlert(R.DrawSeenSecurity, $"drawn-seen:{w}:{name}");
            Note("drawn.seen", $"The {w.Replace("camera:", "")} {(w.StartsWith("camera", StringComparison.Ordinal) ? "camera shows" : "sees")} the {name}'s weapon drawn. Alert {Alert}.");
            switch (w)
            {
                case "guard":
                    if (GuardDown) return;
                    { var pose = GuardPose()!.Value; if (pose.phase != "door" && !GuardHeld) { GuardHeld = true; heldPos = pose.pos; heldFacing = pose.facing; heldPhase = "drawing on the cell"; GuardAwayUntil = INF; } }
                    GuardEngaged = true; Remember(GuardP, "saw-weapon-drawn", name, true);
                    CallSecurity(R.RespSeenS, "The guard calls in a drawn weapon.", origin: () => OriginNow("drawn-seen:" + name, "response", w, op.Pos, null, op.Pos, name));
                    return;
                case "patrol":
                    if (!PatrolChasing && !PatrolDown && PatrolAwayUntil <= Tick) { chasePos = PatrolPose()!.Value.pos; PatrolChasing = true; chaseOp = op.Id; patrolOrigin = op.Pos; patrolReturning = false; PatrolGun.NoFoeSince = -1; Note("patrol.breaks", "The patrol breaks its route and turns on the drawn weapon."); }
                    CallSecurity(R.RespSeenS, "The patrol reports a drawn weapon.", origin: () => OriginNow("drawn-seen:" + name, "response", w, op.Pos, null, op.Pos, name));
                    return;
                case "camera:entrance": case "camera:pickup":
                    CallSecurity(R.RespSeenS, "The watchers on the camera report a drawn weapon.", origin: () => OriginNow("drawn-seen:" + name, "response", w, op.Pos, null, op.Pos, name));
                    return;
                default:
                    if (w.StartsWith("camera:", StringComparison.Ordinal)) CallSecurity(R.RespSeenS, "The watchers on the camera report a drawn weapon.", origin: () => OriginNow("drawn-seen:" + name, "response", w, op.Pos, null, op.Pos, name)); // a city camera (the mast)
                    return;
            }
        }

        /// <summary>The attention a run draws, a tick at a time (motive-fights.md §1.1): people within witness range on a clear line remember
        /// where and when (and the face: memory by the operative); security that sees it counts a found fault, Alert to cell.runAlert, once a
        /// run. No Trail, no standing. Running is free once a fight is on or the run is loud.</summary>
        void RunAttention(Op op)
        {
            if (RunFree(op)) return;
            string name = Sim.Op.Name(op.Id);
            foreach (var (p, _) in WitnessesWithPos(op.Pos, null)) if (op.RunSeen.Add(p.Id)) Remember(p, "saw-runner", name, true);
            if (!GuardDown && !GuardAlly && GuardWatching(op.Pos) && op.RunSeen.Add(GuardP.Id)) Remember(GuardP, "saw-runner", name, true);
            if (op.RunAlerted) return;
            var w = SecurityWatcherOf(op.Pos); if (w == null) return;
            op.RunAlerted = true;
            RaiseAlert(R.RunAlert, $"runner-seen:{w}:{name}");
            Note("run.seen", $"The {w.Replace("camera:", "")} {(w.StartsWith("camera", StringComparison.Ordinal) ? "camera" : "")} sees the {name} running: a found fault. Alert {Alert}.".Replace("  ", " "));
        }

        // ---------------------------------------------------------------- the orders

        void StartDraw(Op op)
        {
            var g = op.Gun;
            g.Drawn = true; g.HolsterAt = -1; g.DrawReady = Tick + R.DrawTicks; g.DrawTick = Tick; g.Stance = "return"; g.Target = "";
        }

        string Draw(Op op, Order o)
        {
            var g = op.Gun;
            if (g.W == null) return No("no-weapon", $"{o.Op} carries no weapon (Arms)");
            if (g.Drawn && g.HolsterAt < 0) return No("already-drawn", "the weapon is already drawn");
            StartDraw(op);
            Note("order.draw", $"{Sim.Op.Name(op.Id)} draws ({R.DrawTicks / Hz}.{R.DrawTicks % Hz} s).");
            return "";
        }
        string Holster(Op op, Order o)
        {
            var g = op.Gun;
            if (!g.Drawn || g.HolsterAt >= 0) return No("not-drawn", "no weapon drawn");
            g.HolsterAt = Tick + R.HolsterTicks; g.Order = ""; g.Force = false; g.Target = "";
            Note("order.holster", $"{Sim.Op.Name(op.Id)} holsters.");
            return "";
        }
        string Cease(Op op, Order o)
        {
            var g = op.Gun;
            if (!g.Drawn) return No("not-drawn", "no weapon drawn");
            g.Order = ""; g.Force = false; g.Target = ""; g.LostAt = -1;
            Note("order.cease", $"{Sim.Op.Name(op.Id)} ceases fire.");
            return "";
        }
        string Stance(Op op, Order o)
        {
            if (op.Gun.W == null) return No("no-weapon", $"{o.Op} carries no weapon (Arms)");
            if (o.Stance != "hold" && o.Stance != "return" && o.Stance != "free") return No("stance-unknown", $"stance '{o.Stance}' is unknown (hold, return, free)");
            op.Gun.Stance = o.Stance;
            Note("order.stance", $"{Sim.Op.Name(op.Id)}: {o.Stance}.");
            return "";
        }
        string Panic(Order o)
        {
            if (o.Op != "cell") return No("panic-not-cell", "panic is the cell's: op \"cell\"");
            if (!FightOn) return No("panic-no-fight", "no fight: panic works only once a fight is on");
            int n = 0;
            foreach (var op in Ops)
            {
                if (op.Down || op.Inside || op.InCar || op.Gun.W == null) continue;
                if (!op.Gun.Drawn || op.Gun.HolsterAt >= 0) StartDraw(op);
                op.Gun.Stance = "free"; n++;
            }
            if (n == 0) return No("panic-nobody", "nobody armed can fire");
            Note("order.panic", $"Panic: {n} armed operatives fire at will.");
            return "";
        }

        /// <summary>Resolve a fire order's target: "hostiles" and "security" are the nearest one up with a line; others name one.</summary>
        string FireTarget(Op op, string target)
        {
            int max = op.Gun.W!.MaxCm;
            if (target == "hostiles") return NearestHostile(op.Pos, max)?.Id ?? "";
            if (target == "security")
            {
                string best = ""; long bd = long.MaxValue;
                for (int k = 0; k < SecGuns.Length; k++)
                {
                    var at = SecOfficerPose(k)?.pos; if (!at.HasValue) continue;
                    long d = G.D2(op.Pos, at.Value); if (d < bd && d <= (long)max * max && Sees(op.Pos, at.Value)) { bd = d; best = SecGuns[k].Id; }
                }
                if (best.Length == 0) for (int k = 0; k < SecGuns.Length; k++) if (SecOfficerPose(k).HasValue) return SecGuns[k].Id; // none in line: the first up, to say why
                return best;
            }
            return target;
        }

        string Fire(Op op, Order o)
        {
            var g = op.Gun;
            if (g.W == null) return No("no-weapon", $"{o.Op} carries no weapon (Arms)");
            if (op.Running) return No("fire-running", "a running operative doesn't fire: walk or stop first");
            if (op.Carrying.HasValue || op.CarryBody.Length > 0) return No("fire-carrying", "carrying, the operative doesn't fire");
            if (CarriesVale(op)) return No("fire-carrying-vale", "walking Vale, the Enforcer doesn't fire: the others cover him (brief 018)");
            string t = FireTarget(op, o.Target);
            if (t.Length == 0) return No("no-target", o.Target == "hostiles" ? "no hostile in range with a clear line" : $"no {o.Target} to fire at");
            if (IsOpId(t)) return No("fire-on-cell", "the cell doesn't fire on its own");
            var tg = GunOf(t); if (tg == null) return No("target-unknown", $"target '{o.Target}' is unknown (unknown = reject)");
            if (FightOverTick != INF && IsFightHostile(t)) return No("fight-over", $"the fight is over: {t} is no target (rulebook fight.over)");
            if (IsCivilian(t) && !o.Force) return No("civilian-target", $"{t} is a civilian or a contact: a target only when forced (Ctrl)");
            var at = PosOf(t);
            if (!at.HasValue || tg.Down) return No("no-target", $"no {o.Target} to fire at");
            if (!G.Within(op.Pos, at.Value, g.W.MaxCm)) return No("out-of-range", $"out of range ({g.W.MaxCm / 100} m)", m: g.W.MaxCm / 100);
            if (!Sees(op.Pos, at.Value)) return No("no-clear-line", "no clear line");
            if (!g.Drawn || g.HolsterAt >= 0) StartDraw(op);
            g.Order = t; g.Force = o.Force; g.LostAt = -1;
            Actions.Add("fire:" + o.Target);
            Note("fire." + o.Target, $"{Sim.Op.Name(op.Id)} fires on {t} until down.");
            return "";
        }

        string Carry(Op op, Order o)
        {
            if (op.Id == OpId.Enforcer && (Vale == ValeAt.WithEnforcer || Vale == ValeAt.Taking)) return No("carry-vale", "the Enforcer is carrying Vale");
            if (op.Carrying.HasValue || op.CarryBody.Length > 0) return No("already-carrying", "already carrying");
            if (!IsOpId(o.Target)) return PersonById(o.Target) != null ? CarryBody(op, o) : No("carry-names-downed", "carry names a downed operative or a body");
            var other = OpOf(Sim.Op.Parse(o.Target));
            if (other == op) return No("carry-self", "nobody carries themself");
            if (!other.Down) return No("not-down", $"{o.Target} is not down");
            if (other.CarriedBy.HasValue) return No("already-carried", $"{o.Target} is already carried");
            if (other.InCar) return No("in-car", $"the {o.Target} is in the car");
            if (!G.Within(op.Pos, other.Pos, actReach)) return No("stand-beside-op", $"stand beside the {o.Target}", m: actReach / 100);
            Engage(op, o, R.CarryS); op.Gun.Order = ""; op.Gun.Target = "";
            return "";
        }

        // ---------------------------------------------------------------- the cards

        /// <summary>The going-loud card (motive-fights.md §2.6; Sky 2026-10-15 Q4: commit by holding weapons.costs.loudHold, no pause): would
        /// this order make the run loud, and what follows. Changes nothing.</summary>
        public LoudCard GoingLoud(Order o)
        {
            var c = new LoudCard { TrailPerHit = R.HitTrail, TrailPerDown = R.DownTrail, TrailPerShooting = R.GunfireTrail, HoldTicks = R.LoudHoldTicks, ResponseOfficers = R.ResponseOfficers, AlertTo = Alert };
            if (Over) { c.Refused = "the mission is over"; return c; }
            bool loudNow = Alert >= 2 || Gunfire > 0 || FightBranch == "loud";
            if (o.Do == "panic") { c.Why = "panic"; if (!FightOn) c.Refused = "no fight: panic works only once a fight is on"; else c.Why = "fight-on"; return c; }
            if (o.Do != "draw" && o.Do != "fire") { c.Why = "no-change"; return c; }
            var op = OpOf(Sim.Op.Parse(o.Op)); var g = op.Gun;
            if (g.W == null) { c.Refused = $"{o.Op} carries no weapon (Arms)"; return c; }
            if (o.Do == "fire" && CarriesVale(op)) { c.Refused = "walking Vale, the Enforcer doesn't fire"; return c; }
            if (FightOn || FightBranch.Length > 0) { c.Why = "fight-on"; return c; }
            if (loudNow) { c.Why = "already-loud"; return c; }
            string reported; int delay; int civ = 0;
            if (o.Do == "draw")
            {
                var w = SecurityWatcherOf(op.Pos);
                if (w == null) { c.Why = "unseen-draw"; c.AlertTo = WitnessesWithPos(op.Pos, null).Exists(x => x.p.Civilian) ? Math.Max(Alert, R.DrawSeenPeople) : Alert; return c; }
                c.Why = "draw-seen"; reported = w == "security" ? "none" : "seen"; delay = w == "security" ? -1 : R.RespSeenS;
                c.AlertTo = Math.Max(Alert, R.DrawSeenSecurity);
            }
            else
            {
                string t = FireTarget(op, o.Target); var at = t.Length > 0 ? PosOf(t) : null;
                if (t.Length == 0 || !at.HasValue || IsOpId(t) || GunOf(t) == null) { c.Refused = $"no {o.Target} to fire at"; return c; }
                if (IsCivilian(t) && !o.Force) { c.Refused = $"{t} is a civilian or a contact: a target only when forced (Ctrl)"; return c; }
                c.Why = "fire";
                Person? victim = CivilianOf(t) ?? (t == "guard" ? GuardP : null);
                if (IsPersonTarget(t)) foreach (var p in WitnessesOf(at.Value, victim)) if (p.Civilian) civ++;
                var (d, _, _) = Reporter(t, op.Pos, civ > 0); delay = d;
                reported = IsCivilian(t) ? "civilian" : t == "rivals" ? (d == R.RespRivalsUnseenS ? "rivals-unseen" : "seen") : d < 0 ? "none" : d == R.RespWitnessS && civ > 0 ? "witness" : d == R.RespUnseenS ? "unseen" : "seen";
                c.AlertTo = Math.Max(Alert, civ > 0 || IsCivilian(t) ? R.ViolenceSeen : R.GunfireAlert);
                c.RivalsInS = RivalsDrawn || RivalsArrived ? 0 : Math.Max(0, Math.Min(RivalAt, Tick + T(R.RivalsDrawnS)) - Tick) / Hz;
                var pp = PatrolPose();
                c.PatrolBreaks = !PatrolDown && PatrolAwayUntil <= Tick && !PatrolChasing && pp.HasValue && G.Within(pp.Value.pos, op.Pos, R.PatrolBreakCm);
            }
            c.Loud = true; c.Civilians = civ; c.ReportedBy = reported; c.DownedCaptured = true;
            if (delay >= 0) { int arr = GunfireArrival(delay); c.PoliceInS = (arr - Tick) / Hz; c.SecurityArrives = Math.Min(SecurityArrives, arr); c.Seal = c.SecurityArrives + T(SealS); }
            else if (SecurityArrives != INF) { c.SecurityArrives = SecurityArrives; c.Seal = Lockdown; }
            if (Start.FinalFight && FightBranch.Length == 0)
            {
                c.FightAfter = "loud";
                c.Officers = R.LoudOfficers + (c.AlertTo >= 3 ? R.LoudAlert : 0) + (o.Do == "fire" && IsCivilian(FireTarget(op, o.Target)) ? R.LoudCivilian : 0);
                c.GuardAllyLost = !GuardDown && !SawCell(GuardP) && !GuardEngaged;
                c.WarningLost = Inez.Turned && !Inez.Down && Inez.Has(R.HelpedAct);
            }
            return c;
        }

        /// <summary>The price chip for a move (motive-fights.md §1.2): walk and run times, and who would see the run along the route now.</summary>
        public MoveQuote QuoteMove(string opName, Pt to)
        {
            var q = new MoveQuote(); var op = OpOf(Sim.Op.Parse(opName));
            q.RunRefused = RunRefusal(op);
            var route = S.Grid.Free(to) ? S.Grid.Route(op.Pos, to) : null;
            if (route == null) { q.RunRefused = q.RunRefused.Length > 0 ? q.RunRefused : "no walk there"; return q; }
            var path = new Path(route);
            q.WalkS = (int)((path.Length + opSpeed * Hz - 1) / (opSpeed * Hz));
            q.RunS = (int)((path.Length + R.RunSpeed * Hz - 1) / (R.RunSpeed * Hz));
            { var at = new List<Pt>(); for (long mm = 0; ; mm += 1000) { at.Add(path.At(Math.Min(mm, path.Length))); if (mm >= path.Length) break; } q.Seen = SeenAt(at); } // the same samples as below
            q.RunFree = RunFree(op); q.AlertIfRun = Alert;
            if (q.RunFree) return q;
            var people = new HashSet<string>(StringComparer.Ordinal);
            for (long mm = 0; ; mm += 1000) // a sample every metre of the route, at the current tick
            {
                var p = path.At(Math.Min(mm, path.Length));
                foreach (var w in SecurityWatchers) if (!q.RunSeenBy.Contains(w) && WatcherSees(w, p)) q.RunSeenBy.Add(w);
                foreach (var (pp, wp) in OnTheStreet()) if (G.Within(wp, p, witnessRange)) people.Add(pp.Id);
                if (mm >= path.Length) break;
            }
            q.RunPeople = people.Count;
            if (q.RunSeenBy.Count > 0) q.AlertIfRun = Math.Max(Alert, R.RunAlert);
            return q;
        }

        /// <summary>Why this operative can't run now, or "" (motive-fights.md §1.1; Sky 2026-10-15 Q3: no running while carrying Vale).</summary>
        string RunRefusal(Op op)
        {
            if (op.Down) return No("agent-down", $"the {Sim.Op.Name(op.Id)} is down");
            if (op.Id == OpId.Enforcer && (Vale == ValeAt.WithEnforcer || Vale == ValeAt.Taking)) return No("run-carrying-vale", "carrying Vale, the Enforcer walks: a man being taken walks");
            if (op.Carrying.HasValue || op.CarryBody.Length > 0) return No("run-carrying-downed", "carrying, the operative walks");
            if (op.Id == OpId.Tech && LoopOn) return No("run-tethered", "the Tech is tethered to the cabinet while the loop holds");
            if (op.Busy != null) return No("agent-busy", $"{Sim.Op.Name(op.Id)} is busy until {op.BusyEnd}", tick: op.BusyEnd);
            return "";
        }
    }
}

sim/Suborned.Sim/GameCrowd.cs.text:
// The city's people stepping their routines (N12; GDD §04 person = routine + need + temperament + memory; brief 010): every
// simulated person of sim/data/handover.people.json stands at the stop their routine gives for the mission's clock, or walks the
// grid between two stops, timed from one stop's end to the next one's start. At home, working inside or beyond the sheet they are
// not on the street. On the street they witness (§05; rulebook witness.sees): within 13 m on a clear sightline they add Trail once
// an incident, move standing, and remember. The four people the Handover casts by role are played by their role, not here.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed class Walker
    {
        public Person P = null!;
        public string[] Place = Array.Empty<string>(); public int[] From = Array.Empty<int>(), To = Array.Empty<int>(); public bool[] Out = Array.Empty<bool>(); // ticks from mission 0:00
        /// <summary>A fresh copy for one game: the routine is shared, the person's state is not.</summary>
        // in a fight (Pulse §4): "" routine, startled, fleeing, sheltered, returning; where they stand or run, and since when
        public string St = ""; public int Until, RunStart; public Pt At; public Path? Run; public string Refuge = "";
        public int Pace; // brief 013: the pace of a report's walk or a check (mm a tick); 0 for the crowd machine's own states
        public int PacePct = -1; // brief 023 (engine 0.8.2): the extra per cent this person walks a routine leg at (rulebook crowd.pace), from their id; -1 until first read
        public Walker Fresh()
        {
            var p = new Person { Id = P.Id, Name = P.Name, Job = P.Job, Temperament = P.Temperament, Need = P.Need, Role = "", Record = P.Record, Size = P.Size, Holder = P.Holder };
            Array.Copy(P.Sc, p.Sc, 4);
            return new Walker { P = p, Place = Place, From = From, To = To, Out = Out };
        }
    }

    public sealed class Crowd
    {
        public readonly List<Walker> Walkers = new List<Walker>();
        public readonly Dictionary<string, Pt> Places = new Dictionary<string, Pt>(StringComparer.Ordinal);
        public readonly int StartsAt;
        /// <summary>The need records (brief 017; sim people `needs.records`, from contracts/people/&lt;plan&gt;.needs.json): id → kind, label, size.</summary>
        public readonly SortedDictionary<string, (string kind, string label, string size)> Records = new SortedDictionary<string, (string, string, string)>(StringComparer.Ordinal);
        /// <summary>Everyone's need record, the cast's too: id → record, size, holder.</summary>
        public readonly Dictionary<string, (string record, string size, string holder)> RecordOf = new Dictionary<string, (string, string, string)>(StringComparer.Ordinal);
        /// <summary>The record a replaced need of `kind` takes (phase 1: the kind's one record, the first by id; "" if the catalogue has none).
        /// No draw: phase 1 moves no stream (brief 017: need.replaced draws records in phase 2).</summary>
        public string DefaultRecord(string kind) { foreach (var kv in Records) if (kv.Value.kind == kind) return kv.Key; return ""; }
        /// <summary>Everyone's ties, home and work, the cast's too (between missions: word along ties, need replacement's requires).</summary>
        public readonly Dictionary<string, List<(string kind, string with)>> Ties = new Dictionary<string, List<(string, string)>>(StringComparer.Ordinal);
        public readonly Dictionary<string, bool> HasHome = new Dictionary<string, bool>(StringComparer.Ordinal), HasWork = new Dictionary<string, bool>(StringComparer.Ordinal);
        /// <summary>Everyone's stops, the cast's too, in ticks (brief 013: check-in marks read a post's shift, suspicion reads shared stops).</summary>
        /// <summary>Every routine leg's walk (place → place), built once at load (Warm), read-only after: a leg's route never depends on when
        /// it is walked, so building them up front changes no run, and the chime (58 clerks starting new legs on one tick) costs no frame.</summary>
        public readonly Dictionary<string, Path> Legs = new Dictionary<string, Path>(StringComparer.Ordinal);
        public void Warm(Site site)
        {
            foreach (var w in Walkers)
                for (int i = 0; i + 1 < w.Place.Length; i++)
                {
                    var a = w.Place[i]; var b = w.Place[i + 1]; if (a == "beyond" || b == "beyond") continue;
                    var key = a + "→" + b; if (Legs.ContainsKey(key)) continue;
                    Legs[key] = Leg(site, Places[a], Places[b]);
                }
        }
        internal static Path Leg(Site site, Pt pa, Pt pb)
        {
            var fa = site.Grid.NearestFree(pa) ?? pa; var fb = site.Grid.NearestFree(pb) ?? pb;
            var pts = new List<Pt> { pa };
            var route = site.Grid.Route(fa, fb);
            if (route != null) pts.AddRange(route); else pts.Add(fb);
            pts.Add(pb);
            return new Path(pts.ToArray());
        }
        public readonly Dictionary<string, List<(string place, int from, int to, bool outside)>> Stops = new Dictionary<string, List<(string, int, int, bool)>>(StringComparer.Ordinal);
        public Crowd(string json, Rules rules, ICollection<string> cast)
        {
            var n = JNode.Parse(json, "people");
            n.Only("schema", "from", "scope", "frame", "startsAt", "places", "needs", "people");
            if (n["schema"].Str() != "suborned.sim.people/2") throw new FormatException("people schema is not suborned.sim.people/2");
            // the need records (brief 017): every record's kind is a rules need and its size one the need kinds name (unknown = reject)
            var nd = n["needs"]; nd.Only("sizes", "records", "frame");
            var sizes = new HashSet<string>(StringComparer.Ordinal); foreach (var z in nd["sizes"].Items) sizes.Add(z.Str());
            foreach (var kv in nd["records"].Entries)
            {
                var x = kv.Value.Items; if (x.Count != 3) throw new FormatException($"{kv.Value.Path}: a record is [kind, label, size]");
                string kind = x[0].Str(), label = x[1].Str(), size = x[2].Str();
                rules.CheckNeed(kind);
                if (label.Length == 0) throw new FormatException($"{kv.Value.Path}: a record has a label");
                if (!sizes.Contains(size)) throw new FormatException($"{kv.Value.Path}: size '{size}' is not in needs.sizes (unknown = reject)");
                Records[kv.Key] = (kind, label, size);
            }
            StartsAt = n["startsAt"].Int();
            foreach (var kv in n["places"].Entries) Places[kv.Key] = Pt.Of(kv.Value);
            foreach (var p in n["people"].Items)
            {
                p.Only("id", "name", "job", "temperament", "need", "home", "work", "record", "size", "holder", "start", "ties", "stops");
                var ties = new List<(string, string)>(); foreach (var t in p["ties"].Items) ties.Add((t.Items[0].Str(), t.Items[1].Str()));
                Ties[p["id"].Str()] = ties; HasHome[p["id"].Str()] = p["home"].Int() == 1; HasWork[p["id"].Str()] = p["work"].Int() == 1;
                var id = p["id"].Str();
                string rec = p["record"].Str(), size = p["size"].Str(), holder = p["holder"].Str();
                if (!Records.TryGetValue(rec, out var r)) throw new FormatException($"{id}: need record '{rec}' is not in needs.records (unknown = reject)");
                if (r.kind != p["need"].Str()) throw new FormatException($"{id}: need record '{rec}' is a {r.kind} record, not {p["need"].Str()}");
                if (r.size != size) throw new FormatException($"{id}: size '{size}' is not record {rec}'s ({r.size})");
                RecordOf[id] = (rec, size, holder);
                var all = new List<(string, int, int, bool)>(); foreach (var sx in p["stops"].Items) { var x = sx.Items; all.Add((x[0].Str(), x[1].Int() * Game.Hz, x[2].Int() * Game.Hz, x[3].Int() == 1)); }
                Stops[id] = all;
                if (cast.Contains(id)) continue;
                var person = new Person { Id = id, Name = p["name"].Str(), Job = p["job"].Str(), Temperament = p["temperament"].Str(), Need = p["need"].Str(), Record = rec, Size = size, Holder = holder };
                rules.Temp(person.Temperament); rules.CheckNeed(person.Need);
                var st = p["start"].Ints(); for (int k = 0; k < 4; k++) person.Sc[k] = st[k];
                var stops = p["stops"].Items; var w = new Walker { P = person, Place = new string[stops.Count], From = new int[stops.Count], To = new int[stops.Count], Out = new bool[stops.Count] };
                for (int i = 0; i < stops.Count; i++)
                {
                    var s = stops[i].Items;
                    w.Place[i] = s[0].Str(); w.From[i] = s[1].Int() * Game.Hz; w.To[i] = s[2].Int() * Game.Hz; w.Out[i] = s[3].Int() == 1;
                    if (w.Place[i] != "beyond" && !Places.ContainsKey(w.Place[i])) throw new FormatException($"{id}: place {w.Place[i]} is unknown");
                }
                Walkers.Add(w);
            }
            // a holder is nobody on the sheet ("beyond") or a person of this file (phase 2 binds them)
            foreach (var kv in RecordOf) if (kv.Value.holder != "beyond" && !RecordOf.ContainsKey(kv.Value.holder)) throw new FormatException($"{kv.Key}: holder '{kv.Value.holder}' is not a person of the people file (unknown = reject)");
        }
    }

    public sealed partial class Game
    {
        public Crowd? People2;
        public readonly List<Walker> Walkers = new List<Walker>(); // this game's people, fresh from People2
        readonly Dictionary<string, Path> crowdPaths = new Dictionary<string, Path>(StringComparer.Ordinal);

        /// <summary>Where a person of the crowd is at this tick, or null if they are not on the street.</summary>
        public Pt? CrowdPos(Walker w) => CrowdPos(w, Tick);
        public Pt? CrowdPos(Walker w, int tick)
        {
            if (w.P.Down) return null;
            if (w.St.Length > 0 && tick == Tick) return ScatterPos(w);
            return RoutinePos(w, tick);
        }
        /// <summary>Where the routine puts a person of the crowd at this tick (no fight).</summary>
        Pt? RoutinePos(Walker w, int tick)
        {
            if (w.P.Down) return null;
            var c = People2!;
            for (int i = 0; i < w.Place.Length; i++)
            {
                if (tick >= w.From[i] && tick < w.To[i]) return w.Out[i] ? c.Places[w.Place[i]] : (Pt?)null;
                if (i + 1 < w.Place.Length && tick >= w.To[i] && tick < w.From[i + 1])
                {
                    if (w.Place[i] == "beyond" || w.Place[i + 1] == "beyond") return null;
                    var path = CrowdPath(w.Place[i], w.Place[i + 1]);
                    int span = w.From[i + 1] - w.To[i];
                    return span <= 0 ? path.End : path.At(LegMm(w, path, tick - w.To[i], span));
                }
            }
            return null;
        }
        /// <summary>How far along a routine leg a person is, `t` ticks into a leg timed `span` (brief 023, engine 0.8.2; rulebook crowd.pace): each
        /// person walks it (100 + k) % of its timed pace, k = 0..pace from a hash of their id, so people who set out together string out; once
        /// at its end they wait there until the next stop starts (never late: the leg's own timing is the slowest).</summary>
        internal long LegMm(Walker w, Path path, long t, int span)
        {
            if (w.PacePct < 0) w.PacePct = (int)(Streams.Fnv1a32(w.P.Id + "/pace") % (uint)(R.CrowdPaceSpreadPct + 1));
            long mm = path.Length * t * (100 + w.PacePct) / (100L * span);
            return mm < path.Length ? mm : path.Length;
        }
        Path CrowdPath(string a, string b)
        {
            var key = a + "→" + b;
            var c = People2!;
            if (c.Legs.TryGetValue(key, out var p)) return p; // built at load (Crowd.Warm)
            if (crowdPaths.TryGetValue(key, out p)) return p;
            p = Crowd.Leg(S, c.Places[a], c.Places[b]); crowdPaths[key] = p; return p;
        }

        /// <summary>Everyone on the street who could witness: the cast by their role, then the crowd by id (Start.Crowd, Suture's T4 arm).</summary>
        IEnumerable<(Person p, Pt at)> OnTheStreet()
        {
            foreach (var p in People)
            {
                if (p == ValeP && (Vale == ValeAt.WithEnforcer || Vale == ValeAt.Taking)) continue; // the captive is no witness: he is the act
                var at = PersonPos(p); if (at.HasValue) yield return (p, at.Value);
            }
            if (People2 == null || !Start.Crowd) yield break;
            foreach (var w in Walkers) { var at = CrowdPos(w); if (at.HasValue) yield return (w.P, at.Value); }
        }

        /// <summary>The people within witness range of `at` on a clear sightline, but not `except`.</summary>
        List<Person> WitnessesOf(Pt at, Person? except, Person? also = null)
        {
            var seen = new List<Person>();
            foreach (var (p, wp) in OnTheStreet())
            {
                if (p == except || p == also) continue;
                if (G.Within(wp, at, witnessRange) && Sees(wp, at)) seen.Add(p);
            }
            return seen;
        }
    }
}

sim/Suborned.Sim/GameDrive.cs.text:
// The driven agent (brief 025 playground, EXPERIMENTAL; Keel, briefs/024/keel-wasd.md; rulebook cell.drive). The host moves one operative
// freely (a character controller) and hands the engine where it is each tick as a drive sample, an order in the log like any other, so a
// replay reads the samples back and never re-runs the controller. The engine checks every sample against the agent's pace budget and the walk
// grid (and the gap to people), keeps the legal part, and the agent is then simply where it stands for every other rule. Integer state only.
using System;

namespace Suborned.Sim
{
    /// <summary>What the host reads back each tick for a driven operative (Game.DrivePose).</summary>
    public struct DrivePose
    {
        public bool Driven;   // the engine has this operative under the host's control
        public Pt Pos;        // where the engine has it (cm): the host's controller goes here when it differs
        public int Face;      // the last sample's facing (degrees), -1 if none
        public bool Running;  // moving at a run this tick (a run the engine took: carrying or tethered, it walks)
        public bool Corrected; // this tick's sample was not taken whole (budget, a wall, the gap, a busy agent pinned)
        public int Corrections; // samples corrected since control began (diagnostic)
    }

    public sealed partial class Game
    {
        /// <summary>The driven agent's pace, onBusy, onRelease and gap for this run: the playground start's (Start.drive) over cell.drive.</summary>
        int DrivePacePm => Start.DrivePace ?? 1000;
        int DriveGapCm => Start.DriveGap ?? R.Drive!.GapCm;
        string DriveOnBusy => Start.DriveOnBusy ?? R.Drive!.OnBusy;
        string DriveOnRelease => Start.DriveOnRelease ?? R.Drive!.OnRelease;

        /// <summary>The host's read-back for one operative (read-only).</summary>
        public DrivePose DrivePoseOf(OpId id)
        {
            var op = OpOf(id);
            return new DrivePose { Driven = op.Driven, Pos = op.Pos, Face = op.Face, Running = op.Driven && op.Running, Corrected = op.Driven && driveCorrected[(int)id] == Tick, Corrections = op.DriveHeld };
        }
        readonly int[] driveCorrected = { -1, -1, -1, -1 }; // the tick each operative's sample was last corrected (derived from the samples: not hashed)

        /// <summary>A drive sample for this tick, ready to Issue: where the host's controller has the operative (cm), Shift held, facing (degrees).</summary>
        public Order DriveSample(OpId id, Pt at, bool run, int face) => new Order { Tick = Tick, Op = Sim.Op.Name(id), Do = "drive", Point = at, Run = run, Face = ((face % 360) + 360) % 360 };
        /// <summary>The order that hands control of an operative back (it stands, or resumes: cell.drive.onRelease).</summary>
        public Order DriveRelease(OpId id) => new Order { Tick = Tick, Op = Sim.Op.Name(id), Do = "drive", Release = true };

        /// <summary>The drive order (rulebook cell.drive): taken now, applied by the next step. Down and inside are refused before this.</summary>
        string Drive(Op op, Order o)
        {
            if (R.Drive == null) return No("unknown-verb", "verb 'drive' is unknown (unknown = reject): the rulebook has no cell.drive");
            if (o.Release) { if (op.Driven) EndDrive(op, true); return ""; }
            if (!o.Point.HasValue) return No("no-place", "a drive sample says where the agent is (to: [x, y] cm)");
            if (op.InCar) return No("in-car", $"the {o.Op} is in the car: a move steps out first");
            if (!op.Driven)
            {
                op.Driven = true; op.DriveSpan = false; op.DrivePush = 0; op.DriveResume = null; op.DriveHeld = 0;
                if (op.Walk != null) { op.DriveResume = op.Walk.End; op.DriveResumeRun = op.Running; } // the walk control takes over (resumed on release if onRelease resume)
                op.Walk = null; op.WalkMm = 0; op.Running = false;
                op.DriveBudget = DriveCapMm(op, false);
            }
            op.DriveTo = o.Point; op.DriveRun = o.Run;
            if (o.Face >= 0) op.Face = ((o.Face % 360) + 360) % 360;
            return "";
        }

        /// <summary>mm a tick the operative may move driven: a walk (a carrier's while carrying), or a run when one is allowed (RunRefusal less
        /// "busy": a busy agent is pinned anyway), scaled by the playground pace.</summary>
        int DriveCapMm(Op op, bool run)
        {
            bool canRun = run && !(op.Id == OpId.Enforcer && (Vale == ValeAt.WithEnforcer || Vale == ValeAt.Taking)) && !op.Carrying.HasValue && op.CarryBody.Length == 0 && !(op.Id == OpId.Tech && LoopOn);
            int pace = PaceOf(op, canRun);
            return Math.Max(1, (int)((long)pace * DrivePacePm / 1000));
        }
        bool DriveCanRun(Op op) => op.DriveRun && DriveCapMm(op, true) > DriveCapMm(op, false);

        /// <summary>One tick of a driven operative (from the step, where a walk would advance).</summary>
        void StepDrive(Op op)
        {
            if (op.Down || op.Inside || op.InCar || op.CarriedBy.HasValue) { EndDrive(op, false); return; }
            var d = R.Drive!; var want = op.DriveTo; op.DriveTo = null; op.DriveMoved = false;
            bool run = DriveCanRun(op); int cap = DriveCapMm(op, run);
            op.DriveBudget = Math.Min(op.DriveBudget + cap, cap * d.BurstTicks);
            if (!op.DriveRun || !run) op.DriveSpan = false; // a walk sample (or a run refused: carrying, tethered) ends the run span
            op.Running = false;
            if (!want.HasValue) return;
            var from = op.Pos; var to = want.Value;
            if (op.Busy != null)
            {
                int push = G.Dist(from, to);
                if (push <= d.SlackCm) { op.DrivePush = 0; return; }
                if (DriveOnBusy == "hold") { Corrected(op); return; }
                op.DrivePush += push;
                if (op.DrivePush < d.BusyPushCm) { Corrected(op); return; }
                op.DrivePush = 0;
                Cancel(op); // the cancel order's own cost and log (rulebook cancel)
                if (op.Busy != null) { Corrected(op); return; } // an act that can't be cancelled (the wait inside): pinned
            }
            else op.DrivePush = 0;
            bool whole = true;
            long dist = Mm(from, to), allow = op.DriveBudget + d.SlackCm * 10L; // millimetres, so a step's length is never rounded down into the budget
            if (dist > allow) { to = G.Lerp(from, to, allow, dist); whole = false; }
            var at = AxisX(from, to.X); at = AxisY(at, to.Y);
            int gap = DriveGapCm;
            if (gap > 0 && !GapClear(from, at, gap))
            {
                var xOnly = AxisX(from, to.X); var yOnly = AxisY(from, to.Y);
                at = GapClear(from, xOnly, gap) ? xOnly : GapClear(from, yOnly, gap) ? yOnly : from;
            }
            if (at != want.Value) whole = false;
            if (!whole) Corrected(op);
            op.DriveBudget = (int)Math.Max(-d.SlackCm * 10L, op.DriveBudget - Mm(from, at)); // slack overdraws the budget, never adds to it: the pace holds on average
            op.Pos = at; op.DriveMoved = at != from;
            if (run && op.DriveMoved)
            {
                if (!op.DriveSpan)
                {
                    op.DriveSpan = true; op.RunAlerted = false; op.RunSeen.Clear();
                    if (op.Gun.Order.Length > 0) { op.Gun.Order = ""; op.Gun.Force = false; op.Gun.Target = ""; Note("fire.cancelled", $"{Sim.Op.Name(op.Id)} runs: the fire order ends."); }
                }
                op.Running = true; RunAttention(op);
            }
        }
        static long Mm(Pt a, Pt b) => G.Isqrt(G.D2(a, b) * 100); // mm between two cm points, floored to the mm
        void Corrected(Op op) { op.DriveHeld++; driveCorrected[(int)op.Id] = Tick; }

        /// <summary>Move along x from p to x, stopping at the last centimetre before the first blocked cell (the cell p stands in is passable).</summary>
        Pt AxisX(Pt p, int x)
        {
            var g = S.Grid; int j = g.CJ(p.Y), i0 = g.CI(p.X), i1 = g.CI(x);
            if (i1 == i0) return new Pt(x, p.Y);
            int step = i1 > i0 ? 1 : -1;
            for (int i = i0 + step; ; i += step)
            {
                if (!g.FreeCell(i, j)) return new Pt(step > 0 ? g.X0 + i * g.Cell - 1 : g.X0 + (i + 1) * g.Cell, p.Y);
                if (i == i1) return new Pt(x, p.Y);
            }
        }
        Pt AxisY(Pt p, int y)
        {
            var g = S.Grid; int i = g.CI(p.X), j0 = g.CJ(p.Y), j1 = g.CJ(y);
            if (j1 == j0) return new Pt(p.X, y);
            int step = j1 > j0 ? 1 : -1;
            for (int j = j0 + step; ; j += step)
            {
                if (!g.FreeCell(i, j)) return new Pt(p.X, step > 0 ? g.Y0 + j * g.Cell - 1 : g.Y0 + (j + 1) * g.Cell);
                if (j == j1) return new Pt(p.X, y);
            }
        }
        /// <summary>The step from → to keeps the gap: it ends within `gap` of nobody on the street it came nearer to (stepping away is free).</summary>
        bool GapClear(Pt from, Pt to, int gap)
        {
            if (to == from) return true;
            foreach (var (p, at) in OnTheStreet())
            {
                if (p.Down) continue;
                if (G.Within(to, at, gap) && G.D2(to, at) < G.D2(from, at)) return false;
            }
            return true;
        }

        /// <summary>Control ends: released by the host (release true: onRelease applies), or by the game (down, inside, in the car, a click move).</summary>
        void EndDrive(Op op, bool release)
        {
            op.Driven = false; op.DriveTo = null; op.DriveRun = false; op.DriveSpan = false; op.DriveMoved = false; op.Running = false; op.DrivePush = 0; op.DriveBudget = 0;
            var resume = op.DriveResume; bool resumeRun = op.DriveResumeRun; op.DriveResume = null; op.DriveResumeRun = false;
            if (!release || DriveOnRelease != "resume" || !resume.HasValue || op.Down || op.Inside || op.InCar || op.Busy != null) return;
            var route = S.Grid.Route(op.Pos, resume.Value); if (route == null) return;
            op.Walk = new Path(route); op.WalkMm = 0; if (op.Walk.Length == 0) { op.Walk = null; return; }
            bool run = resumeRun && DriveCapMm(op, true) > DriveCapMm(op, false); // a run where one is allowed (as RunRefusal, without its refusal)
            op.Running = run; op.WalkSpeed = PaceOf(op, run);
            if (run) { op.RunAlerted = false; op.RunSeen.Clear(); }
            Note("order.move", $"{Sim.Op.Name(op.Id)} {(run ? "runs" : "heads")} on for {resume.Value}.");
        }
    }
}

sim/Suborned.Sim/GameFight.cs.text:
// The final fight (GDD §07 [S]: always; 3–5 hostiles; rulebook `fight`). It starts when the Enforcer has Vale and is fought at the
// getaway car: the car can't leave while a hostile holds it. Loud (any shot or Alert ≥ 2): police officers run in from the response
// unit's entry; the seal clock runs; no allies. Safe: the rival crew ambushes the extraction, fewer for a turned driver and an earlier
// false tip; a helped Inez's warning holds their first shots back; a guard who never saw the cell joins in. Every hostile shoots at
// its own weapon's cadence (GameCombat.cs; Sky 2026-10-15, briefs/011/motive-fights.md: the volley is retired).
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed class Hostile
    {
        public string Id = ""; public Pt At, Home; public Path? Run; public int RunStart, Speed; public bool Present; public Gun Gun = null!; // Home: its stand (police; a blocker's lane point)
        public bool Blocker; // brief 018 §1: it went for the road, and holds its point in the exit lane as police hold a stand
        public bool Down => Gun.Down; public int Health => Gun.Health;
        public Pt Pos(int tick) => Run == null ? At : Run.At((long)Math.Max(0, tick - RunStart) * Speed);
        public bool Moving(int tick) => Run != null && (long)Math.Max(0, tick - RunStart) * Speed < Run.Length;
    }

    public sealed partial class Game
    {
        public string FightBranch = "";                    // "", "loud", "safe"
        public int FightStart = INF, FightSprung = INF, FightOverTick = INF;
        public bool FightWarned, GuardAlly;
        public int FightHits, DownedByEnforcer, DownedByGuard, DownedByCell, FightShots;
        public readonly List<Hostile> Hostiles = new List<Hostile>();
        public readonly List<string> FightWhy = new List<string>();
        Path? guardAllyPath; int guardAllyStart;
        bool rivalsAbsorbed, misledOnce;


        /// <summary>The Enforcer has Vale: the final fight begins (§07: always).</summary>
        void StartFight()
        {
            if (!Start.FinalFight || FightBranch.Length > 0) return;
            bool loud = Gunfire > 0 || Alert >= 2;
            FightBranch = loud ? "loud" : "safe"; FightStart = Tick;
            FightJoinsFinal(); // fight.public: gunfire still open is the final fight
            RoundsEnd("final-fight"); // brief 022
            if (loud)
            {
                int n = R.LoudOfficers;
                if (Alert >= 3) { n += R.LoudAlert; FightWhy.Add("alert-3"); }
                bool civShot = false; foreach (var kv in civGuns) if (kv.Value.Down) civShot = true; // a civilian shot (a takedown is no shot)
                if (civShot) { n += R.LoudCivilian; FightWhy.Add("civilian-shot"); }
                var entry = S.Stand(S.FightEntry);
                var stands = S.FightPolice;
                for (int i = 0; i < n && i < stands.Length; i++)
                {
                    var route = S.Grid.Route(entry, S.Stand(stands[i])) ?? new[] { entry, S.Stand(stands[i]) };
                    var gun = NewGun($"officer-{i + 1}", R.Pistol, true, R.HealthOfficer); gun.Engaged = true; gun.St = "advance"; // summoned: no alert delay (Pulse §3.2)
                    Hostiles.Add(new Hostile { Id = gun.Id, At = S.Stand(stands[i]), Home = S.Stand(stands[i]), Run = new Path(route), RunStart = Tick, Speed = secSpeed, Present = true, Gun = gun });
                }
                int lockBefore = Lockdown;
                Lockdown = Math.Min(Lockdown, Tick + T(SealS));
                SealOrigin(lockBefore, () => { var o = alertTwoOrigin ?? gunfireOrigin; return o == null ? OriginNow("loud-fight", "loud-fight", "", null, null, null, "enforcer") : Recast(o, "loud-fight"); }); // what made it loud
                Note("fight.loud", $"The final fight: {Hostiles.Count} police officers come in from the north street. The seal clock is running.");
            }
            else
            {
                int n = R.SafeHostiles;
                if (Driver.Turned && !Driver.Down) { n -= R.SafeMinus; FightWhy.Add("driver-blocks-rival-car"); }
                if (misledOnce) { n -= R.SafeMinus; FightWhy.Add("earlier-false-tip"); }
                var spots = S.FightAmbush;
                for (int i = 0; i < n && i < spots.Length; i++)
                {
                    var gun = NewGun($"rival-{i + 1}", R.Pistol, false, R.HealthRival); gun.St = "routine"; // lurking (Pulse §3.1)
                    Hostiles.Add(new Hostile { Id = gun.Id, At = S.Stand(spots[i]), Home = S.Stand(spots[i]), Speed = rivSpeed, Gun = gun });
                }
                FightWarned = Inez.Turned && !Inez.Down && Inez.Has(R.HelpedAct);
                if (FightWarned) FightWhy.Add("waitress-warns");
                GuardAlly = !GuardDown && GuardGun.Health == GuardGun.Max && !GuardEngaged && !SawCell(GuardP);
                if (GuardAlly) FightWhy.Add("guard-fights-them");
                rivalsAbsorbed = true; // the crew is the ambush now
                Note("fight.safe", $"The final fight: the rival crew ({Hostiles.Count}) lies in wait for the extraction.");
            }
        }

        /// <summary>The guard "never saw you" (§07): he holds no memory the cell left — no face, no act seen.</summary>
        bool SawCell(Person p) => p.Memory.Count > 0;


        void FightStep()
        {
            if (FightBranch.Length == 0 || FightOverTick != INF) return;
            JoinResponse();
            if (FightBranch == "loud" && !blockersPicked && pickFrom.Length == 0) pickFrom = "police"; // brief 018 §1: the first officer to arrive takes the lane (picked after this tick's fire)
            if (RivalReachesVale()) { Fail("rivals-reach-vale", "A rival reaches the car with nobody beside it and takes Vale out.", RivalsAtCar); return; }
            var e = Enforcer; var car = S.At(S.GetawayCar);
            if (FightBranch == "safe" && FightSprung == INF && Vale == ValeAt.WithEnforcer && !e.Inside && G.Within(e.Pos, car, R.SafeAmbushCm))
            {
                FightSprung = Tick;
                // lying in wait, the crew fires aimNew after springing, plus the warning if Inez gave it (motive-fights.md §2.2 timing)
                foreach (var h in Hostiles) { h.Present = true; h.Gun.Engaged = true; h.Gun.St = "alerted"; h.Gun.Until = h.Gun.NextShot = Tick + R.AimNewTicks + (FightWarned ? T(R.SafeWarnS) : 0); }
                Note("fight.ambush", FightWarned ? "Inez's warning comes in time: the ambush is seen before it fires." : "The rival crew springs its ambush at the getaway car.");
                if (!blockersPicked) pickFrom = "rivals"; // brief 018 §1: one goes for the road as the ambush springs (picked after this tick's fire)
                if (GuardAlly)
                {
                    var from = GuardPose()?.pos ?? S.Stand(S.GuardPost);
                    var stop = AllyStop(); // his post, or the cover beside it (Pulse §3.4)
                    var route = S.Grid.Route(S.Grid.NearestFree(from) ?? from, S.Grid.NearestFree(stop) ?? stop);
                    guardAllyPath = new Path(route ?? new[] { from, stop }); guardAllyStart = Tick;
                    GuardHeld = true; heldPhase = "fighting the rivals"; heldPos = from; GuardAwayUntil = INF;
                    Note("fight.guard", "The guard hears the shooting and runs in against the rivals.");
                }
            }
            bool anyUp = false; foreach (var h in Hostiles) if (!h.Down && h.Gun.St != "break" && h.Gun.St != "gone") anyUp = true;
            if (!anyUp && Hostiles.Count > 0) { FightOverTick = Tick; Note("fight.over", "The last of them is down or gone. The car can go."); return; }
            // the guard runs in against the rivals (safe); his shots are in Combat()
            if (GuardAlly && guardAllyPath != null && !GuardDown)
            {
                long mm = (long)(Tick - guardAllyStart) * secSpeed;
                heldPos = guardAllyPath.At(mm); heldFacing = guardAllyPath.Heading(mm);
            }
        }
        bool GuardAllyMoving => GuardAlly && guardAllyPath != null && (long)(Tick - guardAllyStart) * secSpeed < guardAllyPath.Length;

        Hostile? NearestHostile(Pt from, int reach)
        {
            Hostile? best = null; long bd = long.MaxValue;
            foreach (var h in Hostiles)
            {
                if (!h.Present || h.Down || h.Gun.St == "break" || h.Gun.St == "gone") continue;
                var p = h.Pos(Tick); long d = G.D2(from, p);
                if (d <= (long)reach * reach && d < bd && Sees(from, p)) { bd = d; best = h; }
            }
            return best;
        }


        void MisledOnce() { misledOnce = true; }
        bool RivalsAbsorbed => rivalsAbsorbed;
    }
}

sim/Suborned.Sim/GameGetaway.cs.text:
// The getaway (brief 018, Motive; approved by Sky 2026-10-18: "I want to get my team into the car, and get away"). Rulebook fight.hold,
// fight.block, fight.blockers, cell.board, campaign.custody, debrief.lines left-behind, captive, car-seen; site getaway.exit.
//  · The hold: a holder is a combatant (a final-fight hostile, or anyone who has fired on or aims at the cell) not down, broken or gone,
//    within fight.hold of the car (any level, line or none) or on the street inside the exit lane. Every position the engine keeps is on
//    the street level, so "on the street" holds for every body here. An ambusher lying in wait holds only if its spot does.
//  · The blocker: fight.blockers hostiles per fight go for the road, by the shortest grid walk to the lane (to the lane's nearest point a
//    metre inside its sides), ties by id; safe: picked from the ambush when it springs; loud: from the officers on the fight's first tick
//    (they all walk at one pace, so the shortest walk is the first to arrive). It walks to the nearest free cover point inside the lane,
//    else to that lane point in the open, without stopping on the way, and holds it as police hold a stand. Not replaced.
//  · Board (1 s; carrying, +carry.s, the carried first) and Go (instant: refused while held, naming the holders). The win is Vale in the
//    car when it leaves. Left behind at Go: downed → captured; standing → captured while a combatant is up and not broken (fighting) or
//    the seal clock runs (sealed), else walks out. Captures happen only at Go.
//  · Seen leaving: a police officer, a robot or an engaged patrol up with the car in its cone or within witness range on a clear line: one
//    witnessed incident (+witness-trail) and the investigation hunts the car (cell-car). Rivals never report.
//  · The custody projection for the debrief (no campaign layer runs yet): +captured-trail each, held at the police post, the Talker test
//    once each between-missions phase, the facts a captive would give.
using System;
using System.Collections.Generic;
using System.Globalization;

namespace Suborned.Sim
{
    /// <summary>One captured operative as the debrief projects them (brief 018 §3; rulebook campaign.custody).</summary>
    public sealed class Captive
    {
        public string Op = "", Why = "", HeldAt = "";
        /// <summary>Missions the captive holds before the questioning they talk at; TalksAt that questioning (1-based), 0 if they hold the whole rescue window.</summary>
        public int Holds, TalksAt, RescueUntil;
        public readonly int[] Sc = new int[4]; // bravery, resentment, fear, loyalty when they talk (or at the window's end)
        public readonly List<string> Facts = new List<string>(); public string Left = "", Right = "";
    }

    public sealed partial class Game
    {
        /// <summary>The hostiles that went for the road (brief 018 §1), in the order picked.</summary>
        public readonly List<string> Blockers = new List<string>();
        bool blockersPicked; string pickFrom = ""; bool carWasHeld, blockerOut; // the pick due this tick (rivals, police); the hold's last state; blocker.out logged

        /// <summary>End of the tick's fire (Waymark, c018): a pick due this tick is made among the candidates still standing after it (a
        /// candidate downed by this tick's shots is no candidate); the blocker's fall and the hold coming free are logged by code.</summary>
        void GetawayAfterFire()
        {
            if (pickFrom.Length > 0)
            {
                var from = pickFrom; pickFrom = "";
                PickBlockers(Hostiles.FindAll(h => from == "rivals" ? IsRival(h.Id) : !IsRival(h.Id) && h.Present));
            }
            if (FightBranch.Length == 0) return;
            if (!blockerOut && Blockers.Count > 0)
            {
                bool any = false; foreach (var id in Blockers) { var b = HostileOf(id); if (b != null && Up(b)) any = true; }
                if (!any) { blockerOut = true; var b0 = HostileOf(Blockers[0])!; Note("blocker.out", $"{b0.Id}, on the road, is {(b0.Down ? "down" : "gone")}: nobody blocks the lane now."); }
            }
            bool held = CarHeld();
            if (carWasHeld && !held) Note("car.free", "Nothing holds the getaway car: it can go.");
            carWasHeld = held;
        }
        /// <summary>The tick the getaway car left (INF while it hasn't).</summary>
        public int CarLeftTick = INF;
        /// <summary>The security body that saw the car leave ("" if none): the departure was one witnessed incident and the car is hunted.</summary>
        public string CarSeenBy = "";
        /// <summary>Everyone not in the car when it left, as LeftBehind() gave them at that tick.</summary>
        public readonly List<(string op, string fate, string why)> LeftBehindAtGo = new List<(string, string, string)>();

        /// <summary>Anyone in the getaway car: an operative, or Vale.</summary>
        public bool AnyInCar { get { foreach (var op in Ops) if (op.InCar) return true; return Vale == ValeAt.Car; } }

        bool HoldsCar(Pt p) => G.Within(p, Car, R.HoldCm) || S.InExitLane(p);
        static bool Up(Hostile h) => !h.Down && h.Gun.St != "break" && h.Gun.St != "gone";

        /// <summary>The holders of the getaway car now, in id order (brief 018 §1): the HUD names them, Go's refusal lists them. Read-only.</summary>
        public List<string> CarHolders()
        {
            var l = new List<string>();
            foreach (var h in Hostiles) if (Up(h) && (h.Present || FightBranch == "safe") && HoldsCar(h.Pos(Tick))) l.Add(h.Id); // a broken rival no longer holds it (Pulse §2.1)
            foreach (var id in CombatantIds())
            {
                if (IsFightHostile(id) || l.Contains(id) || !Combatant(id)) continue;
                var at = PosOf(id); if (at.HasValue && HoldsCar(at.Value)) l.Add(id);
            }
            l.Sort(StringComparer.Ordinal);
            return l;
        }
        /// <summary>A holder still stands (rulebook fight.hold): Go is refused.</summary>
        public bool CarHeld() => CarHolders().Count > 0;

        /// <summary>A combatant still up and not broken, anywhere (a lying-in-wait ambusher counts, as for the hold): the fight is still on.</summary>
        bool FightStillOn()
        {
            foreach (var h in Hostiles) if (Up(h) && (h.Present || FightBranch == "safe")) return true;
            foreach (var id in CombatantIds()) if (!IsFightHostile(id) && Combatant(id)) return true;
            return false;
        }

        /// <summary>Everyone a Go now would leave behind, with their fate and why (brief 018 §3): the Go card's preview and the H11 warning.
        /// Read-only. fate: captured or walked; why: downed, fighting, sealed or walked.</summary>
        public List<(string op, string fate, string why)> LeftBehind()
        {
            var l = new List<(string, string, string)>(); bool fighting = FightStillOn(), sealing = Lockdown != INF;
            foreach (var op in Ops)
            {
                if (op.InCar) continue;
                string name = Sim.Op.Name(op.Id);
                if (op.Down) l.Add((name, "captured", "downed"));
                else if (fighting) l.Add((name, "captured", "fighting"));
                else if (sealing) l.Add((name, "captured", "sealed"));
                else l.Add((name, "walked", "walked"));
            }
            return l;
        }

        /// <summary>Retired by brief 018 (LeftBehind() replaces it): the names a Go now would leave captured. Kept for hosts mid-migration only.</summary>
        [Obsolete("brief 018: LeftBehind() gives every op left behind with fate and why")]
        public List<string> WouldBeCaptured() { var l = new List<string>(); foreach (var x in LeftBehind()) if (x.fate == "captured") l.Add(x.op); return l; }

        // ---------------------------------------------------------------- the orders

        /// <summary>Board (brief 018 §2): into the getaway car, with whoever the operative carries (Vale, or a downed operative), the carried first.</summary>
        string Board(Op op, Order o)
        {
            if (o.Target.Length > 0 && o.Target != "car") return No("target-unknown", $"board names the getaway car (\"car\"), not '{o.Target}'");
            if (op.Running) return No("board-running", "a running operative doesn't board: stop first");
            if (op.Id == OpId.Tech && LoopOn) return No("board-tethered", "the Tech is tethered to the cabinet while the loop holds");
            if (op.CarryBody.Length > 0) return No("already-carrying", "carrying a body: the car seats the cell and the target");
            if (!G.Within(op.Pos, Car, R.AtReachCm)) return No("stand-at-getaway", "stand at the getaway car", cm: R.AtReachCm);
            bool carrying = op.Carrying.HasValue || (op.Id == OpId.Enforcer && Vale == ValeAt.WithEnforcer);
            op.Gun.Order = ""; op.Gun.Force = false; op.Gun.Target = "";
            Engage(op, o, R.BoardS + (carrying ? R.CarryS : 0));
            return "";
        }
        void LandBoard(Op op)
        {
            if (op.Down) return;
            var seat = S.Stand(S.GetawayCar); string name = Sim.Op.Name(op.Id), with = "";
            op.InCar = true; op.Pos = seat; op.Walk = null; op.WalkMm = 0; op.Running = false; op.Gun.Order = ""; op.Gun.Force = false; op.Gun.Target = "";
            if (op.Carrying.HasValue)
            {
                var c = OpOf(op.Carrying.Value); op.Carrying = null; c.CarriedBy = null; c.InCar = true; c.Pos = seat;
                with = " with the " + Sim.Op.Name(c.Id); Chain.Add(Sim.Op.Name(c.Id) + "-in-getaway-car");
            }
            if (op.Id == OpId.Enforcer && Vale == ValeAt.WithEnforcer) { Vale = ValeAt.Car; with = " with Vale"; Chain.Add("vale-in-getaway-car"); }
            Note("board.in", $"The {name} is in the car{with}.");
        }

        /// <summary>A move on a boarded operative (brief 018 §2): board.s to step out at the car's side, then the move. Vale stays in.</summary>
        string StepOut(Op op, Order o)
        {
            Pt to;
            if (o.Point.HasValue) to = o.Point.Value;
            else if (S.HasPlace(o.To)) to = S.Stand(o.To);
            else return No("no-place", $"no place '{o.To}'");
            if (!S.Grid.Free(to)) return No("unwalkable", "that ground can't be walked (a roof, a wall or a solid)");
            if (S.Grid.Route(S.Stand(S.GetawayCar), to) == null) return No("no-walk", "no walk there");
            Engage(op, o, R.BoardS);
            return "";
        }
        void LandStepOut(Op op, Order o)
        {
            if (op.Down || !op.InCar) return;
            op.InCar = false; op.Pos = S.Stand(S.GetawayCar);
            Note("board.out", $"The {Sim.Op.Name(op.Id)} steps out of the car.");
            var why = Move(op, o);
            if (why.Length > 0) Note("order.rejected", $"{o.Op} move {o.To}: {why}");
        }

        /// <summary>Go (brief 018 §2): the car leaves at once with whoever is in it, and the mission ends at this tick. Refused while the car is
        /// held (car-held, its holders' ids in the answer) or empty.</summary>
        string Go(Order o)
        {
            if (o.Op.Length > 0 && o.Op != "cell" && !IsOpId(o.Op)) return No("target-unknown", $"'{o.Op}' gives no Go: the cell or an operative does");
            if (!AnyInCar) return No("car-empty", "nobody is in the car");
            var hs = CarHolders();
            if (hs.Count > 0) return No("car-held", $"the car is held: {string.Join(", ", hs)}", ids: string.Join(",", hs));
            Leave();
            return "";
        }

        /// <summary>The Go card before the click (Latch): would Go be taken now, and if not, why (car-held names the holders in `ids`). Read-only;
        /// LeftBehind() is the card's list of who stays.</summary>
        public Answer GoQuery()
        {
            var saved = refusal; refusal = default; string why;
            try
            {
                if (Over) why = No("mission-over", "the mission is over");
                else if (!AnyInCar) why = No("car-empty", "nobody is in the car");
                else { var hs = CarHolders(); why = hs.Count > 0 ? No("car-held", $"the car is held: {string.Join(", ", hs)}", ids: string.Join(",", hs)) : ""; }
            }
            catch (Exception e) when (!(e is OutOfMemoryException)) { why = No("engine-error", "engine error: " + e.GetType().Name + ": " + e.Message); }
            var a = AnswerOf(why); refusal = saved; return a;
        }

        void Leave()
        {
            SeenLeaving();
            var lb = LeftBehind(); LeftBehindAtGo.AddRange(lb);
            foreach (var (name, fate, why) in lb)
            {
                if (fate == "captured") { Captured.Add(name); Chain.Add(name + "-captured"); Note("captured", $"The {name} is left behind and captured ({why})."); }
                else { Chain.Add(name + "-walks-out"); Note("walked", $"The {name} is left behind on a calm street and walks out."); }
            }
            CarLeftTick = Tick;
            if (Vale == ValeAt.Car) { Result = Outcome.Success; Chain.Add("car-leaves-with-vale"); Note("success", "The car leaves with Vale. The crew escapes."); }
            else { Result = Outcome.Withdrawn; Withdrew(true); Chain.Add("car-leaves-without-vale"); Note("withdraw.car", "The car leaves without Vale: the cell withdraws."); }
            EndOpenFight(); // brief 018 §4: the final fight is judged at the tick the car leaves
            fightClosedLate = true; // Finish replaces a checkpoint already taken at this tick with the state after Go
        }

        /// <summary>Seen leaving (brief 018 §3): one witnessed incident and the car hunted.</summary>
        void SeenLeaving()
        {
            var by = CarWatcher(); if (by.Length == 0) return;
            CarSeenBy = by;
            if (incidents.Add("car-seen")) AddTrail(R.WitnessTrail, "car-seen:" + by);
            Note("car.seen", $"The {by} sees the car leave. The investigation will hunt it.");
        }

        /// <summary>The security body that would see the car leave now, the first by id, or "": the response unit's officers and the final
        /// fight's (their cone, else witness range on a clear line), the response's robots and police (theirs, likewise), the patrol only while
        /// engaged (chasing or answering an alarm). Never the rivals, never the guard. Read-only: the Go card's "+1 T".</summary>
        public string CarWatcher()
        {
            var car = Car; var c = new List<string>();
            bool near(Pt p) => G.Within(p, car, witnessRange) && Sees(p, car);
            for (int k = 0; k < SecGuns.Length; k++)
            {
                if (SecGuns[k].Down) continue; var pose = SecOfficerPose(k); if (!pose.HasValue) continue;
                if (SecOfficerWatching(k, car) || near(pose.Value.pos)) c.Add(SecGuns[k].Id);
            }
            // the final fight's officers watch the fight and the car is where it is: a clear line within their pistol's maximum reach
            // (brief 018 §10, Pulse; the response unit's officers, robots and patrol keep their cones)
            foreach (var h in Hostiles)
            {
                if (IsRival(h.Id) || SecIndex(h.Id) >= 0 || !h.Present || h.Down || h.Gun.St == "gone") continue;
                var p = h.Pos(Tick); if ((G.Within(p, car, R.Pistol.MaxCm) && Sees(p, car)) || near(p)) c.Add(h.Id);
            }
            foreach (var u in Units)
            {
                if (u.Legacy || u.Patrol || !u.OnStreet(Tick) || u.Gun.Down) continue;
                var up = UnitPose(u); if (UnitSees(u, car) || (up.HasValue && near(up.Value.pos))) c.Add(u.Id);
            }
            if (!PatrolDown && PatrolAwayUntil <= Tick && (PatrolChasing || PatrolUnit() != null || IsFightHostile("patrol")))
            {
                var pp = PatrolPose(); if (PatrolWatching(car) || (pp.HasValue && near(pp.Value.pos))) c.Add("patrol");
            }
            c.Sort(StringComparer.Ordinal);
            return c.Count > 0 ? c[0] : "";
        }

        // ---------------------------------------------------------------- the blocker and the car in the fight

        /// <summary>Pick the fight's blockers (rulebook fight.blockers) from these hostiles and send them to the road. Once per fight.</summary>
        void PickBlockers(List<Hostile> cands)
        {
            if (blockersPicked) return; blockersPicked = true;
            // brief 018 §10 (Pulse): each candidate is scored by the grid walk to the post it would take; cover is taken by the winner only
            var scored = new List<(long mm, string id, Hostile h)>();
            foreach (var h in cands)
            {
                if (!Up(h)) continue;
                var from = h.Pos(Tick); var post = BlockPost(from, out _);
                var to = S.Grid.NearestFree(post); if (!to.HasValue) continue;
                var route = S.Grid.Route(S.Grid.NearestFree(from) ?? from, to.Value); if (route == null) continue;
                scored.Add((new Path(route).Length, h.Id, h));
            }
            scored.Sort((a, b) => a.mm != b.mm ? a.mm.CompareTo(b.mm) : string.CompareOrdinal(a.id, b.id));
            for (int i = 0; i < scored.Count && i < R.Blockers; i++)
            {
                var (_, _, h) = scored[i];
                var post = BlockPost(h.Pos(Tick), out var cv); Pt to = cv != null ? post : S.Grid.NearestFree(post) ?? post;
                if (cv != null) TakeCover(h.Gun, cv); else ReleaseCover(h.Gun); // the cover it held before (a joined officer's) is free again
                h.Blocker = true; h.Home = to; MoveTo(h, to); Blockers.Add(h.Id);
                Note("fight.blocker", $"{h.Id} goes for the road ({(cv != null ? "cover at " + cv.Id : "the lane, in the open")}).");
            }
        }
        /// <summary>The blocker's post (brief 018 §10, Pulse): the cover BlockCover gives, else the open lane centreline fight.blockNear along it.</summary>
        Pt BlockPost(Pt from, out CoverPoint? cv) { cv = BlockCover(from); return cv != null ? cv.At : S.LanePointAt(R.BlockNearCm); }
        /// <summary>The free cover point inside the exit lane and between fight.blockNear and fight.blockFar of the car point (straight line, as
        /// the hold), nearest `from` (present, at least partial; ties by id), or null.</summary>
        CoverPoint? BlockCover(Pt from)
        {
            CoverPoint? best = null; long bd = long.MaxValue;
            foreach (var c in S.Cover)
            {
                if (coverTaken.ContainsKey(c.Id) || c.Q < R.CoverQPartial || !c.Present(Tick / Hz) || !S.InExitLane(c.At)) continue;
                if (G.Within(c.At, Car, R.BlockNearCm - 1) || !G.Within(c.At, Car, R.BlockFarCm)) continue; // the ring: not at the door, in the cell's reach
                long d = G.D2(from, c.At);
                if (d < bd || (d == bd && best != null && string.CompareOrdinal(c.Id, best.Id) < 0)) { bd = d; best = c; }
            }
            return best;
        }

        /// <summary>A rival within cell.atReach of the car while Vale is in it, with no operative standing within cell.reach of it (brief 018 §1).</summary>
        bool RivalReachesVale()
        {
            if (Vale != ValeAt.Car) return false;
            bool rival = false;
            foreach (var h in Hostiles) if (IsRival(h.Id) && h.Present && Up(h) && G.Within(h.Pos(Tick), Car, R.AtReachCm)) rival = true;
            if (!rival) return false;
            foreach (var op in Ops) if (!op.Down && !op.InCar && !op.Inside && G.Within(op.Pos, Car, actReach)) return false;
            return true;
        }

        // ---------------------------------------------------------------- the custody projection (the debrief)

        /// <summary>The district's police post a captive is held at: the post (not a staffed door) nearest the car, ties by id. A world with no
        /// police post is rejected (unknown = reject).</summary>
        string PostOfCaptives()
        {
            string best = ""; long bd = long.MaxValue;
            foreach (var (id, at) in S.Posts)
            {
                if (id.StartsWith("door:", StringComparison.Ordinal)) continue;
                long d = G.D2(at, Car);
                if (d < bd || (d == bd && string.CompareOrdinal(id, best) < 0)) { bd = d; best = id; }
            }
            if (best.Length == 0) throw new InvalidOperationException("a captive has no police post to be held at: the world places none (brief 018 §3; unknown = reject)");
            return best;
        }

        /// <summary>Brief 018 §3 in the between-missions phase: the left-behind lines, the car seen, each captive's custody (+captured-trail to
        /// the campaign, the Talker test once per phase held, projected) and what they would give.</summary>
        void Custody(Between b, Func<int, string> fmt)
        {
            foreach (var (op, fate, why) in LeftBehindAtGo) b.Lines.Add(new BetweenLine { Line = "left-behind", Who = op, Detail = $"{fate} ({why})" });
            if (CarSeenBy.Length > 0) { b.CarSeenBy = CarSeenBy; b.Lines.Add(new BetweenLine { Line = "car-seen", Who = CarSeenBy, Detail = $"+{fmt(R.WitnessTrail)} T; the investigation hunts the car (cell-car)" }); }
            if (!LeftBehindAtGo.Exists(x => x.fate == "captured")) return;
            string post = PostOfCaptives();
            var contacts = new List<string>();
            foreach (var p in People) if (p.Turned && !p.Down) contacts.Add(p.Id);
            foreach (var w in Walkers) if (w.P.Turned && !w.P.Down && !contacts.Contains(w.P.Id)) contacts.Add(w.P.Id);
            contacts.Sort(StringComparer.Ordinal);
            string side(int[] sc, int[] ix) { var parts = new List<string>(); foreach (var i in ix) parts.Add(Rules.ScaleNames[i] + " " + R.Step(i, sc[i]) + " " + fmt(sc[i])); return string.Join(" + ", parts); }
            foreach (var (op, fate, why) in LeftBehindAtGo)
            {
                if (fate != "captured") continue;
                var c = new Captive { Op = op, Why = why, HeldAt = post, RescueUntil = R.CustodyMissions };
                Array.Copy(R.CellStart, c.Sc, 4); // the founding cell (brief 018 §3); recruits would keep their own scales
                if (why != "downed") { c.Sc[Rules.Resentment] = R.Clamp(Rules.Resentment, c.Sc[Rules.Resentment] + R.AbandonedResentment); c.Sc[Rules.Loyalty] = R.Clamp(Rules.Loyalty, c.Sc[Rules.Loyalty] - R.AbandonedLoyalty); }
                for (int q = 1; q <= R.CustodyMissions; q++)
                {
                    c.Sc[Rules.Fear] = R.Clamp(Rules.Fear, c.Sc[Rules.Fear] + R.CustodyFear);
                    c.Sc[Rules.Loyalty] = R.Clamp(Rules.Loyalty, c.Sc[Rules.Loyalty] - R.CustodyLoyalty);
                    if (R.IsTalker(c.Sc)) { c.TalksAt = q; break; }
                }
                c.Holds = c.TalksAt > 0 ? c.TalksAt - 1 : R.CustodyMissions;
                foreach (var o in Ops) c.Facts.Add("cell-face:" + Sim.Op.Name(o.Id));
                c.Facts.Add("cell-car"); c.Facts.Add("place-time");
                foreach (var id in contacts) c.Facts.Add("contact:" + id);
                c.Left = side(c.Sc, R.TalkerLeft); c.Right = side(c.Sc, R.TalkerRight);
                b.CampaignTrail += R.CapturedTrail; b.Captives.Add(c);
                b.Lines.Add(new BetweenLine { Line = "captive", Who = op, Detail = $"held at {post}; holds {fmt(c.Holds)} missions; rescue for {fmt(c.RescueUntil)} missions; +{fmt(R.CapturedTrail)} T" });
                if (c.TalksAt > 0) b.Lines.Add(new BetweenLine { Line = "give-up", Who = op, Detail = $"{string.Join(", ", c.Facts)} at questioning {fmt(c.TalksAt)}: {c.Left} > {c.Right}" });
            }
        }

        /// <summary>The getaway's state for the checkpoint hash: no bytes until someone boards, a blocker is picked or the car leaves.</summary>
        internal void HashGetaway(Hash.H h)
        {
            bool any = Blockers.Count > 0 || CarLeftTick != INF || CarSeenBy.Length > 0 || carWasHeld || pickFrom.Length > 0; foreach (var op in Ops) any |= op.InCar;
            if (!any) return;
            foreach (var op in Ops) h.Z(op.InCar);
            foreach (var x in Blockers) h.S(x);
            h.Z(carWasHeld).Z(blockerOut);
            h.I(CarLeftTick).S(CarSeenBy);
            foreach (var (op, fate, why) in LeftBehindAtGo) h.S(op).S(fate).S(why);
        }
    }
}

sim/Suborned.Sim/GameHudReads.cs.text:
// Read-only accessors for the takedown HUD (Glyph, briefs/013/glyph-takedown-hud.md, ask 1; Aster 2026-10-16). Each reads the state the
// engine already holds and changes nothing: no state, no hash moves, no order. The host calls them at will (hover, every frame).
//  · HeldUntil(door): when a held door's hold ends (the units' sweep, then the stand-down), Game.Never at Alert 3, -1 if not held.
//  · StashRoom(stash): the bodies in a stash and how many it holds (the pips).
//  · NextRound(stash): a container's next servicing round, and whether the cell knows it ("?" until it does).
//  · CarryPathSight(op, to): who sees which stretch of a carry walk, by SeenQuote's watcher test, second by second.
//  · NeedRecordOf(person): a person's need as kind, record and label (brief 017 phase 1, for Intel). The truth, not what the cell knows:
//    the host shows the kind's word while the need is only told and the label once learned, by Person.Knows("need") as before.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>One stretch of a carry walk that the same watchers see (CarryPathSight): seconds from the start, where it begins and ends,
    /// and SeenQuote's answer for it.</summary>
    public sealed class CarryStretch
    {
        public int FromS, ToS; public Pt From, To;
        public string Seen = "no";                                     // yes, ?, no (SeenQuote.Seen)
        public readonly List<string> SeenBy = new List<string>();      // known watchers that see it (the true answer)
        public readonly List<string> MaybeSeenBy = new List<string>(); // unknown watchers that could: "?"
    }

    /// <summary>The sight along a carry walk (Glyph §4: "seen on the way: who, n s").</summary>
    public sealed class CarrySight
    {
        public string Refused = "";                                    // why there is no walk ("" when there is one)
        public int S; public int PaceCmS;                              // the whole walk, seconds (rounded up), at the carrier's pace (cm/s)
        public string Seen = "no";                                     // yes if a known watcher sees any of it; ? if only unknown ones could; no
        public readonly List<CarryStretch> Stretches = new List<CarryStretch>();
        public readonly SortedDictionary<string, int> SeenS = new SortedDictionary<string, int>(StringComparer.Ordinal);  // known watcher → seconds seen
        public readonly SortedDictionary<string, int> MaybeS = new SortedDictionary<string, int>(StringComparer.Ordinal); // unknown watcher → seconds it could see
    }

    public sealed partial class Game
    {
        /// <summary>The tick a hold that never ends reports (Alert 3: the units never stand down).</summary>
        public const int Never = INF;

        /// <summary>When the hold on this entrance ends (Glyph §6, the ring to the stand-down): -1 if no unit holds it now; Never at Alert 3;
        /// else the later of the units' sweep at the scene (a check, then its search and the stashes it still has to open) and the stand-down
        /// (response.standDown after the last alarm). A later alarm moves it: this is the answer now.</summary>
        public int HeldUntil(string doorId)
        {
            if (!DoorHeld(doorId)) return -1;
            if (Alert >= 3) return Never;
            int end = lastAlarm < 0 ? Tick : lastAlarm + T(Alert >= 2 ? R.StandDownSearchS : R.StandDownInquiryS);
            if (!SceneHolds.Exists(h => h.Doors.Contains(doorId) && HoldActive(h))) return FixtureHeldUntil(doorId); // test only: held by a start fixture alone (N85)
            foreach (var h in SceneHolds)
            {
                if (!h.Doors.Contains(doorId) || !HoldActive(h)) continue;
                foreach (var u in Units)
                {
                    if (u.Robot || u.Act != h.Act || !u.Scene || u.Gun.Down) continue;
                    int sweep = u.St == "check" ? u.Until + T(R.SearchS) + u.ToOpen.Count * T(R.SearchStashS)
                        : u.St == "search" ? Math.Max(u.Until, u.ToOpen.Count == 0 ? u.Until : u.NextOpen + (u.ToOpen.Count - 1) * T(R.SearchStashS))
                        : -1;
                    end = Math.Max(end, sweep);
                }
            }
            return Math.Max(end, Tick);
        }

        /// <summary>A stash's room (Glyph §5, the pips): the bodies in it now and how many it holds (HoldsOf); (-1, -1) for an unknown id.</summary>
        public (int bodies, int holds) StashRoom(string stashId)
        {
            var s = StashById(stashId); if (s == null) return (-1, -1);
            return (InStash(stashId), HoldsOf(s));
        }

        /// <summary>A container's next servicing round (Pulse §4.1; takedown.service): the first tick from now on which the round opens it
        /// (its phase from the container's id, every service.period), and whether the cell knows it. -1 for a door or an unknown id (a door
        /// has no round). Known once a Scout's Watch on the container has completed this mission (GameStashWatch.cs); until then the HUD
        /// shows "?". Read-only.</summary>
        public (int tick, bool known) NextRound(string stashId)
        {
            var s = StashById(stashId); if (s == null || s.Kind != "container") return (-1, false);
            int period = T(R.ServicePeriodS), phase = (int)(Streams.Fnv1a32(s.Id) % (uint)period);
            int next = Tick + ((phase - Tick % period) % period + period) % period;
            return (next, KnowsRound(s.Id));
        }

        /// <summary>Who sees a carry walk from the carrier to `to` (Glyph §4): the grid route at the carrier's carrying pace (the Enforcer
        /// walks, the others takedown.carry.untrained), sampled once a second of the walk, each sample by SeenAt (SeenQuote's watcher test:
        /// known watchers give the true answer, unknown ones "?"), merged into stretches with the same answer. The watchers as they stand
        /// now: a camera's sweep or the patrol's later place is not forecast. Read-only.</summary>
        public CarrySight CarryPathSight(OpId carrier, Pt to)
        {
            var c = new CarrySight(); var op = OpOf(carrier);
            if (op.Down) { c.Refused = "agent-down"; return c; }
            if (op.Inside) { c.Refused = "enforcer-inside"; return c; }
            var path = RouteOf(op.Pos, to);
            int pace = carrier == OpId.Enforcer ? opSpeed : R.CarryUntrainedSpeed; // mm a tick (= cm/s)
            c.PaceCmS = pace;
            int ticks = (int)((path.Length + pace - 1) / pace); c.S = (ticks + Hz - 1) / Hz;
            CarryStretch? cur = null;
            for (int sec = 0; sec <= c.S; sec++)
            {
                var at = path.At(Math.Min(path.Length, (long)sec * Hz * pace));
                var q = SeenAt(at);
                string key = q.Seen + "|" + string.Join(",", q.SeenBy) + "|" + string.Join(",", q.MaybeSeenBy);
                string curKey = cur == null ? "" : cur.Seen + "|" + string.Join(",", cur.SeenBy) + "|" + string.Join(",", cur.MaybeSeenBy);
                if (cur == null || key != curKey)
                {
                    cur = new CarryStretch { FromS = sec, ToS = sec, From = at, To = at, Seen = q.Seen };
                    cur.SeenBy.AddRange(q.SeenBy); cur.MaybeSeenBy.AddRange(q.MaybeSeenBy);
                    c.Stretches.Add(cur);
                }
                else { cur.ToS = sec; cur.To = at; }
                if (sec == c.S) break; // the last sample is the end of the walk: no second after it
                foreach (var w in q.SeenBy) c.SeenS[w] = (c.SeenS.TryGetValue(w, out var n) ? n : 0) + 1;
                foreach (var w in q.MaybeSeenBy) c.MaybeS[w] = (c.MaybeS.TryGetValue(w, out var n) ? n : 0) + 1;
            }
            c.Seen = c.SeenS.Count > 0 || c.Stretches.Exists(x => x.Seen == "yes") ? "yes" : c.MaybeS.Count > 0 || c.Stretches.Exists(x => x.Seen == "?") ? "?" : "no";
            return c;
        }

        /// <summary>A person's need (brief 017): its kind (Person.Need, what every rule reads), the catalogue record's id and its label
        /// ("Bureau loan"), by id or role, cast or crowd. Null if there is no such person; record and label "" when the host loaded no people
        /// file or the catalogue has no record of the kind. Read-only: the truth, gated by the host on Knows("need").</summary>
        public (string kind, string record, string label)? NeedRecordOf(string idOrRole) => PersonById(idOrRole) is Person p ? NeedRecordOf(p) : ((string, string, string)?)null;
        /// <summary>The same for a person the engine handed out (a contact the debrief carries: Between.Contacts, whose need may be replaced).</summary>
        public (string kind, string record, string label) NeedRecordOf(Person p)
            => (p.Need, p.Record, p.Record.Length > 0 && People2 != null && People2.Records.TryGetValue(p.Record, out var r) ? r.label : "");
    }
}

sim/Suborned.Sim/GameInvestigation.cs.text:
// What the city learns, and what happens before the next mission (brief 011 A, task 3).
// During the mission: every incident keeps its place, time and witnesses; the watchers (the two cameras and the patrol: §05 watchers)
// log any operative they see, with place and time, act or no act; a watcher that logs an operative within approach reach of a contact
// exposes the contact's job (rulebook exposure, Motive's review #12); in a Menace district a sighting counts as a witness report.
// After the mission, for the debrief: the investigation (rulebook investigation, investigator.question) and the between-missions
// events (rulebook phases.between-missions) run on copies of the people, so the mission's state and its checkpoint hashes are untouched.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed class Incident { public int Tick; public string Kind = "", Cause = ""; public Pt At; public readonly List<(Person p, Pt at)> Witnesses = new List<(Person, Pt)>(); }
    public sealed class Sighting { public string Watcher = "", Op = ""; public int From, To; public Pt At; }
    public sealed class Finding { public string Who = "", Outcome = "", Lead = ""; public readonly List<string> Facts = new List<string>(); public string Cause = ""; public int Hop; }
    public sealed class Investigation
    {
        public int Investigators, Hops; public readonly List<Finding> Findings = new List<Finding>(); public readonly HashSet<string> Exposed = new HashSet<string>(StringComparer.Ordinal);
        public string NamedCause = "";
        /// <summary>What the investigation hunts next mission (brief 018 §3, Sky 2026-10-18 answer 5): cell-car when security saw the car leave.</summary>
        public readonly List<string> Hunted = new List<string>();
    }
    public sealed class BetweenLine { public string Line = "", Who = "", Detail = ""; }
    /// <summary>One district's Standing across the mission and the break (brief 014; rulebook standing, debrief.lines.standing): where it
    /// started, where the mission left it, the word, the drift, where the next mission starts, and the line's one cause.</summary>
    public sealed class StandingLine
    {
        public string District = "", Band = "", Cause = "", Who = "";
        public int From, End, Found, Word, WordUncapped, Drift, To; public bool Moved;
