    /// <summary>The seeded streams (rulebook streams): FNV-1a 32 and mulberry32, integer draws; the same as contracts/rules/rulebook.ref.ts.</summary>
    public static class Streams
    {
        public static uint Fnv1a32(string key) { unchecked { uint h = 0x811c9dc5; foreach (var c in key) { h ^= c; h *= 0x01000193; } return h; } }
        public sealed class Mulberry
        {
            uint s;
            public Mulberry(string key) { s = Fnv1a32(key); if (s == 0) s = 1; }
            public uint Next()
            {
                unchecked
                {
                    s += 0x6d2b79f5; uint t = s;
                    t = (t ^ (t >> 15)) * (t | 1);
                    t ^= t + (t ^ (t >> 7)) * (t | 61);
                    return t ^ (t >> 14);
                }
            }
        }
        /// <summary>x = floor(u × total ÷ 2^32); walk the items in order subtracting each weight.</summary>
        public static T Draw<T>(string key, IReadOnlyList<(T item, int weight)> items)
        {
            if (items.Count == 0) throw new ArgumentException("nothing to draw");
            long total = 0; foreach (var i in items) { if (i.weight <= 0) throw new ArgumentException("weights are positive"); total += i.weight; }
            long x = (long)(((ulong)new Mulberry(key).Next() * (ulong)total) >> 32);
            foreach (var i in items) { x -= i.weight; if (x < 0) return i.item; }
            return items[items.Count - 1].item;
        }
    }

    public sealed partial class Game
    {
        public readonly List<Incident> Incidents = new List<Incident>();
        public readonly List<Sighting> Sightings = new List<Sighting>();
        public readonly SortedSet<string> ExposedByWatcher = new SortedSet<string>(StringComparer.Ordinal);
        readonly Dictionary<string, Sighting> openSighting = new Dictionary<string, Sighting>(StringComparer.Ordinal);

        Incident AddIncident(string kind, string cause, Pt at, IEnumerable<(Person p, Pt at)>? witnesses = null)
        {
            var i = new Incident { Tick = Tick, Kind = kind, Cause = cause, At = at };
            if (witnesses != null) i.Witnesses.AddRange(witnesses);
            Incidents.Add(i); return i;
        }
        List<(Person p, Pt at)> WitnessesWithPos(Pt at, Person? except)
        {
            var seen = new List<(Person, Pt)>();
            foreach (var (p, wp) in OnTheStreet()) { if (p == except) continue; if (G.Within(wp, at, witnessRange) && Sees(wp, at)) seen.Add((p, wp)); }
            return seen;
        }

        /// <summary>§05 watchers, once a second: each live watcher logs every operative in its sightline, as spans of place and time.</summary>
        void Watchers()
        {
            if (Tick % Hz != 0) return;
            var world = new List<string>(); foreach (var c in S.Cameras) if (c.World) world.Add(c.Id); // the city's own cameras (brief 013), after the mission's
            for (int w = 0; w < 3 + world.Count; w++)
            {
                string id = w == 0 ? "camera:entrance" : w == 1 ? "camera:pickup" : w == 2 ? "patrol" : "camera:" + world[w - 3];
                foreach (var op in Ops)
                {
                    if (op.Inside) continue;
                    bool sees = w == 0 ? CameraWatching("entrance", op.Pos) : w == 1 ? CameraWatching("pickup", op.Pos) : w == 2 ? PatrolWatching(op.Pos) : CameraWatching(world[w - 3], op.Pos);
                    string key = id + "/" + Sim.Op.Name(op.Id);
                    if (!sees) { openSighting.Remove(key); continue; }
                    foreach (var c in People) // a logged operative beside a contact, at any second of the sighting, ties the contact to the cell (rulebook exposure)
                    {
                        if (!c.Turned || c.Down) continue;
                        var cp = PersonPos(c); if (cp.HasValue && G.Within(cp.Value, op.Pos, R.ApproachReachCm)) ExposedByWatcher.Add(c.Role);
                    }
                    if (openSighting.TryGetValue(key, out var s) && s.To == Tick - Hz) { s.To = Tick; continue; }
                    var n = new Sighting { Watcher = id, Op = Sim.Op.Name(op.Id), From = Tick, To = Tick, At = op.Pos };
                    Sightings.Add(n); openSighting[key] = n;
                    if (R.BandOf(Standing) == Band.Menace) // §05: in a Menace district a sighting counts as a witness report
                    {
                        Reported++;
                        RaiseAlert(R.AlertByIncident[Math.Min(Reported, R.AlertByIncident.Length) - 1], "sighting:" + id);
                        AddIncident("report", "sighting:" + id, op.Pos);
                    }
                }
            }
        }

        // ------------------------------------------------------------------ after the mission

        /// <summary>The investigation (rulebook investigation; investigator.question), worked from the leads at the end of the mission.</summary>
        public Investigation Investigate()
        {
            if (EndOpenFight()) fightClosedLate = true; // the mission is over: a fight still open ends with it (fight.public)
            var inv = new Investigation();
            if (CarSeenBy.Length > 0) inv.Hunted.Add("cell-car"); // brief 018 §3: the car seen leaving is hunted, whatever the Trail
            if (Trail < R.TrailOpen) return inv;
            inv.Investigators = R.InvestigatorsBase + R.InvestigatorsPerAlert * Alert;
            inv.Hops = inv.Investigators * R.InvestigatorHops;
            // leads: incidents with their witnesses, and the watchers' sightings (witnesses: who stood within range of the place then)
            var leads = new List<(int tick, int seq, string what, Pt at, List<(Person p, Pt at)> who)>();
            int seq = 0;
            foreach (var i in Incidents) leads.Add((i.Tick, seq++, "incident:" + i.Cause, i.At, new List<(Person, Pt)>(i.Witnesses)));
            foreach (var s in Sightings) leads.Add((s.From, seq++, "sighting:" + s.Watcher + ":" + s.Op, s.At, PeopleNear(s.At, s.From)));
            var spent = new HashSet<int>(); var asked = new HashSet<Person>();
            for (int hop = 1; hop <= inv.Hops; hop++)
            {
                int pick = -1;
                for (int k = 0; k < leads.Count; k++)
                {
                    if (spent.Contains(leads[k].seq)) continue;
                    if (pick < 0 || leads[k].tick > leads[pick].tick || (leads[k].tick == leads[pick].tick && leads[k].seq > leads[pick].seq)) pick = k;
                }
                if (pick < 0) break;
                var lead = leads[pick];
                var who = lead.who.FindAll(x => !asked.Contains(x.p) && !x.p.Down);
                who.Sort((a, b) => { long da = G.D2(a.at, lead.at), db = G.D2(b.at, lead.at); return da != db ? da.CompareTo(db) : string.CompareOrdinal(a.p.Id, b.p.Id); });
                if (who.Count == 0) { spent.Add(lead.seq); inv.Findings.Add(new Finding { Hop = hop, Who = "", Outcome = "no-one-to-ask", Lead = lead.what }); continue; }
                if (who.Count == 1) spent.Add(lead.seq);
                var p = who[0].p; asked.Add(p);
                var f = Question(p, lead.what); f.Hop = hop;
                if (f.Outcome == "gives" || f.Outcome == "volunteers") // volunteers: a reporter (brief 013)
                {
                    foreach (var m in p.Memory) // each fact's place and time becomes a lead (one step up the chain, §02)
                    {
                        if (m.Act == "told") continue;
                        var at = PlaceAt(m.Place, p);
                        leads.Add((m.Tick, seq++, "told-by:" + f.Who + ":" + m.Act, at, PeopleNear(at, m.Tick)));
                    }
                    if (inv.NamedCause.Length == 0 && f.Facts.Contains(R.FaceFact.TryGetValue("fixer", out var face) ? face : "fixer-face")) inv.NamedCause = "named-witness:" + f.Who;
                }
                if (p.Turned && p.Role.Length > 0) inv.Exposed.Add(p.Role);
                inv.Findings.Add(f);
            }
            return inv;
        }

        /// <summary>What this person would tell an investigator now (rulebook investigator.question): the outcome, the facts and, for a
        /// Talker, the cause in words. Read-only; Investigate asks each person it reaches exactly this, so a scenario can test the Talker
        /// rule on a person whether or not the investigation's hops reach them.</summary>
        public Finding Question(Person p, string lead = "")
        {
            var ev = R.Ev("investigator.question");
            var outcome = FirstOutcome(ev, Ctx(p, ev)).Id; // holds-nothing, gives, lies, nothing: the rulebook's event decides
            var f = new Finding { Who = p.Role.Length > 0 ? p.Role : p.Id, Outcome = outcome, Lead = lead };
            if (outcome == "gives") { foreach (var fact in FactsOf(p)) f.Facts.Add(fact); f.Cause = TalkerCause(p); }
            else if (outcome == "volunteers") foreach (var fact in FactsOf(p)) f.Facts.Add(fact); // a reporter gives what they hold, no Talker test (brief 013)
            else if (outcome == "lies") f.Facts.Add(R.BandOf(Standing) == Band.Hero ? R.LieGivesHero : R.LieGivesOtherwise);
            return f;
        }

        /// <summary>§04 Talker test in words: "fear afraid 2 + resentment resentful 1 > bravery helper 1 + loyalty none 0" (Motive K7).</summary>
        string TalkerCause(Person p)
        {
            string side(int[] ix) { var parts = new List<string>(); foreach (var i in ix) parts.Add(Rules.ScaleNames[i] + " " + R.Step(i, p.Sc[i]) + " " + p.Sc[i].ToString(System.Globalization.CultureInfo.InvariantCulture)); return string.Join(" + ", parts); }
            return side(R.TalkerLeft) + " > " + side(R.TalkerRight);
        }
        public List<string> FactsOf(Person p)
        {
            var o = new List<string>();
            void add(string f) { if (!o.Contains(f)) o.Add(f); }
            foreach (var m in p.Memory) { if (m.Act == "told") continue; add("place-time"); foreach (var af in R.ActFacts[m.Act]) add(af); if (R.FaceFact.TryGetValue(m.By, out var ff)) add(ff); } // the act's facts (brief 013: enforcer-face), then the face of who did it
            foreach (var m in p.Memory) if (m.Act == "told" && m.Told != null) foreach (var f in m.Told.Split('|')) if (f.Length > 0) add(f);
            o.Sort((a, b) => R.Facts.IndexOf(a).CompareTo(R.Facts.IndexOf(b)));
            return o;
        }
        Pt PlaceAt(string place, Person p)
        {
            if (S.HasPlace(place)) return S.Stand(place);
            if (People2 != null && People2.Places.TryGetValue(place, out var c)) return c;
            return PersonPos(p) ?? S.Stand(S.GuardPost);
        }
        /// <summary>The simulated people within witness range of `at` at tick `t` on a clear sightline: the crowd where their routine had
        /// them, the cast where they stand for the mission.</summary>
        List<(Person p, Pt at)> PeopleNear(Pt at, int t)
        {
            var o = new List<(Person, Pt)>();
            foreach (var p in People) { var pp = PersonPos(p); if (pp.HasValue && G.Within(pp.Value, at, witnessRange) && Sees(pp.Value, at)) o.Add((p, pp.Value)); }
            if (People2 != null && Start.Crowd) foreach (var w in Walkers) { var wp = CrowdPos(w, t); if (wp.HasValue && G.Within(wp.Value, at, witnessRange) && Sees(wp.Value, at)) o.Add((w.P, wp.Value)); }
            return o;
        }

        /// <summary>The between-missions events (rulebook phases.between-missions), in their order, on copies of the people: what the next
        /// mission inherits, as debrief lines with causes (K7, §08). `mission` is this mission's number in the campaign (the Handover: 1).</summary>
        public Between BetweenMissions(Investigation inv, int mission = 1)
        {
            var b = new Between();
            var copies = new Dictionary<Person, Person>();
            Person C(Person p)
            {
                if (copies.TryGetValue(p, out var c)) return c;
                c = new Person { Role = p.Role, Id = p.Id, Name = p.Name, Temperament = p.Temperament, Need = p.Need, Job = p.Job, Turned = p.Turned, NeedMet = p.NeedMet, Down = p.Down, KRoutine = p.KRoutine, KNeed = p.KNeed, KTemperament = p.KTemperament, Place = p.Place, Suspected = p.Suspected, Record = p.Record, Size = p.Size, Holder = p.Holder };
                Array.Copy(p.Sc, c.Sc, 4); c.Memory.AddRange(p.Memory); foreach (var a in p.KnownRefused) c.KnownRefused.Add(a);
                copies[p] = c; return c;
            }
            var everyone = new List<Person>(People); foreach (var w in Walkers) everyone.Add(w.P);
            everyone.Sort((x, y) => string.CompareOrdinal(x.Id, y.Id));
            var byId = new Dictionary<string, Person>(StringComparer.Ordinal); foreach (var p in everyone) byId[p.Id] = p;
            void line(string l, Person who, string detail) => b.Lines.Add(new BetweenLine { Line = l, Who = who.Role.Length > 0 ? who.Role : who.Id, Detail = detail });
            string fmt(int v) => v.ToString(System.Globalization.CultureInfo.InvariantCulture);

            // ladder.job: each job done this mission, exposed or not (rulebook exposure: questioned, or a watcher logged an operative beside them)
            foreach (var p in everyone)
            {
                if (!p.Turned || p.Down) continue;
                foreach (var m in p.Memory)
                {
                    if (m.Act != "job") continue;
                    var c = C(p); bool exposed = ExposedByWatcher.Contains(p.Role) || inv.Exposed.Contains(p.Role);
                    string move = exposed ? "job-exposed" : "job-unexposed";
                    var (k, by) = R.Ladders[move][0];
                    int was = c.Sc[k]; foreach (var (kk, bb) in R.Ladders[move]) c.Sc[kk] = R.Clamp(kk, c.Sc[kk] + bb);
                    line("ladder", p, $"{move}: {Rules.ScaleNames[k]} {R.Step(k, was)} → {R.Step(k, c.Sc[k])}");
                }
            }
            // contact.informs, mercenary.sells: one ambush in the next mission however many (Motive's review #4)
            foreach (var p in everyone)
            {
                if (!p.Turned || p.Down) continue;
                var c = C(p);
                if (c.Sc[Rules.Resentment] >= R.ScaleMax[Rules.Resentment]) { b.Ambush = true; b.AmbushBy.Add(c.Role.Length > 0 ? c.Role : c.Id); line("informer", p, "resentment " + R.Step(Rules.Resentment, c.Sc[Rules.Resentment]) + ": sells a route; an ambush is scheduled"); }
                else if (c.Temperament == "mercenary" && R.BandOf(Standing) == Band.Menace && c.Sc[Rules.Loyalty] <= R.ScaleMin[Rules.Loyalty]) { b.Ambush = true; b.AmbushBy.Add(c.Role.Length > 0 ? c.Role : c.Id); line("sold", p, "a Mercenary in a Menace district who owes the cell nothing sells a route"); }
            }
            // debtor.lapses: a met debt ends the ties that carried it
            var ties = People2?.Ties;
            foreach (var p in everyone)
            {
                if (!p.NeedMet || p.Need != "debt" || ties == null || !ties.TryGetValue(p.Id, out var ts)) continue;
                foreach (var (kind, with) in ts) if (kind == "debtor") line("tie-lapsed", p, "debtor tie to " + with + ": the debt is cleared");
            }
            // need.replaced (Sky Q2): from the person's own stream, {person}/need/{mission}
            foreach (var p in everyone)
            {
                if (!p.NeedMet) continue;
                var c = C(p); string old = c.Need;
                c.Need = ReplacementNeed(c, mission); c.NeedMet = false;
                if (People2 != null) { c.Record = People2.DefaultRecord(c.Need); c.Size = c.Record.Length > 0 ? People2.Records[c.Record].size : ""; c.Holder = c.Record.Length > 0 ? "beyond" : ""; } // brief 017 phase 1: the kind's record, no draw
                if (c.Turned) c.KNeed = true; else c.KNeed = false;
                line("need-replaced", p, $"{old} → {c.Need}{(c.Turned ? " (told free: a contact)" : " (Listen again)")}");
            }
            // word.passes (K3, Sky Q6): facts, never opinion, along family and workmate ties, one hop; an obliged contact keeps quiet
            if (ties != null)
                foreach (var p in everyone)
                {
                    var facts = FactsOfWitnessed(p);
                    if (facts.Count == 0 || C(p).Sc[Rules.Loyalty] >= R.WordQuietLoyalty || !ties.TryGetValue(p.Id, out var ts)) continue;
                    foreach (var (kind, with) in ts)
                    {
                        if ((kind != "family" && kind != "workmate") || !byId.TryGetValue(with, out var q)) continue;
                        var cq = C(q); var held = FactsOf(cq); var add = facts.FindAll(f => !held.Contains(f));
                        if (add.Count == 0) continue;
                        cq.Memory.Add(new Mem { Act = "told", By = p.Id, Place = cq.Place, Tick = Tick, Witnessed = false, Told = string.Join("|", add) });
                        line("word", p, $"tells {(q.Role.Length > 0 ? q.Role : q.Id)} ({kind}): {string.Join(", ", add)}");
                    }
                }
            // standing.word (brief 014): each person the cell helped, pressured or knocked out, alive, with a tie of a kind in standing.word.ties,
            // tells them how a stranger treated them: a feeling, never a fact, so no memory or knowledge moves; harm outranks help
            var word = new List<(int delta, string cause, string who)>();
            foreach (var p in everyone)
            {
                var done = DoneTo(p);
                if (done.Count == 0 || !Alive(p) || ties == null || !ties.TryGetValue(p.Id, out var wts) || !wts.Exists(t => R.WordTies.Contains(t.Item1))) continue;
                string how = done.Contains("pressured") ? "pressured" : done.Contains("knocked-out") ? "knocked-out" : "helped";
                int d = how == "helped" ? R.WordStandingStep : -R.WordStandingStep;
                word.Add((d, "word-" + how, Who(p))); b.Word.Add((Who(p), how == "helped" ? "hero" : "menace"));
            }
            // contact.introduces: who each contact could introduce (the pick is the player's order in the debrief)
            if (ties != null)
                foreach (var p in everyone)
                {
                    if (!p.Turned || p.Down || !ties.TryGetValue(p.Id, out var ts)) continue;
                    var can = new List<string>();
                    foreach (var (kind, with) in ts) if (R.TieIntroduces.TryGetValue(kind, out var intro) && intro && byId.TryGetValue(with, out var q) && !q.Turned && !q.Has(R.RefusedAct)) can.Add(with + " (" + kind + ")");
                    if (can.Count > 0) line("introduced", p, "can introduce " + string.Join(", ", can) + ", up to " + fmt(R.IntroductionsPerContact) + " (the player's pick)");
                }
            Takedowns(b, C, byId, line, fmt);
            Custody(b, fmt); // brief 018 §3: who was left behind, the car seen, each captive (GameGetaway.cs)
            StandingNext(b, word, fmt);
            foreach (var p in everyone) if (p.Turned) b.Contacts.Add(C(p));
            return b;
        }

        /// <summary>standing.done-to: what the cell did to the person this mission that their word carries (rulebook DoneTo): a Help that landed
        /// (memory help, any outcome), a Pressure that landed (memory pressure), a knockout that landed (a takedown ko, not a Take or a kill).</summary>
        List<string> DoneTo(Person p)
        {
            var o = new List<string>();
            if (p.Has(R.HelpedAct)) o.Add("helped");
            if (p.Has("pressure")) o.Add("pressured");
            if (Acts.Exists(a => a.P == p && !a.Take && !a.Kill && a.Lead != null)) o.Add("knocked-out");
            return o;
        }
        /// <summary>standing.alive: not killed by a takedown that landed (so not missing either) and not shot down; a knocked-out body lives.</summary>
        bool Alive(Person p)
        {
            if (Acts.Exists(a => a.P == p && !a.Take && a.Kill && a.Lead != null)) return false;
            if (!p.Down) return true;
            var body = BodyOf(p); return body != null && !body.Dead;
        }

        /// <summary>The district's Standing for the next mission (rulebook standing; standing.word, standing.drift) and its one debrief line.
        /// The Handover plays in one district (sim/data/handover.provisional.json district), so one line.</summary>
        void StandingNext(Between b, List<(int delta, string cause, string who)> word, Func<int, string> fmt)
        {
            var l = new StandingLine { District = S.District, From = StandingAtStart, End = Standing, Found = b.CampaignStanding };
            foreach (var m in StandingMoves) l.Moves.Add((m.delta, m.cause, m.who));
            foreach (var v in b.FoundAfter) l.Moves.Add((R.FoundKillStanding, "found-killing", v)); // a killing found after the mission (bodies.surface)
            int sum = 0; foreach (var w in word) { sum += w.delta; l.Moves.Add(w); }
            l.WordUncapped = sum; l.Word = Math.Max(-R.WordStandingCap, Math.Min(R.WordStandingCap, sum));
            l.Moved = l.Moves.Count > 0;
            int at = l.End + l.Found + l.Word;
            if (!l.Moved) { int gap = R.StandingStart - at; l.Drift = Math.Sign(gap) * Math.Min(R.StandingDrift, Math.Abs(gap)); }
            l.To = at + l.Drift;
            l.Band = Rules.BandId(R.BandOf(l.To));
            // the cause: the one that moved it most toward the net change (earliest on a tie); balanced when the moves cancel; else the drift
            int net = l.To - l.From - l.Drift;
            if (!l.Moved) { l.Cause = l.Drift < 0 ? "drift-down" : l.Drift > 0 ? "drift-up" : "steady"; }
            else if (net == 0) l.Cause = "balanced";
            else
            {
                var order = new List<string>(); var by = new Dictionary<string, int>(StringComparer.Ordinal); var first = new Dictionary<string, string>(StringComparer.Ordinal);
                foreach (var (d, c, w) in l.Moves) { if (!by.ContainsKey(c)) { by[c] = 0; order.Add(c); first[c] = w; } by[c] += d; }
                int best = 0; foreach (var c in order) { int v = by[c] * Math.Sign(net); if (v > best) { best = v; l.Cause = c; l.Who = first[c]; } }
            }
            if (!R.StandingCauses.Contains(l.Cause)) throw new InvalidOperationException($"standing cause '{l.Cause}' is not in the rulebook");
            b.Standing.Add(l);
            string sg(int v) => (v > 0 ? "+" : "") + fmt(v);
            b.Lines.Add(new BetweenLine { Line = "standing", Who = l.Who, Detail = $"{l.District}: {sg(l.From)} → {sg(l.To)} {l.Band} ({l.Cause}{(l.Who.Length > 0 ? ": " + l.Who : "")}; mission {sg(l.End - l.From)}, found {sg(l.Found)}, word {sg(l.Word)}{(l.Word != l.WordUncapped ? " of " + sg(l.WordUncapped) : "")}, drift {sg(l.Drift)})" });
        }

        /// <summary>Brief 013's between-missions events, in the phase order (bodies.surface, body.grieved, missing.worried, area.hardens,
        /// cases.count): a hidden killing is a missing person, an open or found one a found killing; a knockout still down comes home and
        /// gives a statement; ties grieve or worry; the block hardens; the cases set the district's next level. On copies, as the rest.</summary>
        void Takedowns(Between b, Func<Person, Person> C, Dictionary<string, Person> byId, Action<string, Person, string> line, Func<int, string> fmt)
        {
            if (!Acts.Exists(x => !x.Take)) { b.NextLevel = S.SecurityLevel; return; } // a Take seen is an incident, never a body
            var found = new List<TdAct>(); var missing = new List<TdAct>();
            foreach (var a in Acts)
            {
                if (a.Take) continue;
                var body = BodyOf(a.P);
                string where = a.Scene.ToString();
                if (a.Kill)
                {
                    bool hidden = body != null && !body.Open && !a.Confirmed;
                    if (hidden) { missing.Add(a); b.CampaignTrail += R.MissingTrail; line("missing", a.P, $"{(body!.Stash)}: {fmt(R.MissingTrail)} T, no Menace; the case stays open until the body is found"); }
                    else
                    {
                        found.Add(a);
                        if (!a.ActTrail) { b.CampaignTrail += R.HitTrail + R.DownTrail + R.KillTrail; line("case", a.P, $"found after the mission where he lay: {fmt(R.HitTrail + R.DownTrail + R.KillTrail)} T"); }
                        if (!a.StandingPaid) { b.CampaignStanding += R.FoundKillStanding; b.FoundAfter.Add(Who(a.P)); }
                    }
                    continue;
                }
                if (body != null && body.P.Down && !a.Statement) // a knockout still down at the end: he comes home and gives a statement (Motive §3.2)
                {
                    var c = C(a.P);
                    c.Sc[Rules.Fear] = R.Clamp(Rules.Fear, c.Sc[Rules.Fear] + 1); if (a.Aware) c.Sc[Rules.Resentment] = R.Clamp(Rules.Resentment, c.Sc[Rules.Resentment] + 1);
                    if (!a.ActTrail) b.CampaignTrail += R.HitTrail + R.DownTrail;
                    line("statement", a.P, $"comes home: place and time{(a.Aware ? " and the Enforcer's face" : "")}; {fmt(a.ActTrail ? 0 : R.HitTrail + R.DownTrail)} T");
                }
            }
            // ties: grief for a found killing (a turned contact takes the saw-violence move; everyone else fear +1), worry for a missing person
            void ties(TdAct a, string what)
            {
                if (People2 == null || !People2.Ties.TryGetValue(a.P.Id, out var ts)) return;
                var ids = new List<string>(); foreach (var (k, id) in ts) if (R.CloseTies.Contains(k) && !ids.Contains(id)) ids.Add(id);
                ids.Sort(StringComparer.Ordinal);
                foreach (var id in ids)
                {
                    if (!byId.TryGetValue(id, out var q)) continue;
                    var c = C(q);
                    if (what == "grief" && q.Turned) { foreach (var (k, by) in R.Ladders["saw-violence"]) c.Sc[k] = R.Clamp(k, c.Sc[k] + by); line("grief", q, $"{Who(a.P)}: saw-violence"); }
                    else { c.Sc[Rules.Fear] = R.Clamp(Rules.Fear, c.Sc[Rules.Fear] + R.MissingTiesFear); line(what, q, $"{Who(a.P)}: fear +{fmt(R.MissingTiesFear)}"); }
                }
            }
            foreach (var a in found) ties(a, "grief");
            foreach (var a in missing) ties(a, "worry");
            foreach (var a in found) { b.AreaWatch.Add((a.Scene.ToString(), R.AreaWatchStep, R.AreaWatchStep, R.AreaWatchMissions)); b.Cases.Add((Who(a.P), "found-killing", a.Scene.ToString(), R.CaseCloseMissions)); }
            foreach (var a in missing) { b.AreaWatch.Add((a.Scene.ToString(), R.AreaWatchStep, R.AreaWatchStep, R.AreaWatchMissions)); b.Cases.Add((Who(a.P), "missing", a.Scene.ToString(), -1)); }
            foreach (var w in b.AreaWatch) b.Lines.Add(new BetweenLine { Line = "area-watch", Who = "", Detail = $"{w.place}: +{fmt(w.guards)} guard, +{fmt(w.cameras)} camera for {fmt(w.missions)} missions" });
            b.OpenCases = b.Cases.Count;
            b.NextLevel = Math.Min(4, Math.Min(S.SecurityBase + R.CaseLevelCap, S.SecurityBase + b.OpenCases / R.CasesPerLevel));
            foreach (var c in b.Cases) b.Lines.Add(new BetweenLine { Line = "case", Who = c.who, Detail = c.kind == "missing" ? "missing: open until the body is found" : $"found killing: closes after {fmt(c.missions)} missions" });
        }

        List<string> FactsOfWitnessed(Person p)
        {
            var o = new List<string>();
            foreach (var m in p.Memory) { if (m.Act == "told") continue; if (!o.Contains("place-time")) o.Add("place-time"); foreach (var af in R.ActFacts[m.Act]) if (!o.Contains(af)) o.Add(af); if (R.FaceFact.TryGetValue(m.By, out var f) && !o.Contains(f)) o.Add(f); }
            return o;
        }

        /// <summary>need.replaced's draw: people.rules needs in order, `requires` met, metBy ∩ respondsTo, never the need just met; equal weights
        /// until the people export carries each person's cast-row need weights (Splice; rulebook streams.weights).</summary>
        string ReplacementNeed(Person p, int mission)
        {
            var t = R.Temp(p.Temperament); var ties = People2?.Ties; var myTies = ties != null && ties.TryGetValue(p.Id, out var ts) ? ts : new List<(string, string)>();
            bool home = People2 != null && People2.HasHome.TryGetValue(p.Id, out var h) && h, work = People2 != null && People2.HasWork.TryGetValue(p.Id, out var wk) && wk;
            var cands = new List<(string item, int weight)>();
            foreach (var id in R.NeedIds)
            {
                if (id == p.Need) continue;
                var n = R.Needs[id];
                bool ok = n.Requires switch { "nothing" => true, "home" => home, "work" => work, "family-tie" => myTies.Exists(x => x.Item1 == "family"), "rival-tie" => myTies.Exists(x => x.Item1 == "rival"), _ => false };
                bool acts = false; foreach (var a in n.MetBy) if (t.RespondsTo.Contains(a)) acts = true;
                if (ok && acts) cands.Add((id, 1));
            }
            if (cands.Count == 0) return p.Need;
            var key = R.StreamKeys["need-replace"].Replace("{person}", p.Id).Replace("{mission}", mission.ToString(System.Globalization.CultureInfo.InvariantCulture));
            return Streams.Draw(key, cands);
        }
    }
}

sim/Suborned.Sim/GameOrders.cs.text:
// Orders: each is checked when given (a rejected order changes nothing and is logged with its reason), takes its time, and lands at
// its end. Turn, Watch and Listen run from the rulebook's events (needs, price lines, outcomes, also, witnesses); the other verbs
// read their numbers from the rulebook's `cell` section and the mission's from the site.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed partial class Game
    {
        /// <summary>Give an order now (its tick must be the game's tick). Returns whether it was taken and, if not, a stable refusal code
        /// (Fable's `locks`, contracts/missions/handover/text.json), the engine's words for the log, and the numbers a line needs.
        /// Deconstructs as (ok, why) or (ok, code, why).</summary>
        public Answer Issue(Order o)
        {
            if (o.Tick != Tick) throw new InvalidOperationException($"order for tick {o.Tick} given at tick {Tick}");
            string why; refusal = default;
            try { why = Over ? No("mission-over", "the mission is over") : Check(o); }
            catch (Exception e) when (!(e is OutOfMemoryException)) { why = No("engine-error", "engine error: " + e.GetType().Name + ": " + e.Message); }
            bool ok = why.Length == 0;
            var a = AnswerOf(why);
            if (!ok && a.code == "uncoded") throw new InvalidOperationException($"a refusal without a code: {why}"); // every refusal says its code (Fable)
            Orders.Add((o, ok, a.code, why));
            if (!ok) Note("order.rejected", $"{o.Op} {o.Do} {o.Target}{o.To}: {why}");
            return a;
        }
        public bool Do(Order o) => Issue(o).ok;

        (string? code, int m, int cm, long usd, int tick, string ids) refusal;
        /// <summary>A refusal: its stable code and its numbers (m, cm, usd, tick; -1 when it has none), the ids it names (car-held's holders),
        /// and the words for the log.</summary>
        string No(string code, string why, int m = -1, int cm = -1, long usd = -1, int tick = -1, string ids = "")
        {
            if (Array.IndexOf(Answer.Codes, code) < 0) throw new InvalidOperationException($"refusal code '{code}' is not in Answer.Codes");
            refusal = (code, m, cm, usd, tick, ids); return why;
        }
        /// <summary>The answer for these words: taken when empty, else the refusal No() recorded.</summary>
        Answer AnswerOf(string why) => why.Length == 0 ? new Answer { ok = true, code = "", why = "", m = -1, cm = -1, usd = -1, tick = -1, ids = "" }
            : new Answer { ok = false, code = refusal.code ?? "uncoded", why = why, m = refusal.m, cm = refusal.cm, usd = refusal.usd, tick = refusal.tick, ids = refusal.ids ?? "" };
        /// <summary>A rulebook need that does not hold, as its own code (Fable): the knowledge a Turn or Listen needs, the need it acts on,
        /// a refusal remembered, a contact or not, and cash for the worst case (with the worst case in usd).</summary>
        string NeedsNo(Cond c, PCtx x)
        {
            string why = $"needs {Describe(c)}";
            switch (c.K)
            {
                case "known": return No("needs-" + c.S("what"), why);
                case "requires": { var req = R.ApproachRequires(c.S("approach")); return No(req == "need" ? "needs-need" : req == "temperament" ? "needs-temperament" : "needs-routine", why); }
                case "leverage": return No("no-leverage", why);
                case "need-met-by": return No("no-act-need", why);
                case "need-met": return No("need-met", why);
                case "memory": return No("refusal-remembered", why);
                case "turned": return No(c.B("is") ? "not-a-contact" : "already-turned", why);
                case "cash-covers": return No("no-cash", why, usd: Quote(x.Ev, x.P).WorstUsd);
                default: return No("needs-" + c.K, why);
            }
        }

        string Check(Order o)
        {
            if (o.Do == "withdraw") { Result = Outcome.Withdrawn; Withdrew(false); Note("withdraw", "The cell withdraws. The attempt ends."); return ""; }
            if (o.Do == "panic") return Panic(o);
            if (o.Do == "go") return Go(o); // brief 018: anyone, from the car's card (GameGetaway.cs)
            var op = OpOf(Sim.Op.Parse(o.Op));
            if (op.Down) return No("agent-down", $"the {o.Op} is down");
            if (o.Do == "cancel") return Cancel(op); // before the inside and busy checks: cancel stops exactly those
            if (op.Inside) return No("enforcer-inside", "the Enforcer is inside the Office");
            if (o.Do == "drive") return Drive(op, o); // brief 025 (EXPERIMENTAL): before the busy check, since moving a busy agent is the step's to judge (cell.drive.onBusy)
            if (op.Busy != null) return No("agent-busy", $"{o.Op} is busy until {op.BusyEnd}", tick: op.BusyEnd);
            if (op.InCar) // brief 018: a move steps out first; a stance, holster or cease changes nothing on the street; the rest waits for stepping out
            {
                if (o.Do == "move") return StepOut(op, o);
                if (o.Do != "stance" && o.Do != "holster" && o.Do != "cease") return No("in-car", $"the {o.Op} is in the car: a move steps out first");
            }
            switch (o.Do)
            {
                case "move": return Move(op, o);
                case "watch": case "listen": return Scout(op, o);
                case "turn": return Turn(op, o);
                case "call": return Call(op, o);
                case "loop": return Loop(op, o);
                case "reroute": return Reroute(op, o);
                case "mislead": return Mislead(op, o);
                case "fire": return Fire(op, o);
                case "draw": return Draw(op, o);
                case "holster": return Holster(op, o);
                case "cease": return Cease(op, o);
                case "stance": return Stance(op, o);
                case "carry": return Carry(op, o);
                case "enter": return Enter(op, o);
                case "take": return Take(op, o);
                case "board": return Board(op, o); // brief 018 (GameGetaway.cs); extract is retired
                case "takedown": return Takedown(op, o);   // brief 013 (GameTakedown.cs)
                case "drop": return Drop(op, o);
                case "stash": return Stash(op, o);
                case "restrain": return Restrain(op, o);
                default: return No("unknown-verb", $"verb '{o.Do}' is unknown (unknown = reject)");
            }
        }

        void Engage(Op op, Order o, int seconds)
        {
            if (seconds < 1) seconds = 1; // the rulebook bounds every duration to 1 s or more at load (Redline E3); a 1 s floor is the belt

            op.Walk = null; op.WalkMm = 0; // engaging stops the approach walk
            op.Busy = o; op.BusyStart = Tick; op.BusyEnd = Tick + T(seconds);
            Note("order." + o.Do, $"{Sim.Op.Name(op.Id)} {o.Do}{(o.Target.Length > 0 ? " " + o.Target : "")} ({seconds} s)");
        }

        string Move(Op op, Order o)
        {
            Pt to;
            if (o.Point.HasValue) to = o.Point.Value;
            else if (S.HasPlace(o.To)) to = S.Stand(o.To);
            else return No("no-place", $"no place '{o.To}'");
            if (!S.Grid.Free(to)) return No("unwalkable", "that ground can't be walked (a roof, a wall or a solid)");
            if (o.Run) { var no = RunRefusal(op); if (no.Length > 0) return no; }
            var route = S.Grid.Route(op.Pos, to); if (route == null) return No("no-walk", "no walk there");
            if (op.Driven) EndDrive(op, false); // brief 025: a click move takes control back
            op.Walk = new Path(route); op.WalkMm = 0;
            if (op.Walk.Length == 0) op.Walk = null;
            op.Running = o.Run; op.WalkSpeed = PaceOf(op, o.Run);
            if (o.Run) { op.RunAlerted = false; op.RunSeen.Clear(); if (op.Gun.Order.Length > 0) { op.Gun.Order = ""; op.Gun.Force = false; op.Gun.Target = ""; Note("fire.cancelled", $"{Sim.Op.Name(op.Id)} runs: the fire order ends."); } }
            Note("order.move", $"{Sim.Op.Name(op.Id)} {(o.Run ? "runs" : "heads")} for {(o.To.Length > 0 ? o.To : to.ToString())}.");
            return "";
        }

        /// <summary>A move's pace: walking (cell.speed) or running (cell.runSpeed). Who may not run is RunRefusal's (GameCombat.cs).</summary>
        int PaceOf(Op op, bool run) => run ? R.RunSpeed : op.CarryBody.Length > 0 && op.Id != OpId.Enforcer ? R.CarryUntrainedSpeed : opSpeed; // brief 013: only the Enforcer carries a body at a walk

        // ---------------------------------------------------------------- the person events (rulebook scout.*, turn.*)

        string Present(Person p, out Pt pos)
        {
            pos = default;
            var at = PersonPos(p);
            if (!at.HasValue) return p.Down ? No("person-down", $"{p.Role} is down") : No("person-away", $"{p.Role} is not out on the street");
            pos = at.Value; return "";
        }

        /// <summary>A Watch or a Listen; `engage` false checks it only (LearnQuery, the card before the click) and changes nothing. A Watch on a
        /// machine (a camera, the patrol) is open to the operatives in its kind's sight `by` (Sky 2026-10-18: the Tech too); a person's Watch
        /// and every Listen are the Scout's. A watcher known on arrival (the response, the rivals) is nothing to watch for anyone (target-unknown).
        /// Any other operative is refused only-scout, as before.</summary>
        string Scout(Op op, Order o, bool engage = true)
        {
            bool machine = o.Do == "watch" && !IsPersonRoleName(o.Target);
            if (op.Id != OpId.Scout && !(machine && (WatchesKind(op, o.Target) || ArrivesKnown(o.Target)))) return No("only-scout", "only the Scout watches people and listens (§03)");
            if (machine && IsContainer(o.Target)) return WatchContainer(op, o, engage); // a container's round (§05; GameStashWatch.cs)
            if (machine) return WatchWatcher(op, o, engage); // a camera or the patrol (rulebook sight)
            if (!IsPersonRoleName(o.Target)) return No("target-unknown", $"'{o.Target}' is no one to listen to here");
            var p = PersonByRole(o.Target);
            if (!ScoutTeaches(R.Ev("scout." + o.Do), p)) return o.Do == "listen" ? No("already-heard", $"the cell knows {p.Role}'s need and temperament already: a Listen teaches nothing more") : No("already-watched", $"the cell knows {p.Role}'s place and when already: a Watch teaches nothing more");
            var miss = Present(p, out var pos); if (miss.Length > 0) return miss;
            var ev = R.Ev("scout." + o.Do);
            int reach = actReach;
            foreach (var c in ev.Needs) if (c.K == "reach") reach = (int)R.Num(c.S("m")) * 100;
            var x = Ctx(p, ev);
            // only asking (ScoutQuery, target mode; Latch 2026-10-18): a need the order lacks outranks its reach, since walking closer won't
            // cure it. Issue keeps its order (reach, then needs), so every recorded run replays as before.
            if (!engage) foreach (var c in ev.Needs) if (c.K != "reach" && !Holds(c, x)) return NeedsNo(c, x);
            if (!G.Within(op.Pos, pos, reach)) return No("too-far", $"stand within {reach / 100} m of {p.Role}", m: reach / 100);
            foreach (var c in ev.Needs) if (c.K != "reach" && !Holds(c, x)) return NeedsNo(c, x);
            if (!engage) return "";
            var q = Quote(ev, p);
            Engage(op, o, (int)q.S);
            op.BusyQuote = q; op.BusyPaid = 0;
            RoundHold(p, op, o.Do, op.BusyEnd); // brief 022: spoken to, a server stands still (Watch holds nothing: rounds.holds)
            return "";
        }

        /// <summary>Whether a Scout event on this person can still teach the cell anything (Sky 2026-10-18: "if I've listened to someone before,
        /// I think I can then listen to them again?"; a repeat that teaches nothing is refused, already-heard or already-watched, at no cost).
        /// Read from the rulebook, not listed here: every fact its outcomes and `also` rows learn of the subject (an `also` that needs a lover
        /// only for someone who has one), the temperament if the event is in preview.knownBy, and for the guard's Watch his sight (rulebook
        /// sight: his Watch teaches it too). A secret counts only for someone who has one. Knowledge forgotten opens the event again.</summary>
        bool ScoutTeaches(Event ev, Person p)
        {
            bool Open(string what) => what == "secret" ? p.Secret.Length > 0 && !p.KSecret : what != "refused" && !p.Knows(what);
            bool Learns(List<Eff> changes) { foreach (var c in changes) if (c.Do == "learn" && c.S("of") == "subject") foreach (var w in c.L("what")) if (Open(w)) return true; return false; }
            foreach (var oc in ev.Outcomes) if (Learns(oc.Changes)) return true;
            foreach (var a in ev.Also) if (!a.When.Exists(c => c.K == "lover-within") || p.Lover != null) if (Learns(a.Changes)) return true;
            if (R.KnownBy.Contains(ev.Id) && !p.KTemperament) return true;
            if (ev.Id == "scout.watch" && p == GuardP && !(Known("guard")?.Sight ?? true)) return true;
            return false;
        }

        /// <summary>The Scout's Watch or Listen row before the click: LearnQuery for the Scout (kept for its callers).</summary>
        public Answer ScoutQuery(string verb, string target) => LearnQuery("scout", verb, target);

        /// <summary>The Watch or Listen row before the click (Latch, as CallQuery), for any operative: would this agent's order on this target be
        /// taken now, and if not, its refusal code (only-scout, run-tethered, already-heard, already-watched, too-far, …), words and numbers,
        /// exactly as Issue would answer it. The Tech's Watch on a machine (Sky 2026-10-18) asks here with agent "tech". Read-only.</summary>
        public Answer LearnQuery(string agent, string verb, string target)
        {
            var saved = refusal; refusal = default; string why;
            try
            {
                var op = OpOf(Sim.Op.Parse(agent));
                why = Over ? No("mission-over", "the mission is over")
                    : verb != "watch" && verb != "listen" ? No("unknown-verb", $"verb '{verb}' is no Watch or Listen")
                    : op.Down ? No("agent-down", $"the {agent} is down")
                    : op.Inside ? No("enforcer-inside", "inside the Office")
                    : op.Busy != null ? No("agent-busy", $"{agent} is busy until {op.BusyEnd}", tick: op.BusyEnd)
                    : Scout(op, new Order { Tick = Tick, Op = agent, Do = verb, Target = target }, engage: false);
            }
            catch (Exception e) when (!(e is OutOfMemoryException)) { why = No("engine-error", "engine error: " + e.GetType().Name + ": " + e.Message); }
            var a = AnswerOf(why);
            refusal = saved;
            return a;
        }

        string Turn(Op op, Order o)
        {
            if (op.Id != OpId.Fixer) return No("only-fixer", "only the Fixer turns people (§03)");
            if (o.Approach.Length == 0) return No("turn-needs-approach", "turn needs an approach (ask, pay, help, pressure)");
            var ev = R.Ev("turn." + o.Approach);
            var p = PersonByRole(o.Target); var miss = Present(p, out var pos); if (miss.Length > 0) return miss;
            if (p == ValeP) return No("vale-not-contact", "Vale is the target, not a contact");
            var x = Ctx(p, ev);
            x.Reach = G.Within(op.Pos, pos, approachReach);
            foreach (var c in ev.Needs) if (!Holds(c, x)) return c.K == "reach" ? No("too-far", $"stand within {approachReach / 100} m of {p.Role}", m: approachReach / 100) : NeedsNo(c, x);
            var q = Quote(ev, p);
            if (p == Driver && Tick + T((int)q.S) > T(driverLastS)) return No("driver-too-late", "the driver can be turned only until 5:40 (§07 last chance to turn driver)", tick: T(driverLastS));
            Cash -= q.Usd; // the price is paid when the order is given; a refusal gives back exactly this (Redline E2)
            Engage(op, o, (int)q.S);
            op.BusyQuote = q; op.BusyPaid = q.Usd;
            RoundHold(p, op, o.Approach, op.BusyEnd); // brief 022: spoken to, a server stands still
            return "";
        }

        /// <summary>An order lands: its effects at the end of its time.</summary>
        void Land(Op op, Order o)
        {
            switch (o.Do)
            {
                case "watch" when IsContainer(o.Target): LandWatchContainer(op, o); break; // a container's round (GameStashWatch.cs)
                case "watch" when !IsPersonRoleName(o.Target): LandWatchWatcher(op, o); break; // a camera or the patrol (rulebook sight), the Scout's or the Tech's
                case "watch": case "listen":
                    LandPersonEvent(op, o, R.Ev("scout." + o.Do), PersonByRole(o.Target));
                    if (o.Do == "watch" && o.Target == "guard") WatchedWatcher("guard", R.SightWatchS); // the guard's Watch teaches his sight too
                    break;
                case "turn": LandPersonEvent(op, o, R.Ev("turn." + o.Approach), PersonByRole(o.Target)); break;
                case "loop":
                    LoopOn = true; LoopCam = o.Target; AddTrail(R.LoopTrail, "loop"); Actions.Add(o.Target == "entrance" ? "loop" : "loop:" + o.Target);
                    Note("loop.on", "One feed repeats. The Tech is tied to the cabinet."); break;
                case "reroute":
                    if (PatrolDown) break;
                    PatrolAwayUntil = Tick + T(R.RerouteAwayS); PatrolChasing = false; PatrolTracking = false;
                    if (PatrolUnit() is Unit pu) { pu.St = "gone"; PatrolAlarmed = false; } // false orders override the alarm too
                    AddTrail(R.RerouteTrail, "reroute"); Actions.Add("reroute"); Chain.Add("patrol-rerouted");
                    Note("patrol.rerouted", "The patrol follows false orders and leaves the entrance sweep."); break;
                case "mislead":
                    if (!RivalsPresent) { Note("mislead.missed", "The rivals are gone before the tip lands."); break; }
                    RivalsDelayedUntil = Tick + T(R.MisleadAwayS); RivalsDelayMethod = "mislead"; MisledOnce();
                    AddTrail(R.MisleadTrail, "mislead"); Actions.Add("mislead"); Chain.Add("rivals-false-tip");
                    Note("rivals.misled", "A false tip sends the rival crew away. They may return."); break;
                case "enter" when o.How == "out": ExitWithoutVale(op, false); break; // a cancelled Enter waiting inside for a free door
                case "enter":
                    {
                        // rev 4 R4.1: no exit through a held door. The service door held, out by the public door; both held, he waits inside
                        bool serviceHeld = DoorHeld(ExitDoor), frontHeld = serviceHeld && DoorHeld(EnterDoor);
                        if (frontHeld)
                        {
                            if (!Log.Exists(l => l.Tick == Tick - 1 && l.Code == "enter.in")) Note("enter.in", "Both doors are held: the Enforcer waits inside with Vale.");
                            op.Busy = o; op.BusyEnd = Tick + 1; break; // re-tried each tick until a door frees
                        }
                        op.Inside = false; op.Pos = serviceHeld ? S.Stand(S.GuardPost) : S.Stand(S.ValeService); EntryInProgress = false; Vale = ValeAt.WithEnforcer;
                        Note("enter.out", serviceHeld ? "The service door is held: Vale and the Enforcer come out at the public door." : "Vale and the Enforcer come out at the service lane."); StartFight(); break;
                    }
                case "takedown": LandTakedown(op, o); break;
                case "board": LandBoard(op); break;
                case "move": LandStepOut(op, o); break; // only a boarded operative's move is an action: the step out
                case "drop": case "stash": case "restrain": LandBodyOrder(op, o); break;
                case "carry" when !IsOpId(o.Target): LandBodyOrder(op, o); break;
                case "carry":
                    {
                        var other = OpOf(Sim.Op.Parse(o.Target));
                        if (!other.Down || other.CarriedBy.HasValue) { Note("carry.missed", $"There is nobody to lift at the {o.Target}'s place."); break; }
                        op.Carrying = other.Id; other.CarriedBy = op.Id;
                        Note("carry.lifted", $"The {Sim.Op.Name(op.Id)} lifts the {o.Target}. Walk them to the car.");
                        break;
                    }
                case "take":
                    Vale = ValeAt.WithEnforcer; op.Gun.Order = ""; op.Gun.Force = false; op.Gun.Target = ""; // brief 018: walking Vale, he doesn't fire
                    if (!Driver.Turned) AddTrail(R.TakeTrailUnturned, "take:unturned-driver");
                    Chain.Add("vale-taken-outside"); Note("take.done", "Vale is with the Enforcer. Get to the car."); StartFight(); break;
            }
        }

        void LandPersonEvent(Op op, Order o, Event ev, Person p)
        {
            var x = Ctx(p, ev);
            var q = op.BusyQuote ?? Quote(ev, p); long paid = op.BusyPaid; // charge what the card said when the order was given
            op.BusyQuote = null; op.BusyPaid = 0;
            var outcome = FirstOutcome(ev, x);
            x.Outcome = outcome.Id;
            var changes = new List<Eff>(outcome.Changes);
            foreach (var a in ev.Also) if (AllHold(a.When, x)) changes.AddRange(a.Changes);
            var acts = new List<string>();
            if (!ev.Private) foreach (var w in ev.Witnesses) if (AllHold(w.When, x)) acts.Add(w.Act); // rulebook privacy: a private conversation has no onlookers
            bool witnessed = false;
            foreach (var act in acts) witnessed |= WitnessAct(act, p, "fixer");
            bool charged = false;
            foreach (var c in changes) charged |= Apply(c, p, q, witnessed);
            if (paid > 0 && !charged) { Cash += paid; } // no deal: the money stays with the cell
            if (R.KnownBy.Contains(ev.Id)) p.Learn("temperament"); // rulebook preview.knownBy (Sky 2026-10-15: Listen)
            if (ev.Id.StartsWith("turn.", StringComparison.Ordinal))
            {
                Actions.Add($"{ev.Id}:{p.Role}");
                if (outcome.Id == "turned" && p == Inez) InezMethod = o.Approach;
            }
            Note($"{ev.Id}.{outcome.Id}", $"{p.Name} ({p.Role}): {ev.Id} → {outcome.Id}.");
        }

        /// <summary>One change from a rulebook outcome. Returns true if it charged money.</summary>
        bool Apply(Eff c, Person p, Quote q, bool witnessed)
        {
            switch (c.Do)
            {
                case "charge":
                    var parts = c.L("parts");
                    if (parts.Contains("trail")) AddTrail((int)q.Trail, $"{q.Event}:{p.Role}");
                    return parts.Contains("usd");
                case "turn": p.Turned = true; Chain.Add($"{p.Role}-turned"); return false;
                case "move": LadderMove(p, c.S("on")); return false;
                case "need-met": p.NeedMet = true; return false;
                case "remember": Remember(p, c.S("act"), "fixer", witnessed); return false;
                case "learn":
                    if (c.S("of") != "subject") throw new FormatException($"learn of {c.S("of")} is not a mission effect");
                    foreach (var w in c.L("what")) { if (w == "refused") p.KnownRefused.Add(q.Event.Substring(5)); else p.Learn(w); }
                    return false;
                case "forget": foreach (var w in c.L("what")) p.Forget(w); return false;
                case "report": Report(p); return false;
                case "debrief": DebriefLines.Add((Tick, c.S("line"), p.Role, "")); return false;
                default: throw new FormatException($"effect '{c.Do}' is not a mission effect");
            }
        }

        void LadderMove(Person p, string move)
        {
            foreach (var (k, by) in R.Ladders[move]) p.Sc[k] = R.Clamp(k, p.Sc[k] + by);
        }

        /// <summary>rulebook memory (K1): an entry on the subject; when full, the oldest sighting or told fact goes first (Motive's review #9).</summary>
        void Remember(Person p, string act, string by, bool witnessed)
        {
            p.Memory.Add(new Mem { Act = act, By = by, Place = p.Place, Tick = Tick, Witnessed = witnessed });
            if (p.Memory.Count <= R.MemoryCap) return;
            int drop = -1;
            for (int j = 0; j < p.Memory.Count; j++)
                if (Sighting(p.Memory[j].Act) && (drop < 0 || p.Memory[j].Tick < p.Memory[drop].Tick)) drop = j;
            if (drop < 0) for (int j = 0; j < p.Memory.Count; j++) if (drop < 0 || p.Memory[j].Tick < p.Memory[drop].Tick) drop = j;
            p.Memory.RemoveAt(drop);
        }

        /// <summary>rulebook memory.whenFull: what a person saw (or was told) goes before what was done to them.</summary>
        static bool Sighting(string act) => act == "saw-act" || act == "saw-runner" || act == "saw-gunfire" || act == "saw-violence" || act == "saw-weapon-drawn" || act == "told"
            || act == "saw-takedown" || act == "saw-carry" || act == "found-body" || act == "heard-alarm"; // brief 013's sightings

        /// <summary>A report (rulebook reports): an incident for Alert — the nth reported incident raises it to at least byIncident[n−1].</summary>
        void Report(Person p)
        {
            Reported++;
            var list = R.AlertByIncident;
            int at = list[Math.Min(Reported, list.Length) - 1];
            RaiseAlert(at, $"report:{p.Role}");
            AddIncident("report", "report:" + p.Role, PersonPos(p) ?? S.Stand(S.GuardPost), new[] { (p, PersonPos(p) ?? S.Stand(S.GuardPost)) });
            Note("report", $"{p.Name} reports the approach. Alert {Alert}.");
        }

        /// <summary>rulebook witness.sees: anyone (but the subject and the cell) within witness range on a clear sightline sees a traceable act:
        /// one incident adds witness Trail and moves standing once; simulated witnesses remember it.</summary>
        bool WitnessAct(string act, Person subject, string by)
        {
            var at = PersonPos(subject); if (!at.HasValue) return false;
            var seenAt = WitnessesWithPos(at.Value, subject);
            var seen = seenAt.ConvertAll(x => x.p);
            if (seen.Count == 0) return false;
            var inc = AddIncident(act, act + ":" + subject.Role, at.Value, seenAt);
            inc.Witnesses.Add((subject, at.Value)); // the person the act was done to stood at it: the nearest to question (§05 sightline + distance)
            if (incidents.Add($"{act}:{subject.Role}:{Tick}"))
            {
                AddTrail(R.WitnessTrail, $"witnessed:{act}:{subject.Role}");
                MoveStanding(R.Traceable[act] * R.StandingStep, $"witnessed:{act}", "seen-" + act, subject.Role.Length > 0 ? subject.Role : subject.Id);
            }
            foreach (var w in seen) Remember(w, "saw-act", by, true);
            Note("witness." + act, $"{seen.Count} saw the {act}.");
            return true;
        }

        // ---------------------------------------------------------------- the rulebook's conditions, the action card

        sealed class PCtx { public Person P = null!; public Event Ev = null!; public Band Band; public string? Outcome; public bool Reach = true; public long Cash; }
        PCtx Ctx(Person p, Event ev) => new PCtx { P = p, Ev = ev, Band = R.BandOf(Standing), Cash = Cash };
        bool AllHold(List<Cond> cs, PCtx x) { foreach (var c in cs) if (!Holds(c, x)) return false; return true; }
        Outcome_ FirstOutcome(Event ev, PCtx x) { foreach (var o in ev.Outcomes) if (AllHold(o.When, x)) return new Outcome_(o); throw new InvalidOperationException("no outcome"); }
        readonly struct Outcome_ { public readonly string Id; public readonly List<Eff> Changes; public Outcome_(ROutcome o) { Id = o.Id; Changes = o.Changes; } }

        static string Describe(Cond c) => c.K switch
        {
            "requires" => "the " + c.S("approach") + " approach's knowledge (Watch for routine, Listen for need)",
            "need-met-by" => "a need this approach acts on",
            "leverage" => "the need it acts on known, or their secret known (Listen)",
            "need-met" => "a need still unmet",
            "memory" => "no remembered refusal",
            "turned" => c.B("is") ? "a turned contact" : "someone not yet turned",
            "cash-covers" => "cash for the worst case",
            "known" => "the " + c.S("what") + " known",
            _ => c.K,
        };

        bool Holds(Cond c, PCtx x)
        {
            var p = x.P;
            switch (c.K)
            {
                case "tier": return c.S("is") == "simulated";
                case "turned": if (c.N.Has("of")) break; return p.Turned == c.B("is");
                case "known": return p.Knows(c.S("what")) == (!c.N.Has("is") || c.B("is"));
                case "leverage": // Motive, motive-lovers.md §2.2: the need it acts on (known), or the person's secret known
                    {
                        var r = R.ApproachRequires(c.S("approach"));
                        return ((r == "nothing" || p.Knows(r)) && R.NeedMetBy(p.Need, c.S("approach"))) || p.Knows("secret");
                    }
                case "lover-within": { if (p.Lover == null) return false; var a = PersonPos(p); var b = PersonPos(p.Lover); return a.HasValue && b.HasValue && G.Within(a.Value, b.Value, (int)R.Num(c.S("m")) * 100); }
                case "requires": { var r = R.ApproachRequires(c.S("approach")); return r == "nothing" || p.Knows(r); }
                case "need-met-by": return R.NeedMetBy(p.Need, c.S("approach"));
                case "need-is": return c.L("in").Contains(p.Need);
                case "need-met": return p.NeedMet == c.B("is");
                case "reach": return x.Reach;
                case "cash-covers": return x.Cash >= Quote(x.Ev, p).WorstUsd;
                case "memory": if (c.N.Has("of") || c.N.Has("this")) break; return p.Has(c.S("act")) == c.B("has");
                case "fit": return c.L("is").Contains(FitId(R.FitOf(x.Ev.Id.Substring(5), p.Temperament, x.Band)));
                case "temperament": return c.L("in").Contains(p.Temperament);
                case "standing": return c.L("band").Contains(Rules.BandId(x.Band));
                case "orders-reached": return (p.Count(R.HelpedAct) + 1 >= OrdersFor(x.Ev, x)) == c.B("is");
                case "reports": foreach (var rr in R.Reports) if (AllHold(rr, x)) return true; return false;
                case "reports-approach": return R.Temp(p.Temperament).ReportsApproach;
                case "outcome": return x.Outcome != null && c.L("is").Contains(x.Outcome);
                case "talker": return R.IsTalker(p.Sc) == c.B("is");
                case "lies":
                    {
                        bool lies = R.IsTalker(p.Sc) == R.LieTalker && p.Has(R.HelpedAct) == R.LieHelped && p.Sc[Rules.Bravery] >= R.LieBraveryAtLeast;
                        return lies == c.B("is");
                    }
                case "holds-fact": return (p.Memory.Count > 0) == c.B("is");
                case "scale":
                    {
                        int a = p.Sc[Rules.ScaleIndex(c.S("scale"))];
                        var than = c.N["than"]; long b = than.Kind == JKind.Str ? R.Num(than.Str()) : p.Sc[Rules.ScaleIndex(than["scale"].Str())];
                        switch (c.S("op")) { case "<": return a < b; case "<=": return a <= b; case "==": return a == b; case ">=": return a >= b; case ">": return a > b; }
                        throw new FormatException("op");
                    }
                case "trail": return Trail >= R.Num(c.S("atLeast"));
            }
            throw new FormatException($"condition '{c.K}' is not evaluated inside a mission");
        }
        static string FitId(Fit f) => f == Fit.Suits ? "suits" : f == Fit.Worse ? "worse" : "refused";
        static readonly string[] TemperamentConds = { "fit", "temperament", "reports", "reports-approach", "orders-reached" };
        static bool ReadsTemperament(List<Cond> cs) { foreach (var c in cs) if (Array.IndexOf(TemperamentConds, c.K) >= 0) return true; return false; }

        long OrdersFor(Event ev, PCtx x)
        {
            long n = 0; bool any = false;
            for (int i = 0; i < ev.Price.Count; i++)
            {
                var l = ev.Price[i];
                if (!AllHold(l.When, x)) continue;
                if (l.Orders != null) { n += l.OrdersV; any = true; } else if (i == 0) { n += 1; any = true; }
            }
            return any && n > 0 ? n : 1;
        }

        /// <summary>The action card for an event on a person (§02 full price, K8 line items, Sky Q3 "?").</summary>
        public Quote Quote(Event ev, Person p)
        {
            var q = new Quote();
            var x = Ctx(p, ev);
            for (int i = 0; i < ev.Price.Count; i++)
            {
                var l = ev.Price[i];
                bool truth = AllHold(l.When, x);
                string shown = truth ? "yes" : "no";
                if (!p.KTemperament && ReadsTemperament(l.When)) shown = Agree(p, t => AllHold(l.When, WithTemperament(x, t)) ? "yes" : "no");
                var line = new Quote.L { Line = l.Id, Usd = l.UsdV, S = l.SV, Trail = l.TrailV, Orders = l.Orders != null ? l.OrdersV : (i == 0 ? 1 : 0), Holds = shown };
                q.Lines.Add(line);
                if (truth) { q.Usd += line.Usd; q.S += line.S; q.Trail += line.Trail; }
                if (truth || shown == "?") q.WorstUsd += line.Usd;
            }
            q.Orders = OrdersFor(ev, x);
            q.Outcome = p.KTemperament ? FirstOutcome(ev, x).Id : Agree(p, t => FirstOutcome(ev, WithTemperament(x, t)).Id);
            q.Event = ev.Id;
            if (ev.Id.StartsWith("scout.", StringComparison.Ordinal) && !ScoutTeaches(ev, p)) q.Refused = ev.Id == "scout.listen" ? "already-heard" : "already-watched"; // the same test Issue refuses by
            q.Leverage = ev.Id == "turn.pressure" && p.Knows("secret");
            if (ev.Id.StartsWith("turn.", StringComparison.Ordinal) && p.KnownRefused.Contains(ev.Id.Substring(5))) q.Outcome = "refused"; // a refusal seen: ✗
            if (ev.Id.StartsWith("turn.", StringComparison.Ordinal))
            {
                // would they report it: the event's own report rows (its `also` with a report), so an exposure that silences a Loyal person reads "no"
                bool Rep(PCtx c) { foreach (var a in ev.Also) if (a.Changes.Exists(e => e.Do == "report") && AllHold(a.When, c)) return true; return false; }
                q.Reports = p.KTemperament ? (Rep(x) ? "yes" : "no") : Agree(p, t => Rep(WithTemperament(x, t)) ? "yes" : "no");
                var list = R.AlertByIncident;
                q.AlertIfReported = Math.Max(Alert, list[Math.Min(Reported + 1, list.Length) - 1]);
            }
            var at = PersonPos(p);
            if (at.HasValue && !ev.Private) q.Witnesses = WitnessesWithPos(at.Value, p).Count; // who would see it: the same reading as witness.sees (WitnessAct), crowd included
            return q;
        }
        static readonly Cond ReportsCond = new Cond(JNode.Parse("{\"k\": \"reports\"}"));

        /// <summary>The action card for an operative's approach to a role: the price, the risks, and the walk to stand within reach.</summary>
        public Quote Preview(string approach, string role, OpId by = OpId.Fixer)
        {
            var p = PersonByRole(role); var q = Quote(R.Ev("turn." + approach), p);
            var at = PersonPos(p); var op = OpOf(by);
            if (at.HasValue && ServerOf(p) != null && !G.Within(op.Pos, at.Value, approachReach)) // brief 022: aim the walk at where her round will have her
            {
                var st = S.Grid.NearestFree(at.Value); var rt = st.HasValue ? S.Grid.Route(op.Pos, st.Value) : null;
                if (rt != null) { int k = (int)(new Path(rt).Length / Math.Max(1, opSpeed)); var ahead = PoseAhead(p, k); if (ahead.HasValue) at = ahead.Value.pos; }
            }
            if (at.HasValue && !G.Within(op.Pos, at.Value, approachReach))
            {
                var stand = S.Grid.NearestFree(at.Value); var route = stand.HasValue ? S.Grid.Route(op.Pos, stand.Value) : null;
                if (route != null) { long mm = Math.Max(0, new Path(route).Length - approachReach * 10L); q.WalkS = (int)((mm + opSpeed * Hz - 1) / (opSpeed * Hz)); }
            }
            // seen by (rulebook sight.unknown): where the operative stands for the act, its own place when already within reach, else the person's
            if (at.HasValue) q.Seen = SeenAt(G.Within(op.Pos, at.Value, approachReach) ? op.Pos : at.Value);
            return q;
        }

        /// <summary>The dossier's face bit: this person holds the Fixer's face (rulebook memory.faceFacts; §03 the face witnesses remember).</summary>
        public bool HoldsFace(Person p) { foreach (var m in p.Memory) if (R.FaceFact.ContainsKey(m.By)) return true; return false; }

        PCtx WithTemperament(PCtx x, string t)
        {
            var q = new Person { Role = x.P.Role, Id = x.P.Id, Name = x.P.Name, Temperament = t, Need = x.P.Need, Turned = x.P.Turned, NeedMet = x.P.NeedMet, KRoutine = x.P.KRoutine, KNeed = x.P.KNeed, KTemperament = x.P.KTemperament, Place = x.P.Place, Secret = x.P.Secret, KSecret = x.P.KSecret, Lover = x.P.Lover, Record = x.P.Record, Size = x.P.Size, Holder = x.P.Holder };
            Array.Copy(x.P.Sc, q.Sc, 4); q.Memory.AddRange(x.P.Memory);
            return new PCtx { P = q, Ev = x.Ev, Band = x.Band, Outcome = x.Outcome, Reach = x.Reach, Cash = x.Cash };
        }
        /// <summary>The answer every temperament gives alike, else "?" (Motive's review, other findings 3).</summary>
        string Agree(Person p, Func<string, string> f)
        {
            string? first = null;
            foreach (var t in R.TemperamentIds) { var a = f(t); if (first == null) first = a; else if (a != first) return "?"; }
            return first ?? "?";
        }

        // ---------------------------------------------------------------- the other verbs

        /// <summary>Whether the Fixer could call this contact now (the action card's Call), without calling.</summary>
        public bool CanCall(string role)
        {
            var p = PersonByRole(role); var f = OpOf(OpId.Fixer);
            if (Over || f.Busy != null || p.Down || !p.Turned) return false;
            if (p == Driver) return Vale != ValeAt.Car && (BlockMove == INF || Tick >= BlockedUntil + blockMoveT) && Tick < T(driverLastS) - blockMoveT;
            return p.Lover != null && SummonRefusal(p, out _).code == null;
        }

        /// <summary>Why the contact's lover won't come to a call now (rulebook summon), or code null; walkTicks: his walk to the caller.</summary>
        (string? code, string why) SummonRefusal(Person caller, out int walkTicks)
        {
            walkTicks = 0;
            var lover = caller.Lover!;
            if (lover != GuardP) return ("summon-no-visit", $"{lover.Role} has no post to leave (only a lover with a post is modelled)");
            if (GuardDown || lover.Down) return ("summon-busy", "he's down");
            var at = GuardPose(); if (!at.HasValue) return ("summon-off-street", "he isn't on the street");
            if (GuardHeld || GuardEngaged || !GuardAtDoor) return ("summon-busy", "he's busy");
            if (Alert > R.SummonAlertMax) return ("summon-alert", "security is searching: he won't leave");
            foreach (var m in lover.Memory)
                if ((m.Act == "saw-gunfire" || m.Act == "saw-violence" || m.Act == "saw-weapon-drawn") && (m.By == "scout" || m.By == "fixer" || m.By == "tech" || m.By == "enforcer"))
                    return ("summon-saw-violence", "he saw what you did");
            if (lover.Summoned >= R.SummonsPerShift) return ("summon-came-once", "he came once already");
            var to = ServerOf(caller) is RoundsData.Server csv && !caller.Down ? csv.At : PersonPos(caller); if (!to.HasValue) return ("summon-off-street", "she isn't on the street"); // brief 022: the summons reads her post, never her pose
            var route = S.Grid.Route(S.Grid.NearestFree(at.Value.pos) ?? at.Value.pos, S.Grid.NearestFree(to.Value) ?? to.Value);
            if (route == null) return ("summon-too-far", "no walk between them");
            long len = new Path(route).Length; walkTicks = (int)((len + opSpeed - 1) / opSpeed); // at walking pace (cell.speed)
            if (walkTicks > T(R.SummonWalkMaxS)) return ("summon-too-far", $"too far: {walkTicks / Hz} s away");
            return (null, "");
        }

        /// <summary>The call card, before the click (Latch): would the Fixer's call on this role be taken now, and if not, its refusal code,
        /// words and numbers, exactly as Issue would answer it. Read-only: it changes nothing.</summary>
        public Answer CallQuery(string role)
        {
            var saved = refusal; refusal = default; string why;
            try
            {
                var op = OpOf(OpId.Fixer);
                why = Over ? No("mission-over", "the mission is over")
                    : op.Down ? No("agent-down", "the fixer is down")
                    : op.Busy != null ? No("agent-busy", $"fixer is busy until {op.BusyEnd}", tick: op.BusyEnd)
                    : CallRefusal(op, role);
            }
            catch (Exception e) when (!(e is OutOfMemoryException)) { why = No("engine-error", "engine error: " + e.GetType().Name + ": " + e.Message); }
            var a = AnswerOf(why);
            refusal = saved;
            return a;
        }

        /// <summary>Why the Fixer's call on a role is refused now, or "" (the checks of Call, without its effects).</summary>
        string CallRefusal(Op op, string role)
        {
            if (op.Id != OpId.Fixer) return No("only-fixer", "only the Fixer calls contacts (§03)");
            var p = PersonByRole(role);
            if (p.Down) return No("person-down", $"{p.Role} is down");
            if (!p.Turned) return No("not-a-contact", $"{p.Role} is not a contact");
            if (p == Driver) // the driver's call is his role job, the camera block (unchanged)
            {
                if (Vale == ValeAt.Car) return No("car-gone", "the official car is gone");
                if (BlockMove != INF && Tick < BlockedUntil + blockMoveT) return No("car-busy", "the car is still blocking or returning", tick: BlockedUntil + blockMoveT);
                if (Tick >= T(driverLastS) - blockMoveT) return No("call-too-late", "too late: the car leaves for the pickup at 5:40", tick: T(driverLastS) - blockMoveT);
                return "";
            }
            if (p.Lover != null)
            {
                var (code, why) = SummonRefusal(p, out int walk);
                return code != null ? No(code, why, tick: code == "summon-too-far" ? walk : -1) : "";
            }
            return No("nothing-to-call", $"{p.Role} has nothing to do on a call");
        }

        string Call(Op op, Order o)
        {
            var no = CallRefusal(op, o.Target); if (no.Length > 0) return no;
            var p = PersonByRole(o.Target);
            if (p == Driver) // the driver's call is his role job, the camera block (unchanged)
            {
                BlockMove = Tick; BlockedFrom = Tick + blockMoveT; BlockedUntil = Tick + blockMoveT + blockHoldT;
                AddTrail(R.CallTrail, "call:driver"); Remember(Driver, "job", "fixer", false);
                Actions.Add("call:driver"); Chain.Add("driver-blocks-camera");
                Note("call.driver", "The driver starts moving the car across the pickup camera.");
                return "";
            }
            return Summon(p); // CallRefusal let it through: the lover comes
        }

        /// <summary>The summons (rulebook summon; Motive, motive-lovers.md §1.3): a turned contact's call sends for their lover, read from the
        /// city's ties. He walks the grid to her at walking pace, stays summon.stay and walks back; refused at no cost, with its code.</summary>
        string Summon(Person p)
        {
            SummonRefusal(p, out int walk);
            var lover = p.Lover!;
            var sv = ServerOf(p);
            var from = GuardPose()!.Value.pos; var to = sv != null ? sv.At : PersonPos(p)!.Value;
            guardOut = new Path(S.Grid.Route(S.Grid.NearestFree(from) ?? from, S.Grid.NearestFree(to) ?? to)!);
            walkT = walk; stayT = T(R.SummonStayS); guardRunning = false;
            if (sv != null) // brief 022: he walks to her post and stops rounds.close from it, at her side (PartnerStop), facing her
            {
                var side = PartnerStop(p, lover); // baked free and walkable from his post; a stop his grid cannot reach falls back as no stop does
                var toSide = side.HasValue ? S.Grid.Route(S.Grid.NearestFree(from) ?? from, side.Value) : null;
                if (toSide != null) guardOut = new Path(toSide);
                else guardOut = guardOut.Cut(Math.Max(0, guardOut.Length - R.PartnersCloseCm * 10L)); // the file holds no stop: the old stop, on his route
                walkT = (int)((guardOut.Length + opSpeed - 1) / opSpeed);
                cafeFace = to - guardOut.End;
                RoundCall(p, Tick + walkT, Tick + walkT + stayT, guardOut.End);
            }
            else cafeFace = S.CafeFacing;
            guardBack = new Path(S.Grid.Route(S.Grid.NearestFree(guardOut.End) ?? guardOut.End, S.Grid.NearestFree(from) ?? from)!);
            LureTick = Tick; GuardAwayUntil = Tick + 2 * walkT + stayT; lover.Summoned++;
            AddTrail(R.CallTrail, "call:" + p.Role); Remember(p, "job", "fixer", false);
            Actions.Add("call:" + p.Role); Chain.Add($"{p.Role}-calls-{lover.Role}");
            Note("call." + p.Role, $"{p.Name} calls {lover.Name}. He leaves his post and walks over to her ({walkT / Hz} s), to stay {R.SummonStayS} s.");
            return "";
        }

        string Loop(Op op, Order o)
        {
            if (op.Id != OpId.Tech) return No("only-tech", "only the Tech loops cameras (§03)");
            if (!LoopTarget(o.Target)) return No("loop-wrong-target", "the Tech's cabinet loops the entrance camera, the pickup camera and the city's own cameras (the Records Square mast)");
            if (LoopOn) return No("loop-holds", "the loop already holds");
            if (!G.Within(op.Pos, S.At("cabinet"), R.AtReachCm)) return No("stand-at-cabinet", "stand at the cabinet", cm: R.AtReachCm);
            Engage(op, o, R.LoopS); return "";
        }
        /// <summary>A camera the cabinet loops (rulebook cell.loop.targets): a site camera named in the list, or any of the city's own
        /// cameras when the list holds "world". One loop at a time.</summary>
        bool LoopTarget(string id)
        {
            var cam = S.Cameras.Find(c => c.Id == id); if (cam == null) return false;
            return R.LoopTargets.Contains(id) || (cam.World && R.LoopTargets.Contains("world"));
        }
        string Reroute(Op op, Order o)
        {
            if (op.Id != OpId.Tech) return No("only-tech", "only the Tech reroutes patrols (§03)");
            if (PatrolDown) return No("patrol-down", "the patrol is down");
            if (PatrolAwayUntil > Tick) return No("patrol-away", "the patrol is already away", tick: PatrolAwayUntil);
            if (!G.Within(op.Pos, S.At("cabinet"), R.AtReachCm)) return No("stand-at-cabinet", "stand at the cabinet", cm: R.AtReachCm);
            Engage(op, o, R.RerouteS); return "";
        }
        string Mislead(Op op, Order o)
        {
            if (op.Id != OpId.Scout) return No("only-scout", "only the Scout misleads (§03)");
            var r = RivalsPose(); if (!r.HasValue) return No("no-rivals", "no rivals here");
            if (!G.Within(op.Pos, r.Value.pos, actReach)) return No("stand-near-rivals", "stand near the rivals", m: actReach / 100);
            Engage(op, o, R.MisleadS); return "";
        }

        string Enter(Op op, Order o)
        {
            if (op.Id != OpId.Enforcer) return No("only-enforcer", "only the Enforcer enters (§03)");
            if (op.CarryBody.Length > 0) return No("already-carrying", "carrying a body");
            if (Alert >= 3 && DialNow.DoorsLock) return No("doors-locked", "lockdown: the Office doors are locked (brief 013, the dial)");
            if (DoorHeld(EnterDoor)) return No("door-held", "a unit holds the scene at this door: nobody goes in (rev 4: a found body)");
            if (Vale != ValeAt.Office || EntryInProgress) return No("vale-not-inside", "Vale is not inside");
            if (!G.Within(op.Pos, S.At(S.GuardPost), R.AtReachCm)) return No("stand-at-door", "stand at the public door", cm: R.AtReachCm);
            op.Walk = null;
            if (GuardAtDoor) { Fail("entry-seen-guard", "The guard is back at the door. Vale is warned.", () => With(Because("seen", true, Locate("guard", "saw", op.Pos)), "enforcer")); return ""; }
            if (CameraWatching("entrance", op.Pos)) { Fail("entry-seen-camera", "The entrance camera reports the breach. Vale is locked down.", () => With(Because("seen", true, Locate("camera:entrance", "saw", op.Pos)), "enforcer")); return ""; }
            if (PatrolWatching(S.At(S.GuardPost))) { Fail("entry-seen-patrol", "The patrol reports the breach. Vale is locked down.", () => With(Because("seen", true, Locate("patrol", "saw", S.At(S.GuardPost))), "enforcer")); return ""; }
            RouteKind = "front"; RouteGuard = BodyOf(GuardP) is Body gb ? (gb.Dead ? "killed" : "knocked-out") : GuardDown ? "shot" : "waitress"; RouteBot = SweepSeesEntrance(Tick) ? "rerouted" : "gap"; // a takedown is no shooting (brief 013 E4)
            EntryInProgress = true; op.Inside = true; Chain.Add("enforcer-reaches-vale");
            bool alarm = Alert >= 2; // Sky 2026-10-15 Q5 (rulebook cell.enter.alarm): once Alert ≥ 2 the Office staff hide Vale
            op.Gun.Order = ""; op.Gun.Target = "";
            Engage(op, o, R.EnterS + (alarm ? R.EnterAlarmS : 0));
            Note("enter.in", alarm ? "The Enforcer is inside. The alarm is up: the staff are hiding Vale. Watch the service lane." : "The Enforcer is inside. Watch the service lane.");
            return "";
        }
        string Take(Op op, Order o)
        {
            if (op.Id != OpId.Enforcer) return No("only-enforcer", "only the Enforcer takes Vale (§03)");
            if (op.CarryBody.Length > 0) return No("already-carrying", "carrying a body");
            if (Vale != ValeAt.Pickup) return No("vale-not-at-car", "Vale is not at his car");
            var vp = ValePos()!.Value;
            if (!G.Within(op.Pos, vp, actReach)) return No("stand-beside-vale", "stand beside Vale", m: actReach / 100);
            op.Walk = null;
            if (!PickupService && !TakeInCar && CameraWatching("pickup", op.Pos)) { Fail("abduction-seen-camera", "The pickup camera reports the abduction. Vale is rescued.", () => With(Because("seen", true, Locate("camera:pickup", "saw", op.Pos), Locate("councillor", "victim")), "enforcer")); return ""; }
            var rp = RivalsPose();
            if (RivalsPresent && (!RivalsDrawn || (rp.HasValue && G.Within(op.Pos, rp.Value.pos, RivalsGun.W!.EffCm)))) // drawn rivals within their weapon's effective reach
            { Fail("rivals-reach-vale", "The rival crew follows Vale's car and reaches the pickup first.", () => With(Because("beat-to-pickup", true, Locate("rivals", "reached", vp), Locate("councillor", "victim")), "enforcer")); return ""; }
            RouteKind = PickupService ? "service" : "pickup"; RouteRival = RivalsArrived ? RivalsDelayMethod : "";
            Vale = ValeAt.Taking;
            Engage(op, o, R.TakeS);
            TakeScan(); // a Take seen is a takedown seen (brief 013 D; rev 4: its struggle, unless inside his own car)
            return "";
        }
    }
}

sim/Suborned.Sim/GamePublicFight.cs.text:
// A public fight (Sky 2026-10-16, via Aster: "it should be per fight, and depends who you're fighting - a rival gang that has menace
// level authority is a +1"; Motive, briefs/014/motive-standing.md, a public fight; rulebook fight.public). It replaces engine 0.6.1's
// per-target gunfire step (gunfire.heard, retired with the cause seen-gunfire).
//  · One fight: the final fight is one fight, from its first shot by or at the cell to its end (FightOverTick) or the mission's. Outside
//    it, a fight starts at the first shot by or at the cell and ends crowd.quiet after the last such shot. Gunfire still open when the
//    final fight starts is the final fight. A fight still open when the mission ends ends with it.
//  · Public: a person of the city who is not security stands on the street within crowd.scatter of the shooter of any of its shots,
//    line or no line. Outside the final fight its shots are those by or at the cell; in it, every shot.
//  · When it ends, a public fight moves Standing once, by fight.public's first outcome that holds (the rulebook's order, read at load):
//    the cell fired on security −1; fired first on rivals the public doesn't fear −1; drove off rivals the district fears +1; else 0.
//    Untraced shots count (Standing is the public's judgement, not evidence). A seen act: outside the word's cap, a move for the drift.
using System;
using System.Collections.Generic;
using System.Globalization;

namespace Suborned.Sim
{
    /// <summary>One fight as fight.public judges it (Sky 2026-10-16). Output and hashed state, never read by a host to decide anything.</summary>
    public sealed class PublicFight
    {
        public int Start, Last, End = -1;            // ticks: its first shot, its last shot by or at the cell, when it ended
        public bool Final, Public;                   // the final fight; a person of the city heard it
        public bool OnSecurity, OnRivals;            // the cell fired on security, on rivals
        public string FirstSecurity = "";            // the first security body the cell fired on (the move's who)
        public string RivalsFirst = "";              // who fired the first shot between the cell and the rivals: "cell", "rivals" or ""
        public int CrewBroken = -1;                  // the rival crew was driven back in this fight and has not fired on the cell since
        public readonly List<string> Rivals = new List<string>(); // the rival bodies the cell fought, in the order met
        public string Outcome = "", Cause = "";      // fight.public's outcome ("unheard" when nobody heard it) and its Standing cause
        public int Delta;
    }

    public sealed partial class Game
    {
        /// <summary>The fights of this mission that have ended, in order (fight.public).</summary>
        public readonly List<PublicFight> Fights = new List<PublicFight>();
        /// <summary>The fight on now, if any.</summary>
        public PublicFight? OpenFight { get; private set; }
        bool finalFightJudged, fightClosedLate;

        /// <summary>How the public sees this mission's rivals: a start that fixes it, else the mission's word (site rivals.public), else the rulebook's default.</summary>
        public string RivalsPublic => Start.RivalsPublic ?? (S.RivalsPublic.Length > 0 ? S.RivalsPublic : R.RivalsPublicDefault);

        static bool IsRivalId(string id) => id == "rivals" || id.StartsWith("rival-", StringComparison.Ordinal);
        /// <summary>Authority: the guard, the patrol, the response unit's officers, the response's robots and police, the final fight's officers.</summary>
        bool IsSecurityId(string id) => id == "guard" || id == "patrol" || SecIndex(id) >= 0 || UnitOf(id) != null || (IsFightHostile(id) && !IsRivalId(id));
        bool FinalFightOn => FightBranch.Length > 0 && FightOverTick == INF && !finalFightJudged;

        /// <summary>A shot lands (Resolve): it opens or extends the fight, and the people within reach of its shooter hear it.</summary>
        void FightShot(string by, string t, Pt from)
        {
            bool cellBy = IsOpId(by), cellAt = IsOpId(t);
            var f = OpenFight;
            if (!cellBy && !cellAt) { if (f != null && f.Final) Hear(f, from); return; } // in the final fight every shot is the fight's
            if (f != null && !f.Final && Tick - f.Last >= R.FightQuietTicks) { EndFight(); f = null; }
            if (f == null) { f = new PublicFight { Start = Tick, Final = FinalFightOn }; OpenFight = f; }
            else if (!f.Final && FinalFightOn) f.Final = true;
            f.Last = Tick;
            Hear(f, from);
            if (cellBy)
            {
                if (IsSecurityId(t)) { f.OnSecurity = true; if (f.FirstSecurity.Length == 0) f.FirstSecurity = t; }
                else if (IsRivalId(t)) { f.OnRivals = true; if (!f.Rivals.Contains(t)) f.Rivals.Add(t); if (f.RivalsFirst.Length == 0) f.RivalsFirst = "cell"; }
            }
            else if (IsRivalId(by))
            {
                if (!f.Rivals.Contains(by)) f.Rivals.Add(by);
                if (f.RivalsFirst.Length == 0) f.RivalsFirst = "rivals";
                if (by == "rivals") f.CrewBroken = -1; // back and firing: not broken
            }
        }

        /// <summary>Public: a person of the city who is not security, on the street within the reach of the shooter, line or no line.</summary>
        void Hear(PublicFight f, Pt from)
        {
            if (f.Public) return;
            foreach (var (p, wp) in OnTheStreet()) if (p.Civilian && G.Within(wp, from, R.FightPublicCm)) { f.Public = true; return; }
        }

        /// <summary>The rival crew is driven back (Damage): it broke in this fight.</summary>
        void CrewBroken() { if (OpenFight != null) OpenFight.CrewBroken = Tick; }

        /// <summary>The final fight starts (StartFight): gunfire still open is the final fight, else it closes first.</summary>
        void FightJoinsFinal()
        {
            var f = OpenFight; if (f == null || f.Final) return;
            if (Tick - f.Last >= R.FightQuietTicks) EndFight(); else f.Final = true;
        }

        /// <summary>End of a tick: a fight outside the final fight ends quiet after its last shot; the final fight at its end; any fight with the mission.</summary>
        void FightEnds()
        {
            var f = OpenFight; if (f == null) return;
            if (Over) EndFight();
            else if (f.Final) { if (FightOverTick != INF) EndFight(); }
            else if (Tick - f.Last >= R.FightQuietTicks) EndFight();
        }

        /// <summary>The run ends with a fight open (Finish, Investigate): it ends now. True when one did.</summary>
        bool EndOpenFight() { if (OpenFight == null) return false; EndFight(); return true; }

        void EndFight()
        {
            var f = OpenFight!; OpenFight = null; f.End = Tick;
            if (f.Final) finalFightJudged = true;
            f.Outcome = "unheard";
            if (f.Public)
            {
                f.Outcome = "none";
                foreach (var o in R.FightOutcomes)
                {
                    bool all = true; foreach (var c in o.When) if (!FightHolds(c, f)) { all = false; break; }
                    if (!all) continue;
                    f.Outcome = o.Id; f.Delta = o.Delta; f.Cause = o.Cause; break;
                }
            }
            Fights.Add(f);
            string span = $"{Sim.Report.Clock(f.Start)}-{Sim.Report.Clock(f.Last)}";
            if (f.Delta != 0)
            {
                string who = f.OnSecurity ? f.FirstSecurity : "rivals"; // authority outranks (the rulebook's first outcome)
                MoveStanding(f.Delta, $"fight:{span}:{f.Outcome}", f.Cause, who);
            }
            Note("fight.judged", f.Public ? $"The fight ({span}{(f.Final ? ", the final fight" : "")}) is over: the street judges it {f.Outcome} ({(f.Delta > 0 ? "+" : "")}{f.Delta.ToString(CultureInfo.InvariantCulture)} Standing)." : $"The fight ({span}) is over. Nobody heard it.");
        }

        bool FightHolds(Cond c, PublicFight f)
        {
            switch (c.K)
            {
                case "fired-on": foreach (var x in c.L("in")) if ((x == "security" && f.OnSecurity) || (x == "rivals" && f.OnRivals)) return true; return false;
                case "rivals-public": return c.L("in").Contains(RivalsPublic);
                case "fired-first": return (f.RivalsFirst == "cell") == c.B("is");
                case "rivals-broken": return RivalsBroken(f) == c.B("is");
            }
            throw new InvalidOperationException($"fight.public: '{c.K}' is not a fight's condition"); // Rules rejects it at load
        }

        /// <summary>Every rival the cell fought in this fight (in the final fight, every rival of the ambush too) broke, was driven back
        /// or is down when it ends. The crew absorbed into the ambush is judged by the ambush.</summary>
        bool RivalsBroken(PublicFight f)
        {
            var set = new List<string>(f.Rivals);
            if (f.Final) foreach (var h in Hostiles) if (IsRivalId(h.Id) && h.Present && !set.Contains(h.Id)) set.Add(h.Id);
            int judged = 0;
            foreach (var id in set)
            {
                if (id == "rivals")
                {
                    if (RivalsAbsorbed) continue;
                    if (f.CrewBroken < 0) return false;
                    judged++; continue;
                }
                var h = HostileOf(id);
                if (h != null && !h.Down && h.Gun.St != "break" && h.Gun.St != "gone") return false;
                judged++;
            }
            return judged > 0;
        }
    }
}

sim/Suborned.Sim/GameResponse.cs.text:
// The response as a dial (brief 013 B, Keel; Sky 2026-10-16: "it's easy to swarm the play area with robots if we need to temper the game
// play"): the rulebook's `response` section (Motive's levels, briefs/013/motive-takedowns.md §5.3; Pulse's behaviour, briefs/013/
// pulse-witnesses.md §12, §13). The level is data (the district's base + the mission's bonus, sim/data/handover.provisional.json until the
// plan and mission carry it; a scenario may fix it). A landed alarm sends robots at Alert 1, units and robots at Alert 2, the cordon at 3;
// units verify the scene (confirmed or unfounded), search, hold, and stand down. Also here: the staff check-in marks (Motive §5.1) and a
// person who misses an expected tie (§5.2).
// The response unit of §05 (the two officers of SecGuns, walking from the security entry) stays the first unit, so a run at level 1 with
// gunfire only is the run it was.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>One member of the response (a robot or an officer) sent by an alarm: where it starts and goes, what it is doing.</summary>
    public sealed class Unit
    {
        public string Id = ""; public bool Robot, Patrol, Legacy; public Gun Gun = null!; public int Speed;
        public Pt From, Dest; public int Launch; public Path? Route; public int Act = -1; public bool Scene, Cordon;
        public string St = "wait";   // wait (not yet on the street), walk, check, search, hold, back, gone
        public int Until, Arrive; public bool Verified;
        public readonly List<string> ToOpen = new List<string>(); public int NextOpen = -1;
        public bool OnStreet(int tick) => St != "wait" && St != "gone" && (Legacy || tick >= Launch);
    }

    public sealed partial class Game
    {
        public readonly List<Unit> Units = new List<Unit>();
        readonly SortedSet<string> missedMarks = new SortedSet<string>(StringComparer.Ordinal);       // staff whose missed check-in has landed
        readonly SortedDictionary<string, int> suspicious = new SortedDictionary<string, int>(StringComparer.Ordinal); // "waiter>expected": since when
        readonly List<string> extraCivGuns = new List<string>();                                         // crowd people shot at, by id
        int robotsSent, unitsSent, policeSeq, robotSeq, reinforceAt = INF, lastAlarm = -1, guardBackAt = -1;
        List<Pt> dests = new List<Pt>();

        /// <summary>The security level of this run (0..4): the scenario's, else the district's base + the mission's bonus.</summary>
        public int SecurityLevel => Start.Security ?? S.SecurityLevel;
        /// <summary>The last alarm's destinations, in order (Pulse §12.1): the scene first. For the HUD and the scenarios.</summary>
        public IReadOnlyList<Pt> AlarmDestinations => dests;
        public DialLevel DialNow => R.Dial[SecurityLevel];
        /// <summary>The seal after a confirmation (or a gunfire response's arrival), at this level.</summary>
        public int SealS => DialNow.SealS;
        /// <summary>A gunfire report's arrival at this level (rulebook security.rule): the delays are level 1's arrivals; the report lands the
        /// same seconds after the shot, the unit rolls this level's dispatch later. At level 1 exactly the delay.</summary>
        int GunfireArrival(int delayS) => Math.Max(Tick + 1, Tick + T(delayS) + T(DialNow.DispatchS) - T(R.Dial[1].DispatchS));

        // ---------------------------------------------------------------- an alarm

        /// <summary>A landed alarm (Pulse §12): the destination list, then the response the level sends at the Alert it leaves, topped up,
        /// never repeated. raiser: who called it (their ties are tier 3); the act's victim is the missing person (tier 2). step: a later
        /// report of an incident already dispatched raised Alert: the same destinations, topped up to the new Alert's counts.</summary>
        TdAct? lastAct;
        void Alarm(TdAct? a, Pt scene, Person? raiser, string stash, bool step = false)
        {
            lastAlarm = Tick; lastAct = a;
            var lv = DialNow;
            if (!step || dests.Count == 0) BuildDests(a, scene, raiser);
            int land = Tick;
            // robots: a1 at Alert 1, a2 from Alert 2 (the dial's count, topped up)
            int wantR = Alert >= 2 ? lv.A2Robots : Alert >= 1 ? lv.A1Robots : 0; // a level's count, topped up: robots already out stay out
            int launch = land + T(lv.DispatchS);
            int k = SendRobots(a, wantR, land, launch, stash);
            // units at Alert 2: the response unit first (§05), then police units; the cordon at Alert 3
            if (Alert >= 2)
            {
                int wantU = lv.A2Units;
                if (unitsSent < wantU && SecurityArrives == INF) { CallScene(launch, scene, a); }
                for (int i = 0; unitsSent < wantU && i < 16; i++) { if (!SendPolice(a, scene, true, launch + k * R.LaunchGapTicks, stash)) break; k++; }
                if (reinforceAt == INF && lv.ReinforceS > 0) reinforceAt = launch + T(lv.ReinforceS);
            }
            if (Alert >= 3 && !cordonSent) Cordon(launch + k * R.LaunchGapTicks);
            CoverScene(a, scene, stash, launch);
            Note("alarm.dispatches", $"{(step ? $"Alert {Alert}: the desk tops the response up" : "The desk sends the response")} (level {lv.Level}, {lv.Name}): {robotsSent} robot{(robotsSent == 1 ? "" : "s")}, {unitsSent} unit{(unitsSent == 1 ? "" : "s")}, on the street {Sim.Report.Clock(launch)}.");
        }
        bool cordonSent;
        /// <summary>A landed alarm's scene must be checked (Pulse §12.2: re-run at the next landed alarm): if no unit is sent to it, the
        /// response member nearest it in walking time (a robot or an officer, not the cordon; ties on id) is sent there instead.</summary>
        void CoverScene(TdAct? a, Pt scene, string stash, int launch)
        {
            if (a == null) return;
            var at = S.Grid.NearestFree(scene) ?? scene;
            foreach (var u in Units) if (u.St != "gone" && u.Act == a.Id && u.Scene && G.Within(u.Dest, at, witnessRange)) { if (stash.Length > 0 && !u.ToOpen.Contains(stash) && u.St != "hold") u.ToOpen.Add(stash); return; }
            Unit? best = null; int bt = int.MaxValue;
            foreach (var u in Units)
            {
                if (u.St == "gone" || u.St == "back" || u.Legacy || u.Cordon || u.Gun.Down) continue;
                if (u.Robot && !G.Within(u.Patrol ? SweepPos(Tick) : u.From, at, R.RobotReachCm)) continue; // beyond robot reach: for officers
                var from = u.St == "wait" ? (u.Patrol ? PatrolPose()!.Value.pos : u.From) : UnitPose(u)?.pos ?? u.From;
                int t = TravelTicks(from, at, u.Speed);
                if (t < bt || (t == bt && best != null && string.CompareOrdinal(u.Id, best.Id) < 0)) { bt = t; best = u; }
            }
            if (best == null) return;
            if (best.St != "wait")
            {
                var from = UnitPose(best)!.Value.pos; var route = S.Grid.Route(S.Grid.NearestFree(from) ?? from, at);
                best.Route = new Path(route != null && route.Length >= 2 ? route : new[] { from, at }); best.Launch = Tick; best.St = "walk"; // radioed: it turns now
            }
            best.Dest = at; best.Act = a.Id; best.Scene = true; best.Verified = false; best.ToOpen.Clear(); if (stash.Length > 0) best.ToOpen.Add(stash);
            Note("alarm.reassigns", $"{best.Id} is sent to the new scene.");
        }
        /// <summary>A gunfire report's response (Motive §5.3: gunfire is an alarm): the response unit is the first unit, then the level's
        /// Alert 2 robots to the scene and its destinations, the reinforcement clock and, at Alert 3, the cordon.</summary>
        void GunfireAlarm(int arrival, Pt scene)
        {
            lastAlarm = Tick; var lv = DialNow;
            unitsSent++;
            BuildDests(null, scene, null);
            int want = Alert >= 2 ? lv.A2Robots : lv.A1Robots;
            int land = arrival - T(lv.DispatchS);
            int k = SendRobots(null, want, land, arrival, "");
            if (reinforceAt == INF && lv.ReinforceS > 0 && Alert >= 2) reinforceAt = arrival + T(lv.ReinforceS);
            if (Alert >= 3 && !cordonSent) Cordon(arrival + k * R.LaunchGapTicks);
        }
        /// <summary>Robots to the alarm's places in order, one each, then round again while the level wants more (Pulse §12.2); a place no
        /// robot can take (beyond robot reach of every free robot) is left to the officers. Returns the robots sent.</summary>
        int SendRobots(TdAct? a, int want, int land, int launch, string stash)
        {
            int k = 0;
            for (int pass = 0; robotsSent < want && pass < 8; pass++)
            {
                bool any = false;
                foreach (var d in dests) { if (robotsSent >= want) break; if (SendRobot(a, d, land, launch + k * R.LaunchGapTicks, stash)) { k++; any = true; } }
                if (!any) break;
            }
            return k;
        }

        /// <summary>The destination list (Pulse §12.1; Aster 2026-10-16, both tiers): the scene; the missing person's post, car and ties' stands
        /// now; the raiser's ties' stands now; duplicates within witness range dropped.</summary>
        void BuildDests(TdAct? a, Pt scene, Person? raiser)
        {
            var l = new List<Pt>();
            void add(Pt? p) { if (!p.HasValue) return; var f = S.Grid.NearestFree(p.Value) ?? p.Value; foreach (var x in l) if (G.Within(x, f, witnessRange)) return; l.Add(f); }
            add(scene);
            if (a != null)
            {
                var v = a.P;
                var post = PostOf(v, Tick); if (post.HasValue) add(post.Value.at);
                if (v == Driver) add(CarPos());
                int n = 0; foreach (var t in TiePlaces(v, raiser)) { if (n++ >= R.AlarmSpread) break; add(t); }
            }
            if (raiser != null) { int n = 0; foreach (var t in TiePlaces(raiser, a?.P)) { if (n++ >= R.AlarmSpread) break; add(t); } }
            dests = l;
        }
        /// <summary>Where a person's lover, family and workmates are meant to be now (their routine; indoors, their unit's door), by kind
        /// then id; `skip` left out.</summary>
        IEnumerable<Pt> TiePlaces(Person p, Person? skip)
        {
            if (People2 == null || !People2.Ties.TryGetValue(p.Id, out var ts)) yield break;
            foreach (var kind in R.CloseTies.Count == 0 ? new List<string>() : new List<string> { "lover", "family", "workmate" })
            {
                var ids = new List<string>(); foreach (var (k, id) in ts) if (k == kind && R.CloseTies.Contains(k)) ids.Add(id);
                ids.Sort(StringComparer.Ordinal);
                foreach (var id in ids)
                {
                    var q = PersonById(id); if (q == null || q == skip) continue;
                    var at = PosOfPerson(q);
                    if (at.HasValue) { yield return at.Value; continue; }
                    var w = WalkerOf(q); if (w == null) continue;
                    var door = DoorOfStop(w, Tick); if (door.HasValue) yield return door.Value;
                }
            }
        }
        /// <summary>The staffed door of the unit a person's current stop is at (indoors), if any: "door:" + the place's id among the refuges.</summary>
        Pt? DoorOfStop(Walker w, int tick)
        {
            for (int i = 0; i < w.Place.Length; i++)
                if (tick >= w.From[i] && tick < w.To[i]) { foreach (var (id, at, kind) in S.Refuges) if (kind == "door" && id == "door:" + w.Place[i]) return at; return null; }
            return null;
        }

        /// <summary>The robot for a destination (Pulse §12.2): the patrol when it is on its sweep and nearer, else a robot from the nearest dock
        /// (none placed yet: the response unit's entry), one every launch.gap.</summary>
        bool SendRobot(TdAct? a, Pt dest, int land, int launch, string stash)
        {
            if (CombatantCount() >= R.CombatantCap) return false;
            bool patrolFree = !PatrolDown && !PatrolChasing && PatrolAwayUntil <= Tick && PatrolUnit() == null && !PatrolAlarmed;
            var origin = OriginOf(dest, S.Docks);
            // robot reach (Pulse §12.2; Motive rev 3): a robot takes a place only within robotReach of where it starts
            bool patrolCan = patrolFree && G.Within(PatrolPose()!.Value.pos, dest, R.RobotReachCm), dockCan = G.Within(origin, dest, R.RobotReachCm);
            if (!patrolCan && !dockCan) return false;
            Unit u;
            if (patrolCan && (!dockCan || TravelTicks(PatrolPose()!.Value.pos, dest, R.RobotSpeed) <= TravelTicks(origin, dest, R.RobotSpeed) + (launch - (land + T(R.RobotWireS)))))
            {
                u = new Unit { Id = "patrol", Robot = true, Patrol = true, Gun = PatrolGun, Speed = R.RobotSpeed, Launch = land + T(R.RobotWireS), Dest = dest, From = PatrolPose()!.Value.pos };
                PatrolAlarmed = true;
            }
            else u = new Unit { Id = "robot-" + (++robotSeq), Robot = true, Gun = NewGun("robot-" + robotSeq, R.Pistol, true, R.HealthPatrol), Speed = R.RobotSpeed, Launch = launch, From = origin, Dest = dest };
            u.Act = a?.Id ?? -1; u.Scene = dests.Count > 0 && G.Within(dest, dests[0], 100); if (u.Scene && stash.Length > 0) u.ToOpen.Add(stash);
            Units.Add(u); robotsSent++;
            return true;
        }
        bool PatrolAlarmed;
        bool SendPolice(TdAct? a, Pt dest, bool scene, int launch, string stash)
        {
            if (CombatantCount() + R.ResponseOfficers > R.CombatantCap) return false;
            var origin = OriginOf(dest, S.Posts);
            for (int k = 0; k < R.ResponseOfficers; k++)
            {
                var id = "police-" + (++policeSeq);
                var u = new Unit { Id = id, Gun = NewGun(id, R.Pistol, true, R.HealthOfficer), Speed = secSpeed, Launch = launch + k * R.LaunchGapTicks, From = origin, Dest = dest, Act = a?.Id ?? -1, Scene = scene };
                if (scene && stash.Length > 0) u.ToOpen.Add(stash);
                Units.Add(u);
            }
            unitsSent++;
            return true;
        }
        /// <summary>The response unit (§05's two officers) to a silent alarm's scene: it rolls at `arrival` from its entry; the seal waits for
        /// a confirmation (Motive §2.3). Its officers verify and search like any unit.</summary>
        void CallScene(int arrival, Pt scene, TdAct? a)
        {
            var from = S.Stand(S.SecEntry); var to = S.Grid.NearestFree(scene) ?? scene;
            var route = S.Grid.Route(from, to);
            if (route != null && route.Length >= 2) securityPath = new Path(route);
            SecurityArrives = arrival; unitsSent++;
            if (sealOnArrival) { sealOnArrival = false; SealFrom(arrival, () => pendingSealOrigin); }
            for (int k = 0; k < SecGuns.Length; k++) Units.Add(new Unit { Id = SecGuns[k].Id, Legacy = true, Gun = SecGuns[k], Speed = secSpeed, Launch = arrival, Dest = to, Act = a?.Id ?? -1, Scene = true, St = "walk" });
            Note("security.called", "The response unit is sent to the scene. Security is coming from the north street.");
        }
        void Cordon(int launch)
        {
            cordonSent = true; var lv = DialNow;
            var mouths = new List<Pt>(); foreach (var (id, at, kind) in S.Refuges) if (kind == "mouth") mouths.Add(S.Grid.NearestFree(at) ?? at);
            for (int i = 0; i < lv.A3Units && mouths.Count > 0; i++) { var u0 = Units.Count; if (!SendPolice(null, mouths[i % mouths.Count], false, launch + i * R.LaunchGapTicks, "")) break; for (int j = u0; j < Units.Count; j++) Units[j].Cordon = true; }
            if (lv.DoorsLock) Note("doors.lock", "Lockdown: the Office doors are locked.");
        }
        Pt OriginOf(Pt dest, List<(string id, Pt at)> places)
        {
            if (places.Count == 0) return S.Stand(S.SecEntry);
            (string id, Pt at) best = places[0]; long bd = long.MaxValue;
            foreach (var p in places) { long d = G.D2(p.at, dest); if (d < bd || (d == bd && string.CompareOrdinal(p.id, best.id) < 0)) { bd = d; best = p; } }
            return best.at;
        }
        int TravelTicks(Pt from, Pt to, int speed)
        {
            var a = S.Grid.NearestFree(from) ?? from; var b = S.Grid.NearestFree(to) ?? to;
            var route = S.Grid.Route(a, b); long len = route == null ? G.Dist(a, b) * 10L : new Path(route).Length;
            return (int)((len + speed - 1) / speed);
        }
        int CombatantCount()
        {
            int n = 0;
            if (!GuardDown && !GuardGun.Down) n++; if (!PatrolDown) n++;
            foreach (var g in SecGuns) if (!g.Down) n++;
            if (RivalsPresent) n++;
            foreach (var h in Hostiles) if (!h.Down && h.Present) n++;
            foreach (var u in Units) if (!u.Patrol && !u.Legacy && !u.Gun.Down && u.St != "gone") n++;
            return n;
        }
        public Unit? PatrolUnit() { foreach (var u in Units) if (u.Patrol && u.St != "gone" && u.St != "wait") return u; return null; }
        Unit? UnitOf(string id) { foreach (var u in Units) if (u.Id == id && !u.Legacy && !u.Patrol) return u; return null; }

        // ---------------------------------------------------------------- the units, a tick at a time

        /// <summary>Where a unit stands and faces now, or null off the street.</summary>
        public (Pt pos, Pt facing)? UnitPose(Unit u)
        {
            if (u.Legacy) { int k = SecIndex(u.Id); return k >= 0 ? SecOfficerPose(k) : null; }
            if (u.Gun.Down) return null;
            switch (u.St)
            {
                case "wait": case "gone": return null;
                case "walk": case "back":
                    {
                        if (u.Route == null) return (u.From, new Pt(100, 0));
                        long mm = (long)(Tick - u.Launch) * u.Speed; if (mm < 0) mm = 0;
                        return mm >= u.Route.Length ? (u.Route.End, u.Route.Heading(u.Route.Length)) : (u.Route.At(mm), u.Route.Heading(mm));
                    }
                default: return u.Route == null ? (u.Dest, new Pt(100, 0)) : (u.Route.End, u.Route.Heading(u.Route.Length));
            }
        }
        bool UnitSees(Unit u, Pt p, bool crowd = true)
        {
            var s = UnitPose(u); if (!s.HasValue) return false;
            return G.InCone(s.Value.pos, s.Value.facing, R.SecReachCm, R.SecHalfCm, near, p) && Sees(s.Value.pos, p) && !(crowd && CrowdBlocks(s.Value.pos, p));
        }

        void UnitsStep()
        {
            if (Units.Count == 0 && reinforceAt == INF) return;
            // an Alert step re-runs the dispatch (Pulse §12.2): units at Alert 2 after an Alert 1 alarm, the cordon at 3
            if (lastAlarm >= 0)
            {
                var lv0 = DialNow; int launch0 = Tick + T(lv0.DispatchS);
                if (Alert >= 2 && unitsSent == 0) { var sc = dests.Count > 0 ? dests[0] : S.Stand(S.SecTo); CallScene(launch0, sc, lastAct); if (reinforceAt == INF && lv0.ReinforceS > 0) reinforceAt = launch0 + T(lv0.ReinforceS); }
                if (Alert >= 2 && robotsSent < lv0.A2Robots) SendRobots(lastAct, lv0.A2Robots, Tick, launch0, "");
                if (Alert >= 3 && !cordonSent) Cordon(launch0);
            }
            // reinforcement (Motive §5.3): one more unit every `reinforce` while Alert is 2 or more, up to the cap (Alert 3's own on top)
            var lv = DialNow;
            if (Tick >= reinforceAt && Alert >= 2)
            {
                int cap = lv.UnitCap;
                if (unitsSent < cap && lv.ReinforceS > 0)
                {
                    var dest = FewestUnits();
                    if (SendPolice(null, dest, dests.Count > 0 && G.Within(dest, dests[0], 100), Tick, "")) Note("response.reinforces", $"Another unit is sent ({unitsSent} of {cap}).");
                }
                reinforceAt = unitsSent < cap && lv.ReinforceS > 0 ? Tick + T(lv.ReinforceS) : INF;
            }
            bool standDown = StoodDown();
            // by index: a search that opens a stash can find the body of an incident not yet reported, which lands and dispatches (Units
            // grows inside the loop; the same class of fault as ReportsStep's, brief 013 D). A unit added now waits for its launch.
            for (int ui = 0; ui < Units.Count; ui++)
            {
                var u = Units[ui];
                if (u.Gun.Down && u.St != "gone") { u.St = "gone"; if (u.Patrol) PatrolAlarmed = false; continue; }
                switch (u.St)
                {
                    case "wait":
                        if (Tick < u.Launch) break;
                        {
                            var from = u.Patrol ? PatrolPose()!.Value.pos : u.From;
                            var a = S.Grid.NearestFree(from) ?? from; var b = S.Grid.NearestFree(u.Dest) ?? u.Dest;
                            var route = S.Grid.Route(a, b); u.Route = new Path(route != null && route.Length >= 2 ? route : new[] { a, b });
                            u.Launch = Tick; u.St = "walk";
                            if (u.Patrol) Note("patrol.alarm", "The patrol leaves its sweep for the alarm.");
                        }
                        break;
                    case "walk":
                        if (u.Legacy) { if (Tick >= SecurityArrives && (long)(Tick - SecurityArrives) * secSpeed >= securityPath.Length) { u.St = "check"; u.Until = Tick + T(R.CheckS); u.Arrive = Tick; } break; }
                        if (u.Route != null && (long)(Tick - u.Launch) * u.Speed >= u.Route.Length) { u.St = "check"; u.Until = Tick + T(R.CheckS); u.Arrive = Tick; }
                        break;
                    case "check":
                        if (Tick < u.Until) break;
                        if (!u.Robot && u.Scene && (u.ToOpen.Count > 0 || Alert >= 2 || HeldScene(u))) // rev 4: a held scene's officers sweep it on arrival
                        {
                            u.St = "search"; u.Until = Tick + T(R.SearchS); u.NextOpen = Tick + T(R.SearchStashS);
                            if (Alert >= 2) foreach (var s in StashesNear(u.Act >= 0 ? Acts[u.Act].Scene : u.Dest)) if (!u.ToOpen.Contains(s) && !Units.Exists(o => o != u && o.St == "search" && o.ToOpen.Contains(s))) u.ToOpen.Add(s); // the unit's officers share the stashes out
                        }
                        else if (u.Robot && u.ToOpen.Count > 0) { u.St = "search"; u.Until = Tick + T(R.SearchS); u.NextOpen = Tick + T(R.SearchStashS); }
                        else u.St = "hold";
                        break;
                    case "search":
                        // the stash comes off the list before it is opened: a body inside lands its incident, which may send this very unit on
                        // to a new scene (CoverScene clears its list and turns it to walk; Keel 2026-10-16, an ArgumentOutOfRange at 7:58.5
                        // on a driver-route variant). Then the search is over here.
                        if (u.ToOpen.Count > 0 && Tick >= u.NextOpen) { var sid = u.ToOpen[0]; u.ToOpen.RemoveAt(0); u.NextOpen = Tick + T(R.SearchStashS); OpenStash(u, sid); if (u.St != "search") break; }
                        if (Tick >= u.Until && u.ToOpen.Count == 0) u.St = "hold";
                        break;
                }
                if (standDown && (u.St == "hold" || (u.St == "check" && !HeldScene(u))) && !u.Legacy && !u.Cordon)
                {
                    if (u.Patrol) { var p = UnitPose(u)!.Value.pos; u.St = "gone"; PatrolAlarmed = false; chasePos = p; PatrolChasing = true; patrolReturning = true; PatrolGun.NoFoeSince = -1; Note("patrol.stands-down", "The patrol goes back to its sweep."); continue; }
                    var here = UnitPose(u)!.Value.pos; var route = S.Grid.Route(S.Grid.NearestFree(here) ?? here, S.Grid.NearestFree(u.From) ?? u.From);
                    u.Route = new Path(route != null && route.Length >= 2 ? route : new[] { here, u.From }); u.Launch = Tick; u.St = "back";
                }
                if (u.St == "back" && u.Route != null && (long)(Tick - u.Launch) * u.Speed >= u.Route.Length) u.St = "gone";
                // verify the scene (Pulse §3.5): within witness range of it on a clear line
                if (u.Scene && !u.Verified && u.Act >= 0 && u.OnStreet(Tick) && !u.Gun.Down) Verify(u);
            }
            // what the response sees on its way and where it holds: bodies (Pulse §3.5)
            if (Tick % R.BodyCheckTicks == 0)
                foreach (var b in Bodies.ToArray())
                {
                    if (!b.Open || b.Seizing) continue;
                    foreach (var u in Units) if (u.OnStreet(Tick) && !u.Gun.Down && UnitSees(u, BodyPos(b))) { FoundBySecurity(b, u.Id); break; }
                }
        }
        Pt FewestUnits()
        {
            if (dests.Count == 0) return S.Stand(S.SecTo);
            Pt best = dests[0]; int bn = int.MaxValue;
            foreach (var d in dests) { int n = 0; foreach (var u in Units) if (!u.Robot && u.St != "gone" && G.Within(u.Dest, d, 100)) n++; if (n < bn) { bn = n; best = d; } }
            return best;
        }
        List<string> StashesNear(Pt at)
        {
            var l = new List<(long d, string id)>();
            foreach (var s in S.Stashes) { long d = G.D2(s.Stand, at); if (d <= (long)R.SearchStashCm * R.SearchStashCm) l.Add((d, s.Id)); }
            l.Sort((x, y) => x.d != y.d ? x.d.CompareTo(y.d) : string.CompareOrdinal(x.id, y.id));
            return l.ConvertAll(x => x.id);
        }

        /// <summary>A unit at the scene: an open body of the act there (or carried there) is confirmed; else unfounded (Pulse §3.5).</summary>
        void Verify(Unit u)
        {
            var a = Acts[u.Act]; var pose = UnitPose(u); if (!pose.HasValue) return;
            var scene = a.Scene;
            if (!G.Within(pose.Value.pos, scene, witnessRange) || !Sees(pose.Value.pos, scene)) return;
            u.Verified = true;
            var b = BodyOf(a.P);
            if (b != null && b.Open && !b.Seizing && G.Within(BodyPos(b), scene, witnessRange) && Sees(pose.Value.pos, BodyPos(b))) { FoundBySecurity(b, u.Id); return; }
            if (!a.Confirmed) Note("report.unfounded", $"{u.Id} finds nothing where {Who(a.P)} was reported.");
        }

        /// <summary>A stash opened by the search or a report from it: a body inside is found (out of it, beside it).</summary>
        void OpenStash(Unit u, string id)
        {
            var s = StashById(id); if (s == null) return;
            foreach (var b in Bodies.ToArray())
            {
                if (b.Stash != id) continue;
                var a = ActOf(b); a.Opened.Add(id);
                b.Stash = ""; b.At = s.Stand;
                Note("stash.opened", $"{u.Id} opens the {id}: {Who(b.P)} is inside.");
                FoundBySecurity(b, u.Id);
                return;
            }
            Note("stash.opened", $"{u.Id} opens the {id}: nothing.");
        }

        /// <summary>The response finds a body (its own eyes): its incident lands if it hadn't, and is confirmed.</summary>
        void FoundBySecurity(Body b, string by)
        {
            var a = ActOf(b); RoundsEnd("body-found"); // brief 022
            if (!a.Landed) LandAct(a, b.Dead ? "dead" : "down", by, null, BodyPos(b), SevOf(b.Dead ? "dead" : "down"), "");
            else HoldScene(a, b.Dead ? "dead" : "down", BodyPos(b)); // found by the response's own eyes after another report (a missed mark): the scene is held
            Confirm(a, b, by);
        }

        /// <summary>A confirmation (Motive §2.3; rulebook report.verifies): Alert to the confirmed level (a kill a search, a knockout stays),
        /// the act's Trail, a found killing's Standing, the seal at a confirmation at Alert 2 or more; a knocked-out victim is brought round.</summary>
        void Confirm(TdAct a, Body? b, string by)
        {
            if (a.Confirmed) return; a.Confirmed = true;
            if (a.Kill) RaiseAlert(Math.Max(a.Alert, R.AlertDead), "confirmed:dead:" + a.Victim);
            a.Alert = Math.Max(a.Alert, Alert);
            if (!a.Take) ChargeAct(a); // a Take keeps its own Trail (cell.take)
            if (a.Kill && !a.StandingPaid) { a.StandingPaid = true; MoveStanding(R.FoundKillStanding, "found-killing:" + a.Victim, "found-killing", Who(a.P)); }
            Note("report.confirmed", $"{by.Replace("camera:", "the camera ")} confirms {Who(a.P)}: {(a.Take ? "taken" : a.Kill ? "dead" : "out")}.");
            if (Alert >= 2) SealFrom(Math.Max(Tick, SecurityArrives), () => Confirmed(a, by)); // the seal is the unit's cordon: from the later of the confirmation and the unit on the street (Motive rev 3)
            if (b != null && !a.Kill && b.P.Down && Bodies.Contains(b) && !b.Seizing) Wake(b, true);
        }

        bool sealOnArrival; // confirmed at Alert 2 or more before the response unit was called: the seal waits for it
        void SealFrom(int at, Func<CauseOrigin?>? origin = null)
        {
            if (at >= INF) { sealOnArrival = true; if (origin != null) { try { pendingSealOrigin = origin(); } catch (Exception e) when (!(e is OutOfMemoryException)) { } } return; }
            int seal = at + T(SealS);
            if (seal < Lockdown) { int lockBefore = Lockdown; Lockdown = seal; if (origin != null) SealOrigin(lockBefore, origin); Note("seal.starts", $"Confirmed at Alert {Alert}: the district seals {SealS} s after the unit is on the street ({Sim.Report.Clock(at)})."); }
        }

        // ---------------------------------------------------------------- the scene held (Motive rev 4 R4.1; Sky 2026-10-16)

        /// <summary>A found body's scene: where it lay when its report landed, and the entrances the unit there holds.</summary>
        public sealed class SceneHold { public int Act; public Pt At; public readonly List<string> Doors = new List<string>(); }
        public readonly List<SceneHold> SceneHolds = new List<SceneHold>();

        /// <summary>The entrances a unit at `at` holds (rev 4 R4.1): the one the body lies at (within near) and every entrance within witness
        /// range on a clear line (the witness test, so the price can show it). In the site's order.</summary>
        public List<string> DoorsInSightOf(Pt at)
        {
            var l = new List<string>();
            foreach (var e in S.Entrances) if (G.Within(e.at, at, near) || (G.Within(e.stand, at, witnessRange) && Sees(at, e.stand))) l.Add(e.id);
            return l;
        }
        string NearestEntrance(Pt p) { string best = ""; long bd = long.MaxValue; foreach (var e in S.Entrances) { long d = G.D2(e.at, p); if (d < bd) { bd = d; best = e.id; } } return best; }
        /// <summary>The door Enter goes in by (the public door at the guard's post) and the one the Enforcer comes out by with Vale (the
        /// service door by the lane): the site's entrances nearest each.</summary>
        public string EnterDoor => NearestEntrance(S.At(S.GuardPost));
        public string ExitDoor => NearestEntrance(S.Stand(S.ValeService));
        /// <summary>The response stands down (existing timers): stand-down.inquiry after the last alarm at Alert 1, .search at 2, never at 3.</summary>
        bool StoodDown() => Alert < 3 && lastAlarm >= 0 && Tick - lastAlarm >= T(Alert >= 2 ? R.StandDownSearchS : R.StandDownInquiryS);
        bool HeldScene(Unit u) => !u.Robot && u.Scene && u.Act >= 0 && SceneHolds.Exists(h => h.Act == u.Act);
        /// <summary>A scene is held from an officer's arrival at it (checking, searching) until the unit stands down.</summary>
        bool HoldActive(SceneHold h)
        {
            foreach (var u in Units)
            {
                if (u.Robot || u.Act != h.Act || !u.Scene || u.Gun.Down) continue;
                if (!(u.St == "check" || u.St == "search" || (u.St == "hold" && !StoodDown()))) continue;
                var p = UnitPose(u); if (p.HasValue && G.Within(p.Value.pos, h.At, witnessRange)) return true;
            }
            return false;
        }
        /// <summary>Is this entrance held now (no Enter, no exit through it)?</summary>
        public bool DoorHeld(string id) { if (id.Length == 0) return false; foreach (var h in SceneHolds) if (h.Doors.Contains(id) && HoldActive(h)) return true; return FixtureHeldUntil(id) >= 0; }
        /// <summary>Test only (Start.Holds, N85): the tick a start fixture's hold on this door ends, if one holds it now; else -1.</summary>
        int FixtureHeldUntil(string id) { int end = -1; foreach (var (d, f, u) in Start.Holds) if (d == id && Tick >= T(f) && Tick < T(u)) end = Math.Max(end, T(u)); return end; }

        /// <summary>A report that a body lies here has landed (rev 4 R4.1): the scene is held. "Found" is a landed report of a person lying
        /// (down, dead, a takedown seen) whose body is still there, open, or a woken victim's own report where he woke; an empty post (a
        /// missed mark), a missing person, a carry or a body already moved holds nothing. The unit comes at any Alert, officers (no robot
        /// reach), the level's dispatch after the landing, unless one is already sent to this act's scene (Alert 2's response unit); it is
        /// not one of the dial's counted units. One hold an act.</summary>
        void HoldScene(TdAct a, string kind, Pt place)
        {
            if (a.Take || !(kind == "down" || kind == "dead" || kind == "seen" || kind == "woken")) return;
            foreach (var x in SceneHolds) if (x.Act == a.Id) return;
            Pt at; var b = BodyOf(a.P);
            if (b != null && b.Open && !b.Carrier.HasValue && G.Within(b.At, place, witnessRange)) at = b.At;
            else if (kind == "woken") at = place;
            else return;
            var h = new SceneHold { Act = a.Id, At = at }; h.Doors.AddRange(DoorsInSightOf(at));
            SceneHolds.Add(h);
            if (!Units.Exists(u => !u.Robot && u.Act == a.Id && u.Scene && u.St != "gone" && u.St != "back" && G.Within(u.Dest, S.Grid.NearestFree(at) ?? at, witnessRange))) // a unit already bound for this scene (Alert 2's response unit)
            {
                int counted = unitsSent;
                if (SendPolice(a, S.Grid.NearestFree(at) ?? at, true, Tick + T(DialNow.DispatchS), "")) { unitsSent = counted; Note("security.called", $"A body is found: a unit is sent to hold the scene{(h.Doors.Count > 0 ? " (" + string.Join(", ", h.Doors) + ")" : "")}. Security is coming."); }
            }
        }

        // ---------------------------------------------------------------- check-in marks (Motive §5.1)

        /// <summary>A staff person's post now or next in their routine (a stop at a staffed door's place), and its shift (contiguous stops
        /// there). The cast guard's post is the mission's (he holds it all mission).</summary>
        (string place, Pt at, int from, int to)? PostOf(Person p, int tick)
        {
            if (!IsStaff(p)) return null;
            var stops = StopsOf(p); if (stops == null) return null;
            for (int i = 0; i < stops.Count; i++)
            {
                var (place, from, to, _) = stops[i];
                Pt? door = null; foreach (var (id, at, kind) in S.Refuges) if (kind == "door" && id == "door:" + place) door = at;
                if (!door.HasValue) continue;
                int j = i; while (j + 1 < stops.Count && stops[j + 1].place == place && stops[j + 1].from == stops[j].to) j++;
                int end = p == GuardP ? INF : stops[j].to;
                if (end > tick) return (place, door.Value, from, end);
                i = j;
            }
            return null;
        }
        List<(string place, int from, int to, bool outside)>? StopsOf(Person p) => People2 != null && People2.Stops.TryGetValue(p.Id, out var s) ? s : null;
        /// <summary>The next check-in mark at or after `tick` of a staff person (ticks), or -1.</summary>
        public int NextMarkOf(Person p, int tick)
        {
            var post = PostOf(p, tick); if (!post.HasValue) return -1;
            int period = T(R.CheckInPeriodS), from = post.Value.from;
            int k = tick <= from ? 0 : (tick - from + period - 1) / period;
            int m = from + k * period;
            return Math.Min(m, post.Value.to);
        }

        /// <summary>At each mark, a staff person who is down, held or hidden misses it: the report lands at the mark, at the post (Alert mark).
        /// The guard shot (no takedown) is the same: his missed mark calls the response (Motive §5.1; retires the 18 s check-in).</summary>
        void CheckIns()
        {
            int period = T(R.CheckInPeriodS);
            foreach (var b in Bodies)
            {
                var p = b.P; if (!IsStaff(p) || missedMarks.Contains(p.Id)) continue;
                var post = PostOf(p, Tick); if (!post.HasValue || Tick < post.Value.from) continue;
                if ((Tick - post.Value.from) % period != 0 && Tick != post.Value.to) continue;
                missedMarks.Add(p.Id);
                var a = ActOf(b); a.MarkMissed = true;
                Note("post.missed", $"{Who(p)} misses his check-in at {Sim.Report.Clock(Tick)}. The post is reported empty.");
                LandAct(a, "mark", "desk", null, post.Value.at, R.AlertMark, "");
            }
            if (GuardDown && BodyOf(GuardP) == null && !missedMarks.Contains(GuardP.Id))
            {
                var post = PostOf(GuardP, Tick);
                if (post.HasValue && Tick >= post.Value.from && (Tick - post.Value.from) % period == 0)
                {
                    missedMarks.Add(GuardP.Id); MissingNotice = Tick;
                    Note("guard.check-in", "The guard misses his check-in. Security now knows the post is empty.");
                    CallSecurity(0, "The empty guard post is reported.", S.Stand(S.GuardPost), landing: true, origin: () => OriginNow("post-empty:guard", "response", "desk", S.Stand(S.GuardPost), S.Stand(S.GuardPost), null, OpIn(GuardGun.ShotBy)));
                }
            }
        }

        // ---------------------------------------------------------------- a missing expected person (Motive §5.2; Pulse §11)

        /// <summary>Once a second: a person who shares a stop at one place with a lover, family member or workmate (both routines; never
        /// authored), is at it, and finds them down, held or hidden while their routine puts them there, raises the alarm after
        /// suspicion.s (× suspicion.pm by temperament): a missing-person report from where they stand. A turned waiter (not a lover) and a
        /// person being taken report nothing.</summary>
        void Suspicion()
        {
            if (Tick % Hz != 0 || People2 == null) return;
            foreach (var b in Bodies)
            {
                var q = b.P; var qs = StopsOf(q); if (qs == null) continue;
                foreach (var (place, qFrom, qTo, _) in qs)
                {
                    if (Tick < qFrom || Tick >= qTo || place == "beyond") continue;
                    if (!People2.Places.TryGetValue(place, out var placeAt)) continue;
                    if (!People2.Ties.TryGetValue(q.Id, out var ts)) continue;
                    var ids = new List<(string kind, string id)>(); foreach (var (k, id) in ts) if (R.CloseTies.Contains(k)) ids.Add((k, id));
                    ids.Sort((x, y) => string.CompareOrdinal(x.id, y.id));
                    foreach (var (kind, id) in ids)
                    {
                        var p = PersonById(id); if (p == null || p.Down) continue;
                        if (p == ValeP && (Vale == ValeAt.Taking || Vale == ValeAt.WithEnforcer)) continue; // a held person reports nothing
                        string key = p.Id + ">" + q.Id;
                        if (ActOf(b).Noticed.Contains(p.Id)) continue; // they saw it, found him or were told: no suspicion, they know
                        if (!AtPlace(p, place, placeAt, q)) { if (suspicious.TryGetValue(key, out var s0) && s0 >= 0) suspicious.Remove(key); continue; }
                        if (IsCellPerson(p) && kind != "lover") continue;
                        if (!suspicious.TryGetValue(key, out var since)) { suspicious[key] = Tick; continue; }
                        if (since < 0) continue; // raised already
                        int pm = R.SuspicionPm.TryGetValue(p.Temperament, out var v) ? v : 1000;
                        if (Tick - since < T(R.SuspicionS) * pm / 1000) continue;
                        suspicious[key] = -1;
                        var a = ActOf(b);
                        Remember(p, "missed-expected", "", false);
                        Note("person.missed", $"{Who(p)} expected {Who(q)} at {place} and grows suspicious.");
                        var at = PosOfPerson(p) ?? placeAt;
                        if (IsStaff(p) || PosOfPerson(p) == null) AddRep(a, "missing", p.Id, p, placeAt, Tick + T(IsStaff(p) ? R.PostCallS : R.CallS), "radio");
                        else WalkToPhone(a, p, WalkerOf(p), "missing", at, opSpeed, Tick, placeAt, "");
                    }
                }
            }
        }
        /// <summary>Walking somewhere: a person of the crowd between two stops or not on their routine, Vale on his way to the car, the guard
        /// on his walk.</summary>
        bool OnTheWay(Person p)
        {
            if (WalkerOf(p) is Walker w)
            {
                if (w.St.Length > 0) return true;
                for (int i = 0; i < w.Place.Length; i++) if (Tick >= w.From[i] && Tick < w.To[i]) return false;
                return true;
            }
            if (p == ValeP) return Vale == ValeAt.Leaving;
            if (p == GuardP) { var gp = GuardPose(); return gp.HasValue && gp.Value.phase != "door" && gp.Value.phase != "at café"; }
            return false;
        }
        /// <summary>The vehicle bound to a person (Pulse §12.1): the official car is its driver's; where it stands now.</summary>
        Pt? VehicleOf(Person q) => q == Driver ? CarPos() : (Pt?)null;
        /// <summary>The person is at the place: on the street within meet of it or of the expected person's own vehicle (waiting at the car the
        /// driver left), or (indoors) their routine's stop is that place now.</summary>
        bool AtPlace(Person p, string place, Pt placeAt, Person q)
        {
            var at = PosOfPerson(p);
            if (at.HasValue && OnTheWay(p)) return false; // the expectation opens when they arrive (Pulse §11.1): on the way, nobody is waiting yet
            if (at.HasValue) return G.Within(at.Value, placeAt, R.MeetCm) || (VehicleOf(q) is Pt car && G.Within(at.Value, car, R.MeetCm));
            if (WalkerOf(p) is Walker w) for (int i = 0; i < w.Place.Length; i++) if (Tick >= w.From[i] && Tick < w.To[i]) return w.Place[i] == place && !w.Out[i];
            return false;
        }

        // ---------------------------------------------------------------- the step, and the units in a fight

        /// <summary>Brief 013's tick, after the crowd's: bodies, reports, check-in marks, suspicion, the response's units. Nothing runs, and
        /// nothing is hashed, until a takedown, a downed guard or an alarm.</summary>
        void TakedownStep()
        {
            TakeScan(); if (Over) return; // before the early return: an unseen Take opens nothing
            if (Acts.Count == 0 && Units.Count == 0 && !GuardDown && reinforceAt == INF && guardBackAt < 0) return;
            if (guardBackAt >= 0 && Tick >= guardBackAt) GuardBack();
            BodiesStep(); if (Over) return;
            ReportsStep(); if (Over) return;
            CheckIns(); if (Over) return;
            Suspicion(); if (Over) return;
            UnitsStep();
        }
        void GuardBack()
        {
            guardBackAt = -1; if (GuardDown || !GuardHeld || heldPhase != "woken") return;
            var from = heldPos; GuardHeld = false;
            guardRun = new Path(S.Grid.Route(S.Grid.NearestFree(from) ?? from, S.Stand(S.GuardPost)) ?? new[] { from, S.Stand(S.GuardPost) });
            guardRunning = true; LureTick = Tick; GuardAwayUntil = Tick + (int)((guardRun.Length + secSpeed - 1) / secSpeed);
            Note("guard.back-to-post", "The guard walks back to his post.");
        }

        /// <summary>The response's units fire like the city's other gunmen (Pulse §1): before the final fight, at an operative with a weapon
        /// out, who has fired, who holds Vale, or whom security saw do violence.</summary>
        void UnitsCombat()
        {
            foreach (var u in Units)
            {
                if (u.Legacy || u.Gun.Down || !u.OnStreet(Tick)) continue;
                var pose = UnitPose(u); if (!pose.HasValue) continue;
                var uu = u; PreFight(u.Id, u.Gun, pose.Value.pos, p => UnitSees(uu, p, false));
            }
        }

        internal void HashResponse(Hash.H h)
        {
            h.I(robotsSent).I(unitsSent).I(reinforceAt).I(lastAlarm).I(guardBackAt).Z(cordonSent).Z(PatrolAlarmed).Z(sealOnArrival);
            if (SceneHolds.Count > 0) { h.S("holds"); foreach (var x in SceneHolds) { h.I(x.Act).P(x.At); foreach (var d in x.Doors) h.S(d); h.I(-1); } } // rev 4: only runs with a held scene add bytes
            foreach (var d in dests) h.P(d);
            foreach (var u in Units)
            {
                h.S(u.Id).S(u.St).I(u.Launch).I(u.Until).I(u.Arrive).Z(u.Verified).I(u.Act).Z(u.Scene).Z(u.Cordon).P(u.Dest).I(u.NextOpen);
                foreach (var s in u.ToOpen) h.S(s);
                var p = UnitPose(u); h.Z(p.HasValue); if (p.HasValue) h.P(p.Value.pos);
                if (!u.Legacy && !u.Patrol) Hash.HashGun(h, u.Gun);
            }
        }
    }
}

sim/Suborned.Sim/GameRounds.cs.text:
// The living café (brief 022, Pulse; Sky 2026-10-18: "have the waitress also walk around the cafe tables, and when guard comes, they stand
// together"). The round is baked at build time (tools/routines/rounds.ts → sim/data/handover.rounds.json); the engine reads it and plays it on a
// round clock that stops while she is held (rulebook rounds). This is tools/routines/rounds.ts poseAt in integers, piece for piece:
//  · free: the round clock runs with the mission; she rests at her post and goes out to a table (to table, serving, from table)
//  · held: an order of a verb in rounds.holds taken on her, from the tick it is taken to the tick it lands, plus rounds.linger; she stands
//    where she is, turned to the operative; an order taken inside the linger is the same hold, longer. Watch holds nothing.
//  · called: the summons; she walks back to her post the way she came, waits, stands together with him from his arrival to his turn plus
//    rounds.part, and the round resumes at the start of its next rest
//  · ended: at the first of rounds.ends she walks back and stands her post for the rest of the mission
// Every reader of her position (reach, witnesses, sight, the summons' lover-within) reads PersonPos, which is the round's.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>The baked rounds (suborned.sim.rounds/1), read strictly: unknown = reject.</summary>
    public sealed class RoundsData
    {
        public sealed class Exc { public string Table = ""; public Pt At, Face; public int Start, Out, Serve, Back; public Path Path = null!; }
        public sealed class Server { public string Id = "", Role = "", Post = ""; public Pt At, Face; public int From, To, Origin; public readonly List<Exc> Exc = new List<Exc>(); }
        public readonly Dictionary<string, Server> Servers = new Dictionary<string, Server>(StringComparer.Ordinal);
        public int LingerS, CloseCm, ClearCm, PartS, StayS, PaceCmPerS;
        public Pt GuardStopAt, GuardFace; public int GuardWalkCm, GuardStopWalkCm;
        /// <summary>Where the summoned partner may stand, in the file's order (ring of CloseCm round her post, free ground, most lateral first, her left first): the engine picks, never computes.</summary>
        public readonly List<Pt> GuardStops = new List<Pt>();
        /// <summary>The reference poses (tick, x, y, facing x, facing y, phase) by server and kind: free, held, called, ended (tests read them).</summary>
        public readonly Dictionary<string, Dictionary<string, List<(int tick, Pt pos, Pt face, string phase)>>> Vectors = new Dictionary<string, Dictionary<string, List<(int, Pt, Pt, string)>>>(StringComparer.Ordinal);

        public static RoundsData Parse(string json, Rules r, Site site)
        {
            var n = JNode.Parse(json, "rounds"); var d = new RoundsData();
            n.Only("schema", "from", "frame", "rules", "servers", "meetings", "guard", "vectors");
            if (n["schema"].Str() != "suborned.sim.rounds/1") throw new FormatException("rounds schema is not suborned.sim.rounds/1");
            var ru = n["rules"]; ru.Only("file", "sha256", "paceCmPerS", "lingerS", "closeCm", "clearCm", "partS", "settleS", "stayS", "chanceStayS");
            d.LingerS = ru["lingerS"].Int(); d.CloseCm = ru["closeCm"].Int(); d.ClearCm = ru["clearCm"].Int(); d.PartS = ru["partS"].Int(); d.StayS = ru["stayS"].Int(); d.PaceCmPerS = ru["paceCmPerS"].Int();
            // the baked numbers are the rulebook's (Motive confirms them there): a file baked from other numbers is rejected
            if (d.LingerS != r.RoundsLingerS || d.CloseCm != r.PartnersCloseCm || d.ClearCm != r.PartnersClearCm || d.PartS != r.PartnersPartS || d.StayS != r.SummonStayS || d.PaceCmPerS != r.CellSpeed)
                throw new FormatException("rounds.rules (lingerS, closeCm, clearCm, partS, stayS, paceCmPerS) are not the rulebook's rounds.linger, rounds.close, rounds.clear, rounds.part, summon.stay and cell.speed: rebake (bun run rounds)");
            if (n["meetings"].Items.Count > 0) throw new FormatException("rounds.meetings: chance meetings are not played yet (brief 022 §2.6): unknown = reject");
            foreach (var kv in n["servers"].Entries)
            {
                var v = kv.Value; v.Only("name", "post", "at", "face", "spans");
                var role = site.Cast.Find(c => c.Id == kv.Key)?.Role ?? throw new FormatException($"rounds.servers.{kv.Key} is not cast: only the cast is played by the engine (unknown = reject)");
                var sv = new Server { Id = kv.Key, Role = role, Post = v["post"].Str(), At = Pt.Of(v["at"]), Face = Pt.Of(v["face"]) };
                var spans = v["spans"].Items; if (spans.Count != 1) throw new FormatException($"rounds.servers.{kv.Key}: one span is played (brief 022), not {spans.Count}");
                var sp = spans[0]; sp.Only("place", "from", "to", "origin", "excursions");
                if (sp["place"].Str() != sv.Post) throw new FormatException($"rounds.servers.{kv.Key}: the span's place is the post");
                sv.From = sp["from"].Int(); sv.To = sp["to"].Int(); sv.Origin = sp["origin"].Int();
                if (sv.Origin != Math.Max(0, sv.From) || sv.To <= Math.Max(0, sv.From)) throw new FormatException($"rounds.servers.{kv.Key}: origin is max(0, from) and the span is not empty");
                int last = -1;
                foreach (var e in sp["excursions"].Items)
                {
                    e.Only("table", "at", "face", "start", "out", "serve", "back", "m", "path");
                    var pts = new List<Pt>(); foreach (var q in e["path"].Items) pts.Add(Pt.Of(q));
                    var x = new Exc { Table = e["table"].Str(), At = Pt.Of(e["at"]), Face = Pt.Of(e["face"]), Start = e["start"].Int(), Out = e["out"].Int(), Serve = e["serve"].Int(), Back = e["back"].Int(), Path = new Path(pts.ToArray()) };
                    if (pts.Count < 2 || pts[0] != sv.At || pts[pts.Count - 1] != x.At) throw new FormatException($"{e.Path}.path runs from the post to the service point");
                    if (x.Out < 1 || x.Serve < 1 || x.Back < 1 || x.Start <= last) throw new FormatException($"{e.Path}: legs are whole seconds, excursions in order");
                    last = x.Start + x.Out + x.Serve + x.Back - 1;
                    sv.Exc.Add(x);
                }
                d.Servers[sv.Id] = sv;
                var vec = new Dictionary<string, List<(int, Pt, Pt, string)>>(StringComparer.Ordinal);
                if (n["vectors"].Opt(kv.Key) is JNode vs)
                    foreach (var k in vs.Entries)
                    {
                        var rows = new List<(int, Pt, Pt, string)>();
                        foreach (var row in k.Value.Items) { var it = row.Items; rows.Add((it[0].Int(), new Pt(it[1].Int(), it[2].Int()), new Pt(it[3].Int(), it[4].Int()), it[5].Str())); }
                        vec[k.Key] = rows;
                    }
                d.Vectors[sv.Id] = vec;
            }
            var g = n["guard"]; g.Only("from", "post", "walkCm", "ringCm", "stopAt", "face", "stops");
            d.GuardStopAt = Pt.Of(g["stopAt"]); d.GuardFace = Pt.Of(g["face"]); d.GuardWalkCm = g["walkCm"].Int();
            if (g["ringCm"].Int() != d.CloseCm) throw new FormatException("rounds.guard.ringCm is rules.closeCm");
            foreach (var st in g["stops"].Items) { st.Only("at", "face", "deg", "walkCm"); if (d.GuardStops.Count == 0) d.GuardStopWalkCm = st["walkCm"].Int(); d.GuardStops.Add(Pt.Of(st["at"])); }
            if (d.GuardStops.Count > 0 && d.GuardStops[0] != d.GuardStopAt) throw new FormatException("rounds.guard.stopAt is stops[0]");
            return d;
        }
    }

    /// <summary>A server's pose: where she is, which way she faces, and what she is doing (at post, to table, serving, from table, held, to
    /// post, together).</summary>
    public struct RoundPose { public Pt Pos, Face; public string Phase; }

    /// <summary>What the mission did to a server's round, in ticks: the holds (taken, landed; the linger is added when played), the call, the end.</summary>
    public sealed class RoundEvents
    {
        public sealed class Hold { public int From, To; public Pt Face; public OpId By; }
        public readonly List<Hold> Holds = new List<Hold>();
        public int CallAt = -1, CallArrive, CallUntil; public Pt CallStop;
        public int EndAt = -1; public string EndWhy = "";
        public int Version;
    }

    public sealed partial class Game
    {
        /// <summary>Brief 022: the round is played (the mission's rounds file is loaded and the start doesn't switch it off).</summary>
        public bool RoundsOn => S.Rounds != null && (Start.Rounds ?? true);
        readonly Dictionary<string, RoundEvents> roundEv = new Dictionary<string, RoundEvents>(StringComparer.Ordinal);
        readonly Dictionary<string, (int version, List<Piece> pieces)> roundCache = new Dictionary<string, (int, List<Piece>)>(StringComparer.Ordinal);

        RoundsData.Server? ServerOf(Person p) => RoundsOn && S.Rounds!.Servers.TryGetValue(p.Id, out var sv) ? sv : null;
        RoundEvents EvOf(RoundsData.Server sv) { if (!roundEv.TryGetValue(sv.Id, out var e)) roundEv[sv.Id] = e = new RoundEvents(); return e; }
        readonly RoundEvents noEvents = new RoundEvents();
        /// <summary>The events for reading only (the HUD, PersonPos, the hash): never creates state, so a read can't change a run.</summary>
        RoundEvents EvRead(RoundsData.Server sv) => roundEv.TryGetValue(sv.Id, out var e) ? e : noEvents;

        /// <summary>Where a person stands and faces now, and their phase: a server's from her round; anyone else from PersonPos (phase "").</summary>
        public (Pt pos, Pt facing, string phase)? PersonPose(Person p)
        {
            if (p.Down) return null;
            var sv = ServerOf(p);
            if (sv == null) { var at = PersonPos(p); return at.HasValue ? (at.Value, new Pt(0, 0), "") : ((Pt, Pt, string)?)null; }
            var q = RoundPoseAt(sv, EvRead(sv), Tick); return (q.Pos, q.Face, q.Phase);
        }
        /// <summary>Where a server will be `ticks` from now if nothing more is done to her (the HUD; Preview aims there). Others: as now.</summary>
        public (Pt pos, Pt facing, string phase)? PoseAhead(Person p, int ticks)
        {
            if (p.Down) return null;
            var sv = ServerOf(p); if (sv == null) return PersonPose(p);
            var q = RoundPoseAt(sv, EvRead(sv), Tick + Math.Max(0, ticks)); return (q.Pos, q.Face, q.Phase);
        }
        /// <summary>Ticks until a server is next at her post, standing (0 if she is now); -1 if she has no round (or never, within 5 minutes).</summary>
        public int RoundNext(Person p)
        {
            var sv = ServerOf(p); if (sv == null || p.Down) return -1;
            var ev = EvRead(sv);
            for (int k = 0; k <= T(300); k++) { var q = RoundPoseAt(sv, ev, Tick + k); if (q.Phase == "at post" || q.Phase == "together") return k; }
            return -1;
        }

        /// <summary>An order of a verb in rounds.holds is taken on a server: she stands still until it lands (plus the linger), turned to the operative.</summary>
        void RoundHold(Person p, Op op, string verb, int landsAt)
        {
            var sv = ServerOf(p); if (sv == null || !R.RoundHolds.Contains(verb)) return;
            var ev = EvOf(sv); var me = RoundPoseAt(sv, ev, Tick).Pos;
            var f = op.Pos - me; if (f == new Pt(0, 0)) f = sv.Face;
            ev.Holds.Add(new RoundEvents.Hold { From = Tick, To = landsAt, Face = f, By = op.Id }); ev.Version++;
        }
        /// <summary>An operative's order ends early (cancelled, or the operative down): a hold it made ends now (its linger still follows).</summary>
        void RoundHoldCut(Op op)
        {
            foreach (var ev in roundEv.Values)
                foreach (var h in ev.Holds) if (h.By == op.Id && h.To > Tick) { h.To = Tick; ev.Version++; }
        }
        /// <summary>The summoned partner's stop (brief 022 addendum, partners.summoned.side): the first stop in the file with nobody within partners-clear-cm of it at the tick of the call
        /// (the operatives not down and not inside, the patrol, and everyone on the street by the engine's own OnTheStreet: the cast by role, the crowd when Start.Crowd;
        /// not the server and not the summoned); if every stop is taken, the one whose nearest person is farthest, the earlier on a tie; integer distances, a fixed order:
        /// the same people give the same stop. Null when the file holds no stop (the old stop: on his route, close short of her post).</summary>
        Pt? PartnerStop(Person server, Person lover)
        {
            var stops = S.Rounds!.GuardStops; if (stops.Count == 0) return null;
            var people = new List<Pt>();
            foreach (var op in Ops) if (!op.Down && !op.Inside) people.Add(op.Pos);
            if (!PatrolDown && PatrolPose() is var pp && pp.HasValue) people.Add(pp.Value.pos);
            foreach (var (who, at) in OnTheStreet()) if (who != server && who != lover) people.Add(at);
            Pt best = stops[0]; long bestD = -1;
            foreach (var st in stops)
            {
                long near = long.MaxValue; foreach (var q in people) near = Math.Min(near, G.Dist(st, q));
                if (near >= R.PartnersClearCm) return st;
                if (near > bestD) { bestD = near; best = st; }
            }
            return best;
        }
        /// <summary>The summons reaches a server (brief 022): she walks back to her post, and they stand together while he stays.</summary>
        void RoundCall(Person p, int arrive, int until, Pt stop)
        {
            var sv = ServerOf(p); if (sv == null) return;
            var ev = EvOf(sv); if (ev.CallAt >= 0) return;
            ev.CallAt = Tick; ev.CallArrive = arrive; ev.CallUntil = until; ev.CallStop = stop; ev.Version++;
        }
        /// <summary>The round ends for the rest of the mission (rounds.ends: alert-2, gunfire, body-found, final-fight): she walks back and stands her post.</summary>
        void RoundsEnd(string why)
        {
            if (!RoundsOn || !R.RoundEnds.Contains(why)) return;
            foreach (var sv in S.Rounds!.Servers.Values)
            {
                var ev = EvOf(sv); if (ev.EndAt >= 0) continue;
                ev.EndAt = Tick; ev.EndWhy = why; ev.Version++;
                Note("round.ends", $"{why}: {(PersonById(sv.Id)?.Name ?? sv.Id)} walks back to her post and stays there.");
            }
        }

        // ---------------------------------------------------------------- the pose (tools/routines/rounds.ts poseAt, in integers)

        sealed class Piece
        {
            public int From, To; public string Kind = ""; // run, fixed, walk
            public int C0; public Pt Pos, Face; public string Phase = "";
            public Path? WPath; public long StartMm; public int Dur;
        }

        static long RoundHalf(long num, long den) => den <= 0 ? 0 : (2 * num + den) / (2 * den); // Math.round(num / den) for num, den ≥ 0

        /// <summary>The nominal round, on its clock in ticks from the origin: at post, or an excursion's legs.</summary>
        static RoundPose BodyPose(RoundsData.Server sv, int tr)
        {
            foreach (var x in sv.Exc)
            {
                int t0 = x.Start * Hz, t1 = t0 + x.Out * Hz, t2 = t1 + x.Serve * Hz, t3 = t2 + x.Back * Hz;
                if (tr < t0 || tr >= t3) continue;
                if (tr < t1) { long mm = RoundHalf(x.Path.Length * (tr - t0), t1 - t0); return new RoundPose { Pos = x.Path.At(mm), Face = x.Path.Heading(mm), Phase = "to table" }; }
                if (tr < t2) return new RoundPose { Pos = x.At, Face = x.Face, Phase = "serving" };
                long m2 = RoundHalf(x.Path.Length * (t3 - tr), t3 - t2); var h = x.Path.Heading(m2);
                return new RoundPose { Pos = x.Path.At(m2), Face = new Pt(-h.X, -h.Y), Phase = "from table" };
            }
            return new RoundPose { Pos = sv.At, Face = sv.Face, Phase = "at post" };
        }
        /// <summary>The walk home from round-clock tick tr: the path, where on it she is, and how long it takes (rounds.ts walkBack).</summary>
        static (Path path, long startMm, int dur)? WalkBack(RoundsData.Server sv, int tr)
        {
            foreach (var x in sv.Exc)
            {
                int t0 = x.Start * Hz, t1 = t0 + x.Out * Hz, t2 = t1 + x.Serve * Hz, t3 = t2 + x.Back * Hz;
                if (tr < t0 || tr >= t3) continue;
                if (tr < t1) return (x.Path, RoundHalf(x.Path.Length * (tr - t0), t1 - t0), tr - t0);
                if (tr < t2) return (x.Path, x.Path.Length, t3 - t2);
                return (x.Path, RoundHalf(x.Path.Length * (t3 - tr), t3 - t2), t3 - tr);
            }
            return null;
        }
        static int Resume(RoundsData.Server sv, int tr)
        {
            foreach (var x in sv.Exc) { int t0 = x.Start * Hz, t3 = t0 + (x.Out + x.Serve + x.Back) * Hz; if (tr >= t0 && tr < t3) return t3; }
            return tr;
        }

        List<Piece> Pieces(RoundsData.Server sv, RoundEvents ev)
        {
            if (roundCache.TryGetValue(sv.Id, out var c) && c.version == ev.Version) return c.pieces;
            const int MAX = int.MaxValue;
            int ling = T(S.Rounds!.LingerS), part = T(S.Rounds.PartS), origin = T(sv.Origin);
            var pieces = new List<Piece>(); int cur = origin, clock = 0;
            void run(int to, int c0, int from) => pieces.Add(new Piece { From = from, To = to, Kind = "run", C0 = c0 });
            Piece walkTo(int from, int tr)
            {
                var w = WalkBack(sv, tr);
                if (w == null) return new Piece { From = from, To = from, Kind = "fixed", Pos = sv.At, Face = sv.Face, Phase = "to post" };
                return new Piece { From = from, To = from + w.Value.dur, Kind = "walk", WPath = w.Value.path, StartMm = w.Value.startMm, Dur = w.Value.dur };
            }
            // an order taken before the last one's linger is over is the same hold, longer
            var holds = new List<(int from, int to, Pt face)>();
            var sorted = StableByFrom(ev.Holds); // by the tick taken, ties in the order taken
            foreach (var h in sorted)
            {
                if (holds.Count > 0 && h.From <= holds[holds.Count - 1].to + ling) { var l = holds[holds.Count - 1]; holds[holds.Count - 1] = (l.from, Math.Max(l.to, h.To), h.Face); }
                else holds.Add((h.From, h.To, h.Face));
            }
            var events = new List<(string kind, int at, int ix)>();
            for (int i = 0; i < holds.Count; i++) events.Add(("hold", holds[i].from, i));
            if (ev.CallAt >= 0) events.Add(("call", ev.CallAt, -1));
            if (ev.EndAt >= 0) events.Add(("end", ev.EndAt, -1));
            events = StableByAt(events);
            foreach (var e in events)
            {
                if (e.at < cur)
                {
                    if (e.kind == "hold") continue;
                    if (pieces.Count > 0 && pieces[pieces.Count - 1].To > e.at) pieces[pieces.Count - 1].To = e.at;
                    cur = e.at;
                }
                if (e.at > cur) { run(e.at, clock, cur); clock += e.at - cur; cur = e.at; }
                if (e.kind == "hold")
                {
                    var h = holds[e.ix]; var was = BodyPose(sv, clock); int to = h.to + ling;
                    pieces.Add(new Piece { From = cur, To = to, Kind = "fixed", Pos = was.Pos, Face = h.face, Phase = "held" });
                    cur = to;
                }
                else if (e.kind == "call")
                {
                    var w = walkTo(cur, clock); int arrive = w.To; pieces.Add(w);
                    int wait = Math.Max(arrive, ev.CallArrive);
                    pieces.Add(new Piece { From = arrive, To = wait, Kind = "fixed", Pos = sv.At, Face = sv.Face, Phase = "at post" });
                    var gf = ev.CallStop - sv.At;
                    int end = Math.Max(wait, ev.CallUntil) + part;
                    pieces.Add(new Piece { From = wait, To = end, Kind = "fixed", Pos = sv.At, Face = gf, Phase = "together" });
                    cur = end; clock = Resume(sv, clock);
                }
                else
                {
                    var w = walkTo(cur, clock); pieces.Add(w);
                    pieces.Add(new Piece { From = w.To, To = MAX, Kind = "fixed", Pos = sv.At, Face = sv.Face, Phase = "at post" });
                    cur = MAX; break;
                }
            }
            if (cur < MAX) run(MAX, clock, cur);
            roundCache[sv.Id] = (ev.Version, pieces);
            return pieces;
        }
        static List<RoundEvents.Hold> StableByFrom(List<RoundEvents.Hold> l) { var o = new List<RoundEvents.Hold>(l); var ix = new Dictionary<RoundEvents.Hold, int>(); for (int i = 0; i < o.Count; i++) ix[o[i]] = i; o.Sort((a, b) => a.From != b.From ? a.From.CompareTo(b.From) : ix[a].CompareTo(ix[b])); return o; }
        static List<(string kind, int at, int ix)> StableByAt(List<(string kind, int at, int ix)> l) { var o = new List<(string kind, int at, int ix, int n)>(); for (int i = 0; i < l.Count; i++) o.Add((l[i].kind, l[i].at, l[i].ix, i)); o.Sort((a, b) => a.at != b.at ? a.at.CompareTo(b.at) : a.n.CompareTo(b.n)); return o.ConvertAll(x => (x.kind, x.at, x.ix)); }

        /// <summary>A server's pose at a mission tick, given what the mission did to her (rounds.ts poseAt).</summary>
        RoundPose RoundPoseAt(RoundsData.Server sv, RoundEvents ev, int tick)
        {
            if (tick < T(sv.Origin)) return new RoundPose { Pos = sv.At, Face = sv.Face, Phase = "at post" };
            var pieces = Pieces(sv, ev);
            Piece? p = null; foreach (var x in pieces) if (tick >= x.From && tick < x.To) { p = x; break; }
            p ??= pieces[pieces.Count - 1];
            switch (p.Kind)
            {
                case "run": return BodyPose(sv, p.C0 + (tick - p.From));
                case "walk":
                    {
                        int k = Math.Min(p.Dur, tick - p.From); long mm = p.Dur == 0 ? 0 : RoundHalf(p.StartMm * (p.Dur - k), p.Dur); var h = p.WPath!.Heading(mm);
                        return new RoundPose { Pos = p.WPath.At(mm), Face = new Pt(-h.X, -h.Y), Phase = "to post" };
                    }
                default: return new RoundPose { Pos = p.Pos, Face = p.Face, Phase = p.Phase };
            }
        }

        /// <summary>The reference function for tests (brief 022 vectors): a server's pose at a tick under the given events, without touching the run.</summary>
        public RoundPose RoundReference(string serverId, int tick, (int from, int to, Pt face)[] holds, (int at, int arrive, int until, Pt stop)? call, int endAt)
        {
            var sv = S.Rounds!.Servers[serverId]; var ev = new RoundEvents();
            foreach (var h in holds) ev.Holds.Add(new RoundEvents.Hold { From = h.from, To = h.to, Face = h.face });
            if (call.HasValue) { ev.CallAt = call.Value.at; ev.CallArrive = call.Value.arrive; ev.CallUntil = call.Value.until; ev.CallStop = call.Value.stop; }
            ev.EndAt = endAt; ev.Version = -1;
            var saved = roundCache.TryGetValue(serverId, out var c) ? c : ((int, List<Piece>)?)null;
            roundCache.Remove(serverId);
            var q = RoundPoseAt(sv, ev, tick);
            if (saved.HasValue) roundCache[serverId] = saved.Value; else roundCache.Remove(serverId);
            return q;
        }

        /// <summary>The round's state for the checkpoint hash: no bytes unless the round is played.</summary>
        internal void HashRounds(Hash.H h)
        {
            if (!RoundsOn) return;
            var ids = new List<string>(roundEv.Keys); ids.Sort(StringComparer.Ordinal);
            foreach (var id in ids)
            {
                var ev = roundEv[id]; h.S(id).I(ev.Holds.Count);
                foreach (var x in ev.Holds) h.I(x.From).I(x.To).P(x.Face);
                h.I(ev.CallAt).I(ev.CallArrive).I(ev.CallUntil).P(ev.CallStop).I(ev.EndAt).S(ev.EndWhy);
            }
            foreach (var sv in S.Rounds!.Servers.Values) { var p = PersonById(sv.Id); if (p != null && !p.Down) { var q = RoundPoseAt(sv, EvRead(sv), Tick); h.P(q.Pos).S(q.Phase); } }
        }
    }
}

sim/Suborned.Sim/GameScatter.cs.text:
// The crowd in a fight (Pulse, briefs/011/pulse-fight-ai.md §4; rulebook `crowd`): the city's people scatter from shots and drawn weapons
// to the refuges of the site's cover data, shelter, and walk back when it is quiet; and a person on the street blocks a watcher's
// sightline. The four people cast by role keep their places. Integers only; people act in the walker order (by id, as loaded).
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed partial class Game
    {
        readonly List<Pt> shotsThisTick = new List<Pt>();
        public int LastShotTick = -1; Pt lastShooter;
        readonly List<Pt> occluders = new List<Pt>(); int occludersTick = -1;

        Pt? ScatterPos(Walker w)
        {
            switch (w.St)
            {
                case "startled": return w.At;
                case "fleeing": return w.Run == null ? w.At : w.Run.At((long)(Tick - w.RunStart) * R.CrowdRunSpeed);
                case "returning": return w.Run == null ? w.At : w.Run.At((long)(Tick - w.RunStart) * opSpeed);
                // brief 013: a witness on the way to a phone or to look at a body, a victim staggering; at the phone they are off the street
                case "reporting": case "checking": return w.Run == null || Tick < w.RunStart ? w.At : w.Run.At((long)(Tick - w.RunStart) * w.Pace);
                case "woken": return w.Run == null || Tick < w.RunStart ? w.At : w.Run.At((long)(Tick - w.RunStart) * w.Pace);
                case "calling": return S.CallBoxes.Exists(c => c.id == w.Refuge) ? w.At : (Pt?)null; // at a call box on the street (stoppable, Pulse §3.2); a staffed door's phone is inside
                default: return null; // sheltered: off the street
            }
        }

        /// <summary>One tick of the crowd (Pulse §4): startle on a shot within crowd.scatter or a drawn weapon in sight within witness range;
        /// flee to a refuge; shelter; walk back crowd.quiet after the last shot.</summary>
        void CrowdStep()
        {
            occludersTick = -1;
            if (People2 == null || !Start.Crowd) { shotsThisTick.Clear(); return; }
            var drawn = new List<Pt>();
            foreach (var op in Ops) if (op.Gun.Drawn && !op.Down && !op.Inside) drawn.Add(op.Pos);
            long scatter2 = (long)R.CrowdScatterCm * R.CrowdScatterCm;
            int startled = 0, sheltered = 0, back = 0;
            foreach (var w in Walkers)
            {
                if (w.P.Down) continue;
                switch (w.St)
                {
                    case "": case "returning":
                        {
                            var pos = CrowdPos(w); if (!pos.HasValue) break;
                            Pt? from = null;
                            foreach (var s in shotsThisTick) if (G.D2(s, pos.Value) <= scatter2) { from = s; break; }
                            if (!from.HasValue) foreach (var d in drawn) if (G.Within(d, pos.Value, witnessRange) && Sees(d, pos.Value)) { from = d; break; }
                            if (!from.HasValue) break;
                            w.St = "startled"; w.At = pos.Value; w.Run = null; w.RunStart = Tick; lastShooterFor[w.P.Id] = from.Value;
                            w.Until = Tick + (w.P.Temperament == "fearful" ? R.CrowdStartleFearfulTicks : R.CrowdStartleTicks); startled++;
                            break;
                        }
                    case "startled":
                        if (Tick < w.Until) break;
                        {
                            var shooter = LastShotTick >= w.RunStart ? lastShooter : lastShooterFor[w.P.Id]; // the most recent shot's shooter, else what startled them
                            var (id, at) = RefugeFor(w.At, shooter);
                            w.Refuge = id; w.Run = RouteOf(w.At, at); w.RunStart = Tick; w.St = "fleeing";
                        }
                        break;
                    case "fleeing":
                        if (w.Run == null || (long)(Tick - w.RunStart) * R.CrowdRunSpeed >= w.Run.Length) { w.St = "sheltered"; w.Until = Tick; sheltered++; }
                        break;
                    case "sheltered":
                        if (Tick - Math.Max(LastShotTick, w.Until) < T(R.CrowdQuietS)) break;
                        {
                            var home = RoutinePos(w, Tick);
                            if (!home.HasValue) { w.St = ""; break; }
                            var start = w.Run?.End ?? w.At;
                            w.Run = RouteOf(start, home.Value); w.RunStart = Tick; w.At = start; w.St = "returning";
                        }
                        break;
                }
                if (w.St == "returning" && (w.Run == null || (long)(Tick - w.RunStart) * opSpeed >= w.Run.Length)) { w.St = ""; w.Run = null; back++; }
            }
            shotsThisTick.Clear();
            if (startled > 0) Note("crowd.startled", $"{startled} on the street are startled and run.");
            if (sheltered > 0) Note("crowd.sheltered", $"{sheltered} reach shelter.");
            if (back > 0) Note("crowd.back", $"{back} are back on their way.");
        }
        readonly Dictionary<string, Pt> lastShooterFor = new Dictionary<string, Pt>(StringComparer.Ordinal);

        Path RouteOf(Pt a, Pt b)
        {
            var fa = S.Grid.NearestFree(a) ?? a; var fb = S.Grid.NearestFree(b) ?? b;
            var route = S.Grid.Route(fa, fb);
            return new Path(route != null && route.Length >= 2 ? route : new[] { a, b });
        }

        /// <summary>Pulse §4 refuge: within crowd.fleeMax, ending farther from the shooter than the person stands, the nearest (ties on id);
        /// if none, the refuge farthest from the shooter.</summary>
        (string id, Pt at) RefugeFor(Pt me, Pt shooter)
        {
            long mine = G.D2(me, shooter), max2 = (long)R.CrowdFleeMaxCm * R.CrowdFleeMaxCm;
            (string id, Pt at) best = ("", me); long bd = long.MaxValue;
            foreach (var (id, at, _) in S.Refuges)
            {
                long d = G.D2(me, at);
                if (d > max2 || G.D2(at, shooter) <= mine) continue;
                if (d < bd || (d == bd && string.CompareOrdinal(id, best.id) < 0)) { bd = d; best = (id, at); }
            }
            if (best.id.Length > 0) return best;
            long far = -1;
            foreach (var (id, at, _) in S.Refuges) { long d = G.D2(at, shooter); if (d > far || (d == far && string.CompareOrdinal(id, best.id) < 0)) { far = d; best = (id, at); } }
            return best;
        }

        /// <summary>Pulse §4: a person on the street, not sheltered, blocks a watcher's sightline that passes within crowd.occlude of them,
        /// between two bodies' width (2 × occlude) of either end.</summary>
        public bool CrowdBlocks(Pt a, Pt b)
        {
            if (People2 == null || !Start.Crowd) return false;
            if (occludersTick != Tick)
            {
                occluders.Clear(); occludersTick = Tick;
                foreach (var w in Walkers) { var p = CrowdPos(w); if (p.HasValue) occluders.Add(p.Value); }
            }
            long dx = b.X - a.X, dy = b.Y - a.Y, l2 = dx * dx + dy * dy; if (l2 == 0) return false;
            long occ = R.CrowdOccludeCm, end2 = 4 * occ * occ;
            foreach (var p in occluders)
            {
                long px = p.X - a.X, py = p.Y - a.Y, dot = px * dx + py * dy;
                if (dot <= 0 || dot >= l2) continue;
                if (G.D2(p, a) <= end2 || G.D2(p, b) <= end2) continue;
                long cross = px * dy - py * dx;
                if (cross * cross <= occ * occ * l2) return true;
            }
            return false;
        }
    }
}

sim/Suborned.Sim/GameSight.cs.text:
// What the cell knows of the city's watchers, and the reads the HUD draws from it (Sky 2026-10-16: view cones are the Scout's skill;
// Glyph's review, briefs/011/ui/review-2026-10-16 §3.4; the rulebook's `sight` section).
//  · ConeFan(watcher): the watcher's sight now as a flat polygon on the ground, the engine's own test (rulebook perception: its cone or
//    sweep, the near circle, occluders at eye height; people on the street if asked). Integer only, read-only, cached by pose.
//  · Known(watcher): what the cell has learned of it, witnessed (a Scout Watch) or told (the start state), or known on arrival.
//    Learned knowledge is the cell's, not the Scout's: it stays when the Scout goes down.
//  · Routine(watcher, horizon): the watcher's schedule ahead (the patrol's turns and its door windows), once its routine is known.
//  · Detection(): every watcher that sees an operative now (the fill), known or not.
//  · Seen(...): the quote's "seen by": known watchers' true answer, "?" for an unknown watcher that could see (rulebook sight.unknown).
// None of these changes the game; only Watch (an order) and the arrival of the response unit or the rivals add knowledge.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>A watcher's sight as a polygon on the ground (cm, the block frame), for the HUD to fill.</summary>
    public sealed class Fan
    {
        public string Watcher = "";     // camera:<id>, guard, patrol, security-<n>, rivals
        public string Kind = "";        // camera, guard, patrol, security, rivals (Glyph's grammar: one shape cue each)
        public Pt At, Facing;           // where the watcher stands and the way it faces (cm; the facing is a direction, any length)
        public int Level;               // the ground the fan lies on, cm (0: the street; every Handover watcher stands on it)
        public bool Live;               // false: it sees nothing now (a looped or blocked camera, a rerouted patrol, the guard on the cell's side); the shape is its sight as it stands
        public int Reach;               // the farthest point from At, cm
        /// <summary>The polygon, counter-clockwise in the block frame (x right, y up), starting behind the watcher. When the watcher's own
        /// point is a corner (a camera's apex, the patrol's base) it is Points[0]. Empty when nothing is in sight.</summary>
        public Pt[] Points = Array.Empty<Pt>();
        /// <summary>What ends the sight at each point: apex, reach (the cone's or sweep's edge: the dashed far edge), near (the circle
        /// anyone within perception.near is seen in), blocked (a wall, roof or solid at eye height), crowd (a person on the street).</summary>
        public string[] Stop = Array.Empty<string>();
        /// <summary>A camera with several heads (the Records Square mast): the other heads' polygons and stops, as Points and Stop.</summary>
        public Pt[][] More = Array.Empty<Pt[]>(); public string[][] MoreStop = Array.Empty<string[]>();
    }

    /// <summary>What the cell knows of one watcher (rulebook sight).</summary>
    public sealed class WatcherKnown
    {
        public string Watcher = "", Kind = "";
        public bool Sight, Routine;     // its sight (the cone the HUD may draw), its routine (Routine() answers)
        public string How = "";         // watched, told, arrival; "" while unknown
        public int SightAt = -1, RoutineAt = -1; // the tick each was learned (-1: not, or known from the start)
        public int WatchedS;            // seconds of completed Scout Watch on it
        public int RoutineNeedsS;       // watched seconds its routine needs (sight.watch.routine), 0 when the routine comes with the sight or a person's Watch
    }

    /// <summary>A fact the cell learned of a watcher, in the order learned: the record (hashed when there is one).</summary>
    public sealed class SightFact { public string Watcher = "", What = "", How = ""; public int Tick; }

    /// <summary>One step of a watcher's schedule: turn-at-a, turn-at-b, sees-door, door-clear, back-on-sweep, off-routine, at-cafe, leaves-cafe, back-at-door.</summary>
    public sealed class RoutineEvent { public int Tick; public string What = ""; }

    /// <summary>A watcher noticing an operative now (the detection fill): drawn from the watcher toward the operative.</summary>
    public sealed class Noticing
    {
        public string Watcher = "", Op = "";
        public int PerMille;            // 0..1000; today 1000: the rules notice at once (rulebook perception; a gradual notice is Motive's to set)
        public bool Known;              // the cell knows this watcher's sight; false: the HUD shows "?" over the watcher
        public Pt From, To;             // the watcher, the operative
    }

    /// <summary>A quote's "seen by" (rulebook sight.unknown): the answer the card shows, never more than the cell knows.</summary>
    public sealed class SeenQuote
    {
        public string Seen = "no";                              // yes: a known watcher sees it; ?: none known does, an unknown one could; no
        public readonly List<string> SeenBy = new List<string>();      // known watchers that see it now (the true answer)
        public readonly List<string> MaybeSeenBy = new List<string>(); // unknown watchers that could (in their farthest sight, on a clear line): "?"
        public int AlertIfSeen;                                 // Alert if a run is seen (cell.runAlert), for "yes" and "?" alike
    }

    public sealed partial class Game
    {
        public readonly List<SightFact> SightFacts = new List<SightFact>();
        readonly SortedDictionary<string, int> watchedS = new SortedDictionary<string, int>(StringComparer.Ordinal);

        /// <summary>The kind of a watcher id: camera, guard, patrol, security, rivals; "" for anything else.</summary>
        public static string WatcherKind(string id) =>
            id.StartsWith("camera:", StringComparison.Ordinal) ? "camera" : id == "guard" ? "guard" : id == "patrol" ? "patrol"
            : id.StartsWith("security-", StringComparison.Ordinal) || id.StartsWith("police-", StringComparison.Ordinal) || id.StartsWith("robot-", StringComparison.Ordinal) ? "security" // brief 013: the response's units come for the cell like the response unit
            : id == "rivals" ? "rivals" : "";

        /// <summary>Every watcher of this mission, in a fixed order: the cameras, the guard, the patrol, the response officers, the rivals.</summary>
        public List<string> WatcherIds()
        {
            var l = new List<string>();
            foreach (var c in S.Cameras) l.Add("camera:" + c.Id);
            l.Add("guard"); l.Add("patrol");
            foreach (var g in SecGuns) l.Add(g.Id);
            l.Add("rivals");
            foreach (var u in Units) if (!u.Legacy && !u.Patrol) l.Add(u.Id); // brief 013: robots and police the dial sent, by id (none in a run without an alarm)
            return l;
        }
        bool IsWatcher(string id)
        {
            switch (WatcherKind(id))
            {
                case "camera": { var cid = id.Substring(7); foreach (var c in S.Cameras) if (c.Id == cid) return true; return false; }
                case "security": return SecIndex(id) >= 0 || UnitOf(id) != null;
                case "": return false;
                default: return true;
            }
        }
        static bool IsPersonRoleName(string id) => id == "waitress" || id == "driver" || id == "guard" || id == "councillor";

        // ---------------------------------------------------------------- the shape a watcher sees with now

        /// <summary>A watcher's perception now: a cone (ahead within reach, side within half × ahead ÷ reach, and anyone within near) or the
        /// patrol's sweep (depth, and side within halfBase + depth × perMille); Live = it is watching (rulebook perception; Game.cs).</summary>
        struct Shape
        {
            public bool Sweep, Live; public Pt At, F; public int Reach, Half, Near, Depth, HalfBase, PerMille;
            public Pt[]? Heads; // a camera with several heads (the mast): its cone along each; F is the first
            public string Key() => $"{(Sweep ? 1 : 0)}|{(Live ? 1 : 0)}|{At.X},{At.Y}|{F.X},{F.Y}|{Reach}|{Half}|{Near}|{Depth}|{HalfBase}|{PerMille}|{Heads?.Length ?? 1}";
        }

        Shape? ShapeOf(string w)
        {
            switch (WatcherKind(w))
            {
                case "camera":
                    {
                        var id = w.Substring(7);
                        foreach (var c in S.Cameras)
                            if (c.Id == id)
                                return new Shape { At = c.At, F = c.Facing, Heads = c.Facings.Length > 1 ? c.Facings : null, Reach = c.Reach, Half = c.Half, Near = 0, Live = !(id == LoopCam && LoopOn) && !(id == "pickup" && !PickupCameraLive()) };
                        return null;
                    }
                case "guard":
                    {
                        var gp = GuardPose(); if (!gp.HasValue) return null;
                        var (pos, f, phase) = gp.Value; bool door = phase == "door";
                        return new Shape { At = pos, F = f, Reach = door ? R.DoorReachCm : R.FacingReachCm, Half = door ? R.DoorHalfCm : R.FacingHalfCm, Near = door ? 0 : near, Live = !GuardAlly };
                    }
                case "patrol":
                    {
                        if (PatrolDown) return null;
                        var (pos, f) = PatrolPose()!.Value;
                        if (PatrolChasing && PatrolAwayUntil <= Tick) return new Shape { At = pos, F = f, Reach = R.FacingReachCm, Half = R.FacingHalfCm, Near = near, Live = true };
                        return new Shape { Sweep = true, At = pos, F = f, Depth = R.PatrolDepthCm, HalfBase = R.PatrolHalfBase, PerMille = R.PatrolHalfPerMille, Live = PatrolAwayUntil <= Tick };
                    }
                case "security":
                    {
                        if (UnitOf(w) is Unit u) { var up = UnitPose(u); if (!up.HasValue) return null; return new Shape { At = up.Value.pos, F = up.Value.facing, Reach = R.SecReachCm, Half = R.SecHalfCm, Near = near, Live = true }; }
                        int k = SecIndex(w); if (k < 0) return null;
                        var s = SecOfficerPose(k); if (!s.HasValue) return null;
                        return new Shape { At = s.Value.pos, F = s.Value.facing, Reach = R.SecReachCm, Half = R.SecHalfCm, Near = near, Live = true };
                    }
                case "rivals":
                    {
                        if (!RivalsDrawn) return null; // before gunfire the rival crew watches the building, not the street (RivalsWatching)
                        var r = RivalsPose(); if (!r.HasValue) return null;
                        return new Shape { At = r.Value.pos, F = r.Value.facing, Reach = R.RivReachCm, Half = R.RivHalfCm, Near = near, Live = true };
                    }
            }
            return null;
        }

        /// <summary>The shape test alone, as the engine's (G.InCone; InSweepCone).</summary>
        bool InShape(Shape s, Pt p)
        {
            if (s.Sweep) return InSweepCone(s.At, s.F, p);
            if (s.Heads != null) { foreach (var f in s.Heads) if (G.InCone(s.At, f, s.Reach, s.Half, s.Near, p)) return true; return false; }
            return G.InCone(s.At, s.F, s.Reach, s.Half, s.Near, p);
        }

        /// <summary>Would this watcher see p from where it stands, ignoring whether it is watching now (a looped camera's sight as it
        /// stands)? The engine's test: its shape, a clear line at eye height, and (crowd) nobody on the street across the line. Rivals'
        /// own sight ignores people, as RivalsWatching does.</summary>
        public bool InSight(string watcher, Pt p, bool crowd = true)
        {
            var s = ShapeOf(watcher); if (!s.HasValue) return false;
            if (!InShape(s.Value, p) || !Sees(s.Value.At, p)) return false;
            return !(crowd && watcher != "rivals" && CrowdBlocks(s.Value.At, p));
        }
        /// <summary>The watcher sees p now (Live and InSight): the same answer as CameraWatching, GuardWatching (unless the guard is the
        /// cell's ally), PatrolWatching, the officers' and RivalsWatching. The detection fill and the "seen by" truth read this.</summary>
        public bool SeesNow(string watcher, Pt p, bool crowd = true)
        {
            var s = ShapeOf(watcher); if (!s.HasValue || !s.Value.Live) return false;
            return InSight(watcher, p, crowd);
        }

        // ---------------------------------------------------------------- the fan

        readonly Dictionary<string, (string key, Fan fan)> fanCache = new Dictionary<string, (string, Fan)>(StringComparer.Ordinal);

        /// <summary>The watcher's sight now as a polygon on the ground (rulebook perception, the engine's own test), or null when the watcher
        /// is not on the street (down, not yet come, an unknown id). crowd: also cut by people on the street (Pulse §4; they move, so the
        /// shape changes every tick); without it the fan is the walls' and solids' alone, and stays put while the watcher does.
        /// Read-only and deterministic (integers only). Cost: rays from the watcher to every occluder corner in reach (three each), where an
        /// occluder edge crosses the shape's edge or another occluder's, the shape's corners and 64 around the near circle, each tested against the occluders'
        /// edges: about 300 rays × 100 edges on the civic block, ~0.1 ms; cached per watcher until its pose or state changes, so a still
        /// watcher (a camera, the guard at his door) costs a dictionary lookup per call. With crowd, the cache holds for the tick only.</summary>
        public Fan? ConeFan(string watcher, bool crowd = false)
        {
            var sh = ShapeOf(watcher); if (!sh.HasValue) return null;
            var s = sh.Value;
            bool useCrowd = crowd && watcher != "rivals" && People2 != null && Start.Crowd;
            string key = s.Key() + (useCrowd ? "|crowd@" + Tick.ToString(System.Globalization.CultureInfo.InvariantCulture) : "");
            string ck = watcher + (useCrowd ? "/crowd" : "");
            if (fanCache.TryGetValue(ck, out var hit) && hit.key == key) return hit.fan;
            var fan = BuildFan(watcher, s, useCrowd);
            if (s.Heads != null) // a mast: one polygon a head; the first is the fan's own, the rest its More (brief 013)
            {
                var more = new List<Pt[]>(); var moreStop = new List<string[]>();
                for (int h = 1; h < s.Heads.Length; h++) { var sh2 = s; sh2.F = s.Heads[h]; sh2.Heads = null; var f2 = BuildFan(watcher, sh2, useCrowd); more.Add(f2.Points); moreStop.Add(f2.Stop); fan.Reach = Math.Max(fan.Reach, f2.Reach); }
                fan.More = more.ToArray(); fan.MoreStop = moreStop.ToArray();
            }
            fanCache[ck] = (key, fan);
            return fan;
        }

        /// <summary>Every watcher on the street whose sight the cell knows (the Alt view), in WatcherIds order.</summary>
        public List<Fan> KnownFans(bool crowd = false)
        {
            var l = new List<Fan>();
            foreach (var w in WatcherIds()) { var k = Known(w); if (k == null || !k.Sight) continue; var f = ConeFan(w, crowd); if (f != null) l.Add(f); }
            return l;
        }

        static readonly int[] Circle64 =
        {
            10000, 0, 9952, 980, 9808, 1951, 9569, 2903, 9239, 3827, 8819, 4714, 8315, 5556, 7730, 6344, 7071, 7071, 6344, 7730, 5556, 8315, 4714, 8819,
            3827, 9239, 2903, 9569, 1951, 9808, 980, 9952, 0, 10000, -980, 9952, -1951, 9808, -2903, 9569, -3827, 9239, -4714, 8819, -5556, 8315,
            -6344, 7730, -7071, 7071, -7730, 6344, -8315, 5556, -8819, 4714, -9239, 3827, -9569, 2903, -9808, 1951, -9952, 980, -10000, 0, -9952,
            -980, -9808, -1951, -9569, -2903, -9239, -3827, -8819, -4714, -8315, -5556, -7730, -6344, -7071, -7071, -6344, -7730, -5556, -8315,
            -4714, -8819, -3827, -9239, -2903, -9569, -1951, -9808, -980, -9952, 0, -10000, 980, -9952, 1951, -9808, 2903, -9569, 3827, -9239,
            4714, -8819, 5556, -8315, 6344, -7730, 7071, -7071, 7730, -6344, 8315, -5556, 8819, -4714, 9239, -3827, 9569, -2903, 9808, -1951, 9952, -980,
        };
        const long RayLen = 65536; // every ray direction is scaled to about this length, so the products below stay far inside a long

        Fan BuildFan(string watcher, Shape s, bool crowd)
        {
            var fan = new Fan { Watcher = watcher, Kind = WatcherKind(watcher), At = s.At, Facing = s.F, Level = 0, Live = s.Live };
            var o = s.At;
            // a watcher standing in a solid sees nothing (Occluder.Blocks: a sightline that starts inside it is blocked)
            foreach (var oc in S.Occluders) if (eye >= oc.Z && eye <= oc.Z + oc.H && G.InPoly(o, oc.Poly)) return fan;

            // the shape as a convex polygon about o (the cone's triangle, the sweep's trapezoid), and its near circle
            var poly = new List<Pt>(); bool apex;
            long fl0 = G.Isqrt((long)s.F.X * s.F.X + (long)s.F.Y * s.F.Y);
            if (s.Sweep)
            {
                apex = true; // o is on the base: a corner of the fan
                if (fl0 > 0)
                {
                    long fx = s.F.X, fy = s.F.Y, hb = s.HalfBase, hf = s.HalfBase + (long)s.Depth * s.PerMille / 1000, d = s.Depth;
                    Pt P(long a, long side) => new Pt(o.X + (int)((fx * a - fy * side) / fl0), o.Y + (int)((fy * a + fx * side) / fl0));
                    poly.Add(P(0, -hb)); poly.Add(P(d, -hf)); poly.Add(P(d, hf)); poly.Add(P(0, hb));
                }
            }
            else
            {
                apex = s.Near == 0;
                if (fl0 > 0)
                {
                    long fx = (long)s.F.X * 1024 / fl0, fy = (long)s.F.Y * 1024 / fl0; long fl = G.Isqrt(fx * fx + fy * fy); // as G.InCone scales it
                    if (fl > 0)
                    {
                        Pt P(long a, long side) => new Pt(o.X + (int)((fx * a - fy * side) / fl), o.Y + (int)((fy * a + fx * side) / fl));
                        poly.Add(o); poly.Add(P(s.Reach, -s.Half)); poly.Add(P(s.Reach, s.Half));
                    }
                }
            }
            long maxR = s.Near; foreach (var p in poly) maxR = Math.Max(maxR, G.Isqrt(G.D2(o, p)));
            if (maxR == 0) return fan;

            // the occluders that matter: at eye height, within maxR of o
            int bx0 = (int)(o.X - maxR), bx1 = (int)(o.X + maxR), by0 = (int)(o.Y - maxR), by1 = (int)(o.Y + maxR);
            var occ = new List<Occluder>();
            foreach (var oc in S.Occluders) if (eye >= oc.Z && eye <= oc.Z + oc.H && oc.BoxMeets(bx0, by0, bx1, by1)) occ.Add(oc);
            var walkers = new List<Pt>();
            long occR = R.CrowdOccludeCm;
            if (crowd) foreach (var w in Walkers) { var wp = CrowdPos(w); if (wp.HasValue && G.Within(o, wp.Value, (int)(maxR + 2 * occR))) walkers.Add(wp.Value); }

            // the rays: toward the shape's corners, its near circle, every occluder corner in reach and where an occluder edge crosses the
            // shape's edge (each also a hair either side, so a shadow's edge is caught on both sides), and every person's edges
            var dirs = new List<Pt>(); var seen = new HashSet<long>();
            void Ray(long vx, long vy)
            {
                if (vx == 0 && vy == 0) return;
                long len = G.Isqrt(vx * vx + vy * vy); if (len == 0) return;
                int dx = (int)(vx * RayLen / len), dy = (int)(vy * RayLen / len);
                if (seen.Add(unchecked(((long)dx << 32) ^ (uint)dy))) dirs.Add(new Pt(dx, dy));
            }
            void Ray3(Pt to)
            {
                long vx = to.X - o.X, vy = to.Y - o.Y; if (vx == 0 && vy == 0) return;
                long len = G.Isqrt(vx * vx + vy * vy); long dx = vx * RayLen / len, dy = vy * RayLen / len;
                Ray(dx, dy); Ray(dx - dy / 512, dy + dx / 512); Ray(dx + dy / 512, dy - dx / 512);
            }
            foreach (var p in poly) Ray3(p);
            if (s.Near > 0) for (int k = 0; k < 64; k++) Ray(Circle64[2 * k], Circle64[2 * k + 1]);
            long maxR2 = maxR * maxR;
            foreach (var oc in occ)
            {
                var pg = oc.Poly;
                for (int i = 0, j = pg.Length - 1; i < pg.Length; j = i++)
                {
                    if (G.D2(o, pg[i]) <= maxR2) Ray3(pg[i]);
                    for (int a = 0, b = poly.Count - 1; a < poly.Count; b = a++)
                        if (SegPoint(poly[b], poly[a], pg[j], pg[i]) is Pt x) Ray3(x);
                }
            }
            // where two solids' edges cross (a low wall into a building's face): a corner of the shadow that is no corner of either
            for (int a = 0; a < occ.Count; a++)
                for (int b = a + 1; b < occ.Count; b++)
                {
                    var pa = occ[a].Poly; var pb = occ[b].Poly;
                    for (int i = 0, j = pa.Length - 1; i < pa.Length; j = i++)
                        for (int m = 0, n = pb.Length - 1; m < pb.Length; n = m++)
                            if (SegPoint(pa[j], pa[i], pb[n], pb[m]) is Pt x && G.D2(o, x) <= maxR2) Ray3(x);
                }
            // a person's shadow edges are the two tangents from o to the circle of crowd.occlude round them, at asin(occ / d) either side of the
            // line to them, built as directions (never as rounded points beside them): a point a centimetre off at a person 3 m away swings the
            // ray by more than its hair, and both hairs then fell in the shadow, dropping the clear wedge beside it (Keel 2026-10-19: the
            // Records Square mast's crowd fan at 0:30, a person 3 m off its cone's edge)
            void RayDir3(long dx, long dy) { while (Math.Abs(dx) > 1L << 30 || Math.Abs(dy) > 1L << 30) { dx /= 2; dy /= 2; } long len = G.Isqrt(dx * dx + dy * dy); if (len == 0) return; dx = dx * RayLen / len; dy = dy * RayLen / len; Ray(dx, dy); Ray(dx - dy / 512, dy + dx / 512); Ray(dx + dy / 512, dy - dx / 512); }
            foreach (var w in walkers)
            {
                long vx = w.X - o.X, vy = w.Y - o.Y, d2 = vx * vx + vy * vy, len = G.Isqrt(d2); if (len == 0) continue;
                Ray3(w);
                if (len <= occR) continue; // o inside the body: no tangent
                long c = G.Isqrt(d2 - occR * occR); // d·cos θ, with sin θ = occ / d
                RayDir3(vx * c - vy * occR, vy * c + vx * occR); RayDir3(vx * c + vy * occR, vy * c - vx * occR);
            }

            // each ray's end: the farther of the shape's exit and the near circle, cut at the first occluder (or person) across it
            var ends = new List<(Pt dir, Pt end, string stop, int idx)>();
            for (int n = 0; n < dirs.Count; n++)
            {
                var d = dirs[n];
                Pt end = o; string stop = "apex";
                if (poly.Count >= 3) { var x = PolyExit(o, d, poly); if (x.HasValue) { end = x.Value; stop = "reach"; } }
                if (s.Near > 0)
                {
                    long len = G.Isqrt((long)d.X * d.X + (long)d.Y * d.Y);
                    var c = new Pt(o.X + (int)((long)d.X * s.Near / len), o.Y + (int)((long)d.Y * s.Near / len));
                    if (G.D2(o, c) > G.D2(o, end)) { end = c; stop = "near"; }
                }
                if (end == o) continue;
                long best = G.D2(o, end);
                foreach (var oc in occ)
                {
                    if (!oc.BoxMeets(Math.Min(o.X, end.X), Math.Min(o.Y, end.Y), Math.Max(o.X, end.X), Math.Max(o.Y, end.Y))) continue;
                    var pg = oc.Poly;
                    for (int i = 0, j = pg.Length - 1; i < pg.Length; j = i++)
                        if (SegPoint(o, end, pg[j], pg[i]) is Pt x) { long dd = G.D2(o, x); if (dd < best) { best = dd; end = x; stop = "blocked"; } }
                }
                if (walkers.Count > 0) { var cut = CrowdCut(o, end, walkers, occR); if (cut.HasValue) { end = cut.Value; stop = "crowd"; } }
                if (end == o) continue;
                ends.Add((d, end, stop, n));
            }

            // in angle order, counter-clockwise from straight behind the watcher (ties: the ray made first)
            var back = fl0 > 0 ? new Pt(-s.F.X, -s.F.Y) : new Pt(-1, 0);
            ends.Sort((a, b) =>
            {
                int ha = Half(back, a.dir), hb2 = Half(back, b.dir);
                if (ha != hb2) return ha.CompareTo(hb2);
                long c = G.Cross(new Pt(0, 0), a.dir, b.dir);
                if (c != 0) return c > 0 ? -1 : 1;
                return a.idx.CompareTo(b.idx);
            });
            var pts = new List<Pt>(); var stops = new List<string>();
            if (apex) { pts.Add(o); stops.Add("apex"); }
            foreach (var e in ends)
            {
                if (pts.Count > 0 && pts[pts.Count - 1] == e.end) continue;
                pts.Add(e.end); stops.Add(e.stop);
            }
            if (pts.Count > 1 && pts[0] == pts[pts.Count - 1]) { pts.RemoveAt(pts.Count - 1); stops.RemoveAt(stops.Count - 1); }
            // drop a point within a centimetre of the straight line between its neighbours, all three ended alike by a straight edge (the
            // shape's edge or a solid's), so a straight edge is two points; the near circle keeps its 64
            for (int i = pts.Count - 2; i >= 1; i--)
            {
                if (stops[i] != stops[i - 1] || stops[i] != stops[i + 1] || (stops[i] != "reach" && stops[i] != "blocked")) continue;
                long c = Math.Abs(G.Cross(pts[i - 1], pts[i], pts[i + 1])), l = G.Isqrt(G.D2(pts[i - 1], pts[i + 1]));
                if (l > 0 && c <= l) { pts.RemoveAt(i); stops.RemoveAt(i); }
            }
            if (pts.Count < 3) return fan;
            fan.Points = pts.ToArray(); fan.Stop = stops.ToArray();
            long far = 0; foreach (var p in pts) far = Math.Max(far, G.D2(o, p)); fan.Reach = (int)G.Isqrt(far);
            return fan;
        }

        /// <summary>0 for directions in [0, π) counter-clockwise from r, 1 for [π, 2π).</summary>
        static int Half(Pt r, Pt u)
        {
            long c = (long)r.X * u.Y - (long)r.Y * u.X, d = (long)r.X * u.X + (long)r.Y * u.Y;
            return c > 0 || (c == 0 && d > 0) ? 0 : 1;
        }

        /// <summary>Where segments ab and cd meet (one point; for overlapping collinear segments, the end of cd nearest a), else null.</summary>
        static Pt? SegPoint(Pt a, Pt b, Pt c, Pt d)
        {
            long sx = b.X - a.X, sy = b.Y - a.Y, ex = d.X - c.X, ey = d.Y - c.Y;
            long den = sx * ey - sy * ex, cx = c.X - a.X, cy = c.Y - a.Y;
            if (den == 0)
            {
                if (cx * sy - cy * sx != 0) return null; // parallel, apart
                long ss = sx * sx + sy * sy; if (ss == 0) return null;
                Pt? best = null; long bd = long.MaxValue;
                foreach (var q in new[] { c, d }) { long t = (long)(q.X - a.X) * sx + (long)(q.Y - a.Y) * sy; if (t < 0 || t > ss) continue; long dd = G.D2(a, q); if (dd < bd) { bd = dd; best = q; } }
                if (best == null && ((long)(c.X - a.X) * sx + (long)(c.Y - a.Y) * sy < 0) != ((long)(d.X - a.X) * sx + (long)(d.Y - a.Y) * sy < 0)) best = a; // a lies inside cd
                return best;
            }
            long tn = cx * ey - cy * ex, un = cx * sy - cy * sx;
            if (den < 0) { den = -den; tn = -tn; un = -un; }
            if (tn < 0 || tn > den || un < 0 || un > den) return null;
            return new Pt(a.X + (int)(sx * tn / den), a.Y + (int)(sy * tn / den));
        }

        /// <summary>Where a ray from o along d leaves the convex polygon (o inside it or on its edge), or null if it never enters.</summary>
        static Pt? PolyExit(Pt o, Pt d, List<Pt> poly)
        {
            Pt? best = null; long bd = 0;
            for (int i = 0, j = poly.Count - 1; i < poly.Count; j = i++)
            {
                Pt c = poly[j], e = poly[i];
                long ex = e.X - c.X, ey = e.Y - c.Y, den = (long)d.X * ey - (long)d.Y * ex, cx = c.X - o.X, cy = c.Y - o.Y;
                if (den == 0)
                {
                    if (cx * d.Y - cy * d.X != 0) continue; // parallel to the edge, off it
                    foreach (var q in new[] { c, e }) { long t = (long)(q.X - o.X) * d.X + (long)(q.Y - o.Y) * d.Y; if (t > 0) { long dd = G.D2(o, q); if (dd > bd) { bd = dd; best = q; } } }
                    continue;
                }
                long tn = cx * ey - cy * ex, un = cx * d.Y - cy * d.X;
                if (den < 0) { den = -den; tn = -tn; un = -un; }
                if (tn <= 0 || un < 0 || un > den) continue;
                var x = new Pt(o.X + (int)((long)d.X * tn / den), o.Y + (int)((long)d.Y * tn / den));
                long dx = G.D2(o, x); if (dx > bd) { bd = dx; best = x; }
            }
            return best;
        }

        /// <summary>Where people on the street cut the sightline o→end (CrowdBlocks: within occlude of the line, two bodies' width from
        /// either end), or null.</summary>
        static Pt? CrowdCut(Pt o, Pt end, List<Pt> walkers, long occ)
        {
            long sx = end.X - o.X, sy = end.Y - o.Y, l2 = sx * sx + sy * sy; if (l2 == 0) return null;
            long len = G.Isqrt(l2), limit = len, end2 = 4 * occ * occ;
            foreach (var p in walkers)
            {
                long px = p.X - o.X, py = p.Y - o.Y, dot = px * sx + py * sy;
                if (dot <= 0 || G.D2(p, o) <= end2) continue;
                long cross = px * sy - py * sx;
                if (cross * cross > occ * occ * l2) continue;
                long proj = dot / len, perp2 = cross * cross / l2;
                long clear = proj + G.Isqrt(Math.Max(0, end2 - perp2)) + 1;
                if (clear < limit) limit = clear;
            }
            if (limit >= len) return null;
            return new Pt(o.X + (int)(sx * limit / len), o.Y + (int)(sy * limit / len));
        }

        // ---------------------------------------------------------------- what the cell knows

        /// <summary>What the cell knows of this watcher now, or null for an id that is no watcher of this mission (rulebook sight).</summary>
        public WatcherKnown? Known(string watcher)
        {
            if (!IsWatcher(watcher)) return null;
            var kind = WatcherKind(watcher); var (learn, routine) = R.SightKinds[kind];
            var k = new WatcherKnown { Watcher = watcher, Kind = kind, WatchedS = watchedS.TryGetValue(watcher, out var ws) ? ws : 0, RoutineNeedsS = routine == "watched" ? R.SightRoutineS : 0 };
            if (learn == "arrival")
            {
                var unit = kind == "security" ? UnitOf(watcher) : null;
                bool came = unit != null ? unit.OnStreet(Tick) || unit.St == "gone" : kind == "security" ? Tick >= SecurityArrives : RivalsDrawn && RivalsArrived;
                if (came) { k.Sight = true; k.How = "arrival"; k.SightAt = unit != null ? unit.Launch : kind == "security" ? SecurityArrives : RivalsDrawnTick; k.Routine = routine == "none"; }
                return k;
            }
            foreach (var f in SightFacts)
            {
                if (f.Watcher != watcher) continue;
                if (f.What == "sight" && !k.Sight) { k.Sight = true; k.How = f.How; k.SightAt = f.Tick; }
                if (f.What == "routine" && !k.Routine) { k.Routine = true; k.RoutineAt = f.Tick; }
            }
            if (routine == "fixed" && k.Sight) { k.Routine = true; k.RoutineAt = k.SightAt; }
            if (routine == "person") { k.Routine = GuardP.KRoutine; k.RoutineAt = -1; }
            if (routine == "none") k.Routine = k.Sight;
            return k;
        }

        /// <summary>A fact learned (once each): the record the hash walks.</summary>
        void LearnSight(string watcher, string what, string how)
        {
            foreach (var f in SightFacts) if (f.Watcher == watcher && f.What == what) return;
            SightFacts.Add(new SightFact { Watcher = watcher, What = what, How = how, Tick = Tick });
        }

        /// <summary>A completed Watch of a watcher (rulebook sight learn watch): its sight, the watched seconds, and the routine once they reach
        /// sight.watch.routine (a watched routine). The guard's Watch is his person event's too: his routine is his person routine.</summary>
        void WatchedWatcher(string watcher, int seconds)
        {
            watchedS[watcher] = (watchedS.TryGetValue(watcher, out var s) ? s : 0) + seconds;
            LearnSight(watcher, "sight", "watched");
            if (R.SightKinds[WatcherKind(watcher)].routine == "watched" && watchedS[watcher] >= R.SightRoutineS) LearnSight(watcher, "routine", "watched");
        }

        /// <summary>The start state's told knowledge of a watcher (Start.Known: "sight", and "routine" for a watched routine).</summary>
        void ToldWatcher(string watcher, string what)
        {
            if (!IsWatcher(watcher)) throw new FormatException($"start known: '{watcher}' is no watcher (unknown = reject)");
            var (learn, routine) = R.SightKinds[WatcherKind(watcher)];
            if (learn != "watch") throw new FormatException($"start known: {watcher}'s sight is known on arrival (rulebook sight.kinds)");
            if (what == "sight") LearnSight(watcher, "sight", "told");
            else if (what == "routine" && routine == "watched") LearnSight(watcher, "routine", "told");
            else throw new FormatException($"start known: '{what}' of {watcher} (sight, or routine for a watched routine)");
        }

        /// <summary>The knowledge bytes for the checkpoint hash: nothing at all until the cell has learned something, so every run that
        /// never watches a watcher hashes as it always did.</summary>
        internal void HashSight(Hash.H h)
        {
            if (SightFacts.Count == 0) return;
            h.S("sight");
            foreach (var f in SightFacts) h.S(f.Watcher).S(f.What).S(f.How).I(f.Tick);
            foreach (var kv in watchedS) h.S(kv.Key).I(kv.Value);
        }

        // ---------------------------------------------------------------- Watch on a watcher (the order)

        /// <summary>Whether this operative may Watch this watcher (rulebook sight.kinds.*.by; Sky 2026-10-18: the Tech watches the machines).</summary>
        /// <summary>A watcher whose sight is known on arrival (rulebook sight learn arrival): nothing to watch for, whoever asks.</summary>
        bool ArrivesKnown(string target) => IsWatcher(target) && R.SightKinds[WatcherKind(target)].learn == "arrival";
        bool WatchesKind(Op op, string target) => IsWatcher(target) && Array.IndexOf(R.SightBy[WatcherKind(target)], Sim.Op.Name(op.Id)) >= 0;

        /// <summary>A Watch on a camera or the patrol (rulebook sight.watch) by the Scout or the Tech (sight.kinds.*.by): within its reach of the
        /// watcher on a clear line; it takes watch.s and lands as WatchedWatcher, the cell's knowledge whoever watched (the patrol's seconds add
        /// up across both). The Tech doesn't Watch while his loop holds (tethered to the cabinet: run-tethered, as for a run). The guard is
        /// watched as a person (scout.watch) and Land teaches his sight as well.</summary>
        string WatchWatcher(Op op, Order o, bool engage = true)
        {
            var kind = WatcherKind(o.Target);
            if (!IsWatcher(o.Target)) return No("target-unknown", $"'{o.Target}' is no one to watch here");
            if (R.SightKinds[kind].learn != "watch") return No("target-unknown", $"the {kind}'s sight is known when they come: there is nothing to watch for");
            if (!WatchesKind(op, o.Target)) return No("only-scout", $"only the Scout watches the {kind} (§03)");
            if (op.Id == OpId.Tech && LoopOn) return No("run-tethered", "the Tech is tethered to the cabinet while the loop holds");
            // Sky 2026-10-18: a Watch that can teach nothing is refused, free: its sight known, and its routine (a camera's comes with its sight;
            // the patrol's once the cell's Watches of it total sight.watch.routine seconds, or told)
            { var k = Known(o.Target)!; if (k.Sight && k.Routine) return No("already-watched", $"the cell knows the {o.Target.Replace("camera:", "")}{(kind == "camera" ? " camera" : "")}'s sight{(kind == "patrol" ? " and routine" : "")} already: a Watch teaches nothing more"); }
            var sh = ShapeOf(o.Target);
            if (!sh.HasValue) return kind == "patrol" ? No("patrol-down", "the patrol is down") : No("target-unknown", $"the {o.Target} is not on the street");
            var at = sh.Value.At;
            if (!G.Within(op.Pos, at, R.SightReachCm)) return No("too-far", $"stand within {R.SightReachCm / 100} m of the {o.Target.Replace("camera:", "")} {(kind == "camera" ? "camera" : "")}".TrimEnd(), m: R.SightReachCm / 100);
            if (!Sees(op.Pos, at)) return No("no-clear-line", $"no clear line: move to where the {Sim.Op.Name(op.Id)} can see it");
            if (!engage) return "";
            Engage(op, o, R.SightWatchS);
            op.BusyQuote = null; op.BusyPaid = 0;
            return "";
        }

        void LandWatchWatcher(Op op, Order o)
        {
            WatchedWatcher(o.Target, R.SightWatchS);
            var k = Known(o.Target)!;
            Note(op.Id == OpId.Tech ? "tech.watch.watched" : "scout.watch.watched", $"The {(op.Id == OpId.Tech ? "Tech" : "Scout")} has watched the {o.Target.Replace("camera:", "") + (k.Kind == "camera" ? " camera" : "")}: its sight is known{(k.Routine ? ", and its routine" : k.RoutineNeedsS > 0 ? $" ({k.WatchedS} of {k.RoutineNeedsS} s toward its routine)" : "")}.");
        }

        // ---------------------------------------------------------------- the routine ahead (stage 2)

        /// <summary>The watcher's schedule from now to now + horizon, as watched (no interference assumed beyond what the cell already did):
        /// null while its routine is unknown. The patrol: where it stands (its first event now: sees-door or door-clear), then each turn at
        /// an end of its sweep and each change in whether it sees the public door; back-on-sweep after a reroute; off-routine while it
        /// chases. The guard: his visit if he is away (at-cafe, leaves-cafe, back-at-door), else nothing (he holds the door). A camera:
        /// nothing (fixed). Cost: one sweep test a tick of the horizon for the patrol (1,000 ticks ≈ 0.1 ms); call it once a second.</summary>
        public List<RoutineEvent>? Routine(string watcher, int horizonTicks)
        {
            var k = Known(watcher); if (k == null || !k.Routine) return null;
            var l = new List<RoutineEvent>(); int end = Tick + Math.Max(0, horizonTicks);
            void add(int t, string what) { if (t >= Tick && t <= end) l.Add(new RoutineEvent { Tick = t, What = what }); }
            switch (k.Kind)
            {
                case "patrol":
                    {
                        if (PatrolDown) return l;
                        if (PatrolChasing) { add(Tick, "off-routine"); return l; }
                        int from = Tick;
                        if (PatrolAwayUntil > Tick) { add(PatrolAwayUntil, "back-on-sweep"); from = PatrolAwayUntil; }
                        int period = T(R.PatrolPeriodS), half = period / 2;
                        bool? was = null;
                        for (int t = from; t <= end; t++)
                        {
                            int ph = t % period;
                            if (t > from && ph == 0) add(t, "turn-at-a");
                            if (t > from && ph == half) add(t, "turn-at-b");
                            bool sees = SweepSeesEntrance(t);
                            if (was != sees) add(t, sees ? "sees-door" : "door-clear");
                            was = sees;
                        }
                        l.Sort((a, b) => a.Tick != b.Tick ? a.Tick.CompareTo(b.Tick) : 0);
                        return l;
                    }
                case "guard":
                    {
                        if (GuardDown || GuardHeld || LureTick < 0 || Tick >= GuardAwayUntil) return l;
                        if (guardRunning) { add(GuardAwayUntil, "back-at-door"); return l; }
                        add(LureTick + walkT, "at-cafe"); add(LureTick + walkT + stayT, "leaves-cafe"); add(GuardAwayUntil, "back-at-door");
                        return l;
                    }
                default: return l;
            }
        }

        // ---------------------------------------------------------------- detection (the fill)

        /// <summary>Every watcher that notices an operative now, in WatcherIds then operative order: the fill toward the operative, and
        /// whether the cell knows the watcher (else the HUD's "?"). Today a watcher notices at once (rulebook perception): a sighting is
        /// logged on the whole second, a run or a drawn weapon counts the tick it is seen. An operative inside the Office or down is not
        /// noticed. Read-only; ~5 watchers × 4 operatives sight tests a call.</summary>
        public List<Noticing> Detection()
        {
            var l = new List<Noticing>();
            foreach (var w in WatcherIds())
            {
                var sh = ShapeOf(w); if (!sh.HasValue || !sh.Value.Live) continue;
                bool known = Known(w)!.Sight;
                foreach (var op in Ops)
                {
                    if (op.Inside || op.Down) continue;
                    if (SeesNow(w, op.Pos)) l.Add(new Noticing { Watcher = w, Op = Sim.Op.Name(op.Id), PerMille = 1000, Known = known, From = sh.Value.At, To = op.Pos });
                }
            }
            return l;
        }
        /// <summary>One watcher's detection of one operative, per mille (0..1000).</summary>
        public int DetectionOf(string watcher, string op)
        {
            var o = OpOf(Sim.Op.Parse(op)); if (o.Inside || o.Down) return 0;
            return SeesNow(watcher, o.Pos) ? 1000 : 0;
        }

        // ---------------------------------------------------------------- "seen by" on a card

        /// <summary>The "seen by" a card shows for an operative at these points now (rulebook sight.unknown): each watcher whose sight the
        /// cell knows gives its true answer (SeesNow, people on the street included); one it doesn't know shows "?" if it could see any point
        /// whatever its facing (within its farthest sight, on a clear line past the walls), and nothing if it couldn't. A watcher not
        /// watching now (looped, rerouted) shows nothing: the cell did that. The outcome never reads this; only the card does.</summary>
        public SeenQuote SeenAt(IReadOnlyList<Pt> points)
        {
            var q = new SeenQuote { AlertIfSeen = Math.Max(Alert, R.RunAlert) };
            foreach (var w in WatcherIds())
            {
                var sh = ShapeOf(w); if (!sh.HasValue || !sh.Value.Live) continue;
                var k = Known(w)!;
                if (k.Sight) { foreach (var p in points) if (SeesNow(w, p)) { q.SeenBy.Add(w); break; } continue; }
                long reach = FarthestSight(sh.Value);
                foreach (var p in points) if (G.Within(sh.Value.At, p, (int)reach) && Sees(sh.Value.At, p)) { q.MaybeSeenBy.Add(w); break; }
            }
            q.Seen = q.SeenBy.Count > 0 ? "yes" : q.MaybeSeenBy.Count > 0 ? "?" : "no";
            if (q.Seen == "no") q.AlertIfSeen = Alert;
            return q;
        }
        public SeenQuote SeenAt(Pt at) => SeenAt(new[] { at });

        /// <summary>The farthest a shape sees, any facing: its far corner, or its near circle.</summary>
        static long FarthestSight(Shape s) => s.Sweep
            ? G.Isqrt((long)s.Depth * s.Depth + (long)(s.HalfBase + (long)s.Depth * s.PerMille / 1000) * (s.HalfBase + (long)s.Depth * s.PerMille / 1000))
            : Math.Max(s.Near, G.Isqrt((long)s.Reach * s.Reach + (long)s.Half * s.Half));
    }
}

sim/Suborned.Sim/GameStashWatch.cs.text:
// The Scout's Watch on a container (GDD §05 bodies: "A container is emptied on a round every 15:00, its time learnable by Watch, in the
// mission only"). The round itself is GameTakedown's ServiceRound and the HUD's NextRound; this file holds what the cell has learned of
// it. The Watch reuses the rulebook's sight.watch (its seconds and its reach) and the Watch cancel line (lost: nothing learned). Mission
// knowledge only: never carried to the debrief. Hashed only once something is learned, so every run that never watches a container
// hashes as it always did.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed partial class Game
    {
        /// <summary>The containers whose round the cell has learned this mission, in the order learned, with the tick each was learned.</summary>
        readonly List<(string id, int tick)> roundsKnown = new List<(string id, int tick)>();

        /// <summary>Whether this id is a container stash (one with a servicing round).</summary>
        bool IsContainer(string id) => StashById(id) is StashPlace s && s.Kind == "container";

        /// <summary>Whether the cell knows this container's round (a completed Watch). Read-only.</summary>
        public bool KnowsRound(string stashId) => roundsKnown.Exists(r => r.id == stashId);

        /// <summary>A Watch on a container (the Scout's: §03 Watch reveals a routine): within sight.watch reach of the container's stand on a
        /// clear line; it takes sight.watch seconds, costs nothing, and lands as the round learned. A round already known is refused
        /// already-watched, free. `engage` false only checks (LearnQuery) and changes nothing.</summary>
        string WatchContainer(Op op, Order o, bool engage = true)
        {
            var s = StashById(o.Target);
            if (s == null || s.Kind != "container") return No("target-unknown", $"'{o.Target}' is no container to watch here");
            if (op.Id != OpId.Scout) return No("only-scout", "only the Scout watches a container's round (§03)");
            if (KnowsRound(s.Id)) return No("already-watched", $"the cell knows when the round empties the {s.Id} already: a Watch teaches nothing more");
            if (!G.Within(op.Pos, s.Stand, R.SightReachCm)) return No("too-far", $"stand within {R.SightReachCm / 100} m of the {s.Id}", m: R.SightReachCm / 100);
            if (!Sees(op.Pos, s.Stand)) return No("no-clear-line", $"no clear line: move to where the {Sim.Op.Name(op.Id)} can see it");
            if (!engage) return "";
            Engage(op, o, R.SightWatchS);
            op.BusyQuote = null; op.BusyPaid = 0;
            return "";
        }

        void LandWatchContainer(Op op, Order o)
        {
            var s = StashById(o.Target);
            if (s == null || s.Kind != "container" || KnowsRound(s.Id)) return;
            roundsKnown.Add((s.Id, Tick));
            int next = NextRound(s.Id).tick, secs = next / Hz;
            Note("scout.watch.container", $"The Scout has watched the {s.Id}: the round empties it every {R.ServicePeriodS / 60}:{R.ServicePeriodS % 60:00}, next at {secs / 60}:{secs % 60:00}.");
        }

        /// <summary>The learned rounds for the checkpoint hash: no bytes until the cell has learned one.</summary>
        internal void HashStashWatch(Hash.H h)
        {
            if (roundsKnown.Count == 0) return;
            h.S("rounds-known").I(roundsKnown.Count);
            foreach (var (id, tick) in roundsKnown) h.S(id).I(tick);
        }
    }
}

sim/Suborned.Sim/GameTakedown.cs.text:
// Takedowns, bodies and the people who find them (brief 013 B, Keel; Sky 2026-10-16: "anyone can be targeted, but it's all about being seen
// or not"). The rules are the rulebook's `takedown` and `witness` sections (Motive, briefs/013/motive-takedowns.md; Pulse,
// briefs/013/pulse-witnesses.md). One rule set for every simulated person, cast or crowd: no named target list.
//  · The Enforcer takes a person down (knockout or kill) within reach; the victim is seized at the order and lies where he fell: a body.
//  · A body persists. Anyone whose sight passes an open body finds it; only a stash (a container, a service door) hides one.
//  · Silent acts reach Alert only through people: a witness or a finder decides by Pulse's list, walks to a phone and calls; the report
//    lands at the desk and Alert rises then (Sky merged call 1). Gunfire keeps its rule at sight.
//  · One takedown is one incident (TdAct): every discovery of it (seen, found, carried, woken, missed, missing) raises Alert once, to
//    the worst level, and its Trail is charged once.
// Integers only; people in OnTheStreet order (the cast by role, then the crowd by id); acts, bodies and reports in creation order.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    /// <summary>A person taken down: where they lie, who carries them, the stash that hides them, whether they are tied (brief 013).</summary>
    public sealed class Body
    {
        public string Id = ""; public Person P = null!; public Walker? W; public int Act;
        public bool Dead, Seizing, Restrained; public Pt At; public OpId? Carrier; public string Stash = "";
        public int DownTick, WakeAt, Phase, NextCallOut = -1, FreeAt = -1;
        public bool Open => Stash.Length == 0;
    }

    /// <summary>One takedown, one incident (Motive §2.3): what the city has learned of it. Take: Vale's abduction seen (How "take", no
    /// body; Aster 2026-10-16, brief 013 D: a Take seen within witness range is a takedown seen).</summary>
    public sealed class TdAct
    {
        public int Id; public string Victim = "", How = ""; public Person P = null!; public Pt At, Scene; public int Tick; public bool Aware, Kill;
        public int Alert; public bool Take, Landed, Witnessed, TrailPaid, StandingPaid, ActTrail, Confirmed, SecuritySaw, MarkMissed, Missed, Woke, Statement;
        public readonly SortedSet<string> Noticed = new SortedSet<string>(StringComparer.Ordinal); // who reacted (people by id, watchers by id)
        public readonly SortedSet<string> Heard = new SortedSet<string>(StringComparer.Ordinal);
        public readonly SortedSet<string> Opened = new SortedSet<string>(StringComparer.Ordinal);  // stashes the search opened
        public readonly SortedSet<string> Told = new SortedSet<string>(StringComparer.Ordinal);    // who heard of it from a tie (one hop: never retold)
        public Incident? Lead;                                                                     // the investigation's lead for it
    }

    /// <summary>A report on its way to the desk (Pulse §3): who carries it, what it says, when it lands.</summary>
    public sealed class Rep
    {
        public int Seq, Act; public string Kind = "", By = "", Stash = ""; public Person? P; public Walker? W; public Pt Place; public int Sev, LandAt;
        public string Phase = "";   // react, check, walk, call, radio, watcher; a tell (Kind "tell"): walk, flee, call
        public int PhaseUntil;      // check: when the check ends
    }

    /// <summary>What the takedown card shows before the order is given (Motive §5.4). "?" where the cell doesn't know.</summary>
    public sealed class TakedownQuote
    {
        public string Refused = "", RefusedCode = "";
        public long Usd; public int S;                     // time in seconds (the struggle included when the target sees it coming)
        public string Aware = "?";                         // yes, no, ? (from behind: no)
        public bool Armed; public string IfAware = "";     // "struggle" or "fight" (an armed target who sees it coming)
        public SeenQuote Seen = new SeenQuote();           // watchers: true answer if known, "?" if not (rulebook sight.unknown)
        public readonly List<(string id, string name, string verb, int landS)> People = new List<(string, string, string, int)>(); // within witness range now: verb "?" until the temperament is known
        public int AlertIfSeen, AlertIfFound, TrailIfFound, TrailIfMissing; public bool MenaceIfFound;
        public int PoliceInS = -1;                         // a body found here now by staff: the response on the scene in ~n s (rev 4: a unit comes at any Alert)
        public readonly List<string> HoldsDoors = new List<string>(); // rev 4 R4.1: the entrances a found body here would hold (Enter refused, no exit)
        public int HoldS;                                  // and for about how long once the unit is there (s): its sweep, or the search stand-down at Alert 2
        public string IfNeverFound = "";                   // comes-home or missing
        public int WakesAt = -1, NextMark = -1, Ties;      // ticks; the next check-in mark of a staff victim once his routine is known; ties (kill)
    }

    public sealed partial class Game
    {
        public readonly List<TdAct> Acts = new List<TdAct>();
        public readonly List<Body> Bodies = new List<Body>();
        public readonly List<Rep> Reps = new List<Rep>();
        readonly SortedSet<string> markedFoes = new SortedSet<string>(StringComparer.Ordinal); // operatives security saw do violence (they engage them)
        int repSeq;
        /// <summary>Security saw this operative do violence (brief 013): they engage him on sight, weapon out or not.</summary>
        public bool MarkedFoe(string op) => markedFoes.Contains(op);
        Dictionary<string, Person>? byIdCache; Dictionary<Person, Walker>? walkerOfCache;

        // ---------------------------------------------------------------- who is who

        Dictionary<string, Person> ById { get { if (byIdCache == null) BuildIndex(); return byIdCache!; } }
        Dictionary<Person, Walker> WalkerOfMap { get { if (walkerOfCache == null) BuildIndex(); return walkerOfCache!; } }
        void BuildIndex()
        {
            byIdCache = new Dictionary<string, Person>(StringComparer.Ordinal); walkerOfCache = new Dictionary<Person, Walker>();
            foreach (var p in People) byIdCache[p.Id] = p;
            foreach (var w in Walkers) { byIdCache[w.P.Id] = w.P; walkerOfCache[w.P] = w; }
        }
        /// <summary>A simulated person by role (waitress, driver, guard, councillor) or by id, cast or crowd; null if none.</summary>
        public Person? PersonById(string idOrRole)
        {
            if (IsPersonRoleName(idOrRole)) return PersonByRole(idOrRole);
            return ById.TryGetValue(idOrRole, out var p) ? p : null;
        }
        /// <summary>Where a person stands now, or (off the street) where the mission keeps them; for the scenarios.</summary>
        public Pt CrowdPosOrStand(Person p) => PosOfPerson(p) ?? (p.Place.Length > 0 && S.HasPlace(p.Place) ? S.Stand(p.Place) : default);
        public Walker? WalkerOf(Person p) => WalkerOfMap.TryGetValue(p, out var w) ? w : null;
        /// <summary>Where a person stands on the street now, cast or crowd; null if down, inside or off the street.</summary>
        public Pt? PosOfPerson(Person p) { var w = WalkerOf(p); return w != null ? (Start.Crowd ? CrowdPos(w) : null) : PersonPos(p); }
        bool IsStaff(Person p) => p == GuardP || R.StaffJobs.Contains(p.Job);
        bool IsCellPerson(Person p) => p.Turned || p.Sc[Rules.Loyalty] >= R.WordQuietLoyalty;
        /// <summary>The kinds of tie a has with b (the people file's ties; the cast's lover tie as the engine holds it).</summary>
        List<string> TiesBetween(Person a, Person b)
        {
            var l = new List<string>();
            if (People2 != null && People2.Ties.TryGetValue(a.Id, out var ts)) foreach (var (k, w) in ts) if (w == b.Id && !l.Contains(k)) l.Add(k);
            if (a.Lover == b && !l.Contains("lover")) l.Add("lover");
            return l;
        }
        bool IsKin(Person a, Person victim) { foreach (var k in TiesBetween(a, victim)) if (R.KinTies.Contains(k)) return true; return false; }
        public Body? BodyOf(Person p) { foreach (var b in Bodies) if (b.P == p) return b; return null; }
        public Body? BodyById(string idOrRole) { var p = PersonById(idOrRole); return p == null ? null : BodyOf(p); }
        /// <summary>Where a body is now: with its carrier, in its stash, or where it lies.</summary>
        public Pt BodyPos(Body b) => b.Carrier.HasValue ? OpOf(b.Carrier.Value).Pos : b.At;
        TdAct ActOf(Body b) => Acts[b.Act];
        StashPlace? StashById(string id) { foreach (var s in S.Stashes) if (s.Id == id) return s; return null; }
        int InStash(string id) { int n = 0; foreach (var b in Bodies) if (b.Stash == id) n++; return n; }
        /// <summary>How many bodies a stash holds (rev 4 R4.3): a service door takedown.stash.doorHolds (a storeroom), a container what its
        /// site entry says (the Dumpster 1). The site's door entries carry 1 from before rev 4; the rulebook's number is the rule.</summary>
        public int HoldsOf(StashPlace s) => s.Kind == "door" ? R.StashDoorHolds : s.Holds;

        // ---------------------------------------------------------------- the takedown order

        /// <summary>Is the target aware of the Enforcer as the order is given (Motive §1.3)? The guard by his own cone (his door cone at the
        /// door); anyone walking by the facing cone along the way they walk; anyone who has witnessed one of the cell's acts this mission;
        /// otherwise a person standing at a stop has no facing yet (Pulse), so is surprised. A runner within witness range is heard.
        /// Armed: carries a weapon (the door guard).</summary>
        (bool aware, bool armed) Awareness(Person p, Pt at)
        {
            var e = Enforcer; bool armed = p == GuardP && GuardGun.W != null && !GuardAlly;
            bool aware = e.Running && (e.Walk != null || e.DriveMoved) && G.Within(e.Pos, at, witnessRange); // brief 025: a driven run is a run
            if (!aware && p == GuardP) aware = GuardWatching(e.Pos, false);
            // Motive rev 3 §1.3: a person who witnessed one of the cell's acts (a takedown, a carry, a drawn weapon) stays aware of the
            // Enforcer for the rest of the mission (until Pulse gives a stop its facing)
            if (!aware) foreach (var m in p.Memory) if (m.Act == "saw-takedown" || m.Act == "saw-carry" || m.Act == "saw-weapon-drawn") { aware = true; break; }
            if (!aware) { var f = FacingOf(p); if (f.HasValue && G.InCone(at, f.Value, R.FacingReachCm, R.FacingHalfCm, 0, e.Pos) && Sees(at, e.Pos)) aware = true; }
            return (aware, armed);
        }
        /// <summary>The way a person faces now, if the engine knows it: a walker on the move, the way they walk; else none.</summary>
        Pt? FacingOf(Person p)
        {
            var w = WalkerOf(p); if (w == null || !Start.Crowd || w.P.Down) return null;
            if (w.St.Length > 0)
            {
                if (w.Run != null && (w.St == "fleeing" || w.St == "returning" || w.St == "reporting" || w.St == "checking") && Tick >= w.RunStart)
                { long mm = (long)(Tick - w.RunStart) * (w.Pace > 0 ? w.Pace : w.St == "fleeing" ? R.CrowdRunSpeed : opSpeed); if (mm < w.Run.Length) return w.Run.Heading(mm); }
                return null;
            }
            var c = People2!;
            for (int i = 0; i + 1 < w.Place.Length; i++)
                if (Tick >= w.To[i] && Tick < w.From[i + 1] && w.Place[i] != "beyond" && w.Place[i + 1] != "beyond")
                {
                    var path = CrowdPath(w.Place[i], w.Place[i + 1]); int span = w.From[i + 1] - w.To[i];
                    return span <= 0 ? (Pt?)null : path.Heading(LegMm(w, path, Tick - w.To[i], span));
                }
            return null;
        }

        string Takedown(Op op, Order o)
        {
            if (op.Id != OpId.Enforcer) return No("only-enforcer", "only the Enforcer takes people down (§03; brief 013)");
            if (Vale == ValeAt.WithEnforcer || Vale == ValeAt.Taking) return No("carry-vale", "the Enforcer is carrying Vale");
            if (op.Carrying.HasValue || op.CarryBody.Length > 0) return No("already-carrying", "already carrying");
            if (o.How != "knockout" && o.How != "kill") return No("takedown-how", "a takedown is a knockout or a kill");
            var p = PersonById(o.Target);
            if (p == null) return No("target-unknown", $"'{o.Target}' is no one here (unknown = reject)");
            if (p == ValeP && o.How == "knockout") return No("takedown-vale", "Vale is taken, not knocked out: use Take");
            var at = PosOfPerson(p);
            if (!at.HasValue) return p.Down ? No("person-down", $"{o.Target} is down") : No("person-away", $"{o.Target} is not out on the street");
            if (!G.Within(op.Pos, at.Value, R.TakedownReachCm)) return No("too-far", $"stand within {R.TakedownReachCm} cm of {o.Target}", cm: R.TakedownReachCm);
            var (aware, armed) = Awareness(p, at.Value);
            op.Walk = null; op.WalkMm = 0; op.Running = false;
            Actions.Add("takedown:" + o.How);
            if (aware && armed) { TakedownFails(op, p, at.Value); return ""; }
            var a = new TdAct { Id = Acts.Count, Victim = p.Id, How = o.How, P = p, At = at.Value, Scene = at.Value, Tick = Tick, Aware = aware, Kill = o.How == "kill" };
            Acts.Add(a);
            var b = new Body { Id = p.Id, P = p, W = WalkerOf(p), Act = a.Id, Seizing = true, At = at.Value, Dead = false, WakeAt = INF, Phase = (int)(Streams.Fnv1a32(p.Id) % (uint)R.BodyCheckTicks) };
            Seize(p, at.Value);
            Bodies.Add(b);
            int secs = (a.Kill ? R.KillS : R.KoS) + (aware ? R.StruggleS : 0);
            Engage(op, o, secs);
            Note("takedown.starts", $"The Enforcer takes {Who(p)} down ({o.How}, {secs} s){(aware ? ": he sees it coming and struggles" : "")}.");
            if (aware) Shout(a, at.Value, p);
            ScanAct(a, at.Value, "act", b);
            return "";
        }

        /// <summary>The armed target saw him coming (Motive §1.3): the takedown fails into a fight, under the drawn-weapon rule.</summary>
        void TakedownFails(Op op, Person p, Pt at)
        {
            Note("takedown.fails", $"{Who(p)} sees the Enforcer coming and draws: the takedown fails.");
            markedFoes.Add("enforcer");
            var pose = GuardPose();
            if (pose.HasValue && pose.Value.phase != "door" && !GuardHeld) { GuardHeld = true; heldPos = pose.Value.pos; heldFacing = pose.Value.facing; heldPhase = "drawing on the cell"; GuardAwayUntil = INF; }
            GuardEngaged = true; Remember(GuardP, "attacked-aware", "enforcer", true);
            RaiseAlert(R.DrawSeenSecurity, "takedown-fails:" + p.Id);
            CallSecurity(R.RespSeenS, "The guard calls in an attack.", at, origin: () => OriginNow("attack:" + Who(p), "response", Who(p), at, at, op.Pos, "enforcer"));
        }

        /// <summary>The person is taken off the street (a body from the order on: no witness, no reporter, no walk).</summary>
        void Seize(Person p, Pt at)
        {
            p.Down = true;
            var w = WalkerOf(p); if (w != null) { w.St = ""; w.Run = null; w.Pace = 0; }
            if (p == GuardP) { GuardDown = true; GuardEngaged = false; GuardHeld = false; }
            if (p == Driver) carStoppedAt = CarPos();
            foreach (var r in Reps) if (r.P == p && r.LandAt > Tick) r.Phase = "stopped";
        }
        static string Who(Person p) => p.Role.Length > 0 ? p.Role : p.Id;

        void LandTakedown(Op op, Order o)
        {
            var b = BodyById(o.Target); if (b == null || !b.Seizing) return;
            var a = ActOf(b); var p = b.P;
            b.Seizing = false; b.DownTick = Tick; b.Dead = a.Kill; b.At = a.At;
            Remember(p, a.Aware ? "attacked-aware" : "attacked", a.Aware ? "enforcer" : "", false);
            a.Lead = AddIncident("takedown", "takedown:" + p.Id, a.At);
            if (a.Kill)
            {
                b.WakeAt = INF;
                Chain.Add("killed:" + Who(p)); Note("takedown.dead", $"{Who(p)} is dead. The body lies where it fell.");
                if (p == ValeP) { Vale = ValeAt.Dead; Fail("vale-dead", "Vale is dead. The live capture objective has failed.", () => With(Because("killed", true, Locate(Sim.Op.Name(op.Id), "killed", b.At), Locate("councillor", "victim", null, b.At)), Sim.Op.Name(op.Id))); }
            }
            else
            {
                b.WakeAt = Tick + T(R.WakeS);
                Chain.Add("knocked-out:" + Who(p)); Note("takedown.out", $"{Who(p)} is out. He wakes in {R.WakeS} s.");
            }
        }

        // ---------------------------------------------------------------- carry, drop, stash, restrain (any operative)

        string CarryBody(Op op, Order o)
        {
            var b = BodyById(o.Target);
            if (b == null || b.Seizing) return No("no-body", $"there is no body of {o.Target} to carry");
            if (b.Carrier.HasValue) return No("already-carried", $"{o.Target} is already carried");
            if (!b.Open) return No("body-stashed", $"{o.Target} is hidden");
            if (!G.Within(op.Pos, BodyPos(b), actReach)) return No("stand-beside-body", $"stand beside {o.Target}", m: actReach / 100);
            Engage(op, o, R.CarryS); op.Gun.Order = ""; op.Gun.Target = "";
            return "";
        }
        string Drop(Op op, Order o)
        {
            if (op.CarryBody.Length == 0) return No("not-carrying", "carrying nobody");
            Engage(op, o, R.DropS); return "";
        }
        string Stash(Op op, Order o)
        {
            if (op.CarryBody.Length == 0) return No("not-carrying", "carry the body to the stash first");
            var s = StashById(o.Target); if (s == null) return No("target-unknown", $"no stash '{o.Target}' (unknown = reject)");
            if (!G.Within(op.Pos, s.Stand, R.AtReachCm)) return No("stand-at-stash", "stand at the stash", cm: R.AtReachCm);
            if (InStash(s.Id) >= HoldsOf(s)) return No("stash-full", $"the {s.Id} is full");
            Engage(op, o, s.Kind == "door" ? R.StashDoorS : R.StashContainerS); return "";
        }
        string Restrain(Op op, Order o)
        {
            var b = BodyById(o.Target);
            if (b == null || b.Seizing) return No("no-body", $"there is no body of {o.Target} to tie");
            if (b.Dead) return No("body-dead", $"{o.Target} is dead");
            if (b.Restrained) return No("already-restrained", $"{o.Target} is already tied");
            if (!b.Open || b.Carrier.HasValue) return No("body-stashed", $"{o.Target} is not lying here");
            if (b.P.Down == false) return No("no-body", $"{o.Target} is awake");
            if (!G.Within(op.Pos, BodyPos(b), actReach)) return No("stand-beside-body", $"stand beside {o.Target}", m: actReach / 100);
            Engage(op, o, R.RestrainS); return "";
        }

        /// <summary>The body-handling orders land (Land's switch hands them here).</summary>
        void LandBodyOrder(Op op, Order o)
        {
            switch (o.Do)
            {
                case "carry":
                    {
                        var b = BodyById(o.Target);
                        if (b == null || b.Carrier.HasValue || !b.Open || !b.P.Down) { Note("carry.missed", $"There is nobody to lift at {o.Target}'s place."); return; }
                        b.Carrier = op.Id; op.CarryBody = b.Id;
                        Note("carry.body", $"The {Sim.Op.Name(op.Id)} lifts {Who(b.P)}{(op.Id == OpId.Enforcer ? "" : " (slowly: only the Enforcer carries at a walk)")}.");
                        return;
                    }
                case "drop": PutDown(op, "drop"); return;
                case "stash":
                    {
                        var b = CarriedBody(op); var s = StashById(o.Target);
                        if (b == null || s == null) return;
                        b.Carrier = null; op.CarryBody = ""; b.Stash = s.Id; b.At = s.Stand;
                        if (!b.Dead && b.NextCallOut < 0 && b.WakeAt <= Tick) b.NextCallOut = Tick + T(R.CallOutS);
                        Actions.Add("stash:" + s.Kind); Note("stash." + s.Kind, $"{Who(b.P)} is hidden in the {s.Id}.");
                        return;
                    }
                case "restrain":
                    {
                        var b = BodyById(o.Target); if (b == null || b.Dead || !b.Open || !b.P.Down) return;
                        b.Restrained = true; b.NextCallOut = -1;
                        Note("restrain.done", $"{Who(b.P)} is tied.");
                        return;
                    }
            }
        }
        Body? CarriedBody(Op op) { if (op.CarryBody.Length == 0) return null; foreach (var b in Bodies) if (b.Id == op.CarryBody && b.Carrier == op.Id) return b; return null; }
        /// <summary>A carried body is laid down where the carrier stands (drop, cancel, the carrier hit or down).</summary>
        void PutDown(Op op, string why)
        {
            var b = CarriedBody(op); op.CarryBody = ""; if (b == null) return;
            b.Carrier = null; b.At = op.Pos;
            Note("carry.down", $"{Who(b.P)} is laid down ({why}).");
        }

        // ---------------------------------------------------------------- what the city sees (Pulse §2)

        /// <summary>Everyone on the street within witness range on a clear line of `at`, and every watcher that sees it, notices `what`
        /// (act, carry, body) once per incident (Pulse §2.2). b is null for a Take (Vale is no body). dry: only whether anyone would notice
        /// now, changing nothing (the Take's incident opens at its first sighting, so an unseen Take leaves no trace).</summary>
        bool ScanAct(TdAct a, Pt at, string what, Body? b, bool dry = false)
        {
            foreach (var (p, wp) in OnTheStreet())
            {
                if (p == a.P || a.Noticed.Contains(p.Id) || Accomplice(a, p)) continue; // rev 4: an accomplice is never a witness
                if (!G.Within(wp, at, witnessRange) || !Sees(wp, at)) continue;
                if (dry) return true;
                a.Noticed.Add(p.Id);
                PersonNotices(a, p, wp, what, b);
                if (Over) return true;
            }
            foreach (var w in WatchersNow())
            {
                if (a.Noticed.Contains(w)) continue;
                if (w == "guard") continue; // the door guard is a person: he notices as one (above), within witness range, and by his cone (below)
                if (!WatcherSees(w, at)) continue;
                if (dry) return true;
                a.Noticed.Add(w);
                WatcherNotices(a, w, what, b);
                if (Over) return true;
            }
            if (!a.Noticed.Contains(GuardP.Id) && !GuardAlly && !GuardDown && GuardP != a.P && GuardWatching(at))
            {
                if (dry) return true;
                a.Noticed.Add(GuardP.Id); PersonNotices(a, GuardP, GuardPose()!.Value.pos, what, b);
            }
            return false;
        }
        /// <summary>Where an act is now: its body (with its carrier, in its stash, where it lies), or for a Take, Vale where he is being taken.</summary>
        Pt ActAt(TdAct a, Body? b) => b != null ? BodyPos(b) : a.Take ? (ValePos() ?? a.At) : a.At;

        /// <summary>The city's eyes now: the cameras, the guard, the patrol, the response unit's officers and the response's units, by id.</summary>
        List<string> WatchersNow()
        {
            var l = new List<string>();
            foreach (var c in S.Cameras) l.Add("camera:" + c.Id);
            l.Add("guard"); l.Add("patrol");
            if (Tick >= SecurityArrives) l.Add("security");
            foreach (var u in Units) if (u.OnStreet(Tick) && !u.Patrol && !u.Legacy && !u.Gun.Down) l.Add(u.Id);
            return l;
        }

        /// <summary>A person notices an act, a carry or a body: the sighting (Trail and Standing once an incident, a turned contact's
        /// saw-violence move), then their reaction by the list (Pulse §2.3).</summary>
        void PersonNotices(TdAct a, Person p, Pt wp, string what, Body? b)
        {
            if (what == "body") RoundsEnd("body-found"); // brief 022
            string by = what == "act" ? "enforcer" : what == "carry" && b != null && b.Carrier.HasValue ? Sim.Op.Name(b.Carrier.Value) : "";
            Remember(p, what == "act" ? "saw-takedown" : what == "carry" ? "saw-carry" : "found-body", by, true);
            if (a.Lead != null && !a.Lead.Witnesses.Exists(x => x.p == p)) a.Lead.Witnesses.Add((p, wp));
            if (what != "body") AtSight(a, p);
            if (p == GuardP && what != "body" && !GuardAlly) { SecuritySees(a, "guard", what, b); return; } // armed security engages (Motive §1.4)
            React(a, p, wp, what, b);
        }

        /// <summary>A witnessed act at sight (Motive §1.4): +witness Trail once an incident unless the witness owes the cell (Sky call 5),
        /// Standing once whoever saw it, a turned contact's saw-violence move.</summary>
        void AtSight(TdAct a, Person p)
        {
            a.Witnessed = true;
            if (!IsCellPerson(p) && !a.TrailPaid) { a.TrailPaid = true; AddTrail(R.WitnessTrail, "witnessed:takedown:" + a.Victim); }
            if (!a.StandingPaid) { a.StandingPaid = true; MoveStanding(R.Traceable["takedown"] * R.StandingStep, "witnessed:takedown:" + a.Victim, "seen-takedown", Who(a.P)); }
            if (p.Turned) LadderMove(p, "saw-violence");
        }

        /// <summary>Pulse's decision list, first row that holds (rulebook witness.rule).</summary>
        string Decide(TdAct a, Person p, string what)
        {
            int f = p.Sc[Rules.Fear];
            if (IsStaff(p)) return "radio";
            if (IsKin(p, a.P)) return f >= R.TerrifiedFear ? "flee" : "report";
            if (IsCellPerson(p)) return "quiet";
            if (p.Sc[Rules.Resentment] >= R.ScaleMax[Rules.Resentment]) return "report";
            if (f >= R.TerrifiedFear) return "flee";
            switch (p.Temperament)
            {
                case "loyal": return "report";
                case "idealist": return what == "body" ? "check" : "report";
                case "mercenary": return Alert >= R.MercenaryAlert ? "report" : "quiet";
                case "fearful": return what == "body" ? "avoid" : "flee";
                default: return "quiet";
            }
        }
        /// <summary>The verb a card shows for this person (Pulse §3.6): "?" until the cell knows the temperament, unless a row before the
        /// temperament's decides it (staff, kin, a contact).</summary>
        string VerbShown(TdAct a, Person p, string what)
        {
            if (IsStaff(p) || IsKin(p, a.P) || IsCellPerson(p) || p.KTemperament) return Decide(a, p, what);
            return "?";
        }

        void React(TdAct a, Person p, Pt wp, string what, Body? b)
        {
            string verb = Decide(a, p, what);
            bool kin = IsKin(p, a.P);
            bool shout = kin || (what != "body" && ((verb == "report" && p.Temperament == "idealist") || (verb == "flee" && p.Sc[Rules.Fear] >= R.ScreamFear)));
            Note("witness.react", $"{Who(p)} {(what == "act" ? "sees the takedown" : what == "carry" ? "sees a body carried" : "finds a body")}: {verb}.");
            if (shout) Shout(a, ActAt(a, b), p);
            var w = WalkerOf(p);
            switch (verb)
            {
                case "radio": StartReport(a, p, KindOf(a, b, what, true), wp, "radio", b); break;
                case "report": StartReport(a, p, KindOf(a, b, what, false), wp, what == "body" && !kin ? "walk" : "run", b); break; // kin run without hesitation (Pulse row 2)
                case "check": StartReport(a, p, "down", wp, "check", b); break;
                case "flee":
                    {
                        bool fled = false;
                        if (w != null && (w.St == "" || w.St == "returning")) { fled = true; w.St = "startled"; w.At = wp; w.Run = null; w.RunStart = Tick; w.Pace = 0; lastShooterFor[p.Id] = ActAt(a, b); w.Until = Tick + (p.Temperament == "fearful" ? R.CrowdStartleFearfulTicks : R.CrowdStartleTicks); }
                        TellOrPhone(a, p, w, wp, fled); break;
                    }
                default: TellOrPhone(a, p, w, wp, false); break; // quiet, avoid
            }
            if (b != null && b.Restrained && !b.Dead && (verb == "report" || verb == "check" || verb == "radio") && b.FreeAt < 0) b.FreeAt = Tick + T(R.WitnessReactS) + T(R.FreeS); // Pulse §2.1 free
        }
        /// <summary>What a report says (Motive §2.3): a takedown seen, a carry seen, a dead body (when the finder knows: staff), a person lying.</summary>
        string KindOf(TdAct a, Body? b, string what, bool knows) => what == "act" ? "seen" : what == "carry" ? "carry" : knows && b != null && b.Dead ? "dead" : "down";
        int SevOf(string kind) => kind switch
        {
            "seen" => R.AlertSeen, "carry" => R.AlertCarry, "dead" => R.AlertDead, "down" => R.AlertDown, "woken" => R.AlertWoken,
            "noise" => R.AlertNoise, "mark" => R.AlertMark, "missing" => R.AlertMissing, "tell" => 0, _ => R.AlertDown, // a tell never lands at the desk
        };

        /// <summary>A scream (Pulse §2.1 shout): heard within witness.scream with no line. A hearer with a line within witness range has
        /// seen it already; the rest hold heard-alarm (a lead: place and time).</summary>
        void Shout(TdAct a, Pt at, Person by)
        {
            Note("witness.scream", $"{Who(by)} screams.");
            foreach (var (p, wp) in OnTheStreet())
            {
                if (p == by || p == a.P || a.Noticed.Contains(p.Id) || a.Heard.Contains(p.Id)) continue;
                if (!G.Within(wp, at, R.ScreamCm)) continue;
                a.Heard.Add(p.Id); Remember(p, "heard-alarm", "", false);
            }
        }

        /// <summary>A watcher notices (Pulse §3.2): a camera's watcher reports at its next scan; the patrol robot rings the desk; armed
        /// security that sees an act or a carry engages (Motive §1.4); the response's units find a body for the scene they hold.</summary>
        void WatcherNotices(TdAct a, string w, string what, Body? b)
        {
            string kind = KindOf(a, b, what, true);
            if (what == "body") RoundsEnd("body-found"); // brief 022
            if (w.StartsWith("camera:", StringComparison.Ordinal))
            {
                int phase = (int)(Streams.Fnv1a32(w) % (uint)T(R.CameraScanS)), period = T(R.CameraScanS);
                int next = Tick + ((phase - Tick % period) % period + period) % period;
                AddRep(a, kind, w, null, ActAt(a, b), next + T(R.PostCallS), "watcher");
                Note("witness.camera", $"The {w.Substring(7)} camera records it; its watcher reads the screen at {Sim.Report.Clock(next)}.");
                return;
            }
            if (what != "body") { SecuritySees(a, w, what, b); return; }
            if (b == null) return;
            if (w == "patrol") { AddRep(a, kind, w, null, BodyPos(b), Tick + T(R.RobotReportS), "watcher"); Note("witness.patrol", "The patrol finds a body and rings the desk."); return; }
            FoundBySecurity(b, w); // the response finds it
        }

        /// <summary>Armed security sees violence (Motive §1.4): Alert to the drawn-weapon level at sight, the operative is a foe they engage,
        /// and they call it in: the incident lands at once and is confirmed by their own eyes.</summary>
        void SecuritySees(TdAct a, string w, string what, Body? b)
        {
            string actor = what == "carry" && b != null && b.Carrier.HasValue ? Sim.Op.Name(b.Carrier.Value) : "enforcer";
            markedFoes.Add(actor);
            Note("takedown.seen", $"The {w.Replace("camera:", "")} sees {(what == "carry" ? "a body carried" : a.Take ? "Vale taken" : "the takedown")}: Alert {Math.Max(Alert, R.DrawSeenSecurity)}.");
            if (w == "guard" && !GuardDown)
            {
                var pose = GuardPose(); if (pose.HasValue && pose.Value.phase != "door" && !GuardHeld) { GuardHeld = true; heldPos = pose.Value.pos; heldFacing = pose.Value.facing; heldPhase = "drawing on the cell"; GuardAwayUntil = INF; }
                GuardEngaged = true;
            }
            if (w == "patrol" && !PatrolChasing && !PatrolDown && PatrolAwayUntil <= Tick && PatrolUnit() == null)
            { chasePos = PatrolPose()!.Value.pos; PatrolChasing = true; chaseOp = Sim.Op.Parse(actor); patrolOrigin = OpOf(chaseOp).Pos; patrolReturning = false; PatrolGun.NoFoeSince = -1; Note("patrol.breaks", "The patrol breaks its route and turns on the cell."); }
            a.SecuritySaw = true;
            LandAct(a, what == "act" ? "seen" : "carry", w, null, ActAt(a, b), R.DrawSeenSecurity, "");
            Confirm(a, b, w);
        }

        // ---------------------------------------------------------------- reports in transit (Pulse §3.2)

        void AddRep(TdAct a, string kind, string by, Person? p, Pt place, int landAt, string phase, string stash = "")
        {
            var r = new Rep { Seq = repSeq++, Act = a.Id, Kind = kind, By = by, P = p, W = p == null ? null : WalkerOf(p), Place = place, Sev = SevOf(kind), LandAt = landAt, Phase = phase, Stash = stash };
            Reps.Add(r);
        }
        int Pending(TdAct a) { int n = 0; foreach (var r in Reps) if (r.Act == a.Id && r.Kind != "tell" && r.Phase != "stopped" && r.Phase != "landed" && r.P != null) n++; return n; } // a tell is no report: not in the cap

        /// <summary>The nearest report point by the grid walk (ties on id): the site's staffed doors and its call boxes. Returns its stand and
        /// the walk there, or null if none can be walked to.</summary>
        (string id, Pt at, Path path)? ReportPoint(Pt from)
        {
            (string id, Pt at, Path path)? best = null;
            var pts = new List<(string, Pt)>();
            foreach (var (id, at, kind) in S.Refuges) if (kind == "door") pts.Add((id, at));
            foreach (var cb in S.CallBoxes) pts.Add(cb);
            var a = S.Grid.NearestFree(from) ?? from;
            // nearest by the straight line first: a walk is never shorter than it, so once the next point's line is longer than the best
            // walk found nothing after it can win (the same choice as walking to every point, at a few A* instead of one a point)
            var order = new List<(long line, string id, Pt at, Pt b)>();
            foreach (var (id, at) in pts) { var b0 = S.Grid.NearestFree(at) ?? at; order.Add((G.Isqrt(G.D2(a, b0)) * 10, id, at, b0)); }
            order.Sort((x, y) => x.line != y.line ? x.line.CompareTo(y.line) : string.CompareOrdinal(x.id, y.id));
            foreach (var (line, id, at, b) in order)
            {
                if (best != null && line > best.Value.path.Length + 1000) break; // 1 m of slack for the integer rounding of both lengths
                var route = S.Grid.Route(a, b);
                var path = route == null ? null : new Path(route.Length >= 2 ? route : new[] { a, b });
                if (path == null) continue;
                if (best == null || path.Length < best.Value.path.Length || (path.Length == best.Value.path.Length && string.CompareOrdinal(id, best.Value.id) < 0)) best = (id, at, path);
            }
            return best;
        }

        /// <summary>A person starts a report (Pulse §3.2): staff radio from where they stand (react + postCall); anyone else walks to the
        /// nearest report point (walking for a body, running for an act or a carry) and calls (call); an Idealist first walks to the body
        /// and checks it (check). The cast stand where the mission keeps them and are timed by the same walk. At most witness.cap in transit.</summary>
        void StartReport(TdAct a, Person p, string kind, Pt from, string mode, Body? b)
        {
            if (Pending(a) >= R.ReportCap) return;
            var w = WalkerOf(p);
            int react = T(R.WitnessReactS);
            if (mode == "radio") { AddRep(a, kind, p.Id, p, ActAt(a, b), Tick + react + T(R.PostCallS), "radio"); Note("report.started", $"{Who(p)} radios it in."); return; }
            if (mode == "check" && b != null)
            {
                var to = BodyPos(b); var path = RouteOf(from, to); int speed = opSpeed;
                int arrive = Tick + react + (int)((Math.Max(0, path.Length - near * 10L) + speed - 1) / speed);
                if (w != null) { w.St = "checking"; w.At = from; w.Run = path; w.RunStart = Tick + react; w.Pace = speed; }
                var r = new Rep { Seq = repSeq++, Act = a.Id, Kind = "down", By = p.Id, P = p, W = w, Place = to, Sev = SevOf("down"), LandAt = INF, Phase = "check", PhaseUntil = arrive + T(R.BodyCheckS) };
                Reps.Add(r); Note("report.started", $"{Who(p)} goes to look."); return;
            }
            WalkToPhone(a, p, w, kind, from, mode == "run" ? R.CrowdRunSpeed : opSpeed, Tick + react, ActAt(a, b), "");
        }
        void WalkToPhone(TdAct a, Person p, Walker? w, string kind, Pt from, int pace, int start, Pt place, string stash)
        {
            var rp = ReportPoint(from);
            int walk = rp == null ? 0 : (int)((rp.Value.path.Length + pace - 1) / pace);
            int land = start + walk + T(R.CallS);
            if (w != null && rp != null) { w.St = "reporting"; w.At = from; w.Run = rp.Value.path; w.RunStart = start; w.Pace = pace; w.Refuge = rp.Value.id; }
            AddRep(a, kind, p.Id, p, place, land, "walk", stash);
            if (kind == "tell") Note("witness.to-phone", $"{Who(p)} walks to {(rp?.id ?? "a phone")} to tell someone (calls {Sim.Report.Clock(land)}).");
            else Note("report.started", $"{Who(p)} {(pace > opSpeed ? "runs" : "walks")} to {(rp?.id ?? "a phone")} to report it (lands {Sim.Report.Clock(land)}).");
        }

        /// <summary>One tick of the reports: a reporter taken down or carried drops his report; a checker who reaches the body learns its
        /// state and goes to the phone; a walker at the phone is off the street calling; a report lands at its tick (by order of landing,
        /// then of starting). By index: a finished check starts its walk to the phone as a new report (WalkToPhone adds to Reps), so the
        /// list grows inside the loop; a report added this tick is stepped this tick too, after the ones before it (brief 013 D: Waymark's
        /// "Collection was modified" at 5:34.1, an Idealist's check ending while the clerks stream out).</summary>
        void ReportsStep()
        {
            for (int i = 0; i < Reps.Count; i++)
            {
                var r = Reps[i];
                if (r.Phase == "stopped" || r.Phase == "landed") continue;
                if (r.P != null && (r.P.Down || (r.P == ValeP && ValeHeld)) && r.Kind != "woken") { r.Phase = "stopped"; if (r.Kind == "tell") Note("witness.tell-stopped", $"{Who(r.P)} never reaches the phone."); else Note("report.stopped", $"{Who(r.P)}'s report never lands."); continue; }
                if (r.Phase == "flee") // a fleeing teller phones from the refuge she reaches, if it is a staffed door; any other shelter has no phone
                {
                    var fw = r.W!;
                    if (fw.St == "startled" || fw.St == "fleeing") continue;
                    if (fw.St == "sheltered" && S.Refuges.Exists(x => x.id == fw.Refuge && x.kind == "door")) { r.Phase = "call"; r.LandAt = Tick + T(R.CallS); }
                    else { r.Phase = "stopped"; Note("witness.tell-stopped", $"{Who(r.P!)} shelters with no phone and tells no one."); }
                    continue;
                }
                if (r.Phase == "check" && Tick >= r.PhaseUntil)
                {
                    var b = BodyOf(Acts[r.Act].P);
                    bool there = b != null && b.Open && G.Within(BodyPos(b), r.Place, witnessRange);
                    string kind = there && b!.Dead ? "dead" : "down";
                    var from = PosOfWalkerNow(r.W) ?? r.Place;
                    r.Phase = "stopped"; // the check is done: the report walks on as a new one (it keeps its place in the cap)
                    WalkToPhone(Acts[r.Act], r.P!, r.W, kind, from, opSpeed, Tick, r.Place, "");
                    continue;
                }
                if (r.Phase == "walk" && r.W != null && r.W.St == "reporting" && r.W.Run != null && Tick >= r.W.RunStart && (long)(Tick - r.W.RunStart) * r.W.Pace >= r.W.Run.Length)
                { r.W.St = "calling"; r.W.At = r.W.Run.End; }
            }
            Rep? next;
            while ((next = NextLanding()) != null)
            {
                bool atPhone = next.Phase == "walk" || next.Phase == "call"; // walked to a report point and called from it (or phoned from a refuge door)
                next.Phase = "landed";
                var a = Acts[next.Act];
                var phoneAt = next.W != null ? (next.W.Run?.End ?? next.W.At) : (Pt?)null;
                if (next.W != null && (next.W.St == "calling" || next.W.St == "reporting")) Return(next.W, next.W.Run?.End ?? next.W.At);
                if (next.Kind == "tell") { Tell(a, next.P!, phoneAt ?? PosOfPerson(next.P!) ?? next.Place, true); continue; } // at the phone: a call to a tie, no report
                if (next.P != null) Remember(next.P, "reported", "", false);
                LandAct(a, next.Kind, next.By, next.P, next.Place, next.Sev, next.Stash);
                if (next.P != null && next.Kind != "woken" && next.Kind != "mark") { var from = PosOfPerson(next.P) ?? phoneAt ?? next.Place; Tell(a, next.P, from, atPhone || AtPhone(from)); }
                if (Over) return;
            }
        }
        Rep? NextLanding() { Rep? best = null; foreach (var r in Reps) if (r.Phase != "stopped" && r.Phase != "landed" && r.LandAt <= Tick && (best == null || r.LandAt < best.LandAt)) best = r; return best; }
        Pt? PosOfWalkerNow(Walker? w) => w == null ? null : CrowdPos(w);
        /// <summary>Back to their routine, at walking pace, from where they stand (the crowd's returning walk).</summary>
        void Return(Walker w, Pt from)
        {
            var home = RoutinePos(w, Tick);
            if (!home.HasValue) { w.St = ""; w.Run = null; w.Pace = 0; return; }
            w.Run = RouteOf(from, home.Value); w.RunStart = Tick; w.At = from; w.St = "returning"; w.Pace = 0;
        }

        /// <summary>A report lands at the desk (Motive §2.3; rulebook report.lands): Alert to its level (a knockout at most koAlertMax by
        /// itself), the incident's highest; the nth reported incident at least byIncident[n-1]; a seen takedown's and a woken victim's
        /// report charge the act's Trail; the response by the dial.</summary>
        void LandAct(TdAct a, string kind, string by, Person? p, Pt place, int sev, string stash)
        {
            if (!a.Kill && (kind == "down" || kind == "dead" || kind == "woken" || kind == "noise" || kind == "mark" || kind == "missing")) sev = Math.Min(sev, R.KoAlertMax);
            bool first = !a.Landed; a.Landed = true;
            int to = sev;
            if (first) { Reported++; var list = R.AlertByIncident; to = Math.Max(sev, list[Math.Min(Reported, list.Length) - 1]); }
            a.Alert = Math.Max(a.Alert, to);
            int before = Alert;
            string reporter = p != null ? Who(p) : by;
            if (first && !actOrigin.ContainsKey(a.Id)) actOrigin[a.Id] = OriginNow($"report:{kind}:{a.Victim}", "response", reporter, place, p == null ? place : (Pt?)null, place, "enforcer"); // the report that raised the response (FailCause.cs, output only)
            landingBy = reporter; landingAt = place;
            RaiseAlert(to, $"report:{kind}:{a.Victim}");
            landingBy = "";
            if ((kind == "seen" || kind == "woken") && !a.Take) ChargeAct(a); // a Take keeps its own Trail (cell.take)
            AddIncident("report", $"report:{kind}:{a.Victim}", place, p != null ? new[] { (p, PosOfPerson(p) ?? place) } : null);
            a.Scene = place;
            Note("report.landed", $"{(p != null ? Who(p) : by.Replace("camera:", "the camera "))}'s report lands: {kind} ({Who(a.P)}). Alert {Alert}.");
            // one incident, one dispatch (Aster 2026-10-16, brief 013 D: the desk sent the response again for every report of the same
            // incident). The first landed report dispatches; a later one that raises Alert tops the same dispatch up to the new Alert's
            // counts (the dial's counts, never a second set); any other later report only sends a unit already out to a new scene.
            if (first) Alarm(a, place, p, stash);
            else if (Alert > before) Alarm(a, place, p, stash, step: true);
            else CoverScene(a, place, stash, Tick + T(DialNow.DispatchS));
            HoldScene(a, kind, place); // rev 4: a found body brings the unit and holds the doors in its sight
        }

        /// <summary>The act's own Trail, once (Motive §2.3): the hit and the down a shot person costs, and the kill's.</summary>
        void ChargeAct(TdAct a)
        {
            if (a.ActTrail) return; a.ActTrail = true;
            AddTrail(R.HitTrail + R.DownTrail + (a.Kill ? R.KillTrail : 0), "takedown:" + a.How + ":" + a.Victim);
        }

        /// <summary>Telling a tie (Pulse §3.4; Aster 2026-10-16, brief 013 E1: calls are voice, GDD §01): the first tie of the kinds in
        /// witness.tells, by id, who can hear the teller now: on the street within witness.tell (face to face), or, only when the teller is
        /// at a phone (a report point: a staffed door's desk or a call box), indoors at a unit (a phone). A told entry, facts only; one hop
        /// (a told person never retells it). A told Loyal person reports it from where they are. True if someone was told.</summary>
        bool Tell(TdAct a, Person p, Pt from, bool atPhone)
        {
            if (People2 == null || !People2.Ties.TryGetValue(p.Id, out var ts)) return false;
            if (a.Told.Contains(p.Id)) return false; // one hop: what you were told you keep (rulebook memory: a told entry is never retold)
            if (IsCellPerson(p) && !IsKin(p, a.P)) return false; // a person who owes the cell passes nothing on
            var (q, kind, indoors) = TieToTell(a, ts, from, atPhone);
            if (q == null) return false;
            var facts = FactsOfWitnessed(p);
            q.Memory.Add(new Mem { Act = "told", By = p.Id, Place = q.Place, Tick = Tick, Witnessed = false, Told = string.Join("|", facts) });
            a.Noticed.Add(q.Id); a.Told.Add(q.Id);
            Note("witness.told", $"{Who(p)} tells {Who(q)} ({kind}{(indoors ? ", by phone" : "")}).");
            if (q.Temperament == "loyal" && !IsCellPerson(q))
            {
                var qw = WalkerOf(q); var qp = PosOfPerson(q);
                if (indoors) AddRep(a, "down", q.Id, q, a.Scene, Tick + T(R.CallS) + T(R.CallS), "radio"); // hears the call, then calls the desk
                else if (qp.HasValue) WalkToPhone(a, q, qw, "down", qp.Value, opSpeed, Tick + T(R.WitnessReactS), a.Scene, "");
            }
            return true;
        }
        /// <summary>The tie a teller at `from` reaches now (Tell's order): face to face on the street within witness.tell; indoors only from a phone.</summary>
        (Person? q, string kind, bool indoors) TieToTell(TdAct a, List<(string kind, string with)> ts, Pt from, bool atPhone)
        {
            foreach (var kind in R.TellTies)
            {
                var ids = new List<string>(); foreach (var (k, wid) in ts) if (k == kind) ids.Add(wid);
                ids.Sort(StringComparer.Ordinal);
                foreach (var id in ids)
                {
                    var q = PersonById(id); if (q == null || q.Down || q == a.P || a.Noticed.Contains(q.Id)) continue;
                    var qw = WalkerOf(q); var qp = PosOfPerson(q);
                    bool indoors = qw != null && Indoors(qw);
                    if (indoors ? !atPhone : !(qp.HasValue && G.Within(qp.Value, from, R.TellCm))) continue;
                    return (q, kind, indoors);
                }
            }
            return (null, "", false);
        }
        /// <summary>Whoever quiets, avoids or flees tells a tie (Pulse §3.4): face to face if one is within witness.tell, or from the phone
        /// they stand at; else, if a tie is indoors (a phone away), they go to a phone first (Aster 2026-10-16, brief 013 E1), the same walk
        /// as a report and stopped the same way (taken down before the call, nobody is told): walking from where they stand, or, fleeing,
        /// from the refuge they run to if it is a staffed door. Nobody to tell, no walk.</summary>
        void TellOrPhone(TdAct a, Person p, Walker? w, Pt from, bool fled)
        {
            bool atPhone = AtPhone(from);
            if (Tell(a, p, from, atPhone) || atPhone) return;
            if (People2 == null || !People2.Ties.TryGetValue(p.Id, out var ts) || a.Told.Contains(p.Id) || (IsCellPerson(p) && !IsKin(p, a.P))) return;
            if (TieToTell(a, ts, from, true).q == null) return; // nobody indoors to call either
            if (fled && w != null) { AddRep(a, "tell", p.Id, p, from, INF, "flee"); return; }
            WalkToPhone(a, p, w, "tell", from, opSpeed, Tick + T(R.WitnessReactS), from, "");
        }
        /// <summary>Is `at` at a phone: within near of a report point (a staffed door, a call box)?</summary>
        bool AtPhone(Pt at)
        {
            foreach (var (_, ra, kind) in S.Refuges) if (kind == "door" && G.Within(ra, at, near)) return true;
            foreach (var (_, ca) in S.CallBoxes) if (G.Within(ca, at, near)) return true;
            return false;
        }
        /// <summary>Vale is in the cell's hands (being taken, held, in the car): he calls no one.</summary>
        bool ValeHeld => Vale == ValeAt.Taking || Vale == ValeAt.WithEnforcer || Vale == ValeAt.Car;
        /// <summary>The person's routine has them inside a unit now (a stop not on the street, not beyond the sheet).</summary>
        bool Indoors(Walker w)
        {
            for (int i = 0; i < w.Place.Length; i++) if (Tick >= w.From[i] && Tick < w.To[i]) return !w.Out[i] && w.Place[i] != "beyond" && !w.Place[i].StartsWith("home", StringComparison.Ordinal);
            return false;
        }

        // ---------------------------------------------------------------- the Take, witnessed (brief 013 D; Motive rev 4 R4.2, Sky 2026-10-16)

        /// <summary>A Take at Vale's own car with its driver turned happens inside the car (Sky, rev 4): an interior, off-screen (§01), with
        /// no witness window and nothing for the pickup camera to see; onlookers see a councillor get into his official car.</summary>
        public bool TakeInCar => Driver.Turned && !Driver.Down;
        /// <summary>An accomplice of the act is never its witness (rev 4 R4.2, the first row, ahead of kin): a person turned to enable this
        /// very act. For the Take (and the escort that is its tail), the driver turned to move the pickup or blind its camera.</summary>
        bool Accomplice(TdAct a, Person p) => a.Take && p == Driver && Driver.Turned;
        TdAct? TakeActNow() { foreach (var x in Acts) if (x.Take) return x; return null; }

        /// <summary>Vale's abduction as people see it (rev 4 R4.2; rulebook witness): any Take but the one inside his own car reads as an act for
        /// its first cell.take.struggle s (Vale resists when seized): everyone within witness range on a clear line and every watcher that
        /// sees him notices a takedown, with its reactions, report chain and Alert; the rest of the Take reads as nothing. Escorted on foot
        /// (held, with the Enforcer, out of the Office), he looks wrong only to his kin (lover, family) within witness range on a clear
        /// line, or to anyone within near on a clear line, who sees the grip: a carry seen (Alert 2 on landing). One incident for the Take
        /// and its escort, opened at the first sighting: an unseen Take leaves nothing. It is no assault: the Take keeps its own Trail
        /// (cell.take.trailUnturned); witness Trail and Standing move at sight. A live pickup camera still fails a Take in the open at the
        /// order (§07, abduction-seen-camera).</summary>
        void TakeScan()
        {
            if (Over) return;
            var at = ValePos(); if (!at.HasValue) return;
            if (Vale == ValeAt.Taking)
            {
                if (TakeInCar) return;
                var e = Enforcer; if (e.Busy == null || e.Busy.Do != "take") return;
                if (Tick >= e.BusyEnd - T(R.TakeS) + T(R.TakeStruggleS)) return; // past the struggle the Take reads as nothing
                var a = TakeActNow();
                if (a == null)
                {
                    if (!ScanAct(new TdAct { P = ValeP, Take = true, At = at.Value }, at.Value, "act", null, dry: true)) return;
                    a = OpenTakeAct(at.Value);
                }
                ScanAct(a, at.Value, "act", null);
            }
            else if (Vale == ValeAt.WithEnforcer && !Enforcer.Inside)
            {
                var a = TakeActNow();
                if (a == null)
                {
                    if (!ScanEscort(new TdAct { P = ValeP, Take = true, At = at.Value }, at.Value, dry: true)) return;
                    a = OpenTakeAct(at.Value);
                }
                ScanEscort(a, at.Value);
            }
        }
        TdAct OpenTakeAct(Pt at)
        {
            var a = new TdAct { Id = Acts.Count, Victim = ValeP.Id, How = "take", P = ValeP, At = at, Scene = at, Tick = Tick, Take = true };
            Acts.Add(a);
            a.Lead = AddIncident("takedown", "take:" + ValeP.Id, at); // the reactions log it (witness.react, witness.camera, takedown.seen)
            return a;
        }
        /// <summary>The escort (rev 4 R4.2): Vale's kin within witness range, or anyone within near, on a clear line, see the grip.</summary>
        bool ScanEscort(TdAct a, Pt at, bool dry = false)
        {
            foreach (var (p, wp) in OnTheStreet())
            {
                if (p == a.P || a.Noticed.Contains(p.Id) || Accomplice(a, p)) continue;
                if (!(G.Within(wp, at, near) || (G.Within(wp, at, witnessRange) && IsKin(p, a.P))) || !Sees(wp, at)) continue;
                if (dry) return true;
                a.Noticed.Add(p.Id);
                PersonNotices(a, p, wp, "carry", null);
                if (Over) return true;
            }
            return false;
        }

        // ---------------------------------------------------------------- the bodies, a tick at a time

        void BodiesStep()
        {
            foreach (var b in Bodies.ToArray())
            {
                if (Over) return;
                var a = ActOf(b);
                if (b.Seizing) { ScanAct(a, BodyPos(b), "act", b); continue; } // the act is seen at any tick of it
                if (b.Carrier.HasValue) { ScanAct(a, BodyPos(b), "carry", b); continue; }
                if (b.FreeAt >= 0 && Tick >= b.FreeAt && b.Restrained) { b.Restrained = false; b.FreeAt = -1; Note("restrain.freed", $"{Who(b.P)} is untied."); }
                if (!b.Dead && Tick >= b.WakeAt && b.P.Down)
                {
                    if (b.Restrained) { } // awake, tied: waits for a finder
                    else if (!b.Open) { if (b.NextCallOut < 0) b.NextCallOut = Tick; } // awake in a stash: calls out
                    else { Wake(b, false); continue; }
                }
                if (!b.Open && !b.Dead && !b.Restrained && b.NextCallOut >= 0 && Tick >= b.NextCallOut && Tick >= b.WakeAt) { CallOut(b); b.NextCallOut = Tick + T(R.CallOutS); }
                if (!b.Open) { ServiceRound(b); continue; }
                if ((Tick - b.Phase) % R.BodyCheckTicks == 0) ScanAct(a, BodyPos(b), "body", b);
            }
        }

        /// <summary>A knocked-out victim wakes (Motive §3; Pulse §5): he staggers, then reports the assault whatever his temperament (a
        /// contact who owes the cell says nothing); staff radio. brought: the response brought him round (his statement, no report).</summary>
        void Wake(Body b, bool brought)
        {
            var a = ActOf(b); var p = b.P; var at = BodyPos(b);
            Bodies.Remove(b); p.Down = false; a.Woke = true;
            p.Sc[Rules.Fear] = R.Clamp(Rules.Fear, p.Sc[Rules.Fear] + 1); if (a.Aware) p.Sc[Rules.Resentment] = R.Clamp(Rules.Resentment, p.Sc[Rules.Resentment] + 1);
            if (p == GuardP) { GuardDown = false; GuardHeld = true; heldPos = at; heldFacing = S.GuardFacing; heldPhase = "woken"; GuardAwayUntil = INF; guardBackAt = Tick + T(R.StaggerS) + (brought ? 0 : T(R.PostCallS)); } // he radios, then walks back to his post
            if (p == Driver) carStoppedAt = null;
            var w = WalkerOf(p);
            if (w != null) { w.St = "woken"; w.At = at; w.Run = null; w.Pace = 0; w.Until = Tick + T(R.StaggerS); w.RunStart = Tick; }
            if (brought) { a.Statement = true; Note("victim.statement", $"{Who(p)} is brought round and gives his statement."); ChargeAct(a); if (w != null) w.Until = Tick; return; }
            Note("victim.wakes", $"{Who(p)} wakes.");
            if (IsCellPerson(p)) return; // a contact who owes the cell says nothing (Pulse §5)
            int start = Tick + T(R.StaggerS);
            if (IsStaff(p)) { AddRep(a, "woken", p.Id, p, at, start + T(R.PostCallS), "radio"); return; }
            var rp = ReportPoint(at); int walk = rp == null ? 0 : (int)((rp.Value.path.Length + opSpeed - 1) / opSpeed);
            AddRep(a, "woken", p.Id, p, at, start + walk + T(R.CallS), "walk");
            if (w != null && rp != null) { w.Run = rp.Value.path; w.Pace = opSpeed; w.Refuge = rp.Value.id; w.RunStart = start; }
        }

        /// <summary>A hidden, awake, untied victim calls out (Motive §3.3): heard within witness.scream with no line; a hearer who would report
        /// a body reports a noise from the stash (Alert noise), and its verify opens it.</summary>
        void CallOut(Body b)
        {
            var a = ActOf(b); var at = BodyPos(b);
            Note("victim.calls-out", $"A muffled voice from the {b.Stash}.");
            foreach (var (p, wp) in OnTheStreet())
            {
                if (a.Noticed.Contains(p.Id) || !G.Within(wp, at, R.ScreamCm)) continue;
                a.Noticed.Add(p.Id); Remember(p, "heard-alarm", "", false);
                string verb = Decide(a, p, "body");
                if (verb == "radio") AddRep(a, "noise", p.Id, p, at, Tick + T(R.WitnessReactS) + T(R.PostCallS), "radio", b.Stash);
                else if (verb == "report" || verb == "check") WalkToPhone(a, p, WalkerOf(p), "noise", wp, opSpeed, Tick + T(R.WitnessReactS), at, b.Stash);
            }
        }

        /// <summary>A container's round (Pulse §4.1; Sky call 9: in the mission only): every service.period, its phase from the container's
        /// id; the round robot opens it and rings the desk on a body.</summary>
        void ServiceRound(Body b)
        {
            var s = StashById(b.Stash); if (s == null || s.Kind != "container") return;
            int period = T(R.ServicePeriodS), phase = (int)(Streams.Fnv1a32(s.Id) % (uint)period);
            if ((Tick - phase) % period != 0) return;
            var a = ActOf(b);
            if (a.Noticed.Contains("round:" + s.Id)) return;
            a.Noticed.Add("round:" + s.Id);
            Note("stash.serviced", $"The round empties the {s.Id} and finds {Who(b.P)}.");
            b.Stash = ""; // out of the bin, beside it
            AddRep(a, b.Dead ? "dead" : "down", "round:" + s.Id, null, s.Stand, Tick + T(R.RobotReportS), "watcher");
        }

        // ---------------------------------------------------------------- the card

        /// <summary>The takedown card (Motive §5.4): the price, who would see it now (people with their verb, "?" until the temperament is
        /// known; watchers by the sight rule), what follows if seen, found or never found. Changes nothing.</summary>
        public TakedownQuote QuoteTakedown(string target, string how)
        {
            var q = new TakedownQuote();
            var p = PersonById(target); var e = Enforcer;
            if (p == null) { q.Refused = "no one here"; q.RefusedCode = "target-unknown"; return q; }
            if (p == ValeP && how == "knockout") { q.Refused = "Vale is taken, not knocked out: use Take"; q.RefusedCode = "takedown-vale"; }
            var at = PosOfPerson(p);
            if (!at.HasValue) { q.Refused = p.Down ? "down" : "not on the street"; q.RefusedCode = p.Down ? "person-down" : "person-away"; return q; }
            bool kill = how == "kill";
            var (aware, armed) = Awareness(p, at.Value);
            q.Armed = p == GuardP;
            bool known = p != GuardP || (Known("guard")?.Sight ?? false);
            q.Aware = known ? (aware ? "yes" : "no") : "?";
            q.IfAware = q.Armed ? "fight" : "struggle";
            q.S = (kill ? R.KillS : R.KoS) + (aware && known && !armed ? R.StruggleS : 0);
            q.Seen = SeenAt(at.Value);
            var probe = new TdAct { P = p, Kill = kill };
            foreach (var (w, wp) in OnTheStreet())
            {
                if (w == p || !G.Within(wp, at.Value, witnessRange) || !Sees(wp, at.Value)) continue;
                string verb = VerbShown(probe, w, "act");
                int land = -1;
                if (verb == "radio") land = R.WitnessReactS + R.PostCallS;
                else if (verb == "report") { var rp = ReportPoint(wp); land = R.WitnessReactS + R.CallS + (rp == null ? 0 : (int)((rp.Value.path.Length / R.CrowdRunSpeed + 9) / 10)); }
                q.People.Add((w.Id, w.Name, verb, land));
            }
            q.AlertIfSeen = Math.Max(Alert, R.AlertSeen);
            q.AlertIfFound = Math.Max(Alert, kill ? R.AlertDead : Math.Min(R.AlertDown, R.KoAlertMax));
            q.TrailIfFound = R.HitTrail + R.DownTrail + (kill ? R.KillTrail : 0); q.MenaceIfFound = kill;
            q.TrailIfMissing = kill ? R.MissingTrail : R.HitTrail + R.DownTrail;
            q.IfNeverFound = kill ? "missing" : "comes-home";
            if (!kill) q.WakesAt = Tick + T((kill ? R.KillS : R.KoS) + R.WakeS);
            if (IsStaff(p) && p.KRoutine) q.NextMark = NextMarkOf(p, Tick);
            if (kill && People2 != null && People2.Ties.TryGetValue(p.Id, out var ts)) foreach (var (k, _) in ts) if (R.CloseTies.Contains(k)) q.Ties++;
            // the response, were the body found here now by staff: the forecast landing, the level's dispatch, the officers' walk (rev 4
            // R4.1: a found body brings a unit at any Alert, from the nearest post, else the response entry; at Alert 2 the response unit)
            var lv = DialNow; int alertThen = q.AlertIfFound;
            {
                int landS = R.WitnessReactS + R.PostCallS;
                var origin = alertThen >= 2 && SecurityArrives == INF ? S.Stand(S.SecEntry) : OriginOf(at.Value, S.Posts);
                var route = S.Grid.Route(S.Grid.NearestFree(origin) ?? origin, S.Grid.NearestFree(at.Value) ?? at.Value);
                int walkS = route == null ? 0 : (int)((new Path(route).Length + secSpeed * Hz - 1) / (secSpeed * Hz));
                q.PoliceInS = landS + lv.DispatchS + walkS;
            }
            q.HoldsDoors.AddRange(DoorsInSightOf(at.Value));
            q.HoldS = alertThen >= 2 ? Math.Max(R.CheckS + R.SearchS, R.StandDownSearchS) : R.CheckS + R.SearchS;
            return q;
        }

        /// <summary>The state the hash reads: nothing at all until a takedown, a body, a report, a unit or a marked foe exists, so every run
        /// without them hashes as it always did.</summary>
        internal void HashTakedown(Hash.H h)
        {
            if (Acts.Count == 0 && Bodies.Count == 0 && Reps.Count == 0 && Units.Count == 0 && markedFoes.Count == 0 && missedMarks.Count == 0 && suspicious.Count == 0 && extraCivGuns.Count == 0) return;
            h.S("takedown");
            foreach (var a in Acts)
            {
                h.I(a.Id).S(a.Victim).S(a.How).P(a.At).P(a.Scene).I(a.Tick).Z(a.Aware).I(a.Alert).Z(a.Landed).Z(a.Witnessed).Z(a.TrailPaid).Z(a.StandingPaid).Z(a.ActTrail).Z(a.Confirmed).Z(a.SecuritySaw).Z(a.MarkMissed).Z(a.Woke).Z(a.Statement);
                foreach (var x in a.Noticed) h.S(x); h.I(-1); foreach (var x in a.Heard) h.S(x); h.I(-1); foreach (var x in a.Opened) h.S(x); h.I(-1);
                if (a.Told.Count > 0) { h.S("told"); foreach (var x in a.Told) h.S(x); h.I(-1); } // only a run with a tell adds bytes
            }
            foreach (var b in Bodies) { h.S(b.Id).I(b.Act).Z(b.Dead).Z(b.Seizing).Z(b.Restrained).P(BodyPos(b)).I(b.Carrier.HasValue ? (int)b.Carrier.Value : -1).S(b.Stash).I(b.DownTick).I(b.WakeAt).I(b.NextCallOut).I(b.FreeAt); }
            foreach (var r in Reps) h.I(r.Seq).I(r.Act).S(r.Kind).S(r.By).P(r.Place).I(r.Sev).I(r.LandAt).S(r.Phase).I(r.PhaseUntil).S(r.Stash);
            foreach (var x in markedFoes) h.S(x);
            foreach (var x in missedMarks) h.S(x);
            foreach (var kv in suspicious) h.S(kv.Key).I(kv.Value);
            foreach (var g in extraCivGuns) Hash.HashGun(h, civGuns[g]);
            foreach (var op in Ops) h.S(op.CarryBody);
            HashResponse(h);
        }
    }
}

