        static int Bounded(JNode n, long lo, long hi) { long v = n.Long(); if (v < lo || v > hi) throw new FormatException($"{n.Path} = {v} is outside {lo}..{hi}"); return (int)v; }
        static string Known<T>(Dictionary<string, T> d, string id, string what, string where) => d.ContainsKey(id) ? id : throw new FormatException($"{where}: {what} '{id}' is unknown (unknown = reject)");
        string KnownAct(JNode n) { var a = n.Str(); if (!MemoryActs.Contains(a)) throw new FormatException($"{n.Path}: memory act '{a}' is unknown"); return a; }
        static string OneOf(JNode n, string[] allowed) { var v = n.Str(); if (Array.IndexOf(allowed, v) < 0) throw new FormatException($"{n.Path} = '{v}' is not one of {string.Join(", ", allowed)}"); return v; }
        static Fit ParseFit(JNode n) => OneOf(n, Fits) switch { "suits" => Fit.Suits, "worse" => Fit.Worse, _ => Fit.Refused };
        static int[] Scales(List<string> names) { var o = new int[names.Count]; for (int i = 0; i < o.Length; i++) o[i] = ScaleIndex(names[i]); return o; }
        Weapon LoadWeapon(JNode n, string id, int pointBlankCm)
        {
            n.Only("damage", "every", "eff", "max");
            var w = new Weapon(id, RI(n["damage"]), RI(n["every"]), RI(n["eff"]) * 100, RI(n["max"]) * 100);
            if (w.Damage < 1) throw new FormatException($"{n.Path}.damage must be at least 1");
            if (!(pointBlankCm <= w.EffCm && w.EffCm <= w.MaxCm)) throw new FormatException($"{n.Path}: point blank ≤ eff ≤ max");
            return w;
        }
        public Weapon WeaponOf(string id) => id == "pistol" ? Pistol : id == "carbine" ? Carbine : throw new FormatException($"weapon '{id}' is unknown (pistol, carbine)");

        /// <summary>A shot's accuracy in per mille (rulebook weapons): the band's (point blank, effective, long; 0 beyond max), times each
        /// modifier that applies, in this order, each rounded down: moving, cover, vale, untrained. rulebook.ref.ts accuracy() is the same.</summary>
        public int Accuracy(Weapon w, long distanceCm, bool moving, bool cover, bool vale, bool untrained) => Accuracy(w, distanceCm, moving, cover ? ModCover : 1000, vale, untrained);
        /// <summary>As above, with the cover modifier given in per mille (full, partial or 1000 none: Pulse's cover points).</summary>
        public int Accuracy(Weapon w, long distanceCm, bool moving, int coverMod, bool vale, bool untrained)
        {
            if (distanceCm > w.MaxCm) return 0;
            long a = distanceCm <= PointBlankCm ? AccPoint : distanceCm <= w.EffCm ? AccEff : AccLong;
            if (moving) a = a * ModMoving / 1000;
            a = a * coverMod / 1000;
            if (vale) a = a * ModVale / 1000;
            if (untrained) a = a * ModUntrained / 1000;
            return (int)a;
        }

        int RI(JNode n) { if (n.Kind != JKind.Str) throw new FormatException($"{n.Path} is not a ref"); return (int)Num(n.Str()); }

        void ValidateEvent(Event ev)
        {
            bool interpreted = ev.Id.StartsWith("turn.", StringComparison.Ordinal) || ev.Id.StartsWith("scout.", StringComparison.Ordinal);
            bool choosesOnly = ev.Id == "investigator.question"; // the engine reads its needs and picks its outcome; its effects are the investigation's own
            if (ev.IsTurn) Known(approaches, ev.Approach, "approach", ev.Id);
            var outs = new HashSet<string>(StringComparer.Ordinal); foreach (var o in ev.Outcomes) if (!outs.Add(o.Id)) throw new FormatException($"{ev.Id}: outcome {o.Id} repeats");
            void Check(IEnumerable<Cond> cs, string part)
            {
                foreach (var c in cs)
                {
                    ValidateCond(c, ev, part, outs);
                    if (c.K == "cash-covers" && part != "needs") throw new FormatException($"{c.N.Path}: cash-covers may stand only in an event's needs");
                    if (part == "price" && (c.K == "orders-reached" || c.K == "reports" || c.K == "outcome")) throw new FormatException($"{c.N.Path}: '{c.K}' may not price a line");
                    if (c.K == "outcome" && (part == "needs" || part == "outcomes")) throw new FormatException($"{c.N.Path}: outcome stands only in also and witnesses");
                    if ((c.K == "fit" || c.K == "orders-reached") && !ev.IsTurn) throw new FormatException($"{c.N.Path}: '{c.K}' reads a Turn's approach");
                    if ((interpreted || (choosesOnly && part != "also")) && !MissionKinds.Contains(c.K)) throw new FormatException($"{c.N.Path}: '{c.K}' is not evaluated in a mission event");
                }
            }
            Check(ev.Needs, "needs");
            foreach (var l in ev.Price)
            {
                Check(l.When, "price");
                l.UsdV = l.Usd != null ? Num(l.Usd) : 0; l.SV = l.S != null ? Num(l.S) : 0; l.TrailV = l.Trail != null ? Num(l.Trail) : 0; l.OrdersV = l.Orders != null ? Num(l.Orders) : 0;
            }
            if (ev.Price.Count > 0 && ev.Price[0].Id != "base") throw new FormatException($"{ev.Id}: the first price line is the base");
            foreach (var o in ev.Outcomes) { Check(o.When, "outcomes"); foreach (var e in o.Changes) ValidateEff(e, ev, interpreted); }
            foreach (var a in ev.Also) { Check(a.When, "also"); foreach (var e in a.Changes) ValidateEff(e, ev, interpreted); }
            if (ev.Private && ev.Witnesses.Count > 0) throw new FormatException($"{ev.Id}: a private event has no witnesses (rulebook privacy)");
            foreach (var w in ev.Witnesses) { Check(w.When, "witnesses"); if (!Traceable.ContainsKey(w.Act)) throw new FormatException($"{ev.Id}: witness act '{w.Act}' is not traceable"); }
        }

        void ValidateCond(Cond c, Event? ev, string part, HashSet<string>? outs = null)
        {
            var n = c.N; string w = n.Path;
            void Bool(string k) { if (n.Has(k)) n[k].Bool(); }
            switch (c.K)
            {
                case "tier": OneOf(n["is"], new[] { "simulated", "background" }); break;
                case "turned": Bool("is"); if (n.Has("of")) OneOf(n["of"], new[] { "friend" }); break;
                case "known": OneOf(n["what"], Knows); Bool("is"); break;
                case "leverage": Known(approaches, c.S("approach"), "approach", w); break;
                case "lover-within": Num(c.S("m")); break;
                case "requires": case "need-met-by": Known(approaches, c.S("approach"), "approach", w); break;
                case "need-is": foreach (var x in c.L("in")) Known(Needs, x, "need", w); break;
                case "need-met": case "orders-reached": case "talker": case "lies": case "cell": case "called": case "exposed": case "tie-between-holds": case "fired-first": case "rivals-broken": Bool("is"); break;
                case "reach": case "within": case "public": Num(c.S("m")); if (c.K == "within") OneOf(n["sightline"], new[] { "3d" }); break;
                case "fight": Num(c.S("quiet")); break;
                case "fired-on": if (c.L("in").Count == 0) throw new FormatException($"{w}: fired-on names a foe"); foreach (var x in c.L("in")) OneOfStr(x, Foes, w); break;
                case "rivals-public": if (c.L("in").Count == 0) throw new FormatException($"{w}: rivals-public names one"); foreach (var x in c.L("in")) OneOfStr(x, RivalsPublics, w); break;
                case "memory": if (!MemoryActs.Contains(c.S("act"))) throw new FormatException($"{w}: memory act '{c.S("act")}' is unknown"); Bool("has"); if (n.Has("this")) OneOf(n["this"], new[] { "mission" }); if (n.Has("of")) OneOf(n["of"], new[] { "friend" }); break;
                case "fit": foreach (var x in c.L("is")) if (Array.IndexOf(Fits, x) < 0) throw new FormatException($"{w}: fit '{x}' is unknown"); break;
                case "temperament": foreach (var x in c.L("in")) Known(temps, x, "temperament", w); break;
                case "standing": foreach (var x in c.L("band")) if (Array.IndexOf(Bands, x) < 0) throw new FormatException($"{w}: band '{x}' is unknown"); break;
                case "outcome": foreach (var x in c.L("is")) if (outs == null || !outs.Contains(x)) throw new FormatException($"{w}: outcome '{x}' is not one of {ev?.Id}'s"); break;
                case "holds-fact": Bool("is"); if (n.Has("how")) OneOf(n["how"], new[] { "any", "witnessed" }); break;
                case "scale":
                    ScaleIndex(c.S("scale")); OneOf(n["op"], new[] { "<", "<=", "==", ">=", ">" });
                    var than = n["than"]; if (than.Kind == JKind.Str) Num(than.Str()); else { than.Only("scale"); ScaleIndex(than["scale"].Str()); }
                    break;
                case "trail": Num(c.S("atLeast")); break;
                case "tie": foreach (var x in c.L("kinds")) if (!TieKinds.Contains(x)) throw new FormatException($"{w}: tie kind '{x}' is unknown"); break;
                case "act": foreach (var x in c.L("in")) if (!Traceable.ContainsKey(x)) throw new FormatException($"{w}: act '{x}' is not traceable"); break;
                case "count": Ev(c.S("event")); Num(c.S("below")); break;
                case "done-to": foreach (var x in c.L("in")) if (Array.IndexOf(DoneTo, x) < 0) throw new FormatException($"{w}: done-to '{x}' is unknown"); break;
                case "alive": case "standing-moved": Bool("is"); break;
            }
        }

        void ValidateEff(Eff e, Event ev, bool interpreted)
        {
            var n = e.N; string w = n.Path;
            if (interpreted && !MissionEffects.Contains(e.Do)) throw new FormatException($"{w}: effect '{e.Do}' is not applied in a mission event");
            switch (e.Do)
            {
                case "charge": foreach (var x in e.L("parts")) if (x != "usd" && x != "s" && x != "trail") throw new FormatException($"{w}: charge part '{x}'"); break;
                case "move": if (!Ladders.ContainsKey(e.S("on"))) throw new FormatException($"{w}: move '{e.S("on")}' is unknown"); break;
                case "learn": foreach (var x in e.L("what")) OneOfStr(x, Knows, w); OneOf(n["of"], new[] { "subject", "needs-known", "friend" }); if (interpreted && e.S("of") != "subject") throw new FormatException($"{w}: a mission event learns of its subject"); if (e.L("what").Contains("refused") && !ev.IsTurn) throw new FormatException($"{w}: only a Turn learns a refusal"); break;
                case "forget": foreach (var x in e.L("what")) OneOfStr(x, Knows, w); break;
                case "remember": if (!MemoryActs.Contains(e.S("act"))) throw new FormatException($"{w}: memory act '{e.S("act")}' is unknown"); break;
                case "trail": Num(e.S("add")); OneOf(n["per"], new[] { "incident" }); break;
                case "standing": Num(e.S("step")); OneOf(n["per"], new[] { "incident" }); break;
                case "alert": Num(e.S("atLeast")); OneOf(n["per"], new[] { "incident" }); break;
                case "lead": OneOf(n["from"], new[] { "facts", "lie" }); break;
                case "tell": foreach (var x in e.L("along")) if (!TieKinds.Contains(x)) throw new FormatException($"{w}: tie kind '{x}' is unknown"); Num(e.S("hops")); break;
                case "replace-need": if (Book["streams"]["keys"].Opt(e.S("stream")) == null) throw new FormatException($"{w}: stream '{e.S("stream")}' is unknown"); break;
                case "schedule": OneOf(n["fight"], new[] { "ambush" }); break;
                case "debrief": if (!DebriefLines.Contains(e.S("line"))) throw new FormatException($"{w}: debrief line '{e.S("line")}' is unknown"); break;
                case "word-standing": OneOf(n["toward"], new[] { "hero", "menace" }); Num(e.S("step")); Num(e.S("cap")); break;
                case "drift-standing": Num(e.S("step")); Num(e.S("to")); break;
                case "fight-standing": OneOf(n["toward"], new[] { "hero", "menace" }); Num(e.S("step")); if (!StandingCauses.Contains(e.S("cause"))) throw new FormatException($"{w}: cause '{e.S("cause")}' is not a standing cause"); if (ev.Id != "fight.public") throw new FormatException($"{w}: fight-standing is fight.public's"); break;
            }
        }
        static void OneOfStr(string v, string[] allowed, string where) { if (Array.IndexOf(allowed, v) < 0) throw new FormatException($"{where}: '{v}' is not one of {string.Join(", ", allowed)}"); }

        void ResolveAllRefs(JNode n)
        {
            switch (n.Kind)
            {
                case JKind.Str: var s = n.Str(); if (s.Length > 2 && (s.StartsWith("v:", StringComparison.Ordinal) || s.StartsWith("p:", StringComparison.Ordinal)) && IsRef(s)) Num(s); break;
                case JKind.Arr: foreach (var x in n.Items) ResolveAllRefs(x); break;
                case JKind.Obj: foreach (var kv in n.Entries) ResolveAllRefs(kv.Value); break;
            }
        }
        static bool IsRef(string s)
        {
            for (int i = 2; i < s.Length; i++) { char c = s[i]; if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '.')) return false; }
            return true;
        }

        /// <summary>A value of the rulebook by id ("loop-s").</summary>
        public long V(string id) => values.TryGetValue(id, out var v) ? v : throw new FormatException($"rulebook has no value '{id}'");
        public int VI(string id) => (int)V(id);
        /// <summary>A v: or p: ref to its integer; every ref in the rulebook is resolved at load, so in play this is a lookup.</summary>
        public long Num(string reff)
        {
            if (refs.TryGetValue(reff, out var hit)) return hit;
            long v;
            if (reff.StartsWith("v:", StringComparison.Ordinal)) v = V(reff.Substring(2));
            else if (reff.StartsWith("p:", StringComparison.Ordinal))
            {
                JNode x = People;
                foreach (var part in reff.Substring(2).Split('.')) { var y = x.Opt(part); if (y == null) throw new FormatException($"{reff} does not resolve in people.rules.json"); x = y; }
                v = x.Long();
            }
            else throw new FormatException($"'{reff}' is not a ref");
            if (v < -1_000_000_000L || v > 1_000_000_000L) throw new FormatException($"{reff} = {v} is out of range");
            refs[reff] = v; return v;
        }

        public Event Ev(string id) => events.TryGetValue(id, out var e) ? e : throw new FormatException($"rulebook has no event '{id}'");
        public bool HasEvent(string id) => events.ContainsKey(id);
        public Temperament Temp(string id) => temps.TryGetValue(id, out var t) ? t : throw new FormatException($"temperament '{id}' is unknown (unknown = reject)");
        public bool HasTemperament(string id) => temps.ContainsKey(id);
        public Approach App(string id) => approaches.TryGetValue(id, out var a) ? a : throw new FormatException($"approach '{id}' is unknown (unknown = reject)");
        public bool HasApproach(string id) => approaches.ContainsKey(id);
        public string ApproachRequires(string a) => App(a).Requires;
        public bool NeedMetBy(string need, string approach) => Needs.TryGetValue(need, out var n) && n.MetBy.Contains(approach);
        public void CheckNeed(string need) { if (!Needs.ContainsKey(need)) throw new FormatException($"need '{need}' is unknown (unknown = reject)"); }

        public Band BandOf(int standing) => standing >= HeroAt ? Band.Hero : standing <= MenaceAt ? Band.Menace : Band.Neutral;
        public static string BandId(Band b) => b == Band.Hero ? "hero" : b == Band.Menace ? "menace" : "neutral";

        /// <summary>Sky Q4: a standing row wins, then an approach row, then respondsTo (suits) / refuses (refused) / otherwise worse.</summary>
        public Fit FitOf(string approach, string temperament, Band band)
        {
            if (fitRows.TryGetValue(BandId(band) + "/" + temperament + "/" + approach, out var f)) return f;
            if (fitApproach.TryGetValue(approach, out var a)) return a;
            var t = Temp(temperament);
            if (t.Refuses.Contains(approach)) return Fit.Refused;
            if (t.RespondsTo.Contains(approach)) return Fit.Suits;
            return Fit.Worse;
        }

        /// <summary>§04 Talker test, read from people.rules: sum(left) > sum(right).</summary>
        public bool IsTalker(int[] sc)
        {
            int l = 0, r = 0;
            foreach (var i in TalkerLeft) l += sc[i];
            foreach (var i in TalkerRight) r += sc[i];
            return l > r;
        }
        public static int ScaleIndex(string s) { int i = Array.IndexOf(ScaleNames, s); if (i < 0) throw new FormatException($"scale '{s}' is unknown"); return i; }
        public int Clamp(int scale, int v) => Math.Max(ScaleMin[scale], Math.Min(ScaleMax[scale], v));
    }

    /// <summary>One security level of the response dial (rulebook response.levels; Motive, briefs/013/motive-takedowns.md §5.3).</summary>
    public sealed class DialLevel
    {
        public int Level; public string Name = ""; public int DispatchS, A1Robots, A2Units, A2Robots, ReinforceS, UnitCap, SealS, A3Units; public bool DoorsLock;
    }

    /// <summary>A weapon (rulebook weapons.pistol, weapons.carbine): damage a hit, ticks between shots, effective and max reach in cm.</summary>
    public sealed class Weapon
    {
        public readonly string Id; public readonly int Damage, Every, EffCm, MaxCm;
        public Weapon(string id, int damage, int every, int effCm, int maxCm) { Id = id; Damage = damage; Every = every; EffCm = effCm; MaxCm = maxCm; }
    }
}

sim/Suborned.Sim/Scenarios.cs.text:
// The 28 scenarios of the top-down test (~/Projects/game-source/docs/prototypes/suborned-world-sim.test.js, sha256 c41a8d78…),
// rebased on the real civic block, the rulebook and the promoted cast (r016 since 2026-10-16), plus Suture's N-cases the engine owns. Each keeps its intent;
// its positions and times are the real block's (sim/data/handover.site.json), and every change from the prototype is said beside it.
// They live in the engine DLL so the xunit tests, the CLI and Unity (brief 011 D) run the very same code.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public sealed class Scenario
    {
        public string Id = "", Intent = "", Proto = ""; public Start Start = new Start(); public Action<Run> Body = _ => { };
    }

    /// <summary>A scenario being played: the game, and the checks it made.</summary>
    public sealed class Run
    {
        public readonly Game G; public readonly List<(bool ok, string what)> Checks = new List<(bool, string)>();
        public Run(Game g) { G = g; }
        public bool Is(bool ok, string what) { Checks.Add((ok, what)); return ok; }
        public void Eq<T>(T a, T b, string what) => Is(EqualityComparer<T>.Default.Equals(a, b), what + " (got " + Inv(a) + ", want " + Inv(b) + ")");
        static string Inv(object? v)
        {
            if (v is System.Runtime.CompilerServices.ITuple t) // a tuple's own ToString is the culture's (a negative item reads "−1" in sv-SE: Redline E7)
            {
                var parts = new string[t.Length]; for (int i = 0; i < t.Length; i++) parts[i] = Inv(t[i]);
                return "(" + string.Join(", ", parts) + ")";
            }
            return v is IFormattable f ? f.ToString(null, System.Globalization.CultureInfo.InvariantCulture) : v?.ToString() ?? "";
        }
        /// <summary>Give an order now and check it was taken.</summary>
        /// <summary>Brief 022: a player who means to speak to (or watch) a server who works her round waits until she is back at her post (the
        /// HUD's "back in n s", Game.RoundNext); a held server is already standing still. Off-round, or for anyone else, nothing waits.</summary>
        public void ForHer(string verb, string target)
        {
            if (!G.RoundsOn || (verb != "listen" && verb != "watch" && verb != "turn") || target.Length == 0) return;
            Person? p = null; foreach (var x in G.People) if (x.Role == target || x.Id == target) p = x;
            if (p == null || p.Down) return;
            var pose = G.PersonPose(p); if (pose.HasValue && pose.Value.phase == "held") return;
            int n = G.RoundNext(p); if (n > 0) G.RunTo(G.Tick + n);
        }
        public bool Do(string op, string verb, string target = "", string approach = "")
        {
            ForHer(verb, target);
            var (ok, why) = G.Issue(new Order { Tick = G.Tick, Op = op, Do = verb, Target = target, Approach = approach });
            return Is(ok, $"{op} {verb} {target} {approach} taken at {Report.Clock(G.Tick)}{(ok ? "" : ": " + why)}".Replace("  ", " "));
        }
        /// <summary>Give an order now and check it was refused.</summary>
        public bool Refused(string op, string verb, string target, string what, string approach = "")
        {
            var (ok, _) = G.Issue(new Order { Tick = G.Tick, Op = op, Do = verb, Target = target, Approach = approach });
            return Is(!ok, what);
        }
        public bool Try(string op, string verb, string target = "", string approach = "") { ForHer(verb, target); return TryNow(op, verb, target, approach); }
        bool TryNow(string op, string verb, string target, string approach) => G.Issue(new Order { Tick = G.Tick, Op = op, Do = verb, Target = target, Approach = approach }).ok;
        /// <summary>Send an operative to a place; returns the tick they arrive.</summary>
        public int Send(string op, string place, bool run = false)
        {
            var (ok, why) = G.Issue(new Order { Tick = G.Tick, Op = op, Do = "move", To = place, Run = run });
            Is(ok, $"{op} can {(run ? "run" : "walk")} to {place}{(ok ? "" : ": " + why)}");
            return Arrival(op);
        }
        public int SendTo(string op, Pt at)
        {
            var (ok, why) = G.Issue(new Order { Tick = G.Tick, Op = op, Do = "move", Point = at });
            Is(ok, $"{op} can walk to {at}{(ok ? "" : ": " + why)}");
            return Arrival(op);
        }
        public int Arrival(string op)
        {
            var o = G.OpOf(Sim.Op.Parse(op)); if (o.Walk == null) return G.Tick;
            int speed = o.WalkSpeed > 0 ? o.WalkSpeed : G.R.CellSpeed; long left = o.Walk.Length - o.WalkMm;
            return G.Tick + (int)((left + speed - 1) / speed);
        }
        public void To(int tick) => G.RunTo(tick);
        public void Wait(int ticks) => G.Advance(ticks);
        /// <summary>Run until the operative's action in progress lands.</summary>
        public void Done(string op) { var o = G.OpOf(Sim.Op.Parse(op)); if (o.Busy != null) G.RunTo(o.BusyEnd); }
        /// <summary>Give a fire order now (until the target is down); force for a civilian or a contact (the Ctrl case).</summary>
        public bool Fire(string op, string target, bool force = false)
        {
            var (ok, why) = G.Issue(new Order { Tick = G.Tick, Op = op, Do = "fire", Target = target, Force = force });
            return Is(ok, $"{op} fires on {target} at {Report.Clock(G.Tick)}{(ok ? "" : ": " + why)}");
        }
        /// <summary>Step until the condition holds, the run ends, or the limit passes; returns whether it held.</summary>
        public bool Until(Func<bool> cond, int limitTicks = 1200)
        {
            int end = G.Tick + limitTicks;
            while (!cond() && !G.Over && G.Tick < end) G.Step();
            return cond();
        }
        /// <summary>The shots in the log, in order: (tick, shooter, target, hit).</summary>
        public List<(int tick, string by, string target, bool hit)> Shots()
        {
            var l = new List<(int, string, string, bool)>();
            foreach (var x in G.Log)
            {
                if (x.Code != "shot.hit" && x.Code != "shot.miss") continue;
                var by = x.Text.Substring(0, x.Text.IndexOf(" fires on ", StringComparison.Ordinal));
                var rest = x.Text.Substring(by.Length + 10); var t = rest.Substring(0, rest.IndexOf(" at ", StringComparison.Ordinal));
                l.Add((x.Tick, by, t, x.Code == "shot.hit"));
            }
            return l;
        }
        /// <summary>The cell fights as a player would (Sky 2026-10-15 fights): each armed operative named fires on the nearest target up
        /// with a line in its weapon's reach, walks into its effective reach and stops there to shoot (walking halves the aim). Orders only,
        /// so the run replays from its log. Runs until `done`, the run ends, or the limit passes.</summary>
        public void Engage(Func<List<string>> targets, Func<bool> done, int limitS, string[] ops, bool carToEnforcer, bool advance = true)
        {
            int end = G.Tick + Game.T(limitS);
            while (!done() && !G.Over && G.Tick < end)
            {
                var ts = targets();
                foreach (var name in ops)
                {
                    var e = Op(name); var w = e.Gun.W;
                    if (e.Down || e.Inside || e.InCar || e.Busy != null || w == null) continue; // in the car: no fire, and a move would step out (brief 018)
                    string near = ""; Pt np = default; long bd = long.MaxValue;
                    foreach (var id in ts) { var at = G.PosOf(id); if (!at.HasValue || G.GunOf(id)!.Down) continue; long d = G.D2(e.Pos, at.Value); if (d < bd) { bd = d; near = id; np = at.Value; } }
                    if (near.Length == 0) { if (carToEnforcer && name == "enforcer" && e.Walk == null) G.Issue(new Order { Tick = G.Tick, Op = name, Do = "move", Point = G.S.Stand(G.S.GetawayCar) }); continue; }
                    if (name == "enforcer" && G.Vale == ValeAt.WithEnforcer) { if (e.Walk != null) G.Issue(new Order { Tick = G.Tick, Op = name, Do = "move", Point = e.Pos }); continue; } // brief 018: walking Vale he doesn't fire; he holds back while the others fight
                    bool line = G.S.Sight(e.Pos, np, G.R.Eye);
                    bool inEff = line && bd <= (long)(w.EffCm - 200) * (w.EffCm - 200);
                    bool firedOn = G.GunOf(near)!.Target == name;
                    if (e.Gun.Order.Length == 0 && line && bd <= (long)w.MaxCm * w.MaxCm && (inEff || (advance && e.Walk == null) || firedOn)) G.Issue(new Order { Tick = G.Tick, Op = name, Do = "fire", Target = near });
                    if (!advance) continue; // holding a post
                    if (!inEff)
                    {
                        var to = G.S.Grid.NearestFree(np);
                        if (to.HasValue && (e.Walk == null || !G.Within(e.Walk.End, to.Value, 200))) G.Issue(new Order { Tick = G.Tick, Op = name, Do = "move", Point = to.Value }); // re-aim the walk only when the target has moved 2 m
                    }
                    else if (e.Walk != null) G.Issue(new Order { Tick = G.Tick, Op = name, Do = "move", Point = e.Pos }); // in reach: stand and shoot
                }
                G.Step();
            }
        }
        /// <summary>The city's gunmen up on the street: the response unit's officers, a chasing patrol, drawn rivals.</summary>
        public List<string> CityGunmen()
        {
            var ids = new List<string>(); foreach (var s in G.SecGuns) ids.Add(s.Id);
            if (G.PatrolChasing && !G.PatrolDown) ids.Add("patrol");
            if (G.RivalsDrawn && G.RivalsPresent) ids.Add("rivals");
            return ids;
        }
        /// <summary>Hold posts and fire on the city's gunmen once they come into effective reach (or fire on the operative).</summary>
        public void FightOff(Func<bool> done, int limitS, params string[] ops) => Engage(CityGunmen, done, limitS, ops, false, false);
        /// <summary>The final fight: fight the hostiles (and the city's gunmen) until the car is free, walk the Enforcer to it, and fight
        /// again if a hostile comes back within hold of the car on the way.</summary>
        public void FightItOut(int limitS = 120, params string[] with) => FightItOut(false, limitS, with);
        /// <summary>Fight it out (brief 018 §5): until the fight is over (the crew broken or every hostile down), not only until the car is free.</summary>
        public void FightItOutAll(int limitS = 120, params string[] with) => FightItOut(true, limitS, with);
        void FightItOut(bool all, int limitS, string[] with)
        {
            Func<bool> free = all ? () => !G.CarHeld() && G.FightOverTick != int.MaxValue / 4 : () => !G.CarHeld();
            var ops = new List<string> { "enforcer" }; ops.AddRange(with);
            int end = G.Tick + Game.T(limitS); var car = G.S.At(G.S.GetawayCar);
            while (!G.Over && G.Tick < end)
            {
                Engage(() => { var l = new List<string>(); foreach (var h in G.Hostiles) if (h.Present && !h.Down) l.Add(h.Id); l.AddRange(CityGunmen()); return l; },
                       free, Math.Max(1, (end - G.Tick) / Game.Hz), ops.ToArray(), true);
                if (G.Over || G.Tick >= end) return;
                // the fight is over: the engine ends the fire orders still open on the broken crew (rulebook fight.over, Motive 2026-10-19),
                // so the helper calls nothing off (the cease it gave here before 0.8.2 is gone; N95 holds without it)
                if (!G.Within(Op("enforcer").Pos, car, G.R.AtReachCm))
                {
                    int at = SendTo("enforcer", G.S.Stand(G.S.GetawayCar));
                    while (!G.Over && G.Tick < at && free()) G.Step();
                }
                if (free() && G.Within(Op("enforcer").Pos, car, G.R.AtReachCm)) return;
            }
        }
        /// <summary>The getaway (brief 018): each named operative walks to the car if it isn't at it and boards (the Enforcer first, carrying
        /// Vale), then Go once the car is free. Checks each order was taken; returns Go's answer. Anyone not named stays out (left behind).</summary>
        public Answer GetAway(params string[] ops)
        {
            var car = G.S.At(G.S.GetawayCar);
            foreach (var name in ops)
            {
                if (G.Over) break;
                var o = Op(name); if (o.Down || o.InCar) continue;
                if (!G.Within(o.Pos, car, G.R.AtReachCm)) { int at = SendTo(name, G.S.Stand(G.S.GetawayCar)); while (!G.Over && G.Tick < at) G.Step(); }
                if (G.Over) break;
                Do(name, "board", "car"); Done(name); if (!G.Over) G.Step();
            }
            if (G.Over) return default;
            var a = G.Issue(new Order { Tick = G.Tick, Op = "cell", Do = "go" });
            Is(a.ok, $"go taken at {Report.Clock(G.Tick)}{(a.ok ? "" : ": " + a.why)}");
            return a;
        }
        /// <summary>The Enforcer boards with Vale and the car goes (brief 018: Extract retired into Board and Go).</summary>
        public Answer Extract() => GetAway("enforcer");
        /// <summary>A takedown order now (brief 013): knockout or kill, on a person's role or id; checks it was taken.</summary>
        public bool Takedown(string target, string how)
        {
            var a = G.Issue(new Order { Tick = G.Tick, Op = "enforcer", Do = "takedown", Target = target, How = how });
            return Is(a.ok, $"enforcer takedown ({how}) {target} taken at {Report.Clock(G.Tick)}{(a.ok ? "" : ": " + a.why)}");
        }
        /// <summary>A body order now (carry, drop, stash, restrain) by an operative; checks it was taken.</summary>
        public bool Body(string op, string verb, string target = "")
        {
            var a = G.Issue(new Order { Tick = G.Tick, Op = op, Do = verb, Target = target });
            return Is(a.ok, $"{op} {verb} {target} taken at {Report.Clock(G.Tick)}{(a.ok ? "" : ": " + a.why)}".Replace("  ", " "));
        }
        public Pt At(string place) => G.S.At(place);
        public Pt Stand(string place) => G.S.Stand(place);
        public Op Op(string op) => G.OpOf(Sim.Op.Parse(op));
    }

    public static partial class Scenarios
    {
        static List<Scenario>? all;
        public static List<Scenario> All { get { if (all == null) { all = new List<Scenario>(); Handover(); } return all; } }
        public static Scenario? Find(string id) { foreach (var s in All) if (string.Equals(s.Id, id, StringComparison.OrdinalIgnoreCase)) return s; return null; }
        public static Run Run(Engine.Inputs i, Scenario s)
        {
            var r = new Run(Engine.New(i, s.Start));
            s.Body(r);
            r.G.Finish();
            return r;
        }
        static Scenario Add(string id, string proto, string intent, Action<Run> body, Start? start = null)
        {
            var s = new Scenario { Id = id, Proto = proto, Intent = intent, Body = body, Start = start ?? new Start() };
            // The 28 are the top-down test's: it had no final fight and no crowd. N10, N11 and N12 test those; the 28 keep their own world.
            // Brief 013: they also keep the top-down test's response, security level 1 (routine: today's dispatch and seal, no robots at Alert 2);
            // the mission's own level (the civic district's 2) is the N cases' and the route scripts'.
            if (id.StartsWith("S", StringComparison.Ordinal)) { s.Start.FinalFight = false; s.Start.Crowd = false; s.Start.Security ??= 1; }
            all!.Add(s); return s;
        }
        static int T(int s) => Game.T(s);
    }
}

sim/Suborned.Sim/ScenariosCancel.cs.text:
// Cancel and the activity read (Sky 2026-10-15 playtest: "there's nothing showing me what the cell player is doing when they're busy,
// nor is there a way to cancel their action"): each verb cancelled mid-way, at the rulebook cancel line's cost. Each scenario also runs
// twice and replays from its orders (the Theory tests), and checks the state it touches before and after.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        static void CancelCases()
        {
            Add("N27", "—", "Cancel a run and a walk: the operative stops where they stand; nothing to cancel when idle.", r =>
            {
                var g = r.G;
                r.Refused(Scout, "cancel", "", "idle: nothing to cancel");
                r.Send(Scout, "d:Courtyard", run: true); r.Wait(T(3));
                var a = g.ActivityOf(OpId.Scout);
                r.Is(a.Verb == "move" && a.Phase == "running" && a.CanCancel && a.CancelCost == "stop" && a.TicksLeft > 0 && a.Progress > 0 && a.Progress < 1000, $"running: {a.Phase} {a.Progress}‰, {a.TicksLeft} ticks left");
                r.Do(Scout, "cancel");
                var at = r.Op(Scout).Pos; r.Wait(T(2));
                r.Eq(r.Op(Scout).Pos, at, "stopped where they stood");
                r.Is(!r.Op(Scout).Running && g.ActivityOf(OpId.Scout).Phase == "idle", "and idle");
                r.Send(Fixer, "d:Courtyard"); r.Wait(T(3)); r.Do(Fixer, "cancel");
                r.Is(r.Op(Fixer).Walk == null, "a walk stops the same way");
            });

            Add("N28", "—", "Cancel Watch and Listen part-done: the time is spent, nothing is learned (the person's state is as before), and the act can be given again.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard"));
                ulong before = Hash.Person(g.Inez);
                r.Do(Scout, "watch", Inez); r.Wait(T(10));
                var a = g.ActivityOf(OpId.Scout);
                r.Eq((a.Verb, a.Phase, a.Target, a.OnDone), ("watch", "acting", Inez, "learns the routine"), "the HUD reads Watch on Inez");
                r.Eq(a.Progress, 500, "halfway through 20 s: 500 ‰");
                r.Eq(a.TicksLeft, T(10), "10 s left");
                r.Eq(a.CancelCost, "lost", "cancel: lost");
                r.Do(Scout, "cancel"); r.Wait(T(15));
                r.Eq(Hash.Person(g.Inez), before, "nothing learned: Inez's state hashes as before");
                r.Is(!g.Inez.KRoutine, "the routine is not known");
                r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.Is(g.Inez.KRoutine, "watched again in full, it lands");
                r.To(r.Send(Scout, "beside-inez"));
                before = Hash.Person(g.Inez);
                r.Do(Scout, "listen", Inez); r.Wait(T(20)); r.Do(Scout, "cancel"); r.Wait(T(30));
                r.Eq(Hash.Person(g.Inez), before, "a Listen cancelled learns nothing either");
            });

            var help = new Start(); help.Known[Inez] = new List<string> { "routine", "need", "temperament" };
            Add("N29", "—", "Cancel an approach mid-conversation (rulebook cancel.turn aborted): the money held comes back, no Trail, and Inez remembers an aborted approach with the Fixer's face; it is no refusal, so Help can be given again, and given as often as the card asks it turns her.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard"));
                long cash = g.Cash; int trail = g.Trail;
                var q = g.Preview("help", Inez); // the card's outcome is the cast's: turned (an Idealist), not yet (a Fearful Inez's first of two)
                r.Do(Fixer, "turn", Inez, "help");
                r.Is(g.Cash < cash, "the price is held at the order");
                r.Wait(T(20));
                var a = g.ActivityOf(OpId.Fixer);
                r.Eq((a.Verb, a.OnDone, a.CancelCost), ("turn", q.Outcome, "aborted"), "the HUD reads the approach, the card's outcome and the cancel's cost");
                r.Do(Fixer, "cancel");
                r.Eq(g.Cash, cash, "the money comes back");
                r.Eq(g.Trail, trail, "no Trail");
                r.Is(g.Inez.Has("aborted") && !g.Inez.Has("refusal") && !g.Inez.Turned, "she remembers an aborted approach, not a refusal");
                r.Is(g.HoldsFace(g.Inez), "with the Fixer's face");
                r.Is(r.Try(Fixer, "turn", Inez, "help"), "no refusal: Help can be given again"); r.Done(Fixer);
                HelpUntilTurned(r, Inez);
                r.Is(g.Inez.Turned, "Help again turns her");
            }, help);

            Add("N30", "—", "Cancel a Loop: part-done, nothing lands and no Trail; held, the loop ends and the camera comes back.", r =>
            {
                var g = r.G;
                r.To(r.Send(Tech, "cabinet"));
                int trail = g.Trail;
                r.Do(Tech, "loop", "entrance"); r.Wait(T(30)); r.Do(Tech, "cancel");
                r.Wait(T(40));
                r.Is(!g.LoopOn && g.Trail == trail, "part-done: no loop, no Trail");
                r.Do(Tech, "loop", "entrance"); r.Done(Tech);
                r.Is(!g.CameraWatching("entrance", r.Stand("d:Office entrance")), "looped in full, the camera is blind");
                var a = g.ActivityOf(OpId.Tech);
                r.Eq((a.Verb, a.Phase, a.CancelCost), ("loop", "holding", "ends"), "the HUD reads the loop held");
                r.Do(Tech, "cancel");
                r.Is(!g.LoopOn && g.CameraWatching("entrance", r.Stand("d:Office entrance")), "cancelled, the camera comes back");
            });

            Add("N31", "—", "Cancel Reroute and Mislead part-done: the patrol keeps its sweep and the rivals stay; no Trail.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, new Pt(8250, -3100))));
                int trail = g.Trail;
                r.Do(Tech, "reroute", "patrol"); r.Wait(T(20)); r.Do(Tech, "cancel"); r.Wait(T(30));
                r.Is(g.PatrolAwayUntil <= g.Tick && g.Trail == trail, "the patrol keeps its sweep; no Trail");
                r.To(g.RivalAt);
                r.Do(Scout, "mislead", "rivals"); r.Wait(T(20)); r.Do(Scout, "cancel"); r.Wait(T(30));
                r.Is(g.RivalsPresent && g.RivalsDelayedUntil == 0 && g.Trail == trail, "the rivals stay; no Trail");
            });

            Add("N32", "—", "Cancel Enter (rulebook cancel.enter staff-report): the Enforcer comes back out at the public door without Vale; the staff report the intruder, one reported incident.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Scout, "d:Courtyard"), r.Send(Tech, "cabinet")));
                r.Do(Scout, "watch", Inez); r.Do(Tech, "loop", "entrance"); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez);
                r.Send(Fixer, "d:Courtyard"); r.SendTo(Enf, new Pt(4900, -1700));
                r.Done(Scout); HelpUntilTurned(r, Inez);
                while (!g.SweepSeesEntrance(g.Tick)) g.Step();
                r.Do(Fixer, "call", Inez);
                r.To(r.Send(Enf, "d:Office entrance"));
                while (g.PatrolWatching(r.At("d:Office entrance"))) g.Step();
                r.Do(Enf, "enter"); r.Wait(T(10));
                var a = g.ActivityOf(OpId.Enforcer);
                r.Eq((a.Verb, a.CancelCost), ("enter", "staff-report"), "the HUD reads Enter and the cancel's cost");
                int reported = g.Reported;
                r.Do(Enf, "cancel");
                r.Is(!r.Op(Enf).Inside && r.Op(Enf).Pos == r.Stand("d:Office entrance"), "back out at the public door");
                r.Is(g.Vale == ValeAt.Office && !g.EntryInProgress, "without Vale");
                r.Eq(g.Reported, reported + 1, "the staff report the intruder");
                r.Eq(g.Alert, 1, "one reported incident: Alert 1");
            });

            var drv = Turned(Driver); drv.Known[Driver] = new List<string> { "routine", "need", "temperament" };
            Add("N33", "—", "Cancel Take (rulebook cancel.take vale-reports): Vale is let go at his car and reports it; the Enforcer can take him again; holding Vale is no cancel.", r =>
            {
                var g = r.G;
                r.Send(Enf, "d:Service lane");
                r.To(r.SendTo(Scout, new Pt(8250, -3100))); r.To(T(320)); r.Do(Scout, "mislead", "rivals");
                r.To(T(370));
                r.Do(Enf, "take"); r.Wait(T(10));
                r.Eq(g.ActivityOf(OpId.Enforcer).CancelCost, "vale-reports", "the HUD reads the cost");
                r.Do(Enf, "cancel");
                r.Eq(g.Vale, ValeAt.Pickup, "Vale is let go at his car");
                r.Eq(g.Alert, 1, "he reports it: Alert 1");
                r.Is(!g.Acts.Exists(x => x.Take), "the Take was inside his car (the driver turned, rev 4): nobody saw it, so his report is the one incident");
                r.Is(g.ValeP.Has("aborted"), "and remembers it: a lead for the investigators (Motive addendum Q4)");
                r.Do(Enf, "take"); r.Done(Enf);
                r.Eq(g.Vale, ValeAt.WithEnforcer, "taken again");
                var a = g.ActivityOf(OpId.Enforcer);
                r.Is(!a.CanCancel && a.CancelCost == "keeps-vale", "holding Vale: putting him down is no cancel");
                r.Refused(Enf, "cancel", "", "the cancel is refused");
            }, drv);

            Add("N34", "—", "Cancel a carry: lifting part-done, nothing is lifted; carrying, the downed operative is laid down where the carrier stands.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r))));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Scout, "draw"); g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "stance", Stance = "hold" });
                r.Send(Fixer, "d:Office approach");
                r.Is(r.Until(() => r.Op(Scout).Down, T(30)), "the Scout is down");
                r.To(r.SendTo(Fixer, r.Op(Scout).Pos));
                r.Do(Fixer, "carry", Scout); r.Wait(T(1)); r.Do(Fixer, "cancel"); r.Wait(T(5));
                r.Is(!r.Op(Fixer).Carrying.HasValue && !r.Op(Scout).CarriedBy.HasValue, "lifting cancelled: nothing lifted");
                r.Do(Fixer, "carry", Scout); r.Done(Fixer);
                r.Send(Fixer, "d:Courtyard"); r.Wait(T(3));
                r.Eq(g.ActivityOf(OpId.Fixer).Phase, "walking", "carrying, he walks");
                r.Do(Fixer, "cancel"); // a cancel stops the walk first
                r.Eq(g.ActivityOf(OpId.Fixer).CancelCost, "put-down", "standing, the HUD offers to lay him down");
                r.Do(Fixer, "cancel");
                var at = r.Op(Fixer).Pos;
                r.Is(!r.Op(Fixer).Carrying.HasValue && r.Op(Scout).Pos == at, "laid down where the Fixer stands");
                r.Send(Fixer, "d:Office approach"); r.Wait(T(3));
                r.Eq(r.Op(Scout).Pos, at, "and stays there");
            });

            Add("N35", "—", "Cancel a draw and a fire order: a draw not yet done goes back; a fire order ceases before the first shot, the weapon stays drawn.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "loop", "entrance"); r.Done(Tech); r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Enf, "draw"); r.Wait(5);
                r.Eq(g.ActivityOf(OpId.Enforcer).Phase, "drawing", "the HUD reads the draw");
                r.Do(Enf, "cancel");
                r.Is(!r.Op(Enf).Gun.Drawn, "the weapon goes back");
                r.Fire(Enf, GuardR); r.Wait(T(1) + 5);
                var a = g.ActivityOf(OpId.Enforcer);
                r.Is(a.Verb == "fire" && a.Phase == "firing" && a.Target == GuardR && a.TicksLeft > 0, $"the HUD reads the fire order, next shot in {a.TicksLeft} ticks");
                r.Do(Enf, "cancel"); r.Wait(T(5));
                r.Eq(g.Gunfire, 0, "no shot fired");
                r.Is(r.Op(Enf).Gun.Drawn && r.Op(Enf).Gun.Order == "", "ceased, the weapon stays drawn");
                r.Eq(g.GuardHealth, g.R.HealthGuard, "the guard is untouched");
            });
        }
    }
}

sim/Suborned.Sim/ScenariosDrive.cs.text:
// The driven agent (brief 025 playground, EXPERIMENTAL; rulebook cell.drive; engine 0.9.0). Each scenario drives an operative by drive samples
// as a host would (one a tick, where its controller has the agent), and checks what the engine keeps. The suite replays every one of them
// from its start state and order log (the samples are orders), so "the samples replay exactly" is checked for each.
//  D01 a straight walk: samples a walk's pace apart are taken whole; the agent is where the host put it; nothing corrected
//  D02 the pace budget: samples a metre ahead each tick move the agent at its walk (two ticks' burst at most, plus slack), flagged corrected
//  D03 a teleport: a sample 50 m away moves the agent one burst, no more
//  D04 a wall: pushed diagonally into a straight wall, the agent never enters a blocked cell and slides along it
//  D05 a corner: two blocked cells meeting at a corner: a diagonal push never passes between them
//  D06 one run, one notice: a run zig-zagging in sight of the guard is one span (run.seen once, Alert 1); after a walk sample a new span
//  D07 the tether and the loop: the Tech holding the loop asks to run and walks (a run is refused while tethered); driven 2 m off, the loop ends
//  D08 walking Vale: the Enforcer with Vale asks to run and walks at his walk; Vale stays at his side
//  D09 a busy agent: pushing the Scout mid-Watch past busyPush cancels the Watch at its cost (lost); under onBusy hold she stands until it lands
//  D10 release and the click: control ends with a click move; released, the agent stands (onRelease stand) or walks on (resume)
//  D11 the gap: driven straight at the guard, the agent stops short of 40 cm and slides past; with the playground's gap 0 it walks through
//  D12 unknown = reject: a gait the rulebook doesn't name, a facing out of range, release or face on another verb are format errors; a sample
//      with no position, in the car, or down is refused; a playground pace doubles every cap
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        static bool Sample(Run r, string op, Pt at, bool run = false, int face = 0)
        {
            var g = r.G; var a = g.Issue(g.DriveSample(Sim.Op.Parse(op), at, run, face));
            return a.ok;
        }
        /// <summary>Drive `ticks` ticks: each tick a sample `v` cm on from where the engine has the agent (a host whose controller is pulled back).</summary>
        static int Push(Run r, string op, Pt v, int ticks, bool run = false)
        {
            int taken = 0;
            for (int k = 0; k < ticks && !r.G.Over; k++) { var p = r.Op(op).Pos; if (Sample(r, op, new Pt(p.X + v.X, p.Y + v.Y), run, Heading(v))) taken++; r.G.Step(); }
            return taken;
        }
        static int Heading(Pt v) => (int)((Math.Atan2(v.Y, v.X) * 180 / Math.PI + 360) % 360); // a scenario's facing only (never read by a rule)
        static bool OnFree(Run r, string op) => r.G.S.Grid.Free(r.Op(op).Pos);
        /// <summary>The first free cell (ring search from `near`) whose +x neighbour is blocked along three rows, with free ground behind and beside it.</summary>
        static Pt? WallEast(Grid gr, Pt near)
        {
            int ci = gr.CI(near.X), cj = gr.CJ(near.Y);
            for (int rr = 0; rr < 120; rr++)
                for (int i = ci - rr; i <= ci + rr; i++) for (int j = cj - rr; j <= cj + rr; j++)
                {
                    if (Math.Max(Math.Abs(i - ci), Math.Abs(j - cj)) != rr) continue;
                    bool ok = true;
                    for (int k = -1; k <= 6 && ok; k++) ok = gr.FreeCell(i, j + k) && gr.FreeCell(i - 1, j + k) && !gr.FreeCell(i + 1, j + k);
                    if (ok) return gr.Centre(i, j);
                }
            return null;
        }
        /// <summary>A free cell whose +x and +y neighbours are blocked and whose diagonal +x+y is free: a corner a diagonal step could slip through.</summary>
        static (Pt at, Pt beyond)? Corner(Grid gr, Pt near)
        {
            int ci = gr.CI(near.X), cj = gr.CJ(near.Y);
            for (int rr = 0; rr < 160; rr++)
                for (int i = ci - rr; i <= ci + rr; i++) for (int j = cj - rr; j <= cj + rr; j++)
                {
                    if (Math.Max(Math.Abs(i - ci), Math.Abs(j - cj)) != rr) continue;
                    if (gr.FreeCell(i, j) && !gr.FreeCell(i + 1, j) && !gr.FreeCell(i, j + 1) && gr.FreeCell(i + 1, j + 1) && gr.FreeCell(i - 1, j) && gr.FreeCell(i, j - 1))
                        return (gr.Centre(i, j), gr.Centre(i + 1, j + 1));
                }
            return null;
        }
        static int WalkCm(Run r) => r.G.R.CellSpeed / 10;    // cm a tick at a walk (cell.speed, mm a tick)
        static int RunCm(Run r) => r.G.R.RunSpeed / 10;

        static void DriveCases()
        {
            Add("D01", "—", "A straight walk (brief 025, EXPERIMENTAL): the Scout driven 5 s along open ground, a walk's pace apart: every sample taken whole, the agent exactly where the host put her, nothing corrected; the samples are orders in the log.", r =>
            {
                var g = r.G; var start = r.Op(Scout).Pos; int v = WalkCm(r);
                int taken = Push(r, Scout, new Pt(0, -v), T(5));
                r.Eq(taken, T(5), "every sample taken");
                r.Eq(r.Op(Scout).Pos, new Pt(start.X, start.Y - v * T(5)), "where the host put her");
                var pose = g.DrivePoseOf(OpId.Scout);
                r.Is(pose.Driven && pose.Corrections == 0 && !pose.Corrected, $"driven, nothing corrected ({pose.Corrections})");
                r.Eq(g.Orders.Count(o => o.order.Do == "drive"), T(5), "the samples are in the order log");
                r.Eq(g.ActivityOf(OpId.Scout).Phase, "driven", "the HUD's activity: driven");
            }, DriveStart());

            Add("D02", "—", "The pace budget: samples a metre ahead of the Scout each tick. She moves at most two ticks' walk plus slack in the first tick and a walk a tick after (cell.drive.burst, slack): 5 s covers a walk's 7 m, not 50, and each sample is flagged corrected.", r =>
            {
                var g = r.G; var start = r.Op(Scout).Pos; int v = WalkCm(r), slack = g.R.Drive!.SlackCm;
                Sample(r, Scout, new Pt(start.X, start.Y - 100)); g.Step();
                int first = start.Y - r.Op(Scout).Pos.Y;
                r.Is(first <= 2 * v + slack && first >= v, $"the first tick: {first} cm (a walk {v}, burst {2 * v}, slack {slack})");
                Push(r, Scout, new Pt(0, -100), T(5) - 1);
                int went = start.Y - r.Op(Scout).Pos.Y;
                r.Is(went <= v * T(5) + v + slack + 1 && went >= v * T(5) - v, $"5 s at a walk: {went} cm (a walk's {v * T(5)}; one tick's burst and the slack at most over it)");
                r.Is(g.DrivePoseOf(OpId.Scout).Corrections >= T(5) - 1, "each sample corrected");
                r.Is(OnFree(r, Scout), "on free ground");
            }, DriveStart());

            Add("D03", "—", "A teleport: one sample 50 m away. The Scout moves one burst (two ticks' walk plus slack), and the host reads where she is.", r =>
            {
                var g = r.G; var start = r.Op(Scout).Pos; int v = WalkCm(r), slack = g.R.Drive!.SlackCm;
                Sample(r, Scout, new Pt(start.X, start.Y - 5000)); g.Step();
                int d = G.Dist(start, r.Op(Scout).Pos);
                r.Is(d > 0 && d <= 2 * v + slack, $"{d} cm, not 50 m");
                var pose = g.DrivePoseOf(OpId.Scout);
                r.Is(pose.Corrected && pose.Pos == r.Op(Scout).Pos, "the host reads the corrected pose");
            }, DriveStart());

            Add("D04", "—", "A wall: the Scout walked (a click) to the nearest straight wall to her east, then driven diagonally into it (east and along) for 4 s. She never stands on a blocked cell or past the wall's face, and slides along it at the along part of her pace.", r =>
            {
                var g = r.G; var gr = g.S.Grid;
                var w = WallEast(gr, r.Op(Scout).Pos);
                r.Is(w.HasValue, "a straight wall near the Scout");
                if (!w.HasValue) return;
                r.To(r.SendTo(Scout, w.Value));
                int face = gr.X0 + (gr.CI(w.Value.X) + 1) * gr.Cell; // the wall's west face (cm)
                int y0 = r.Op(Scout).Pos.Y, v = WalkCm(r), worstX = int.MinValue; bool free = true;
                for (int k = 0; k < T(4); k++)
                {
                    var p = r.Op(Scout).Pos; Sample(r, Scout, new Pt(p.X + v, p.Y + v / 2)); g.Step();
                    worstX = Math.Max(worstX, r.Op(Scout).Pos.X); free &= OnFree(r, Scout);
                }
                r.Is(free && worstX < face, $"never on a blocked cell, never past the face (x at most {worstX.ToString(System.Globalization.CultureInfo.InvariantCulture)}, face {face.ToString(System.Globalization.CultureInfo.InvariantCulture)})");
                r.Is(r.Op(Scout).Pos.Y - y0 >= v / 2 * T(3), $"slides along it: {r.Op(Scout).Pos.Y - y0} cm");
            }, DriveStart());

            Add("D05", "—", "A corner: a free cell whose east and south neighbours are blocked and whose diagonal is free. Driven straight at the diagonal for 2 s, the Scout never passes between the two blocked cells: she stays in her cell or slides out by a free side, never into the diagonal by the corner.", r =>
            {
                var g = r.G; var gr = g.S.Grid;
                var c = Corner(gr, r.Op(Scout).Pos);
                r.Is(c.HasValue, "such a corner on the block");
                if (!c.HasValue) return;
                r.To(r.SendTo(Scout, c.Value.at));
                int ci = gr.CI(c.Value.at.X), cj = gr.CJ(c.Value.at.Y); bool through = false, free = true;
                for (int k = 0; k < T(2); k++)
                {
                    Sample(r, Scout, c.Value.beyond); g.Step();
                    var p = r.Op(Scout).Pos; free &= gr.Free(p);
                    if (gr.CI(p.X) == ci + 1 && gr.CJ(p.Y) == cj + 1) through = true;
                }
                r.Is(free && !through, "never through the corner");
            }, DriveStart());

            Add("D06", "—", "One run, one notice (cell.drive: a run is a span): the Scout clicked to the guard's forecourt, then run zig-zagging in his sight for 4 s with Shift held throughout: one span, so run.seen once (Alert 1) however the heading turns. A walk sample ends the span; running again is a new span, noticed again.", r =>
            {
                var g = r.G; int v = RunCm(r);
                r.To(r.SendTo(Scout, r.Stand("d:Office approach")));
                for (int k = 0; k < T(4); k++) Push(r, Scout, (k / 5) % 2 == 0 ? new Pt(v, v / 3) : new Pt(-v, v / 3), 1, run: true);
                int seen = g.Log.Count(l => l.Code == "run.seen");
                r.Eq((seen, g.Alert), (1, 1), "one span: noticed once, Alert 1");
                r.Is(r.Op(Scout).RunSeen.Count >= 1, $"the people who saw her remember the run once each ({r.Op(Scout).RunSeen.Count})");
                Push(r, Scout, new Pt(0, WalkCm(r)), 3); // a walk: the span ends
                for (int k = 0; k < T(2); k++) Push(r, Scout, new Pt(0, -v), 1, run: true);
                r.Eq(g.Log.Count(l => l.Code == "run.seen"), 2, "a new span is noticed again");
            }, DriveStart());

            Add("D07", "—", "The tether: the Tech runs (a click) to the cabinet and loops the entrance camera. Driven with Shift held she walks (a run is refused while she holds the loop, as a move's run is); 2 m off the cabinet the loop ends (loop.ends).", r =>
            {
                var g = r.G;
                r.To(r.Send(Tech, "cabinet", run: true)); r.Do(Tech, "loop", "entrance"); r.Done(Tech);
                r.Is(g.LoopOn, "the loop holds");
                var from = r.Op(Tech).Pos; var away = g.S.Grid.Route(from, r.Stand("d:Courtyard"))!; var dir = away[1] - away[0];
                int len = Math.Max(1, G.Dist(away[0], away[1])), v = RunCm(r); var step = new Pt(dir.X * v / len, dir.Y * v / len);
                Push(r, Tech, step, 1, run: true);
                int went = G.Dist(from, r.Op(Tech).Pos);
                r.Is(went <= 2 * WalkCm(r) + g.R.Drive!.SlackCm && !r.Op(Tech).Running, $"tethered, she walks: {went} cm, not running");
                for (int k = 0; k < T(5) && g.LoopOn; k++) Push(r, Tech, step, 1, run: true);
                r.Is(!g.LoopOn && g.Log.Exists(l => l.Code == "loop.ends"), $"off the cabinet the loop ends ({G.Dist(r.Op(Tech).Pos, g.S.At("cabinet"))} cm off)");
            }, DriveStart());

            Add("D08", "—", "Walking Vale: route A to the Take; the Enforcer driven with Shift held walks at his walk (nobody runs carrying Vale), and Vale stays at his side.", r =>
            {
                var g = r.G;
                RouteA(r, reroute: true);
                r.Eq(g.Vale, ValeAt.WithEnforcer, "Vale is with the Enforcer");
                var from = r.Op(Enf).Pos; var to = g.S.Grid.Route(from, r.Stand("d:Getaway bay"))!; var dir = to[1] - to[0];
                int len = Math.Max(1, G.Dist(to[0], to[1])), v = RunCm(r);
                Push(r, Enf, new Pt(dir.X * v / len, dir.Y * v / len), T(2), run: true);
                int went = G.Dist(from, r.Op(Enf).Pos), walk = WalkCm(r) * T(2) + WalkCm(r) + g.R.Drive!.SlackCm + 1; // a walk, one tick's burst, slack once
                r.Is(went <= walk && !r.Op(Enf).Running, $"he walks: {went} cm in 2 s (a walk's {WalkCm(r) * T(2)})");
                r.Eq(g.ValePos(), (Pt?)(r.Op(Enf).Pos + new Pt(100, 0)), "Vale at his side");
            });

            Add("D09", "—", "A busy agent (onBusy cancel): the Scout clicked to Inez and set to Watch her, then pushed: until busyPush (25 cm) in all she is pinned; past it the Watch is cancelled at its cost (lost: nothing learned) and she moves.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "watch", Inez);
                Sample(r, Scout, r.Op(Scout).Pos); // take control standing still
                g.Step();
                var at = r.Op(Scout).Pos;
                Push(r, Scout, new Pt(10, 0), 2);
                r.Is(r.Op(Scout).Busy != null && r.Op(Scout).Pos == at, "pushed 20 cm: pinned, still watching");
                Push(r, Scout, new Pt(10, 0), 2);
                r.Is(r.Op(Scout).Busy == null && g.Log.Exists(l => l.Code == "cancel.watch"), "past 25 cm the Watch is cancelled (lost)");
                r.Is(!g.Inez.KRoutine, "nothing learned");
                Push(r, Scout, new Pt(10, 0), 3);
                r.Is(r.Op(Scout).Pos != at, "and she moves");
            }, DriveStart());

            Add("D09b", "—", "A busy agent (onBusy hold, the playground's switch): the same Watch, pushed throughout; she stands until it lands, then moves, and it teaches what a Watch teaches.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "watch", Inez);
                var at = r.Op(Scout).Pos; int end = r.Op(Scout).BusyEnd;
                while (g.Tick < end - 1) Push(r, Scout, new Pt(10, 0), 1);
                r.Is(r.Op(Scout).Pos == at && !g.Log.Exists(l => l.Code == "cancel.watch"), "held: pinned, never cancelled");
                Push(r, Scout, new Pt(10, 0), 3);
                r.Is(r.Op(Scout).Busy == null && r.Op(Scout).Pos != at, "the Watch lands, then she moves");
                r.Is(g.Log.Exists(l => l.Code == "scout.watch.watched"), "it landed");
            }, DriveStart(onBusy: "hold"));

            Add("D10", "—", "Release and the click (onRelease stand): the Scout clicked to the Courtyard; control taken mid-walk (the walk ends); released, she stands. Taken again, a click move ends control and she walks.", r =>
            {
                var g = r.G;
                r.Send(Scout, "d:Courtyard"); r.Wait(T(2));
                Push(r, Scout, new Pt(0, WalkCm(r)), 3);
                r.Is(r.Op(Scout).Driven && r.Op(Scout).Walk == null, "control ends the walk");
                g.Issue(g.DriveRelease(OpId.Scout)); var at = r.Op(Scout).Pos; r.Wait(T(2));
                r.Is(!r.Op(Scout).Driven && r.Op(Scout).Pos == at, "released: she stands");
                Push(r, Scout, new Pt(0, WalkCm(r)), 2);
                r.Send(Scout, "d:Courtyard");
                r.Is(!r.Op(Scout).Driven && r.Op(Scout).Walk != null, "a click move takes control back");
            }, DriveStart());

            Add("D10b", "—", "Release, resume (the playground's onRelease resume): control taken mid-walk to the Courtyard and released: she walks on to the Courtyard from where she was left.", r =>
            {
                var g = r.G;
                r.Send(Scout, "d:Courtyard"); r.Wait(T(2));
                Push(r, Scout, new Pt(0, WalkCm(r)), 3);
                g.Issue(g.DriveRelease(OpId.Scout));
                r.Is(!r.Op(Scout).Driven && r.Op(Scout).Walk != null && r.Op(Scout).Walk!.End == r.Stand("d:Courtyard"), "she walks on to the Courtyard");
                r.To(r.Arrival(Scout));
                r.Eq(r.Op(Scout).Pos, r.Stand("d:Courtyard"), "and arrives");
            }, DriveStart(onRelease: "resume"));

            Add("D11", "—", "The gap (cell.drive.gap 40 cm): the Scout clicked to 3 m in front of the guard at his post, then driven straight at him for 3 s: she never ends a tick nearer than 40 cm to him while closing. With the playground's gap 0, the same samples walk her through him.", r => GapCase(r, 40), DriveStart());
            Add("D11b", "—", "The gap off (the playground's gap 0): D11's samples walk the Scout to the guard's own spot.", r => GapCase(r, 0), DriveStart(gap: 0));

            Add("D12", "—", "Unknown = reject: a gait the rulebook doesn't name (crouch), a facing of 400, release or face on a move are format errors; a sample with no position is refused (no-place), and in the car (in-car); a playground pace of 2000 per mille doubles a driven walk.", r =>
            {
                var g = r.G;
                bool Throws(string json) { try { Order.Parse(JNode.Parse(json, "order")); return false; } catch (FormatException) { return true; } }
                r.Is(Throws("{\"tick\":0,\"op\":\"scout\",\"do\":\"drive\",\"to\":[0,0],\"gait\":\"crouch\"}"), "a gait the rulebook doesn't name: rejected");
                r.Is(Throws("{\"tick\":0,\"op\":\"scout\",\"do\":\"drive\",\"to\":[0,0],\"face\":400}"), "a facing of 400: rejected");
                r.Is(Throws("{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":[0,0],\"release\":true}") && Throws("{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":[0,0],\"face\":10}"), "release or face on a move: rejected");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "drive" }).code, "no-place", "a sample with no position: refused");
                var start = r.Op(Scout).Pos; int v = WalkCm(r);
                Push(r, Scout, new Pt(0, -2 * v), T(2));
                int went = start.Y - r.Op(Scout).Pos.Y;
                r.Is(went >= 2 * v * T(2) - 2 * v && went <= 2 * v * T(2) + 4 * v, $"pace 2000 per mille: {went} cm in 2 s (twice a walk's {v * T(2)})");
            }, DriveStart(pace: 2000));

            Add("DP1", "—", "The recorded driven session (the replay proof for game:check, brief 025): a session driven the way a host does it (a float controller's positions rounded to centimetres, one sample a tick, Shift on and off, a wall pushed, a Watch pushed into its cancel, a release), saved with its record. Replayed from its start state and order log on this runtime, every checkpoint matches the record, and the outcome.", DrivenSessionProof, DrivenSessionStart());
        }

        static Start DriveStart(int? pace = null, string? onBusy = null, string? onRelease = null, int? gap = null)
        {
            var s = new Start { DrivePace = pace, DriveOnBusy = onBusy, DriveOnRelease = onRelease, DriveGap = gap };
            return s;
        }

        static void GapCase(Run r, int gap)
        {
            var g = r.G; var guard = g.PosOf("guard")!.Value;
            var route = g.S.Grid.Route(guard, r.Stand("d:Office approach"))!;
            var dir = route[1] - route[0]; int len = Math.Max(1, G.Dist(route[0], route[1]));
            var spot = g.S.Grid.NearestFree(new Pt(guard.X + dir.X * 300 / len, guard.Y + dir.Y * 300 / len)) ?? guard;
            r.To(r.SendTo(Scout, spot));
            int nearest = int.MaxValue; bool closingInside = false;
            for (int k = 0; k < T(3); k++)
            {
                var gp = g.PosOf("guard")!.Value; var before = r.Op(Scout).Pos;
                var d = gp - before; int dl = Math.Max(1, G.Dist(gp, before)), v = WalkCm(r);
                Sample(r, Scout, dl <= v ? gp : new Pt(before.X + d.X * v / dl, before.Y + d.Y * v / dl)); g.Step();
                var after = r.Op(Scout).Pos; int now = G.Dist(after, g.PosOf("guard")!.Value);
                nearest = Math.Min(nearest, now);
                if (now < 40 && G.D2(after, gp) < G.D2(before, gp)) closingInside = true;
            }
            if (gap > 0) r.Is(!closingInside && nearest >= 38, $"never closer than the gap while closing (nearest {nearest} cm)");
            else r.Is(nearest <= 15, $"gap off: she walks to him ({nearest} cm)");
        }
    }
}

sim/Suborned.Sim/ScenariosDriveProof.cs.text:
// DP1, the recorded driven session (brief 025; game:check's replay proof). The session (Fixtures/drive-session.script.json) was played the way a
// host plays it: a float controller moved by camera-relative keys at a jittered 60 fps, its position rounded to centimetres and handed over as one
// drive sample a tick, pulled back to the engine's pose when corrected. It is saved with its record (Script.Write: inputs, engine, start hash,
// every checkpoint, outcome) and embedded in the DLL, so every runtime that runs the scenarios (the CLI, the Editor, the built player) replays it
// from its start state and order log and must match the record. Re-record it when the inputs or the engine move: suborned-sim drive-session.
using System;
using System.IO;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        public const string DriveSessionResource = "Suborned.Sim.Fixtures.drive-session.script.json";
        static Suborned.Sim.Script? driveSession; static string? driveSessionError;
        static Suborned.Sim.Script? DriveSession()
        {
            if (driveSession != null || driveSessionError != null) return driveSession;
            try
            {
                using var st = typeof(Scenarios).Assembly.GetManifestResourceStream(DriveSessionResource);
                if (st == null) { driveSessionError = "the recorded driven session is not embedded (Fixtures/drive-session.script.json)"; return null; }
                using var rd = new StreamReader(st); driveSession = Suborned.Sim.Script.Parse(rd.ReadToEnd());
            }
            catch (Exception e) { driveSessionError = e.GetType().Name + ": " + e.Message; }
            return driveSession;
        }
        static Start DrivenSessionStart() => DriveSession()?.Start ?? new Start();

        static void DrivenSessionProof(Run r)
        {
            var s = DriveSession();
            if (!r.Is(s != null && s.Expect != null, $"the recorded session loads with its record{(driveSessionError != null ? ": " + driveSessionError : "")}")) return;
            var g = r.G; var x = s!.Expect!;
            r.Eq(x.Engine, Engine.Version, "recorded on this engine (else re-record: suborned-sim drive-session)");
            r.Eq(Hash.Hex(g.StartHash), x.Start, "the same start state and inputs (else re-record: suborned-sim drive-session)");
            int drives = 0;
            foreach (var o in s.Orders)
            {
                if (o.Tick > s.Until) break;
                g.RunTo(o.Tick); if (g.Over && g.Tick != o.Tick) break;
                if (g.Tick == o.Tick) { g.Issue(o); if (o.Do == "drive") drives++; }
            }
            g.RunTo(s.Until); g.Finish();
            r.Is(drives >= Game.T(10), $"a driven session: {drives} drive samples");
            int n = Math.Min(x.Checkpoints.Count, g.Checkpoints.Count), bad = -1;
            for (int i = 0; i < n && bad < 0; i++) if (x.Checkpoints[i].tick != g.Checkpoints[i].tick || x.Checkpoints[i].hash != Hash.Hex(g.Checkpoints[i].hash)) bad = i;
            r.Is(bad < 0 && x.Checkpoints.Count == g.Checkpoints.Count, bad < 0 ? $"every checkpoint matches the record ({g.Checkpoints.Count})" : $"checkpoint {bad} differs at tick {g.Checkpoints[bad].tick}");
            r.Eq(g.Result.ToString().ToLowerInvariant(), x.Outcome, "the outcome matches the record");
        }
    }
}

sim/Suborned.Sim/ScenariosFailCause.cs.text:
// The fail camera's culprit (Sky 2026-10-18: "if you fail mission, the camera should pan around the item / person that failed you so you
// know what it was for next time"; FailCause.cs). Every way the Handover can end without Vale carries its cause: the fail code, why, the
// deciding tick, the culprits (the first is the one to orbit) where they stood and faced, the operatives involved, and, where no single
// culprit decided it (the seal clock), the report that started it. Read-only: none of these runs hashes differently for it.
// Fail kinds that other scenarios already end in carry these checks in place: S09 (vale-dead, shot), N58 (vale-dead, killed),
// N36 (rivals-reach-vale, the Enforcer downed in the safe fight), N68 (sealed, a confirmed report), N69b (entry-seen-camera),
// N112 (the car leaves without Vale: withdraw). The rest are here; several replay the fail route scripts of
// contracts/missions/handover/routes/ (named beside them). Brief 018's rival at the car (rivals-reach-vale, reached-car) has no route
// that reaches it on today's data: sim/Suborned.Sim.Tests/FailCauseTests.cs builds that cause from a placed fixture.
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>The run ended with this cause: its code, why, single or not, at the run's last tick; the operatives it names; the first
        /// culprit (the one to orbit) by id and kind, placed. first "": no culprit. Returns the cause (null if missing).</summary>
        static FailCause? CauseIs(Run r, string fail, string why, bool single, string first, string kind, string ops)
        {
            var g = r.G; var c = g.Cause;
            if (!r.Is(c != null, $"the run carries the fail camera's cause ({fail})")) return null;
            r.Eq((c!.Fail, c.Why, c.Single, c.Tick), (fail, why, single, g.Tick), "the cause: fail, why, single, and the deciding tick is the run's last");
            r.Eq(string.Join(",", c.Ops), ops, "the operatives it names");
            if (first.Length == 0) { r.Eq(c.Culprits.Count, 0, "no single culprit"); return c; }
            var b = c.Culprits.FirstOrDefault();
            r.Is(b != null && b.Id == first && b.Kind == kind && b.Placed, $"the culprit to orbit is the {kind} {first}, placed (got {b})");
            return c;
        }
        /// <summary>A watcher culprit stands and faces as the engine has it at the deciding tick (the run is over: its pose now is that tick's).</summary>
        static void PosedAs(Run r, Blamed? b, Pt at, Pt facing, string what)
        {
            if (b == null) return;
            r.Is(b.Placed && b.At == at && b.Faces && b.Facing == facing, $"{what}: at {at} facing {facing} (got {b})");
        }
        /// <summary>A shooter culprit: where it fired from, facing the one it hit, within its weapon's reach.</summary>
        static void ShotFrom(Run r, FailCause? c, string shooter, string victim)
        {
            if (c == null || c.Culprits.Count < 2) { r.Is(false, "a shooter and a victim"); return; }
            var s = c.Culprits[0]; var v = c.Culprits[1];
            r.Is(s.Id == shooter && s.Role == "shot" && v.Id == victim && v.Role == "victim" && v.Placed, $"the shooter {shooter}, then the victim {victim} (got {s}; {v})");
            long dot = (long)s.Facing.X * (v.At.X - s.At.X) + (long)s.Facing.Y * (v.At.Y - s.At.Y);
            r.Is(s.Placed && s.Faces && dot > 0 && G.Within(s.At, v.At, r.G.R.Carbine.MaxCm), $"the shooter faces the victim from within a weapon's reach ({s.At} → {v.At})");
        }
        /// <summary>A route script's orders (suborned.sim.script/1 "orders"), played at their ticks.</summary>
        static void Script(Run r, string orders) => Orders(r, JNode.Parse(orders, "orders").Items.Select(Order.Parse).ToArray());

        static void FailCauseCases()
        {
            Add("N119", "—", "The fail camera: entry seen by the guard (§07). The Enforcer walks to the public door and enters with the guard at it: the culprit is the guard at his post, facing the way he watches the door; the Enforcer is the operative he saw.", r =>
            {
                var g = r.G;
                r.To(r.Send(Enf, "d:Office entrance"));
                r.Do(Enf, "enter");
                r.Eq(g.FailCode, "entry-seen-guard", "the guard at the door sees the entry");
                var c = CauseIs(r, "entry-seen-guard", "seen", true, "guard", "guard", Enf);
                PosedAs(r, c?.Culprits.FirstOrDefault(), r.Stand(g.S.GuardPost), g.S.GuardFacing, "the guard at his post");
                r.Eq(c?.Culprits.FirstOrDefault()?.Role, "saw", "he saw it");
                r.Is(c?.Origin == null, "a single culprit: no origin");
            });

            Add("N120", "—", "The fail camera: entry seen by the patrol (§07; route fail-entry-seen-patrol): route A without the reroute, the Enter at 4:40.4 while the sweep covers the door. The culprit is the patrol robot where its sweep stands at that tick, facing along it.", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Courtyard\"},{\"tick\":0,\"op\":\"tech\",\"do\":\"move\",\"to\":\"cabinet\"},{\"tick\":283,\"op\":\"scout\",\"do\":\"watch\",\"target\":\"waitress\"},{\"tick\":345,\"op\":\"tech\",\"do\":\"loop\",\"target\":\"entrance\"},{\"tick\":803,\"op\":\"scout\",\"do\":\"move\",\"to\":\"beside-inez\"},{\"tick\":813,\"op\":\"scout\",\"do\":\"listen\",\"target\":\"waitress\"},{\"tick\":813,\"op\":\"fixer\",\"do\":\"move\",\"to\":\"d:Courtyard\"},{\"tick\":813,\"op\":\"enforcer\",\"do\":\"move\",\"to\":[6950,-4250]},{\"tick\":1233,\"op\":\"fixer\",\"do\":\"turn\",\"target\":\"waitress\",\"approach\":\"help\"},{\"tick\":1733,\"op\":\"fixer\",\"do\":\"turn\",\"target\":\"waitress\",\"approach\":\"help\"},{\"tick\":2233,\"op\":\"fixer\",\"do\":\"call\",\"target\":\"waitress\"},{\"tick\":2233,\"op\":\"enforcer\",\"do\":\"move\",\"to\":\"d:Office entrance\"},{\"tick\":2804,\"op\":\"enforcer\",\"do\":\"enter\"}]"); // c022 (2026-10-19, the door on the west face): the loop at 0:34.5, the Enforcer waits at (69.5, -42.5)
                r.Eq(g.FailCode, "entry-seen-patrol", "the patrol's sweep sees the entry");
                var c = CauseIs(r, "entry-seen-patrol", "seen", true, "patrol", "patrol", Enf);
                var pp = g.PatrolPose()!.Value;
                PosedAs(r, c?.Culprits.FirstOrDefault(), pp.pos, pp.facing, "the patrol on its sweep");
            });

            Add("N121", "—", "The fail camera: the abduction seen by the pickup camera (§07; route fail-take-seen-camera): the driver unturned, the rivals sent away, the Take at the official car under the live pickup camera. The culprit is the pickup camera, facing the car; Vale is the second, where he stood.", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"enforcer\",\"do\":\"move\",\"to\":\"d:Boarding pavilion\"},{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":\"rival-park\"},{\"tick\":3200,\"op\":\"scout\",\"do\":\"mislead\",\"target\":\"rivals\"},{\"tick\":3700,\"op\":\"enforcer\",\"do\":\"take\"}]");
                r.Eq(g.FailCode, "abduction-seen-camera", "the pickup camera sees the Take");
                var c = CauseIs(r, "abduction-seen-camera", "seen", true, "camera:pickup", "camera", Enf);
                var cam = g.S.Cameras.Single(x => x.Id == "pickup");
                PosedAs(r, c?.Culprits.FirstOrDefault(), cam.At, cam.Facing, "the pickup camera on its pole");
                r.Is(c != null && c.Culprits.Count == 2 && c.Culprits[1].Kind == "vale" && c.Culprits[1].At == g.CarPos(), "then Vale, at his car");
            });

            Add("N122", "—", "The fail camera: the rivals beat the cell to the pickup (§07; route fail-rivals-reach-vale): route B without the false tip; the rivals follow the car to the service lane, and the Take there is theirs. The culprit is the rival crew where it stands.", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"enforcer\",\"do\":\"move\",\"to\":\"d:Service lane\"},{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Meet driver\"},{\"tick\":0,\"op\":\"fixer\",\"do\":\"move\",\"to\":\"d:Boarding pavilion\"},{\"tick\":576,\"op\":\"scout\",\"do\":\"watch\",\"target\":\"driver\"},{\"tick\":776,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Meet driver\"},{\"tick\":797,\"op\":\"scout\",\"do\":\"listen\",\"target\":\"driver\"},{\"tick\":1217,\"op\":\"fixer\",\"do\":\"turn\",\"target\":\"driver\",\"approach\":\"pay\"},{\"tick\":1717,\"op\":\"scout\",\"do\":\"move\",\"to\":[8250,-3100]},{\"tick\":3700,\"op\":\"enforcer\",\"do\":\"take\"}]"); // c022: the Scout steps to the driver before the Listen (3 m)
                r.Eq(g.FailCode, "rivals-reach-vale", "the rivals reach Vale first");
                var c = CauseIs(r, "rivals-reach-vale", "beat-to-pickup", true, "rivals", "rival", Enf);
                var rp = g.RivalsPose()!.Value;
                PosedAs(r, c?.Culprits.FirstOrDefault(), rp.pos, rp.facing, "the rival crew");
                r.Is(c != null && c.Culprits.Count == 2 && c.Culprits[1].Kind == "vale", "then Vale");
            });

            Add("N123", "—", "The fail camera: the rivals have Vale at the close (§07): nobody touches anything; at 8:30 the rival crew, still watching the pickup, has him. The culprit is the rival crew; no operative is named.", r =>
            {
                var g = r.G;
                r.To(T(g.S.Over));
                r.Eq(g.FailCode, "rivals-reach-vale", "at the close the rivals are there");
                var c = CauseIs(r, "rivals-reach-vale", "reached-at-close", true, "rivals", "rival", "");
                var rp = g.RivalsPose()!.Value;
                PosedAs(r, c?.Culprits.FirstOrDefault(), rp.pos, rp.facing, "the rival crew at its car");
            });

            Add("N124", "—", "The fail camera: Vale leaves in his car (§07; route fail-vale-leaves): the Scout sends the rivals away late, so they are gone at 8:30 and the official car leaves with him. The culprit is the official car where it stands, then Vale.", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":\"rival-park\"},{\"tick\":2500,\"op\":\"scout\",\"do\":\"mislead\",\"target\":\"rivals\"}]");
                r.To(T(g.S.Over));
                r.Eq(g.FailCode, "vale-leaves", "Vale leaves in the official car");
                var c = CauseIs(r, "vale-leaves", "too-late", true, "car", "car", "");
                r.Is(c != null && c.Culprits[0].At == g.CarPos() && c.Culprits.Count == 2 && c.Culprits[1].Kind == "vale" && c.Culprits[1].Role == "left", "the official car at the pickup, then Vale leaving in it");
            });

            Add("N125", "—", "The fail camera: the Enforcer down (§07; route fail-enforcer-down): an unprepared shot at the guard from inside his cone; the Enforcer trades fire until the response unit's officer drops him. The culprit is the shooter that downed him, where it fired from and facing him; the Enforcer is the operative and the second culprit (the victim).", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"enforcer\",\"do\":\"move\",\"to\":\"d:Office approach\"},{\"tick\":354,\"op\":\"enforcer\",\"do\":\"fire\",\"target\":\"guard\"}]");
                r.Until(() => g.Over, T(120));
                r.Eq(g.FailCode, "enforcer-down", "the Enforcer is down");
                // Changed 2026-10-19 (the door on the west face): which of the two officers drops him is the block's (it was security-1, it is
                // security-2 from the new forecourt); the test is that the culprit is whoever landed the last hit on him, an officer
                var last = r.Shots().FindLast(s => s.hit && s.target == Enf).by ?? "";
                r.Is(last.StartsWith("security-", StringComparison.Ordinal), $"a response officer drops him ({last})");
                var c = CauseIs(r, "enforcer-down", "shot", true, last, "officer", Enf);
                ShotFrom(r, c, last, Enf);
                r.Is(r.Shots().FindLast(s => s.hit).by == last, "the last hit of the run is the culprit's");
            });

            Add("N126", "—", "The fail camera: the driver shot during the handover (§07): the Enforcer at the boarding pavilion fires on the driver (forced) after Vale is out. The culprit is the Enforcer where he fired from, facing the driver; the driver is the second (the victim), where he fell.", r =>
            {
                var g = r.G;
                r.To(r.Send(Enf, "d:Boarding pavilion"));
                r.To(T(g.S.ValeExits) + T(1));
                r.Fire(Enf, Driver, force: true);
                r.Until(() => g.Over, T(20));
                r.Eq(g.FailCode, "driver-shot", "the driver is shot with Vale out");
                var c = CauseIs(r, "driver-shot", "shot", true, Enf, "op", Enf);
                ShotFrom(r, c, Enf, Driver);
                r.Is(c != null && c.Culprits[0].At == r.Op(Enf).Pos, "he fired from where he stands");
            });

            Add("N127", "—", "The fail camera: the seal, and what started it (§07; route fail-district-seals without the loop, and without its second fire order, refused there: the guard is already down): the entrance camera shows the Enforcer's drawn weapon at 2:25.1 and its watchers call the response; the guard's missed check-in at 2:30 calls it again, earlier, and the district seals 2:25 after that unit is on the street. No single culprit: the origin is the camera's report (the first, which raised the response), where the camera stands; the last move is the desk's report of the empty post, whose clock ran out.", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"enforcer\",\"do\":\"move\",\"to\":[6950,-4250]},{\"tick\":1450,\"op\":\"enforcer\",\"do\":\"fire\",\"target\":\"guard\"},{\"tick\":1520,\"op\":\"enforcer\",\"do\":\"move\",\"to\":\"d:Behind café\"}]"); // c022: the Enforcer fires from (69.5, -42.5), beside the door on the west face
                r.Until(() => g.Over, T(300));
                r.Eq(g.FailCode, "sealed", "the district seals");
                var c = CauseIs(r, "sealed", "sealed", false, "", "", Enf);
                var o = c?.Origin; var cam = g.S.Cameras.Single(x => x.Id == "entrance");
                r.Is(o != null && o.Because == "response" && o.Report == "drawn-seen:enforcer" && o.Ops.SequenceEqual(new[] { Enf }), $"the origin: the drawn weapon reported, which called the response (got {o?.Report}, {o?.Because})");
                PosedAs(r, o?.Reporter, cam.At, cam.Facing, "its reporter, the entrance camera");
                r.Is(o != null && o.Tick < g.Tick && g.Log.Exists(l => l.Tick == o.Tick && l.Code == "security.called"), "at the tick the response was called");
                var m = c?.LastMove;
                r.Is(m != null && m.Report == "post-empty:guard" && m.Reporter?.Id == "desk" && m.Reporter.At == r.Stand(g.S.GuardPost) && m.Tick > o!.Tick, "the last move: the desk's report of the empty post, at the post");
            });

            Add("N128", "—", "The fail camera: the seal of a loud final fight (route careless-body-found): the guard killed at his post and left there, the Enter at once; the Tech leaves the cabinet and the entrance camera's watcher reads the dead guard (Alert 2). The Enforcer comes out into the loud fight, whose seal clock runs out at 5:37. No single culprit: the origin is what made the fight loud, the camera's report that raised Alert to 2, where the camera stands.", r =>
            {
                var g = r.G;
                Script(r, "[{\"tick\":0,\"op\":\"tech\",\"do\":\"move\",\"to\":\"cabinet\",\"run\":true},{\"tick\":0,\"op\":\"enforcer\",\"do\":\"move\",\"to\":[6950,-4250]},{\"tick\":0,\"op\":\"scout\",\"do\":\"move\",\"to\":\"d:Office approach\"},{\"tick\":0,\"op\":\"fixer\",\"do\":\"move\",\"to\":\"crew:fixer\"},{\"tick\":166,\"op\":\"tech\",\"do\":\"loop\",\"target\":\"entrance\"},{\"tick\":462,\"op\":\"scout\",\"do\":\"watch\",\"target\":\"guard\"},{\"tick\":662,\"op\":\"scout\",\"do\":\"move\",\"to\":\"crew:scout\"},{\"tick\":1060,\"op\":\"tech\",\"do\":\"reroute\",\"target\":\"patrol\"},{\"tick\":1440,\"op\":\"enforcer\",\"do\":\"move\",\"to\":[6520,-4110]},{\"tick\":1510,\"op\":\"enforcer\",\"do\":\"takedown\",\"target\":\"guard\",\"how\":\"kill\"},{\"tick\":1540,\"op\":\"enforcer\",\"do\":\"enter\"},{\"tick\":1540,\"op\":\"tech\",\"do\":\"move\",\"to\":[675,-4625]},{\"tick\":1540,\"op\":\"scout\",\"do\":\"move\",\"to\":[1175,-4825]},{\"tick\":1540,\"op\":\"fixer\",\"do\":\"move\",\"to\":[1025,-4625]},{\"tick\":1920,\"op\":\"scout\",\"do\":\"draw\"},{\"tick\":1920,\"op\":\"scout\",\"do\":\"stance\",\"stance\":\"free\"},{\"tick\":1920,\"op\":\"fixer\",\"do\":\"draw\"},{\"tick\":1920,\"op\":\"fixer\",\"do\":\"stance\",\"stance\":\"free\"},{\"tick\":1920,\"op\":\"tech\",\"do\":\"draw\"},{\"tick\":1920,\"op\":\"tech\",\"do\":\"stance\",\"stance\":\"free\"},{\"tick\":1920,\"op\":\"enforcer\",\"do\":\"move\",\"to\":\"d:Getaway bay\"}]"); // c022's careless-body-found
                r.To(T(g.S.Over));
                r.Eq(g.FailCode, "sealed", "the loud fight's seal runs out");
                var c = CauseIs(r, "sealed", "sealed", false, "", "", Enf);
                var o = c?.Origin; var cam = g.S.Cameras.Single(x => x.Id == "entrance");
                r.Is(o != null && o.Because == "loud-fight" && o.Report.StartsWith("report:dead:", StringComparison.Ordinal), $"the origin: the dead guard's report made the fight loud (got {o?.Report}, {o?.Because})");
                PosedAs(r, o?.Reporter, cam.At, cam.Facing, "its reporter, the entrance camera");
                r.Is(o != null && g.Ledger.Exists(l => l.tick == o.Tick && l.what == "alert" && l.now >= 2 && l.now - l.delta < 2), "it raised Alert to 2 at that tick");
                r.Is(c?.LastMove == null, "nothing moved the clock after the fight set it");
            });

            Add("N129", "—", "The fail camera: a withdrawal has no culprit (the cell pulled out at 0:30).", r =>
            {
                var g = r.G;
                r.Wait(T(30));
                r.Is(g.Issue(new Order { Tick = g.Tick, Do = "withdraw" }).ok, "withdraw taken");
                r.Eq(g.Result, Outcome.Withdrawn, "the cell withdraws");
                var c = CauseIs(r, "withdraw", "withdrew", false, "", "", "");
                r.Is(c != null && c.Origin == null, "and nothing started it");
            });
        }
    }
}

