// Running and real-time shoot-outs (Sky 2026-10-15: Motive's briefs/011/motive-fights.md approved, all five answers as recommended):
// a run seen by people and by security, runs refused, hits counted not rolled, a drawn weapon as an act, the going-loud card, panic,
// and carrying a downed operative.
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        static int SawRunner(Game g)
        {
            int n = 0;
            foreach (var p in g.People) n += p.Count("saw-runner");
            foreach (var w in g.Walkers) n += w.P.Count("saw-runner");
            return n;
        }
        /// <summary>A point in front of the guard at his door, within point blank (3 m along his facing), on free ground.</summary>
        static Pt FrontOfGuard(Run r) => r.Stand("d:Office entrance") + Along(r.G.S.GuardFacing, 300); // along his facing from the site (2026-10-19: west, the door on the west face; was a fixed 3 m north)
        /// <summary>`cm` along a facing (any length), in integer centimetres.</summary>
        static Pt Along(Pt facing, int cm) { long len = Math.Max(1, G.Isqrt((long)facing.X * facing.X + (long)facing.Y * facing.Y)); return new Pt((int)(facing.X * cm / len), (int)(facing.Y * cm / len)); }
        /// <summary>Free ground `cm` in front of the guard where he stands now (along his facing).</summary>
        static Pt AheadOfGuard(Run r, int cm) { var gp = r.G.GuardPose()!.Value; return r.G.S.Grid.NearestFree(gp.pos + Along(gp.facing, cm))!.Value; }

        static void FightCases()
        {
            Add("N20", "—", "A running witness (motive-fights.md §1.1): the Scout runs past the Office; people in range remember where and when (no Trail); security that sees the run counts one found fault, Alert 1, once a run; the guard who saw it is no ally in a safe fight.", r =>
            {
                var g = r.G;
                int trail = g.Trail;
                var q = g.QuoteMove(Scout, r.Stand("d:Office approach"));
                r.Is(q.RunS * 2 <= q.WalkS + 1 && q.RunS > 0, $"the chip: run {q.RunS} s against walk {q.WalkS} s (2.8 m/s against 1.4)");
                r.Is(q.RunSeenBy.Count > 0 && q.AlertIfRun == 1, $"the chip names who would see the run ({string.Join(", ", q.RunSeenBy)}) and Alert → 1");
                r.To(r.Send(Scout, "d:Office approach", run: true));
                r.Eq(g.Trail, trail, "running is no traceable act: no Trail");
                r.Eq(g.Alert, 1, "security saw a runner: a found fault, Alert 1");
                r.Eq(g.Ledger.FindAll(l => l.cause.StartsWith("runner-seen:", StringComparison.Ordinal)).Count, 1, "once a run, however many watchers saw it");
                r.Is(SawRunner(g) > 0, $"people remember the runner, place and time ({SawRunner(g)})");
                r.Is(g.GuardP.Has("saw-runner"), "the guard saw him: he holds a memory, so he won't fight at the cell's side (§07 never saw you)");
            });

            Add("N20b", "—", "Running is free once the run is loud (motive-fights.md §1.1): after gunfire nobody counts a runner.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Fire(Enf, GuardR); r.Is(r.Until(() => g.GuardDown, T(30)), "the guard is down: the run is loud");
                int seen = SawRunner(g), ledger = g.Ledger.Count;
                r.Is(g.QuoteMove(Scout, r.Stand("d:Office approach")).RunFree, "the chip says running is free");
                r.To(r.Send(Scout, "d:Office approach", run: true));
                r.Eq(SawRunner(g), seen, "no one counts the runner");
                r.Is(!g.Ledger.GetRange(ledger, g.Ledger.Count - ledger).Exists(l => l.cause.StartsWith("runner-seen:", StringComparison.Ordinal)), "and no found fault");
            });

            Add("N21", "—", "Runs refused, each with its reason (motive-fights.md §1.1): the Tech tethered to a loop, an operative in the middle of an action; walking stays open.", r =>
            {
                var g = r.G;
                r.To(r.Send(Tech, "cabinet")); r.Do(Tech, "loop", "entrance"); r.Done(Tech);
                var (ok, why) = g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "move", To = "d:Courtyard", Run = true });
                r.Is(!ok && why.Contains("tethered"), $"the Tech can't run while the loop holds: {why}");
                r.Eq(g.QuoteMove(Tech, r.Stand("d:Courtyard")).RunRefused, why, "the chip says so before the double-click");
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez);
                (ok, why) = g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "move", To = "d:Office approach", Run = true });
                r.Is(!ok && why.Contains("busy"), $"mid-action, no run: {why}");
                r.Done(Scout);
                r.Send(Scout, "d:Office approach", run: true);
                r.Is(r.Op(Scout).Running, "the action done, the Scout runs");
                r.Send(Tech, "d:Courtyard");
                r.Is(r.Op(Tech).Walk != null && !r.Op(Tech).Running, "the Tech may still walk away (and the loop ends at the tether)");
            });

            Add("N22", "—", "Hits are counted, not rolled (motive-fights.md §2.2): the untrained Scout's pistol at point blank is 750 ‰, so exactly three hits in four, the third shot the miss; the guard's 3 health falls on the fourth shot. +2 T for the hit, +2 for the down.", r =>
            {
                var g = r.G;
                r.Eq(g.R.Accuracy(g.R.Pistol, 300, false, false, false, true), 750, "point blank × untrained: 750 ‰");
                r.Eq(g.R.Accuracy(g.R.Pistol, 1200, true, false, false, false), 375, "effective, walking: 375 ‰");
                r.Eq(g.R.Accuracy(g.R.Carbine, 1800, false, false, true, false), 562, "the Enforcer holding Vale fires one-handed: 562 ‰");
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r))));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                int trail = g.Trail;
                r.Fire(Scout, GuardR);
                r.Is(r.Until(() => g.GuardDown, T(20)), "the guard is down");
                var mine = r.Shots().FindAll(x => x.by == Scout && x.target == GuardR);
                r.Eq(string.Join(",", mine.ConvertAll(x => x.hit ? "hit" : "miss")), "hit,hit,miss,hit", "exactly three in four, in this order, every run");
                r.Eq(mine[1].tick - mine[0].tick, g.R.Pistol.Every, "a pistol fires every 1.5 s");
                r.Eq(g.Trail - trail, g.R.GunfireTrail + g.R.HitTrail + g.R.DownTrail, "+2 T the shooting (once), +2 T hit, +2 T down: not per shot (Motive addendum Q1)");
                r.Eq(g.Gunfire, 4, "four shots fired");
                r.Is(!r.Op(Scout).Down, $"the guard fired back but the Scout stands ({r.Op(Scout).Gun.Health}/{r.Op(Scout).Gun.Max})");
            });

            Add("N23", "—", "A drawn weapon is an act (motive-fights.md §2.3): drawn among people out of security's sight, one witnessed incident (+1 T, Alert 1), and they hold the Fixer's face; drawn in the guard's cone, Alert 2, he engages and calls it in.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard"));
                var card = g.GoingLoud(new Order { Tick = g.Tick, Op = Fixer, Do = "draw" });
                r.Is(!card.Loud && card.Why == "unseen-draw", $"no security sees him: drawing isn't going loud ({card.Why})");
                int trail = g.Trail;
                r.Do(Fixer, "draw"); r.Wait(1);
                r.Eq(g.Trail - trail, g.R.WitnessTrail, "one witnessed incident: +1 T");
                r.Eq(g.Alert, card.AlertTo, $"Alert as the card said ({card.AlertTo})");
                r.Eq(g.Alert, 1, "Alert 1");
                r.Is(g.Incidents.Exists(i => i.Kind == "weapon-drawn" && i.Witnesses.Count > 0), "the incident with its witnesses (for the investigators)");
                r.Is(g.Walkers.Exists(w => g.HoldsFace(w.P)), "a witness holds the Fixer's face");
                r.Eq(g.Standing, g.StandingAtStart - g.R.StandingStep, "a gun shown on the street: one step toward Menace (Motive addendum Q5)");
                r.Wait(T(3)); r.Eq(g.Trail - trail, g.R.WitnessTrail, "once a draw, not once a tick");
                r.SendTo(Scout, r.Op(Fixer).Pos + new Pt(0, 100)); r.Until(() => r.Op(Scout).Walk == null, T(120));
                int incidents = g.Incidents.FindAll(i => i.Kind == "weapon-drawn").Count;
                r.Do(Fixer, "holster"); r.Wait(T(1)); r.Do(Fixer, "draw"); r.Do(Scout, "draw"); r.Wait(T(2));
                r.Eq(g.Incidents.FindAll(i => i.Kind == "weapon-drawn").Count, incidents + 1, "two drawing together at one place: one incident (Motive addendum Q1)");
                r.Eq(g.Trail - trail, 2 * g.R.WitnessTrail, "+1 T for it, not +2");
                r.To(r.Send(Fixer, "d:Office approach"));
                r.Eq(g.Alert, 2, "walking into the guard's cone with the weapon out: Alert 2");
                r.Is(g.GuardEngaged, "the guard engages");
                r.Is(g.SecurityArrives < int.MaxValue / 4, "and calls it in");
            });

            Add("N24", "—", "Going loud (motive-fights.md §2.6; Sky Q4: commit by holding, no pause): the card says what a shot would set off, changes nothing, and the run then does what it said.", r =>
            {
                var g = r.G;
                r.To(r.Send(Enf, "d:Office approach"));
                ulong before = Hash.State(g);
                var c = g.GoingLoud(new Order { Tick = g.Tick, Op = Enf, Do = "fire", Target = GuardR });
                r.Eq(Hash.State(g), before, "reading the card changes nothing");
                r.Is(c.Loud && c.Why == "fire", "a shot before any fight goes loud");
                r.Is(c.AlertTo >= 2, $"Alert → {c.AlertTo} ({c.Civilians} civilians watching)");
                // brief 013: the delays are level 1's arrivals; at the mission's level the unit rolls that level's dispatch instead (the Handover: 2, 10 s)
                r.Eq(c.PoliceInS, (c.Civilians > 0 ? g.R.RespWitnessS : g.R.RespSeenS) + g.DialNow.DispatchS - g.R.Dial[1].DispatchS, "police from the north street, by who reports it, at the level's dispatch");
                r.Eq(c.Seal, c.SecurityArrives + T(g.SealS), "the seal follows their arrival");
                r.Eq(c.FightAfter, "loud", "the final fight turns loud");
                r.Is(c.Officers >= g.R.LoudOfficers && c.ResponseOfficers == g.R.ResponseOfficers, $"{c.Officers} officers and the response unit's {c.ResponseOfficers}");
                r.Is(c.GuardAllyLost, "the guard won't help");
                r.Eq((c.TrailPerShooting, c.TrailPerHit, c.TrailPerDown, c.HoldTicks), (2, 2, 2, 5), "+2 T the shooting, +2 T a person hit, +2 T a down; hold 0.5 s to commit");
                r.Is(c.DownedCaptured, "the loss line: anyone downed is captured unless carried (Motive addendum Q3)");
                r.Fire(Enf, GuardR);
                r.Until(() => g.Gunfire > 0, T(10));
                r.Eq(g.Alert, c.AlertTo, "Alert as the card said");
                r.Is(g.SecurityArrives >= c.SecurityArrives && g.SecurityArrives <= c.SecurityArrives + g.R.DrawTicks + g.R.AimNewTicks, "the response as the card said, within the draw and the aim");
                var after = g.GoingLoud(new Order { Tick = g.Tick, Op = Scout, Do = "fire", Target = GuardR });
                r.Is(!after.Loud, $"once loud, no card ({after.Why}{after.Refused})");
            });

            Add("N25", "—", "Panic (motive-fights.md §2.4): refused with no fight on; once the guard fires on the cell, every armed operative draws and fires at will.", r =>
            {
                var g = r.G;
                r.Refused("cell", "panic", "", "no fight: panic is refused");
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r)), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Scout, "draw");
                r.Is(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "stance", Stance = "hold" }).ok, "the Scout holds fire");
                r.Is(r.Until(() => g.CellFiredOn, T(10)), "the guard sees the weapon and fires on the Scout: a fight is on");
                r.Is(!r.Shots().Exists(x => x.by == Scout), "holding, the Scout hasn't fired");
                r.Do("cell", "panic");
                r.Is(Array.TrueForAll(g.Ops, o => o.Gun.W == null || (o.Gun.Drawn && o.Gun.Stance == "free")), "every armed operative draws and fires at will");
                r.Is(r.Until(() => g.GuardDown, T(20)), "the guard is down");
                r.Is(r.Shots().Exists(x => x.by == Scout && x.target == GuardR) && r.Shots().Exists(x => x.by == Enf && x.target == GuardR), "the Scout and the Enforcer fired on him without a fire order");
                r.Is(!r.Shots().Exists(x => x.by != GuardR && x.target == "patrol"), "at will is at combatants only: nobody fired on the patrol, which never engaged");
            });

            var pressure = new Start(); pressure.Known[Inez] = new List<string> { "routine", "need", "temperament" };
            Add("N36", "—", "The safe fight lost (Motive addendum Q7): unprepared (Inez pressured, so no warning; the guard saw the Enforcer, so no ally), the Enforcer alone at the car goes down, and the fail is the rivals' goal: they take Vale.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Office approach", run: true)); // running past the door: the guard holds a memory, so no ally (Motive §1.1)
                r.Is(g.GuardP.Has("saw-runner"), "the guard saw the Scout run");
                r.To(Max(r.Send(Fixer, "d:Courtyard"), r.Send(Tech, "cabinet"), r.Send(Scout, "d:Courtyard"))); r.Do(Tech, "loop", "entrance");
                r.Do(Fixer, "turn", Inez, "pressure"); r.Done(Fixer); r.Done(Tech);
                r.SendTo(Enf, new Pt(4900, -1700)); r.To(r.Arrival(Enf));
                while (!g.SweepSeesEntrance(g.Tick)) g.Step();
                r.Do(Fixer, "call", Inez);
                r.To(r.Send(Enf, "d:Office entrance"));
                while (g.PatrolWatching(r.At("d:Office entrance"))) g.Step();
                r.Do(Enf, "enter"); r.Do(Tech, "reroute", "patrol"); r.Done(Enf);
                r.Is(!g.FightWarned, "pressured, Inez warns nobody");
                r.Is(!g.GuardAlly, "the guard saw the cell: no ally");
                r.Send(Enf, "d:Getaway bay");
                r.FightItOut(120);
                r.Eq(g.Result, Outcome.Failure, "the lone, unprepared Enforcer loses the safe fight");
                r.Eq(g.FailCode, "rivals-reach-vale", "and the fail names what the rivals came for");
                var fc = CauseIs(r, "rivals-reach-vale", "downed-enforcer", true, r.Shots().FindLast(s => s.hit).by, "rival", Enf); // the fail camera (ScenariosFailCause.cs): the rival whose shot downed him
                ShotFrom(r, fc, r.Shots().FindLast(s => s.hit).by, Enf);
            }, pressure);

            Add("N37", "—", "The crowd scatters (Pulse §4): a weapon drawn among people on the square startles those in sight within witness range; after the startle they run to a refuge farther from it than they stood, shelter off the street, and walk back when it has been quiet.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard"));
                var at = r.Op(Fixer).Pos;
                var near = g.Walkers.FindAll(w => { var p = g.CrowdPos(w); return p.HasValue && G.Within(p.Value, at, g.R.WitnessRangeCm) && g.S.Sight(at, p.Value, g.R.Eye); });
                r.Is(near.Count > 0, $"people in sight of the Fixer ({near.Count})");
                r.Do(Fixer, "draw"); r.Wait(1);
                r.Is(near.TrueForAll(w => w.St == "startled"), "each of them is startled");
                var stood = new Dictionary<string, long>(); foreach (var w in near) stood[w.P.Id] = G.D2(w.At, at);
                r.Wait(g.R.CrowdStartleTicks + 1);
                r.Is(near.TrueForAll(w => w.St == "fleeing"), "after the startle they run");
                bool away = true; foreach (var w in near) { var rf = g.S.Refuges.Find(x => x.id == w.Refuge); if (G.D2(rf.at, at) <= stood[w.P.Id] && g.S.Refuges.Exists(x => G.D2(x.at, at) > stood[w.P.Id] && G.Within(x.at, w.At, g.R.CrowdFleeMaxCm))) away = false; }
                r.Is(away, "each to a refuge farther from the weapon than they stood");
                r.Is(r.Until(() => near.TrueForAll(w => w.St == "sheltered"), T(60)), "they reach shelter");
                r.Is(near.TrueForAll(w => !g.CrowdPos(w).HasValue), "off the street");
                r.Do(Fixer, "holster");
                r.Is(r.Until(() => near.TrueForAll(w => w.St == "" || w.St == "returning"), T(g.R.CrowdQuietS + 5)), "quiet for crowd.quiet, they come back");
            });

            Add("N38", "—", "A shot startles everyone within crowd.scatter, seen or not; a person on a watcher's sightline blocks it (Pulse §4: watchers only).", r =>
            {
                var g = r.G;
                r.To(r.Send(Enf, "d:Office approach"));
                var at = r.Op(Enf).Pos;
                var within = g.Walkers.FindAll(w => { var p = g.CrowdPos(w); return p.HasValue && G.Within(p.Value, at, g.R.CrowdScatterCm); });
                r.Fire(Enf, GuardR); r.Until(() => g.Gunfire > 0, T(10)); r.Wait(1);
                r.Is(within.TrueForAll(w => w.St != ""), $"everyone within 30 m is startled or already running ({within.Count})");
                // a sightline through a person on the street is blocked; one that passes 1 m clear of everyone is not
                var w0 = g.Walkers.Find(w => w.St == "" && g.CrowdPos(w).HasValue)!; var p0 = g.CrowdPos(w0)!.Value;
                r.Is(g.CrowdBlocks(p0 + new Pt(-1000, 0), p0 + new Pt(1000, 0)), "a line through a person is blocked (crowd.occlude)");
                int found = -1;
                for (int dy = 100; dy <= 3000 && found < 0; dy += 100)
                {
                    bool clear = true;
                    foreach (var w in g.Walkers) { var p = g.CrowdPos(w); if (p.HasValue && p.Value.X >= p0.X - 1100 && p.Value.X <= p0.X + 1100 && Math.Abs(p.Value.Y - (p0.Y + dy)) < 100) clear = false; }
                    if (clear) found = dy;
                }
                r.Is(found > 0 && !g.CrowdBlocks(p0 + new Pt(-1000, found), p0 + new Pt(1000, found)), $"a line 1 m clear of everyone is not ({found} cm off)");
            });

            Add("N38b", "—", "Shots in a crowd are witnessed (Pulse §4; Latch's play test asked): people within witness range on a clear line of the shooter or the target at the shot remember saw-gunfire with the Fixer's face; people beyond it only startle.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard"));
                r.Do(Fixer, "draw"); r.Wait(g.R.DrawTicks + 1); // drawn first, so the shot is the only new act
                var inez = g.PersonPos(g.Inez)!.Value;
                r.Fire(Fixer, Inez, force: true);
                r.Is(r.Until(() => g.Gunfire > 0, T(10)), "the shot");
                var at = r.Op(Fixer).Pos;
                var inRange = g.Walkers.FindAll(w => { var p = g.CrowdPos(w); return p.HasValue && ((G.Within(p.Value, at, g.R.WitnessRangeCm) && g.S.Sight(p.Value, at, g.R.Eye)) || (G.Within(p.Value, inez, g.R.WitnessRangeCm) && g.S.Sight(p.Value, inez, g.R.Eye))); });
                r.Is(inRange.Count > 0, $"people stand within witness range of the shot ({inRange.Count})");
                r.Is(inRange.TrueForAll(w => w.P.Has("saw-gunfire")), "each remembers saw-gunfire");
                r.Is(inRange.Exists(w => g.HoldsFace(w.P)), "with the Fixer's face");
                r.Is(g.Incidents.Exists(i => i.Cause == "violence:waitress" && i.Witnesses.Count >= inRange.Count), "and they are the incident's witnesses (for the investigators)");
            });

            Add("N39", "—", "Route A's window is the lover tie (Motive, briefs/011/motive-lovers.md; Sky: Inez and the door guard are lovers): the turned Inez's call sends for the guard, read from the city's ties; he walks the grid to her, stays 60 s (summon.stay) and walks back.", r =>
            {
                var g = r.G;
                r.Is(g.Inez.Lover == g.GuardP && g.GuardP.Lover == g.Inez, "the cast's people file ties them as lovers, both ends");
                r.Do(Fixer, "call", Inez);
                var c = g.Log.FindLast(l => l.Code == "call.waitress");
                r.Is(c.Code == "call.waitress", $"the call sends for him: {c.Text}");
                int walk = g.VisitWalkTicks;
                r.Eq(g.GuardAwayUntil - g.LureTick, 2 * walk + T(g.R.SummonStayS), "away for his walk there, 60 s, and his walk back");
                r.Is(walk > 0 && walk <= T(g.R.SummonWalkMaxS), $"his walk from the door is {walk / 10} s, within summon.walkMax");
                r.Wait(T(5));
                r.Is(!g.GuardAtDoor, "the door is empty: route A's window");
                r.To(g.LureTick + walk);
                r.Eq(g.GuardPose()!.Value.phase, "at café", "he is with her");
                r.To(g.GuardAwayUntil);
                r.Is(g.GuardAtDoor, "and back at his post when the window closes");
                r.Is(g.Chain.Contains("waitress-calls-guard"), "the debrief chain names it");
            }, Turned(Inez));

            var untied = Turned(Inez); untied.Untie.Add(Inez);
            Add("N39b", "—", "With no lover tie the call doesn't pull him (systems over scripts: the lure is the tie, never the mission): a turned Inez has nothing to do on a call.", r =>
            {
                var g = r.G;
                r.Is(g.Inez.Lover == null && g.Inez.Secret.Length == 0, "the tie and her affair are cut (a test's start state)");
                var (ok, code, _) = g.Issue(new Order { Tick = g.Tick, Op = Fixer, Do = "call", Target = Inez });
                r.Is(!ok && code == "nothing-to-call", $"refused: {code}");
                r.Wait(T(5));
                r.Is(g.GuardAtDoor && g.Trail == 0, "the guard stays at the door, and the refused call costs nothing");
            }, untied);

            Add("N39c", "—", "The summons refused, each at no cost with its code (rulebook summon): already away (busy), come once this shift, and Alert above summon.alertMax; and Alert reaching 2 mid-visit sends him running back.", r =>
            {
                var g = r.G;
                r.Do(Fixer, "call", Inez);
                int trail = g.Trail;
                var (ok, code, _) = g.Issue(new Order { Tick = g.Tick, Op = Fixer, Do = "call", Target = Inez });
                r.Is(!ok && code == "summon-busy" && g.Trail == trail, $"while he's away: {code}, no cost");
                r.To(g.GuardAwayUntil + 1);
                (ok, code, _) = g.Issue(new Order { Tick = g.Tick, Op = Fixer, Do = "call", Target = Inez });
                r.Is(!ok && code == "summon-came-once" && g.Trail == trail, $"back at his post: {code}, no cost");
                r.Is(!g.CanCall(Inez), "the card says the call can't be given");
            }, Turned(Inez));

            Add("N39d", "—", "Alert reaching 2 ends the visit (rulebook summon): he runs back to his post at security's pace; and a call at Alert 2 is refused (summon-alert).", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Enf, BesideDoor));
                r.Do(Fixer, "call", Inez);
                int planned = g.GuardAwayUntil;
                r.Wait(T(20));
                r.Fire(Enf, "patrol");
                r.Is(r.Until(() => g.Alert >= 2, T(60)), "gunfire: Alert 2");
                r.Wait(1);
                r.Is(g.Log.Exists(l => l.Code == "guard.recalled"), "the visit ends: he runs back");
                r.Is(g.GuardAwayUntil < planned, $"back sooner than the planned window ({Report.Clock(g.GuardAwayUntil)} < {Report.Clock(planned)})");
            }, Turned(Inez));

            // the Loyal guard's exposure rule is under test (§2.2: a Loyal man pressed by exposure doesn't report it), so the start state makes the
            // guard Loyal whoever the cast is (§04 restricted: a guard is Loyal or Mercenary; the r016 cast's guard is a Mercenary)
            var known = new Start(); known.Known[Inez] = new List<string> { "routine", "need", "temperament" }; known.Temperament[GuardR] = "loyal";
            Add("N40", "—", "Watching the lovers together teaches the affair on both (Motive, motive-lovers.md §1.2); with the guard's secret known, Pressure on the Loyal guard is at its proper step, needs no pressable need, and he doesn't report it (§2.2).", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Fixer, "d:Courtyard"), r.Send(Scout, "d:Courtyard")));
                HelpUntilTurned(r, Inez);
                r.Is(!g.Inez.KSecret && !g.GuardP.KSecret, "help needs no secret: the affair is still unknown");
                r.Eq(g.Preview("pressure", GuardR).Outcome == "?" || !g.Preview("pressure", GuardR).Leverage, true, "no leverage on the guard yet");
                r.Do(Fixer, "call", Inez);
                r.To(g.LureTick + g.VisitWalkTicks);
                r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.Is(g.Inez.KSecret && g.GuardP.KSecret, "a Watch that ends with them together teaches the affair, on both");
                var q = g.Preview("pressure", GuardR);
                r.Is(q.Leverage, "the card reads exposure: his secret");
                r.Eq(q.Reports, "no", "a Loyal man pressed by exposure doesn't report it");
                r.Eq(q.Trail, (long)g.R.Num("p:approaches.pressure.trail"), "at its proper step: no wrong-approach line for a Loyal guard");
                var gp = g.GuardPose()!.Value.pos;
                if (!G.Within(r.Op(Fixer).Pos, gp, g.R.ApproachReachCm)) r.To(r.SendTo(Fixer, g.S.Grid.NearestFree(gp)!.Value));
                r.Is(g.GuardPose()!.Value.phase == "at café", "he is still with her");
                {
                    int alert = g.Alert;
                    r.Do(Fixer, "turn", GuardR, "pressure"); r.Done(Fixer);
                    r.Is(g.GuardP.Turned && g.Alert == alert, "turned, and no report");
                }
            }, known);

            Add("N26", "—", "Downed and carried (motive-fights.md §2.2, §1.1): the guard downs the Scout, who holds fire; the Fixer lifts him in 3 s; the carrier can't run or fire; the Scout's orders are refused.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r))));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Scout, "draw"); g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "stance", Stance = "hold" });
                r.Send(Fixer, "d:Office approach");
                r.Is(r.Until(() => r.Op(Scout).Down, T(30)), "the Scout is down");
                r.Refused(Scout, "move", "", "a downed operative takes no orders");
                r.To(r.SendTo(Fixer, r.Op(Scout).Pos));
                r.Do(Fixer, "carry", Scout);
                r.Eq(r.Op(Fixer).BusyEnd - g.Tick, T(g.R.CarryS), "lifting takes 3 s");
                r.Done(Fixer);
                r.Eq(r.Op(Fixer).Carrying, (OpId?)OpId.Scout, "the Fixer carries the Scout");
                var (ok, why) = g.Issue(new Order { Tick = g.Tick, Op = Fixer, Do = "move", To = "d:Getaway bay", Run = true });
                r.Is(!ok && why.Contains("carrying"), $"carrying, no run: {why}");
                r.Refused(Fixer, "fire", GuardR, "carrying, no fire");
                r.Send(Fixer, "d:Getaway bay"); r.Wait(T(5));
                r.Eq(r.Op(Scout).Pos, r.Op(Fixer).Pos, "the carried Scout goes where the Fixer goes");
                // carried is not yet safe (Waymark asked): only in the car (brief 018: Board, the carried first, 1 s + carry 3 s)
                r.Is(!G.Within(r.Op(Fixer).Pos, r.At("d:Getaway bay"), 2000) && g.LeftBehind().Contains((Scout, "captured", "downed")), "carried 20 m and more from the car, a Go now would leave him: captured, downed");
                r.Until(() => r.Op(Fixer).Walk == null, T(120));
                r.Is(G.Within(r.Op(Fixer).Pos, r.At("d:Getaway bay"), g.R.AtReachCm) && g.LeftBehind().Contains((Scout, "captured", "downed")), "carried to the car but not in it: still left behind");
                r.Do(Fixer, "board", "car");
                r.Eq(r.Op(Fixer).BusyEnd - g.Tick, T(g.R.BoardS + g.R.CarryS), "boarding carrying: 1 s + 3 s");
                r.Done(Fixer);
                r.Is(r.Op(Fixer).InCar && r.Op(Scout).InCar && !g.LeftBehind().Exists(x => x.op == Scout || x.op == Fixer), "both in the car: neither is left behind");
            });
        }
    }
}

sim/Suborned.Sim/ScenariosGetaway.cs.text:
// The getaway (brief 018, Motive; Sky 2026-10-18: "I want to get my team into the car, and get away"). On the real block, the promoted
// cast and the crowd, at the mission's own security level unless a case says otherwise.
//  N111 the hold and Go refused: the Scout boards empty-handed (1 s) before the ambush; one rival goes for the road; the ambush stops
//       hold nothing by standing; Go is refused car-held, naming the holders in id order (the Go card reads the same); in the car she
//       doesn't fire, and any shot at her is at one beside cover (×500)
//  N112 left behind, downed and fighting (§3 rows 1, 2): the guard downs the Scout; the Fixer boards and the car goes without Vale
//       (Withdrawn): the Scout captured downed, the Tech and the Enforcer captured fighting; custody holds 2 and 1 missions
//  N113 §4's twin of N95: route A, board and go with the crew unbroken (Board with Vale 4 s): the fight moves Standing 0; the three left
//       are captured fighting and the captures move nothing; the blocker is not replaced
//  N114 left behind, walked (§3 row 4): route A fought out (the crew broken), the car goes before any seal: the three walk out
//  N115 left behind, sealed (§3 row 3), and stepping out: N68's route G-kill without the final fight (the dead guard read by the camera:
//       the seal clock runs, nobody fights); the Fixer boards, steps out and back in; Go (Withdrawn): the three captured sealed
//  N116 seen leaving: the response unit passes the bay with the car in its cone; Go: +1 T, the car hunted, the car-seen line
//  N118 the menu's Withdraw stays a free abort: N112's fixture withdrawn from the menu captures nobody
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        const int Never = int.MaxValue / 4;
        /// <summary>East of the getaway bay, 14 m off, within 30 m of the patrol's sweep at its south end (patrol-a).</summary>
        static readonly Pt EastOfBay = new Pt(2200, -4500);

        /// <summary>Route A's Enforcer draws and walks Vale to the bay until the ambush springs.</summary>
        static void ToAmbush(Run r)
        {
            var g = r.G;
            r.Do(Enf, "draw");
            r.Send(Enf, "d:Getaway bay");
            while (!g.Over && g.FightSprung == Never)
            {
                if (supportTech && r.Op(Tech).Busy == null) { supportTech = false; r.Send(Tech, "crew:tech"); r.Do(Tech, "draw"); }
                g.Step();
            }
            supportTech = false;
        }
        /// <summary>The Enforcer walks the rest of the way to the car and boards with Vale; returns the ticks the Board took.</summary>
        static int BoardVale(Run r)
        {
            var g = r.G; var car = r.At("d:Getaway bay");
            if (!G.Within(r.Op(Enf).Pos, car, g.R.AtReachCm)) { int at = r.SendTo(Enf, r.Stand("d:Getaway bay")); while (!g.Over && g.Tick < at) g.Step(); }
            r.Do(Enf, "board", "car"); int took = r.Op(Enf).BusyEnd - g.Tick; r.Done(Enf); if (!g.Over) g.Step();
            return took;
        }
        /// <summary>The Scout, the Fixer and the Tech walk to their start points by the car (crew:*) and draw: they will draw the ambush's fire.</summary>
        static void Support(Run r)
        {
            var g = r.G; supportTech = true;
            r.Send(Scout, "crew:scout"); r.Send(Fixer, "crew:fixer"); r.Do(Scout, "draw"); r.Do(Fixer, "draw"); // no waiting: the Enforcer goes at once (a man held still is seen)
        }
        [ThreadStatic] static bool supportTech; // the Tech follows to crew:tech once his reroute lands (ToAmbush)
        /// <summary>The hostiles up and present, optionally sparing the blocker.</summary>
        static List<string> Targets(Game g, bool spareBlocker) { var l = new List<string>(); foreach (var h in g.Hostiles) if (h.Present && !h.Down && h.Gun.St != "break" && h.Gun.St != "gone" && !(spareBlocker && h.Blocker)) l.Add(h.Id); return l; }
        /// <summary>The Enforcer walks Vale into the car while the three by the car fire on the ambush from their posts (the blocker spared or not);
        /// returns the ticks the Board took.</summary>
        static int CoveredBoarding(Run r, bool spareBlocker)
        {
            var g = r.G; string[] sup = { Scout, Fixer, Tech };
            int at = r.SendTo(Enf, r.Stand("d:Getaway bay"));
            r.Engage(() => Targets(g, spareBlocker), () => g.Tick >= at, 60, sup, false, advance: false);
            if (g.Over) return -1;
            r.Do(Enf, "board", "car"); int took = r.Op(Enf).BusyEnd - g.Tick;
            r.Engage(() => Targets(g, spareBlocker), () => r.Op(Enf).InCar, 10, sup, false, advance: false);
            return took;
        }
        /// <summary>The Enforcer walks Vale into the car while the three by the car fire on the blocker alone, from their posts.</summary>
        static void BlockerOnly(Run r)
        {
            var g = r.G; string[] sup = { Scout, Fixer, Tech }; var b = g.Hostiles.Find(h => h.Blocker);
            List<string> t() => b == null || b.Down || b.Gun.St == "break" || b.Gun.St == "gone" ? new List<string>() : new List<string> { b.Id };
            int at = r.SendTo(Enf, r.Stand("d:Getaway bay"));
            r.Engage(t, () => g.Tick >= at, 60, sup, false, advance: false);
            if (g.Over) return;
            r.Do(Enf, "board", "car");
            r.Engage(t, () => r.Op(Enf).InCar, 10, sup, false, advance: false);
            r.Engage(t, () => t().Count == 0, 60, sup, false, advance: true);
        }
        /// <summary>Board and go, covered (brief 018 §5): the Enforcer walks Vale straight to the car while the three by it fire on the blocker
        /// alone, then on whoever is up to draw the fire off him (rivals shoot whoever last shot at them), until he is in with Vale; then they hold.</summary>
        static void CoveredBoardAndGo(Run r, bool go, bool draw = true)
        {
            var g = r.G; string[] sup = { Scout, Fixer, Tech };
            int at = r.SendTo(Enf, r.Stand("d:Getaway bay"));
            DownBlocker(r, sup);
            if (!draw) foreach (var op in sup) { g.Issue(new Order { Tick = g.Tick, Op = op, Do = "cease" }); g.Issue(new Order { Tick = g.Tick, Op = op, Do = "stance", Stance = "hold" }); }
            if (draw) r.Engage(() => Targets(g, false), () => g.Tick >= at, 60, sup, false, advance: false);
            else DrawFire(r, () => g.Tick >= at, 60);
            if (g.Over) return;
            r.Do(Enf, "board", "car");
            if (draw) r.Engage(() => Targets(g, false), () => r.Op(Enf).InCar, 10, sup, false, advance: false);
            else DrawFire(r, () => r.Op(Enf).InCar, 10);
            foreach (var op in sup) { g.Issue(new Order { Tick = g.Tick, Op = op, Do = "cease" }); g.Issue(new Order { Tick = g.Tick, Op = op, Do = "stance", Stance = "hold" }); }
            if (go && !g.Over) r.Is(r.Do("cell", "go"), "Go");
        }
        /// <summary>Draw the fire off the Enforcer (brief 018 §5: rivals shoot whoever last shot at them) without breaking the crew: each of the
        /// three by the car fires one shot at a rival aiming at him, ceases, and fires again only when that rival's grudge (weapons.lineLapse) is
        /// about to lapse. Runs until `until` or the run ends.</summary>
        static void DrawFire(Run r, Func<bool> until, int limitS)
        {
            var g = r.G; string[] sup = { Scout, Fixer, Tech }; var last = new Dictionary<string, int>(); int seen = g.Log.Count, end = g.Tick + T(limitS);
            while (!until() && !g.Over && g.Tick < end)
            {
                for (; seen < g.Log.Count; seen++)
                {
                    var l = g.Log[seen]; if (l.Code != "shot.hit" && l.Code != "shot.miss") continue;
                    foreach (var s in sup) if (l.Text.StartsWith(s + " fires on ", StringComparison.Ordinal)) { last[s] = l.Tick; g.Issue(new Order { Tick = g.Tick, Op = s, Do = "cease" }); }
                }
                foreach (var s in sup)
                {
                    var o = r.Op(s); if (o.Down || o.InCar || o.Busy != null || o.Gun.W == null || o.Gun.Order.Length > 0) continue;
                    if (last.TryGetValue(s, out var t0) && g.Tick - t0 < T(g.R.LineLapseS) - 5) continue;
                    string best = ""; long bd = long.MaxValue;
                    foreach (var h in g.Hostiles)
                    {
                        if (!h.Present || h.Down || h.Gun.St == "break" || h.Gun.St == "gone" || h.Gun.Target != Enf) continue;
                        var p = h.Pos(g.Tick); long d = G.D2(o.Pos, p);
                        if (d < bd && d <= (long)o.Gun.W.MaxCm * o.Gun.W.MaxCm && g.S.Sight(o.Pos, p, g.R.Eye)) { bd = d; best = h.Id; }
                    }
                    if (best.Length > 0) g.Issue(new Order { Tick = g.Tick, Op = s, Do = "fire", Target = best });
                }
                g.Step();
            }
        }
        /// <summary>Fire on the blocker alone until it is down, broken or gone.</summary>
        static void DownBlocker(Run r, params string[] ops)
        {
            var g = r.G; var b = g.Hostiles.Find(h => h.Blocker);
            if (b == null) return;
            r.Engage(() => b.Down || b.Gun.St == "break" || b.Gun.St == "gone" ? new List<string>() : new List<string> { b.Id }, () => b.Down || b.Gun.St == "break" || b.Gun.St == "gone", 120, ops, true);
        }
        static Order Go(Game g) => new Order { Tick = g.Tick, Op = "cell", Do = "go" };
        static (string op, string fate, string why) FateOf(Game g, string op) => g.LeftBehindAtGo.Find(x => x.op == op);
        /// <summary>Shots in the log at a target after a tick: (shooter, metres, per mille).</summary>
        static List<(string by, int m, int pm)> ShotsAt(Game g, string target, int after)
        {
            var l = new List<(string, int, int)>();
            foreach (var x in g.Log)
            {
                if (x.Tick <= after || (x.Code != "shot.hit" && x.Code != "shot.miss")) continue;
                int i = x.Text.IndexOf(" fires on " + target + " at ", StringComparison.Ordinal); if (i < 0) continue;
                var rest = x.Text.Substring(i + (" fires on " + target + " at ").Length);
                int m = int.Parse(rest.Substring(0, rest.IndexOf(' ')), CultureInfo.InvariantCulture);
                int p0 = rest.IndexOf('(') + 1; int pm = int.Parse(rest.Substring(p0, rest.IndexOf(' ', p0) - p0), CultureInfo.InvariantCulture);
                l.Add((x.Text.Substring(0, i), m, pm));
            }
            return l;
        }

        static void GetawayCases()
        {
            Add("N111", "—", "The hold and Go refused (brief 018 §1, §2): route A, quiet. The Scout walks to the car and boards empty-handed (1 s) before the ambush. When it springs one rival (fight.blockers) goes for the road, to a point in the exit lane (site getaway.exit); the other ambush stops, 12–19 m off, hold nothing by standing there. Go (someone is in the car) is refused car-held while the blocker stands in the lane, and the refusal names every holder in id order; the Go card (GoQuery) reads the same. In the car the Scout doesn't fire, and any shot at her there is at one beside cover (×500).", r =>
            {
                var g = r.G; var car = r.At("d:Getaway bay");
                RouteA(r, reroute: true);
                int at = r.Send(Scout, "d:Getaway bay"); r.Send(Fixer, "crew:fixer"); r.Do(Fixer, "draw"); r.Do(Scout, "draw");
                r.Do(Enf, "draw"); r.Send(Enf, "d:Getaway bay");
                int boarded = -1;
                while (!g.Over && g.FightSprung == Never)
                {
                    if (boarded < 0 && g.Tick >= at && r.Op(Scout).Busy == null) { r.Do(Scout, "board", "car"); boarded = r.Op(Scout).BusyEnd - g.Tick; }
                    g.Step();
                }
                r.Eq(boarded, T(g.R.BoardS), "the Scout boards empty-handed: 1 s");
                r.Is(r.Op(Scout).InCar && g.Vale != ValeAt.Car, "the Scout is in the car before the ambush, without Vale");
                r.Eq(g.Blockers.Count, g.R.Blockers, "one hostile goes for the road (fight.blockers)");
                var b = g.Hostiles.Find(h => h.Blocker);
                if (!r.Is(b != null, "the blocker is one of the ambush")) return;
                r.Is(b!.Id.StartsWith("rival-", StringComparison.Ordinal) && g.S.InExitLane(b.Home), $"the blocker ({b.Id}) makes for a point in the exit lane");
                r.Is(!G.Within(b.Home, car, g.R.BlockNearCm - 1) && G.Within(b.Home, car, g.R.BlockFarCm), $"its post is in the 10–13 m ring from the car, not at the door ({b.Gun.Cover}, {G.Dist(b.Home, car) / 100} m; brief 018 §10)");
                bool holdsWhere(string id) { var h = g.Hostiles.Find(x => x.Id == id); var p = h != null ? h.Pos(g.Tick) : g.PosOf(id)!.Value; return G.Within(p, car, g.R.HoldCm) || g.S.InExitLane(p); }
                r.Is(g.CarHolders().TrueForAll(holdsWhere), "every holder stands within 8 m of the car or in the lane");
                r.Is(g.Hostiles.Exists(h => !h.Blocker && !h.Down && !g.CarHolders().Contains(h.Id)), "the ambush stops hold nothing by standing there");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "fire", Target = "hostiles" }).code, "fire-carrying-vale", "walking Vale, the Enforcer doesn't fire (brief 018, Waymark c018)");
                r.Engage(() => Targets(g, true), () => g.CarHolders().Contains(b.Id), 30, new[] { Enf, Fixer }, false, advance: false); // the rest fight on, sparing the blocker
                r.Is(!r.Shots().Exists(x => x.by == Enf), "and fires nothing while he holds her");
                r.Is(g.CarHolders().Contains(b.Id) && !g.Over, $"the blocker in the lane holds the car ({Report.Clock(g.Tick)})");
                var a = g.Issue(Go(g));
                r.Eq((a.ok, a.code), (false, "car-held"), "Go is refused while the car is held");
                r.Eq(a.ids, string.Join(",", g.CarHolders()), "the refusal names the holders, in id order");
                r.Is(a.ids.Split(',').Contains(b.Id), $"the blocker is among them ({a.ids})");
                var q = g.GoQuery();
                r.Eq((q.ok, q.code, q.ids), (a.ok, a.code, a.ids), "the Go card reads the same");
                r.Refused(Scout, "fire", "hostiles", "in the car the Scout doesn't fire");
                int from = g.Tick; r.Wait(T(20));
                r.Is(!r.Shots().Exists(x => x.tick > from && x.by == Scout), "she fires nothing from the car");
                var shots = ShotsAt(g, Scout, from);
                bool cover(int m, int pm) { for (int d = m * 100; d < m * 100 + 100; d++) if (g.R.Accuracy(g.R.Pistol, d, false, g.R.ModCover, false, true) == pm) return true; return false; }
                r.Is(shots.TrueForAll(x => cover(x.m, x.pm)), $"any shot at her in the car is at one beside cover, ×500 ({shots.Count} shots: {string.Join(", ", shots.Select(x => x.pm))} ‰)");
            });

            Add("N112", "—", "Left behind, downed and fighting (brief 018 §3 rows 1 and 2), and Go without Vale: the guard downs the Scout in front of the Office (N26's fixture); the Fixer boards the empty car and the car goes. The outcome is Withdrawn and the left-behind rules apply: the Scout is captured downed; the Tech and the Enforcer, standing while the guard still fights, are captured fighting. Custody (campaign.custody, founding cell bravery 2, loyalty 3): downed holds 2 missions (talks at the third questioning, 3 + 0 > 2 + 0), abandoned holds 1 (2 + 1 > 2 + 0); +4 T each to the campaign; a captive gives every face, the car and place and time.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r))));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Scout, "draw"); g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "stance", Stance = "hold" });
                int at = r.Send(Fixer, "d:Getaway bay");
                r.Is(r.Until(() => r.Op(Scout).Down, T(30)), "the guard downs the Scout");
                r.To(Math.Max(g.Tick, at));
                r.Is(g.LeftBehind().Contains((Scout, "captured", "downed")), "the Go card: the Scout would be captured, downed");
                r.Do(Fixer, "board", "car"); r.Eq(r.Op(Fixer).BusyEnd - g.Tick, T(g.R.BoardS), "boarding empty-handed: 1 s"); r.Done(Fixer); g.Step();
                r.Is(r.Op(Fixer).InCar && g.Vale != ValeAt.Car, "the Fixer is in the car, without Vale");
                var lb = g.LeftBehind();
                var a = g.Issue(Go(g));
                r.Is(a.ok, $"Go is taken: nothing holds the car ({a.why})");
                r.Eq(g.Result, Outcome.Withdrawn, "Go without Vale: the cell withdraws by car");
                r.Eq(g.LeftBehindAtGo.Count, 3, "everyone not in the car is left behind");
                r.Is(g.LeftBehindAtGo.SequenceEqual(lb), "as the Go card said");
                r.Eq(FateOf(g, Scout), (Scout, "captured", "downed"), "downed, not in the car: captured");
                r.Eq(FateOf(g, Tech), (Tech, "captured", "fighting"), "standing while the guard still fights: captured");
                r.Eq(FateOf(g, Enf), (Enf, "captured", "fighting"), "the Enforcer too");
                r.Eq(string.Join(",", g.Captured), "scout,tech,enforcer", "captures only at Go, in the cell's order");
                var d = Debrief.Of(g); var next = d.Next;
                var sc = next.Captives.Find(c => c.Op == Scout); var te = next.Captives.Find(c => c.Op == Tech);
                if (!r.Is(sc != null && te != null && next.Captives.Count == 3, "three captives in the debrief")) return;
                r.Eq((sc!.Why, sc.Holds, sc.TalksAt, sc.Sc[Rules.Fear], sc.Sc[Rules.Resentment], sc.Sc[Rules.Bravery], sc.Sc[Rules.Loyalty]), ("downed", 2, 3, 3, 0, 2, 0), "downed: holds 2 missions, talks at the third (3 + 0 > 2 + 0)");
                r.Eq((te!.Why, te.Holds, te.TalksAt, te.Sc[Rules.Fear], te.Sc[Rules.Resentment], te.Sc[Rules.Bravery], te.Sc[Rules.Loyalty]), ("fighting", 1, 2, 2, 1, 2, 0), "abandoned: holds 1 mission, talks at the second (2 + 1 > 2 + 0)");
                r.Is(sc.HeldAt.Length > 0 && sc.RescueUntil == g.R.CustodyMissions, $"held at {sc.HeldAt}; a rescue for {sc.RescueUntil} missions");
                r.Is(sc.Facts.Take(6).SequenceEqual(new[] { "cell-face:scout", "cell-face:fixer", "cell-face:tech", "cell-face:enforcer", "cell-car", "place-time" }), $"a captive gives every face, the car, place and time ({string.Join(", ", sc.Facts)})");
                r.Is(next.CampaignTrail >= 3 * g.R.CapturedTrail, $"+4 T each to the campaign ({next.CampaignTrail})");
                r.Eq(next.Lines.Count(l => l.Line == "left-behind"), 3, "a left-behind line each");
                r.Eq(next.Lines.Count(l => l.Line == "captive"), 3, "a captive line each");
                r.Eq(d.LeftBehind.Count, 3, "the debrief carries who was left");
                var fc = CauseIs(r, "withdraw", "car-left-without-vale", false, "getaway-car", "car", ""); // the fail camera (ScenariosFailCause.cs): the car that left without him
                r.Is(fc != null && fc.Culprits[0].At == r.At(g.S.GetawayCar) && d.Cause == fc, "at the getaway bay; the debrief carries the same cause");
            });

            Add("N113", "—", "§4's twin of N95 (brief 018 §4): route A, quiet, the feared rivals' ambush; the three by the car down the blocker and draw the fire while the Enforcer walks Vale in, and the car goes with the crew unbroken. The final fight is judged when the car leaves: public, but no outcome holds (driven off needs the crew broken): Standing 0 from the fight, cause none; Inez's word still adds +1 between missions (+2 → +3). The three left by the car are captured fighting: the captures move nothing. The blocker is not replaced.", r =>
            {
                var g = r.G;
                r.Eq(g.RivalsPublic, "menace", "the Handover's rivals are feared");
                RouteA(r, reroute: true);
                Support(r);
                ToAmbush(r);
                var b = g.Hostiles.Find(h => h.Blocker)!;
                CoveredBoardAndGo(r, go: false, draw: false); // the three by the car down the blocker and draw the fire while the Enforcer boards
                r.Is(!g.CarHeld() && (b.Down || b.Gun.St == "break" || b.Gun.St == "gone"), $"the car is free: the blocker {b.Id} is down");
                r.Is(g.Hostiles.Exists(h => h.Present && !h.Down && h.Gun.St != "break" && h.Gun.St != "gone"), "the crew is not broken");
                r.Eq(g.Hostiles.Count(h => h.Blocker), 1, "the job of the road did not pass on");
                var bo = g.Log.FindAll(l => l.Code == "blocker.out"); var cf = g.Log.FindAll(l => l.Code == "car.free");
                // 2026-10-19 (Keel, brief 023; the west-face door): the three down rival-1 before he reaches the lane, so the car is never held and
                // no car.free is logged; "blocker.out, then car.free" is checked in N95, where he holds the lane first
                r.Is(bo.Count == 1 && cf.TrueForAll(l => l.Tick >= bo[0].Tick), $"logged by code: blocker.out, and no car.free before it ({string.Join(", ", bo.Concat(cf).Select(l => l.Code + "@" + Report.Clock(l.Tick)))})");
                r.Is(r.Do("cell", "go"), "Go");
                r.Eq(g.Result, Outcome.Success, "Vale in the car when it leaves: the win");
                if (!r.Is(g.Fights.Count == 1, $"one fight: the final fight ({g.Fights.Count})")) return;
                var f = g.Fights[0];
                r.Eq((f.Final, f.Public, f.Outcome, f.Delta), (true, true, "none", 0), "judged when the car leaves: the crew unbroken, Standing 0");
                r.Eq(f.End, g.CarLeftTick, "it ends with the mission, at the tick the car leaves");
                r.Eq(FightMoves(g).Count, 0, "no move from the fight");
                r.Is(g.LeftBehindAtGo.Count == 3 && g.LeftBehindAtGo.TrueForAll(x => x.fate == "captured" && x.why == "fighting"), "the rest, left while the crew fights on, are captured fighting");
                r.Eq(g.StandingMoves.Count, 0, "the captures move nothing");
                var next = g.BetweenMissions(g.Investigate());
                var l = OneLine(r, next);
                r.Eq((l.From, l.End, l.Word, l.To), (2, 2, 1, 3), "2 + 0 the fight + 1 Inez's word = +3 (Motive's board-and-go row)");
                r.Eq(next.Captives.Count, 3, "three captives");
                r.Is(next.Captives.TrueForAll(c => c.Holds == 1 && c.Facts.Contains("contact:" + g.Inez.Id)), "each holds 1 mission and would give Inez as a contact");
            });

            Add("N114", "—", "Left behind, walked (brief 018 §3 row 4): route A fought out until the crew breaks (FightItOutAll; with the blocker on the road, the car comes free before the crew breaks), the Enforcer boards with Vale and the car goes before the guard's missed check-in (the rivals downed him) calls security. The fight is over and no seal runs: the three left walk out, nobody is captured, no captive in the debrief. The fight +1 (the crew driven off).", r =>
            {
                var g = r.G;
                RouteA(r, reroute: true);
                Support(r); ToAmbush(r); // brief 018: walking Vale the Enforcer doesn't fire; the three by the car fight
                r.FightItOutAll(120, Scout, Fixer, Tech); // brief 018 §10: the blocker on the road falls first, so fight on until the crew breaks
                r.Is(g.FightOverTick != Never, "the fight is over: the crew broken");
                BoardVale(r);
                r.Is(g.Lockdown == Never, "no seal clock");
                r.Is(r.Do("cell", "go"), "Go");
                r.Eq(g.Result, Outcome.Success, "the win");
                r.Is(g.LeftBehindAtGo.Count == 3 && g.LeftBehindAtGo.TrueForAll(x => x.fate == "walked" && x.why == "walked"), $"the fight over and no seal: the three left walk out ({string.Join("; ", g.LeftBehindAtGo)})");
                r.Eq(g.Captured.Count, 0, "nobody captured");
                var next = Debrief.Of(g).Next;
                r.Is(next.Captives.Count == 0 && next.Lines.Count(l => l.Line == "left-behind" && l.Detail == "walked (walked)") == 3, "no captive; three walked lines");
                r.Eq(FightMoves(g).Sum(m => m.delta), 1, "the crew driven off: +1");
            });

            Add("N115", "—", "Left behind, sealed (brief 018 §3 row 3), and stepping out (§2): N68's route G-kill without the final fight (the dead guard left at his post; the entrance camera reads him when the Tech leaves the cabinet: Alert 2, the response called, the seal clock running). Nobody has fought the cell. The Fixer walks to the car and boards (1 s), steps out at the car's side (1 s) and boards again; Go before the seal (Withdrawn: no Vale) leaves the Scout, the Tech and the Enforcer (inside with Vale) standing under the seal: captured sealed.", r =>
            {
                var g = r.G;
                Orders(r, new Order { Tick = 0, Op = Tech, Do = "move", To = "cabinet", Run = true }, MvTo(0, Enf, BesideDoor), Mv(0, Scout, "d:Office approach"), Mv(0, Fixer, "crew:fixer"),
                    Act(166, Tech, "loop", "entrance"), Act(462, Scout, "watch", "guard"), Mv(662, Scout, "crew:scout"), Act(1060, Tech, "reroute", "patrol"), // c022's route G-kill timings (N68)
                    MvTo(1440, Enf, BesideGuard), Act(1510, Enf, "takedown", "guard", "kill"), Act(1540, Enf, "enter"),
                    MvTo(1540, Tech, new Pt(675, -4625)), MvTo(1540, Scout, new Pt(1175, -4825)), Mv(1540, Fixer, "d:Getaway bay"));
                r.Is(r.Until(() => g.Lockdown != Never, T(120)) && !g.Over, $"the seal clock runs ({Report.Clock(g.Tick)}; seal {Report.Clock(g.Lockdown)})");
                r.Until(() => r.Op(Fixer).Walk == null, T(60));
                r.Do(Fixer, "board", "car"); r.Done(Fixer); g.Step();
                var a = g.Issue(new Order { Tick = g.Tick, Op = Fixer, Do = "move", To = "d:Getaway bay" });
                r.Is(a.ok && r.Op(Fixer).BusyEnd - g.Tick == T(g.R.BoardS), $"a move on a boarded operative: 1 s to step out ({a.why})");
                r.Done(Fixer); g.Step();
                r.Is(!r.Op(Fixer).InCar && r.Op(Fixer).Pos == r.Stand("d:Getaway bay"), "out at the car's side");
                r.Do(Fixer, "board", "car"); r.Eq(r.Op(Fixer).BusyEnd - g.Tick, T(g.R.BoardS), "back in: 1 s"); r.Done(Fixer); g.Step();
                r.Is(g.Lockdown != Never && g.Tick < g.Lockdown && !g.Over, "the seal clock runs, not yet sealed");
                r.Is(r.Do("cell", "go"), "Go before the seal");
                r.Eq(g.Result, Outcome.Withdrawn, "no Vale: the cell withdraws by car");
                r.Is(g.LeftBehindAtGo.Count == 3 && g.LeftBehindAtGo.TrueForAll(x => x.fate == "captured" && x.why == "sealed"), $"nobody fights, but the seal clock runs: captured, sealed ({string.Join("; ", g.LeftBehindAtGo)})");
                r.Is(Debrief.Of(g).Next.Captives.TrueForAll(c => c.Why == "sealed" && c.Holds == 1), "left standing: abandoned, each holds 1 mission");
            }, NoFight());

            Add("N116", "—", "Seen leaving (brief 018 §3; Sky 2026-10-18 answer 5), at level 1: the Fixer waits in the car while the Enforcer shoots the guard at the door; the response unit comes in from the north street and passes the bay with the car in its officers' cone. Go then (no Vale: Withdrawn) makes the departure one witnessed incident, +1 T (witness-trail), and the investigation hunts the car (cell-car); the debrief's car-seen line. The officers on the street are not holders: they stand outside 8 m and the lane. (On this block a loud final fight's officers hold stands the car is hidden from, or 19.4 m off, past security's 19 m: Keel's probe.)", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor), r.Send(Fixer, "d:Getaway bay")));
                r.Do(Tech, "loop", "entrance"); r.Done(Tech); r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Fixer, "board", "car"); r.Done(Fixer);
                r.Fire(Enf, GuardR); r.Until(() => g.GuardDown, T(30));
                r.Is(r.Until(() => g.CarWatcher().Length > 0, T(120)), $"the response unit has the car in sight ({Report.Clock(g.Tick)}: {g.CarWatcher()})");
                var watcher = g.CarWatcher();
                r.Is(watcher.StartsWith("security-", StringComparison.Ordinal) && !g.CarHeld(), "a response officer, and nothing holds the car");
                int trail = g.Trail;
                r.Is(r.Do("cell", "go"), "Go");
                r.Eq((g.Result, g.CarSeenBy, g.Trail - trail), (Outcome.Withdrawn, watcher, g.R.WitnessTrail), "seen leaving: +1 T");
                r.Is(g.Ledger.Exists(x => x.what == "trail" && x.cause == "car-seen:" + watcher), "the ledger names it");
                var d = Debrief.Of(g);
                r.Is(d.Inv.Hunted.Contains("cell-car"), "the investigation hunts the car");
                r.Is(d.Next.Lines.Exists(l => l.Line == "car-seen" && l.Who == watcher), "the debrief's car-seen line");
            }, Level(1));

            Add("N118", "—", "The menu's Withdraw stays a free abort (Sky 2026-10-18 answer 4): N112's fixture, the Scout downed, withdrawn from the menu instead of by car: nobody is captured, nobody is left behind.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r))));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Scout, "draw"); g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "stance", Stance = "hold" });
                r.Is(r.Until(() => r.Op(Scout).Down, T(30)), "the guard downs the Scout");
                r.Is(g.Do(new Order { Tick = g.Tick, Op = "cell", Do = "withdraw" }), "withdraw");
                r.Eq((g.Result, g.Captured.Count, g.LeftBehindAtGo.Count), (Outcome.Withdrawn, 0, 0), "a free abort: nobody captured");
            });
        }

        /// <summary>N10's loud route to the car: the guard shot, the Enforcer in and out with Vale, the cell drawn, the Enforcer walking Vale to the car.</summary>
        static void LoudToCar(Run r)
        {
            var g = r.G;
            r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
            r.Do(Tech, "loop", "entrance"); r.Done(Tech); r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
            int mark = g.NextMarkOf(g.GuardP, g.Tick); if (mark - g.Tick < T(30)) r.To(mark + 1);
            r.Fire(Enf, GuardR); r.Until(() => g.GuardDown, T(30));
            r.To(r.Send(Enf, "d:Office entrance"));
            r.Do(Enf, "enter"); r.Done(Enf);
            r.Eq(g.FightBranch, "loud", "a loud final fight");
            foreach (var op in new[] { Scout, Fixer, Tech }) r.Do(op, "draw");
            r.Send(Enf, "d:Getaway bay");
        }
    }
}

sim/Suborned.Sim/ScenariosHandover.cs.text:
// S01–S28: the top-down test's scenarios on the real block. "proto" is the prototype test's line. What changed and why is said in
// each; the common changes are: actions take their rulebook time and land at its end (the prototype landed them at once); Watch
// reveals the routine only and Listen the need and temperament (Sky 2026-10-15); who plays each role, and their temperament, is the
// promoted cast's (sim/data/handover.site.json cast, M-2): a scenario that plays the mission reads the card as a player would (route A
// helps Inez until the card's "turned" lands), and one that tests a single temperament's rule names it in its start state; places are the civic block's (sim/data/handover.site.json); the guard walks 45 s
// (mission.json windows.front-door); the mission is over at the close mission.json gives (§07 8:00; Sky moves it to 8:30; the prototype ran to 9:50).
using System;
using System.Collections.Generic;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        const string Scout = "scout", Fixer = "fixer", Tech = "tech", Enf = "enforcer";
        const string Inez = "waitress", Driver = "driver", GuardR = "guard", Vale = "councillor";
        static readonly Pt Roof = new Pt(6400, -3000); // inside the Records Office
        // where the Enforcer stands to shoot the guard unseen: beside the public door, outside his door cone and the pickup camera.
        // Re-sited 2026-10-19 with the door (Sky's option (b): the public door on the Office's west face): 5.6 m south of the door on the
        // forecourt, where Waymark's c022 routes park him (route G, loud); was (4850, -2300) beside the old north door. The entrance
        // camera, which now looks south along the face, sees it unless looped; the patrol's sweep crosses it.
        static readonly Pt BesideDoor = new Pt(6950, -4250);
        // posts covering the service lane exit, 10 m down the lane from where the response unit stops (motive-fights.md §2.9: the cell covers the exit).
        // Re-sited 2026-10-19: the service door is on the east face, in a quiet yard the unit enters from the north; the posts are at
        // its south end. Were (62.5, -53) and (60, -53), down the old lane west of the Office.
        static readonly Pt LanePostA = new Pt(7050, -1680), LanePostB = new Pt(7050, -1450);
        static Start NoFight() { var s = new Start(); s.FinalFight = false; return s; }
        static Start Level(int level) { var s = new Start(); s.Security = level; return s; } // brief 013: the response dial's level, fixed
        /// <summary>S11's cover for the exit: the Scout here, the Fixer 2.5 m north, the Tech 2.5 m west, on the response unit's way from the
        /// north street to the Office approach. Moved 2026-10-19 (Keel, brief 023; the door on the west face) from (4500, -3500), where the
        /// unit came into reach 1 s too late, 10 m back toward the square, so they meet it earlier on the same walk.</summary>
        static readonly Pt S11Post = new Pt(3500, -4000);
        /// <summary>S14: where the Enforcer withdraws once the guard is down, round the Office's south-west corner toward the official side,
        /// off the response unit's way to the Office approach. Added 2026-10-19 (Keel, brief 023): with the door on the west face the unit
        /// reaches the approach before the 4:00 mark and downed the Enforcer standing there, ending the run before the mark it tests.</summary>
        static readonly Pt S14Away = new Pt(7250, -4000);
        static Start Turned(params string[] roles) { var s = new Start(); s.Turned.AddRange(roles); return s; }
        static int Max(params int[] xs) { int m = int.MinValue; foreach (var x in xs) m = Math.Max(m, x); return m; }

        /// <summary>Turn the driver as a player reads the card after Listen: the approach that turns him in one order, else Help again
        /// until he turns. (The cast decides: a Mercenary driver takes Pay; an Idealist would take one Help.)</summary>
        static void TurnDriver(Run r)
        {
            var g = r.G;
            string a = g.Preview("help", Driver).Outcome == "turned" ? "help" : g.Preview("pay", Driver).Outcome == "turned" ? "pay" : "help";
            r.Do(Fixer, "turn", Driver, a); r.Done(Fixer);
            while (!g.Driver.Turned && !g.Over && a == "help") { r.Do(Fixer, "turn", Driver, a); r.Done(Fixer); }
        }

        /// <summary>Help a person as route A does (§07: the Fixer helps Inez), reading the card as a player would: Help again while she is
        /// not yet turned (one Help turns an Idealist; a Fearful person needs Help ×2, a Loyal one trust over time; §04). The cast decides how
        /// many; a card that reads "refused" is not given, and the scenario's check says so.</summary>
        static void HelpUntilTurned(Run r, string role, int most = 4)
        {
            var g = r.G; var p = g.PersonByRole(role);
            for (int i = 0; i < most && !p.Turned && !g.Over; i++)
            {
                if (!r.Is(g.Preview("help", role).Outcome != "refused", $"the card for Help on {role} does not read refused")) return;
                r.Do(Fixer, "turn", role, "help"); r.Done(Fixer);
            }
        }

        /// <summary>Route A as S10 plays it, to the moment the Enforcer comes out with Vale.</summary>
        static void RouteA(Run r, bool reroute = false)
        {
            var g = r.G;
            r.To(Max(r.Send(Scout, "d:Courtyard"), r.Send(Tech, "cabinet")));
            r.Do(Scout, "watch", Inez); r.Do(Tech, "loop", "entrance"); r.Done(Scout);
            r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez);
            r.Send(Fixer, "d:Courtyard"); r.SendTo(Enf, new Pt(4900, -1700));
            r.Done(Scout); HelpUntilTurned(r, Inez);
            while (!g.SweepSeesEntrance(g.Tick)) g.Step();
            r.Do(Fixer, "call", Inez);
            r.To(r.Send(Enf, "d:Office entrance"));
            while (g.PatrolWatching(r.At("d:Office entrance"))) g.Step();
            r.Do(Enf, "enter");
            if (reroute) r.Do(Tech, "reroute", "patrol");
            r.Done(Enf);
        }

        static void Handover()
        {
            Add("S01", "13", "The pickup camera covers the car, the entrance camera the door; neither sees through the Office; a loop blinds the entrance camera.", r =>
            {
                var g = r.G;
                r.Is(g.CameraWatching("pickup", r.At("d:Official drop-off")), "the pickup camera covers Vale's car");
                r.Is(!g.CameraWatching("pickup", Roof), "the pickup camera does not see through the Office");
                r.Is(g.CameraWatching("entrance", r.Stand("d:Office entrance")), "the entrance camera covers the door");
                r.Is(!g.CameraWatching("entrance", Roof), "the entrance camera does not see into the Office");
                // FIX → orders: the prototype set the loop directly; here the Tech walks to the cabinet and loops it
                r.To(r.Send(Tech, "cabinet")); r.Do(Tech, "loop", "entrance"); r.Done(Tech);
                r.Is(!g.CameraWatching("entrance", r.Stand("d:Office entrance")), "a loop blinds the entrance camera");
            });

            Add("S02", "23", "5:50 Vale leaves; the unturned driver waits at the pickup; Vale walks in live time; 6:10 he is at the car.", r =>
            {
                var g = r.G;
                r.To(T(350));
                r.Eq(g.Vale, ValeAt.Leaving, "at 5:50 Vale is leaving");
                r.Eq(g.ValePos(), (Pt?)r.Stand("d:Official entrance"), "Vale comes out of the official entrance");
                r.Eq(g.CarPos(), r.At("d:Official drop-off"), "the unturned driver waits at the pickup");
                r.To(T(360));
                var mid = g.ValePos()!.Value;
                r.Is(mid != r.Stand("d:Official entrance") && mid != g.CarPos(), "Vale walks toward the car in live time");
                r.To(T(370));
                r.Eq(g.Vale, ValeAt.Pickup, "at 6:10 Vale is at the car");
                r.Eq(g.ValePos(), (Pt?)g.CarPos(), "Vale stands at the official car");
            });

            Add("S03", "36", "Called, the guard walks away in live time; behind him the Enforcer is out of his cone; a far shot leaves Inez unwitnessed; his 3 health drops him (Sky 2026-10-15 fights: health, not 2 hits); Alert 2.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Enf, new Pt(4600, -2600))); // behind the guard's walk to the café (the prototype's 46, 63 behind the door)
                r.Do(Fixer, "call", Inez);
                var atCall = g.GuardPose()!.Value.pos;
                r.Wait(T(10));
                var walking = g.GuardPose()!.Value;
                r.Is(walking.pos != atCall, "the guard walks away from the door in live time");
                r.Eq(walking.phase, "walking to café", "the guard is walking to the café");
                r.Is(!g.GuardWatching(r.Op(Enf).Pos), "behind the walking guard the Enforcer is out of his view");
                int trail = g.Trail;
                r.Fire(Enf, GuardR);
                r.Is(r.Until(() => g.GuardDown, T(30)), "fired on until down, the guard drops");
                r.Is(!g.InezWitnessedShooting, "Inez cannot witness a shot far from her café");
                r.Eq(g.Trail - trail, 6, "+2 T the shooting, +2 T the person hit, +2 T the down (once each, not per shot; Motive addendum Q1)");
                r.Eq(g.Alert, 2, "unwitnessed gunfire raises Alert to 2 (§05 any gunfire)");
            }, Turned(Inez)); // FIX → start state: Inez turned before the mission (the prototype set contacts.inez)

            Add("S04", "56", "Shooting the guard at the café: Inez witnesses, Alert 3 at once, no instant fail, the response comes in 12 s.", r =>
            {
                var g = r.G;
                r.To(r.Send(Enf, "d:Between tables")); // 7.3 m from the café door, behind where the guard will stand
                r.Do(Fixer, "call", Inez);
