            });

            Add("N12", "—", "People step their routines (§04, brief 010): at each tick everyone stands at the stop the people file gives, or walks between two stops, or is off the street.", r =>
            {
                var g = r.G;
                r.Is(g.Walkers.Count > 100, $"the civic block's people are in ({g.Walkers.Count})");
                bool atStops = true; int walking = 0, onStreet0 = 0;
                Walker? mover = null;
                for (int t = 0; t <= T(480); t += T(30))
                {
                    r.To(t);
                    foreach (var w in g.Walkers)
                    {
                        var at = g.CrowdPos(w);
                        int i = Array.FindIndex(w.From, f => f <= t);
                        bool inStop = false;
                        for (int k = 0; k < w.Place.Length; k++)
                            if (t >= w.From[k] && t < w.To[k]) { inStop = true; if (w.Out[k] ? at != g.People2!.Places[w.Place[k]] : at != null) atStops = false; }
                        if (!inStop && at.HasValue) { walking++; mover ??= w; }
                        if (t == 0 && at.HasValue) onStreet0++;
                    }
                }
                r.Is(atStops, "everyone at a stop stands at its place, or is off the street (at home, inside, beyond)");
                // Changed (r016 cast, 2026-10-16): was "more than 10", the fixture cast's count; the people file says who is out at 0:00
                int outAt0 = 0;
                foreach (var w in g.Walkers) for (int k = 0; k < w.Place.Length; k++) if (w.From[k] <= 0 && 0 < w.To[k] && w.Out[k]) { outAt0++; break; }
                r.Is(outAt0 > 0 && onStreet0 >= outAt0, $"people are out on the street at 0:00 ({onStreet0}; the people file puts {outAt0} at a street stop)");
                r.Is(walking > 0 && mover != null, $"someone walks between stops during the mission ({mover?.P.Id})");
                if (mover != null)
                {
                    int k = 0; while (k + 1 < mover.Place.Length && !(mover.To[k] <= g.Tick && g.Tick < mover.From[k + 1])) k++;
                    var seen = new List<Pt>();
                    for (int t = 0; t <= T(480); t += Game.Hz) { var p = g.CrowdPos(mover, t); if (p.HasValue && !seen.Contains(p.Value)) seen.Add(p.Value); }
                    r.Is(seen.Count > 5, $"{mover.P.Name} moves in live time ({seen.Count} positions)");
                }
            });

            Add("N12b", "—", "A private Help (rulebook privacy, Sky 2026-10-16: a turning conversation is private, unless it's pressure): the Fixer helps Inez with customers at the café terrace in sight. Onlookers learn nothing: no witness Trail, no Standing move, no incident, nobody remembers the Fixer's face; the Help's own price stands (its base Trail).", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard"));
                int onlookers = g.Preview("pressure", Inez).Witnesses; // the same people, for a visible act (N12c)
                r.Is(onlookers > 0, $"people stand within witness range of Inez, on a clear line: a threat here would be seen by {onlookers}");
                int trail = g.Trail, standing = g.Standing, incidents = g.Incidents.Count;
                var q = g.Preview("help", Inez); // the card after Listen: turned, or not yet (a Fearful Inez takes two; the cast decides)
                r.Eq(q.Witnesses, 0, "the card counts nobody who would see it: the conversation is private");
                r.Do(Fixer, "turn", Inez, "help"); r.Done(Fixer);
                r.Is(g.Inez.Has("help") && g.Inez.Turned == (q.Outcome == "turned"), $"the Help lands as the card said ({q.Outcome})");
                r.Eq(g.Trail - trail, (int)q.Trail, "the Help's own Trail only: no witness Trail");
                r.Eq(g.Standing, standing, "no Standing move");
                r.Eq(g.Incidents.Count, incidents, "no incident for the investigators");
                r.Is(!g.Walkers.Exists(w => w.P != g.Inez && (g.HoldsFace(w.P) || w.P.Memory.Exists(m => m.Act == "saw-act"))), "no onlooker remembers the act or the Fixer's face");
                r.Is(!g.Ledger.Exists(l => l.cause.StartsWith("witnessed:", StringComparison.Ordinal)), "the ledger has no witnessed act");
                r.Is(!g.Log.Exists(l => l.Code.StartsWith("witness.", StringComparison.Ordinal)), "nobody saw the help");
                var next = g.BetweenMissions(g.Investigate());
                r.Is(!next.Lines.Exists(l => l.Line == "word" && l.Who != Inez), "between missions: no onlooker passes word of it");
            });

            Add("N12c", "—", "Pressure stays witnessable (rulebook privacy: a threat is visible): the Fixer presses Inez with the same customers in sight. A witness adds Trail once, moves Standing one step toward Menace (§04 public threats), remembers the Fixer's face, and the threat is an incident for the investigators.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard"));
                int trail = g.Trail, standing = g.Standing;
                var q = g.Preview("pressure", Inez);
                r.Is(q.Witnesses > 0, $"the card counts who would see it ({q.Witnesses})");
                r.Do(Fixer, "turn", Inez, "pressure"); r.Done(Fixer);
                r.Eq(g.Trail - trail, (int)q.Trail + g.R.WitnessTrail, "the Pressure's own Trail, and +1 T for the witnessed threat (once, however many saw it)");
                r.Eq(g.Standing, standing - g.R.StandingStep, "a public threat moves Standing one step toward Menace");
                r.Is(g.Walkers.Exists(w => w.P != g.Inez && g.HoldsFace(w.P)), "a witness remembers the Fixer's face");
                r.Is(g.Ledger.Exists(l => l.cause == "witnessed:threat:waitress"), "the ledger names the witnessed act");
                r.Is(g.Incidents.Exists(i => i.Cause == "threat:waitress" && i.Witnesses.Count > 1), "an incident with its witnesses, for the investigators");
            });

            var drvKnown = Turned(Driver); drvKnown.Known[Driver] = new List<string> { "routine", "need", "temperament" };
            Add("N16", "—", "Watchers log the cell (§05): the pickup camera logs the Fixer beside the driver; a watcher that logs an operative beside a contact exposes the contact's job (Motive's review #12), so the next mission's ladder moves resentment, not bravery.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Boarding pavilion"));
                r.Wait(T(2));
                r.Is(g.Sightings.Exists(s => s.Watcher == "camera:pickup" && s.Op == "fixer"), "the pickup camera logged the Fixer, with place and time");
                r.Is(g.ExposedByWatcher.Contains(Driver), "logged beside the driver: the driver is exposed");
                r.Do(Fixer, "call", Driver);
                r.To(T(200));
                var next = g.BetweenMissions(g.Investigate());
                r.Is(next.Lines.Exists(l => l.Line == "ladder" && l.Who == Driver && l.Detail.StartsWith("job-exposed", StringComparison.Ordinal)), "the driver's job was exposed: resentment, not bravery");
            }, drvKnown);

            // N17 and N17b test the Talker rule on Inez (Game.Question: what she would tell an investigator), and that the investigation, if its
            // hops reach her, hears exactly that. Whether they reach her is the cast's: the investigators question the people nearest the act
            // first, then by id (rulebook investigation); in the r016 cast two café servers (p-cafe-11, -12) share the café entrance with Inez
            // (p-cafe-14) and at Alert 0 (one investigator, two hops) are asked before her. The fixture's Inez was p-cafe-11 and won that tie.
            Add("N17", "—", "The investigation (§05, rulebook investigation): a pressured Inez is a Talker and gives up the Fixer's face to the investigators, with the cause in words (K7); a helped Inez lies, and in a neutral district that gives them nothing.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard")); r.Do(Fixer, "turn", Inez, "pressure"); r.Done(Fixer);
                var q = g.Question(g.Inez);
                r.Is(q.Outcome == "gives" && q.Facts.Contains("fixer-face"), "questioned, Inez gives up the Fixer's face");
                r.Is(q.Cause.Contains(">"), $"with the cause: {q.Cause}");
                var inv = g.Investigate();
                r.Is(inv.Findings.Count > 0, "the investigators work the threat");
                var f = inv.Findings.Find(x => x.Who == Inez);
                r.Is(f == null || (f.Outcome == q.Outcome && string.Join(",", f.Facts) == string.Join(",", q.Facts) && f.Cause == q.Cause), $"reached ({f != null}), she tells them exactly that");
                var named = inv.Findings.Find(x => x.Outcome == "gives" && x.Facts.Contains("fixer-face"));
                r.Eq(inv.NamedCause, named != null ? "named-witness:" + named.Who : "", "the first questioned who gave up the Fixer's face is the investigation's named cause");
                r.Is(f == null || inv.NamedCause == "named-witness:waitress", "if Inez is reached, she is the named witness");
            });

            Add("N17b", "—", "The investigation, the other way: a helped Inez is no Talker; brave enough (people.rules talker.lie: an Idealist starts a helper) she covers for the cell with a lie, else she says nothing (a Fearful Inez starts an informant); in a neutral district either gives the investigators nothing.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard")); HelpUntilTurned(r, Inez); // a contact helped as often as the card asks (the cast's temperament)
                var q = g.Question(g.Inez);
                bool brave = g.Inez.Sc[Rules.Bravery] >= g.R.LieBraveryAtLeast; // the cast's temperament decides (§04 start: Idealist bravery 1)
                r.Is(brave ? q.Outcome == "lies" && q.Facts.Count == 1 && q.Facts[0] == "nothing" : q.Outcome == "nothing" && q.Facts.Count == 0,
                     $"questioned, Inez {(brave ? "lies: nothing" : "is no Talker and says nothing")} ({q.Outcome} {string.Join(",", q.Facts)}; bravery {g.Inez.Sc[Rules.Bravery]})");
                var inv = g.Investigate();
                var f = inv.Findings.Find(x => x.Who == Inez);
                r.Is(f == null || (f.Outcome == q.Outcome && string.Join(",", f.Facts) == string.Join(",", q.Facts)), $"reached ({f != null}), she tells them exactly that");
                r.Eq(inv.NamedCause, "", "nobody named the cell");
            });

            var brave = new Start(); brave.Temperament[Inez] = "idealist";
            Add("N17c", "—", "The lie itself (people.rules talker.lie), whoever the cast is: the start state makes Inez an Idealist (bravery helper from the start, §04); helped, she is no Talker, covers for the cell, and in a neutral district her lie gives the investigators nothing.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard")); HelpUntilTurned(r, Inez);
                var q = g.Question(g.Inez);
                r.Is(q.Outcome == "lies" && q.Facts.Count == 1 && q.Facts[0] == "nothing", $"questioned, Inez lies: nothing ({q.Outcome} {string.Join(",", q.Facts)})");
            }, brave);

            Add("N18", "—", "Between missions (rulebook phases): after route A, Inez's ladder follows the investigation: questioned, her job is exposed (resentment compliant → resentful), else it is not (bravery informant → helper); her met debt is replaced from her own stream (Q2), told free as she is a contact; obliged, she passes no word (K3, Motive #10); she can introduce along her own family, workmate and regular ties (K5).", r =>
            {
                var g = r.G;
                RouteA(r, reroute: true);
                Support(r); ToAmbush(r); // brief 018: walking Vale the Enforcer doesn't fire; the three by the car fight
                r.FightItOutAll(120, Scout, Fixer, Tech); r.Extract();
                r.Eq(g.Result, Outcome.Success, "route A wins");
                var next = Debrief.Of(g).Next;
                // Changed (rulebook privacy, Sky 2026-10-16): the Help is private, so no onlooker's sighting is a lead. Whether the
                // investigators reach Inez by another lead is the cast's and the route's; the ladder must follow it.
                var inv = Debrief.Of(g).Inv;
                r.Is(!inv.Findings.Exists(f => f.Lead.StartsWith("incident:debt-cleared", StringComparison.Ordinal) || f.Lead.StartsWith("incident:payment", StringComparison.Ordinal)), "a private Help leaves the investigators no witnessed lead");
                bool asked = inv.Findings.Exists(f => f.Who == Inez);
                string ladder = asked ? "job-exposed: resentment compliant → resentful" : "job-unexposed: bravery informant → helper";
                r.Is(next.Lines.Exists(l => l.Line == "ladder" && l.Who == Inez && l.Detail == ladder), $"{(asked ? "questioned" : "not questioned")}, her ladder: {ladder}");
                var need = next.Lines.Find(l => l.Line == "need-replaced" && l.Who == Inez);
                r.Is(need != null && need.Detail.StartsWith("debt → ", StringComparison.Ordinal) && need.Detail.EndsWith("(told free: a contact)", StringComparison.Ordinal), $"her debt is replaced and told free ({need?.Detail})");
                r.Is(!next.Lines.Exists(l => l.Line == "word" && l.Who == Inez), "obliged, she passes no word");
                var kinds = new List<string>(); // the kinds of tie introductions travel along that Inez has in the people file (§04 ties)
                foreach (var (kind, _) in g.People2!.Ties[g.Inez.Id]) if ((kind == "family" || kind == "workmate" || kind == "regular") && !kinds.Contains(kind)) kinds.Add(kind);
                var intro = next.Lines.Find(l => l.Line == "introduced" && l.Who == Inez);
                r.Is(kinds.Count > 0 && intro != null && kinds.TrueForAll(k => intro.Detail.Contains("(" + k + ")")), $"she can introduce along her own ties ({string.Join(", ", kinds)}): {intro?.Detail}");
                r.Is(!next.Ambush, "no ambush is scheduled");
            });

            Add("N19", "—", "Running (Sky 2026-10-15: double-click runs): the Scout runs to the courtyard at the rulebook's run speed and arrives sooner than the Fixer walking the same distance, by exactly the ticks the two paces give.", r =>
            {
                var g = r.G;
                int t0 = g.Tick;
                int scoutAt = r.Send(Scout, "d:Courtyard", run: true);
                long len = r.Op(Scout).Walk!.Length;
                int fixerAt = r.Send(Fixer, "d:Courtyard");
                long flen = r.Op(Fixer).Walk!.Length;
                int runTicks = (int)((len + g.R.RunSpeed - 1) / g.R.RunSpeed), walkTicks = (int)((flen + g.R.CellSpeed - 1) / g.R.CellSpeed);
                r.Eq(scoutAt - t0, runTicks, $"the run takes ceil({len} mm / {g.R.RunSpeed} mm a tick) ticks");
                r.Eq(fixerAt - t0, walkTicks, $"the walk takes ceil({flen} mm / {g.R.CellSpeed} mm a tick) ticks");
                r.To(scoutAt);
                r.Eq(r.Op(Scout).Pos, r.Stand("d:Courtyard"), "the Scout is there at the tick the run gives");
                r.Is(r.Op(Fixer).Walk != null, "the Fixer is still walking");
                r.To(fixerAt);
                r.Eq(r.Op(Fixer).Pos, r.Stand("d:Courtyard"), "the Fixer arrives at the tick the walk gives");
                r.Is(walkTicks - runTicks > 0, $"running saved {walkTicks - runTicks} ticks");
            });

            Add("N19b", "—", "No running while carrying Vale (Sky 2026-10-15 Q3: a man being taken walks): the run order is refused with its reason; a walk is taken.", r =>
            {
                var g = r.G;
                r.Send(Enf, "d:Service lane");
                r.To(Max(r.Send(Scout, "d:Meet driver"), r.Send(Fixer, "d:Boarding pavilion")));
                r.Do(Scout, "watch", Driver); r.Done(Scout); r.Do(Scout, "listen", Driver); r.Done(Scout);
                TurnDriver(r);
                r.To(r.SendTo(Scout, new Pt(8250, -3100))); r.To(T(320)); r.Do(Scout, "mislead", "rivals");
                r.To(T(370)); r.Do(Enf, "take"); r.Done(Enf);
                var (ok, why) = g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "move", To = "d:Getaway bay", Run = true });
                r.Is(!ok && why.Contains("Vale"), $"carrying Vale, the run is refused: {why}");
                r.Eq(g.QuoteMove(Enf, r.Stand("d:Getaway bay")).RunRefused, why, "the move chip shows the same reason");
                r.Send(Enf, "d:Getaway bay");
                r.Eq(r.Op(Enf).WalkSpeed, g.R.CellSpeed, "he walks");
            }, NoFight());

            var known = new Start(); known.Known[Inez] = new List<string> { "routine", "need", "temperament" }; known.Known[Driver] = new List<string> { "routine", "need", "temperament" };
            var purse = new Start(); purse.Known[Inez] = known.Known[Inez]; purse.Known[Driver] = known.Known[Driver];
            // §04's purse is one Help on Inez and one on the driver (Motive §3): the rule under test, so the start state makes both people one
            // Help turns, whoever the cast is (the r016 cast's Inez is Fearful, two Helps; its driver a Mercenary)
            purse.Temperament[Inez] = "idealist"; purse.Temperament[Driver] = "idealist";
            Add("N09", "—", "The purse (§04): Help Inez + Help the driver = $80,000 fits $100,000.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard")); r.Do(Fixer, "turn", Inez, "help"); r.Done(Fixer);
                r.To(r.Send(Fixer, "d:Boarding pavilion")); r.Do(Fixer, "turn", Driver, "help"); r.Done(Fixer);
                r.Is(g.Inez.Turned && g.Driver.Turned, "both turned");
                r.Eq(g.Cash, 20000L, "$80,000 spent of $100,000");
            }, purse);

            var merc = new Start(); merc.Temperament[Inez] = "mercenary"; merc.Known[Inez] = new List<string> { "routine", "need", "temperament" }; merc.Known[Driver] = new List<string> { "routine", "need", "temperament" };
            Add("N09b", "—", "The purse the other way (§04): Pay on a Mercenary Inez ($70,000) leaves too little to Help the driver ($40,000): the order can't be given.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard")); r.Do(Fixer, "turn", Inez, "pay"); r.Done(Fixer);
                r.Is(g.Inez.Turned, "a Mercenary takes the fee");
                r.Eq(g.Cash, 30000L, "$70,000 spent");
                r.To(r.Send(Fixer, "d:Boarding pavilion"));
                r.Refused(Fixer, "turn", Driver, "$110,000 is over the purse: the driver can't be helped", "help");
            }, merc);

            // the refused approach and the one-step-worse line are the rules under test: the start state makes Inez an Idealist (Pay refused,
            // Pressure without leverage one step worse), whoever the cast is
            var tip = new Start(); tip.Known[Inez] = new List<string> { "routine", "need" }; tip.Temperament[Inez] = "idealist";
            Add("N14", "—", "The card (Sky Q3, Q4): \"?\" until the temperament is known; a refused approach fails and is remembered; the wrong approach costs one step.", r =>
            {
                var g = r.G;
                var q = g.Preview("help", Inez);
                r.Eq(q.Outcome, "?", "with the need known but not the temperament, Help's outcome shows \"?\"");
                r.Eq(q.Lines.Find(l => l.Line == "one-more-help")!.Holds, "?", "and its wrong-approach line shows \"?\"");
                r.Eq(g.Preview("ask", Inez).Outcome, "refused", "Ask in a neutral district reads refused: every temperament refuses it");
                r.Eq(g.Preview("pay", Inez).Reports, "?", "whether she would report a fee shows \"?\" (a Loyal person would, Motive's review: the risk line)");
                r.Eq(q.Reports, "no", "Help is reported by no temperament in a neutral district");
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.Eq(g.Preview("help", Inez).Outcome, "turned", "after Listen the card says Help turns her");
                r.Eq(g.Preview("pay", Inez).Outcome, "refused", "and that Pay is refused");
                r.Eq(g.Preview("pressure", Inez).Trail, 3L, "and that Pressure costs +3 T: Listen found her affair, so exposure is at its proper step (Motive, motive-lovers.md §2.2)");
                r.Is(g.Preview("pressure", Inez).Leverage, "the card reads exposure: her secret");
            }, tip);

            Add("N15", "—", "K1, K2, K8 in the mission: Help writes a memory entry with the Fixer's face; gratitude is +1 loyalty; the price is line items.", r =>
            {
                var g = r.G;
                var q = g.Preview("help", Inez);
                r.Eq(q.Lines.Count, 4, "four line items: base, refused before, one more Help, trust over time");
                r.Eq(q.Lines[0].Line, "base", "the first is the base");
                r.To(r.Send(Fixer, "d:Courtyard")); r.Do(Fixer, "turn", Inez, "help"); r.Done(Fixer);
                var m = g.Inez.Memory.Find(x => x.Act == "help");
                r.Is(m.Act == "help" && m.By == "fixer" && m.Place == "d:Café door", "memory: help, by the Fixer's face, at the café door (K1)");
                r.Is(g.HoldsFace(g.Inez), "she holds the Fixer's face (the dossier's face bit)");
                r.Eq(g.Inez.Sc[Rules.Loyalty], 1, "gratitude: loyalty obliged (K2)");
                r.Is(g.Ledger.Exists(l => l.what == "trail" && l.cause == "turn.help:waitress"), "the Trail ledger names the cause");
            }, known);

            FightCases();
            CancelCases();
            SightCases();
            TakedownCases(); // brief 013
            TakedownFixes(); // brief 013 D
            TakedownE(); // brief 013 E
            StandingCases(); // brief 014
            RepeatCases(); // Sky 2026-10-18: a Watch or Listen that teaches nothing more is refused
            TechWatchCases(); // Sky 2026-10-18: the Tech watches the machines too
            RoundsCases(); // brief 022: the living café
            GetawayCases(); // brief 018 (Sky 2026-10-18): the hold, the blocker, Board and Go, left behind, seen leaving, custody
            FailCauseCases(); // Sky 2026-10-18: the fail camera's culprit, every way the Handover ends without Vale
            DriveCases(); // brief 025 (EXPERIMENTAL): the driven agent, and the recorded driven session (DP1)
        }
    }
}

sim/Suborned.Sim/ScenariosPublicFight.cs.text:
// A public fight (Sky 2026-10-16, via Aster: "it should be per fight, and depends who you're fighting - a rival gang that has menace
// level authority is a +1"; Motive, briefs/014/motive-standing.md, a public fight; rulebook fight.public). One scenario a row of the
// outcomes table, on the real block and the promoted cast, with the crowd in unless a scenario says otherwise.
//  N95  feared rivals driven off: route A's safe final fight, the rivals break: one fight, +1 seen-fight-rivals when it ends; with
//       Inez's word the district ends at +4, Hero (Motive's route A row)
//  N96  a rival fight not won: the Enforcer fires one shot on the feared rival crew as it arrives, then the cell withdraws: 0
//  N97  firing first on rivals nobody fears: N96's orders with neutral rivals: −1 seen-fight-first
//  N98  a fight with security: the patrol shot down from the walk north of the Office at 4:30: −1 seen-fight-security, once, 30 s after the last shot
//  N99  a mixed fight: the patrol shot down, then the rival crew its gunfire draws, driven off inside 30 s: one fight, −1 (authority outranks)
//  N100 a fight nobody heard: N98's orders with no crowd and no cast within 30 m: no move, steady
//  N101 two fights 30 s apart: N99's orders with a wait before the rivals (the fight's end, people back): two fights, −1 and +1 (N99 is the closer twin: one)
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>The walk north of the Office, 26 m from the public door on its west face; the Enforcer fires at 4:30 (ShotAt), when the
        /// patrol's sweep is 23 m off and a person of the city crossing from the square is within 30 m. Re-sited 2026-10-19 (Keel, brief 023:
        /// the door on the west face, the sweep along the forecourt): was a corner of the square at (2000, -1000) firing on arrival at 0:30, but
        /// the sweep is 60 m from the square now and nobody of the city is near the forecourt before 3:30.</summary>
        static readonly Pt ShotCorner = new Pt(4300, -2600);
        const int ShotAt = 2700;

        static string Moves(Game g) => string.Join(", ", FightMoves(g).Select(m => $"{m.delta.ToString(System.Globalization.CultureInfo.InvariantCulture)} {m.cause} {m.who}"));
        static List<(int tick, int delta, string cause, string who)> FightMoves(Game g) => g.StandingMoves.FindAll(m => m.cause.StartsWith("seen-fight-", StringComparison.Ordinal));

        /// <summary>The civilians within the public reach of an operative now: the cast by role, then (crowd) the city's people.</summary>
        static int HeardBy(Game g, string op, bool crowd)
        {
            int n = 0; var at = g.OpOf(Sim.Op.Parse(op)).Pos;
            foreach (var p in g.People) { var q = g.PersonPos(p); if (p.Civilian && q.HasValue && G.Within(q.Value, at, g.R.FightPublicCm)) n++; }
            if (crowd) foreach (var w in g.Walkers) { var q = g.CrowdPos(w); if (w.P.Civilian && q.HasValue && G.Within(q.Value, at, g.R.FightPublicCm)) n++; }
            return n;
        }

        /// <summary>The Enforcer shoots the patrol robot down from the walk north of the Office at 4:30; returns the tick it went down.</summary>
        static int PatrolShotDown(Run r)
        {
            var g = r.G;
            r.To(r.SendTo(Enf, ShotCorner)); r.To(Math.Max(g.Tick, ShotAt));
            r.Fire(Enf, "patrol");
            r.Is(r.Until(() => g.PatrolDown, T(60)), $"the patrol is down at {Report.Clock(g.Tick)}");
            return g.Tick;
        }

        /// <summary>The rival crew arrives (3:10) by its car; the Enforcer, waiting beside it out of their way, fires on them as they come.</summary>
        static void FireOnArrivingRivals(Run r, bool once)
        {
            var g = r.G;
            r.To(r.SendTo(Enf, Beside(r, g.S.Stand(g.S.RivalsPark)) ?? g.S.Stand(g.S.RivalsPark)));
            r.Do(Enf, "draw");
            r.Is(r.Until(() => g.RivalsPresent, T(g.S.RivalsArrive) + T(5) - g.Tick), $"the rival crew is here at {Report.Clock(g.Tick)}");
            r.Fire(Enf, "rivals");
            r.Is(r.Until(() => r.Shots().Exists(x => x.by == Enf && x.target == "rivals"), T(10)), "the Enforcer fires on the crew");
            if (once) { r.Do(Enf, "cease"); return; }
            r.Is(r.Until(() => g.RivalsDelayMethod == "fire", T(20)), $"the crew is driven back at {Report.Clock(g.Tick)}");
        }

        /// <summary>The patrol down, the Enforcer walks within reach of the rival crew its gunfire drew to the Office front and fires on them
        /// until they are driven back.</summary>
        static void FireOnDrawnRivals(Run r, bool waitForPeople = false)
        {
            var g = r.G;
            r.Is(r.Until(() => g.RivalsDrawn && g.RivalsPresent, T(30)), $"the gunfire draws the rival crew ({Report.Clock(g.Tick)})");
            r.To(r.SendTo(Enf, g.S.Grid.NearestFree(NearFront) ?? NearFront));
            if (waitForPeople) r.Is(r.Until(() => HeardBy(g, Enf, true) > 0, T(120)), $"people back on the street within reach at {Report.Clock(g.Tick)}");
            r.Fire(Enf, "rivals");
            r.Is(r.Until(() => g.RivalsDelayMethod == "fire", T(30)), $"the crew is driven back at {Report.Clock(g.Tick)}");
        }
        /// <summary>Between the shot corner and the Office front, 16 m from where the drawn rivals make for (d:Office approach). Re-sited
        /// 2026-10-19 with the door (brief 023; was (3600, -2000)).</summary>
        static readonly Pt NearFront = new Pt(4800, -4200);

        static void PublicFightCases()
        {
            Add("N95", "—", "Feared rivals driven off (Sky 2026-10-16: 'a rival gang that has menace level authority is a +1'; rulebook fight.public): route A, quiet, then the safe final fight; the Handover's rivals are feared (mission rivals.public menace) and the cell breaks them. The final fight is one fight, public (the square is within 30 m of the car): Standing +1 once, when it ends, cause seen-fight-rivals. Between missions Inez's word adds +1: the district ends at +4, the Hero band (Motive's route A row).", r =>
            {
                var g = r.G;
                r.Eq(g.RivalsPublic, "menace", "the Handover's rivals are feared");
                RouteA(r, reroute: true);
                r.Eq((g.FightBranch, g.Fights.Count, g.StandingMoves.Count), ("safe", 0, 0), "a quiet route: no fight and no move before the final fight");
                Support(r); ToAmbush(r); // brief 018: walking Vale the Enforcer doesn't fire; the three by the car fight
                r.FightItOutAll(120, Scout, Fixer, Tech); // brief 018 §10: break the crew (the blocker falls first; a free car alone is board and go, N113)
                r.Extract();
                r.Eq(g.Result, Outcome.Success, "route A wins through the ambush");
                var bo = g.Log.FindAll(l => l.Code == "blocker.out"); var cf = g.Log.FindAll(l => l.Code == "car.free"); // moved here from N113 (2026-10-19)
                r.Is(bo.Count == 1 && cf.Count >= 1 && cf[0].Tick >= bo[0].Tick, $"logged by code: blocker.out, then car.free ({string.Join(", ", bo.Concat(cf).Select(l => l.Code + "@" + Report.Clock(l.Tick)))})");
                r.Eq(g.Fights.Count, 1, "one fight: the final fight");
                var f = g.Fights[0];
                r.Is(f.Final && f.Public, "the final fight, and the public heard it");
                r.Eq((f.OnRivals, f.OnSecurity, f.Outcome, f.Delta, f.Cause), (true, false, "rivals", 1, "seen-fight-rivals"), "the cell drove off a feared crew: +1");
                r.Eq(f.End, g.FightOverTick, "it moves when the fight ends");
                var m = FightMoves(g);
                r.Eq(m.Count, 1, "once per fight, however many shots");
                r.Eq((m[0].tick, m[0].delta, m[0].cause, m[0].who), (g.FightOverTick, 1, "seen-fight-rivals", "rivals"), "+1 at the fight's end");
                var l = OneLine(r, g.BetweenMissions(g.Investigate()));
                r.Eq((l.From, l.End, l.Word, l.Drift, l.To, l.Band), (2, 3, 1, 0, 4, "hero"), "2 + 1 the fight + 1 Inez's word = +4, Hero");
                r.Eq(l.Cause, "seen-fight-rivals", "the line's cause: the fight (the earliest of the two equal moves)");
            });

            Add("N137", "—", "Fire ends with the final fight (rulebook fight.over, Motive 2026-10-19): N95's route and ambush, but once a rival breaks the cell gives an explicit fire order on him (fire until down). When the final fight is over every fire order still on a final-fight hostile ends (fire.done, 'the fight is over'), a new one is refused fight-over, and 35 s later (past crowd.quiet) no shot has opened a second fight: one fight, one Standing move, +1 seen-fight-rivals.", r =>
            {
                var g = r.G;
                RouteA(r, reroute: true);
                Support(r); ToAmbush(r);
                string[] cell = { Enf, Scout, Fixer, Tech };
                Func<string> broken = () => { foreach (var h in g.Hostiles) if (h.Present && !h.Down && h.Gun.St == "break") return h.Id; return ""; };
                r.Engage(() => { var l = new List<string>(); foreach (var h in g.Hostiles) if (h.Present && !h.Down) l.Add(h.Id); return l; },
                         () => broken().Length > 0 || g.FightOverTick != Never, 120, new[] { Scout, Fixer, Tech }, true);
                string runner = broken();
                r.Is(runner.Length > 0 && g.FightOverTick == Never, $"a rival breaks while the fight is on ({(runner.Length > 0 ? runner : "none")})");
                string by = "";
                foreach (var name in new[] { Scout, Fixer, Tech })
                {
                    var o = r.Op(name); if (o.Down || o.Busy != null || o.Gun.W == null || runner.Length == 0) continue;
                    if (g.Issue(new Order { Tick = g.Tick, Op = name, Do = "fire", Target = runner }).ok) { by = name; break; }
                }
                r.Is(by.Length > 0, $"an explicit fire order on the breaking rival {runner} is taken while the fight is on ({(by.Length > 0 ? by : "nobody had a line")})");
                r.FightItOutAll(120, Scout, Fixer, Tech);
                r.Is(g.FightOverTick != Never, "the final fight is over");
                foreach (var name in cell)
                {
                    var o = r.Op(name);
                    r.Is(o.Down || o.Gun.Order.Length == 0 || !g.Hostiles.Exists(h => h.Id == o.Gun.Order), $"{name}: no fire order left on a final-fight hostile ({o.Gun.Order})");
                }
                var still = g.Hostiles.Find(h => h.Present && !h.Down);
                if (still != null && by.Length > 0 && !r.Op(by).Down)
                {
                    var a = g.Issue(new Order { Tick = g.Tick, Op = by, Do = "fire", Target = still.Id });
                    r.Eq(a.code, "fight-over", $"a new fire order on {still.Id} ({still.Gun.St}) is refused");
                }
                int over = g.FightOverTick;
                r.Wait(T(35));
                r.Is(!g.Log.Exists(l => (l.Code == "shot.hit" || l.Code == "shot.miss") && l.Tick > over && g.Hostiles.Exists(h => l.Text.Contains(" fires on " + h.Id + " "))), "no cell shot at a final-fight hostile after the fight is over");
                r.Eq(g.Fights.Count, 1, "one fight: the final fight, no straggler fight");
                var m = FightMoves(g);
                r.Eq(m.Count, 1, "one Standing move from the fight");
                if (m.Count > 0) r.Eq((m[0].delta, m[0].cause), (1, "seen-fight-rivals"), "+1, the feared crew driven off");
                r.Extract();
                r.Eq(g.Result, Outcome.Success, "route A still wins");
            });

            Add("N96", "—", "A rival fight not won (rulebook fight.public): the Enforcer fires on the feared rival crew as it arrives, then the cell withdraws with the crew unbroken. The fight ends with the mission: public, but no outcome holds (not security; feared, so firing first is no fault; not driven off): Standing does not move.", r =>
            {
                var g = r.G;
                FireOnArrivingRivals(r, once: true);
                r.Wait(T(3));
                r.Do(Enf, "withdraw");
                r.Eq(g.Result, Outcome.Withdrawn, "the cell withdraws");
                r.G.Finish();
                r.Eq(g.Fights.Count, 1, "one fight, ended with the mission");
                var f = g.Fights[0];
                r.Is(f.Public, $"public: {HeardBy(g, Enf, true)} civilians within {g.R.FightPublicCm / 100} m of the Enforcer");
                r.Eq((f.OnRivals, f.OnSecurity, f.RivalsFirst, f.Outcome, f.Delta), (true, false, "cell", "none", 0), "the cell fired first on feared rivals and did not break them: 0");
                r.Is(g.RivalsDelayMethod != "fire", "the crew was not driven back");
                r.Eq(FightMoves(g).Count, 0, "no fight move");
            }, new Start { FinalFight = false });

            Add("N97", "—", "Firing first on rivals nobody fears (rulebook fight.public; a scenario fixes rivals.public neutral): N96's orders exactly. The cell fired the first shot between it and the crew: Standing −1 when the fight ends, cause seen-fight-first.", r =>
            {
                var g = r.G;
                r.Eq(g.RivalsPublic, "neutral", "these rivals are not feared");
                FireOnArrivingRivals(r, once: true);
                r.Wait(T(3));
                r.Do(Enf, "withdraw");
                r.G.Finish();
                r.Eq(g.Fights.Count, 1, "one fight");
                var f = g.Fights[0];
                r.Eq((f.Public, f.RivalsFirst, f.Outcome, f.Delta, f.Cause), (true, "cell", "first", -1, "seen-fight-first"), "the cell fired first on neutral rivals: −1");
                var m = FightMoves(g);
                r.Eq((m.Count, m[0].tick, m[0].who), (1, f.End, "rivals"), "once, when the fight ends (here, with the mission)");
            }, new Start { FinalFight = false, RivalsPublic = "neutral" });

            Add("N98", "—", "A fight with security (rulebook fight.public): the Enforcer shoots the patrol robot down from the walk north of the Office at 4:30, people of the city within 30 m. Standing −1 once, not at the first shot but when the fight ends, 30 s (crowd.quiet) after the last shot by or at the cell; cause seen-fight-security, naming the patrol. Trail and Alert are the shots' own, as before; the district ends at +1.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Enf, ShotCorner)); r.To(Math.Max(g.Tick, ShotAt));
                r.Is(HeardBy(g, Enf, true) > 0, $"civilians within {g.R.FightPublicCm / 100} m of the Enforcer ({HeardBy(g, Enf, true)})");
                r.Fire(Enf, "patrol");
                r.Is(r.Until(() => g.PatrolDown, T(60)), $"the patrol is down at {Report.Clock(g.Tick)}");
                r.Eq(g.StandingMoves.Count, 0, "nothing moves while the fight is on");
                r.Is(r.Until(() => g.Fights.Count > 0, T(60)), $"the fight ends at {Report.Clock(g.Tick)}");
                var f = g.Fights[0];
                r.Eq(f.End - f.Last, g.R.FightQuietTicks, "30 s after the last shot");
                r.Eq((f.Public, f.OnSecurity, f.FirstSecurity, f.Outcome, f.Delta), (true, true, "patrol", "security", -1), "a fight with authority: −1");
                var m = FightMoves(g);
                r.Eq((m.Count, m[0].tick, m[0].cause, m[0].who), (1, f.End, "seen-fight-security", "patrol"), "once, when it ends");
                r.Eq(g.Standing, g.R.StandingStart - 1, "+2 → +1");
                r.Eq((g.Trail, g.Alert), (g.R.GunfireTrail + g.R.HitTrail + g.R.DownTrail, g.R.GunfireAlert), "Trail and Alert are the shots' own: a shooting, a hit, a down; Alert 2");
                r.Wait(T(5));
                var l = OneLine(r, g.BetweenMissions(g.Investigate()));
                r.Eq((l.From, l.End, l.Word, l.Drift, l.To, l.Cause, l.Who), (2, 1, 0, 0, 1, "seen-fight-security", "patrol"), "the district ends at +1, the fight its cause");
            }, new Start { FinalFight = false });

            // N99, N101: the patrol shot down, then the rival crew its gunfire draws, driven off: inside 30 s one fight, after 30 s two.
            void PatrolThenRivals(Run r, bool apart)
            {
                var g = r.G;
                PatrolShotDown(r);
                if (apart) r.Is(r.Until(() => g.Fights.Count == 1, T(60)), $"the patrol's fight ends at {Report.Clock(g.Tick)}");
                FireOnDrawnRivals(r, apart);
                int first = r.Shots().Find(x => (x.by == Enf && x.target == "rivals") || (x.by == "rivals" && x.target == Enf)).tick;
                int gap = first - r.Shots().FindLast(x => x.tick < first && (x.by == Enf || x.target == Enf)).tick;
                r.Is(apart ? gap >= g.R.FightQuietTicks : gap < g.R.FightQuietTicks, $"the rivals' fight starts {gap / 10} s after the last shot at the patrol");
                r.Is(r.Until(() => g.OpenFight == null, T(60)), $"the last fight ends at {Report.Clock(g.Tick)}");
            }
            Add("N99", "—", "A mixed fight (rulebook fight.public: authority outranks): the Enforcer shoots the patrol down from the walk north of the Office, then walks on the rival crew its gunfire draws and drives it off, never 30 s without a shot. One fight, on security and on rivals (broken): −1, seen-fight-security, once; the win over the rivals counts for nothing.", r =>
            {
                var g = r.G;
                PatrolThenRivals(r, false);
                r.Eq(g.Fights.Count, 1, "one fight: no 30 s gap");
                var f = g.Fights[0];
                r.Eq((f.Public, f.OnSecurity, f.OnRivals, f.Outcome, f.Delta, f.Cause), (true, true, true, "security", -1, "seen-fight-security"), "on security and rivals: authority outranks, −1");
                r.Is(f.CrewBroken >= 0, "though the rivals broke");
                r.Eq(Moves(g), "-1 seen-fight-security patrol", "one move, naming the patrol");
            }, new Start { FinalFight = false });

            Add("N100", "—", "A fight nobody heard (rulebook fight.public): N98's orders in a world with no crowd (Start.Crowd off); the cast's civilians (Inez, the driver, Vale inside) are all beyond 30 m of every shot. The fight ends unheard: Standing does not move, and the district stands steady at +2. Trail and Alert are N98's.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Enf, ShotCorner)); r.To(Math.Max(g.Tick, ShotAt));
                r.Eq(HeardBy(g, Enf, false), 0, "no civilian within 30 m of the Enforcer");
                r.Fire(Enf, "patrol");
                r.Is(r.Until(() => g.PatrolDown, T(60)), $"the patrol is down at {Report.Clock(g.Tick)}");
                r.Is(r.Until(() => g.Fights.Count > 0, T(60)), $"the fight ends at {Report.Clock(g.Tick)}");
                var f = g.Fights[0];
                r.Eq((f.Public, f.OnSecurity, f.Outcome, f.Delta), (false, true, "unheard", 0), "nobody heard it: no outcome");
                r.Eq((g.Standing, g.StandingMoves.Count), (g.R.StandingStart, 0), "Standing does not move");
                r.Eq((g.Trail, g.Alert), (g.R.GunfireTrail + g.R.HitTrail + g.R.DownTrail, g.R.GunfireAlert), "Trail and Alert as in N98");
                var l = OneLine(r, g.BetweenMissions(g.Investigate()));
                r.Eq((l.To, l.Cause), (2, "steady"), "steady at +2");
            }, new Start { FinalFight = false, Crowd = false });

            Add("N101", "—", "Two fights 30 s apart give two moves (rulebook fight.public: a fight ends crowd.quiet after its last shot): N99's orders, but the Enforcer waits for the patrol's fight to end and for people to come back within 30 s of him (the first shots scattered them) before he fires on the rivals; at security level 0 (lax), so the response does not join in. Two public fights: −1 for the patrol, then +1 for driving off the feared crew: two moves, the district back at +2. N99 is the closer twin: one fight, one move.", r =>
            {
                var g = r.G;
                PatrolThenRivals(r, true);
                r.Eq(string.Join(", ", g.Fights.Select(f => $"{f.Public} {f.Outcome}")), "True security, True rivals", "two fights: the patrol's, then the rivals' (won)");
                r.Eq(Moves(g), "-1 seen-fight-security patrol, 1 seen-fight-rivals rivals", "two moves");
                r.Eq(g.Standing, g.R.StandingStart, "+2 → +1 → +2");
            }, new Start { FinalFight = false, Security = 0 });
        }
    }
}

sim/Suborned.Sim/ScenariosRepeat.cs.text:
// A Watch or Listen that can teach nothing more is refused, free (Sky 2026-10-18, playing: "if I've listened to someone before, I think I
// can then listen to them again?"). Listen on a person whose need and temperament (and secret, if any) the cell knows: already-heard. Watch
// when everything a Watch can teach of the target is known: a person's routine (and an affair a lover's visit could show), the guard's
// sight too, a camera's sight, the patrol's sight and routine (open until the cell's Watches total its routine seconds): already-watched.
// What a Scout event teaches is read from the rulebook (GameOrders.ScoutTeaches). The card (Quote.Refused) and the query before the click
// (ScoutQuery) give the same answer Issue gives. Each scenario also runs twice and replays from its orders (the Theory tests).
using System;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>A refused Scout order costs nothing: no time, cash, Trail or Alert, the Scout stays free, and the query and the card
        /// said the same code before it was given.</summary>
        static void RefusedFree(Run r, string verb, string target, string code, Person? p = null)
        {
            var g = r.G; var s = g.OpOf(OpId.Scout);
            var (tick, cash, trail, alert, mem) = (g.Tick, g.Cash, g.Trail, g.Alert, p?.Memory.Count ?? 0);
            r.Eq(g.ScoutQuery(verb, target).code, code, $"before the click, {verb} {target} reads {code} (ScoutQuery)");
            if (p != null) r.Eq(g.Quote(g.R.Ev("scout." + verb), p).Refused, code, $"the {verb} card on {target} carries {code}");
            var a = g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = verb, Target = target });
            r.Is(!a.ok && a.code == code, $"{verb} {target} again is refused {code} (got {(a.ok ? "taken" : a.code)})");
            r.Is(s.Busy == null && g.Tick == tick && g.Cash == cash && g.Trail == trail && g.Alert == alert && (p?.Memory.Count ?? 0) == mem,
                "the refusal costs nothing: no time, cash, Trail or Alert, the Scout free, nobody remembers it");
            r.Is(g.Log.Exists(l => l.Tick == g.Tick && l.Code == "order.rejected" && l.Text.Contains(target)), "the log keeps the refused order");
        }

        static void RepeatCases()
        {
            Add("N102", "—", "Listen to Inez twice (Sky 2026-10-18): route A's opening, Watch then Listen; the cell now knows her need, her temperament and her secret (the affair), so a second Listen is refused already-heard, free, and the card and the query said so first. Her routine and the affair known, a Watch on her teaches nothing either: already-watched.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard"));
                { var q = g.ScoutQuery("listen", Inez); r.Is(!q.ok && q.code != "already-heard", $"before a Watch, Listen is refused, but not for knowledge ({q.code})"); }
                r.Is(g.ScoutQuery("watch", Inez).ok && g.Quote(g.R.Ev("scout.watch"), g.Inez).Refused == "", "the first Watch is open: card and query");
                r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez"));
                r.Is(g.ScoutQuery("listen", Inez).ok && g.Quote(g.R.Ev("scout.listen"), g.Inez).Refused == "", "the first Listen is open: card and query");
                r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.Is(g.Inez.KNeed && g.Inez.KTemperament && g.Inez.KSecret, "heard: her need, her temperament and the affair");
                RefusedFree(r, "listen", Inez, "already-heard", g.Inez);
                RefusedFree(r, "watch", Inez, "already-watched", g.Inez);
            });

            Add("N103", "—", "Watch the entrance camera twice (Sky 2026-10-18): the first Watch teaches its sight and, a camera being fixed, its routine with it; a second is refused already-watched, free. The refusal is about knowledge, not ground: from far off the query says already-watched, not too-far.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Scout, WatchSpot(r, "camera:entrance")));
                r.Is(g.ScoutQuery("watch", "camera:entrance").ok, "the first Watch is open");
                r.Do(Scout, "watch", "camera:entrance"); r.Done(Scout);
                var k = g.Known("camera:entrance")!;
                r.Is(k.Sight && k.Routine, "its sight is known, and its fixed routine with it");
                RefusedFree(r, "watch", "camera:entrance", "already-watched");
                r.To(r.Send(Scout, "crew:fixer"));
                r.Eq(g.ScoutQuery("watch", "camera:entrance").code, "already-watched", "far off, still already-watched (not too-far)");
                r.Is(g.ScoutQuery("watch", "camera:pickup").code != "already-watched", "the pickup camera, never watched, is not refused for knowledge");
            });

            Add("N104", "—", "Watch the patrol until its routine is known (Sky 2026-10-18; rulebook sight.watch.routine 40 s): the first Watch teaches its sight; the second is not refused, since its routine is still to learn (20 of 40 s), and teaches it; the third is refused already-watched, free.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Scout, WatchSpot(r, "patrol", unseen: false)));
                r.Is(r.Until(() => Watchable(r, "patrol"), T(120)), "the patrol comes within reach and in line");
                r.Do(Scout, "watch", "patrol"); r.Done(Scout);
                var k1 = g.Known("patrol")!;
                r.Is(k1.Sight && !k1.Routine, $"one Watch: its sight, not its routine ({k1.WatchedS} of {k1.RoutineNeedsS} s)");
                r.Is(r.Until(() => Watchable(r, "patrol"), T(120)), "in reach and in line again");
                r.Is(g.ScoutQuery("watch", "patrol").ok, "its sight known, its routine not: the second Watch is open");
                r.Do(Scout, "watch", "patrol"); r.Done(Scout);
                r.Is(g.Known("patrol")!.Routine, "two Watches: its routine is known");
                r.Is(r.Until(() => Watchable(r, "patrol"), T(120)), "in reach and in line a third time");
                RefusedFree(r, "watch", "patrol", "already-watched");
            });

            Add("N105", "—", "A Watch that still has something to teach is not refused (Sky 2026-10-18): the guard's routine, need, temperament and the affair told before the mission, but not his sight; the Watch on him is taken and teaches his sight (rulebook sight: the guard's Watch teaches it), then a second is refused already-watched. Inez watched once (her routine known) but never heard: the affair is still to learn, and a Watch while her lover is beside her could show it, so a second Watch on her is taken too.", r =>
            {
                var g = r.G;
                r.Is(g.GuardP.KRoutine && g.GuardP.KSecret && !g.Known(GuardR)!.Sight, "told his routine and the affair, not his sight");
                r.To(r.SendTo(Scout, AheadOfGuard(r, 400)));
                r.Is(g.ScoutQuery("watch", GuardR).ok && g.Quote(g.R.Ev("scout.watch"), g.GuardP).Refused == "", "his sight unknown: the Watch is open, card and query");
                r.Do(Scout, "watch", GuardR); r.Done(Scout);
                r.Is(g.Known(GuardR)!.Sight, "his sight is learned");
                RefusedFree(r, "watch", GuardR, "already-watched", g.GuardP);
            }, Told(GuardR, "routine", "need", "temperament", "secret"));

            Add("N105b", "—", "A Watch that may still show an affair is not refused (Sky 2026-10-18; Motive, motive-lovers.md §1.2: a Watch that ends with two lovers together reveals it): Inez watched once, her routine known, never heard, her lover the guard: the second Watch on her is taken, and Listen is open.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard"));
                r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.Is(g.Inez.KRoutine && !g.Inez.KSecret && g.Inez.Lover == g.GuardP, "her routine known, the affair not, the guard her lover");
                r.Is(g.Quote(g.R.Ev("scout.watch"), g.Inez).Refused == "" && g.ScoutQuery("watch", Inez).ok, "a second Watch is open: card and query");
                r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.Is(g.Quote(g.R.Ev("scout.listen"), g.Inez).Refused == "", "Listen is still open: her need and temperament unknown");
            });
            Add("N106", "—", "The query asks needs before reach (Latch 2026-10-18): at 0:02 the Scout stands far from Inez and her routine is unknown. ScoutQuery says needs-routine (walking closer won't cure it); the order itself, given there, still answers too-far (Issue checks reach first, so replays don't move). Within reach, both say needs-routine.", r =>
            {
                var g = r.G;
                r.To(T(2));
                var at = g.PersonPos(g.Inez)!.Value;
                r.Is(!G.Within(r.Op(Scout).Pos, at, g.R.ListenReachCm), "the Scout stands out of Listen's reach");
                r.Eq(g.ScoutQuery("listen", Inez).code, "needs-routine", "at a distance the query gives the missing need, not too-far");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "listen", Target = Inez }).code, "too-far", "the order itself keeps Issue's order: too-far");
                r.To(r.Send(Scout, "beside-inez"));
                r.Eq(g.ScoutQuery("listen", Inez).code, "needs-routine", "within reach, the query: needs-routine");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "listen", Target = Inez }).code, "needs-routine", "within reach, the order: needs-routine");
            });
        }

        static Start Told(string role, params string[] what) { var s = new Start(); s.Known[role] = new System.Collections.Generic.List<string>(what); return s; }
    }
}

sim/Suborned.Sim/ScenariosRounds.cs.text:
// The living café (brief 022, Pulse; Sky 2026-10-18: "have the waitress also walk around the cafe tables, and when guard comes, they stand
// together"), on the real block with the mission's baked round (sim/data/handover.rounds.json). Pulse's reference poses are matched in
// Suborned.Sim.Tests/Rounds.cs; these play the round with orders.
//  N130 a Listen refused too-far while she serves a table; the HUD's "back in n s" (RoundNext) and PoseAhead say when she is back; then taken
//  N131 the chain hold: a Listen, then a Help given at the tick it lands: one hold, she stands still the whole way though her round was due out
//  N132 the call from mid-walk: she walks back to her post; the guard walks his route and stops 1.2 m short, facing her; they stand together
//  N133 the round ends at the first shot: she walks back from her table and stands her post for the rest of the mission
//  N134 the guard stands at her side (brief 022 addendum): nobody near, he takes the first stop (her left); the Scout at beside-inez is 1.4 m or more from him
//  N135 the Scout stands on the first stop at the call: he takes the other hand
//  N136 both front stops are taken: the stop whose nearest person is farthest
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>The cases that read the round itself (they have nothing to compare with the round off).</summary>
        public static readonly HashSet<string> PlaysTheRound = new HashSet<string>(StringComparer.Ordinal) { "N130", "N131", "N132", "N133", "N134", "N135", "N136" };
        static string PhaseOf(Game g) => g.PersonPose(g.Inez)?.phase ?? "";
        static Start KnowingRoutine() { var s = new Start(); s.Known["waitress"] = new List<string> { "routine" }; return s; }

        static void RoundsCases()
        {
            Add("N130", "—", "A Listen refused while she serves (brief 022): Inez's round takes her to table 3 at 0:34 (8 s out, serving 0:42 to 0:57). The Scout at beside-inez (her routine known from the briefing) is 3 m from her post, 8 m from the table: a Listen at 0:45 is refused too-far. RoundNext says how long until she is back at her post and PoseAhead where she will be; the Listen given then is taken, and holds her.", r =>
            {
                var g = r.G;
                r.Is(g.RoundsOn, "the mission's data plays her round");
                r.To(r.Send(Scout, "beside-inez"));
                r.To(T(45));
                r.Eq(PhaseOf(g), "serving", "at 0:45 she serves a table");
                var a = g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "listen", Target = Inez });
                r.Eq((a.ok, a.code), (false, "too-far"), "the Listen is refused: she is out of reach");
                int n = g.RoundNext(g.Inez);
                r.Is(n > 0 && n < T(60), $"back at her post in {n / Game.Hz} s (the HUD's back in n s)");
                var ahead = g.PoseAhead(g.Inez, n);
                r.Is(ahead.HasValue && ahead.Value.phase == "at post" && ahead.Value.pos == g.S.Stand(g.Inez.Place), "PoseAhead puts her at her post then");
                r.To(g.Tick + n);
                r.Eq(PhaseOf(g), "at post", "she is back");
                a = g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "listen", Target = Inez });
                r.Is(a.ok, $"the Listen is taken ({a.why})");
                r.Wait(T(2)); r.Eq(PhaseOf(g), "held", "spoken to, she stands still");
            }, KnowingRoutine());

            Add("N131", "—", "The chain hold (brief 022, rounds.holds and linger): the Scout listens to Inez at 0:20 (her routine known from the briefing); the Fixer's Help is given at the tick the Listen lands. One hold from 0:20 to the Help's landing plus 3 s: she stands still the whole way, though her round would have taken her to table 3 at 0:34; the round clock stopped, so she goes out 14 s after the hold (her clock was at 0:20).", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Scout, "beside-inez"), r.Send(Fixer, "d:Courtyard")));
                r.To(T(20));
                var a = g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "listen", Target = Inez }); r.Is(a.ok, $"Listen at 0:20 ({a.why})");
                int from = g.Tick; r.Done(Scout);
                a = g.Issue(new Order { Tick = g.Tick, Op = Fixer, Do = "turn", Target = Inez, Approach = "help" }); r.Is(a.ok, $"Help at the Listen's landing ({a.why})");
                int lands = r.Op(Fixer).BusyEnd;
                bool still = true; while (g.Tick < lands + T(g.R.RoundsLingerS)) { if (PhaseOf(g) != "held") still = false; g.Step(); }
                r.Is(still, $"held from {Report.Clock(from)} to {Report.Clock(lands)} + 3 s, through 0:34 when her round was due out");
                int back = g.Tick;
                r.Eq(PhaseOf(g), "at post", "the hold over, she stands her post");
                r.Is(r.Until(() => PhaseOf(g) == "to table", T(30)) && Math.Abs(g.Tick - back - T(14)) <= 1, $"her round goes on where it stopped: out {(g.Tick - back) / Game.Hz} s later (14 s: her clock stood at 0:20)");
            }, KnowingRoutine());

            Add("N132", "—", "The call from mid-walk (brief 022, the summons): Inez turned, the Fixer calls at 0:36, 2 s into her walk to table 3. She turns back and walks to her post; the guard walks the route he always walked to her post and stops 1.2 m short of it, facing her (his walk 1.2 m shorter than to the post); from his arrival they stand together until he turns to go, plus 2 s; then her round resumes at the start of its next rest.", r =>
            {
                var g = r.G;
                r.To(T(36));
                r.Eq(PhaseOf(g), "to table", "0:36: she is walking to a table");
                r.Do(Fixer, "call", Inez);
                g.Step(); r.Eq(PhaseOf(g), "to post", "the call: she walks back to her post");
                int arrive = g.LureTick + g.VisitWalkTicks;
                var st0 = g.S.Rounds!.GuardStops[0]; int cut = (g.S.Rounds.GuardStopWalkCm * 10 + g.R.CellSpeed - 1) / g.R.CellSpeed, full = (g.S.Rounds.GuardWalkCm * 10 + g.R.CellSpeed - 1) / g.R.CellSpeed;
                r.Is(Math.Abs(g.VisitWalkTicks - cut) <= 3 && g.VisitWalkTicks < full + T(1), $"his walk is to his stop at her side: {g.VisitWalkTicks / Game.Hz} s (to her post it was {full / Game.Hz} s)");
                r.To(arrive + 1);
                var gp = g.GuardPose()!.Value; var post = g.S.Stand(g.Inez.Place);
                int d = G.Dist(gp.pos, post);
                r.Is(gp.phase == "at café" && d >= g.R.PartnersCloseCm - 30 && d <= g.R.PartnersCloseCm + 30, $"he stops {d} cm from her post");
                r.Is(G.Within(gp.pos, g.S.Rounds!.GuardStops[0], 5), "at the first stop in the file (nobody stands near it)");
                r.Is(G.Within(g.PersonPos(g.Inez)!.Value, post, 1) && PhaseOf(g) == "together", "she is at her post, together with him");
                long dot = (long)gp.facing.X * (post.X - gp.pos.X) + (long)gp.facing.Y * (post.Y - gp.pos.Y);
                r.Is(dot > 0, "he faces her");
                r.To(arrive + T(g.R.SummonStayS) + T(g.R.PartnersPartS) + 1);
                r.Eq(PhaseOf(g), "at post", "he has gone: her round resumes at its next rest");
            }, Turned(Inez));

            Add("N133", "—", "The round ends at the first shot (brief 022, rounds.ends): Inez serves table 3 at 0:45 when the Enforcer fires on the guard at the door. The round ends (round.ends, gunfire): she walks back from the table and stands her post for the rest of the mission.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Enf, BesideDoor));
                r.To(T(44)); r.Eq(PhaseOf(g), "serving", "she serves a table");
                r.Fire(Enf, GuardR);
                r.Is(r.Until(() => r.Shots().Count > 0, T(10)), "the first shot");
                r.Is(g.Log.Exists(l => l.Code == "round.ends"), "the round ends at it");
                r.Is(r.Until(() => PhaseOf(g) == "at post", T(16)), $"she is back at her post ({Report.Clock(g.Tick)})");
                bool stays = true; for (int k = 0; k < T(90) && !g.Over; k += 5) { if (PhaseOf(g) != "at post") stays = false; g.Advance(5); }
                r.Is(stays, "and stays there");
            }, Level(1));

            Add("N134", "—", "The guard stands at her side (brief 022 addendum, partners.summoned.side): Inez turned, the Scout at beside-inez (2.1 m from her post), the Fixer at the Courtyard. The call at 0:20 sends the guard to the first stop in the file (her left, 45 degrees off her facing); nobody stands within a metre of it, and the Scout is 1.4 m or more from him, not 0.9 m.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Scout, "beside-inez"), r.Send(Fixer, "d:Courtyard")));
                r.To(T(20)); r.Do(Fixer, "call", Inez);
                var arrive = g.LureTick + g.VisitWalkTicks; r.To(arrive + 1);
                var gp = g.GuardPose()!.Value; var stops = g.S.Rounds!.GuardStops;
                r.Is(gp.phase == "at café" && G.Within(gp.pos, stops[0], 5), $"he stands at the first stop {stops[0]} (at {gp.pos})");
                var scout = r.Op(Scout).Pos; int d = G.Dist(gp.pos, scout);
                r.Is(d >= 140, $"he is {d} cm from the Scout, not on top of him (was 90 cm at the old stop)");
                r.Is(G.Dist(gp.pos, g.S.Stand(g.Inez.Place)) >= g.R.PartnersCloseCm - 5 && G.Dist(gp.pos, g.S.Stand(g.Inez.Place)) <= g.R.PartnersCloseCm + 5, "1.2 m from her post");
            }, Turned(Inez));

            Add("N135", "—", "The other hand (brief 022 addendum): the Scout stands on the first stop when the call is given (Listen done from there, 1.2 m from Inez's post). The guard takes the second stop, her right, instead of stopping on him.", r =>
            {
                var g = r.G; var stops = g.S.Rounds!.GuardStops;
                r.To(Max(r.SendTo(Scout, stops[0]), r.Send(Fixer, "d:Courtyard")));
                r.To(T(20)); r.Do(Fixer, "call", Inez);
                r.To(g.LureTick + g.VisitWalkTicks + 1);
                var gp = g.GuardPose()!.Value;
                r.Is(G.Within(r.Op(Scout).Pos, stops[0], 30), "the Scout is on the first stop");
                r.Is(G.Within(gp.pos, stops[1], 5), $"he takes the second stop {stops[1]} (at {gp.pos})");
                r.Is(G.Dist(gp.pos, r.Op(Scout).Pos) >= g.R.PartnersClearCm, "a metre or more from the Scout");
            }, Turned(Inez));

            Add("N136", "—", "Every stop taken (brief 022 addendum): the Scout on the first stop, the Fixer on the second, the Tech on the third. The guard takes the stop whose nearest person is farthest (the earlier in the file on a tie), the same pick every time.", r =>
            {
                var g = r.G; var stops = g.S.Rounds!.GuardStops;
                r.To(Max(r.SendTo(Scout, stops[0]), Max(r.SendTo(Fixer, stops[1]), r.SendTo(Tech, stops[2]))));
                r.To(g.Tick + T(1)); r.Do(Fixer, "call", Inez);
                r.To(g.LureTick + g.VisitWalkTicks + 1);
                var gp = g.GuardPose()!.Value; var people = new List<Pt> { r.Op(Scout).Pos, r.Op(Fixer).Pos, r.Op(Tech).Pos, r.Op(Enf).Pos };
                long best = -1; Pt want = stops[0];
                foreach (var st in stops) { long near = long.MaxValue; foreach (var q in people) near = Math.Min(near, G.Dist(st, q)); if (near > best) { best = near; want = st; } }
                r.Is(G.Within(gp.pos, want, 5), $"he stands at {want}, the stop farthest from all four (at {gp.pos}, {best} cm clear)");
            }, Turned(Inez));
        }
    }
}

sim/Suborned.Sim/ScenariosSight.cs.text:
// Cones are the Scout's skill (Sky 2026-10-16; Glyph's review §3.4; the rulebook's `sight`): what the cell knows of each watcher, how
// a Watch teaches it, what the cards show before and after, the routine a timed Watch teaches, and the detection fill. Each scenario also
// runs twice and replays from its orders (the Theory tests). The fan's geometry is checked point by point in the tests (SightTests).
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>The free ground nearest the Scout, or `who` (that it can walk to) from which a Watch on this watcher is taken now: within
        /// sight.watch.reach less 2 m, on a clear line (or, line false, behind a solid), and (unseen) in no watcher's sight. Ties by grid
        /// cell, so the same run finds the same spot.</summary>
        static Pt WatchSpot(Run r, string watcher, bool unseen = true, bool line = true, string who = Scout) => FindWatchSpot(r, watcher, unseen, line, who) ?? throw new InvalidOperationException($"no spot to watch {watcher} from");
        static Pt? FindWatchSpot(Run r, string watcher, bool unseen, bool line, string who = Scout)
        {
            var g = r.G; var at = g.ConeFan(watcher)!.At; var grid = g.S.Grid; var from = r.Op(who).Pos;
            var cands = new List<(long d, int i, int j, Pt c)>(); int reach = g.R.SightReachCm - 200;
            for (int i = 0; i < grid.Nx; i++)
                for (int j = 0; j < grid.Ny; j++)
                {
                    if (!grid.FreeCell(i, j)) continue;
                    var c = grid.Centre(i, j);
                    if (!G.Within(c, at, reach) || g.S.Sight(c, at, g.R.Eye) != line) continue;
                    if (unseen && g.WatcherIds().Exists(w => g.SeesNow(w, c, false))) continue;
                    cands.Add((G.D2(c, from), i, j, c));
                }
            cands.Sort((a, b) => a.d != b.d ? a.d.CompareTo(b.d) : a.i != b.i ? a.i.CompareTo(b.i) : a.j.CompareTo(b.j));
            foreach (var x in cands) if (grid.Route(from, x.c) != null) return x.c; // the nearest the Scout can walk to
            return null;
        }

        /// <summary>The Scout (or `who`) stands within sight.watch.reach of the watcher on a clear line now (what a Watch on it needs).</summary>
        static bool Watchable(Run r, string watcher, string who = Scout)
        {
            var f = r.G.ConeFan(watcher); var at = r.Op(who).Pos;
            return f != null && G.Within(at, f.At, r.G.R.SightReachCm) && r.G.S.Sight(at, f.At, r.G.R.Eye);
        }

        static void SightCases()
        {
            Add("N41", "—", "Cones are the Scout's skill (Sky 2026-10-16; rulebook sight): no watcher's sight is known at the start and no fan is drawn; the card's 'seen by' shows '?' for a watcher that could see the route, never its answer. Only the Scout and (Sky 2026-10-18) the Tech watch a camera, within 18 m on a clear line; the response unit is not watched. A 20 s Watch on the entrance camera teaches its sight (its routine with it: a camera is fixed), and the card then shows the true answer.", r =>
            {
                var g = r.G;
                r.Is(g.WatcherIds().TrueForAll(w => !g.Known(w)!.Sight), "no watcher's sight is known at the start");
                r.Eq(g.KnownFans().Count, 0, "no cone is drawn by default");
                var door = r.Stand("d:Office entrance");
                var q0 = g.QuoteMove(Scout, door);
                r.Is(q0.RunSeenBy.Contains("camera:entrance"), "the engine's truth: the entrance camera would see the run");
                r.Is(q0.Seen.Seen == "?" && q0.Seen.SeenBy.Count == 0 && q0.Seen.MaybeSeenBy.Contains("camera:entrance"), $"the card shows '?' (seen {q0.Seen.Seen}, maybe {string.Join(",", q0.Seen.MaybeSeenBy)})");
                r.Eq(q0.Seen.AlertIfSeen, g.R.RunAlert, "and the Alert a seen run would raise");
                var far = g.QuoteMove(Scout, r.Stand("crew:fixer"));
                r.Is(!far.Seen.MaybeSeenBy.Contains("camera:entrance"), "a route no camera could see, whatever its facing, shows no '?' for it");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "watch", Target = "camera:entrance" }).code, "too-far", "the Tech watches the machines too (Sky 2026-10-18), but not from the start: too far"); // was only-scout before Sky 2026-10-18
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "watch", Target = "camera:entrance" }).code, "too-far", "too far to watch the camera from the start");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "watch", Target = "security-1" }).code, "target-unknown", "the response unit's sight is known when it comes: nothing to watch");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "watch", Target = "camera:roof" }).code, "target-unknown", "no such camera");
                // within reach but behind a solid: the first watcher (in WatcherIds order) with such ground the Scout can walk to
                var hid = g.WatcherIds().Where(w => w.StartsWith("camera:", StringComparison.Ordinal) || w == "patrol").Select(w => (w, at: FindWatchSpot(r, w, false, false))).FirstOrDefault(x => x.at.HasValue);
                if (r.Is(hid.at.HasValue, $"there is ground within reach of a watcher but behind a solid ({hid.w})"))
                {
                    r.To(r.SendTo(Scout, hid.at!.Value));
                    r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "watch", Target = hid.w }).code, "no-clear-line", $"within reach of the {hid.w} but behind a solid: no clear line");
                }
                var spot = WatchSpot(r, "camera:entrance");
                r.To(r.SendTo(Scout, spot));
                r.Do(Scout, "watch", "camera:entrance");
                var a = g.ActivityOf(OpId.Scout);
                r.Is(a.Verb == "watch" && a.Target == "camera:entrance" && a.OnDone == "learns the sight" && a.TicksLeft == T(g.R.SightWatchS), $"the HUD reads Watch on the camera: {a.OnDone}, {a.TicksLeft} ticks");
                r.Is(!g.Known("camera:entrance")!.Sight, "nothing is learned before the Watch lands");
                r.Done(Scout);
                var k = g.Known("camera:entrance")!;
                r.Is(k.Sight && k.Routine && k.How == "watched" && k.SightAt == g.Tick && k.WatchedS == g.R.SightWatchS, $"the camera's sight is known, watched at {Report.Clock(k.SightAt)}, and its fixed routine with it");
                r.Is(g.Log.Exists(l => l.Code == "scout.watch.watched" && l.Text.Contains("entrance")), "the Scout says what was learned");
                r.Eq(string.Join(",", g.KnownFans().Select(f => f.Watcher)), "camera:entrance", "the Alt view: the one cone learned");
                var q1 = g.QuoteMove(Scout, door);
                r.Is(!q1.Seen.MaybeSeenBy.Contains("camera:entrance") && q1.Seen.SeenBy.Contains("camera:entrance") == q1.RunSeenBy.Contains("camera:entrance"), "the card now shows the camera's true answer");
                var c = g.Preview("help", Inez).Seen;
                r.Is(c != null && !c.MaybeSeenBy.Contains("camera:entrance"), "the action card's 'seen by' reads the same knowledge");
                r.Eq(g.Routine("camera:entrance", T(60))!.Count, 0, "a camera has no schedule: it does not move");
                r.Is(g.Routine("patrol", T(60)) == null, "the patrol's routine is unknown");
            });

            Add("N42", "—", "A timed Watch teaches a routine (stage 2; rulebook sight.watch.routine): one Watch of the patrol teaches its sight, the second (40 s watched) its routine. Its schedule then names each turn at an end of the sweep and each change in whether it sees the public door, and the run meets them at those ticks; a reroute moves it.", r =>
            {
                var g = r.G;
                var spot = WatchSpot(r, "patrol", unseen: false);
                r.To(r.SendTo(Scout, spot));
                r.Is(r.Until(() => Watchable(r, "patrol"), T(120)), "the patrol comes within reach and in line");
                r.Do(Scout, "watch", "patrol"); r.Done(Scout);
                var k1 = g.Known("patrol")!;
                r.Is(k1.Sight && !k1.Routine && k1.WatchedS == 20 && k1.RoutineNeedsS == 40, $"one Watch: its sight, not its routine ({k1.WatchedS} of {k1.RoutineNeedsS} s)");
                r.Is(g.Routine("patrol", T(100)) == null, "no schedule yet");
                r.Is(r.Until(() => Watchable(r, "patrol"), T(120)), "in reach and in line again");
                r.Do(Scout, "watch", "patrol");
                r.Eq(g.ActivityOf(OpId.Scout).OnDone, "learns the sight and the routine", "the HUD says the second Watch teaches the routine");
                r.Done(Scout);
                var k2 = g.Known("patrol")!;
                r.Is(k2.Routine && k2.RoutineAt == g.Tick && k2.WatchedS == 40, "two Watches: the routine is known");
                var ev = g.Routine("patrol", T(g.R.PatrolPeriodS))!;
                r.Is(ev.Count > 0 && ev[0].Tick == g.Tick && (ev[0].What == "sees-door") == g.SweepSeesEntrance(g.Tick), $"the schedule starts with where it stands now ({ev[0].What})");
                r.Is(ev.Exists(e => e.What == "turn-at-a") && ev.Exists(e => e.What == "turn-at-b"), "a whole period names both turns");
                foreach (var e in ev.Take(6))
                {
                    r.To(e.Tick);
                    if (e.What == "turn-at-a") r.Eq(g.PatrolPose()!.Value.pos, r.Stand(g.S.PatrolA), $"{Report.Clock(e.Tick)}: at the sweep's end A, as the schedule said");
                    else if (e.What == "turn-at-b") r.Eq(g.PatrolPose()!.Value.pos, r.Stand(g.S.PatrolB), $"{Report.Clock(e.Tick)}: at the sweep's end B, as the schedule said");
                    else r.Eq(g.SweepSeesEntrance(g.Tick), e.What == "sees-door", $"{Report.Clock(e.Tick)}: {e.What}, as the schedule said");
                }
                r.To(r.Send(Tech, "cabinet"));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                var after = g.Routine("patrol", T(200))!;
                r.Is(after.Count > 0 && after[0].What == "back-on-sweep" && after[0].Tick == g.PatrolAwayUntil, "rerouted: the schedule says when it is back on its sweep");
                r.Is(!g.ConeFan("patrol")!.Live && !g.Detection().Exists(n => n.Watcher == "patrol"), "away, it watches nothing");
            });

            Add("N43", "—", "The guard is watched as the person he is (scout.watch, 6 m): the Watch teaches his routine and his sight. Detection needs no knowledge: in his cone the Scout is noticed (the fill) with '?' over him until his sight is known, and known after.", r =>
            {
                var g = r.G;
                var front = AheadOfGuard(r, 400);
                r.To(r.SendTo(Scout, front));
                var n0 = g.Detection().Find(n => n.Watcher == "guard" && n.Op == Scout);
                r.Is(n0 != null && n0.PerMille == 1000 && !n0.Known && n0.From == g.GuardPose()!.Value.pos && n0.To == r.Op(Scout).Pos, "in his cone, the guard notices the Scout: the fill, and '?' over him");
                r.Eq(g.DetectionOf("guard", Scout), 1000, "one pair's fill");
                r.Eq(g.DetectionOf("guard", Fixer), 0, "the Fixer, far off, is not noticed");
                r.Do(Scout, "watch", GuardR);
                r.Eq(g.ActivityOf(OpId.Scout).OnDone, "learns the routine and his sight", "the HUD says what the guard's Watch teaches");
                r.Done(Scout);
                var k = g.Known(GuardR)!;
                r.Is(k.Sight && k.Routine && k.How == "watched" && g.GuardP.KRoutine, "his routine (the person's) and his sight are known");
                r.Eq(g.Routine(GuardR, T(120))!.Count, 0, "at his door he holds it: no schedule");
                var n1 = g.Detection().Find(n => n.Watcher == "guard" && n.Op == Scout);
                r.Is(n1 != null && n1.Known, "now the fill is a known watcher's");
                var f = g.ConeFan(GuardR)!;
                r.Is(f.Live && f.Kind == "guard" && f.Points.Length >= 3 && G.InPoly(r.Op(Scout).Pos, f.Points), "the Scout stands inside the guard's fan");
            });

            Add("N44", "—", "Learned knowledge is the cell's, not the Scout's (Sky 2026-10-16): the Scout learns the entrance camera's sight, then goes down in front of the guard; the sight stays known and drawn. A downed Scout watches nothing.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Scout, WatchSpot(r, "camera:entrance")));
                r.Do(Scout, "watch", "camera:entrance"); r.Done(Scout);
                r.Is(g.Known("camera:entrance")!.Sight, "the camera's sight is learned");
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, FrontOfGuard(r))));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.Do(Scout, "draw"); g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "stance", Stance = "hold" });
                r.Is(r.Until(() => r.Op(Scout).Down, T(30)), "the Scout is down");
                var k = g.Known("camera:entrance")!;
                r.Is(k.Sight && k.How == "watched", "the camera's sight is still known");
                r.Is(g.KnownFans().Exists(f => f.Watcher == "camera:entrance"), "and still drawn on Alt");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Scout, Do = "watch", Target = "camera:pickup" }).code, "agent-down", "a downed Scout watches nothing");
                r.Is(!g.Detection().Exists(n => n.Op == Scout), "a downed operative is not noticed");
            });

            Add("N45", "—", "The response unit and the rivals come for the cell: their sight is known from the moment they are on the street (rulebook sight.kinds learn arrival), never watched, never told. Gunfire at the guard draws both.", r =>
            {
                var g = r.G;
                r.Is(!g.Known("security-1")!.Sight && !g.Known("rivals")!.Sight, "neither is known before they come");
                r.Is(g.ConeFan("security-1") == null && g.ConeFan("rivals") == null, "nor on the street");
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "loop", "entrance"); r.Done(Tech);
                r.Fire(Enf, GuardR);
                r.Is(r.Until(() => g.SecurityArrives != int.MaxValue / 4, T(5)), "the response unit is called");
                r.Is(!g.Known("security-1")!.Sight, "called is not come: not known yet");
                r.Is(r.Until(() => g.Tick >= g.SecurityArrives || g.Over, T(120)) && !g.Over, "it reaches the street");
                var k = g.Known("security-1")!;
                r.Is(k.Sight && k.Routine && k.How == "arrival" && k.SightAt == g.SecurityArrives, "its sight is known on arrival");
                r.Is(g.ConeFan("security-1") is Fan f && f.Kind == "security" && f.Live && f.Points.Length >= 3, "and has a fan");
                r.Is(g.KnownFans().Exists(x => x.Watcher == "security-1"), "drawn on Alt");
                r.Is(g.RivalsDrawn, "the gunfire drew the rivals");
                r.Is(r.Until(() => g.RivalsPresent || g.Over, T(120)) && g.RivalsPresent, "they come");
                var kr = g.Known("rivals")!;
                r.Is(kr.Sight && kr.How == "arrival", "their sight is known when they come");
            }, NoFight());
        }
    }
}

sim/Suborned.Sim/ScenariosStanding.cs.text:
// Brief 014 (Keel, 2026-10-16; Sky's approval of briefs/014/motive-standing.md): Standing leans Hero. One scenario a rule, on the real
// block and the promoted cast. The word moves Standing only between missions, so every in-mission price stays as it was.
//  N88 help spreads: route A's Help ×2 on Inez is private (no move in the mission); she tells her ties: +1, the Hero band next mission
//  N89 harm spreads: a Pressure in sight moves it at once (−1) and Inez's word does again (−1): 0, Motive's route A Pressure row
//  N90 harm spreads from a knockout: the guard, knocked out unseen, comes home and tells: −1, the cause names him
//  N91 the cap: three people helped, the word nets +3 and moves the district +2
//  N92, N92b drift both ways: a district where nothing moved steps back toward the start, from the Hero side and from the Menace side, never past it
//  N93 helped and pressured counts as pressured: one Help (not yet), then a Pressure nobody sees: the word is −1, and the Help adds nothing
//  N94 the start is +2: neutral prices in the mission, and nothing moved means steady at +2
//  N95-N101 a public fight moves Standing once, when it ends, by whom the cell fought (Sky 2026-10-16, via Aster; fight.public, replacing
//            0.6.1's per-target gunfire.heard): feared rivals driven off +1 (the safe final fight), a rival fight not won 0, firing first on
//            neutral rivals −1, a fight with security −1, a mixed fight −1, a fight nobody heard 0, and two fights 30 s apart two moves
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        static Start Knowing(params string[] roles)
        {
            var s = new Start { FinalFight = false, Cash = 1_000_000 };
            foreach (var role in roles) s.Known[role] = new List<string> { "routine", "need", "temperament" };
            return s;
        }
        static Start StartingAt(int standing) { var s = new Start { FinalFight = false, Standing = standing }; return s; }

        /// <summary>The Fixer stands within approach reach of a role and helps, reading the card as a player would, until the person turns.</summary>
        static bool HelpRole(Run r, string role, int most = 3)
        {
            var g = r.G; var p = g.PersonByRole(role);
            r.ForHer("turn", role); // brief 022: a server is met at her post
            var at = g.PersonPos(p); if (!r.Is(at.HasValue, $"{role} is on the street at {Report.Clock(g.Tick)}")) return false;
            if (!G.Within(r.Op(Fixer).Pos, at!.Value, g.R.ApproachReachCm)) r.To(r.SendTo(Fixer, g.S.Grid.NearestFree(at.Value)!.Value));
            HelpUntilTurned(r, role, most);
            return r.Is(p.Has(g.R.HelpedAct), $"{role} was helped");
        }
        static StandingLine OneLine(Run r, Between next)
        {
            r.Eq(next.Standing.Count, 1, "one Standing line: the Handover plays in one district");
            r.Is(next.Lines.Count(l => l.Line == "standing") == 1, "and one debrief line for it");
            return next.Standing[0];
        }

        static void StandingCases()
        {
            Add("N88", "—", "Help spreads (Sky 2026-10-16: 'if you help in a good way then can move to hero'; briefs/014/motive-standing.md rule 2): route A's opening, Inez helped until she turns. The Help is private, so nothing moves in the mission and every price is the neutral one. Between missions Inez tells her ties a stranger helped her: +1, once however many ties she has. From +2 the district reaches +3, the Hero band, for the next mission. The word is a feeling, not a fact: nobody's memory changes.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard"));
                HelpUntilTurned(r, Inez);
                r.Is(g.Inez.Turned && g.Inez.Count(g.R.HelpedAct) >= 1, $"Inez helped ×{g.Inez.Count(g.R.HelpedAct)} and turned");
                r.Eq(g.Standing, g.R.StandingStart, "the Help is private: Standing stays at the start in the mission");
                r.Eq(g.StandingMoves.Count, 0, "nothing moved it");
                int ties = g.People2!.Ties[g.Inez.Id].Count(t => g.R.WordTies.Contains(t.Item1));
                r.Is(ties >= 2, $"she has {ties} family, lover or workmate ties");
                var before = g.Walkers.Select(w => Hash.Person(w.P)).ToList();
                var next = g.BetweenMissions(g.Investigate());
                var l = OneLine(r, next);
                r.Is(next.Word.Count == 1 && next.Word[0] == (Inez, "hero"), "one teller: Inez, toward Hero");
                r.Eq((l.From, l.End, l.Word, l.Drift, l.To), (2, 2, 1, 0, 3), "from +2: her word +1 (once, not once per tie), no drift: +3");
                r.Eq((l.Band, l.Cause, l.Who), ("hero", "word-helped", Inez), "the Hero band, because a helped person told her ties");
                r.Eq(g.R.BandOf(l.To), Band.Hero, "the next mission starts in Hero prices");
                r.Is(g.Walkers.Select(w => Hash.Person(w.P)).SequenceEqual(before), "a feeling, not a fact: nobody in the city holds anything new");
                r.Is(!next.Lines.Exists(l2 => l2.Line == "word" && l2.Who == Inez && l2.Detail.Contains("help")), "no fact of the Help goes along her ties");
            });

            Add("N89", "—", "Harm spreads (briefs/014/motive-standing.md rules 3 and 4; Motive's route A Pressure row): the Fixer presses Inez with customers in sight. The threat seen moves Standing at once (−1, as built); between missions Inez tells her ties (−1). From +2 the district ends at 0: neutral. The cause is the earliest of two equal moves, the threat seen.", r =>
            {
                var g = r.G;
                r.To(r.Send(Scout, "d:Courtyard")); r.Do(Scout, "watch", Inez); r.Done(Scout);
                r.To(r.Send(Scout, "beside-inez")); r.Do(Scout, "listen", Inez); r.Done(Scout);
                r.To(r.Send(Fixer, "d:Courtyard"));
                r.Is(g.Preview("pressure", Inez).Witnesses > 0, "customers are in sight");
                r.Do(Fixer, "turn", Inez, "pressure"); r.Done(Fixer);
                r.Eq(g.Standing, g.R.StandingStart - g.R.StandingStep, "the threat seen: one step toward Menace at once");
                r.Is(g.StandingMoves.Count == 1 && g.StandingMoves[0].cause == "seen-threat" && g.StandingMoves[0].who == Inez, "its cause: a threat seen, done to Inez");
                var next = g.BetweenMissions(g.Investigate());
                var l = OneLine(r, next);
                r.Is(next.Word.Count == 1 && next.Word[0] == (Inez, "menace"), "Inez tells her ties: toward Menace");
                r.Eq((l.From, l.End, l.Word, l.Drift, l.To), (2, 1, -1, 0, 0), "+2, the threat −1, her word −1: 0");
                r.Eq((l.Band, l.Cause, l.Who), ("neutral", "seen-threat", Inez), "neutral; the earliest of the two equal causes: the threat seen");
            });

            Add("N90", "—", "Harm spreads from a knockout (briefs/014/motive-standing.md rule 3; Motive's route G knockout row): the guard knocked out from beside after his 2:30 mark, nobody seeing it (N46's opening). No Standing moves in the mission. He wakes and comes home; between missions he tells his ties: −1, from +2 to +1, and the line names him.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                r.Takedown("guard", "knockout"); r.Done(Enf);
                var a = ActOn(r, GuardId);
                r.Is(!a.Witnessed && a.Noticed.Count == 0, "nobody saw it");
                r.Eq(g.Standing, g.R.StandingStart, "no Standing in the mission");
                r.To(T(400));
                var next = g.BetweenMissions(g.Investigate());
                var l = OneLine(r, next);
                r.Is(next.Word.Count == 1 && next.Word[0] == (GuardR, "menace"), "the guard tells his ties: toward Menace");
                r.Eq((l.From, l.End, l.Word, l.Drift, l.To), (2, 2, -1, 0, 1), "+2, his word −1: +1");
                r.Eq((l.Band, l.Cause, l.Who), ("neutral", "word-knocked-out", GuardR), "neutral, because a knocked-out man came home and told");
            });

            Add("N91", "—", "The cap (briefs/014/motive-standing.md rule 2: ±2 per district per mission): the Fixer helps the driver, Inez and the guard (their needs told before the mission, cash to spare, no final fight). Three helped people tell their ties: +3, clamped to +2. From +2 the district reaches +4. A Loyal guard reports the approach: an incident for Alert, no Standing.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Boarding pavilion"));
                HelpRole(r, Driver);
                HelpRole(r, Inez);
                HelpRole(r, GuardR);
                r.Eq(g.Standing, g.R.StandingStart, "every Help is private: no move in the mission");
                var next = g.BetweenMissions(g.Investigate());
                var l = OneLine(r, next);
                r.Eq(next.Word.Count(w => w.toward == "hero"), 3, "three tellers, toward Hero");
                r.Eq((l.WordUncapped, l.Word), (3, g.R.WordStandingCap), "the word nets +3 and moves the district +2 (the cap)");
                r.Eq((l.From, l.To, l.Drift), (2, 4, 0), "+2 → +4");
                r.Eq((l.Band, l.Cause, l.Who), ("hero", "word-helped", Inez), "Hero, because helped people told their ties (the line names the first teller by person id: Inez, p-cafe-14)");
            }, Knowing(Driver, Inez, GuardR));

            Add("N92", "—", "Drift down (briefs/014/motive-standing.md rule 5): a district that starts at +5 (a campaign's Hero) and where nothing moves Standing this mission steps 1 back toward +2: +4, still Hero. Unkept Hero fades.", r =>
            {
                var g = r.G;
                r.Eq(g.Standing, 5, "the start a campaign handed on");
                r.To(T(120));
                var l = OneLine(r, g.BetweenMissions(g.Investigate()));
                r.Eq((l.From, l.End, l.Word, l.Drift, l.To), (5, 5, 0, -g.R.StandingDrift, 4), "nothing moved it: one step back toward the start");
                r.Eq((l.Band, l.Cause, l.Who), ("hero", "drift-down", ""), "still Hero; the cause is the drift");
            }, StartingAt(5));

            Add("N92b", "—", "Drift up, and never past the start (briefs/014/motive-standing.md rule 5): a Menace district (−3) where nothing moves Standing steps to −2, out of the Menace band; one at +3 steps to +2 and one at +2 holds.", r =>
            {
                var g = r.G;
                r.To(T(120));
                var l = OneLine(r, g.BetweenMissions(g.Investigate()));
                r.Eq((l.From, l.Drift, l.To), (-3, g.R.StandingDrift, -2), "−3 → −2: the city forgives a step");
                r.Eq((l.Band, l.Cause), ("neutral", "drift-up"), "out of the Menace band");
                foreach (var (from, to, cause) in new[] { (3, 2, "drift-down"), (2, 2, "steady") })
                {
                    var s = StartingAt(from); var g2 = new Game(g.R, g.S, s, null, g.People2); g2.RunTo(T(120));
                    var l2 = g2.BetweenMissions(g2.Investigate()).Standing[0];
                    r.Eq((l2.To, l2.Cause), (to, cause), $"from {from:+0;-0;0}: never past the start");
                }
            }, StartingAt(-3));

            Add("N93", "—", "Helped and pressured counts as pressured (briefs/014/motive-standing.md rule 3: a threat outweighs a kindness). Inez, Fearful, takes one Help (not yet turned), then the Fixer presses her with nobody in sight (no crowd in this scenario's world). Nothing moves in the mission; between missions her word is −1 and the Help adds nothing: +1.", r =>
            {
                var g = r.G;
                r.To(r.Send(Fixer, "d:Courtyard"));
                var q = g.Preview("help", Inez);
                r.Do(Fixer, "turn", Inez, "help"); r.Done(Fixer);
                r.Is(g.Inez.Has(g.R.HelpedAct) && !g.Inez.Turned, $"one Help landed and she is not yet turned (the card said {q.Outcome}, ×{q.Orders})");
                r.Is(g.Preview("pressure", Inez).Witnesses == 0, "nobody would see the threat");
                r.Do(Fixer, "turn", Inez, "pressure"); r.Done(Fixer);
                r.Is(g.Inez.Has("pressure"), "the Pressure landed");
                r.Eq(g.Standing, g.R.StandingStart, "nothing seen: no move in the mission");
                var next = g.BetweenMissions(g.Investigate());
                var l = OneLine(r, next);
                r.Is(next.Word.Count == 1 && next.Word[0] == (Inez, "menace"), "she tells it as a threat, never as a kindness");
                r.Eq((l.Word, l.To, l.Cause, l.Who), (-1, 1, "word-pressured", Inez), "+2 → +1, because a pressured person told her ties");
            }, Knowing(Inez).Also(s => s.Crowd = false));

            Add("N94", "—", "The start is +2 (Sky 2026-10-16: 'Hero is kinda the default'; briefs/014/motive-standing.md rule 1): one step short of the Hero band, so the mission's prices are neutral (Inez's Help and Pay cards carry no Hero line) and Heat adds nothing from Standing. A mission where nothing moves it ends steady at +2.", r =>
            {
                var g = r.G;
                r.Eq((g.R.StandingStart, g.StandingAtStart, g.Standing), (2, 2, 2), "standing.start is +2, and the mission starts there");
                r.Eq(g.R.BandOf(g.Standing), Band.Neutral, "neutral: Hero begins at +3, Menace at −3");
                r.Eq((g.R.HeroAt, g.R.MenaceAt), (3, -3), "the bands are unchanged");
                foreach (var a in new[] { "help", "pay", "ask", "pressure" })
                    r.Is(!g.Preview(a, Inez).Lines.Exists(x => (x.Line == "hero-overcharge" || x.Line == "menace-discount") && x.Holds != "no"), $"the {a} card holds no Standing line");
                r.Eq(Math.Max(0, -g.Standing), 0, "Heat takes nothing from Standing at the start (Trail + max(0, −Standing))");
                r.To(T(120));
                var l = OneLine(r, g.BetweenMissions(g.Investigate()));
                r.Eq((l.From, l.To, l.Drift, l.Cause), (2, 2, 0, "steady"), "nothing moved: steady at +2");
            }, Knowing(Inez));

            PublicFightCases();
        }
        static Start Also(this Start s, Action<Start> f) { f(s); return s; }
    }
}

sim/Suborned.Sim/ScenariosTakedown.cs.text:
// Brief 013 B (Keel; Sky 2026-10-16): takedowns, bodies, the people who report them and the response dial, as scenarios on the real block
// and the promoted cast (r016). Each runs twice and replays from its orders (the Theory tests). The numbers are the rulebook's, read
// through the engine; the clocks (the guard's 90 s marks from his shift's start, guard 74's walk, the clerks after the chime) are the
// people file's. Where a scenario fixes something in its start state (a level, a temperament), it says why.
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        const string GuardId = "p-records-office-01";
        /// <summary>Beside the door guard, outside his door cone (he faces west over the forecourt): where the Enforcer stands to take him
        /// from the side. 1.2 m south of the public door on its landing, as Waymark's c022 route G (2026-10-19, the door on the west face; was (51.75, -28.8)).</summary>
        static readonly Pt BesideGuard = new Pt(6520, -4110);
        // the service lane's stashes (sim/data/handover.takedown.json: the world's rules put a Dumpster beside the Office's service door)
        const string DumpsterId = "stash/office-service-door/container", ServiceDoorId = "stash/office-service-door/door";
        static readonly Pt Dumpster = new Pt(5975, -1725), ServiceDoor = new Pt(6275, -1875); // their stands (2026-10-19: the service door on the east face; were (60.25, -42.75) and (63.25, -41.25))

        /// <summary>The quiet setup for the guard (Motive §6.1, route G): the Tech loops the entrance camera and reroutes the patrol; the
        /// Enforcer waits beside the door; then, just after the guard's check-in mark, the Enforcer stands beside him.</summary>
        static void GuardQuiet(Run r)
        {
            var g = r.G;
            // 2026-10-19 (the door on the west face): the cabinet is 48 m from the Tech's start, so she runs to it as Waymark's c022 route G
            // does, and the loop and the reroute are done before the guard's 2:30 mark; the Enforcer walks to the door meanwhile. She starts
            // the reroute so it lands 5 s before the mark, as the walk to the old cabinet had it: the patrol's 115 s away then covers the
            // takedown and the 4:00 mark (back on its sweep at 4:00 it would take the alarm itself, Pulse §12.2, which N46 doesn't test).
            int enfAt = r.SendTo(Enf, BesideDoor);
            r.To(r.Send(Tech, "cabinet", run: true));
            r.Do(Tech, "loop", "entrance"); r.Done(Tech);
            r.To(Math.Max(g.Tick, g.NextMarkOf(g.GuardP, g.Tick + T(g.R.RerouteS)) - T(g.R.RerouteS + 5)));
            r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
            r.To(Math.Max(g.Tick, enfAt));
            int mark = g.NextMarkOf(g.GuardP, g.Tick); r.To(mark + 1);
            r.To(r.SendTo(Enf, BesideGuard));
        }
        /// <summary>The last takedown on `id` (a person id or a role); a clear failure, not a LINQ throw, when there is none.</summary>
        static TdAct ActOn(Run r, string id)
        {
            var a = r.G.Acts.LastOrDefault(x => x.Victim == id || x.P.Role == id);
            if (a != null) return a;
            throw new InvalidOperationException($"no takedown on '{id}' at {Report.Clock(r.G.Tick)}: the order was refused (see the failed takedown check before this) or never issued");
        }
        /// <summary>Free ground within reach of a person standing at `at` (1.2 m round, in a fixed order), the Enforcer can walk to, and
        /// not in `facing`'s cone from `at` (behind or beside him); null if none.</summary>
        static Pt? Beside(Run r, Pt at, Pt? facing = null)
        {
            var g = r.G;
            foreach (var d in new[] { new Pt(0, 120), new Pt(0, -120), new Pt(-120, 0), new Pt(120, 0), new Pt(85, 85), new Pt(85, -85), new Pt(-85, 85), new Pt(-85, -85) })
            {
                var q = at + d; if (!g.S.Grid.Free(q) || g.S.Grid.Route(r.Op(Enf).Pos, q) == null) continue;
                if (facing.HasValue && G.InCone(at, facing.Value, g.R.FacingReachCm, g.R.FacingHalfCm, 0, q)) continue;
                return q;
            }
            return null;
        }
        /// <summary>Meet a walking person from behind: stand beside where their routine puts them at `tick`, a little behind their heading,
        /// and wait there; returns the tick to order the takedown (they are within reach and the Enforcer is out of their facing cone).</summary>
        static int MeetFromBehind(Run r, Walker w, int tick)
        {
            var g = r.G; var at = g.CrowdPos(w, tick)!.Value; var ahead = g.CrowdPos(w, tick + 10)!.Value;
            var h = ahead - at; long len = Math.Max(1, G.Isqrt((long)h.X * h.X + (long)h.Y * h.Y));
            Pt spot = at;
            foreach (int side in new[] { 1, -1 })
            {
                var q = new Pt(at.X - (int)(h.X * 70 / len) - side * (int)(h.Y * 100 / len), at.Y - (int)(h.Y * 70 / len) + side * (int)(h.X * 100 / len));
                if (g.S.Grid.Free(q) && g.S.Grid.Route(r.Op(Enf).Pos, q) != null) { spot = q; break; }
            }
            r.SendTo(Enf, spot);
            return tick;
        }
        static Walker WalkerById(Run r, string id) => r.G.Walkers.First(w => w.P.Id == id);
        static Start DriverBlind() { var s = new Start(); s.Turned.Add("driver"); s.Crowd = false; return s; }

        static void TakedownCases()
        {
            Add("N46", "—", "An unseen knockout (brief 013, route G-KO): the camera looped, the patrol rerouted, the guard taken from beside just after his 2:30 check-in mark. Nobody sees it: no Trail, no Standing, no Alert. His next mark (4:00) is missed: the report lands at the mark, Alert 1, and the level's Alert-1 robots go; a knockout never takes Alert above 1 by itself; found and brought round, he gives his statement (+4 T), and no seal starts.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                int trail = g.Trail, standing = g.Standing;
                var q = g.QuoteTakedown("guard", "knockout");
                r.Eq(q.S, g.R.KoS, "the card: 6 s, from the side (he doesn't see it coming)");
                r.Eq(q.TrailIfFound, g.R.HitTrail + g.R.DownTrail, "the card: +4 T if found");
                r.Is(q.Usd == 0 && q.Aware == "?" && q.People.Count == 0 && q.IfNeverFound == "comes-home" && q.WakesAt == g.Tick + T(g.R.KoS + g.R.WakeS), "the card: $0; 'sees it coming: ?' (nobody has watched the guard's sight); nobody within sight now; wakes m:ss; comes home if never found");
                r.Is(q.Seen.Seen != "yes" && q.AlertIfFound == 1 && q.PoliceInS > g.R.WitnessReactS + g.R.PostCallS + g.DialNow.DispatchS, $"the card: no known watcher sees it (the camera looped, the patrol away), Alert 1 if found, the response ~{q.PoliceInS} s if staff found him now (a staff radio, the dispatch, the walk from the entry)");
                r.Takedown("guard", "knockout");
                r.Is(g.GuardDown && g.BodyById("guard") != null, "he is seized at once: a body, off his post");
                r.Done(Enf);
                var a = ActOn(r, GuardId);
                r.Is(!a.Witnessed && a.Noticed.Count == 0, "nobody saw it");
                r.Eq((g.Trail, g.Standing, g.Alert), (trail, standing, 0), "no Trail, no Standing, no Alert");
                r.Eq(g.BodyById("guard")!.WakeAt, g.Tick + T(g.R.WakeS), "he wakes in 120 s");
                int mark = g.NextMarkOf(g.GuardP, g.Tick);
                r.Eq(mark, T(240), "his next mark: 4:00");
                r.To(mark - 1); r.Eq(g.Alert, 0, "quiet until the mark");
                r.To(mark);
                r.Is(a.MarkMissed && g.Log.Exists(l => l.Code == "post.missed"), "the missed mark is reported");
                r.Eq(g.Alert, 1, "Alert 1 when it lands (an inquiry)");
                r.Eq(g.Units.Count(u => u.Robot), g.DialNow.A1Robots, $"the level's Alert-1 robots ({g.DialNow.A1Robots} at level {g.SecurityLevel})");
                var launches = g.Units.Select(u => u.Launch).OrderBy(x => x).ToList();
                r.Is(launches[0] == g.Tick + T(g.DialNow.DispatchS) && launches.Zip(launches.Skip(1), (x, y) => y - x).All(d => d == g.R.LaunchGapTicks), "on the street the level's dispatch after the landing, one every 1.5 s");
                r.Until(() => a.ActTrail, T(200));
                r.Is(a.Confirmed || a.Woke, "found by the passing guard and the patrol (one incident), then he wakes and radios it in");
                r.Eq(g.Alert, 1, "a knockout never takes Alert above 1 by itself");
                r.Is(a.ActTrail && g.Trail == trail + g.R.HitTrail + g.R.DownTrail, "his statement: +4 T, once");
                r.Eq(g.Lockdown, int.MaxValue / 4, "no seal at Alert 1");
            });

            Add("N47", "—", "An unseen kill, carried and hidden (route G-kill): the guard killed from beside just after his 2:30 mark, carried at a walk to the Office's service door and put through it (10 s). Nobody sees the act or the carry. His 4:00 mark is missed (Alert 1); the robots find an empty post; at Alert 1 the search opens nothing, and guard 74 walks past the shut door. At the mission's end the guard is a missing person: +2 T, no Menace, his lover's worry, the block's watch and an open case.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                int trail = g.Trail;
                r.Takedown("guard", "kill"); r.Done(Enf);
                var a = ActOn(r, GuardId); var b = g.BodyById("guard")!;
                r.Is(b.Dead && b.Open, "dead, lying at his post");
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.Eq(r.Op(Enf).CarryBody, GuardId, "the Enforcer carries him");
                int at = r.SendTo(Enf, ServiceDoor);
                r.Eq(r.Op(Enf).WalkSpeed, g.R.CellSpeed, "the Enforcer carries at a walk");
                var run = g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "move", Point = ServiceDoor, Run = true });
                r.Eq(run.code, "run-carrying-downed", "no running with a body");
                r.To(at);
                r.Body(Enf, "stash", ServiceDoorId); r.Done(Enf);
                r.Is(!b.Open && b.Stash == ServiceDoorId && r.Op(Enf).CarryBody.Length == 0, "hidden behind the service door");
                r.Is(!a.Witnessed && a.Noticed.Count == 0, "nobody saw the kill or the carry");
                r.Eq((g.Trail, g.Alert), (trail, 0), "no Trail, no Alert yet");
                r.To(T(240));
                r.Eq(g.Alert, 1, "the 4:00 mark is missed: Alert 1");
                r.To(T(420));
                r.Is(!a.Confirmed && b.Stash.Length > 0, "the door stays shut: at Alert 1 the search opens nothing, and nobody sees behind it");
                r.Eq(g.Alert, 1, "Alert stays 1");
                r.Eq(g.Lockdown, int.MaxValue / 4, "no seal");
                var next = g.BetweenMissions(g.Investigate());
                r.Is(next.Lines.Exists(l => l.Line == "missing" && l.Who == "guard"), "between missions: the guard is missing");
                r.Eq(next.CampaignTrail, g.R.MissingTrail, "+2 T (a file, not a homicide)");
                r.Eq(next.CampaignStanding, 0, "no Menace: nothing was found and nothing seen");
                r.Is(next.Lines.Exists(l => l.Line == "worry" && l.Who == "waitress"), "his lover Inez worries (fear +1)");
                r.Is(next.AreaWatch.Count == 1 && next.AreaWatch[0].guards == g.R.AreaWatchStep && next.AreaWatch[0].missions == g.R.AreaWatchMissions, "the block gets +1 guard and +1 camera for 3 missions");
                r.Is(next.Cases.Count == 1 && next.Cases[0].kind == "missing", "one open case");
                r.Eq(next.NextLevel, g.S.SecurityBase, "one open case: the district's level stands (2 cases raise it 1)");
            });

            Add("N48", "—", "A takedown seen by civilians (Sky merged calls 1, 5): a customer knocked out at a café terrace table in front of the other customers and Inez at the door (Pulse's café fix: the other servers work inside). At sight: +1 witness Trail and one step toward Menace, no Alert. The Loyal and Idealist customers report; when the first report lands, Alert 3 and the act's +4 T; the response goes by the dial (the unit, the robots and, at Alert 3, the cordon; the doors lock at this level). The card listed the witnesses with '?' for unknown temperaments.", r =>
            {
                var g = r.G;
                const string Victim = "p-pylon-row-east-05"; // a Mercenary customer at terrace table 2 from 0:30
                r.To(T(240));
                var seat = g.CrowdPos(WalkerById(r, Victim)) ?? throw new InvalidOperationException($"{Victim} is not on the street at 4:00");
                var spot = Beside(r, seat) ?? throw new InvalidOperationException("no ground beside the terrace table");
                r.To(r.SendTo(Enf, spot));
                var q = g.QuoteTakedown(Victim, "knockout");
                r.Is(q.People.Count >= 3 && q.People.Exists(x => x.verb == "?"), $"the card: {q.People.Count} would see it, verbs '?' until their temperaments are known");
                r.Eq(q.AlertIfSeen, 3, "the card: Alert 3 if seen");
                int trail = g.Trail, standing = g.Standing;
                r.Takedown(Victim, "knockout");
                var a = ActOn(r, Victim);
                r.Is(a.Witnessed, "seen");
                r.Eq(g.Trail, trail + g.R.WitnessTrail, "+1 witness Trail at sight, once");
                r.Eq(g.Standing, standing - g.R.StandingStep, "one step toward Menace at sight");
                r.Eq(g.Alert, 0, "no Alert at sight: a silent act reaches Alert when a report lands");
                var reps = g.Reps.Where(x => x.Act == a.Id && x.P != null).ToList();
                r.Is(reps.Count >= 2 && reps.Count <= g.R.ReportCap, $"{reps.Count} reporters, at most the cap");
                int land = reps.Min(x => x.LandAt);
                r.To(land - 1); r.Eq(g.Alert, 0, "still nothing before the first report lands");
                r.To(land);
                r.Eq(g.Alert, 3, "Alert 3 when the report lands (a takedown seen)");
                r.Is(a.ActTrail, "the act's Trail is charged when a seen takedown's report lands");
                r.Is(g.SecurityArrives == land + T(g.DialNow.DispatchS), "the response unit rolls the level's dispatch after the landing");
                r.Is(g.Units.Count(u => u.Robot) == g.DialNow.A2Robots, "the level's Alert-2 robots");
                r.Is(g.AlarmDestinations.Count >= 1 && G.Within(g.AlarmDestinations[0], a.Scene, g.R.WitnessRangeCm), $"the alarm's places ({g.AlarmDestinations.Count}): the scene first, then where the victim's and the first caller's ties are meant to be (one dispatch, brief 013 D)");
                r.Is(g.Units.Count(u => u.Cordon) == g.DialNow.A3Units * g.R.ResponseOfficers, "Alert 3: the cordon to the mouths");
                r.Eq(g.Lockdown, int.MaxValue / 4, "the seal waits for a confirmation");
                var told = g.Walkers.FirstOrDefault(w => w.P.Memory.Exists(m => m.Act == "told"));
                r.Is(told != null && !told.P.Memory.Exists(m => m.Act == "told" && m.By != reps[0].By && g.Walkers.Exists(x => x.P.Id == m.By && x.P.Memory.Exists(mm => mm.Act == "told"))), "a reporter tells a tie by telephone (facts only, one hop: a told person never retells)");
                r.Until(() => a.Confirmed, T(120));
                r.Is(a.Confirmed && g.Lockdown == g.Tick + T(g.SealS), "a unit confirms him at the scene: the seal starts then");
                // a witness who stays at her stop: the Mercenary customer at table 3 (quiet at Alert 0, so she stays seated)
                const string Stays = "p-garden-row-east-03";
                var ws = WalkerById(r, Stays);
                r.Is(ws.P.Has("saw-takedown") && g.CrowdPos(ws) is Pt ps && G.Within(ps, seat, 600) && g.QuoteTakedown(Stays, "knockout").Aware == "yes", "a witness stays aware of the Enforcer for the rest of the mission (Motive rev 3): taking her now is the seen-coming case, though she sits at a stop");
                if (g.DialNow.DoorsLock) { r.To(r.Send(Enf, "d:Office entrance")); r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "enter" }).code, "doors-locked", "Alert 3 at this level: the doors are locked"); }
            });

            Add("N49", "—", "A takedown seen by a camera: guard 29 at the official entrance knocked out under the pickup camera. The driver beside him is a Mercenary and keeps quiet at Alert 0; the camera's watcher reads the screen at its next scan (every 20 s, phase from the camera's id) and calls it in 3 s later: Alert 3.", r =>
            {
                var g = r.G;
                var w = WalkerById(r, "p-records-office-29"); var at = g.CrowdPos(w)!.Value;
                var spot = Beside(r, at) ?? throw new InvalidOperationException("no ground beside guard 29");
                r.To(r.SendTo(Enf, spot));
                r.Takedown("p-records-office-29", "knockout");
                var a = ActOn(r, "p-records-office-29");
                var cam = g.Reps.FirstOrDefault(x => x.Act == a.Id && x.By == "camera:pickup");
                r.Is(cam != null, "the pickup camera records it");
                int period = T(g.R.CameraScanS), phase = (int)(Streams.Fnv1a32("camera:pickup") % (uint)period);
                r.Is(cam != null && (cam.LandAt - T(g.R.PostCallS) - phase) % period == 0 && cam.LandAt - T(g.R.PostCallS) >= a.Tick && cam.LandAt - T(g.R.PostCallS) < a.Tick + period, "its watcher reads the screen at the next scan, then calls it in");
                r.Is(a.Noticed.Contains(g.Driver.Id) && !g.Reps.Exists(x => x.P == g.Driver && x.Kind != "tell"), "the driver saw it and keeps quiet (a Mercenary at Alert 0): no report");
                r.Is(g.Reps.Exists(x => x.P == g.Driver && x.Kind == "tell" && x.Phase == "walk"), "he goes to a phone to tell a workmate indoors (brief 013 E1: no tie within speaking range)");
                r.Is(g.Driver.Has("saw-takedown") && g.FactsOf(g.Driver).Contains("enforcer-face"), "he holds the Enforcer's face (Sky D3)");
                r.To(cam!.LandAt);
                r.Eq(g.Alert, 3, "the camera's report lands: Alert 3");
            });

            // Changed 2026-10-19 (the public door on the Office's west face): guard 74's way from the café to the official entrance no longer
            // crosses the door guard's cone (it runs east along the square and through the service yard, 22 m from the door at the nearest).
            // Guard 73 walks up the forecourt to the public door for her 5:30 shift and enters his cone at 5:23: she is the one taken.
            Add("N50", "—", "A takedown seen by the door guard (armed security): guard 73 knocked out from behind as she walks up the forecourt in the guard's cone. The guard engages at once: Alert 2 at sight, the Enforcer is a foe, the incident is confirmed by his own eyes and the seal starts; the response comes by the dial.", r =>
            {
                var g = r.G;
                const string Victim = "p-records-office-73";
                var w = WalkerById(r, Victim);
                int t = Enumerable.Range(T(300), T(30)).FirstOrDefault(x => g.CrowdPos(w, x) is Pt p && g.GuardWatching(p, false) && !G.Within(p, g.S.Stand(g.S.GuardPost), 300));
                if (!r.Is(t > 0, "guard 73 crosses the door guard's cone on her way to the door, between 5:00 and 5:30")) return;
                r.To(t - T(70)); int when = MeetFromBehind(r, w, t); // the Enforcer's walk from the start to the forecourt is ~50 s
                r.Is(r.Arrival(Enf) <= when, $"the Enforcer is in place before she passes ({Report.Clock(r.Arrival(Enf))})");
                r.To(when);
                r.Takedown(Victim, "knockout");
                var a = ActOn(r, Victim);
                r.Is(a.SecuritySaw && g.GuardEngaged, "the guard sees it and engages");
                r.Eq(g.Alert, g.R.DrawSeenSecurity, "Alert 2 at sight (security sees violence)");
                r.Is(a.Confirmed && g.SecurityArrives == g.Tick + T(g.DialNow.DispatchS) && g.Lockdown == g.SecurityArrives + T(g.SealS), "confirmed by his own eyes; the seal starts when the response unit is on the street (the unit's cordon, Motive rev 3)");
                r.Is(g.SecurityArrives == g.Tick + T(g.DialNow.DispatchS), "the response unit rolls the level's dispatch later");
                r.Is(g.MarkedFoe(Enf), "the Enforcer is his foe now, weapon out or not: he fires once the Enforcer is in his weapon's effective reach");
            });

            Add("N51", "—", "An armed target sees it coming (Motive §1.3): the Enforcer stands in front of the door guard, in his cone, and orders the takedown. It fails into a fight: the guard draws and engages (Alert 2 at sight, the drawn-weapon rule), calls it in, and nobody is down. The card said so before the order ('aware: yes', a fight) once his sight was known.", r =>
            {
                var g = r.G;
                var front = AheadOfGuard(r, 120); // within takedown reach, in his cone (2026-10-19: west of the door; was (50.55, -30) north of it)
                r.To(r.SendTo(Enf, front));
                r.Is(g.GuardWatching(r.Op(Enf).Pos), "in his door cone");
                r.Eq(g.QuoteTakedown("guard", "knockout").Aware, "?", "the card: '?' while his sight is unknown");
                r.Takedown("guard", "knockout");
                r.Is(g.Log.Exists(l => l.Code == "takedown.fails"), "the takedown fails");
                r.Is(!g.GuardDown && g.GuardEngaged && g.Bodies.Count == 0, "nobody is down; the guard engages");
                r.Eq(g.Alert, g.R.DrawSeenSecurity, "Alert 2 at sight");
                r.Is(g.SecurityArrives < int.MaxValue / 4, "he calls it in");
                r.Is(r.Op(Enf).Busy == null, "the Enforcer is not held in an act");
            });

            Add("N52", "—", "Carry, restrain and stash (Motive §3.3, §4): the guard knocked out unseen; the Fixer lifts him (3 s) and carries at half the walk (0.7 m/s); the Enforcer ties him (8 s), carries him at a walk to the Office's service door and puts him through it (10 s, off-screen). Hidden and tied, he wakes and makes no sound; guard 74 walks the lane past the door and hears nothing. Between missions he comes home and gives his statement (+4 T).", r =>
            {
                var g = r.G;
                r.SendTo(Fixer, BesideDoor + new Pt(0, -150));
                GuardQuiet(r);
                r.Takedown("guard", "knockout"); r.Done(Enf);
                var b = g.BodyById("guard")!; var a = ActOn(r, GuardId);
                r.SendTo(Enf, BesideDoor);
                r.To(r.SendTo(Fixer, BesideGuard));
                r.Body(Fixer, "carry", "guard"); r.Done(Fixer);
                r.SendTo(Fixer, ServiceDoor);
                r.Eq(r.Op(Fixer).WalkSpeed, g.R.CarryUntrainedSpeed, "the Fixer carries at 0.7 m/s");
                r.Wait(T(4));
                r.Eq(r.Op(Fixer).WalkMm, (long)g.R.CarryUntrainedSpeed * T(4), "4 s: 2.8 m along the way (the Enforcer walks 5.6)");
                r.Body(Fixer, "drop"); r.Done(Fixer);
                r.Is(b.Open && !b.Carrier.HasValue, "laid down");
                r.To(r.SendTo(Enf, Beside(r, b.At) ?? b.At));
                r.Body(Enf, "restrain", "guard"); r.Done(Enf);
                r.Is(b.Restrained, "tied");
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, ServiceDoor));
                r.Body(Enf, "stash", ServiceDoorId);
                r.Eq(r.Op(Enf).BusyEnd - g.Tick, T(g.R.StashDoorS), "a service door: 10 s");
                r.Done(Enf);
                r.Is(!b.Open && b.Restrained, "hidden and tied");
                r.Is(!a.Witnessed, "nobody saw any of it");
                r.To(b.WakeAt + T(60));
                r.Is(!g.Log.Exists(l => l.Code == "victim.calls-out"), "tied, he makes no sound");
                r.Is(b.P.Down && g.Bodies.Contains(b), "still hidden");
                var next = g.BetweenMissions(g.Investigate());
                r.Is(next.Lines.Exists(l => l.Line == "statement" && l.Who == "guard"), "he comes home and gives his statement");
                r.Is(next.CampaignTrail >= g.R.HitTrail + g.R.DownTrail || a.ActTrail, "+4 T");
            });

            Add("N53", "—", "Hidden but not tied (Motive §3.3): the guard knocked out unseen and stashed in the Dumpster; awake, he calls out every 10 s, heard within 20 m with no line. Guard 74 walks the lane, hears him and radios a noise (Alert 1); a robot is sent to the Dumpster, opens it and finds him, brings him round: his statement, +4 T. A knockout never takes Alert above 1.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                r.Takedown("guard", "knockout"); r.Done(Enf);
                var b = g.BodyById("guard")!; var a = ActOn(r, GuardId);
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster));
                r.Body(Enf, "stash", DumpsterId); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                r.To(b.WakeAt + 1);
                r.Is(r.Until(() => g.Log.Exists(l => l.Code == "victim.calls-out"), T(20)), "awake in the Dumpster, he calls out");
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.Kind == "noise"), T(120)), "someone hears him and reports a noise");
                r.Is(r.Until(() => a.Confirmed || a.Statement || a.Woke, T(240)), "the Dumpster is opened (by the robot sent to it, or by its round at 5:22 if that comes first) and he is out");
                r.Eq(g.Alert, 1, "Alert 1: a knockout never more by itself");
                r.Is(r.Until(() => a.ActTrail, T(30)), "his statement or his own report: +4 T");
            });

            Add("N54", "—", "A body found by routine (Pulse §4.1): the guard killed unseen and left at his post. His 4:00 mark is missed (Alert 1); at 4:34 the patrol, back on its sweep from the reroute, finds him and rings in a dead body: Alert 2 when it lands, the level's units and robots. A unit confirms him: the act's +6 T, a found killing's step toward Menace (Sky 1), and the seal starts at the confirmation, not before.", r =>
            {
                var g = r.G;
                // Changed 2026-10-19 (the public door on the west face): nobody's routine passes the door between 4:00 and 5:00 now (guard 74
                // walks the square's south side and the service yard; guard 73, coming on shift, walks up the forecourt at 5:06). The routine
                // that finds him is the patrol's: rerouted before the 2:30 mark, it is back on its sweep at 4:20 and sees the body at the door
                // on its way along the forecourt. A robot rings the desk (robot.report, 4 s) where a person radios (5 s); the rest is as before.
                GuardQuiet(r);
                int trail = g.Trail, standing = g.Standing;
                r.Takedown("guard", "kill"); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                var a = ActOn(r, GuardId);
                r.Is(!a.Witnessed && a.Noticed.Count == 0, "nobody saw it");
                r.To(T(240)); r.Eq(g.Alert, 1, "the missed mark: Alert 1");
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.By == "patrol"), T(60)), "the patrol, back on its sweep, finds the body");
                var rep = g.Reps.First(x => x.Act == a.Id && x.By == "patrol");
                r.Eq((rep.Kind, rep.LandAt - g.Tick), ("dead", T(g.R.RobotReportS)), "the patrol knows a dead body and rings the desk: 4 s");
                r.To(rep.LandAt);
                r.Eq(g.Alert, 2, "a dead body reported: Alert 2");
                r.Is(g.SecurityArrives == g.Tick + T(g.DialNow.DispatchS), "the response unit is sent to the scene");
                r.Eq(g.Lockdown, int.MaxValue / 4, "no seal on a report alone");
                r.Is(r.Until(() => a.Confirmed, T(200)), "a unit confirms him");
                r.Eq(g.Lockdown, g.Tick + T(g.SealS), "the seal starts at the confirmation (Alert 2)");
                r.Eq(g.Trail, trail + g.R.HitTrail + g.R.DownTrail + g.R.KillTrail, "the act's Trail: +6 T for a kill");
                r.Eq(g.Standing, standing + g.R.FoundKillStanding, "a found killing: one step toward Menace though nobody saw it (Sky answer 1)");
            });

            Add("N55", "—", "The Dumpster's round (Pulse §4.1; Sky call 9, in the mission only): its phase comes from its id (5:22 for the service lane's, then every 15 minutes, learnable by watching it). The guard is killed unseen and put in the Dumpster at about 2:55; his 4:00 mark is missed (Alert 1, no search at Alert 1). At 5:22 the round empties the Dumpster, finds him and rings the desk: a dead body, Alert 2; a unit confirms him and the seal starts.", r =>
            {
                var g = r.G;
                int period = T(g.R.ServicePeriodS), phase = (int)(Streams.Fnv1a32(DumpsterId) % (uint)period);
                r.Eq(phase, T(322), "the round's phase from the Dumpster's id: 5:22");
                GuardQuiet(r);
                r.Takedown("guard", "kill"); r.Done(Enf);
                var a = ActOn(r, GuardId); var b = g.BodyById("guard")!;
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster));
                r.Body(Enf, "stash", DumpsterId); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                r.Is(!a.Witnessed && !b.Open, "unseen, hidden");
                r.To(phase - 1);
                r.Is(!b.Open && g.Alert == 1, "shut until the round (the 4:00 mark: Alert 1, no search)");
                r.To(phase);
                r.Is(g.Log.Exists(l => l.Code == "stash.serviced") && b.Open, "the round opens the Dumpster and finds him");
                var rep = g.Reps.FirstOrDefault(x => x.Act == a.Id && x.By == "round:" + DumpsterId);
                r.Is(rep != null && rep.Kind == "dead" && rep.LandAt == phase + T(g.R.RobotReportS), "and rings the desk (a robot: 4 s)");
                r.To(rep!.LandAt); r.Eq(g.Alert, 2, "a dead body: Alert 2");
                r.Is(r.Until(() => a.Confirmed, T(200)), "a unit confirms him");
                r.Eq(g.Lockdown, g.Tick + T(g.SealS), "the seal starts at the confirmation");
            });

            Add("N56", "—", "A woken victim's report (Motive §3; Pulse §5): guard 73, crossing the square to his post, is knocked out from behind with nobody near and carried to the bins on Rocket Lane's west pavement. He wakes 120 s later, staggers 4 s and radios it in (staff): Alert 1, +4 T, once; he holds what happened to him (attacked: place and time, no face: he never saw the Enforcer), and his fear rises.", r =>
            {
                var g = r.G;
                var w = WalkerById(r, "p-records-office-73");
                int t = T(240);
                r.To(t - T(25)); MeetFromBehind(r, w, t); r.To(t);
                int fear = w.P.Sc[Rules.Fear];
                r.Takedown("p-records-office-73", "knockout"); r.Done(Enf);
                var a = ActOn(r, "p-records-office-73"); var b = g.BodyById("p-records-office-73")!;
                r.Is(!a.Witnessed && !a.Aware, "unseen, from behind");
                // out of the way of the robots the world's dock (by the café) will send to his post and his ties at 5:30: the bins on
                // Rocket Lane's west pavement, which nobody passes all mission (Vantage K5)
                r.Body(Enf, "carry", "p-records-office-73"); r.Done(Enf);
                r.To(r.SendTo(Enf, g.S.Grid.NearestFree(new Pt(740, -6180))!.Value));
                r.Body(Enf, "drop"); r.Done(Enf);
                r.Is(!a.Witnessed, "the carry unseen too");
                r.SendTo(Enf, r.Op(Enf).Pos + new Pt(-1500, 0));
                r.To(b.WakeAt);
                r.Is(!a.Landed || a.MarkMissed, "nobody else found him first (or only his missed check-in did)");
                r.Is(g.Log.Exists(l => l.Code == "victim.wakes") && !w.P.Down, "he wakes");
                var rep = g.Reps.FirstOrDefault(x => x.Act == a.Id && x.Kind == "woken");
                r.Is(rep != null && rep.LandAt == g.Tick + T(g.R.StaggerS + g.R.PostCallS), "he staggers 4 s and radios it in (3 s)");
                r.To(rep!.LandAt);
                r.Eq(g.Alert, 1, "Alert 1: a knockout's victim never takes it higher by himself");
                r.Is(a.ActTrail, "+4 T: the assault is on file");
                r.Is(w.P.Has("attacked") && !g.FactsOf(w.P).Contains("enforcer-face"), "he knows where and when, not the face");
                r.Eq(w.P.Sc[Rules.Fear], Math.Min(fear + 1, g.R.ScaleMax[Rules.Fear]), "his fear rises");
            });

            Add("N65", "—", "A witness stopped before the report lands (Pulse §3.2): guard 73 is killed unseen crossing the square at 4:00 and carried to the bins on Rocket Lane's west pavement (nobody passes them); at 5:30, when the café's walkers are home and before the clerks leave, he is carried on to the north edge, unseen. At 6:47 clerk 34 (Loyal, and 73's workmate: he runs, Pulse row 2), walking home ahead of his group, finds the body and runs to the nearest phone (a call box) to report it. The Enforcer meets him on the way and takes him down: his report never lands. The next finder's report lands later: the incident still reaches the desk, by the next earliest.", r =>
            {
                var g = r.G;
                var w73 = WalkerById(r, "p-records-office-73");
                int t = T(240);
                r.To(t - T(25)); MeetFromBehind(r, w73, t); r.To(t);
                r.Takedown("p-records-office-73", "kill"); r.Done(Enf);
                var a = ActOn(r, "p-records-office-73");
                r.Body(Enf, "carry", "p-records-office-73"); r.Done(Enf);
                // Pulse's café fix (c013): the terrace's residents walk home past the Office side 3:30-5:30, on the carry's way north. Wait
                // them out at the bins (Vantage K5, as N56), then carry on at 5:30: they are home, and the clerks have not left yet.
                r.To(r.SendTo(Enf, g.S.Grid.NearestFree(new Pt(740, -6180))!.Value));
                r.Body(Enf, "drop"); r.Done(Enf);
                r.To(T(330));
                r.Body(Enf, "carry", "p-records-office-73"); r.Done(Enf);
                var spot = new Pt(4201, 1066); // the probe's spot: first found by clerk 34 alone (6:47), 28 m from a door
                r.To(r.SendTo(Enf, spot));
                r.Body(Enf, "drop"); r.Done(Enf);
                r.Is(!a.Witnessed, "unseen: the kill and the carry");
                r.SendTo(Enf, new Pt(4600, -700)); // where clerk 34 will pass on his way home
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.By == "p-records-office-34"), T(200)), "clerk 34 finds the body and goes to report it");
                var rep = g.Reps.First(x => x.Act == a.Id && x.By == "p-records-office-34");
                r.Is(rep.Phase == "walk" && rep.LandAt > g.Tick + T(10), "he walks to a door: the report is in transit");
                var w34 = WalkerById(r, "p-records-office-34");
                // meet him on his walk: the point of his route the Enforcer reaches first
                Pt meet = w34.Run!.End; int meetT = int.MaxValue;
                for (long mm = 0; mm <= w34.Run.Length; mm += 200)
                {
                    var q = w34.Run.At(mm); int his = w34.RunStart + (int)(mm / w34.Pace);
                    var route = g.S.Grid.Route(r.Op(Enf).Pos, g.S.Grid.NearestFree(q) ?? q); if (route == null) continue;
                    int mine = g.Tick + (int)(new Path(route).Length / g.R.RunSpeed) + T(2);
                    if (mine < his) { meet = q; meetT = his; break; }
                }
                r.Is(meetT < rep.LandAt, "the Enforcer can be on his way before he reaches the door");
                g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "move", Point = g.S.Grid.NearestFree(meet) ?? meet, Run = true });
                r.Until(() => g.CrowdPos(w34) is Pt p34 && G.Within(p34, r.Op(Enf).Pos, g.R.TakedownReachCm), T(60));
                r.Takedown("p-records-office-34", "knockout");
                r.Is(rep.Phase == "stopped" && g.Tick < rep.LandAt, "taken down before his report lands: it is dropped");
                var a34 = ActOn(r, "p-records-office-34");
                r.Is(a34.Aware && g.Log.Exists(l => l.Code == "witness.scream" && l.Text.StartsWith("p-records-office-34")), "he saw the Enforcer coming: he struggles (+3 s) and screams");
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.Phase == "landed"), T(150)), "the next finder's report lands");
                var next = g.Reps.First(x => x.Act == a.Id && x.Phase == "landed");
                r.Is(next.By != "p-records-office-34", "by someone else, later");
                // the Mercenary check (Sky merged call 4) moved to N68 on 2026-10-19 (Keel, brief 023): with Pulse's leave stagger no Mercenary passes this body
                r.Is(g.PersonById("p-records-office-34")!.Has("attacked-aware") && g.FactsOf(g.PersonById("p-records-office-34")!).Contains("enforcer-face"), "clerk 34 holds the Enforcer's face");
            });

            Add("N66", "—", "The search opens a stash (Motive §2.3): the patrol rerouted but the entrance camera live, the guard is killed at his post and put in the Dumpster 18 m away. The camera's watcher reports it (Alert 3); the unit finds no body at the post (unfounded) and, at Alert 2 or more, searches 60 s, opening every stash within 30 m, nearest first, 10 s each: the Dumpster. He is found and confirmed; the seal starts then.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.To(r.SendTo(Enf, BesideGuard));
                r.Takedown("guard", "kill"); r.Done(Enf);
                var a = ActOn(r, GuardId); var b = g.BodyById("guard")!;
                r.Is(g.Reps.Exists(x => x.Act == a.Id && x.By == "camera:entrance"), "the entrance camera records the kill");
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster));
                r.Body(Enf, "stash", DumpsterId); r.Done(Enf);
                r.Is(G.Within(Dumpster, g.S.Stand(g.S.GuardPost), g.R.SearchStashCm), "the Dumpster is within 30 m of the post");
                r.SendTo(Enf, new Pt(6250, -5300));
                r.Is(r.Until(() => g.Alert == 3, T(40)), "the camera's report lands: Alert 3");
                r.Is(r.Until(() => a.Confirmed, T(300)), "the unit searches: it opens the stashes within 30 m, nearest first, and finds him in the Dumpster");
                r.Is(g.Log.Exists(l => l.Code == "report.unfounded") && g.Log.Exists(l => l.Code == "stash.opened" && l.Text.Contains(DumpsterId + ": guard")) && b.Open, "unfounded at the post first; found when the Dumpster is opened");
                r.Eq(g.Lockdown, g.Tick + T(g.SealS), "the seal starts at the confirmation");
            });

            Add("N67", "—", "The Records Square mast (the world's camera, built by its rule SF-9; sim/data/handover.takedown.json): three heads, 70° and 30 m each. It sees East side and Plaza east and Vantage's R7, not the café door behind the café's wall nor the Office side. The Scout learns its sight with a Watch like any camera; the Tech's cabinet loops it like the entrance camera (one loop at a time), and looped it sees nothing.", r =>
            {
                var g = r.G; const string Mast = "camera:mast-314";
                r.Is(g.WatcherIds().Contains(Mast) && g.S.Cameras.Exists(c => c.Id == "mast-314" && c.World && c.Facings.Length == 3), "the mast is a watcher, three heads");
                r.Is(g.CameraWatching("mast-314", r.Stand("d:Plaza east"), false) && g.CameraWatching("mast-314", r.Stand("d:East side"), false), "it sees Plaza east and East side");
                int r7 = 0, r7seen = 0; for (int dx = -300; dx <= 300; dx += 50) for (int dy = -300; dy <= 300; dy += 50) { var q = new Pt(-1880 + dx, -1630 + dy); if (!g.S.Grid.Free(q)) continue; r7++; if (g.CameraWatching("mast-314", q, false)) r7seen++; }
                r.Is(r7seen * 2 > r7, $"and most of Vantage's R7 (the café's east end: {r7seen} of {r7} free points within 3 m; the spot itself is under the pole, between two heads)");
                r.Is(!g.CameraWatching("mast-314", r.Stand("d:Café door"), false) && !g.CameraWatching("mast-314", r.Stand("d:Office entrance"), false), "not the café door (the wall) nor the Office side (beyond 30 m)");
                var spot = WatchSpot(r, Mast);
                r.To(r.SendTo(Scout, spot)); r.Do(Scout, "watch", Mast); r.Done(Scout);
                r.Is(g.Known(Mast)!.Sight && g.ConeFan(Mast)!.More.Length == 2, "watched: its sight is known, a fan for each head");
                r.To(r.Send(Tech, "cabinet"));
                r.Do(Tech, "loop", "mast-314"); r.Done(Tech);
                r.Is(g.LoopOn && g.LoopCam == "mast-314" && !g.CameraWatching("mast-314", r.Stand("d:Plaza east"), false), "looped: it sees nothing");
                r.Is(g.CameraWatching("entrance", r.Stand("d:Office entrance"), false), "the entrance camera stays live");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "loop", Target = "entrance" }).code, "loop-holds", "one loop at a time");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "loop", Target = "pickup" }).code, "loop-holds", "the pickup camera is on the cabinet too (brief 013 D), but one loop at a time");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "loop", Target = "gate" }).code, "loop-wrong-target", "no camera of that name (unknown = reject)");
            });

            Add("N57", "—", "A missing tie (Sky answer 6; Motive §5.2; Pulse §11): the turned driver, called at 5:00, moves the car across the pickup camera; the Enforcer kills him there, unseen, and puts him in the Dumpster. Vale comes out at 5:50 to a car with no driver: after suspicion-s (20 s, flat by default) at the place without him he walks to the official door and calls it in. A missing-person report: Alert 1, one incident with the killing; the alarm sends the response to the bay, to the driver's ties and to Vale's. (Start: the driver is a contact, so his car can blind the camera; the crowd is off, since guard 29 stands 4.1 m from the driver until 5:30: a pickup loop would do it in play, idle-study T1.)", r =>
            {
                var g = r.G;
                r.To(T(240)); r.To(r.SendTo(Enf, g.S.Stand(g.S.CarBlock) + new Pt(-300, -300)));
                r.To(T(300)); r.Do(Fixer, "call", Driver);
                r.To(g.BlockedFrom);
                r.Is(!g.PickupCameraLive(), "the camera is blind behind the car");
                r.To(r.SendTo(Enf, Beside(r, g.DriverPos()!.Value)!.Value));
                r.Takedown("driver", "kill"); r.Done(Enf);
                var a = ActOn(r, "driver");
                r.Body(Enf, "carry", "driver"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster));
                r.Body(Enf, "stash", DumpsterId); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                r.Is(!a.Witnessed && !a.Landed, "unseen, unknown");
                r.To(T(g.S.ValeExits) + 1);
                r.Eq(g.Vale, ValeAt.Leaving, "5:50: Vale comes out to his car (the city doesn't know)");
                r.Is(r.Until(() => g.Log.Exists(l => l.Code == "person.missed"), T(60)), "he grows suspicious");
                r.Eq(g.Tick, T(g.S.ValeAtCar) + T(g.R.SuspicionS), "20 s after he reached the car (6:10): 6:30");
                var rep = g.Reps.First(x => x.Act == a.Id && x.Kind == "missing");
                r.Is(rep.P == g.ValeP, "Vale calls it in");
                r.To(rep.LandAt);
                r.Eq(g.Alert, 1, "a missing-person report: Alert 1");
                var d = g.AlarmDestinations;
                r.Is(d.Count >= 1 && G.Within(d[0], g.People2!.Places["office-bay"], g.R.WitnessRangeCm), $"the alarm's places ({d.Count}): the bay first, where the driver should be (his car stands by it; his and Vale's ties are indoors or off the block, the crowd being off)");
                var robots = g.Units.Where(u => u.Robot).ToList();
                r.Is(robots.Count >= 1 && robots.Count <= g.DialNow.A1Robots && robots.All(u => d.Any(x => G.Within(x, u.Dest, 100)) && G.Within(u.From, u.Dest, g.R.RobotReachCm)), $"robots to the places, each only within 60 m of where it starts ({robots.Count} of the level's {g.DialNow.A1Robots}: the dock by the café is too far from the bay)");
                r.Is(robots.Exists(u => u.Patrol && G.Within(u.Dest, d[0], 100)), "the patrol, near enough, takes the bay");
                r.Is(g.ValeP.Has("missed-expected") && g.ValeP.Has("reported"), "Vale remembers it, and that he reported it (a volunteer when questioned)");
                r.Eq(g.Question(g.ValeP).Outcome, "volunteers", "questioned, he volunteers what he holds (no Talker test)");
            }, DriverBlind());

            Add("N57b", "—", "A held person reports nothing (Motive §5.2): as N57, but the Enforcer takes Vale at the car the moment he arrives, behind the blinded camera; suspicion never fires.", r =>
            {
                var g = r.G;
                r.SendTo(Scout, Beside(r, g.S.Stand(g.S.RivalsPark)) ?? g.S.Stand(g.S.RivalsPark)); r.To(T(g.S.RivalsArrive) + 1); r.Do(Scout, "mislead", "rivals"); // the false tip (route B), so the rivals don't reach Vale first
                r.To(T(240)); r.To(r.SendTo(Enf, g.S.Stand(g.S.CarBlock) + new Pt(-300, -300)));
                r.To(T(300)); r.Do(Fixer, "call", Driver);
                r.To(g.BlockedFrom);
                r.To(r.SendTo(Enf, Beside(r, g.DriverPos()!.Value)!.Value));
                r.Takedown("driver", "kill"); r.Done(Enf);
                r.Body(Enf, "carry", "driver"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster));
                r.Body(Enf, "stash", DumpsterId); r.Done(Enf);
                r.To(r.SendTo(Enf, Beside(r, g.CarPos())!.Value));
                r.To(T(g.S.ValeAtCar));
                r.Do(Enf, "take", Vale);
                r.Wait(T(g.R.SuspicionS + 5));
                r.Is(!g.Over && g.Vale == ValeAt.Taking || g.Vale == ValeAt.WithEnforcer, "Vale is being taken");
                r.Is(!g.Log.Exists(l => l.Code == "person.missed"), "being taken, Vale reports nothing");
                r.Is(!g.Acts.Exists(x => x.Take), "an unseen Take opens no incident (brief 013 D: a Take is seen only by whoever sees it)");
            }, DriverBlind());

            Add("N58", "—", "Who can be taken (Sky 2026-10-16: anyone; one rule, no named list): only the Enforcer; within his reach; anyone on the street, cast or crowd, by role or id; Vale only killed (knockout: use Take), and killing him fails the mission; the patrol and cameras are no targets (Reroute and Loop are their verbs).", r =>
            {
                var g = r.G;
                var x = new Order { Tick = g.Tick, Op = Fixer, Do = "takedown", Target = "p-cafe-14", How = "kill" }; // Inez, standing the café door (on the street all mission)
                r.Eq(g.Issue(x).code, "only-enforcer", "only the Enforcer");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "takedown", Target = "patrol", How = "kill" }).code, "target-unknown", "the patrol is no target");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "takedown", Target = "p-cafe-14", How = "stun" }).code, "takedown-how", "a knockout or a kill");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "takedown", Target = "p-cafe-14", How = "kill" }).code, "too-far", "within reach");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "takedown", Target = "councillor", How = "kill" }).code, "person-away", "Vale is inside");
                r.To(T(g.S.ValeAtCar)); r.To(r.SendTo(Enf, Beside(r, g.ValePos()!.Value)!.Value));
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "takedown", Target = "councillor", How = "knockout" }).code, "takedown-vale", "Vale is taken, not knocked out");
                r.Takedown("councillor", "kill"); r.Done(Enf);
                r.Eq((g.Result, g.FailCode), (Outcome.Failure, "vale-dead"), "Vale killed: the mission fails");
                var fc = CauseIs(r, "vale-dead", "killed", true, Enf, "op", Enf); // the fail camera (ScenariosFailCause.cs): the Enforcer who killed him, then Vale where he lies
                r.Is(fc != null && fc.Culprits.Count == 2 && fc.Culprits[1].Kind == "vale" && fc.Culprits[1].Role == "victim" && fc.Culprits[1].At == g.BodyOf(g.ValeP)!.At, "then Vale, where he lies");
            });

            Add("N59", "—", "An alarm beyond robot reach (Pulse §12.2; Motive rev 3): the Tech runs to the cabinet, the guard is killed unseen just after the reroute lands (2:01) and put through the service door before his 2:30 mark. The mark lands (Alert 1). The patrol is away and the world's one dock (by the café) is more than 60 m from the post, so the level's robots go only where they can: to where his lover is meant to be. Nobody checks the post: nothing is confirmed, Alert stays 1, no seal, the door stays shut. (A report found unfounded at the scene: N66.)", r =>
            {
                var g = r.G;
                g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "move", To = "cabinet", Run = true }); r.SendTo(Enf, BesideDoor);
                r.Until(() => r.Op(Tech).Walk == null, T(60));
                r.Do(Tech, "loop", "entrance"); r.Done(Tech); r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.To(r.SendTo(Enf, BesideGuard));
                r.Is(g.NextMarkOf(g.GuardP, g.Tick) == T(150), "before his 2:30 mark");
                r.Takedown("guard", "kill"); r.Done(Enf);
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, ServiceDoor));
                r.Body(Enf, "stash", ServiceDoorId); r.Done(Enf);
                var a = ActOn(r, GuardId);
                r.Is(!a.Witnessed, "unseen");
                r.SendTo(Enf, BesideDoor);
                r.To(T(150)); r.Eq(g.Alert, 1, "the 2:30 mark is missed: Alert 1");
                var post = g.S.Stand(g.S.GuardPost); var robots = g.Units.Where(u => u.Robot).ToList();
                r.Is(robots.Count > 0 && robots.All(u => !u.Patrol && G.Within(u.From, u.Dest, g.R.RobotReachCm) && !G.Within(u.Dest, post, g.R.WitnessRangeCm)), "robots only within 60 m of their dock: to his lover's place, not his post");
                r.Is(G.Within(g.CrowdPosOrStand(g.Inez), robots[0].Dest, g.R.WitnessRangeCm), "the first robot to Inez, at the café (his lover)");
                r.To(T(330));
                r.Is(!a.Confirmed && g.Alert == 1 && g.Lockdown == int.MaxValue / 4, "nobody checks the post: nothing confirmed, Alert 1, no seal");
                r.Is(g.BodyById("guard")!.Stash.Length > 0, "the service door stays shut");
            });

            Add("N60", "—", "The response dial at level 0 (Sky 2026-10-16: the swarm is data; Motive §5.3): the guard killed unseen and left at his post. His 4:00 mark lands (Alert 1): the level's Alert-1 robots, on the street its dispatch later. Guard 74 finds the body and radios it (Alert 2): the response unit and the level's Alert-2 units and robots, then one more unit every reinforce up to the cap. Only the level's numbers differ.", r =>
            {
                var g = r.G; var lv = g.R.Dial[0];
                r.Eq(g.SecurityLevel, 0, "the level");
                GuardQuiet(r);
                r.Takedown("guard", "kill"); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                r.To(T(240));
                r.Eq(g.Units.Count(u => u.Robot), lv.A1Robots, $"Alert 1: {lv.A1Robots} robot(s)");
                r.Is(g.Units.Where(u => u.Robot && !u.Patrol).All(u => u.Launch >= g.Tick + T(lv.DispatchS)), "on the street the dispatch after the landing");
                var a = ActOn(r, GuardId);
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.Kind == "dead" && x.Phase == "landed"), T(60)), "the dead body is reported");
                r.Eq(g.Alert, 2, "Alert 2");
                int landed = g.Tick;
                r.Eq(g.SecurityArrives, landed + T(lv.DispatchS), "the response unit: the level's dispatch after the landing");
                int officers = g.Units.Count(u => !u.Robot && !u.Cordon);
                r.Eq(officers, lv.A2Units * g.R.ResponseOfficers, $"Alert 2: {lv.A2Units} unit(s) of {g.R.ResponseOfficers}");
                r.Eq(g.Units.Count(u => u.Robot), Math.Max(lv.A1Robots, lv.A2Robots), "robots: the Alert-2 count, those out stay out");
                if (lv.ReinforceS > 0 && lv.UnitCap > lv.A2Units)
                {
                    r.To(landed + T(lv.DispatchS) + T(lv.ReinforceS));
                    r.Eq(g.Units.Count(u => !u.Robot && !u.Cordon), (lv.A2Units + 1) * g.R.ResponseOfficers, $"one more unit {lv.ReinforceS} s after the first rolled");
                }
            }, Level(0));

            Add("N61", "—", "The response dial at level 1 (Sky 2026-10-16: the swarm is data; Motive §5.3): the guard killed unseen and left at his post. His 4:00 mark lands (Alert 1): the level's Alert-1 robots, on the street its dispatch later. Guard 74 finds the body and radios it (Alert 2): the response unit and the level's Alert-2 units and robots, then one more unit every reinforce up to the cap. Only the level's numbers differ.", r =>
            {
                var g = r.G; var lv = g.R.Dial[1];
                r.Eq(g.SecurityLevel, 1, "the level");
                GuardQuiet(r);
                r.Takedown("guard", "kill"); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                r.To(T(240));
                r.Eq(g.Units.Count(u => u.Robot), lv.A1Robots, $"Alert 1: {lv.A1Robots} robot(s)");
