sim/Suborned.Sim/ScenariosTakedownE.cs.text:
// Brief 013 E (Keel, 2026-10-16; Aster's small items after Waymark's c010): one scenario a change, on the real block and the promoted cast.
//  N79 a tie out of speaking range is told only from a phone: the teller walks there, and a takedown on the way stops it (the driver route, early)
//  N80 the same walk not stopped: the tie is told by phone when the call is made, not at the sight
//  N81 face to face is unchanged (the driver route, late: the driver tells Vale at once); N82 one hop: a told person never retells
//  N83 a fleeing teller phones only from the refuge she reaches (re-cast 2026-10-19: clerks 56 and 58, the 5:30 group)
//  N84 a cancelled Enter with the public door held comes out by the service lane; N85 both held: he waits inside, then out by a free door
//  N87 a search that opens a stash and is sent on to the body it found (no engine error: the stash comes off the list first)
//  N86 the HUD's read-only accessors (Glyph's ask 1): held-door stand-down, stash room, servicing round, carry-path sight; no hash moves
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>Waymark's driver-route opening (out/waymark013 d-part2/d-part3): the Tech loops the pickup camera, the Enforcer waits
        /// beside the official entrance on the camera's blind side, the Scout watches the driver.
        /// Retimed 2026-10-19 (the door on the west face; c022): the cabinet is on the forecourt now, the Tech's run there lands at 0:17.1
        /// (was 0:13.6); the Scout walks to the driver as c022's route B does and watches at 0:57.6 within 6 m (the way past the forecourt is
        /// longer; was to the rivals' park, watching at 0:56.0), then steps back to where she stood.</summary>
        static Order[] DriverOpening() => new[] {
            new Order { Tick = 0, Op = Tech, Do = "move", To = "cabinet", Run = true }, MvTo(0, Enf, new Pt(7625, -2880)), Mv(0, Scout, "d:Meet driver"), Mv(0, Fixer, "crew:fixer"),
            Act(166, Tech, "loop", "pickup"), Act(576, Scout, "watch", Driver), MvTo(776, Scout, new Pt(8250, -3100)) };
        const string Guard29 = "p-records-office-29", Guard74 = "p-records-office-74", Guard65 = "p-records-office-65", Clerk39 = "p-records-office-39";
        static bool ToldBy(Person q, Person by) => q.Memory.Exists(m => m.Act == "told" && m.By == by.Id);

        static void TakedownE()
        {
            Add("N79", "—", "Telling a tie needs a phone (Aster 2026-10-16, brief 013 E1; GDD §01: calls are voice, no networks). Waymark's early driver route: guard 29 killed beside the car at 2:31; the driver sees it and, a Mercenary at Alert 0, keeps quiet. His workmate (clerk 39) is indoors and nobody of his is within speaking range, so he must reach a phone first: the same walk as a report (the official entrance's desk), and the same stop. The Enforcer kills him at 2:37, before the call: nobody is told.", r =>
            {
                var g = r.G;
                Orders(r, DriverOpening().Concat(new[] { Act(1510, Enf, "takedown", Guard29, "kill") }).ToArray());
                var a = ActOn(r, Guard29);
                r.Is(a.Noticed.Contains(g.Driver.Id) && !g.Reps.Exists(x => x.P == g.Driver && x.Kind != "tell"), "the driver saw it and reports nothing");
                var tell = g.Reps.SingleOrDefault(x => x.P == g.Driver && x.Kind == "tell");
                r.Is(tell != null && tell.Phase == "walk" && tell.LandAt == T(162), $"he goes to the official entrance's phone: react, the walk, the call at 2:42 ({(tell == null ? "none" : Report.Clock(tell.LandAt))})");
                var c39 = g.PersonById(Clerk39)!;
                r.Is(!ToldBy(c39, g.Driver) && !g.Log.Exists(l => l.Code == "witness.told"), "nobody is told at the sight");
                Orders(r, MvTo(1540, Enf, new Pt(7690, -3370)), Act(1570, Enf, "takedown", Driver, "kill"));
                r.Is(tell != null && tell.Phase == "stopped", "taken down before the call: the tell is stopped, as a report is");
                r.To(T(180));
                r.Is(!ToldBy(c39, g.Driver) && !g.Log.Exists(l => l.Code == "witness.told"), "clerk 39 is never told");
                r.Is(!g.Acts.Any(x => x.Told.Count > 0), "no act was told to anyone");
            });

            Add("N80", "—", "The same walk, not stopped (brief 013 E1): the driver sees guard 29 killed at 2:31, walks to the official entrance's desk and calls his workmate clerk 39 at 2:42: the told entry lands with the call, not at the sight, and the log says by phone. Clerk 39, a Mercenary, keeps it to himself.", r =>
            {
                var g = r.G;
                Orders(r, DriverOpening().Concat(new[] { Act(1510, Enf, "takedown", Guard29, "kill") }).ToArray());
                var tell = g.Reps.Single(x => x.P == g.Driver && x.Kind == "tell");
                var c39 = g.PersonById(Clerk39)!;
                r.To(tell.LandAt - 1);
                r.Is(!ToldBy(c39, g.Driver), "not told the tick before the call");
                r.To(tell.LandAt);
                r.Is(ToldBy(c39, g.Driver) && tell.Phase == "landed", "told at the call (2:42)");
                r.Is(g.Log.Exists(l => l.Code == "witness.told" && l.Tick == tell.LandAt && l.Text.Contains("by phone")), "by phone");
                r.Is(ActOn(r, Guard29).Told.Contains(Clerk39), "the act holds whom it was told to");
                r.Eq(g.Alert, 0, "a tell is no report: no Alert");
                r.Is(!g.Reps.Exists(x => x.P == c39), "clerk 39 (a Mercenary) does nothing with it");
            });

            Add("N81", "—", "Face to face is unchanged (brief 013 E1): Waymark's late driver route; guard 74 knocked out at 5:55 beside the car. The driver sees it, keeps quiet, and tells Vale at once: Vale is on the street, walking to his car within speaking range (no phone, no walk).", r =>
            {
                var g = r.G;
                Orders(r, DriverOpening().Concat(new[] { Act(1900, Scout, "mislead", "rivals"), Mv(2340, Scout, "crew:scout"), Act(3550, Enf, "takedown", Guard74, "knockout") }).ToArray());
                r.Is(ToldBy(g.ValeP, g.Driver), "Vale is told at the sight");
                r.Is(g.Log.Exists(l => l.Code == "witness.told" && l.Tick == T(355) && l.Text.Contains("councillor") && !l.Text.Contains("by phone")), "face to face, not by phone");
                r.Is(!g.Reps.Exists(x => x.P == g.Driver), "no walk to a phone");
            });

            Add("N82", "—", "One hop (Pulse §3.4; rulebook memory: a told entry is never retold): the late driver route on to 6:30. Vale sees the driver knocked out at 6:04 and tells guard 65 face to face; 65, Loyal, walks to report it and it lands at 6:27. At his phone he calls nobody: what he was told is not his to tell. (Before brief 013 E1 a told reporter told again from the phone.)", r =>
            {
                var g = r.G;
                Orders(r, DriverOpening().Concat(new[] { Act(1900, Scout, "mislead", "rivals"), Mv(2340, Scout, "crew:scout"), Act(3550, Enf, "takedown", Guard74, "knockout"),
                    MvTo(3610, Enf, new Pt(7690, -3370)), Act(3640, Enf, "takedown", Driver, "knockout") }).ToArray());
                var a = ActOn(r, Driver);
                var g65 = g.PersonById(Guard65)!;
                r.Is(a.Told.Contains(Guard65) && ToldBy(g65, g.ValeP), "Vale tells guard 65 of the driver's takedown");
                var rep = g.Reps.FirstOrDefault(x => x.P == g65 && x.Act == a.Id && x.Kind == "down");
                r.Is(rep != null, "guard 65 (Loyal) goes to report what he was told");
                if (rep == null) return;
                r.To(rep.LandAt);
                r.Is(rep.Phase == "landed", $"his report lands ({Report.Clock(rep.LandAt)})");
                r.Is(!g.People.Concat(g.Walkers.Select(w => w.P)).Any(p => ToldBy(p, g65)), "and he tells nobody: one hop");
            });

            // Re-cast 2026-10-19 (Keel, brief 023): Pulse's leave stagger (0..8 min after the chime for an inside post) keeps clerk 32 inside
            // past the close and sends 42 out alone at 6:30, so the pair no longer walks. The intent is the same with the 5:30 group bound for
            // Rocket West: clerk 56 (Fearful) walks beside clerk 58, a stranger to her; her one tie, workmate 54, is inside the Office until after
            // the close, so nobody of hers is within speaking range and she can tell only from a phone.
            Add("N83", "—", "A fleeing teller (brief 013 E1; Pulse §3.4: 'tells if they reach a phone'): clerks 56 (Fearful) and 58 walk the forecourt with the 5:30 group bound for Rocket West; the Enforcer knocks out 58 beside her. She flees (startled, then a run to a refuge). Nobody of hers is within speaking range: her one tie, workmate 54, is inside the Office until after the close, so she tells only if the refuge she reaches is a staffed door with its desk phone: no walk to a phone beyond her flight.", r =>
            {
                var g = r.G;
                var v = WalkerById(r, "p-records-office-58"); var w = WalkerById(r, "p-records-office-56");
                r.To(T(340)); r.To(MeetFromBehind(r, v, T(380)));
                r.Is(r.Until(() => g.CrowdPos(v) is Pt p && G.Within(p, r.Op(Enf).Pos, g.R.TakedownReachCm), T(40)), $"clerk 58 walks into reach ({Report.Clock(g.Tick)})");
                r.Takedown("p-records-office-58", "knockout");
                var a = ActOn(r, "p-records-office-58");
                r.Is(a.Noticed.Contains(w.P.Id) && w.St == "startled", "clerk 56 sees it and is startled (Fearful: flee)");
                var tell = g.Reps.SingleOrDefault(x => x.P == w.P && x.Kind == "tell");
                r.Is(tell != null && tell.Phase == "flee" && tell.LandAt == Game.Never, "her tell waits on her flight (no walk of its own)");
                r.Is(!g.Log.Exists(l => l.Code == "witness.told" && l.Text.StartsWith("p-records-office-56 ", StringComparison.Ordinal)), "nobody is told at the sight");
                if (tell == null) return;
                r.Is(r.Until(() => tell.Phase != "flee", T(120)), $"her flight ends ({Report.Clock(g.Tick)}, at {w.Refuge})");
                bool door = g.S.Refuges.Exists(x => x.id == w.Refuge && x.kind == "door");
                if (door)
                {
                    r.Is(tell.Phase == "call" && tell.LandAt == g.Tick + T(g.R.CallS), $"{w.Refuge} is a staffed door: she calls from its desk");
                    r.To(tell.LandAt);
                    r.Is(g.Log.Exists(l => l.Code == "witness.told" && l.Tick == g.Tick && l.Text.StartsWith("p-records-office-56 ", StringComparison.Ordinal) && l.Text.Contains("by phone")), "a tie is told by phone");
                }
                else
                {
                    r.Is(tell.Phase == "stopped" && g.Log.Exists(l => l.Code == "witness.tell-stopped" && l.Text.Contains("no phone")), $"{w.Refuge} has no phone: nobody is told");
                    r.To(g.Tick + T(30));
                    r.Is(!a.Told.Contains("p-records-office-54"), "and her workmate is never told");
                }
            });

            Add("N84", "—", "A cancelled Enter comes out by a door no unit holds (Aster 2026-10-16, brief 013 E3; rulebook response: no exit through a held door). Waymark's orders (2026-10-19, the west-face door): the guard knocked out unseen at his post at 4:00.1 and left; guard 73 finds him and radios it (4:57.1, landing 5:02.1); the Enforcer goes in at the landing, before the scene unit arrives. The unit holds the public door from 5:12.1. The player cancels the Enter: the Enforcer comes out at the service lane, not through the held public door.", r =>
            {
                var g = r.G;
                Orders(r, Mv(0, Tech, "cabinet", run: true), MvTo(0, Enf, BesideDoor), Act(166, Tech, "loop", "entrance"), Act(1900, Tech, "reroute", "patrol"),
                    MvTo(2300, Enf, new Pt(6520, -4110)), Act(2401, Enf, "takedown", "guard", "knockout"), Mv(2461, Enf, "d:Office entrance"));
                var a = ActOn(r, GuardId);
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.P != null && x.Kind == "down" && x.Phase == "radio"), T(200)), $"a passer-by finds him and radios it ({Report.Clock(g.Tick)})");
                var rep = g.Reps.FirstOrDefault(x => x.Act == a.Id && x.P != null && x.Kind == "down" && x.Phase == "radio");
                if (rep == null) return; // the check above has failed: a clear failure, not a LINQ throw (the suite's whole-scenario tests read every run)
                r.Eq((rep.P!.Id, Report.Clock(rep.LandAt)), ("p-records-office-73", "5:02.1"), "guard 73 radios it, landing at 5:02.1 (Waymark 2026-10-19)");
                r.To(rep.LandAt);
                r.Is(!g.DoorHeld(g.EnterDoor), "the unit is not there yet");
                Orders(r, Act(3021, Enf, "enter"));
                r.Is(r.Until(() => g.DoorHeld(g.EnterDoor), T(30)), $"the unit arrives and holds the public door ({Report.Clock(g.Tick)})");
                r.Is(!g.DoorHeld(g.ExitDoor), "the service door is not held");
                r.To(Math.Max(g.Tick, 3125)); // Waymark: the cancel at or after 5:12.5
                r.Is(r.Op(Enf).Inside && g.ActivityOf(OpId.Enforcer).CancelText.Contains("service lane"), "the cancel line says where he would come out");
                r.Do(Enf, "cancel");
                r.Is(!r.Op(Enf).Inside && G.Within(r.Op(Enf).Pos, r.Stand(g.S.ValeService), 100), "out at the service lane");
                r.Is(g.Log.Exists(l => l.Code == "cancel.enter-out" && l.Text.Contains("service lane")), "the log says so");
                r.Eq(g.Vale, ValeAt.Office, "without Vale");
            });

            Add("N85", "—", "Both doors held, he waits (brief 013 E3; rulebook response: no exit through a held door). This block can't reach it in play (Keel 2026-10-19, briefs/023/keel-n85-question.md): the public door and the service door are on opposite faces, so it takes two scenes, and the quiet yard is found only by the response unit (6:24 at best) while any Enter begun before the public door is held (5:12.1) ends by 6:20. So the start places a held scene at each door (test only, Start.holds; Aster 2026-10-19, option 1). N84's orders take the guard down and go in at 5:02.1; from 5:03 both doors are held (the service door to 5:40, the public door to 6:00). The cancelled Enter waits inside without Vale (the wait itself cannot be cancelled), and comes out the tick a door is free, by that door, when the HUD said.", r =>
            {
                var g = r.G;
                Orders(r, Mv(0, Tech, "cabinet", run: true), MvTo(0, Enf, BesideDoor), Act(166, Tech, "loop", "entrance"), Act(1900, Tech, "reroute", "patrol"),
                    MvTo(2300, Enf, new Pt(6520, -4110)), Act(2401, Enf, "takedown", "guard", "knockout"), Mv(2461, Enf, "d:Office entrance"));
                r.To(3021);
                r.Is(!g.DoorHeld(g.EnterDoor) && !g.DoorHeld(g.ExitDoor), "no door held yet");
                Orders(r, Act(3021, Enf, "enter"));
                r.To(T(303));
                r.Is(g.DoorHeld(g.EnterDoor) && g.DoorHeld(g.ExitDoor), "both doors held (the start's scenes)");
                r.Is(r.Op(Enf).Inside, "the Enforcer is inside");
                r.Do(Enf, "cancel");
                r.Is(r.Op(Enf).Inside && g.Log.Exists(l => l.Code == "cancel.enter-waits"), "both held: he waits inside");
                r.Eq(g.Vale, ValeAt.Office, "without Vale");
                var act = g.ActivityOf(OpId.Enforcer);
                r.Is(act.Verb == "enter" && !act.CanCancel, "the wait shows as inside the Office and cannot be cancelled");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "cancel" }).code, "nothing-to-cancel", "a second cancel is refused");
                int front = g.HeldUntil(g.EnterDoor), back = g.HeldUntil(g.ExitDoor), until = Math.Min(front, back);
                r.Eq((Report.Clock(back), front >= T(360)), ("5:40.0", true), "the HUD's stand-downs: the service door at 5:40, the public door not before 6:00");
                r.Is(r.Until(() => !r.Op(Enf).Inside, T(400)), $"he comes out once a door is free ({Report.Clock(g.Tick)})");
                r.Is(G.Within(r.Op(Enf).Pos, r.Stand(g.S.ValeService), 100) && g.Log.Exists(l => l.Code == "cancel.enter-out"), "by the free door (the service door)");
                r.Is(Math.Abs(g.Tick - until) <= T(2), $"when the HUD said ({Report.Clock(until)})");
            }, new Start { Holds = { ("office-entrance", 303, 360), ("office-service-door", 303, 340) } });

            Add("N86", "—", "The HUD's read-only accessors (Glyph's ask 1; Aster 2026-10-16): HeldUntil (a held door's stand-down, -1 when not held), StashRoom (bodies and room), NextRound (a container's next round, unknown to the cell), CarryPathSight (who sees which stretch of a carry, SeenQuote's test a second at a time). Calling them changes nothing: the state hash is the same before and after.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                r.Takedown("guard", "knockout"); r.Done(Enf);
                ulong h0 = Hash.State(g);
                r.Eq(g.HeldUntil(g.EnterDoor), -1, "no door held");
                r.Eq(g.StashRoom(DumpsterId), (0, 1), "the Dumpster: empty, holds 1");
                r.Eq(g.StashRoom(ServiceDoorId), (0, g.R.StashDoorHolds), "the service door: empty, holds 3");
                r.Is(g.StashRoom("nowhere") == (-1, -1), "an unknown stash: (-1, -1)"); // no tuple in the text: its minus sign is the culture's (Redline E7)
                var (round, known) = g.NextRound(DumpsterId);
                int period = T(g.R.ServicePeriodS), phase = (int)(Streams.Fnv1a32(DumpsterId) % (uint)period);
                r.Is(round >= g.Tick && round < g.Tick + period && (round - phase) % period == 0 && !known, $"the Dumpster's next round {Report.Clock(round)}, unknown to the cell (\"?\")");
                r.Eq(g.NextRound(ServiceDoorId).tick, -1, "a door has no round");
                var dry = g.CarryPathSight(OpId.Enforcer, ServiceDoor);
                r.Is(dry.Refused == "" && dry.S > 0 && dry.PaceCmS == g.R.CellSpeed && dry.Stretches.Count >= 1 && dry.Stretches[0].FromS == 0 && dry.Stretches.Last().ToS == dry.S, $"a carry to the service door: {dry.S} s at {dry.PaceCmS} cm/s in {dry.Stretches.Count} stretch(es)");
                r.Is(dry.Stretches.Zip(dry.Stretches.Skip(1), (x, y) => y.FromS == x.ToS + 1).All(b => b), "the stretches follow each other, a second at a time");
                var slow = g.CarryPathSight(OpId.Scout, ServiceDoor);
                r.Is(slow.PaceCmS == g.R.CarryUntrainedSpeed && slow.S > dry.S, $"the Scout carries slower ({slow.S} s)");
                var guardCam = "camera:entrance";
                r.Is(!dry.SeenS.ContainsKey(guardCam), "the looped entrance camera sees none of it");
                r.Is(Hash.State(g) == h0, "nothing changed: the state hash is the same");
                r.Do(Tech, "cancel"); // the loop goes: the entrance camera is live again
                var live = g.CarryPathSight(OpId.Enforcer, ServiceDoor);
                var k = g.Known(guardCam)!;
                r.Is(k.Sight ? live.SeenS.ContainsKey(guardCam) && live.Seen == "yes" : live.MaybeS.ContainsKey(guardCam), $"live, the entrance camera {(k.Sight ? "sees" : "could see (?)")} the first stretch ({string.Join(", ", live.SeenS.Select(x => x.Key + " " + x.Value + " s"))}{string.Join(", ", live.MaybeS.Select(x => x.Key + " ? " + x.Value + " s"))})");
                r.Is(live.Stretches.Exists(x => x.Seen == "no") || live.Seen != "no", "seen and unseen stretches are told apart");
            });

            Add("N87", "—", "A searching officer sent on by what he finds (Keel 2026-10-16, found trying driver-route variants for Waymark; re-pinned to Waymark's orders 2026-10-19, the service door on the east face): the driver and guard 29 killed at 2:31 and 2:35 and put through the service door, guard 74 knocked out in front of the outgoing shift at 5:40, Vale taken at 6:10. At 6:56.1 police-3, searching the lane, opens the service door: the driver's body lands its own incident, and the desk sends police-3 on to it. Before, the search then took the opened stash off a list the reassignment had emptied (ArgumentOutOfRange, engine-error); now the stash comes off the list before it is opened, and the officer walks to the new scene.", r =>
            {
                var g = r.G;
                Orders(r, DriverOpening().Concat(new[] {
                    MvTo(1400, Enf, new Pt(7690, -3370)), Act(1510, Enf, "takedown", Driver, "kill"), MvTo(1540, Enf, new Pt(7625, -2880)), Act(1557, Enf, "takedown", Guard29, "kill"),
                    Act(1617, Enf, "carry", Driver), MvTo(1647, Enf, ServiceDoor), Act(1815, Enf, "stash", ServiceDoorId), Act(1900, Scout, "mislead", "rivals"), Act(1900, Tech, "reroute", "patrol"),
                    new Order { Tick = 1915, Op = Enf, Do = "move", Point = new Pt(7625, -2880), Run = true }, Act(1973, Enf, "carry", Guard29), MvTo(2003, Enf, ServiceDoor), Act(2119, Enf, "stash", ServiceDoorId),
                    MvTo(2219, Enf, new Pt(7625, -2880)), Mv(2340, Scout, "crew:scout"), Act(3400, Enf, "takedown", Guard74, "knockout"), MvTo(3460, Enf, new Pt(7700, -3100)), Act(3700, Enf, "take"),
                    MvTo(4080, Enf, new Pt(2400, -6000)) }).ToArray()); // brief 018 (c018): no panic: without the final fight no fight is on
                const int opens = 4161; // 6:56.1 (Waymark 2026-10-19; was 7:58.5, tick 4785, before the east-face door)
                r.To(opens);
                var open = g.Log.FindIndex(l => l.Code == "stash.opened" && l.Tick == opens && l.Text.Contains("driver"));
                r.Is(open >= 0, "at 6:56.1 an officer opens the service door and finds the driver");
                r.Is(g.Log.Exists(l => l.Code == "alarm.reassigns" && l.Tick == opens), "and is sent on to the scene it found");
                r.Is(g.FailCode != "engine-error", $"no engine error{(g.FailCode == "engine-error" ? ": " + g.FailText : "")}");
                r.To(T(500));
                r.Is(g.FailCode != "engine-error", "the run goes on");
            }, NoFight()); // brief 018 (c018): walking Vale the Enforcer no longer fires, so the loud final fight downs him at 7:35, before the 7:58.5 search; without the final fight the fixture is the same path
        }
    }
}

sim/Suborned.Sim/ScenariosTakedownFixes..text:
// Brief 013 D (Keel, 2026-10-16): the engine fixes and rule changes after Waymark played the Handover with takedowns
// (briefs/013/waymark-handover.md §5, §6; Aster's hand-off). One scenario a fix or change, on the real block and the promoted cast:
//  N68 the report chain no longer throws when a check ends and its walk to the phone is added (5:34.1, "Collection was modified")
//  N69 a takedown under the live entrance camera goes through the camera's report chain; N69b the §07 entry rule it was mistaken for
//  N70 one incident, one dispatch (a crowd's reports); N71 a later report at the same Alert sends nothing; N72 the pickup camera loops
//  N73 a Take seen is a takedown seen (guard 74 at the official entrance at 6:10)
using System;
using System.Collections.Generic;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>Orders at their ticks, as a route script gives them (the scenario then checks what it needs).</summary>
        static void Orders(Run r, params Order[] os)
        {
            foreach (var o in os)
            {
                r.To(o.Tick); o.Tick = r.G.Tick;
                var (ok, why) = r.G.Issue(o);
                r.Is(ok, $"{o.Op} {o.Do} {o.Target}{o.To} taken at {Report.Clock(r.G.Tick)}{(ok ? "" : ": " + why)}");
            }
        }
        static Order Mv(int tick, string op, string to, bool run = false) => new Order { Tick = tick, Op = op, Do = "move", To = to, Run = run };
        static Order MvTo(int tick, string op, Pt at) => new Order { Tick = tick, Op = op, Do = "move", Point = at };
        static Order Act(int tick, string op, string verb, string target = "", string how = "") => new Order { Tick = tick, Op = op, Do = verb, Target = target, How = how };

        static void TakedownFixes()
        {
            Add("N68", "—", "A check that ends while reports are stepped (Waymark §6, 'Collection was modified' at 5:34.1): route G-kill with the body left at the guard's post and the Enforcer waiting with Vale in the service lane (brief 018: at the getaway bay the loud fight's blocker now downs him first). The entrance camera reads the dead guard when the Tech leaves the cabinet (Alert 2); at the chime the clerks stream out and find him; Idealist clerk 09 walks to look (clerk 03 before Pulse's leave stagger, brief 023), and the Mercenaries among them report it, Alert being 2, and at 5:34.1 his check ends and his walk to the phone starts as a new report while the reports are being stepped. The engine goes on, his report is a dead body, and the run is sealed at 6:16 (6:12 before the door moved to the west face). Brief 018: the fixture now runs without the final fight (Start.FinalFight off): with it, the loud fight's blocker takes the cover beside the getaway car and downs the cell long before 5:34, so the stepped report is never reached; without it the 5:34.1 path is the same and the dial's seal falls at 6:16 (5:37 was the loud fight's own seal).", r =>
            {
                var g = r.G;
                Orders(r, new Order { Tick = 0, Op = Tech, Do = "move", To = "cabinet", Run = true }, MvTo(0, Enf, BesideDoor), Mv(0, Scout, "d:Office approach"), Mv(0, Fixer, "crew:fixer"),
                    Act(166, Tech, "loop", "entrance"), Act(462, Scout, "watch", "guard"), Mv(662, Scout, "crew:scout"), Act(1060, Tech, "reroute", "patrol"), // as c022's route G-kill (2026-10-19, the door on the west face: the loop at 0:16.6, the watch at 0:46.2; were 0:13.6 and 0:35.5)
                    MvTo(1440, Enf, BesideGuard), Act(1510, Enf, "takedown", "guard", "kill"), Act(1540, Enf, "enter"),
                    MvTo(1540, Tech, new Pt(675, -4625)), MvTo(1540, Scout, new Pt(1175, -4825)), MvTo(1540, Fixer, new Pt(1025, -4625)), Mv(1920, Enf, "d:Getaway bay"));
                const string Clerk = "p-records-office-09";
                r.Is(r.Until(() => g.Reps.Exists(x => x.By == Clerk && x.Phase == "check"), T(340) - g.Tick), "the Idealist clerk finds the body after the chime and walks to look");
                var check = g.Reps.FirstOrDefault(x => x.By == Clerk && x.Phase == "check"); if (check == null) return;
                // Sky merged call 4 (moved here from N65 on 2026-10-19: the leave stagger sends no Mercenary past N65's body): quiet at Alert 0, a
                // Mercenary who finds a body reports it once Alert is 2 or more; here the entrance camera's report has Alert at 2 before the chime
                r.Is(g.Alert >= g.R.MercenaryAlert && g.Reps.Exists(x => x.P != null && x.P.Temperament == "mercenary" && x.Kind == "down" && x.Phase == "walk"), "a Mercenary who finds it now reports it: quiet at Alert 0, he reports once Alert is 2 or more (Sky merged call 4)");
                r.To(check.PhaseUntil);
                r.Is(g.FailCode != "engine-error", $"no engine error when the check ends ({Report.Clock(g.Tick)}){(g.FailCode == "engine-error" ? ": " + g.FailText : "")}");
                r.Is(check.Phase == "stopped" && g.Reps.Exists(x => x.By == Clerk && x.Kind == "dead" && x.Phase == "walk" && x.Seq > check.Seq), "his check is done: he walks to the phone with a dead body (a new report, stepped the same tick)");
                r.Until(() => g.Over, T(60));
                r.Eq(g.FailCode, "sealed", "sealed, the fixture's failure");
                r.Eq(g.Tick, T(376), "at 6:16 (the dial's seal: no final fight, brief 018; 6:12 before 2026-10-19: the unit's walk to the post on the west face confirms him 4 s later)");
                var fc = CauseIs(r, "sealed", "sealed", false, "", "", Enf); // the fail camera (ScenariosFailCause.cs): no single culprit; the report the confirmation sealed on
                var o = fc?.Origin;
                r.Is(o != null && o.Because == "confirmed" && o.Report.StartsWith("report:dead:", StringComparison.Ordinal) && o.Reporter?.Id == "camera:entrance" && o.Confirmer != null && o.Confirmer.Placed, $"the origin: the entrance camera's report of the dead guard, confirmed by a unit (got {o?.Report}, {o?.Because}, {o?.Reporter}, {o?.Confirmer})");
            }, new Start { FinalFight = false });

            Add("N69", "—", "A takedown under the live entrance camera (Waymark §6): route G without the Loop. The camera is a watcher like any other: it records the act, its watcher reads the screen at the next scan and the report lands 3 s later (Alert 3, a takedown seen); nothing fails at the act or when he is out. At this level Alert 3 locks the Office doors: the Enter is refused, and the response comes by the dial. (The old guard-down rule is kept only for a guard shot: his missed mark calls the response, as gunfire's own rule.)", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                int mark = g.NextMarkOf(g.GuardP, g.Tick); r.To(mark + 1);
                r.To(r.SendTo(Enf, BesideGuard));
                r.Is(g.CameraWatching("entrance", r.Op(Enf).Pos), "the entrance camera is live on the post");
                r.Takedown("guard", "knockout");
                var a = ActOn(r, GuardId);
                r.Is(a.Noticed.Contains("camera:entrance"), "the camera records the act");
                var rep = g.Reps.Single(x => x.Act == a.Id && x.By == "camera:entrance");
                r.Is(rep.Phase == "watcher" && rep.LandAt > g.Tick && rep.LandAt <= g.Tick + T(g.R.CameraScanS) + T(g.R.PostCallS), $"its report lands at the next scan + 3 s ({Report.Clock(rep.LandAt)})");
                r.Done(Enf);
                r.Is(!g.Over && g.GuardDown, "he is out, and nothing has failed");
                r.Eq(g.Alert, 0, "no Alert before the report lands (a silent act)");
                r.To(rep.LandAt - 1); r.Is(!g.Over && g.Alert == 0, "still quiet the tick before");
                r.To(rep.LandAt);
                r.Eq(g.Alert, 3, "the camera's report lands: Alert 3 (a takedown seen)");
                r.Is(!g.Over && g.Log.Exists(l => l.Code == "alarm.dispatches"), "the response is sent; the mission goes on");
                r.To(r.SendTo(Enf, r.Stand(g.S.GuardPost)));
                if (g.DialNow.DoorsLock) r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "enter" }).code, "doors-locked", "Alert 3 at this level: the doors are locked");
            });

            Add("N69b", "—", "What Waymark's careless camera fixture met (§6): the Enter given the moment the guard is out, under the live entrance camera, fails at once by §07's entry rule ('entry seen by guard, live camera or patrol': the Enforcer at the door in its view), before the camera's report of the takedown lands. The takedown's own report is still on its way: the fail is the entry, not the takedown.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                int mark = g.NextMarkOf(g.GuardP, g.Tick); r.To(mark + 1);
                r.To(r.SendTo(Enf, BesideGuard));
                r.Takedown("guard", "knockout"); r.Done(Enf);
                var a = ActOn(r, GuardId);
                var rep = g.Reps.Single(x => x.Act == a.Id && x.By == "camera:entrance");
                r.Is(!g.Over && rep.LandAt > g.Tick, "the guard is out; the camera's report has not landed");
                g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "enter" });
                r.Eq(g.FailCode, "entry-seen-camera", "the Enter in the camera's view fails (§07)");
                var cam = g.S.Cameras.Single(x => x.Id == "entrance"); // the fail camera (ScenariosFailCause.cs): the entrance camera, as it faces
                PosedAs(r, CauseIs(r, "entry-seen-camera", "seen", true, "camera:entrance", "camera", Enf)?.Culprits.FirstOrDefault(), cam.At, cam.Facing, "the entrance camera on its pole");
                r.Is(rep.Phase == "watcher" && !a.Landed, "the takedown's report never landed: it was not the takedown that failed");
            });

            Add("N70", "—", "One incident, one dispatch (Aster 2026-10-16; Waymark §6: six dispatches in 0.1 s): the guard knocked out after 5:30 in front of the clerks streaming out after the chime. Many report it, one incident; the first report to land dispatches the response; a later report that raises the incident's Alert tops the same dispatch up to the new Alert's counts (from the destinations the first set); every other later report lands (logged) and sends nothing.", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Enf, BesideDoor)));
                r.Do(Tech, "loop", "entrance"); r.Done(Tech);
                r.To(T(286)); r.Do(Tech, "reroute", "patrol"); r.Done(Tech);
                r.To(r.SendTo(Enf, BesideGuard));
                r.Takedown("guard", "knockout");
                var a = ActOn(r, GuardId);
                var reps = g.Reps.Where(x => x.Act == a.Id && x.Phase != "stopped").ToList();
                r.Is(reps.Count >= 3, $"{reps.Count} reports of the one takedown on their way");
                int first = reps.Min(x => x.LandAt), last = Math.Min(reps.Max(x => x.LandAt), first + T(g.DialNow.ReinforceS) - 1);
                r.To(first);
                r.Eq(g.Log.Count(l => l.Code == "alarm.dispatches"), 1, "the first report dispatches");
                var dests = g.AlarmDestinations.ToList();
                int steps = 0, quiet = 0; bool unitsOnlyOnStep = true;
                while (g.Tick < last && !g.Over)
                {
                    int alert = g.Alert, units = g.Units.Count, landed = g.Reps.Count(x => x.Act == a.Id && x.Phase == "landed");
                    g.Step();
                    int now = g.Reps.Count(x => x.Act == a.Id && x.Phase == "landed");
                    if (g.Alert > alert) steps++;
                    else { if (now > landed) quiet += now - landed; if (g.Units.Count != units) unitsOnlyOnStep = false; }
                }
                r.Is(quiet >= 2, $"{quiet} later reports landed without raising the Alert");
                r.Is(unitsOnlyOnStep, "they sent no unit (units come only with an Alert step)");
                r.Eq(g.Log.Count(l => l.Code == "alarm.dispatches"), 1 + steps, $"one dispatch, topped up {steps} time(s) by an Alert step, never once a report");
                r.Eq(g.Alert, 3, "Alert 3 (a takedown seen)");
                r.Is(g.Units.Count(u => u.Robot) <= Math.Max(g.DialNow.A1Robots, g.DialNow.A2Robots) && g.Units.Count(u => !u.Robot && !u.Cordon && !u.Legacy) <= g.DialNow.A2Units * g.R.ResponseOfficers, "the dial's counts, never a second set");
                r.Is(g.AlarmDestinations.SequenceEqual(dests), "the destinations stand as the first report set them");
                r.Eq(g.Reported, 1, "one reported incident");
            });

            Add("N71", "—", "A later report at the same Alert sends nothing (one incident, one dispatch): route G-KO, the guard knocked out unseen after his 2:30 mark and left at the post. His 4:00 mark lands (Alert 1: the level's robots); guard 74 finds him and radios it: a knockout stays Alert 1, so his report lands and the robots out stay out, with no second dispatch. A later report that raises the Alert tops the same dispatch up to the new level's counts (N62: the dead guard's report, Alert 1 to 2). His report is the body found, so its scene unit comes (rev 4, N74): that is the lockdown, not a dispatch.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                r.Takedown("guard", "knockout"); r.Done(Enf);
                r.SendTo(Enf, BesideDoor);
                r.To(T(240));
                var a = ActOn(r, GuardId);
                r.Is(a.MarkMissed && g.Alert == 1, "the 4:00 mark lands: Alert 1");
                int robots = g.Units.Count(u => u.Robot); var dests = g.AlarmDestinations.ToList();
                r.Eq(g.Log.Count(l => l.Code == "alarm.dispatches"), 1, "one dispatch");
                r.Is(r.Until(() => g.Reps.Exists(x => x.Act == a.Id && x.P != null && x.Phase == "landed"), T(60)), "a passer-by's report of the body lands");
                r.Eq(g.Alert, 1, "a knockout stays Alert 1");
                r.Eq(g.Log.Count(l => l.Code == "alarm.dispatches"), 1, "no second dispatch");
                r.Eq(g.Units.Count(u => u.Robot), robots, "no robot sent twice");
                r.Is(g.Units.Count(u => !u.Robot) <= g.R.ResponseOfficers && g.SceneHolds.Count == 1, "the one unit that comes is the found body's scene unit (rev 4 R4.1), not a second dispatch");
                r.Is(g.AlarmDestinations.SequenceEqual(dests), "the destinations stand");
            });

            Add("N72", "—", "The Tech loops the pickup camera (Sky answer 6: 'if the tech takes out the camera, then taking out the guard and driver is possible'; Waymark §5.1; rulebook cell.loop.targets): one camera at a time, the same 62 s and +1 T. Looped, it sees nothing: official-entrance guard 29 knocked out beside the car is not on its screen (the driver beside him, a Mercenary at Alert 0, keeps quiet). The entrance camera stays live; one loop at a time.", r =>
            {
                var g = r.G;
                r.To(r.Send(Tech, "cabinet"));
                int trail = g.Trail;
                r.Do(Tech, "loop", "pickup"); r.Done(Tech);
                r.Is(g.LoopOn && g.LoopCam == "pickup" && g.Trail == trail + g.R.LoopTrail, "the pickup camera is looped (+1 T)");
                r.Is(!g.CameraWatching("pickup", r.At("d:Official drop-off")) && g.CameraWatching("entrance", r.Stand("d:Office entrance")), "it sees nothing; the entrance camera stays live");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "loop", Target = "entrance" }).code, "loop-holds", "one loop at a time");
                var w = WalkerById(r, "p-records-office-29"); var at = g.CrowdPos(w)!.Value;
                var spot = Beside(r, at) ?? throw new InvalidOperationException("no ground beside guard 29");
                r.To(r.SendTo(Enf, spot));
                r.Takedown("p-records-office-29", "knockout"); r.Done(Enf);
                var a = ActOn(r, "p-records-office-29");
                r.Is(!a.Noticed.Contains("camera:pickup") && !g.Reps.Exists(x => x.Act == a.Id && x.By == "camera:pickup"), "the looped pickup camera does not report it");
            });

            Add("N73", "—", "A Take seen is a takedown seen (Aster 2026-10-16; Waymark §5.2: guard 74 stood 4 m from Vale at 6:10 and did nothing): the pickup camera looped and the rivals sent away, the Enforcer takes Vale at his car at 6:10 in front of guard 74 at the official entrance. At sight: the witnesses' reactions, +1 witness Trail and one step toward Menace, no Alert; guard 74 (staff) radios it, and when the first report lands, Alert 3 (a takedown seen) and the response. One incident; no assault Trail (the Take keeps its own, +2 T on an unturned driver, when it lands). An unseen Take opens nothing (N57b).", r =>
            {
                var g = r.G;
                r.To(Max(r.Send(Tech, "cabinet"), r.SendTo(Scout, Beside(r, g.S.Stand(g.S.RivalsPark)) ?? g.S.Stand(g.S.RivalsPark))));
                r.To(T(g.S.RivalsArrive) + 1); r.Do(Scout, "mislead", "rivals");
                r.To(T(300)); r.Do(Tech, "loop", "pickup"); r.Done(Tech);
                r.To(r.SendTo(Enf, Beside(r, g.CarPos())!.Value));
                r.To(T(g.S.ValeAtCar));
                var w74 = WalkerById(r, "p-records-office-74");
                r.Is(g.CrowdPos(w74) is Pt p74 && G.Within(p74, g.ValePos()!.Value, g.R.WitnessRangeCm), "guard 74 stands within witness range of Vale at his car");
                int trail = g.Trail, standing = g.Standing;
                r.Do(Enf, "take", Vale);
                r.Eq(g.Vale, ValeAt.Taking, "the Take is under way (the pickup camera looped: no §07 camera fail)");
                var a = g.Acts.SingleOrDefault(x => x.Take);
                r.Is(a != null && a.Witnessed && a.Noticed.Contains("p-records-office-74"), "seen: guard 74 notices it");
                if (a == null) return;
                r.Eq(g.Alert, 0, "no Alert at sight: it reaches Alert when a report lands");
                r.Eq(g.Trail, trail + g.R.WitnessTrail, "+1 witness Trail at sight, once");
                r.Eq(g.Standing, standing - g.R.StandingStep, "one step toward Menace at sight");
                r.Is(g.Reps.Exists(x => x.Act == a.Id && x.By == "p-records-office-74" && x.Phase == "radio"), "guard 74 radios it in (staff)");
                int land = g.Reps.Where(x => x.Act == a.Id && x.Phase != "stopped").Min(x => x.LandAt);
                r.To(land - 1); r.Eq(g.Alert, 0, "quiet until the first report lands");
                r.To(land);
                r.Eq(g.Alert, 3, "Alert 3 when it lands (a takedown seen)");
                r.Is(g.Log.Exists(l => l.Code == "alarm.dispatches") && g.SecurityArrives == land + T(g.DialNow.DispatchS), "the response: the unit the level's dispatch after the landing");
                r.Is(!a.ActTrail && g.Trail == trail + g.R.WitnessTrail, "no assault Trail: the Take keeps its own");
                r.Eq(g.Acts.Count(x => x.Take), 1, "one Take, one incident");
            });

            Add("N74", "—", "A found body holds the scene (Motive rev 4 R4.1; Sky 2026-10-16): the guard knocked out unseen at his post; the card says that, found here, he would hold the Office door. The Tech lets the loop go, so the entrance camera reads him at its next scan: a body found. A unit of officers comes at Alert 1 (no robot reach for officers; not one of the dial's units) and holds the Office door, which he lies at: Enter is refused (door-held) from its arrival, through its check and 60 s sweep, until it stands down; the Alert stays 1 (a knockout), and at Alert 1 the sweep opens no stash.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                var q = g.QuoteTakedown("guard", "knockout");
                r.Is(q.HoldsDoors.Contains(g.EnterDoor) && q.HoldS == g.R.CheckS + g.R.SearchS && q.PoliceInS > 0, $"the card: found here, he holds {string.Join(", ", q.HoldsDoors)} ~{q.HoldS} s; a unit in ~{q.PoliceInS} s");
                r.Takedown("guard", "knockout"); r.Done(Enf);
                var a = ActOn(r, GuardId);
                r.SendTo(Enf, BesideDoor);
                r.Is(g.Issue(new Order { Tick = g.Tick, Op = Tech, Do = "cancel" }).ok && !g.LoopOn, "the Tech lets the loop go: the camera is live");
                r.Is(r.Until(() => a.Landed, T(30)), "the camera reads him: a report of a body lands");
                r.Eq(g.Alert, 1, "a knockout: Alert 1");
                r.Is(g.SceneHolds.Count == 1 && g.SceneHolds[0].Doors.Contains(g.EnterDoor) && !g.SceneHolds[0].Doors.Contains(g.ExitDoor), $"the scene holds the doors in its sight: {string.Join(", ", g.SceneHolds[0].Doors)} (the service door is round the corner)");
                var unit = g.Units.FirstOrDefault(u => !u.Robot && u.Act == a.Id && u.Scene);
                r.Is(unit != null && unit.Launch == g.Tick + T(g.DialNow.DispatchS), "a unit of officers is sent at Alert 1, the level's dispatch after the landing");
                if (unit == null) return;
                r.Is(!g.DoorHeld(g.EnterDoor), "not held until it arrives");
                r.Is(r.Until(() => unit.St == "check", T(120)), "it arrives");
                r.To(r.SendTo(Enf, r.Stand(g.S.GuardPost)));
                r.Is(g.DoorHeld(g.EnterDoor), "the Office door is held");
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "enter" }).code, "door-held", "Enter is refused");
                r.Is(r.Until(() => unit.St == "search", T(20)), "it sweeps the scene");
                r.Is(unit.ToOpen.Count == 0, "at Alert 1 the sweep opens no stash");
                r.Is(r.Until(() => !g.DoorHeld(g.EnterDoor), T(200)), $"the door is held until the unit stands down ({Report.Clock(g.Tick)})");
                r.Is(unit.St == "back" || unit.St == "gone", "the unit goes back");
                r.Eq(g.Alert, 1, "Alert stays 1");
            });

            Add("N74b", "—", "A missed check-in is an empty post, not a body (rev 4 R4.1): the guard killed unseen and put through the service door; his 4:00 mark lands (Alert 1) and the robots come, but no door is held and no officer unit is sent.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                r.Takedown("guard", "kill"); r.Done(Enf);
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, ServiceDoor)); r.Body(Enf, "stash", ServiceDoorId); r.Done(Enf);
                r.To(T(240) + 1);
                r.Eq(g.Alert, 1, "the missed mark: Alert 1");
                r.Is(g.SceneHolds.Count == 0 && !g.Units.Exists(u => !u.Robot), "no scene held, no officers: nobody found a body");
            });

            Add("N75", "—", "No exit through a held door (rev 4 R4.1): the guard killed unseen after his 2:30 mark (dead, he never walks back to his door) and laid at the Office's service door; guard 74, walking the lane from 4:04, finds him and radios it; with the patrol rerouted again, the Enforcer goes in. The unit holds the service door from its arrival. The Enter under way (68 s at Alert 2) finishes, and the Enforcer comes out with Vale by the public door, which is not held.", r =>
            {
                var g = r.G;
                GuardQuiet(r);
                r.Takedown("guard", "kill"); r.Done(Enf);
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, ServiceDoor)); r.Body(Enf, "drop"); r.Done(Enf);
                var a = ActOn(r, GuardId);
                r.To(r.Send(Enf, "d:Office entrance"));
                r.Is(r.Until(() => g.SceneHolds.Count > 0, T(150)), "the body by the service door is found (guard 74, walking the lane)");
                r.To(Math.Max(g.Tick, g.PatrolAwayUntil)); r.Do(Tech, "reroute", "patrol"); r.Done(Tech); // the patrol away again for the Enter
                r.Do(Enf, "enter");
                r.Is(g.SceneHolds.Count > 0 && g.SceneHolds[0].Doors.Contains(g.ExitDoor) && !g.SceneHolds[0].Doors.Contains(g.EnterDoor), "its scene holds the service door, not the public door");
                r.Is(r.Until(() => g.DoorHeld(g.ExitDoor), T(60)), "the unit arrives and holds it");
                r.Is(r.Op(Enf).Inside, "the Enforcer is still inside");
                r.Done(Enf);
                r.Eq(g.Vale, ValeAt.WithEnforcer, "the Enter under way finishes");
                r.Is(G.Within(r.Op(Enf).Pos, r.Stand(g.S.GuardPost), 100) && g.Log.Exists(l => l.Code == "enter.out" && l.Text.Contains("public door")), "out by the public door, not through the held service door");
            });

            Add("N76", "—", "Stash capacity (rev 4 R4.3): a service door opens on a storeroom and holds 3 bodies (takedown.stash.doorHolds), the Dumpster 1 (its site entry). Two guards knocked out unseen in the lane: both go through the service door; the Dumpster, holding one, refuses a second.", r =>
            {
                var g = r.G;
                r.Is(g.S.Stashes.All(s => g.HoldsOf(s) == (s.Kind == "door" ? 3 : 1)), "every service door holds 3, the Dumpster 1");
                GuardQuiet(r);
                r.Takedown("guard", "knockout"); r.Done(Enf);
                r.Body(Enf, "carry", "guard"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster)); r.Body(Enf, "stash", DumpsterId); r.Done(Enf);
                r.Is(g.BodyById("guard")!.Stash == DumpsterId, "the guard is in the Dumpster");
                var w = WalkerById(r, "p-records-office-74");
                r.To(MeetFromBehind(r, w, T(250)));
                r.Is(r.Until(() => g.CrowdPos(w) is Pt p && G.Within(p, r.Op(Enf).Pos, g.R.TakedownReachCm), T(30)), "guard 74 walks into reach");
                r.Takedown("p-records-office-74", "knockout"); r.Done(Enf);
                r.Body(Enf, "carry", "p-records-office-74"); r.Done(Enf);
                r.To(r.SendTo(Enf, Dumpster));
                r.Eq(g.Issue(new Order { Tick = g.Tick, Op = Enf, Do = "stash", Target = DumpsterId }).code, "stash-full", "the Dumpster holds one");
                r.To(r.SendTo(Enf, ServiceDoor)); r.Body(Enf, "stash", ServiceDoorId); r.Done(Enf);
                r.Is(g.BodyById("p-records-office-74")!.Stash == ServiceDoorId, "the service door takes him");
            });

            Add("N77", "—", "Route B under rev 4 (Motive R4.2; Sky 2026-10-16), Waymark's route-b orders: the Take at Vale's own car with its driver turned happens inside the car, off-screen: no witness window, though the clerks fill the lane at 6:10; the turned driver is the act's accomplice, never its witness. The escort to the getaway car (by the lane's south end, as the route walks it) is seen only by Vale's kin, or by anyone within 3 m who sees the grip: nobody. 7:39, 3 T (the Pay is private since Sky 2026-10-16; 4 T before), Alert 0.", r =>
            {
                var g = r.G;
                Orders(r, Mv(0, Enf, "d:Service lane"), Mv(0, Scout, "d:Meet driver"), Mv(0, Fixer, "d:Boarding pavilion"), Act(576, Scout, "watch", Driver), // Waymark's route-b (re-pinned 2026-10-19, brief 023: the west-face door, the crowd's pace)
                    Mv(776, Scout, "d:Meet driver"), new Order { Tick = 776, Op = Fixer, Do = "turn", Target = Driver, Approach = "pay" }, Act(797, Scout, "listen", Driver),
                    MvTo(1217, Scout, new Pt(8250, -3100)), Mv(1276, Fixer, "crew:fixer"), Act(1900, Scout, "mislead", "rivals"), Mv(2340, Scout, "crew:scout"));
                r.To(T(370));
                r.Is(g.PickupService && g.TakeInCar, "Vale at his own car in the lane, its driver turned");
                int near = 0; var vp = g.ValePos()!.Value; foreach (var w in g.Walkers) if (g.CrowdPos(w) is Pt p && G.Within(p, vp, g.R.WitnessRangeCm)) near++;
                // the lane is not empty: someone stands within witness range of the car, so a Take outside it would be seen (Waymark 2026-10-19:
                // three clerks at 6:10 on this tree; the check asks for one, since the crowd's own pace moves who is there)
                r.Is(near >= 1, $"{near} people within witness range of the car");
                Orders(r, Act(3700, Enf, "take"));
                r.Done(Enf);
                r.Is(!g.Acts.Exists(x => x.Take), "inside the car: nobody saw a Take, the driver no witness");
                r.Eq(g.Alert, 0, "Alert 0");
                Orders(r, MvTo(4080, Enf, new Pt(2400, -6000)), Act(4470, "cell", "panic"), Mv(4576, Enf, "d:Getaway bay"), Act(4705, Enf, "board", "car"), Act(4745, "cell", "go")); // brief 018: Board (with Vale, 4 s) and Go
                r.Is(!g.Acts.Exists(x => x.Take), "the escort: no kin of Vale near, nobody within 3 m of the grip");
                r.Eq(g.Result, Outcome.Success, "route B wins");
                r.Eq((g.Tick, g.Trail, g.Alert), (4745, 3, 0), "at 7:54.5 (Waymark's route-b, 2026-10-19; 7:43.3 before the west-face door; brief 018: Board with Vale takes 4 s, then Go), 3 T, Alert 0 (rulebook privacy, Sky 2026-10-16: the driver's Pay is private, so the clerk who saw it adds no witness Trail; it was 4 T)");
            });

            Add("N78", "—", "The escort seen (rev 4 R4.2): Vale taken inside his car in the lane (the driver turned), then walked straight at a clerk standing in the lane: within 3 m she sees the grip. A carry seen: +1 witness Trail and one step toward Menace at sight; her report lands at Alert 2. Workmate is not kin (rev 4): Vale's workmates further off see two men walking.", r =>
            {
                var g = r.G;
                r.Send(Enf, "d:Service lane");
                r.To(Max(r.Send(Scout, "d:Meet driver"), r.Send(Fixer, "d:Boarding pavilion")));
                r.Do(Scout, "watch", Driver); r.Done(Scout); r.Do(Scout, "listen", Driver); r.Done(Scout);
                TurnDriver(r);
                r.To(r.SendTo(Scout, new Pt(8250, -3100))); r.To(T(320)); r.Do(Scout, "mislead", "rivals");
                r.To(T(370)); r.Do(Enf, "take"); r.Done(Enf);
                // the nearest person on the street now who is no accomplice, and walk Vale to her
                Walker? near = null; long bd = long.MaxValue; var at = r.Op(Enf).Pos;
                foreach (var w in g.Walkers) if (w.P != g.Driver && g.CrowdPos(w) is Pt p && g.S.Grid.Free(p)) { long d = G.D2(p, at); if (d < bd) { bd = d; near = w; } }
                r.Is(near != null, "someone is on the street");
                if (near == null) return;
                int trail = g.Trail, standing = g.Standing;
                for (int k = 0; k < 40 && !g.Acts.Exists(x => x.Take); k++) { if (g.CrowdPos(near) is Pt p) r.SendTo(Enf, g.S.Grid.NearestFree(p) ?? p); r.Wait(5); }
                var a = g.Acts.FirstOrDefault(x => x.Take);
                r.Is(a != null && a.Noticed.Contains(near.P.Id), $"{near.P.Id}, within 3 m, sees the grip");
                if (a == null) return;
                r.Is(near.P.Has("saw-carry"), "she holds what she saw: a carry");
                r.Eq(g.Standing, standing - g.R.StandingStep, "one step toward Menace at sight");
                r.Is(g.Trail <= trail + g.R.WitnessTrail, "witness Trail at most +1, once");
                var reps = g.Reps.Where(x => x.Act == a.Id && x.Phase != "stopped").ToList();
                if (reps.Count > 0) { r.To(reps.Min(x => x.LandAt)); r.Eq(g.Alert, 2, "her report lands: Alert 2 (a carry seen)"); }
                else r.Is(a.Noticed.Count >= 1, "she keeps quiet by her row (no report to land)");
            });
        }
    }
}

sim/Suborned.Sim/ScenariosTechWatch.cs.text:
// The Tech watches the machines too (Sky 2026-10-18: "I think tech should be able to watch camera / robots like scout can"; rulebook
// sight.kinds.*.by). A Watch on a camera or the patrol is open to the Scout and the Tech, with the same reach, time and teaching; what either
// learns is the cell's, and the patrol's watched seconds add up across both. A person's Watch (the guard, Inez, the driver) and every Listen
// stay the Scout's (only-scout). The Tech doesn't Watch while his loop holds (tethered to the cabinet: run-tethered). The query before the
// click (LearnQuery, for any agent) answers as Issue does. Each scenario also runs twice and replays from its orders (the Theory tests).
using System;
using System.Linq;

namespace Suborned.Sim
{
    public static partial class Scenarios
    {
        /// <summary>A refused Watch or Listen costs nothing: no time, cash, Trail or Alert, the agent stays free, and LearnQuery said the
        /// same code before it was given.</summary>
        static void RefusedFreeBy(Run r, string who, string verb, string target, string code)
        {
            var g = r.G; var o = r.Op(who);
            var (tick, cash, trail, alert) = (g.Tick, g.Cash, g.Trail, g.Alert);
            r.Eq(g.LearnQuery(who, verb, target).code, code, $"before the click, the {who}'s {verb} {target} reads {code} (LearnQuery)");
            var a = g.Issue(new Order { Tick = g.Tick, Op = who, Do = verb, Target = target });
            r.Is(!a.ok && a.code == code, $"the {who}'s {verb} {target} is refused {code} (got {(a.ok ? "taken" : a.code)})");
            r.Is(o.Busy == null && g.Tick == tick && g.Cash == cash && g.Trail == trail && g.Alert == alert, $"the refusal costs nothing: no time, cash, Trail or Alert, the {who} free");
        }

        static void TechWatchCases()
        {
            Add("N107", "—", "The Tech watches the entrance camera (Sky 2026-10-18; rulebook sight.kinds.camera.by): from 18 m on a clear line, the same 20 s Watch the Scout's is, and its sight is learned (its fixed routine with it), the cell's knowledge: drawn on Alt, and a Watch by the Scout is now refused already-watched too. The Tech's repeat Watch is refused already-watched, free. ScoutQuery and LearnQuery for the Scout agree.", r =>
            {
                var g = r.G;
                r.Is(!g.Known("camera:entrance")!.Sight, "the camera's sight is unknown at the start");
                r.Eq(g.LearnQuery(Tech, "watch", "camera:entrance").code, "too-far", "from the start, the Tech is too far (not only-scout)");
                r.To(r.SendTo(Tech, WatchSpot(r, "camera:entrance", who: Tech)));
                r.Is(g.LearnQuery(Tech, "watch", "camera:entrance").ok, "within reach and in line, the Tech's Watch is open (LearnQuery)");
                r.Do(Tech, "watch", "camera:entrance");
                var a = g.ActivityOf(OpId.Tech);
                r.Is(a.Verb == "watch" && a.Target == "camera:entrance" && a.OnDone == "learns the sight" && a.TicksLeft == T(g.R.SightWatchS), $"the HUD reads the Tech's Watch: {a.OnDone}, {a.TicksLeft} ticks");
                r.Is(!g.Known("camera:entrance")!.Sight, "nothing is learned before the Watch lands");
                r.Done(Tech);
                var k = g.Known("camera:entrance")!;
                r.Is(k.Sight && k.Routine && k.How == "watched" && k.SightAt == g.Tick && k.WatchedS == g.R.SightWatchS, "the camera's sight is known, watched, and its fixed routine with it");
                r.Is(g.Log.Exists(l => l.Code == "tech.watch.watched" && l.Text.Contains("Tech") && l.Text.Contains("entrance")), "the Tech says what was learned");
                r.Eq(string.Join(",", g.KnownFans().Select(f => f.Watcher)), "camera:entrance", "the Alt view: the one cone learned");
                RefusedFreeBy(r, Tech, "watch", "camera:entrance", "already-watched");
                r.Eq(g.ScoutQuery("watch", "camera:entrance").code, "already-watched", "the cell knows it: the Scout's Watch is refused for knowledge too (ScoutQuery)");
                r.Eq(g.LearnQuery(Scout, "watch", "camera:entrance").code, "already-watched", "LearnQuery for the Scout says the same");
                r.Is(g.LearnQuery(Tech, "watch", "camera:pickup").code != "already-watched", "the pickup camera, never watched, is not refused for knowledge");
            });

            Add("N108", "—", "The Scout and the Tech together reach the patrol's routine (Sky 2026-10-18; rulebook sight.watch.routine 40 s): the Scout's Watch teaches its sight (20 of 40 s); the Tech's second Watch is open, since its routine is still to learn, and lands it: the cell's seconds add up across both. Then neither may Watch it again (already-watched).", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Scout, WatchSpot(r, "patrol", unseen: false)));
                r.Is(r.Until(() => Watchable(r, "patrol"), T(120)), "the patrol comes within the Scout's reach and in line");
                r.Do(Scout, "watch", "patrol"); r.Done(Scout);
                var k1 = g.Known("patrol")!;
                r.Is(k1.Sight && !k1.Routine && k1.WatchedS == g.R.SightWatchS, $"the Scout's Watch: its sight, not its routine ({k1.WatchedS} of {k1.RoutineNeedsS} s)");
                r.To(r.SendTo(Tech, WatchSpot(r, "patrol", unseen: false, who: Tech)));
                r.Is(r.Until(() => Watchable(r, "patrol", Tech), T(120)), "the patrol comes within the Tech's reach and in line");
                r.Is(g.LearnQuery(Tech, "watch", "patrol").ok, "its routine still to learn: the Tech's Watch is open");
                r.Do(Tech, "watch", "patrol");
                r.Eq(g.ActivityOf(OpId.Tech).OnDone, "learns the sight and the routine", "the HUD says the Tech's Watch teaches the routine");
                r.Done(Tech);
                var k2 = g.Known("patrol")!;
                r.Is(k2.Routine && k2.RoutineAt == g.Tick && k2.WatchedS == 2 * g.R.SightWatchS, $"the Scout's 20 s and the Tech's 20 s: its routine is known ({k2.WatchedS} s)");
                r.Is(g.Routine("patrol", T(g.R.PatrolPeriodS)) is var ev && ev != null && ev.Exists(e => e.What == "turn-at-a"), "and its schedule is read");
                r.Is(r.Until(() => Watchable(r, "patrol", Tech), T(120)), "in the Tech's reach and in line again");
                RefusedFreeBy(r, Tech, "watch", "patrol", "already-watched");
                r.Eq(g.LearnQuery(Scout, "watch", "patrol").code, "already-watched", "the Scout's Watch is refused for knowledge too");
            });

            Add("N109", "—", "People stay the Scout's (Sky 2026-10-18): the Tech's Watch on the guard, Inez or the driver, and his Listen, are refused only-scout, free, even standing beside the guard; the response unit is watched by no one (target-unknown: its sight is known when it comes); the Fixer and the Enforcer watch no camera.", r =>
            {
                var g = r.G;
                r.To(r.SendTo(Tech, AheadOfGuard(r, 400)));
                RefusedFreeBy(r, Tech, "watch", GuardR, "only-scout");
                RefusedFreeBy(r, Tech, "listen", GuardR, "only-scout");
                RefusedFreeBy(r, Tech, "watch", Inez, "only-scout");
                RefusedFreeBy(r, Tech, "watch", Driver, "only-scout");
                RefusedFreeBy(r, Tech, "watch", "security-1", "target-unknown");
                RefusedFreeBy(r, Scout, "watch", "security-1", "target-unknown");
                RefusedFreeBy(r, Fixer, "watch", "camera:entrance", "only-scout");
                RefusedFreeBy(r, Enf, "watch", "patrol", "only-scout");
                r.Is(!g.Known(GuardR)!.Sight && !g.GuardP.KRoutine, "nothing learned of the guard");
            });

            Add("N110", "—", "The Tech doesn't Watch while his loop holds (rulebook sight: tethered to the cabinet): looping the mast camera, he is refused run-tethered on any camera, free, the loop still holding; when he lets the loop go, he walks within reach of the mast camera, watches it and learns it.", r =>
            {
                var g = r.G;
                r.To(r.Send(Tech, "cabinet"));
                r.Do(Tech, "loop", "mast-314"); r.Done(Tech);
                r.Is(g.LoopOn && g.LoopCam == "mast-314", "the mast camera's loop holds");
                var cams = g.WatcherIds().Where(w => w.StartsWith("camera:", StringComparison.Ordinal)).ToList();
                foreach (var c in cams) RefusedFreeBy(r, Tech, "watch", c, "run-tethered");
                r.Is(g.LoopOn, "the loop still holds");
                r.Is(g.Do(new Order { Tick = g.Tick, Op = Tech, Do = "cancel" }), "the Tech lets the loop go");
                r.Is(!g.LoopOn, "the loop ends");
                var spot = WatchSpot(r, "camera:mast-314", unseen: false, who: Tech);
                r.To(r.SendTo(Tech, spot));
                r.Do(Tech, "watch", "camera:mast-314"); r.Done(Tech);
                r.Is(g.Known("camera:mast-314")!.Sight, "the mast camera's sight is learned by the Tech");
            });
        }
    }
}

sim/Suborned.Sim/Script.cs.text:
// An order script (brief 011 B, Waymark's route scripts): a start state and timed orders in the engine's order format.
// {"schema": "suborned.sim.script/1", "mission": "handover", "start": {...}, "orders": [{"tick": 0, "op": "scout", "do": "move", "to": "d:Courtyard"}, ...], "until": 4800}
using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;

namespace Suborned.Sim
{
    /// <summary>A run record (Redline E4): what a replay must match. inputs = the inputs' canonical hash; engine = Engine.Version (and
    /// the assembly MVID, for information); start = the start state's hash; checkpoints = every (tick, hash); outcome.</summary>
    public sealed class Expect
    {
        public string Inputs = "", Engine = "", Mvid = "", Start = "", Outcome = ""; public readonly List<(int tick, string hash)> Checkpoints = new List<(int, string)>();
    }

    public sealed class Script
    {
        public Start Start = new Start(); public readonly List<Order> Orders = new List<Order>(); public int Until; public Expect? Expect;
        public static Script Parse(string json)
        {
            var n = JNode.Parse(json, "script");
            n.Only("schema", "mission", "note", "start", "orders", "until", "expect");
            if (n["schema"].Str() != "suborned.sim.script/1") throw new FormatException("script schema is not suborned.sim.script/1");
            if (n["mission"].Str() != "handover") throw new FormatException("only the Handover plays (brief 011)");
            var s = new Script { Start = Start.Parse(n.Opt("start")), Until = n.Opt("until")?.Int() ?? 0 }; // 0: to the mission's close
            foreach (var o in n["orders"].Items) s.Orders.Add(Order.Parse(o));
            if (n.Opt("expect") is JNode e)
            {
                e.Only("inputs", "engine", "mvid", "start", "outcome", "checkpoints");
                var x = new Expect { Inputs = e["inputs"].Str(), Engine = e["engine"].Str(), Mvid = e.Opt("mvid")?.Str() ?? "", Start = e["start"].Str(), Outcome = e["outcome"].Str() };
                foreach (var c in e["checkpoints"].Items) { var pair = c.Items; if (pair.Count != 2) throw new FormatException($"{c.Path}: [tick, hash]"); x.Checkpoints.Add((pair[0].Int(), pair[1].Str())); }
                s.Expect = x;
            }
            return s;
        }
        /// <summary>The run as a script: its start state, its orders (rejected ones too: they are the player's), and its record.</summary>
        public static string Write(Game g, ulong inputsHash)
        {
            var w = new JWriter().Obj().Prop("schema", "suborned.sim.script/1").Prop("mission", "handover").Key("start").Raw(g.Start.Canonical()).OpenArr("orders");
            foreach (var (o, _, _, _) in g.Orders) o.Write(w);
            w.EndArr().Prop("until", g.Tick);
            w.Open("expect").Prop("inputs", Hash.Hex(inputsHash)).Prop("engine", Engine.Version).Prop("mvid", Engine.Mvid).Prop("start", Hash.Hex(g.StartHash)).Prop("outcome", g.Result.ToString().ToLowerInvariant());
            w.OpenArr("checkpoints"); foreach (var (t, h) in g.Checkpoints) w.Arr().Num(t).Str(Hash.Hex(h)).EndArr(); w.EndArr().EndObj();
            return w.EndObj().ToString();
        }
        /// <summary>Check a replay against the record: "" if it matches, else the first difference.</summary>
        public string Verify(Game g, ulong inputsHash)
        {
            if (Expect == null) return "";
            if (Expect.Inputs != Hash.Hex(inputsHash)) return $"the inputs differ from the record ({Expect.Inputs} recorded, {Hash.Hex(inputsHash)} now)";
            if (Expect.Engine != Engine.Version) return $"the engine differs from the record ({Expect.Engine} recorded, {Engine.Version} now)";
            if (Expect.Start != Hash.Hex(g.StartHash)) return "the start state differs from the record";
            int n = Math.Min(Expect.Checkpoints.Count, g.Checkpoints.Count);
            for (int i = 0; i < n; i++)
                if (Expect.Checkpoints[i].tick != g.Checkpoints[i].tick || Expect.Checkpoints[i].hash != Hash.Hex(g.Checkpoints[i].hash))
                    return $"checkpoint {i} differs at tick {g.Checkpoints[i].tick}";
            if (Expect.Checkpoints.Count != g.Checkpoints.Count) return $"{g.Checkpoints.Count} checkpoints, the record has {Expect.Checkpoints.Count}";
            if (Expect.Outcome != g.Result.ToString().ToLowerInvariant()) return "the outcome differs from the record";
            return "";
        }
    }

    public static class Report
    {
        public static string Clock(int tick) { int s = tick / Game.Hz; return $"{s / 60}:{(s % 60).ToString("00", CultureInfo.InvariantCulture)}.{tick % Game.Hz}"; }
        public static string Json(string id, Game g, List<(bool ok, string what)> checks, bool replayIdentical)
        {
            var w = new JWriter().Obj().Prop("id", id).Prop("outcome", g.Result.ToString().ToLowerInvariant()).Prop("fail", g.FailCode).Prop("tick", g.Tick)
                .Prop("cash", g.Cash).Prop("trail", g.Trail).Prop("alert", g.Alert).Prop("gunfire", g.Gunfire).Prop("standing", g.Standing)
                .Prop("startHash", Hash.Hex(g.StartHash)).Prop("finalHash", Hash.Hex(g.Checkpoints[g.Checkpoints.Count - 1].hash)).Prop("replayIdentical", replayIdentical);
            if (g.Cause != null) { w.Key("cause"); g.Cause.Write(w); } // the fail camera's culprit (FailCause.cs): written only when the run failed or withdrew
            w.OpenArr("checkpoints"); foreach (var (t, h) in g.Checkpoints) w.Obj().Prop("tick", t).Prop("hash", Hash.Hex(h)).EndObj(); w.EndArr();
            w.OpenArr("checks"); foreach (var c in checks) w.Obj().Prop("ok", c.ok).Prop("what", c.what).EndObj(); w.EndArr();
            w.OpenArr("orders"); foreach (var (o, ok, code, why) in g.Orders) { w.Obj().Key("order").Raw(o.ToString()).Prop("ok", ok); if (!ok) w.Prop("code", code).Prop("why", why); w.EndObj(); } w.EndArr();
            w.OpenArr("ledger"); foreach (var (t, what, d, now, cause) in g.Ledger) w.Obj().Prop("tick", t).Prop("what", what).Prop("delta", d).Prop("now", now).Prop("cause", cause).EndObj(); w.EndArr();
            w.OpenArr("log"); foreach (var l in g.Log) w.Obj().Prop("tick", l.Tick).Prop("code", l.Code).Prop("text", l.Text).EndObj(); w.EndArr();
            if (g.Result == Outcome.Success) { w.Key("debrief"); var d = new JWriter(); Debrief.Of(g).Write(d); w.Raw(d.ToString()); }
            return w.EndObj().ToString();
        }
    }
}

